public class BootstrapEdgeCollector
{
    private static final Logger LOGGER = new Logger(BootstrapEdgeCollector.class, GlobalConstants.MOTADATA_SYSTEM, "Bootstrap Edge Collector");

    private static MessageConsumer<JsonObject> messageConsumer;

    private static void startRemoteEventProcessor()
    {
        Bootstrap.startEngine(new RemoteEventChangeNotificationHandler(), RemoteEventChangeNotificationHandler.class.getSimpleName(), null)
                .onComplete(response ->
                {
                    if (response.succeeded())
                    {
                        var futures = new ArrayList<Future<Object>>();

                        var senderPort = CommonUtil.getEventSenderPort(MotadataConfigUtil.getEventRemoteProcessorSenderProtocol());

                        for (var index = 0; index < MotadataConfigUtil.getEventSenders(MotadataConfigUtil.getEventRemoteProcessorSenderProtocol()); index++)
                        {
                            var promise = Promise.promise();

                            futures.add(promise.future());

                            Bootstrap.startEngine(new RemoteEventSender(buildClientTransportConfig(MotadataConfigUtil.getEventRemoteProcessorSenderProtocol(), senderPort + index, null, CommonUtil.getRemoteEventSender(), SocketMode.PUSH)), RemoteEventSender.class.getSimpleName() + " " + (senderPort + index), null)
                                    .onComplete(result ->
                            {
                                if (result.succeeded())
                                {
                                    promise.complete();
                                }
                                else
                                {
                                    promise.fail(result.cause());
                                }
                            });
                        }

                        Future.join(futures).onComplete(asyncResponse ->
                        {
                            if (asyncResponse.succeeded())
                            {
                                try
                                {
                                    EventBusConstants.setRemoteEventProcessorRegistrationId();

                                    //need to start this engine after RPE register

                                    var asyncResults = new ArrayList<Future<Object>>();

                                    var receiverPort = CommonUtil.getEventReceiverPort(MotadataConfigUtil.getEventRemoteProcessorReceiverProtocol());

                                    for (var index = 0; index < MotadataConfigUtil.getEventReceivers(MotadataConfigUtil.getEventRemoteProcessorReceiverProtocol()); index++)
                                    {
                                        var promise = Promise.promise();

                                        asyncResults.add(promise.future());

                                        Bootstrap.startEngine(new RemoteEventReceiver(buildClientTransportConfig(MotadataConfigUtil.getEventRemoteProcessorReceiverProtocol(), receiverPort + index, EVENT_PUBLICATION, CommonUtil.getRemoteEventReceiver(), SocketMode.SUB)), RemoteEventReceiver.class.getSimpleName() + " " + (receiverPort + index), null)
                                                .onComplete(asyncResult ->
                                        {
                                            if (asyncResult.succeeded())
                                            {
                                                promise.complete();
                                            }
                                            else
                                            {
                                                promise.fail(asyncResult.cause());
                                            }
                                        });
                                    }

                                    Future.join(asyncResults).onComplete(asyncResult ->{

                                        if (asyncResult.succeeded())
                                        {
                                            try
                                            {
                                                LOGGER.info(String.format("%s request to register...", Bootstrap.bootstrapType()));

                                                EventBusConstants.register(new CipherUtil());
                                            }
                                            catch (Exception exception)
                                            {
                                                LOGGER.error(exception);
                                            }
                                        }
                                        else
                                        {
                                            Bootstrap.stop(asyncResult.cause());
                                        }
                                    });
                                }
                                catch (Exception exception)
                                {
                                    Bootstrap.stop(exception);
                                }
                            }
                            else
                            {
                                Bootstrap.stop(asyncResponse.cause());
                            }
                        });
                    }
                    else
                    {
                        Bootstrap.stop(response.cause());
                    }
                });

        messageConsumer = Bootstrap.vertx().eventBus().<JsonObject>localConsumer(EVENT_CONFIG_INIT, message ->
        {
            messageConsumer.unregister();

            if (message.body() != null)
            {
                SNMPTemplateOIDGroupCacheStore.getStore().initStore();

                ObjectManagerCacheStore.getStore().initStore();

                LOGGER.info("all config/cache stores loaded successfully...");

                Bootstrap.startEngine(new LocalEventChangeNotificationHandler(), LocalEventChangeNotificationHandler.class.getSimpleName(), null)
                        .compose(future -> Bootstrap.startEngine(new HealthUtil(), HealthUtil.class.getSimpleName(), null))
                        .compose(future -> Bootstrap.startWorkerEngine(new JVMStatUtil(), JVMStatUtil.class.getSimpleName(), null))
                        .compose(future -> Bootstrap.startWorkerEngine(new DiagnosticUtil(), DiagnosticUtil.class.getSimpleName(), null))
                        .compose(future -> Bootstrap.startEngine(new LocalEventRouter(EventBusConstants.EVENT_DATASTORE_WRITE + GlobalConstants.DOT_SEPARATOR + DatastoreConstants.DatastoreCategory.METRIC.getName() + GlobalConstants.DOT_SEPARATOR + Bootstrap.getRegistrationId(), EVENT_TIMESTAMP, MotadataConfigUtil.getMetricDatastoreWorkerInstances(), CollectorDatastore.class.getCanonicalName(), true, false, EventRouter.DYNAMIC), CollectorDatastore.class.getSimpleName(), null))
                        .onComplete(result ->{

                            if (result.failed())
                            {
                                Bootstrap.stop(result.cause());
                            }
                            else
                            {
                                LogUtil.resetLogLevel(MotadataConfigUtil.getLogLevelResetTimerSeconds());

                                if(LicenseUtil.MONITORING_ENABLED.get())
                                {
                                    Bootstrap.startEngine(new DiscoveryEngine(), DiscoveryEngine.class.getSimpleName(), null)
                                            .compose(future -> Bootstrap.startEngine(new LocalEventRouter(EventBusConstants.EVENT_CONFIG_UPGRADE_MANAGER, Configuration.CONFIG_OBJECT, MotadataConfigUtil.getConfigUpgradeMaxWorkers(), ConfigUpgradeManager.class.getCanonicalName(), true), ConfigUpgradeManager.class.getSimpleName(), null))
                                            .compose(future -> Bootstrap.startEngine(new TopologyEngine(), TopologyEngine.class.getSimpleName(), null))
                                            .compose(future -> Bootstrap.startEngine(new RediscoverEngine(), RediscoverEngine.class.getSimpleName(), null))
                                            .compose(future -> Bootstrap.startEngine(new PluginEngine(), PluginEngine.class.getSimpleName(), null))
                                            .compose(future -> Bootstrap.startEngine(new MetricScheduler(), MetricScheduler.class.getSimpleName(), null))
                                            .compose(future -> Bootstrap.startEngine(new MetricPoller(), MetricPoller.class.getSimpleName(), null))
                                            .compose(future -> Bootstrap.startEngine(new PluginEngineResponseProcessor(), PluginEngineResponseProcessor.class.getSimpleName(), null))
                                            .compose(future -> Bootstrap.startEngine(new CollectorResponseProcessor(), CollectorResponseProcessor.class.getSimpleName(), null))
                                            .compose(future -> Bootstrap.startEngine(new ObjectStatusCalculator(), ObjectStatusCalculator.class.getSimpleName(), null))
                                            .onComplete(result1 ->{

                                                if (result1.succeeded())
                                                {
                                                    LOGGER.info("howdy, metric engine started successfully... :)");
                                                }
                                                else
                                                {
                                                    Bootstrap.stop(result1.cause());
                                                }
                                            });
                                }

                                if (LicenseUtil.LOG_ENABLED.get())
                                {
                                    Bootstrap.startEngine(new LocalEventRouter(EventBusConstants.EVENT_LOG, EventBusConstants.EVENT_SOURCE, MotadataConfigUtil.getLogParsers(), LogParser.class.getCanonicalName(), true, true, EventRouter.ROUND_ROBIN), LogParser.class.getSimpleName(), null)
                                            .compose(future -> Bootstrap.startWorkerEngine(new TCPLogListener(false), TCPLogListener.class.getSimpleName(), null))
                                            .compose(future -> Bootstrap.startWorkerEngine(new UDPLogListener(), UDPLogListener.class.getSimpleName(), null))
                                            .compose(future -> Bootstrap.startWorkerEngine(new UDPLogCollector(), UDPLogCollector.class.getSimpleName(), null))
                                            .compose(future -> Bootstrap.startEngine(new LogCollector(), LogCollector.class.getSimpleName(), null))
                                            .onComplete(asyncResult ->
                                            {
                                                if (asyncResult.succeeded())
                                                {
                                                    if(MotadataConfigUtil.tcpTLSEnabled())
                                                    {
                                                        Bootstrap.startWorkerEngine(new TCPLogListener(true), TCPLogListener.class.getSimpleName() + "TLS", null).onComplete(voidAsyncResult ->{

                                                            if (voidAsyncResult.succeeded())
                                                            {
                                                                LOGGER.info("howdy, TCPLogListener with TLS started successfully... :)");
                                                            }
                                                            else
                                                            {
                                                                Bootstrap.stop(voidAsyncResult.cause());
                                                            }
                                                        });
                                                    }

                                                    LOGGER.info("howdy, log engine started successfully... :)");
                                                }
                                                else
                                                {
                                                    Bootstrap.stop(asyncResult.cause());
                                                }
                                            });
                                }

                                if(LicenseUtil.FLOW_ENABLED.get())
                                {
                                    Bootstrap.startEngine(new FlowListener(), FlowListener.class.getSimpleName(), null)
                                            .compose(future -> Bootstrap.startWorkerEngine(new FlowCacheProcessor(), FlowCacheProcessor.class.getSimpleName(), null))
                                            .compose(future -> Bootstrap.startEngine(new LocalEventRouter(EventBusConstants.EVENT_FLOW, "peer_ip_src", MotadataConfigUtil.getFlowProcessors(), FlowProcessor.class.getCanonicalName(), true, true, EventRouter.ROUND_ROBIN), FlowProcessor.class.getSimpleName(), null))
                                            .compose(future -> Bootstrap.startEngine(new FlowStatCalculator(), FlowStatCalculator.class.getSimpleName(), null))
                                            .onComplete(result1 ->
                                            {
                                                if (result1.succeeded())
                                                {
                                                    LOGGER.info("howdy, flow engine started successfully... :)");
                                                }
                                                else
                                                {
                                                    Bootstrap.stop(result1.cause());
                                                }
                                            });
                                }

                                LOGGER.info(String.format(InfoMessageConstants.MOTADATA_ENGINE_START_SUCCEEDED, Bootstrap.bootstrapType()));
                            }
                        });
            }
        });
    }

    /*
     *   Port details for Agent/RemoteEventProcessor:
     *
     *   event.sender.port : start from 9449
     *   event.receiver.port :start from 9444
     * */

    public void start()
    {
        try
        {
            Bootstrap.logSystemConfig();

            PortUtil.init();

            WebClientUtil.init();

            ProcessUtil.setProcessors();

            startRemoteEventProcessor();
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }
}

