public class BootstrapAgent
{
    private static final Logger LOGGER = new Logger(BootstrapAgent.class, GlobalConstants.MOTADATA_SYSTEM, "Bootstrap Agent", true);

    private static String agentUUID;

    private static String localAddress = GlobalConstants.EMPTY_VALUE;

    public static String getAgentUUID()
    {
        return agentUUID;
    }

    public static void setAgentUUID(String agentUUID)
    {
        BootstrapAgent.agentUUID = agentUUID;
    }

    public static String getLocalAddress()
    {
        return localAddress;
    }

    /**
     * Updates the agent configuration and notifies the system of the changes.
     * <p>
     * This method performs the following steps:
     * <ul>
     *   <li>Updates the agent's service status to "running" in the configuration file.</li>
     *   <li>Sets the agent's root path in the configuration context.</li>
     *   <li>Sends an event to master the system's event bus to notify about the agent configuration change.</li>
     * </ul>
     */
    private static void startAgent()
    {
        var futures = new ArrayList<Future<Object>>();

        var senderPort = CommonUtil.getEventSenderPort(AgentConfigUtil.getEventSenderAgentProtocol());

        EventBusConstants.setAgentRegistrationId();

        CommonUtil.getRemoteEventSenders().forEach(host ->
        {
            for (var index = 0; index < MotadataConfigUtil.getEventSenders(AgentConfigUtil.getEventSenderAgentProtocol()); index++)
            {
                var promise = Promise.promise();

                futures.add(promise.future());

                var connection = PortUtil.test(host.toString(), senderPort + index, 3);

                if (AgentConfigUtil.getEventSenderAgentProtocol().equalsIgnoreCase(TransportProtocol.UDP.getValue()) || connection.containsKey(GlobalConstants.STATUS) && connection.getString(GlobalConstants.STATUS).equalsIgnoreCase(GlobalConstants.STATUS_UP))
                {
                    localAddress = AgentConfigUtil.getEventSenderAgentProtocol().equalsIgnoreCase(TransportProtocol.UDP.getValue()) ? CommonUtil.getIPAddress() : connection.getString(GlobalConstants.IP_ADDRESS);

                    LOGGER.debug(String.format("local address is %s", localAddress));
                }
                else
                {
                    LOGGER.warn(String.format("failed to establish connection with %s:%s", host, senderPort + index));
                }

                LOGGER.info(String.format("remote event sender starting with port %s with protocol : %s ", (senderPort + index), AgentConfigUtil.getEventSenderAgentProtocol()));

                Bootstrap.startEngine(new RemoteEventSender(buildClientTransportConfig(AgentConfigUtil.getEventSenderAgentProtocol(), senderPort + index, null, host.toString(), EventBusConstants.SocketMode.PUSH)), String.format("%s %s:%s", RemoteEventSender.class.getSimpleName(), host, (senderPort + index)), null)
                        .onComplete(result ->
                {
                    if (result.succeeded())
                    {
                        promise.complete();
                    }
                    else
                    {
                        promise.fail(result.cause());
                    }
                });
            }
        });

        Future.join(futures).onComplete(asyncResult ->
        {
            if (asyncResult.succeeded() && (MotadataConfigUtil.devMode() || !localAddress.equalsIgnoreCase(EMPTY_VALUE)))
            {
                try
                {
                    LOGGER.debug("sending for registration");

                    var promises = new ArrayList<Future<Object>>();

                    var receiverPort = CommonUtil.getEventReceiverPort(AgentConfigUtil.getEventReceiverAgentProtocol());

                    var reachable = new AtomicBoolean(false);

                    CommonUtil.getRemoteEventReceivers().forEach(host ->
                    {
                        EventBusConstants.registerAgent(host.toString());

                        for (var index = 0; index < MotadataConfigUtil.getEventReceivers(AgentConfigUtil.getEventReceiverAgentProtocol()); index++)
                        {
                            var promise = Promise.promise();

                            promises.add(promise.future());

                            var connection = PortUtil.test(host.toString(), receiverPort + index, 3);

                            if (AgentConfigUtil.getEventReceiverAgentProtocol().equalsIgnoreCase(TransportProtocol.UDP.getValue()) || connection.containsKey(GlobalConstants.STATUS) && connection.getString(GlobalConstants.STATUS).equalsIgnoreCase(GlobalConstants.STATUS_UP))
                            {
                                reachable.set(true);
                            }
                            else
                            {
                                LOGGER.warn(String.format("failed to establish connection with %s:%s", host, receiverPort + index));
                            }

                            Bootstrap.startEngine(new RemoteEventReceiver(buildClientTransportConfig(AgentConfigUtil.getEventReceiverAgentProtocol(), receiverPort + index, EVENT_REMOTE, host.toString(), EventBusConstants.SocketMode.SUB)), String.format("%s %s:%s", RemoteEventReceiver.class.getSimpleName(), host, (receiverPort + index)), null).onComplete(result ->
                            {
                                if (result.succeeded())
                                {
                                    promise.complete();
                                }
                                else
                                {
                                    promise.fail(result.cause());
                                }
                            });
                        }
                    });

                    Future.join(promises).onComplete(asyncFuture ->
                    {
                        if (asyncFuture.succeeded() && (MotadataConfigUtil.devMode() || reachable.get()))
                        {
                            Bootstrap.startEngine(new AgentManager(), AgentManager.class.getSimpleName(), null)
                                    .compose(future -> Bootstrap.startEngine(new AgentCacheManager(), AgentCacheManager.class.getSimpleName(), null))
                                    .compose(future -> Bootstrap.startEngine(new HealthUtil(), HealthUtil.class.getSimpleName(), null))
                                    .onComplete(result ->
                                    {
                                        try
                                        {
                                            if (result.succeeded())
                                            {
                                                // send heartbeat to motadata server
                                                var event = new JsonObject().put(EventBusConstants.EVENT_TYPE, EventBusConstants.EVENT_AGENT_HEARTBEAT)
                                                        .put(AIOpsObject.OBJECT_IP, CommonUtil.getIPAddress())
                                                        .put(GlobalConstants.DURATION, DateTimeUtil.currentSeconds())
                                                        .put(Agent.AGENT_UUID, BootstrapAgent.getAgentUUID());

                                                // send heartbeat on every 60 sec
                                                Bootstrap.vertx().setPeriodic(1000L * AgentConstants.AGENT_PING_INTERVAL_SECONDS, timer -> Bootstrap.vertx().eventBus().publish(EventBusConstants.EVENT_AGENT, event));

                                                JobScheduler.init();

                                                // first time when agent start, manually it will start all child agents
                                                AgentConstants.agents.forEach(agent -> ProcessUtil.start(agent, EventBusConstants.EVENT_AGENT_START));

                                                LogUtil.resetLogLevel(MotadataConfigUtil.getLogLevelResetTimerSeconds());

                                                CommonUtil.dumpConfigs(AGENT_FILE, AgentConfigUtil.getChildAgentConfigs().put(AGENT, AgentConfigUtil.getChildAgentConfigs().getJsonObject(AGENT).put(AgentConstants.AGENT_SERVICE_STATUS, NMSConstants.STATE_RUNNING)));

                                                var context = AgentConfigUtil.getChildAgentConfigs().put(AgentConstants.AGENT_ROOT_PATH, CURRENT_DIR);

                                                Bootstrap.vertx().eventBus().send(EventBusConstants.EVENT_AGENT, new JsonObject().put(GlobalConstants.STATUS, GlobalConstants.STATUS_SUCCEED).put(Agent.AGENT_UUID, BootstrapAgent.getAgentUUID()).put(EventBusConstants.EVENT_TYPE, EventBusConstants.EVENT_AGENT_CONFIGURATION_CHANGE)
                                                        .put(EventBusConstants.EVENT_ID, CommonUtil.newEventId()).put(Agent.AGENT_CONFIGS, context.encodePrettily()));

                                                LOGGER.info(String.format(InfoMessageConstants.MOTADATA_ENGINE_START_SUCCEEDED, Bootstrap.bootstrapType()));
                                            }
                                            else
                                            {
                                                Bootstrap.stop(result.cause());
                                            }
                                        }
                                        catch (Exception exception)
                                        {
                                            LOGGER.error(exception);
                                        }
                                    });
                        }
                        else
                        {
                            LOGGER.warn("all remote event receivers are down, hence aborting motadata boot process....");

                            LOGGER.error(asyncFuture.cause());

                            Bootstrap.stop(asyncFuture.cause());
                        }
                    });
                }
                catch (Exception exception)
                {
                    LOGGER.warn("all remote event senders are down, hence aborting motadata boot process....");

                    Bootstrap.stop(exception.getCause());
                }
            }
            else
            {
                Bootstrap.stop(asyncResult.cause());
            }
        });
    }

    /*
     *   Port details for Agent/RemoteEventProcessor:
     *
     *   event.sender.port : start from 9449
     *   event.receiver.port :start from 9444
     * */

    public void start()
    {
        try
        {
            var file = new File(GlobalConstants.CURRENT_DIR + GlobalConstants.PATH_SEPARATOR + GlobalConstants.CONFIG_DIR + GlobalConstants.PATH_SEPARATOR + "agent.json");

            if (file.exists())
            {
                MotadataConfigUtil.loadConfigs(new JsonObject(Files.readString(new File(GlobalConstants.CURRENT_DIR + GlobalConstants.PATH_SEPARATOR + GlobalConstants.CONFIG_DIR + GlobalConstants.PATH_SEPARATOR + "motadata.json").toPath(), StandardCharsets.UTF_8)));

                LOGGER.info("motadata config loaded");

                AgentConfigUtil.loadAgentConfigs(new JsonObject(Files.readString(file.toPath(), StandardCharsets.UTF_8)));

                LOGGER.info("agent config loaded");

                Bootstrap.logSystemConfig();

                PortUtil.init();

                WebClientUtil.init();

                ProcessUtil.setProcessors();

                startAgent();
            }
            else
            {
                LOGGER.warn(String.format("failed to find %s configuration file, hence aborting motadata boot process....", file.getName()));

                System.exit(0);
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

    /**
     * Stops the agent service by performing the following steps:
     * <ul>
     *   <li>Loads the agent configuration file if it exists.</li>
     *   <li>Updates the agent's service status to "not running" in the configuration.</li>
     *   <li>Dumps the updated configuration back to the configuration file.</li>
     *   <li>Sends an event to the master to synchronize the updated configuration.</li>
     *   <li>Calls the `Bootstrap.stop` method to stop the agent service.</li>
     * </ul>
     *
     * If an exception occurs during the process, it logs the error and attempts to stop the service forcefully.
     *
     * @param forceFully   Indicates whether the agent should be stopped forcefully.
     * @param passOverClass A `JsonArray` containing any additional classes or data to pass over during the stop process.
     * @param exit         Indicates whether the application should exit after stopping the agent.
     * @return A `Future<Void>` that completes when the stop process is finished.
     */
    public static Future<Void> stop(boolean forceFully, JsonArray passOverClass, boolean exit)
    {
        var promise = Promise.<Void>promise();

        try
        {
            var file = new File(GlobalConstants.CURRENT_DIR + GlobalConstants.PATH_SEPARATOR + GlobalConstants.CONFIG_DIR + GlobalConstants.PATH_SEPARATOR + Agent.AGENT_FILE);

            if (file.exists())
            {
                AgentConfigUtil.loadAgentConfigs(new JsonObject(Files.readString(file.toPath(), StandardCharsets.UTF_8)));
            }

            var configs = AgentConfigUtil.getChildAgentConfigs();

            configs.put(AGENT, configs.getJsonObject(AGENT).put(AgentConstants.AGENT_SERVICE_STATUS, NMSConstants.STATE_NOT_RUNNING));

            CommonUtil.dumpConfigs(AGENT_FILE, configs);

            Bootstrap.vertx().eventBus().send(EventBusConstants.EVENT_AGENT, new JsonObject().put(GlobalConstants.STATUS, GlobalConstants.STATUS_SUCCEED).put(Agent.AGENT_UUID, BootstrapAgent.getAgentUUID()).put(EventBusConstants.EVENT_TYPE, EventBusConstants.EVENT_AGENT_CONFIGURATION_CHANGE)
                    .put(EventBusConstants.EVENT_ID, CommonUtil.newEventId()).put(Agent.AGENT_CONFIGS, configs));

            Bootstrap.stop(forceFully, passOverClass, exit).onComplete(result -> promise.complete());
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);

            Bootstrap.stop(forceFully, passOverClass, exit).onComplete(result -> promise.fail(exception));
        }

        return promise.future();
    }
}

