public class BootstrapObserver
{
    private static final Logger LOGGER = new Logger(BootstrapObserver.class, GlobalConstants.MOTADATA_SYSTEM, "Bootstrap Observer");

    public void start()
    {
        try
        {
            DatastoreConstants.loadConfigs();

            Bootstrap.logSystemConfig();

            ProcessUtil.setProcessors();

            startEngine(new EventSender(buildServerTransportConfig(MotadataConfigUtil.getEventObserverProtocol(), MotadataConfigUtil.getMotadataObserverEventSenderPort(), EVENT_PUBLICATION_MOTADATA_OBSERVER, EventBusConstants.SocketMode.PUB, null)), EventSender.class.getSimpleName() + " " + MotadataConfigUtil.getMotadataObserverEventSenderPort(), null, EVENT_PUBLICATION_MOTADATA_OBSERVER)
                    .compose(future -> startWorkerEngine(new EventReceiver(buildServerTransportConfig(MotadataConfigUtil.getEventObserverProtocol(), MotadataConfigUtil.getMotadataObserverEventReceiverPort(), EVENT_REMOTE, EventBusConstants.SocketMode.PULL, null)), EventReceiver.class.getSimpleName() + " " + MotadataConfigUtil.getMotadataObserverEventReceiverPort(), null))
                    .compose(future -> startEngine(new Observer(), Observer.class.getSimpleName(), null))
                    .onComplete(response ->
                    {
                        if (response.succeeded())
                        {
                            LogUtil.resetLogLevel(MotadataConfigUtil.getLogLevelResetTimerSeconds());

                            EventBusConstants.setManagerRegistrationId();

                            EventBusConstants.setRemoteEventProcessorRegistrationId();

                            JobScheduler.init();

                            LOGGER.info(String.format(InfoMessageConstants.MOTADATA_ENGINE_START_SUCCEEDED, GlobalConstants.BootstrapType.OBSERVER));
                        }
                        else
                        {
                            stop(response.cause());
                        }
                    });
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }
}

