    public static final AtomicBoolean APP_SERVER_ONLINE = new AtomicBoolean(true);
    private static final Logger LOGGER = new Logger(BootstrapStandalone.class, GlobalConstants.MOTADATA_SYSTEM, "Bootstrap Standalone");
    private static final AtomicBoolean INIT_DONE = new AtomicBoolean(false);

    public void start()
    {
        try
        {
            DatastoreConstants.loadConfigs();

            Bootstrap.logSystemConfig();

            PortUtil.init();

            WebClientUtil.init();

            ProcessUtil.setProcessors();

            Bootstrap.startEngine(new DBServiceProvider(), DBServiceProvider.class.getSimpleName(), null)
                    .compose(future -> Bootstrap.startEngine(new SSHClientManager(), SSHClientManager.class.getSimpleName(), null))
                    .compose(future -> Bootstrap.startEngine(new CacheServiceProvider(), CacheServiceProvider.class.getSimpleName(), null))
                    .compose(future -> startEngine(new DatastoreManager(), DatastoreManager.class.getSimpleName(), null))
                    .onComplete(result ->
                    {
                        if (result.succeeded())
                        {
                            initConfig(true);
                        }
                        else
                        {
                            stop(result.cause());
                        }
                    });
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

    private void initConfig(boolean init)
    {
        var future = Promise.<Boolean>promise();

        var promise = Promise.<Void>promise();

        LOGGER.info("initializing config db");

        Bootstrap.configDBService().getOne(DBConstants.TBL_SYSTEM,
                result ->
                {
                    if (result.succeeded() && result.result().containsKey(INSTALLATION_DATE))
                    {
                        future.complete(false);
                    }
                    else
                    {
                        future.complete(true);
                    }
                });


        future.future().onComplete(asyncPromiseResult ->
        {
            LOGGER.info("verifying license...");

            LicenseUtil.init(asyncPromiseResult.result()).onComplete(asyncResponse ->
            {
                if (asyncResponse.succeeded())
                {
                    LOGGER.info("license verified successfully...");

                    try
                    {
                        var license = new JsonObject();

                        if (!Bootstrap.vertx().fileSystem().existsBlocking(LicenseUtil.LICENSE_PATH))
                        {
                            Bootstrap.vertx().fileSystem().createFileBlocking(LicenseUtil.LICENSE_PATH);

                            license.mergeIn(asyncResponse.result());

                            Bootstrap.vertx().fileSystem().writeFileBlocking(LicenseUtil.LICENSE_PATH, Buffer.buffer(CodecUtil.compress(license.encode())));
                        }
                        else
                        {

                            license.mergeIn(new JsonObject(new String(Snappy.uncompress(Bootstrap.vertx().fileSystem().readFileBlocking(LicenseUtil.LICENSE_PATH).getBytes()))));

                            license.mergeIn(asyncResponse.result());
                        }

                        LicenseUtil.load(license);

                        ConfigDBInitializer.init().onComplete(result ->
                        {
                            if (result.succeeded())
                            {
                                // init all stores...
                                Bootstrap.initStores().onComplete(response ->
                                {
                                    if (response.succeeded())
                                    {
                                        LOGGER.info("all config/cache stores loaded successfully...");

                                        Bootstrap.patch(result.result()).onComplete(futureResult ->
                                        {
                                            if (futureResult.succeeded())
                                            {
                                                var asyncFutures = new ArrayList<Future<Void>>();

                                                for (var index = 0; index < MotadataConfigUtil.getHTTPServerInstances(); index++)
                                                {
                                                    var asyncFuture = Promise.<Void>promise();

                                                    asyncFutures.add(asyncFuture.future());

                                                    Bootstrap.startWorkerEngine(new APIServer(), APIServer.class.getSimpleName() + DOT_SEPARATOR + index, null)
                                                            .onComplete(promiseResult ->
                                                            {
                                                                if (promiseResult.succeeded())
                                                                {
                                                                    asyncFuture.complete();
                                                                }
                                                                else
                                                                {
                                                                    asyncFuture.fail(promiseResult.cause());
                                                                }
                                                            });
                                                }

                                                Future.join(asyncFutures).onComplete(asyncResult ->
                                                {
                                                    if (asyncResult.succeeded())
                                                    {
                                                        LOGGER.info("HTTP server started successfully...");

                                                        promise.complete();

                                                        if (init)
                                                        {
                                                            init();
                                                        }
                                                    }
                                                    else
                                                    {
                                                        promise.fail(asyncResult.cause());

                                                        stop(asyncResult.cause());
                                                    }
                                                });
                                            }
                                            else
                                            {
                                                Bootstrap.stop(futureResult.cause());

                                                promise.fail(futureResult.cause());
                                            }
                                        });
                                    }
                                    else
                                    {
                                        stop(response.cause());

                                        promise.fail(response.cause());
                                    }
                                });
                            }
                            else
                            {
                                promise.fail(result.cause());

                                stop(result.cause());
                            }
                        });
                    }
                    catch (Exception exception)
                    {
                        LOGGER.error(exception);

                        stop(exception);
                    }
                }
                else
                {
                    stop(asyncResponse.cause());
                }
            });
        });

        promise.future();
    }

    private void init()
    {
        try
        {
            startDefault();   // if license is valid then start the following engines....
        }
        catch (Exception exception)
        {
            stop(exception);
        }
    }

