                                sync().onComplete(futureResult ->
                                {
                                    AIOpsConstants.CORRELATION_ENABLED = MotadataConfigUtil.correlationEnabled();

                                    var asyncFutures = new ArrayList<Future<Object>>();

                                    var senderPort = CommonUtil.getEventSenderPort(MotadataConfigUtil.getEventAppSenderProtocol());

                                    for (var index = 0; index < MotadataConfigUtil.getEventSenders(MotadataConfigUtil.getEventAppSenderProtocol()); index++)
