                                        asyncFutures.add(promise.future());

                                        LOGGER.info(String.format("event sender starting with port %s and protocol %s", senderPort + index, MotadataConfigUtil.getEventAppSenderProtocol()));

                                        startEngine(new EventSender(buildServerTransportConfig(CommonUtil.getString(MotadataConfigUtil.getEventAppSenderProtocol()), senderPort + index, null, SocketMode.PUB, null)), EventSender.class.getSimpleName() + " " + (senderPort + index), null, EVENT_PUBLICATION)
