    /**
     * Method will responsible to return multiplier for policy workers based on enabled modules.
     * For example, if monitoring and APM both are enabled, then multiplier will be 2. i.e., workers will be 2 times of configured workers.
     * @return Multiplier for policy workers
     */
    public static int getPolicyMultiplier()
    {
        var multiplier = 0;

        if (LicenseUtil.MONITORING_ENABLED.get())
        {
            multiplier++;
        }

        if (LicenseUtil.APM_ENABLED.get())
        {
            multiplier++;
        }

        return multiplier == 0 ? 1 : multiplier;
    }

    /**
     * Deploys RUM event listener verticles.
     * Creates and starts multiple RUMEventListener worker instances based on configuration.
     * The number of listeners is determined by MotadataConfigUtil.getRUMEventListeners().
     *
     * @return CompositeFuture that completes when all RUM event listeners are deployed
     */
    public static CompositeFuture deployRumEventListeners()
    {
        var futures = new ArrayList<Future<Void>>();

        for (var index = 0; index < MotadataConfigUtil.getRUMEventListeners(); index++)
        {
            var promise = Promise.<Void>promise();

            futures.add(promise.future());

            Bootstrap.startWorkerEngine(new RUMEventListener(), RUMEventListener.class.getSimpleName() + DOT_SEPARATOR + index, null).onComplete(asyncResult ->
            {
                if (asyncResult.succeeded())
                {
                    promise.complete();
                }
                else
                {
                    promise.fail(asyncResult.cause());
                }
            });
        }

        return Future.join(futures);
    }
