public class BootstrapManager
{
    private static final Logger LOGGER = new Logger(BootstrapManager.class, GlobalConstants.MOTADATA_SYSTEM, "Bootstrap Manager");

    public void start()
    {
        try
        {
            var file = new File(GlobalConstants.CURRENT_DIR + GlobalConstants.PATH_SEPARATOR + GlobalConstants.CONFIG_DIR + GlobalConstants.PATH_SEPARATOR + "motadata.json");

            if (file.exists())
            {
                LOGGER.info("motadata manager is getting started ...");

                if (MotadataConfigUtil.getSystemBootstrapType().equalsIgnoreCase(GlobalConstants.BootstrapType.AGENT.name()))
                {
                    file = new File(GlobalConstants.CURRENT_DIR + GlobalConstants.PATH_SEPARATOR + GlobalConstants.CONFIG_DIR + GlobalConstants.PATH_SEPARATOR + "agent.json");

                    AgentConfigUtil.loadAgentConfigs(new JsonObject(Files.readString(file.toPath(), StandardCharsets.UTF_8)));
                }

                WebClientUtil.init();

                EventBusConstants.setManagerRegistrationId();

                var promise = Promise.promise();

                CommonUtil.getRemoteEventSenders().forEach(
                        host -> Bootstrap.startEngine(new RemoteEventSender(buildClientTransportConfig(MotadataConfigUtil.getMotadataManagerEventProtocol(), MotadataConfigUtil.getMotadataManagerEventSenderPort(), null, host.toString(), EventBusConstants.SocketMode.PUSH)), String.format("%s %s:%s", RemoteEventSender.class.getSimpleName(), host, MotadataConfigUtil.getMotadataManagerEventSenderPort()), null)
                                        .compose(future -> Bootstrap.startEngine(new RemoteEventReceiver(buildClientTransportConfig(MotadataConfigUtil.getMotadataManagerEventProtocol(), MotadataConfigUtil.getMotadataManagerEventReceiverPort(), EVENT_PUBLICATION, host.toString(), EventBusConstants.SocketMode.SUB)), String.format("%s %s:%s", RemoteEventReceiver.class.getSimpleName(), host, MotadataConfigUtil.getMotadataManagerEventReceiverPort()), null))
                                .onComplete(result ->
                        {
                            if (result.succeeded())
                            {
                                promise.complete();
                            }
                            else
                            {
                                promise.fail(result.cause());
                            }
                        }));


                        promise.future().onComplete(result ->
                        {
                            if (result.succeeded())
                            {
                                Bootstrap.startEngine(new MotadataAppManager(), MotadataAppManager.class.getSimpleName(), null, EVENT_REMOTE).onComplete(asyncResult ->
                                {
                                    if (asyncResult.succeeded())
                                    {
                                        LogUtil.resetLogLevel(MotadataConfigUtil.getLogLevelResetTimerSeconds());

                                        LOGGER.info(String.format(InfoMessageConstants.MOTADATA_ENGINE_START_SUCCEEDED, Bootstrap.bootstrapType()));
                                    }
                                    else
                                    {
                                        LOGGER.warn(String.format("Motadata manager started to failed : reason %s ", asyncResult.cause()));
                                    }
                                });
                            }
                            else
                            {
                                LOGGER.warn(String.format("Motadata manager started to failed : reason %s ", result.cause()));
                            }
                        });
            }
            else
            {
                LOGGER.warn(String.format("failed to find %s configuration file, hence aborting motadata boot process....", file.getName()));

                System.exit(0);
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }
}

