                        {
                            send(remoteType, traceType, context, TRACE_DATASTORE_WORKER_INSTANCES);
                        }
                        else if (Objects.equals(context.getInteger(DATASTORE_CATEGORY), DatastoreCategory.SLO.getName()))
                        {
                            send(remoteType, sloType, context, SLO_DATASTORE_WORKER_INSTANCES);
                        }

                        if (CommonUtil.traceEnabled())
                        {
                            LOGGER.trace(String.format("secondary sync is received with context %s ", context.encode()));
                        }
                    }
                    else
                    {
                        LOGGER.info(String.format("datastore item does not exist , uuid : %s ", datastoreUUID));
