    {
        vertx.<Long>executeBlocking(future ->
                {
                    var id = record.containsKey(GlobalConstants.ID) ? record.getLong(GlobalConstants.ID) : CommonUtil.newId();

                    pool.preparedQuery(prepare(table, record)).execute(result ->
                    {
                        if (result.succeeded())
                        {
                            future.complete(id);
                        }
                        else
                        {
                            future.fail(result.cause().getMessage());
                        }
                    });
                },

                false,
                result ->
                {
                    if (result.succeeded())
                    {
                        handler.handle(Future.succeededFuture(result.result()));

                        if (!remoteIP.equalsIgnoreCase(MOTADATA_OBSERVER))
                        {
                            HAConstants.sync(table, null, record, user, remoteIP, HAConstants.HASyncOperation.SAVE.getName(), COMPLIANCE_DB);
                        }
                    }
                    else
                    {
                        LOGGER.error(result.cause());

                        handler.handle(Future.failedFuture(result.cause()));
                    }
                });

        return this;
    }

