                    if (query != null && !query.isEmpty())
                    {
                        pool.preparedQuery(query.getString(DBConstants.QUERY)).execute()
                                .onComplete(result ->
                                {
                                    if (result.succeeded())
                                    {
                                        if (!query.containsKey(DBConstants.TRANSFORM) || query.getBoolean(DBConstants.TRANSFORM))//fetch data in visualization format or list of result format
                                        {
                                            result.result().forEach(value -> transform(value, item));
                                        }
                                        else
                                        {
                                            var values = new JsonArray();

                                            result.result().forEach(value -> transform(value, values));

