   /**
    * Retrieves a set of entities based on the provided attributes.
    *
    * @param attributes The attributes to evaluate.
    * @return A set of entities derived from the attributes.
    */
   public static Set<String> getEntity(JsonObject attributes)
   {
       var entities = new HashSet<String>();

       for (var entity : entityMapping.entrySet())
       {
           var entityType = entity.getKey();

           if (attributes.getMap().keySet().stream().anyMatch(entity.getValue().getKey()::contains))
           {
               String entityValue = null;

               // Try each fallback key in order until we find a non-empty value
               // For example - DATABASE: tries "db.system.name" first, then "db.system" as fallback
               for (var value : entity.getValue().getValue())
               {
                   entityValue = attributes.getString(value);

                   if (CommonUtil.isNotNullOrEmpty(entityValue)) break;
               }

               // If no fallback key had a value, use "Custom"
               if (!CommonUtil.isNotNullOrEmpty(entityValue))
               {
                   entityValue = "Custom";
               }

               entities.add(entityType.getEntityType() + GlobalConstants.HASH_SEPARATOR + entityValue);
           }
       }

       return entities;
   }

   /**
    * Method will provide the final value based on the data type
    * @param value Value
    * @return Object
    */
   public static Object parseAttributeValue(AnyValue value, Logger logger)
   {
       return switch (value.getValueCase())
       {
           case INT_VALUE -> value.getIntValue();
           case STRING_VALUE -> value.getStringValue();
           case BOOL_VALUE -> value.getBoolValue();
           case BYTES_VALUE -> value.getBytesValue();
           case DOUBLE_VALUE -> value.getDoubleValue();
           case ARRAY_VALUE -> parseArrayValue(value.getArrayValue(), logger);
           case KVLIST_VALUE -> parseKeyValue(value.getKvlistValue(), logger);
           case VALUE_NOT_SET -> GlobalConstants.EMPTY_VALUE;
       };
   }

   /**
    * Method used to parse ARRAY
    * @param value Value
    * @return Object
    */
   private static JsonArray parseArrayValue(ArrayValue value, Logger logger)
   {
       var lists = new JsonArray();

       try
       {
           if (value != null)
           {
               for (var attribute : value.getValuesList())
               {
                   lists.add(parseAttributeValue(attribute, logger));
               }
           }
       }
       catch (Exception exception)
       {
           logger.error(exception);
       }

       return lists;
   }

   /**
    * Method used to parse KEY_VALUE_LIST
    * @param value Value
    * @return Object
    */
   private static JsonObject parseKeyValue(KeyValueList value, Logger logger)
   {
       var values = new JsonObject();

       try
       {
           if (value != null)
           {
               for (var keyValue : value.getValuesList())
               {
                   values.put(keyValue.getKey(), parseAttributeValue(keyValue.getValue(), logger));
               }
           }
       }
       catch (Exception exception)
       {
           logger.error(exception);
       }

       return values;
   }

