       };
   }

   /**
    * Determines the agent type based on the provided attributes.
    * @param attribute The attributes to evaluate.
    * @return The agent type as an Integer.
    */
   public static Integer getAgentType(JsonObject attribute)
   {
       var type = AgentType.JAVA.getName();

       var language = attribute.getString(TraceConstants.TELEMETRY_SDK_LANGUAGE, GlobalConstants.EMPTY_VALUE).toLowerCase().trim();

       if (language.contains("net"))
       {
           type = AgentType.DOT_NET.getName();
       }
       else if(language.contains("php"))
       {
           type = AgentType.PHP.getName();
       }
       else if(language.contains("nodejs"))
       {
           type = AgentType.NODE_JS.getName();
       }
       else if(language.contains("python"))
       {
           type = AgentType.PYTHON.getName();
       }
       else if(language.contains("go"))
       {
           type = AgentType.GO.getName();
       }
       else
       {
           // Support for another language's agent like Golang, Python, etc.
       }

       return type;
   }

   public static short getServiceType(JsonObject attributes)
   {
       for (var entity : serviceTypeMapping.entrySet())
       {
           if (attributes.getMap().keySet().stream().anyMatch(entity.getValue()::contains))
           {
               return entity.getKey().getServiceType();
           }
       }

       return ServiceType.CUSTOM.getServiceType();
   }

   /**
    * Method will check the service count from old and current agent config and based on that we will add or consume the license
    */
   public static boolean checkServiceLicense(JsonObject oldConfigs, JsonObject configs, boolean consumeLicense)
   {
       var valid = true;

       var provision = true;

       var count = 0;

       if (LicenseUtil.APM_ENABLED.get())
       {
           if (oldConfigs.containsKey(AGENT_TRACE) && configs.containsKey(AGENT_TRACE))
           {
               var prevServices = oldConfigs.getJsonObject(AGENT_TRACE).size();

               var services = configs.getJsonObject(AGENT_TRACE).size();

               if (prevServices < services)
               {
                   if (LicenseUtil.licensedTraceServiceConsumed(services - prevServices))
                   {
                       count = services - prevServices;
                   }
                   else
                   {
                       valid = false;
                   }
               }
               else
               {
                   count = prevServices - services;

                   provision = false;
               }
           }
           else if (configs.containsKey(AGENT_TRACE))
           {
               if (LicenseUtil.licensedTraceServiceConsumed(configs.getJsonObject(AGENT_TRACE).size()))
               {
                   count = configs.getJsonObject(AGENT_TRACE).size();
               }
               else
               {
                   valid = false;
               }
           }
           else if (oldConfigs.containsKey(AGENT_TRACE))
           {
               count = oldConfigs.getJsonObject(AGENT_TRACE).size();

               provision = false;
           }

           if (consumeLicense)
           {
               LicenseCacheStore.getStore().update(NMSConstants.TRACE_SERVICES, count, provision);
           }
       }

       return valid;
   }

   /**
    * - This method will add Service into TraceServiceConfigStore only if the service does not exist in Store.
    *
    * @param services - all trace services
    * @param username - username
    * @param remoteAddress - remoteAddress
    */
   public static void addService(JsonObject services, String username, String remoteAddress, String eventSource)
   {
       try
       {
           if (services != null && !services.isEmpty())
           {
               for (var name : services.getMap().keySet())
               {
                   var service = services.getJsonObject(name);

                   if (TraceServiceConfigStore.getStore().serviceExists(name))
                   {
                       LOGGER.info(String.format("Service %s already exists", name));

                       Bootstrap.configDBService().update(DBConstants.TBL_TRACE_SERVICE,
                               new JsonObject().put(DBConstants.FIELD_NAME, GlobalConstants.ID).put(VALUE, TraceServiceConfigStore.getStore().getIdByService(name)),
                               new JsonObject().put("archive", GlobalConstants.NO),
                               username,
                               remoteAddress,
                               result -> TraceServiceConfigStore.getStore().updateItem(TraceServiceConfigStore.getStore().getIdByService(name)));
                   }
                   else
                   {
                       LOGGER.info(String.format("Adding new service %s with type %s", name, service.getString(SERVICE_TYPE)));

                       Bootstrap.configDBService().save(DBConstants.TBL_TRACE_SERVICE, new JsonObject().put(TraceConstants.SERVICE_NAME, name).put(EVENT_SOURCE, remoteAddress).put(TraceConstants.SERVICE_TYPE, service.getString(SERVICE_TYPE)).put("archive", NO).put(EVENT_SOURCE, eventSource), username, remoteAddress, asyncResult ->
                       {
                           if (asyncResult.succeeded())
                           {
                               TraceServiceConfigStore.getStore().addItem(asyncResult.result());
                           }
                           else
                           {
                               LOGGER.error(asyncResult.cause());
                           }
                       });
                   }
               }
           }
       }
       catch (Exception exception)
       {
           LOGGER.error(exception);
       }
   }

   /**
    * Resolves the agent type based on the cache file name pattern.
    * * @param cacheFile - trace cache file
    */
   public static String resolve(String cacheFile)
   {
       if (cacheFile.contains("tracemetric"))
       {
           return TraceConstants.Type.METRIC.getName();
       }
       else if (cacheFile.contains("tracelog"))
       {
           return TraceConstants.Type.LOG.getName();
       }
       else if (cacheFile.contains("trace"))
       {
           return TraceConstants.Type.TRACE.getName();
       }

       return TraceConstants.Type.TRACE.getName();
   }

   /**
    * Method will be used to convert the OTEL attribute format to Json format.
    * Example : {"attributes":[{"key":"my.span.attr","value":{"stringValue":"some value"}},{"key":"my.span.attr2","value":{"intValue":200}},{"key":"my.span.attr3","value":{"boolValue":true}},{"key":"my.span.attr4","value":{"doubleValue":23.2}},{"key":"my.span.attr5","value":{"arrayValue":{"values":[{"stringValue":"/usr/local/java/jdk-17.0.6/bin/java"}]}}},{"key":"my.span.attr6","value":{"kvlistValue":[{"key":"service.name","value":{"stringValue":"my.service"}}]}}]}
    * @param attributes Attributes
    * @return Parsed Attributes
    */
   public static JsonObject parseAttribute(List<KeyValue> attributes, StringBuilder stackBuilder)
   {
       var attribute = new JsonObject();

       try
       {
           if (attributes != null && !attributes.isEmpty())
           {
               for (var keyValue : attributes)
               {
                   var metric = keyValue.getKey();

                   if (TraceConstants.GARBAGE_ATTRIBUTES.contains(metric)) continue;

                   var value = TraceConstants.parseAttributeValue(keyValue.getValue(), LOGGER);

                   if (value != null && !value.toString().isEmpty())
                   {
                       attribute.put(keyValue.getKey(), value);

                       trimStackTrace(metric, attribute, stackBuilder);
                   }
                   else
                   {
                       LOGGER.debug(String.format("Skipping attribute %s as value is null or empty", metric));
                   }
               }
           }
       }
       catch (Exception exception)
       {
           LOGGER.error(exception);
       }

       return attribute;
   }

   /**
    * Trims a long stack trace string found in the given metric attribute to reduce payload size.
    * <p>
    * If the metric name contains "stacktrace" (case-insensitive), and the stack trace exceeds
    * twice the value of {@link TraceConstants#STACKTRACE_MAX_LINES}, the method retains only the
    * first and last {@code STACKTRACE_MAX_LINES} lines. It inserts placeholder lines in between to indicate
    * the truncation.
    * </p>
    *
    * <p>This method helps optimize memory and storage usage, especially when processing large volumes
    * of traces that may contain extensive exception stack traces.</p>
    *
    * @param metric    the name of the metric (used to identify stack trace fields)
    * @param attribute the JSON object containing the metric and its value (expected to be the stack trace string)
    */
   private static void trimStackTrace(String metric, JsonObject attribute, StringBuilder stackBuilder)
   {
       try
       {
           if (metric.toLowerCase().contains("stacktrace") && stackBuilder != null)
           {
               // considering first and last 10 lines of stack trace
               var lines = attribute.getValue(metric).toString().split(NEW_LINE);

               if (lines.length > TraceConstants.STACKTRACE_MAX_LINES * 2)
               {
                   for (var i = 0; i < TraceConstants.STACKTRACE_MAX_LINES; i++) stackBuilder.append(lines[i]).append(NEW_LINE);

                   for (var i = lines.length - TraceConstants.STACKTRACE_MAX_LINES; i < lines.length; i++) stackBuilder.append(lines[i]).append(NEW_LINE);

                   attribute.put(metric, stackBuilder.toString());
               }

               if (MotadataConfigUtil.getEnvironmentType().equalsIgnoreCase(ENV_TEST))
               {
                   Bootstrap.vertx().eventBus().publish("test.trimmed.stack.trace", new JsonObject()
                           .put("untrimmedLineCount", lines.length)
                           .put("trimmedLineCount", attribute.getValue(metric).toString().split(NEW_LINE).length));
               }
           }
       }
       catch (Exception exception)
       {
           LOGGER.error(exception);
       }
       finally
       {
           if (stackBuilder != null)
           {
               stackBuilder.setLength(0);
           }
       }
   }

   /**
    * Appends headers to the provided buffer in the format required by the database.
    * @param buffer The buffer to append headers to.
    * @param timestamp The current timestamp.
    * @param pluginId The plugin ID.
    * @param objectId The object ID.
    */
   public static void appendBytes(Buffer buffer, long timestamp, int pluginId, int objectId)
   {
       buffer.setLongLE(0, timestamp);

       var plugin = pluginId + DASH_SEPARATOR + TraceConstants.resolvePlugin(pluginId);

       var bytes = plugin.getBytes(StandardCharsets.UTF_8);

       buffer.appendIntLE(bytes.length);

       buffer.appendBytes(bytes);

       buffer.appendByte(DatastoreConstants.DatastoreFormat.VERTICAL.getName().byteValue());

       buffer.appendByte(CommonUtil.getByteValue(DatastoreConstants.DatastoreType.TRACE_METRIC.ordinal()));

       buffer.appendIntLE(objectId);
   }

   /**
    * Iterates over the key-value pairs in the given JSON event and updates the buffer with each entry.
    * <p>
    * This method is responsible for serializing all fields of the event by delegating
    * to {@link #updateBuffer(String, String, int, Buffer, StringBuilder, Set)}.
    *
    * @param event   the JSON object containing metric data
    * @param buffer  the buffer where data will be appended
    * @param pluginId the plugin identifier used to tag the data
    * @param builder  a shared {@link StringBuilder} used for efficient string construction
    * @param mappers  a set of known metric mappers to track new mappings
    */
   public static void appendValues(JsonObject event, Buffer buffer, int pluginId, StringBuilder builder, Set<String> mappers)
   {
       event.forEach(key -> updateBuffer(key.getKey(), CommonUtil.getString(key.getValue()), pluginId, buffer, builder, mappers));
   }

   /**
    * Serializes a single metric column and its value into the provided buffer.
    * <p>
    * The method first determines the data category (e.g., FLOAT, NUMERIC, STRING) and encodes
    * the value accordingly. It also handles publishing updates to the column mapper if the
    * metric column is newly observed.
    *
    * @param column   the name of the metric column
    * @param value    the metric value as a string
    * @param pluginId the plugin identifier
    * @param buffer   the buffer into which the serialized data is written
    * @param builder  a shared string builder for constructing mapping keys
    * @param mappers  a set of existing mappings used to avoid duplicates
    */
   public static void updateBuffer(String column, String value, int pluginId, Buffer buffer, StringBuilder builder, Set<String> mappers)
   {
       try
       {
           builder.setLength(0);

           var category = DatastoreConstants.getDataCategory(true, column, value);

           buffer.appendByte(category);

           var bytes = column.getBytes(StandardCharsets.UTF_8);

           buffer.appendIntLE(bytes.length);

           buffer.appendBytes(bytes);

           if (category == DatastoreConstants.DataCategory.FLOAT.getName())
           {
               ByteUtil.writeDouble(buffer, CommonUtil.getDouble(value));
           }
           else if (category == DatastoreConstants.DataCategory.NUMERIC.getName()) // if it has decimal number than convert it into integer
           {
               buffer.appendLongLE(Math.round(CommonUtil.getDouble(value)));
           }
           else
           {
               bytes = value.getBytes(StandardCharsets.UTF_8);

               buffer.appendIntLE(bytes.length);

               buffer.appendBytes(bytes);
           }

           builder.append(category).append(COLUMN_SEPARATOR).append(pluginId).append(COLUMN_SEPARATOR).append(column).append(COLUMN_SEPARATOR).append(NO); //

           if (!mappers.contains(builder.toString()))
           {
               mappers.add(builder.toString());

               Bootstrap.vertx().eventBus().publish(EventBusConstants.EVENT_COLUMN_MAPPER_UPDATE, new JsonObject()
                       .put(EventBusConstants.CHANGE_NOTIFICATION_TYPE, EventBusConstants.ChangeNotificationType.UPDATE_METRIC_COLUMN.name())
                       .put(DatastoreConstants.MAPPER, builder.toString()));
           }
       }
       catch (Exception exception)
       {
           LOGGER.error(exception);
       }
   }

   /**
    * Resolves the plugin name string based on the plugin ID.
    * <p>
    * Returns the appropriate visualization source name depending on whether the plugin ID
    * corresponds to trace metrics or JVM metrics.
    *
    * @param pluginId the plugin ID to resolve
    * @return the corresponding plugin name used in visualization
    */
   public static String resolvePlugin(int pluginId)
   {
       if (pluginId == DatastoreConstants.PluginId.TRACE_METRIC.getName())
       {
           return VisualizationConstants.VisualizationDataSource.TRACE_METRIC.getName();
       }
       else if (pluginId == DatastoreConstants.PluginId.TRACE_ENTITY_METRIC.getName())
       {
           return VisualizationConstants.VisualizationDataSource.TRACE_ENTITY_METRIC.getName();
       }
       else
       {
           return VisualizationConstants.VisualizationDataSource.TRACE_JVM_METRIC.getName();
       }
   }

   /**
    * Serializes a trace event into a binary buffer and sends it to the datastore via the Vert.x event bus.
    * <p>
    * Includes timestamp, plugin and object identifiers, and all event fields. Uses {@link #appendValues}
    * to serialize metric data and publishes it to the appropriate trace category channel.
    *
    * @param event        the trace event data to be serialized
    * @param instanceName the name of the instance generating the metrics
    * @param objectId     the ID of the monitored object
    * @param pluginId     the plugin identifier for this data
    * @param builder      a shared string builder used for efficient mapper key generation
