    /**
     * Serializes a trace event into a binary buffer and sends it to the datastore via the Vert.x event bus.
     * <p>
     * Includes timestamp, plugin and object identifiers, and all event fields. Uses {@link #appendValues}
     * to serialize metric data and publishes it to the appropriate trace category channel.
     *
     * @param event        the trace event data to be serialized
     * @param instanceName the name of the instance generating the metrics
     * @param objectId     the ID of the monitored object
     * @param pluginId     the plugin identifier for this data
     * @param builder      a shared string builder used for efficient mapper key generation
     * @param mappers      a set of known mappers used to avoid redundant update broadcasts
     */
    public static void write(JsonObject event, String instanceName, int objectId, int pluginId, StringBuilder builder, Set<String> mappers)
    {
        try
        {
            var buffer = Buffer.buffer("UTF-8");

            TraceConstants.appendBytes(buffer, DateTimeUtil.currentSeconds(), pluginId, objectId);

            buffer.appendIntLE(instanceName.length());

            buffer.appendString(instanceName);

            TraceConstants.appendValues(event, buffer, pluginId, builder, mappers);

            Bootstrap.vertx().eventBus().send(EventBusConstants.EVENT_DATASTORE_WRITE + DOT_SEPARATOR + DatastoreConstants.DatastoreCategory.TRACE.getName(), buffer.getBytes());
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

    /**
     * Publishes a trace metric event to the Vert.x event bus if the service ID is valid.
     * <p>
     * Enriches the provided event with additional metadata such as object ID, plugin ID,
     * object category, and service ID, then publishes it to the {@code EVENT_TRACE_METRIC_POLICY} address.
     *
     * @param event    the JSON event containing trace metric data
     * @param objectId the unique identifier of the monitored object
     */
    public static void send(JsonObject event, int objectId, int pluginId, long serviceId)
    {
        if (serviceId != NOT_AVAILABLE)
        {
            Bootstrap.vertx().eventBus().publish(EventBusConstants.EVENT_METRIC_POLICY, event.put(com.mindarray.api.Metric.METRIC_OBJECT, ObjectConfigStore.getStore().getIdByObjectId(objectId))
                    .put(GlobalConstants.PLUGIN_ID, pluginId)
                    .put(AIOpsObject.OBJECT_ID, objectId)
                    .put(com.mindarray.api.Metric.METRIC_OBJECT, ObjectConfigStore.getStore().getIdByObjectId(objectId))
                    .put(AIOpsObject.OBJECT_CATEGORY, ObjectConfigStore.getStore().getItemByObjectId(objectId).getString(AIOpsObject.OBJECT_CATEGORY))
                    .put(TraceConstants.SERVICE_ID, serviceId));
        }
    }

    /**
     * Converts a given duration from one {@link TimeUnit} to another.
     *
     * <p>This method utilizes {@link TimeUnit#convert(long, TimeUnit)} to perform the conversion
     * between time units, making it useful for handling durations consistently across components
     * that operate with different time granularities (e.g., seconds, milliseconds, nanoseconds).</p>
     *
     * @param duration the duration value to convert
     * @param fromUnit the original time unit of the duration
     * @param toUnit   the target time unit to convert the duration to
     * @return the converted duration in the target time unit
     */
    public static long convertTime(long duration, TimeUnit fromUnit, TimeUnit toUnit)
    {
        return toUnit.convert(duration, fromUnit);
    }

    /**
     * Converts a {@link ByteString} representing a hexadecimal ID to a string format.
     *
     * <p>This method uses {@link HexFormat} to convert the byte array representation of the ID
     * into a human-readable hexadecimal string. It's useful for displaying or logging IDs in a
     * format that's easily recognizable and comparable.</p>
     *
     * @param id the {@link ByteString} containing the hexadecimal ID
    /* @return the hexadecimal ID as a string */
    public static String convertHex(ByteString id)
    {
        return HexFormat.of().formatHex(id.toByteArray());
    }

    /**
     * Serializes the attributes of an event into a byte array for efficient storage or transmission.
     * <p>
     * Each key-value pair in the {@code attributes} JSON object is processed as follows:
     * <ul>
     *   <li>The key is mapped to an integer ordinal using the {@link EventOrdinalCacheStore} to reduce space.</li>
     *   <li>The value is converted to a UTF-8 byte array.</li>
     *   <li>If the byte length exceeds {@link Short#MAX_VALUE}, the value is trimmed and a warning is logged.</li>
     *   <li>The ordinal (as a 4-byte integer), the byte length of the value (as a 2-byte short),
     *       and the value bytes are appended to the buffer.</li>
     * </ul>
     * This method ensures that attribute data does not exceed buffer size limits and provides
     * a compact binary representation suitable for downstream processing or database insertion.
     *
     * @param attributes a {@link JsonObject} representing event attributes to serialize
     * @return a byte array containing the packed attribute data
     */
    public static byte[] packEvent(JsonObject attributes)
    {
        var buffer = Buffer.buffer();

        for (var key : attributes.getMap().keySet())
        {
            var value = CommonUtil.getString(attributes.getValue(key, EMPTY_VALUE));

            buffer.appendIntLE(EventOrdinalCacheStore.getStore().getOrdinal(DatastoreConstants.PluginId.TRACE_SPAN.getName() + SEPARATOR + key));

            var bytes = value.getBytes(StandardCharsets.UTF_8);

            if (bytes.length > Short.MAX_VALUE) // if any counter value is greater than max of short we will be trimming its value
            {
                var trimmedValue = value.substring(0, Short.MAX_VALUE);

                bytes = trimmedValue.getBytes(StandardCharsets.UTF_8);

                attributes.put(key, trimmedValue);

                LOGGER.warn(String.format("Got large attribute value : %s", value));
            }

            buffer.appendShortLE(CommonUtil.getShort(bytes.length));

            buffer.appendBytes(bytes);
        }

        return buffer.getBytes();
    }

    /**
     * Evaluates whether a span should be sampled based on defined criteria.
     * <p>A span will be sampled if either:
     * <ul>
     *     <li>It has an error status ({@link Status.StatusCode#STATUS_CODE_ERROR})</li>
     *     <li>It is a root span (has no parent span ID)</li>
     * </ul>
     *
     * @param span The span to evaluate, represented as a JsonObject containing span attributes
     *            Must contain {@link TraceConstants#SERVICE_SPAN_STATUS} for error checking and
     *            {@link TraceConstants#SERVICE_SPAN_PARENT_ID} for root span checking
     *
     * @return {@code true} if the span should be sampled, {@code false} otherwise
     *         Returns {@code false} if an exception occurs during evaluation
     */
    public static boolean sample(JsonObject span)
    {
        var valid = false;

        try
        {
            if (span.getInteger(TraceConstants.SERVICE_SPAN_STATUS) == Status.StatusCode.STATUS_CODE_ERROR.getNumber())
            {
                // Considering error span
                valid = true;
            }
            else if (!CommonUtil.isNotNullOrEmpty(span.getString(TraceConstants.SERVICE_SPAN_PARENT_ID)))
            {
                // Considering root span
                valid = true;
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }

        return valid;
    }

    /**
     * Initializes the class loader for trace parser plugins.
     * <p>
     * This method creates a URLClassLoader that points to the plugin scripts directory,
     * allowing the system to dynamically load log parser plugins at runtime.
     * <p>
     * If an exception occurs during initialization, null is returned.
     *
     * @return A URLClassLoader for loading log parser plugins, or null if initialization fails
     */
    private static URLClassLoader init()
    {
        try
        {
            // MOTADATA-6240 : // Changed to use context class loader as parent to ensure plugin classes can access application-level classes within encrypted .exe; fixes classloading failure caused by jar2exe isolating system class loader
            return new URLClassLoader(null, new URL[]{new File(GlobalConstants.CURRENT_DIR + GlobalConstants.PATH_SEPARATOR + GlobalConstants.PLUGIN_SCRIPT_DIR + GlobalConstants.PATH_SEPARATOR).toURI().toURL()}, Thread.currentThread().getContextClassLoader());
        }
        catch (Exception exception)
        {
            return null;
        }
    }


    /**
     * Constructs a namespaced metric key by combining the instance key and the metric key.
     *
     * @param metricKey   the base metric key (e.g., "type", "name")
     * @param instanceKey the instance key used as the prefix
     * @return a string representing the full metric key in the format: instanceKey::metricKey
     */
    protected static String buildMetricKey(String metricKey, String instanceKey)
    {
        return instanceKey + INSTANCE_SEPARATOR + metricKey;
    }


