/**
 * A verticle responsible for calculating and managing trace statistics in real-time.
 * This class processes trace events, computes various metrics, and periodically generates
 * service-level key performance indicators (KPIs).
 *
 * <p>Key features include:
 * <ul>
 *     <li>Real-time trace statistics calculation</li>
 *     <li>Service-level KPI computation (error rates, durations, throughput)</li>
 *     <li>Percentile calculations (P50, P99) for trace durations</li>
 *     <li>Periodic metrics publishing to event bus</li>
 *     <li>Integration with data store for metrics persistence</li>
 * </ul>
 *
 * <p>The calculator processes the following metrics:
 * <ul>
 *     <li>Total trace count per service</li>
 *     <li>Average trace duration</li>
 *     <li>Error rates and success counts</li>
 *     <li>Throughput (traces per minute)</li>
 *     <li>Latency percentiles (P50, P99)</li>
 * </ul>
 *
 * <p>Statistics are calculated and flushed at configurable intervals
 * (default: {@code trace.stat.flush.timer.seconds}). The calculator maintains
 * separate statistics for each service and supports concurrent processing of
 * trace events.
 */
public class TraceStatCalculator extends AbstractVerticle
{
    private static final Logger LOGGER = new Logger(TraceStatCalculator.class, GlobalConstants.MOTADATA_TRACE, "Trace Stat Calculator");
    private final DecimalFormat decimalFormat = new DecimalFormat("#.####");
    // Time interval to update service stats. Default - 60 sec.
    private static final int TRACE_STAT_FLUSH_TIMER_SECONDS = MotadataConfigUtil.getTraceStatFlushTimerSeconds();
    // Time interval to update service dependency in dependency manager. Default - 30 sec.
    private static final Integer SERVICE_DEPENDENCY_FLUSH_INTERVAL =  MotadataConfigUtil.getServiceDependencyFlushTimerSeconds();
    // Time to clean up the trace context after given time. Default - 1 min.
    private static final Integer TRACE_CONTEXT_CLEANUP_TIME = MotadataConfigUtil.getTraceContextCleanUpTimeSeconds();
    private final Map<String, long[]> statsByService = new HashMap<>();
    private final Map<String, List<Long>> durationsByService = new HashMap<>();
    private final Map<String, long[]> entityStatsByService = new HashMap<>();
    private final Map<String,JsonObject> entityStats = new HashMap<>();
    private final Map<String, List<Long>> entityDurationsByService = new HashMap<>();
    private final JsonObject event = new JsonObject();
    private final StringBuilder builder = new StringBuilder(0);
    private Set<String> mappers;

    @Override
    public void start(Promise<Void> promise) throws Exception
    {
        try
        {
            mappers = new HashSet<>();

            vertx.eventBus().<JsonObject>localConsumer(EventBusConstants.EVENT_TRACE_STAT, message -> merge(message.body()));

            vertx.setPeriodic(MotadataConfigUtil.getEnvironmentType().equalsIgnoreCase(ENV_TEST) ? 150 * 1000L : TRACE_STAT_FLUSH_TIMER_SECONDS * 1000L, handler -> calculate());

            // Timer will process trace data to build service dependency relationships and cleans up old traces at every 1 min.
            vertx.setPeriodic(MotadataConfigUtil.getEnvironmentType().equalsIgnoreCase(ENV_TEST) ? 5 * 1000 : SERVICE_DEPENDENCY_FLUSH_INTERVAL * 1000L, timer -> sendServiceDependencyEvent());

            // Reset trace max events counter at every second
            vertx.setPeriodic(1000, id -> TraceCacheStore.getStore().reset());

            if (MotadataConfigUtil.getEnvironmentType().equalsIgnoreCase(ENV_TEST))
            {
                vertx.eventBus().<JsonObject>localConsumer("test.trace.stat", message ->
                        message.reply(new JsonObject().put(TraceConstants.SERVICE_NAME, JsonObject.mapFrom(statsByService)))).exceptionHandler(LOGGER::error);

                vertx.eventBus().<JsonObject>localConsumer("test.entity.trace.stat", message ->
                        message.reply(new JsonObject().put(TraceConstants.SERVICE_NAME, JsonObject.mapFrom(entityStatsByService)))).exceptionHandler(LOGGER::error);

                vertx.eventBus().<JsonObject>localConsumer("test.trace.stat.compute.percentile", message ->
                        message.reply(message.body().put("percentile", computePercentile(message.body().getJsonArray("data").getList(), message.body().getInteger("percentile")))));
            }

            promise.complete();
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);

            promise.fail(exception);
        }
    }

    /**
     * Merges trace statistics into internal data structures for aggregation.
     * <p>
     * The input JSON object is expected to contain trace statistics for one or more services, where each key
     * represents a service identifier and the corresponding value is another JSON object containing specific
     * trace metrics.
     * </p>
     *
     * <p>Internal maps {@code statsByService} and {@code durationsByService} are used for storing aggregated
     * values and duration lists respectively, keyed by service name.</p>
     **
     * @param stats the JSON object containing per-service trace statistics
     */
    private void merge(JsonObject stats)
    {
        try
        {

            var serviceStats = stats.getJsonObject("service.stats");

            var serviceEntityStats = stats.getJsonObject("service.entity.stats");

            if (serviceStats != null)
            {
                for (var entry : serviceStats.getMap().entrySet())
                {
                    var stat = serviceStats.getJsonObject(entry.getKey());

                    var durations = stat.getJsonArray(TraceConstants.TRACE_DURATION);

                    var values = statsByService.computeIfAbsent(entry.getKey(), value -> new long[7]);

                    values[0] += stat.getInteger(TraceConstants.TRACES);

                    values[1] += durations.stream().mapToLong(CommonUtil::getLong).sum();

                    values[2] += stat.getInteger(TraceConstants.TRACE_ERRORS);

                    values[3] += stat.getInteger(TraceConstants.EVENTS);

                    values[4] += stat.getLong(TraceConstants.TRACES_VOLUME_BYTES);

                    values[5] += stat.getLong(TraceConstants.SPANS_VOLUME_BYTES);

                    values[6] += stat.getInteger(TraceConstants.SPANS);

                    durationsByService.computeIfAbsent(entry.getKey(), k -> new ArrayList<>())
                            .addAll(durations.stream().map(CommonUtil::getLong).toList());
                }
            }

            if (serviceEntityStats != null)
            {
                for (var entry : serviceEntityStats.getMap().entrySet())
                {
                    var stat = serviceEntityStats.getJsonObject(entry.getKey());

                    var durations = stat.getJsonArray(TraceConstants.TRACE_DURATION);

                    var values = entityStatsByService.computeIfAbsent(entry.getKey(), value -> new long[3]);

                    values[0] += stat.getInteger(TraceConstants.TRACES);

                    values[1] += durations.stream().mapToLong(CommonUtil::getLong).sum();

                    values[2] += stat.getInteger(TraceConstants.TRACE_ERRORS);

                    entityStats.computeIfAbsent(entry.getKey(), k -> new JsonObject()
                            .put(TraceConstants.TRACE_ENTITY_TYPE, stat.getString(TraceConstants.TRACE_ENTITY_TYPE))
                            .put(TraceConstants.TRACE_ENTITY_VALUE, stat.getString(TraceConstants.TRACE_ENTITY_VALUE)));

                    entityDurationsByService.computeIfAbsent(entry.getKey(), k -> new ArrayList<>())
                            .addAll(durations.stream().map(CommonUtil::getLong).toList());
                }
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

    /**
     * Periodically calculates and writes service-level KPIs such as percentiles, error rates,
     * and trace durations. The default interval is 60 seconds but can be configured using the
     * "trace.stat.flush.timer.seconds" property. After processing, it publishes metrics to
     * the event bus and resets internal data structures.
     */
    private void calculate()
    {
        if (!statsByService.isEmpty())
        {
            var totalTraces = 0L;

            var totalSpans = 0L;

            var totalEvents = 0L;

            var totalTraceVolumeBytes = 0L;

            var totalSpanVolumeBytes = 0L;

            for (var key : statsByService.keySet())
            {
                var values = statsByService.get(key);

                try
                {
                    if (CommonUtil.getLong(values[0]) > 0)
                    {
                        var tokens = key.split(SEPARATOR_WITH_ESCAPE);

                        var objectId = CommonUtil.getInteger(tokens[1]);

                        totalTraces += values[0];

                        totalSpans += values[6];

                        totalEvents += values[3];

                        totalTraceVolumeBytes += values[4];

                        totalSpanVolumeBytes += values[5];

                        event.put(getColumn(NMSConstants.INSTANCE_NAME, false), tokens[0])
                                .put(getColumn(TraceConstants.SERVICE_INSTANCE_KEY, true), tokens[0])
                                .put(getColumn(TraceConstants.SERVICE_LANGUAGE, false), CommonUtil.getInteger(tokens[2]))
                                .put(getColumn(TraceConstants.TRACES, false), values[0])
                                .put(getColumn(TraceConstants.TYPE, false), TraceCacheStore.getStore().getServiceType(tokens[0]))
                                .put(getColumn(TraceConstants.TRACE_DURATION_US, false), Math.round(CommonUtil.getDouble(values[1] / values[0])))  // duration / total number of traces
                                .put(getColumn(TraceConstants.TRACE_DURATION_P99_US, false), Math.round(computePercentile(durationsByService.get(key), TraceConstants.PERCENTILE_99)))
                                .put(getColumn(TraceConstants.TRACE_DURATION_P50_US, false), Math.round(computePercentile(durationsByService.get(key), TraceConstants.PERCENTILE_50)))
                                .put(getColumn(TraceConstants.TRACE_ERRORS, false), values[2])
                                .put(getColumn(TraceConstants.TRACE_SUCCESS, false), values[0] - values[2])
                                .put(getColumn(TraceConstants.EVENTS, false), values[3])
                                .put(getColumn(TraceConstants.TRACES_VOLUME_BYTES, false), values[4])
                                .put(getColumn(TraceConstants.SPANS_VOLUME_BYTES, false), values[5])
                                .put(getColumn(TraceConstants.SPANS, false), values[6])
                                .put(getColumn(TraceConstants.TRACES_PER_MIN, false), Double.valueOf(decimalFormat.format(event.getDouble(TraceConstants.SERVICE_INSTANCE_KEY + GlobalConstants.INSTANCE_SEPARATOR + TraceConstants.TRACES) / (double) (TRACE_STAT_FLUSH_TIMER_SECONDS / 60))))
                                .put(getColumn(TraceConstants.TRACES_ERROR_RATE, false), Double.valueOf(decimalFormat.format((double)(event.getLong(TraceConstants.SERVICE_INSTANCE_KEY + GlobalConstants.INSTANCE_SEPARATOR + TraceConstants.TRACE_ERRORS) * 100)/event.getLong(TraceConstants.SERVICE_INSTANCE_KEY + GlobalConstants.INSTANCE_SEPARATOR + TraceConstants.TRACES))));

                        TraceConstants.write(event, tokens[0], objectId, DatastoreConstants.PluginId.TRACE_METRIC.getName(), builder, mappers);

                        TraceConstants.send(new JsonObject().put(RESULT, new JsonObject().put(TraceConstants.SERVICE_INSTANCE_KEY, new JsonArray().add(event))), objectId, DatastoreConstants.PluginId.TRACE_METRIC.getName(), TraceServiceConfigStore.getStore().getIdByService(event.getString(TraceConstants.SERVICE_INSTANCE_KEY)));

                        LOGGER.info(String.format("Trace service stat : %s", event));
                    }
                }
                catch (Exception exception)
                {
                    LOGGER.error(exception);
                }
                finally
                {
                    if (!MotadataConfigUtil.getEnvironmentType().equalsIgnoreCase(ENV_TEST))
                    {
                        values[0] = 0L; //reset trace count

                        values[1] = 0L; // reset trace duration

                        values[2] = 0L; // reset trace with error

                        values[3] = 0L; // reset events

                        values[4] = 0L; // reset trace volume bytes

                        values[5] = 0L; // reset span volume bytes

                        values[6] = 0L; // reset spans

                        durationsByService.clear();
                    }

                    event.clear();
                }
            }

            if (totalSpans > 0L)
            {
                LOGGER.info(String.format("======== OVER ALL STATS ============ , events/s:%s, span-count/s:%s, trace-count/s:%s, span-bytes/s:%s, trace-bytes/s:%s", totalEvents/TRACE_STAT_FLUSH_TIMER_SECONDS, totalSpans/TRACE_STAT_FLUSH_TIMER_SECONDS, totalTraces/TRACE_STAT_FLUSH_TIMER_SECONDS, totalSpanVolumeBytes/TRACE_STAT_FLUSH_TIMER_SECONDS, totalTraceVolumeBytes/TRACE_STAT_FLUSH_TIMER_SECONDS));
            }
        }

        if (!entityStatsByService.isEmpty())
        {
            for (var key : entityStatsByService.keySet())
            {
                var values = entityStatsByService.get(key);

                try
                {
                    if (CommonUtil.getLong(values[0]) > 0)
                    {
                        var tokens = key.split(SEPARATOR_WITH_ESCAPE);

                        var objectId = CommonUtil.getInteger(tokens[1]);

                        var serviceName = tokens[0];

                        var entity = tokens[3];

                        var instanceKey = serviceName + GlobalConstants.MULTI_INSTANCE_SEPERATOR + entity;

                        event.put(getServiceEntityColumn(NMSConstants.INSTANCE_NAME), instanceKey)
                                .put(TraceConstants.SERVICE_ENTITY_INSTANCE_KEY , instanceKey)
                                .put(getServiceEntityColumn( TraceConstants.TRACE_ENTITY_TYPE), entityStats.get(key).getString(TraceConstants.TRACE_ENTITY_TYPE))
                                .put(getServiceEntityColumn(TraceConstants.TRACE_ENTITY_VALUE), entityStats.get(key).getString(TraceConstants.TRACE_ENTITY_VALUE))
                                .put(getServiceEntityColumn(TraceConstants.TRACES), values[0])
                                .put(getServiceEntityColumn(TraceConstants.TRACE_DURATION_US), Math.round(CommonUtil.getDouble(values[1] / values[0])))  // duration / total number of traces
                                .put(getServiceEntityColumn(TraceConstants.TRACE_DURATION_P99_US), Math.round(computePercentile(entityDurationsByService.get(key), TraceConstants.PERCENTILE_99)))
                                .put(getServiceEntityColumn(TraceConstants.TRACE_DURATION_P50_US), Math.round(computePercentile(entityDurationsByService.get(key), TraceConstants.PERCENTILE_50)))
                                .put(getServiceEntityColumn(TraceConstants.TRACE_ERRORS), values[2])
                                .put(getServiceEntityColumn(TraceConstants.TRACE_SUCCESS), values[0] - values[2])
                                .put(getServiceEntityColumn(TraceConstants.TRACES_PER_MIN), Double.valueOf(decimalFormat.format(event.getDouble("service.entity~" + TraceConstants.TRACES) / (double) (TRACE_STAT_FLUSH_TIMER_SECONDS / 60))))
                                .put(getServiceEntityColumn(TraceConstants.TRACES_ERROR_RATE), Double.valueOf(decimalFormat.format((double)(event.getLong("service.entity~" + TraceConstants.TRACE_ERRORS) * 100)/event.getLong("service.entity~" + TraceConstants.TRACES))));

                        TraceConstants.write(event, instanceKey, objectId, DatastoreConstants.PluginId.TRACE_ENTITY_METRIC.getName(), builder, mappers);

                        TraceConstants.send(new JsonObject().put(RESULT, new JsonObject().put("service.entity", new JsonArray().add(event.put(TraceConstants.SERVICE_INSTANCE_KEY, serviceName)))), objectId, DatastoreConstants.PluginId.TRACE_ENTITY_METRIC.getName(), TraceServiceConfigStore.getStore().getIdByService(serviceName));

                        if (CommonUtil.debugEnabled())
                        {
                            LOGGER.debug(String.format("Trace service entity stat : %s", event));
                        }
                    }
                }
                catch (Exception exception)
                {
                    LOGGER.error(exception);
                }
                finally
                {
                    if (!MotadataConfigUtil.getEnvironmentType().equalsIgnoreCase(ENV_TEST))
                    {
                        values[0] = 0L; // reset trace count

                        values[1] = 0L; // reset trace duration

                        values[2] = 0L; // reset trace with error

                    }

                    event.clear();
                }
            }
            entityStatsByService.clear();

            entityStats.clear();

            entityDurationsByService.clear();
        }
    }

    /**
     * Computes the specified percentile (e.g., P50, P99) from a list of trace durations.
     *
     * @param data A list of trace durations.
     * @param percentile The desired percentile to compute.
     * @return The computed percentile value.
     */
    private double computePercentile(List<Long> data, int percentile)
    {
        var value = 0.0D;

        try
        {
            if (data != null && !data.isEmpty())
            {
                Collections.sort(data);

                var index = (percentile/100.0) * (data.size() - 1); // index =  (p/100) * (n - 1)

                var fractionalPart = index % 1;

                var integerPart = (int) (index - fractionalPart);

                if (fractionalPart > DUMMY_NUMERIC_VALUE)
                {
                    value = (data.get(integerPart+1) - data.get(integerPart)) * fractionalPart + data.get(integerPart);
                }
                else
                {
                    value = data.get(integerPart);
                }
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }

        return Double.parseDouble(decimalFormat.format(value));
    }

    /**
     * Method used to get column name
     * @param column Key
     * @param instance instance
     * @return column
     */
    public static String getColumn(String column, boolean instance)
    {
        return !instance ? TraceConstants.SERVICE_INSTANCE_KEY + GlobalConstants.INSTANCE_SEPARATOR + column : TraceConstants.SERVICE_INSTANCE_KEY;
    }


    /**
     * Method used to get column name
     * @param column Key
