     */
    public static String getServiceEntityColumn(String column)
    {
        return  TraceConstants.SERVICE_ENTITY_INSTANCE_KEY + GlobalConstants.INSTANCE_SEPARATOR + column ;
    }

    /**
     * Processes trace data to build service dependency relationships and cleans up old traces.
     * For each trace:
     * 1. Identifies parent-child service relationships from spans
     * 2. Updates the dependency manager with these relationships
     * 3. Removes trace contexts older than the configured cleanup time
     * Note: By default, trace data is retained for 1 minutes (configurable via trace.context.clean.time.seconds)
     */
    private void sendServiceDependencyEvent()
    {
        vertx.executeBlocking(() ->
        {
            try
            {
                if (!TraceCacheStore.getStore().getSpansByTrace().isEmpty())
                {
                    var event = new JsonObject().put(AIOpsConstants.DEPENDENCY_TYPE, AIOpsConstants.DependencyType.LOCAL_DOMAIN.getName())
                            .put(AIOpsConstants.DEPENDENCY_OPERATION, AIOpsConstants.DependencyOperation.ADD_ENTITIES.getName());

                    TraceCacheStore.getStore().getSpansByTrace().forEach((traceId, spans) ->
                    {
                        spans.forEach((spanId, parentSpanId) ->

                                spans.entrySet().stream().filter(entry -> spanId.equals(entry.getValue())).forEach(entry ->
                                {
                                    var parentService = TraceCacheStore.getStore().getService(spanId);

                                    var childService = TraceCacheStore.getStore().getService(entry.getKey());

                                    if (!parentService.equals(childService))
                                    {
                                        if (CommonUtil.debugEnabled())
                                        {
                                            LOGGER.debug(String.format("Sending request to add dependency for the service : %s , dependency : %s", parentService, childService));
                                        }

                                        // call Dependency Manager to update service dependency mapping
                                        event.put(AIOpsConstants.DEPENDENCY_SOURCE, childService)
                                                .put(AIOpsConstants.DEPENDENCY_LEVEL, AIOpsConstants.DependencyLevel.MINUS_ONE.getName())
                                                .put(TraceConstants.ENTITY, parentService);

                                        vertx.eventBus().send(EVENT_DEPENDENCY + DOT_SEPARATOR + AIOpsConstants.DependencyType.LOCAL_DOMAIN.getName(), event);

                                        event.put(AIOpsConstants.DEPENDENCY_SOURCE, parentService)
                                                .put(AIOpsConstants.DEPENDENCY_LEVEL, AIOpsConstants.DependencyLevel.FOUR.getName())
                                                .put(TraceConstants.ENTITY, childService);

                                        vertx.eventBus().send(EVENT_DEPENDENCY + DOT_SEPARATOR + AIOpsConstants.DependencyType.LOCAL_DOMAIN.getName(), event);
                                    }
                                }));

                        // Removing the trace context after configured time. Default - 1 min
                        if (DateTimeUtil.currentSeconds() - TraceCacheStore.getStore().getTicksByTrace().get(traceId) > TRACE_CONTEXT_CLEANUP_TIME)
                        {
                            TraceCacheStore.getStore().removeTraceContext(traceId).forEach((spanId, parentSpanId) ->
                                    TraceCacheStore.getStore().removeSpansByService(spanId));

                            TraceCacheStore.getStore().removeTicksByTrace(traceId);
                        }
                    });
                }
            }
            catch (Exception exception)
            {
                LOGGER.error(exception);
            }

            return null;
        });
    }

    @Override
    public void stop(Promise<Void> promise)
    {
        calculate();

        promise.complete();
    }
}

