    private Future<Void> executeMetricGroupAttachPatch()
    {

        var promise = Promise.<Void>promise();

        var futures = new ArrayList<Future>();

        var items = ObjectConfigStore.getStore().getItemsByType(NMSConstants.Type.MARIADB);

        for (var item : items)
        {

            var metrics = MetricConfigStore.getStore().getItemsByObject((Long) item);

            var doPatch = true;

            for (var metric : metrics)
            {
                if (metric.getString(Metric.METRIC_PLUGIN).equals("mariadbindex"))
                {
                    doPatch = false;
                }
            }

            if (doPatch)
            {
                var itemPromise = Promise.promise();

                futures.add(itemPromise.future());

                var mariadbIndexMetric = metrics.getFirst().mergeIn(ObjectManagerCacheStore.getStore().getItemByMetricPlugin("mariadbindex"));

                mariadbIndexMetric.remove(ID);

                Bootstrap.configDBService().save(DBConstants.TBL_METRIC, mariadbIndexMetric, DEFAULT_USER, SYSTEM_REMOTE_ADDRESS, result ->
                {
                    if (result.succeeded())
                    {

                        MetricConfigStore.getStore().addItem(result.result()).onComplete(response ->
                        {
                            LOGGER.info("successfully attached plugin for monitor " + item);

                        });

                        itemPromise.complete();
                    }
                    else
                    {
                        LOGGER.error(result.cause());

                        itemPromise.fail(result.cause());

                    }
                });
            }
        }

        CompositeFuture.all(futures).onComplete(result ->
        {
            if (result.succeeded())
            {
                LOGGER.info("successfully attached plugin for all monitors");

                promise.complete();
            }

            else
            {
                LOGGER.error(result.cause());

                promise.fail("Failed to attach plugin for all monitors with reason : " + result.cause().getMessage());

            }
        });

        return promise.future();
    }

    // While bulk notification now we have different json structure which support rich notification like channel
    // so we will change json structure here like the policy context
    private Future<Void> updateObjectNotificationContext()
    {
        var promise = Promise.<Void>promise();

        try
        {
            var items = ObjectConfigStore.getStore().getItems();

            for (var index = 0; index < items.size(); index++)
            {
                var object = items.getJsonObject(index);

                if (object != null && object.containsKey(OBJECT_MONITOR_POLLING_FAILED_NOTIFICATION_STATUS) && object.getString(OBJECT_MONITOR_POLLING_FAILED_NOTIFICATION_STATUS).equalsIgnoreCase(YES))
                {
                    var notificationContext = new JsonObject().put(Notification.NotificationType.EMAIL.getName(),new JsonArray());

                    // we will only patch support the emails as for sms we need users and there is no guarantee there will be users available.
                    // discussed with PMG
                    // there are cases where it stored as string
                    if (object.containsKey(OBJECT_EMAIL_NOTIFICATION_RECIPIENTS))
                    {
                        if (object.getValue(OBJECT_EMAIL_NOTIFICATION_RECIPIENTS) instanceof JsonArray)
                        {
                            notificationContext.getJsonArray(Notification.NotificationType.EMAIL.getName()).addAll(object.getJsonArray(OBJECT_EMAIL_NOTIFICATION_RECIPIENTS));
                        }
                        else if (object.getValue(OBJECT_EMAIL_NOTIFICATION_RECIPIENTS) instanceof String)
                        {
                            notificationContext.getJsonArray(Notification.NotificationType.EMAIL.getName()).add(object.getString(OBJECT_EMAIL_NOTIFICATION_RECIPIENTS));
                        }
                    }

                    object.put(OBJECT_NOTIFICATION,notificationContext);

                    object.remove(OBJECT_EMAIL_NOTIFICATION_RECIPIENTS);

                    object.remove(OBJECT_SMS_NOTIFICATION_RECIPIENTS);

                }
            }

            Bootstrap.configDBService().upsertAll(DBConstants.TBL_OBJECT, items, DEFAULT_USER, SYSTEM_REMOTE_ADDRESS, result ->
            {
                if (result.succeeded())
                {
                    ObjectConfigStore.getStore().initStore().onComplete(asyncResult ->
                    {
                        if(asyncResult.succeeded())
                        {
                            LOGGER.info("successfully migrated all objects");

                            promise.complete();
                        }
                        else
                        {
                            LOGGER.error(asyncResult.cause());

                            promise.fail(asyncResult.cause());
                        }
                    });
                }
                else
                {
                    LOGGER.error(result.cause());

                    promise.fail(result.cause());
                }
            });
        }
        catch (Exception e)
        {
            LOGGER.error(e);

            promise.fail(e);
        }

        return promise.future();

    }


    private Future<Void> executeColumnMapperPatch()
    {
        Promise<Void> promise = Promise.promise();

        LOGGER.info("Executing column mapper patch for Cisco wireless rogue instances");

        Bootstrap.vertx().eventBus().<JsonObject>request(
                EventBusConstants.EVENT_METRIC_COLUMN_MAPPER_QUERY,
                new JsonObject(),
                reply -> handleColumnMapperResponse(reply, promise)
        );

        return promise.future();
    }

    /**
     * Handles the response from metric column mapper query
     */
    private void handleColumnMapperResponse(io.vertx.core.AsyncResult<io.vertx.core.eventbus.Message<JsonObject>> reply, Promise<Void> promise)
    {
        if (!reply.succeeded())
        {
            LOGGER.error(reply.cause());
            promise.fail(reply.cause());
            return;
        }

        var response = reply.result().body();
        if (response == null || !response.containsKey(DatastoreConstants.METRIC_COLUMNS))
        {
            LOGGER.info("No metric columns found in response");
            promise.complete();
            return;
        }

        var metricColumns = response.getJsonObject(DatastoreConstants.METRIC_COLUMNS);

        if (metricColumns == null)
        {
            LOGGER.info("Metric columns object is null");
            promise.complete();
            return;
        }

        // Use streams to filter and collect matching columns
        var matchingColumns = metricColumns.fieldNames().stream()
                .filter(columnName -> isTargetColumn(metricColumns.getJsonObject(columnName)))
                .collect(Collectors.toList());

        if (matchingColumns.isEmpty())
        {
            LOGGER.info("No columns found with target mapper instances: " + MAPPER_STATE_METRICS);
            promise.complete();
            return;
        }

        // Publish updates for all matching columns
        try
        {
            matchingColumns.forEach(this::publishColumnUpdate);

            LOGGER.info(String.format("Successfully modified %d columns: %s",
                    matchingColumns.size(), matchingColumns));

            promise.complete();
        }
        catch (Exception e)
        {
            LOGGER.error(e);

            promise.fail(e);
        }
    }

    /**
     * Checks if a column data contains target mapper instance
     */
    private boolean isTargetColumn(JsonObject columnData)
    {
        if (columnData == null || !columnData.containsKey(DatastoreConstants.MAPPER_INSTANCE))
        {
            return false;
        }

        String mapperInstance = columnData.getString(DatastoreConstants.MAPPER_INSTANCE);
        // Add null safety check
        return mapperInstance != null && MAPPER_STATE_METRICS.contains(mapperInstance);
    }

    /**
     * Publishes column update event
     */
    private void publishColumnUpdate(String columnName)
    {
        Bootstrap.vertx().eventBus().publish(
                EventBusConstants.EVENT_COLUMN_MAPPER_UPDATE,
                new JsonObject()
                        .put(CHANGE_NOTIFICATION_TYPE, DELETE_METRIC_COLUMN.name())
                        .put(DatastoreConstants.MAPPER, columnName)
        );
    }

}

