    private Future<Void> executeNSXTPatch()
    {

        var promise = Promise.<Void>promise();

        migrateDiscoveryObjects()
                .compose(result-> migrateObjects())
                .compose(result-> {
                    if (result)
                    {
                        return  migrateMetrics();
                    }
                    else
                    {
                        return Future.succeededFuture();
                    }
                })
                .compose(result-> migrateGroups())
                .onComplete(result-> {

                    if (result.succeeded())
                    {
                        promise.complete();
                    }
                    else {
                        promise.fail(result.cause());
                    }
                });

        return promise.future();
    }



    /**
     * Migrates discovery objects from NSXT to VMware NSX-T.
     * Updates discovery.object.type field in DiscoveryConfigStore.
     */
    private Future<Void> migrateDiscoveryObjects()
    {
        var promise = Promise.<Void>promise();

        try
        {
            var discoveryObjects = DiscoveryConfigStore.getStore().getItemsByValue(Discovery.DISCOVERY_OBJECT_TYPE, OLD_TYPE);

            if (discoveryObjects.isEmpty())
            {
                LOGGER.info("no discovery objects found with type NSXT");
                promise.complete();
                return promise.future();
            }

            LOGGER.info(String.format("found %d discovery objects to migrate", discoveryObjects.size()));

            var futures = new ArrayList<Future<Void>>();


            for (var i = 0; i < discoveryObjects.size(); i++)
            {

                futures.add(updateDiscoveryObject(discoveryObjects.getJsonObject(i)));
            }


            Future.join(futures).onComplete(result ->
            {
                if (result.succeeded())
                {
                    LOGGER.info("successfully migrated all discovery objects");
                    promise.complete();
                }
                else
                {
                    LOGGER.error(result.cause());
                    promise.fail(result.cause());
                }
            });
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
            promise.fail(exception);
        }

        return promise.future();
    }

