            group.put(Group.FIELD_GROUP_NAME,NEW_TYPE);

            Bootstrap.configDBService().update(DBConstants.TBL_GROUP,
                    new JsonObject().put(FIELD_NAME, GlobalConstants.ID).put(VALUE, group.getLong(ID)),
