                                    if (CommonUtil.traceEnabled())
                                    {
                                        LOGGER.trace(String.format("successfully updated object %s",
                                                object.getString(AIOpsObject.OBJECT_NAME, EMPTY_VALUE)));
                                    }
                                    promise.complete();
                                }
                                else
                                {
                                    LOGGER.warn(String.format("unable to update object store item %s with reason %s",
                                            object.encode(), asyncResult.cause().getMessage()));
                                    promise.fail(asyncResult.cause());
                                }
                            });
