    }

    /**
     * Migrates metric explorer configuration data by updating key names.
     * This method:
     * 1. Retrieves all records from the metric explorer configuration table
     * 2. For each record, renames keys by replacing "metric.explorer" prefix with "explorer"
     * 3. Handles nested context objects by updating their keys as well
     * 4. Saves the updated records to the explorer table
     * 5. Clears and reinitialize the ExplorerConfigStore to reflect changes
     *
     * @return A Future that completes when the migration is successful or fails with an exception
     */
    private Future<Void> executeMetricExplorerPatch()
    {
        var promise = Promise.<Void>promise();

        Bootstrap.configDBService().getAll("tbl_config_metric_explorer", result ->
        {
            if (result.succeeded())
            {
                var items = result.result();

                LOGGER.info(String.format("items : %s", items.encode()));

                var updatedItems = new JsonArray();

                for (var index = 0; index < items.size(); index++)
                {
                    try
                    {
                        var oldItem = items.getJsonObject(index);

                        var item = new JsonObject().put(Explorer.EXPLORER_TYPE, APIConstants.ExplorerType.METRIC.getName());

                        oldItem.getMap().keySet().forEach(key ->
                        {
                            try
                            {
                                if (key.startsWith("metric.explorer"))
                                {
                                    item.put(key.replace("metric.explorer", "explorer"), oldItem.getValue(key));
                                }
                                else
                                {
                                    item.put(key, oldItem.getValue(key));
                                }

                                if (key.equalsIgnoreCase("metric.explorer.context"))
                                {
                                    var oldContext = oldItem.getJsonObject("metric.explorer.context");

                                    var context = new JsonObject();

                                    oldContext.getMap().keySet().forEach(entry -> context.put(entry.replace("metric.explorer", "explorer"), oldContext.getValue(entry)));

                                    item.put(Explorer.EXPLORER_CONTEXT, context);
                                }
                            }
                            catch (Exception exception)
                            {
                                LOGGER.error(exception);
                            }
                        });

                        item.remove(ID);

                        updatedItems.add(item);
                    }
                    catch (Exception exception)
                    {
                        LOGGER.error(exception);
                    }
                }

                if (!updatedItems.isEmpty())
                {
                    Bootstrap.configDBService().saveAll(DBConstants.TBL_EXPLORER, updatedItems, SYSTEM_USER, MOTADATA_SYSTEM, asyncResult ->
                    {
                        if (asyncResult.succeeded())
                        {
                            ExplorerConfigStore.getStore().clear();

                            ExplorerConfigStore.getStore().initStore().onComplete(response ->
                            {
                                if (response.succeeded())
                                {
                                    LOGGER.info("successfully executed patch for metric explorer");

                                    promise.complete();
                                }
                                else
                                {
                                    LOGGER.error(response.cause());

                                    promise.fail(response.cause());
                                }
                            });
                        }
                        else
                        {
                            LOGGER.error(asyncResult.cause());

                            promise.fail(asyncResult.cause());
                        }
                    });
                }
                else
                {
                    promise.complete();

                    LOGGER.info("no metric explorer items found to patch");
                }
            }
            else
            {
                LOGGER.error(new Exception());

                promise.fail(result.cause());
            }
        });

        return promise.future();
    }

    private Future<Void> executeMetricPolicyPatch()
    {
        var promise = Promise.<Void>promise();

        // availability default policy
        var id = 10000000000012L;

        var category = 10000000000127L;

        var item = MetricPolicyConfigStore.getStore().getItem(id);

        if (item != null && item.getJsonObject(PolicyEngineConstants.POLICY_CONTEXT).getString(ENTITY_TYPE, EMPTY_VALUE).equalsIgnoreCase(APIConstants.Entity.GROUP.getName())
                && item.getJsonObject(PolicyEngineConstants.POLICY_CONTEXT).containsKey(ENTITIES)
                && !item.getJsonObject(PolicyEngineConstants.POLICY_CONTEXT).getJsonArray(GlobalConstants.ENTITIES).contains(category))
        {
            item.getJsonObject(PolicyEngineConstants.POLICY_CONTEXT).getJsonArray(GlobalConstants.ENTITIES).add(category);

            Bootstrap.configDBService().updateAll(DBConstants.TBL_METRIC_POLICY,
                    new JsonObject().put(DBConstants.FIELD_NAME, GlobalConstants.ID).put(GlobalConstants.VALUE, id),
                    item,
                    GlobalConstants.DEFAULT_USER, GlobalConstants.MOTADATA_SYSTEM, result ->
                    {
                        if (result.succeeded())
                        {
                            MetricPolicyConfigStore.getStore().updateItem(id).onComplete(asyncResult ->
                            {
                                if (asyncResult.succeeded())
                                {
                                    LOGGER.info("successfully updated availability default policy");

                                    promise.complete();
                                }
                                else
                                {
                                    promise.fail(result.cause());

                                    LOGGER.error(result.cause());
                                }
                            });
                        }
                        else
                        {
                            promise.fail(result.cause());

                            LOGGER.error(result.cause());
                        }
                    });
        }
        else
        {
            promise.complete();
        }

        return promise.future();
    }

    private Future<Void> executeColumnMapperPatch()
    {
        Promise<Void> promise = Promise.promise();

        LOGGER.info("Removing Tanzu metric columns");

        Bootstrap.vertx().eventBus().<JsonObject>request(
                EventBusConstants.EVENT_METRIC_COLUMN_MAPPER_QUERY,
                new JsonObject(),
                reply ->
                {
                    if (reply.succeeded())
                    {
                        var columns = reply.result().body().getJsonObject(DatastoreConstants.METRIC_COLUMNS).fieldNames().stream()
                                .filter(column -> column.startsWith("tanzu"))
                                .collect(Collectors.toList());

                        if (columns.isEmpty())
                        {
                            LOGGER.info("No Tanzu columns found");

                            promise.complete();

                            return;
                        }

                        for (String column : columns)
                        {

                            Bootstrap.vertx().eventBus().publish(EventBusConstants.EVENT_COLUMN_MAPPER_UPDATE,
                                    new JsonObject().put(CHANGE_NOTIFICATION_TYPE, DELETE_METRIC_COLUMN.name()).put(DatastoreConstants.MAPPER, column));
                        }

                        promise.complete();

                    }
                    else
                    {

                        promise.fail(reply.cause());

                        LOGGER.error(reply.cause());

                    }
                }
        );

        return promise.future();
    }


    /**
     * Migrates metric configs from NSXT to VMware NSX-T.
     * Updates metric.type field in MetricConfigStore.
     */
    private Future<Void> migrateMetrics()
    {
        var promise = Promise.<Void>promise();

        try
        {
            var metrics = MetricConfigStore.getStore().getItemsByValue(Metric.METRIC_TYPE, OLD_TYPE);

            if (metrics.isEmpty())
            {
                LOGGER.info("no metrics found with type NSXT");
                promise.complete();
                return promise.future();
            }

            LOGGER.info(String.format("found %d metrics to migrate", metrics.size()));

            var futures = new ArrayList<Future<Void>>();

            for (var i = 0; i < metrics.size(); i++)
            {

                futures.add(updateMetric(metrics.getJsonObject(i)));
            }


            Future.join(futures).onComplete(result ->
            {
                if (result.succeeded())
                {
                    LOGGER.info("successfully migrated all metrics");
                    promise.complete();
                }
                else
                {
                    LOGGER.error(result.cause());
                    promise.fail(result.cause());
                }
            });
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
            promise.fail(exception);
        }

        return promise.future();
    }

    /**
     * Updates a single metric's type from NSXT to VMware NSX-T.
     */
    private Future<Void> updateMetric(JsonObject metric)
    {
        var promise = Promise.<Void>promise();

        try
        {
            // Update the metric type
            metric.put(Metric.METRIC_TYPE, NEW_TYPE);

            Bootstrap.configDBService().update(DBConstants.TBL_METRIC,
                    new JsonObject().put(FIELD_NAME, GlobalConstants.ID).put(VALUE, metric.getLong(ID)),
                    metric, DEFAULT_USER, MOTADATA_SYSTEM, result ->
                    {
                        if (result.succeeded())
                        {
                            MetricConfigStore.getStore().updateItem(metric.getLong(ID)).onComplete(asyncResult ->
                            {
                                if (asyncResult.succeeded())
                                {
                                    if (CommonUtil.traceEnabled())
                                    {
                                        LOGGER.trace(String.format("successfully updated metric %s",
                                                metric.getString(Metric.METRIC_NAME, EMPTY_VALUE)));
                                    }
                                    promise.complete();
                                }
                                else
                                {
                                    LOGGER.warn(String.format("unable to update metric store item %s with reason %s",
                                            metric.encode(), asyncResult.cause().getMessage()));
                                    promise.fail(asyncResult.cause());
                                }
                            });
                        }
                        else
                        {
                            LOGGER.error(result.cause());
                            promise.fail(result.cause());
                        }
                    });
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);

            promise.fail(exception);
        }

        return promise.future();
    }

    private Future<Void> executeSchedulerPatch()
    {
        var promise = Promise.<Void>promise();

        try
        {
            var items = SchedulerConfigStore.getStore().getItems();

            var ids = new JsonArray();

            for (var index = 0; index < items.size(); index++)
            {
                try
                {
                    var item = items.getJsonObject(index);

                    if (!item.containsKey(Scheduler.SCHEDULER_JOB_TYPE))
                    {
                        LOGGER.info("corrupted scheduler item found, removing it : " + item.encode());

                        ids.add(item.getLong(ID));
                    }
                }
                catch (Exception exception)
                {
                    LOGGER.error(exception);
                }
            }

            if (!ids.isEmpty())
            {
                Bootstrap.configDBService().deleteAll(DBConstants.TBL_SCHEDULER, new JsonObject().put(FIELD_NAME, GlobalConstants.ID).put(VALUE, ids),
                        SYSTEM_USER, MOTADATA_SYSTEM, result ->
                        {
                            if (result.succeeded())
                            {
                                SchedulerConfigStore.getStore().deleteItems(ids);

                                promise.complete();
                            }
                            else
                            {
                                LOGGER.error(result.cause());

                                promise.fail(result.cause());
                            }
                        });
            }
            else
            {
                LOGGER.info("no corrupted scheduler items found");

                promise.complete();
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);

            promise.fail(exception);
        }

        return promise.future();
    }
