    private Future<Void> updateRetentionProfile()
    {
        var promise = Promise.<Void>promise();

        var item = DataRetentionPolicyConfigStore.getStore().getItem(GlobalConstants.DEFAULT_ID);

        if (item != null)
        {
            LOGGER.info("Existing retention profile : " + item.encode());

            var context = item.getJsonObject(DataRetentionPolicy.DATA_RETENTION_POLICY_CONTEXT);

            if (context != null)
            {
                if (context.containsKey("AUDIT") && context.getJsonObject("AUDIT").getInteger("raw") < 180)
                {
                    context.put("AUDIT", context.getJsonObject("AUDIT").put("raw", 180));

                    item.put(DataRetentionPolicy.DATA_RETENTION_POLICY_CONTEXT,context);

                    Bootstrap.configDBService().update(DBConstants.TBL_DATA_RETENTION_POLICY,
                            new JsonObject().put(FIELD_NAME, ID).put(VALUE, GlobalConstants.DEFAULT_ID),
                            item,
                            DEFAULT_USER,
                            MOTADATA_SYSTEM, result ->
                            {
                                if (result.succeeded())
                                {
                                    DataRetentionPolicyConfigStore.getStore().updateItem(GlobalConstants.DEFAULT_ID).onComplete(handler ->
                                    {
                                        if (handler.succeeded())
                                        {
                                            LOGGER.info("Data retention value changed for audit , new updated profile is : " + item.encode());

                                            promise.complete();
                                        }
                                        else
                                        {
                                            LOGGER.warn(String.format("Failed to Audit update Data retention in config store with reason : %s", handler.cause().getMessage()));

                                            promise.fail(handler.cause());
                                        }
                                    });
                                }
                                else
                                {
                                    LOGGER.warn(String.format("Failed to Audit update Data retention with reason : %s", result.cause().getMessage()));

                                    promise.fail(result.cause());
                                }
                            });
                }
                else
                {
                    LOGGER.info("No need to update retention profile, because audit retention is greater than 180 days.");

                    promise.complete();
                }
            }
            else
            {
                promise.fail("No retention profile context found");
            }
        }
        else
        {
            promise.fail("item not found");
        }

        return promise.future();
    }
}

