    @Override
    public Future<Void> doPatch()
    {
        var promise = Promise.<Void>promise();

        try
        {
            var item = DataRetentionPolicyConfigStore.getStore().getItem(10000000000001L);

            if (item != null)
            {
                item.getJsonObject(DataRetentionPolicy.DATA_RETENTION_POLICY_CONTEXT).getJsonObject("FLOW").put("raw", 2);//as MOTADATA-3716 will be updating flow data retention to 2

