                        DEFAULT_USER,
                        SYSTEM_REMOTE_ADDRESS, result ->
                        {
                            if (result.succeeded())
                            {
                                DataRetentionPolicyConfigStore.getStore().updateItem(10000000000001L).onComplete(handler ->
                                {
                                    LOGGER.info("Data retention value changed for flow");

                                    promise.complete();
                                });
                            }
                            else
                            {
                                LOGGER.warn(String.format("Failed to update Data retention with reason : %s", result.cause().getMessage()));

                                promise.fail(result.cause());
                            }
                        });
            }
            else
            {
                LOGGER.warn("Data retention item not found");

                promise.fail("Data retention item not found");
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);

            promise.fail(exception);
        }

        return promise.future();
    }
}

