    private static final Logger LOGGER = new Logger(Patch820.class, MOTADATA_PATCH, "Patch 8.2.0");

    private static final String VERSION = "8.2.0";

    @Override
    public String getVersion()
    {
        return VERSION;
    }

    @Override
    public Future<Void> doPatch()
    {
        var promise = Promise.<Void>promise();

        try
        {
            LOGGER.info("executing 8.2.0 patch...");

            var futures = new ArrayList<Future<Void>>();

            futures.add(updateLogParsersPatch());

            futures.add(executeCapacityPlanningReportPatch());

            futures.add(executeRetentionPatch()); // RUM retention patch

            futures.add(createFloatingColumns()); // RUM Floating column patch

            futures.add(executeColumnMapperPatch());

            futures.add(executeEventColumnMapperPatch());

            futures.add(updateExistingForecastReportPatch());

            Future.join(futures).onComplete(result ->
            {
                if (result.succeeded())
                {
                    LOGGER.info("successfully executed 8.2.0 patch");

                    promise.complete();
                }
                else
                {
                    LOGGER.error(result.cause());

                    promise.fail(result.cause());
                }
            });
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);

            promise.fail(exception);
        }

        return promise.future();
    }

    private Future<Void> updateLogParsersPatch()
    {
        var promise = Promise.<Void>promise();

        var futures = new ArrayList<Future<Void>>();

        LOGGER.info("Log parsers patch executing started...");

        futures.add(updateWindowsEventLogParsers());

        futures.add(updateWindowsCollectorLogParsers());

        futures.add(removeDefaultEventPolicies());

        Future.join(futures).onComplete(result ->
        {
            if (result.succeeded())
            {
                LOGGER.info("Log parsers updated successfully");

                promise.complete();
            }
            else
            {
                LOGGER.error(result.cause());

                promise.fail(result.cause());
            }
        });

        return promise.future();
    }

    private Future<Void> updateWindowsEventLogParsers()
    {
        var promise = Promise.<Void>promise();

        var item = LogParserConfigStore.getStore().getItem(10000000000008L);

        if (item != null && item.getJsonArray("log.parser.condition.keywords") != null && !item.getJsonArray("log.parser.condition.keywords").isEmpty())
        {
            var keywords = new JsonArray();

            keywords.add("source");
            keywords.add("provider");

            return updateEntity(item.put("log.parser.condition.keywords", keywords));
        }
        else
        {
            LOGGER.info("Windows Event Log Parser not found...");

            promise.complete();
        }

        return promise.future();
    }

    private Future<Void> removeDefaultEventPolicies()
    {
        var promise = Promise.<Void>promise();

        var ids = new JsonArray("""
                [
                  10000000000001,
                  10000000000002,
                  10000000000003,
                  10000000000004,
                  10000000000005,
                  10000000000006,
                  10000000000007,
                  10000000000008,
                  10000000000009,
                  10000000000010,
                  10000000000011,
                  10000000000012,
                  10000000000013,
                  10000000000015
                ]""");

        Bootstrap.configDBService().updateAll(DBConstants.TBL_EVENT_POLICY,
                new JsonObject().put(DBConstants.FIELD_NAME, ID).put(VALUE, ids),
                new JsonObject().put(PolicyEngineConstants.POLICY_ARCHIVED, YES),
                DEFAULT_USER, SYSTEM_REMOTE_ADDRESS,
                result ->
                {
                    if(result.succeeded())
                    {
                        EventPolicyConfigStore.getStore().updateItems(ids);

                        LOGGER.info("policy deleted successfully...");

                        promise.complete();
                    }
                    else
                    {
                        promise.fail(result.cause());
                    }
                });

        return promise.future();
    }

    private Future<Void> updateWindowsCollectorLogParsers()
    {
        var promise = Promise.<Void>promise();

        var item = LogParserConfigStore.getStore().getItem(10000000000029L);

        if (item != null)
        {
            return updateEntity(item.put("log.parser.dynamic.assign", "no"));
        }
        else
        {
            LOGGER.info("Windows Collector Log Parser not found...");

            promise.complete();
        }

        return promise.future();
    }

    private Future<Void> updateEntity(JsonObject entity)
    {
        var promise = Promise.<Void>promise();

        try
        {
            Bootstrap.configDBService().update(DBConstants.TBL_LOG_PARSER,
                    new JsonObject().put(FIELD_NAME, GlobalConstants.ID).put(VALUE, entity.getLong(ID)),
                    entity, DEFAULT_USER, MOTADATA_SYSTEM, result ->
                    {
                        if (result.succeeded())
                        {

                            LogParserConfigStore.getStore().updateItem(entity.getLong(ID)).onComplete(asyncResult -> promise.complete());

                            LOGGER.info(entity.getString(LogParser.LOG_PARSER_NAME) + " updated successfully...");
                        }
                        else
                        {
                            LOGGER.warn("Failed to update log parser : " + entity.getString(LogParser.LOG_PARSER_NAME) + " with reason : " + result.cause().getMessage());

                            LOGGER.error(result.cause());

                            promise.fail(result.cause());
                        }
                    });
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);

            promise.fail(exception);
        }

        return promise.future();

    }

    private Future<Void> updateExistingForecastReportPatch()
    {
        var promise = Promise.<Void>promise();

        try
        {
            LOGGER.info("Update existing forcast capacity planning report patch executing started...");

            var items = ReportConfigStore.getStore().getItemsByValue(Report.REPORT_TYPE,"forecast");

            var futures = new ArrayList<Future<Void>>();

            for (var index = 0; index < items.size(); index++)
            {
                var valid = false;

                var item = items.getJsonObject(index);

                if(item.containsKey(Report.REPORT_CONTEXT) && item.getJsonObject(Report.REPORT_CONTEXT).containsKey(ReportConstants.TEMPLATE) && item.getJsonArray(Report.REPORT_WIDGETS).size() > 1)
                {
                    valid = true;

                    item.getJsonArray(Report.REPORT_WIDGETS).remove(0); // remove first widget from forecast as it's not needed

                    var widget = item.getJsonArray(Report.REPORT_WIDGETS).getJsonObject(0);

                    widget.put("visualization.secondary.category", "Grid");

                    widget.getJsonObject(VisualizationConstants.VISUALIZATION_PROPERTIES).put("grid",item.getJsonObject(Report.REPORT_CONTEXT).getJsonObject(ReportConstants.TEMPLATE).getJsonObject(VisualizationConstants.VISUALIZATION_PROPERTIES).getJsonObject("grid"));

                    widget.getJsonObject(VisualizationConstants.VISUALIZATION_PROPERTIES).getJsonObject("chart").getJsonObject("sorting").remove("order");

                    item.getJsonObject(Report.REPORT_CONTEXT).put("report.forecast.type","percent");

                    // 3.5 position is needed because we want to show last value column after monitor, instance and before forecast columns
                    var column = new JsonObject()
                            .put("resizable", "yes")
                            .put("disable", "no")
                            .put("orderable", "yes")
                            .put("selectable", "yes")
                            .put("name", widget.getJsonArray(VisualizationConstants.VISUALIZATION_DATA_SOURCES).getJsonObject(0).getJsonArray(VisualizationConstants.DATA_POINTS).getJsonObject(0).getString(VisualizationConstants.DATA_POINT) + "." + DatastoreConstants.AggregationType.LAST.getName())
                            .put("show", "yes")
                            .put("sortable", "yes")
                            .put("position", 3.5)
                            .put("title", "Last Value");

                    widget.getJsonObject(VisualizationConstants.VISUALIZATION_PROPERTIES).getJsonObject(VisualizationConstants.VisualizationCategory.GRID.getName().toLowerCase()).getJsonArray(DBConstants.COLUMNS).add(column);

                    var reportWidget = item.getJsonArray(Report.REPORT_WIDGETS).getJsonObject(0).copy();

                    reportWidget.put(VisualizationConstants.VISUALIZATION_CATEGORY, VisualizationConstants.VisualizationCategory.GRID.getName());

                    var dataPoint = reportWidget.getJsonArray(VisualizationConstants.VISUALIZATION_DATA_SOURCES).getJsonObject(0).getJsonArray(VisualizationConstants.DATA_POINTS).getJsonObject(0);

                    dataPoint.put(VisualizationConstants.AGGREGATOR, DatastoreConstants.AggregationType.LAST.getName());

                    reportWidget.put(NMSConstants.LAST_POLL_VALUE, true);

                    item.getJsonArray(Report.REPORT_WIDGETS).add(reportWidget);
                }

                if(valid)
                {
                    var future = Promise.<Void>promise();

                    futures.add(future.future());

                    Bootstrap.configDBService.update(DBConstants.TBL_REPORT,
                            new JsonObject().put(FIELD_NAME, ID).put(VALUE, item.getLong(ID)),
                            item,
                            DEFAULT_USER, MOTADATA_SYSTEM, result ->
                            {
                                if(result.succeeded())
                                {
                                    ReportConfigStore.getStore().updateItem(item.getLong(ID)).onComplete(asyncResult ->
                                    {
                                        if(asyncResult.succeeded())
                                        {
                                            future.complete();
                                        }
                                        else
                                        {
                                            future.fail(asyncResult.cause());
                                        }
                                    });
                                }
                                else
                                {
                                    future.fail(result.cause());
                                }

                            });
                }
            }

            Future.join(futures).onComplete(result ->
            {
                if (result.succeeded())
                {
                    LOGGER.info("successfully updated forecast default reports");

                    promise.complete();
                }
                else
                {
                    LOGGER.error(result.cause());

                    promise.fail(result.cause());
                }
            });
        }
        catch (Exception e)
        {
            LOGGER.error(e);

            promise.fail(e);
        }

        return promise.future();

    }

    private Future<Void> executeCapacityPlanningReportPatch()
    {
        var promise = Promise.<Void>promise();

        try
        {
            LOGGER.info("Forcast capacity planning report patch executing started...");

            var items = ReportConfigStore.getStore().getItemsByValue(Report.REPORT_TYPE,"capacity.planning");

            var futures = new ArrayList<Future<Void>>();

            for (var index = 0; index < items.size(); index++)
            {
                var valid = false;

                var item = items.getJsonObject(index);

                if(item.containsKey(Report.REPORT_CONTEXT) && item.getJsonObject(Report.REPORT_CONTEXT).containsKey("template"))
                {
                    valid = true;

                    var style = new JsonObject("{\"color.conditions\":[{\"operator\":\">=\",\"value\":\"51\",\"color.type\":\"background\",\"color\":\"#4C545C\"}]}");

                    var grid = item.getJsonObject(Report.REPORT_CONTEXT).getJsonObject("template").getJsonObject(VisualizationConstants.VISUALIZATION_PROPERTIES).getJsonObject("grid");

                    grid.put("value.based.color","yes");

                    var columns = grid.getJsonArray("columns");

                    for (var colIndex = 0; colIndex < columns.size(); colIndex++) {

                        var column = columns.getJsonObject(colIndex);

                        if (column.containsKey("name") && column.getString("name").contains("utilization"))
                        {
                            if(item.getString(Report.REPORT_NAME,EMPTY_VALUE).toLowerCase().contains("idle"))
                            {
                                style.getJsonArray("color.conditions").getJsonObject(0).put("color", "#A5BAD033"); // Idle
                            }
                            else if(item.getString(Report.REPORT_NAME,EMPTY_VALUE).toLowerCase().contains("overutilized"))
                            {
                                style.getJsonArray("color.conditions").getJsonObject(0).put("color", "#F25C4E33"); // Overutilized
                            }
                            else if(item.getString(Report.REPORT_NAME,EMPTY_VALUE).toLowerCase().contains("underutilized"))
                            {
                                style.getJsonArray("color.conditions").getJsonObject(0).put("color", "#F5851833"); // Underutilized
                            }
                            column.put("style",style.copy());
                        }
                        else if (column.getString("name").contains(".value"))
                        {
                            valid = false; // on fresh installation we need to ignore this
                        }
                    }

                    columns.add(new JsonObject("{\"name\":\"cpu.utilization.value\",\"show\":\"no\",\"title\":\"cpu.utilization.value\",\"disable\":\"no\",\"position\":4,\"sortable\":\"yes\",\"orderable\":\"yes\",\"resizable\":\"yes\",\"selectable\":\"yes\"}"));

                    columns.add(new JsonObject("{\"name\":\"memory.utilization.value\",\"show\":\"no\",\"title\":\"memory.utilization.value\",\"disable\":\"no\",\"position\":4,\"sortable\":\"yes\",\"orderable\":\"yes\",\"resizable\":\"yes\",\"selectable\":\"yes\"}"));

                    columns.add(new JsonObject("{\"name\":\"disk.utilization.value\",\"show\":\"no\",\"title\":\"disk.utilization.value\",\"disable\":\"no\",\"position\":4,\"sortable\":\"yes\",\"orderable\":\"yes\",\"resizable\":\"yes\",\"selectable\":\"yes\"}"));
                }

                if(valid)
                {
                    var future = Promise.<Void>promise();

                    futures.add(future.future());

                    Bootstrap.configDBService.update(DBConstants.TBL_REPORT,
                            new JsonObject().put(FIELD_NAME, ID).put(VALUE, item.getLong(ID)),
                            item,
                            DEFAULT_USER, MOTADATA_SYSTEM, result ->
                            {
                                if(result.succeeded())
                                {
                                    ReportConfigStore.getStore().updateItem(item.getLong(ID)).onComplete(asyncResult ->
                                    {
                                        if(asyncResult.succeeded())
                                        {
                                            future.complete();
                                        }
                                        else
                                        {
                                            future.fail(asyncResult.cause());
                                        }
                                    });
                                }
                                else
                                {
                                    future.fail(result.cause());
                                }

                            });
                }

            }

            Future.join(futures).onComplete(result ->
            {
                if (result.succeeded())
                {
                    LOGGER.info("successfully updated capacity planning default reports");

                    promise.complete();
                }
                else
                {
                    LOGGER.error(result.cause());

                    promise.fail(result.cause());
                }
            });
        }
        catch (Exception e)
        {
            LOGGER.error(e);

            promise.fail(e);
        }


        return promise.future();
    }

    /**
     * Method will execute the retention patch for the APM trace.
     * @return Future indicating the success or failure of the patch execution
     */
    private Future<Void> executeRetentionPatch()
    {
        var promise = Promise.<Void>promise();

        var item = DataRetentionPolicyConfigStore.getStore().getItem(GlobalConstants.DEFAULT_ID);

        if (item != null)
        {
            item.getJsonObject(DataRetentionPolicy.DATA_RETENTION_POLICY_CONTEXT)
                    .put("RUM_METRIC", new JsonObject().put("raw", 7).put("aggregated", 7))
                    .put("RUM_EVENT", new JsonObject().put("raw", 2).put("aggregated", 2));

            Bootstrap.configDBService().update(DBConstants.TBL_DATA_RETENTION_POLICY,
                    new JsonObject().put(DBConstants.FIELD_NAME, ID).put(VALUE, DEFAULT_ID),
                    item, DEFAULT_USER, MOTADATA_SYSTEM, result ->
                    {
                        if (result.succeeded())
                        {
                            DataRetentionPolicyConfigStore.getStore().updateItem(DEFAULT_ID).onComplete(handler ->
                            {
                                LOGGER.info("Data retention value changed for RUM Metric and RUM Event");

                                promise.complete();
                            });
                        }
                        else
                        {
                            LOGGER.warn(String.format("Failed to update Data retention with reason : %s", result.cause().getMessage()));

                            promise.fail(result.cause());
                        }
                    });
        }
        else
        {
            promise.complete();
        }

        return promise.future();
    }

    private Future<Void> createFloatingColumns()
    {
        var promise = Promise.<Void>promise();

        var context = new JsonObject()
                .put(SLOConstants.SLO_BURN_RATE, EMPTY_VALUE)
                .put(SLOConstants.SLO_INSTANCE_BURN_RATE, EMPTY_VALUE)
                .put(SLOConstants.SLO_OBJECT_BURN_RATE, EMPTY_VALUE)
                .put("rum.view.cumulative.layout.shift", EMPTY_VALUE)
                .put("rum.apdex.rate", EMPTY_VALUE)
                .put("rum.service~cumulative.layout.shift", EMPTY_VALUE)
                .put("rum.service~apdex.rate", EMPTY_VALUE);

        try
        {
            var file = new File(CURRENT_DIR + PATH_SEPARATOR + GlobalConstants.CONFIG_DIR + PATH_SEPARATOR + DatastoreConstants.FLOATING_COLUMNS);

            if (file.exists())
            {
                LOGGER.info("floating columns already exists hence not creating");

                var existingContext = new JsonObject(Bootstrap.vertx().fileSystem().readFileBlocking(file.getPath()));

                context.mergeIn(existingContext);

                Bootstrap.vertx().fileSystem().writeFileBlocking(file.getPath(), Buffer.buffer(context.encodePrettily().getBytes()));

                promise.complete();
            }
            else
            {
                Bootstrap.vertx().fileSystem().writeFileBlocking(file.getPath(), Buffer.buffer(context.encodePrettily().getBytes()));

                LOGGER.info("floating columns created successfully");

                promise.complete();
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);

            promise.fail(exception);
        }
        finally
        {
            DatastoreConstants.loadConfigs();
        }

        return promise.future();
    }

    private Future<Void> executeColumnMapperPatch()
    {
        Promise<Void> promise = Promise.promise();

        LOGGER.info("removing started.time and started.time.seconds columns");

        Bootstrap.vertx().eventBus().<JsonObject>request(
                EventBusConstants.EVENT_METRIC_COLUMN_MAPPER_QUERY,
                new JsonObject(),
                reply ->
                {
                    if (reply.succeeded())
                    {
                        var columns = reply.result().body().getJsonObject(DatastoreConstants.METRIC_COLUMNS).fieldNames().stream()
                                .filter(column -> column.startsWith("started.time"))
                                .collect(Collectors.toList());

                        if (columns.isEmpty())
                        {
                            LOGGER.info("no columns found");

                            promise.complete();

                            return;
                        }

                        for (String column : columns)
                        {
                            Bootstrap.vertx().eventBus().publish(EventBusConstants.EVENT_COLUMN_MAPPER_UPDATE,
                                    new JsonObject().put(CHANGE_NOTIFICATION_TYPE, DELETE_METRIC_COLUMN.name()).put(DatastoreConstants.MAPPER, column));
                        }

                        promise.complete();

                    }
                    else
                    {

                        promise.fail(reply.cause());

                        LOGGER.error(reply.cause());

                    }
                }
        );

        return promise.future();
    }

    private Future<Void> executeEventColumnMapperPatch()
    {
        LOGGER.info("removing duration column");

        Bootstrap.vertx().eventBus().publish(EventBusConstants.EVENT_COLUMN_MAPPER_UPDATE,
                new JsonObject().put(CHANGE_NOTIFICATION_TYPE, DELETE_EVENT_COLUMN.name()).put(DatastoreConstants.MAPPER, "duration"));

        return Future.succeededFuture();
    }


}

