package com.mindarray.patch;

import com.mindarray.Bootstrap;
import com.mindarray.api.LDAPServer;
import com.mindarray.store.LDAPServerConfigStore;
import com.mindarray.util.Logger;
import io.vertx.core.Future;
import io.vertx.core.Promise;
import io.vertx.core.json.JsonObject;

import java.util.ArrayList;

import static com.mindarray.GlobalConstants.*;
import static com.mindarray.db.DBConstants.FIELD_NAME;
import static com.mindarray.db.DBConstants.TBL_LDAP_SERVER;

public class Patch8021 implements Patch
{
    private static final Logger LOGGER = new Logger(Patch8021.class, MOTADATA_PATCH, "Patch 8.0.21");

    private static final String VERSION = "8.0.21";

    @Override
    public String getVersion()
    {
        return VERSION;
    }

    @Override
    public Future<Void> doPatch()
    {
        var promise = Promise.<Void>promise();

        var futures = new ArrayList<Future<Void>>();

        LOGGER.info("executing patch 8.0.21");

        futures.add(executeLDAPServerPatch());

        Future.join(futures).onComplete(result ->
        {
            if (result.succeeded())
            {
                promise.complete();

                LOGGER.info("successfully executed patch 8.0.21");
            }
            else
            {
                promise.fail(result.cause());

                LOGGER.error(result.cause());
            }
        });

        return promise.future();
    }

    private Future<Void> executeLDAPServerPatch()
    {
        var promise = Promise.<Void>promise();

        try
        {
            var items = LDAPServerConfigStore.getStore().getItems();

            var futures = new ArrayList<Future<Void>>();

            for (var index = 0; index < items.size(); index++)
            {
                var item = items.getJsonObject(index);

                var future = Promise.<Void>promise();

                futures.add(future.future());

                item.put(LDAPServer.LDAP_SERVER_TYPE, LDAPServer.LDAP_SERVER_TYPE_AD);

                Bootstrap.configDBService().update(TBL_LDAP_SERVER,
                        new JsonObject().put(FIELD_NAME, ID).put(VALUE, item.getLong(ID)), item,
                        DEFAULT_USER, MOTADATA_SYSTEM, result ->
                        {
                            if (result.succeeded())
                            {
                                LDAPServerConfigStore.getStore().updateItem(item.getLong(ID)).onComplete(asyncResult ->
                                {
                                    if (asyncResult.succeeded())
                                    {
                                        LOGGER.info(String.format("updated ldap server : %s ", item.encode()));

                                        future.complete();
                                    }
                                    else
                                    {
                                        future.fail(asyncResult.cause());
                                    }
                                });
                            }
                            else
                            {
                                LOGGER.error(result.cause());

                                future.fail(result.cause());
                            }
                        });
            }

            Future.join(futures).onComplete(result ->
            {
                if (result.succeeded())
                {
                    LOGGER.info("LDAP Servers updated successfully!");

                    promise.complete();
                }
                else
                {
                    LOGGER.info("Failed to LDAP Servers : " + result.cause());

                    promise.fail(result.cause());
                }
            });
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);

            promise.fail(exception);
        }

        return promise.future();
    }
}

