/**
 * It handles composing responses for trace history queries, including span details and trace
 * information, while also managing data structures to store trace-related attributes and counts.
 * It also supports operations for visualizing trace data in formats such as grids and processes data
 * for specific visualization categories such as "Span Detail."
 *
 * <p>Components of this processor include:</p>
 * <ul>
 *     <li>Event bus consumers for trace history response data.</li>
 *     <li>Helper methods for composing trace history and span data into proper visualization formats.</li>
 *     <li>Data structures to hold trace information, including traceIds, attributes, and counts.</li>
 *     <li>Methods for cleaning up the internal data structures after processing.</li>
 * </ul>
 *
 * <p>Key functionality includes:</p>
 * <ul>
 *     <li>Consuming trace history data from the event bus.</li>
 *     <li>Processing and organizing trace and span data for visualization in various categories.</li>
 *     <li>Handling different visualization categories (e.g., GRID, TOP-N, HISTOGRAM, etc.) and types (e.g., TRACE, TRACE_SPAN, etc.).</li>
 *     <li>Handling and manipulating trace attributes for visual insights.</li>
 *     <li>Sending processed results back to the event bus for further visualization processing or display.</li>
 * </ul>
 */
public class VisualizationTraceHistoryResponseProcessor extends AbstractVerticle
{
    private static final Logger LOGGER = new Logger(VisualizationTraceHistoryResponseProcessor.class, GlobalConstants.MOTADATA_VISUALIZATION, "Visualization Trace history Response Processor");

    private final Map<Long, Long> queryTracker = new HashMap<>();

    private final Map<Long, TraceStats> traceStats = new HashMap<>();

    private final Map<Long, Scatter> scatterStats = new HashMap<>();

    private final Map<Long, APIStats> apiStats = new HashMap<>();

    public static final String SCATTERED_CHART = "scattered.chart";
    public static final String SPAN_DETAIL = "Span Detail";
    public static final String ROOT_SPAN = "root.span";
    public static final String API_STATS = "api.stats";

    @Override
    public void start(Promise<Void> promise)
    {
        try
        {
            vertx.setPeriodic(30 * 1000L, id ->
            {
                var currentTime = DateTimeUtil.currentSeconds();

                queryTracker.entrySet().removeIf(entry ->
                {
                    if (currentTime >= entry.getValue())
                    {
                        LOGGER.info(String.format("Query %s is removed due to timeout", entry.getKey()));

                        scatteredChartCleanup(entry.getKey());

                        cleanup(entry.getKey());

                        traceStats.remove(entry.getKey());

                        apiStats.remove(entry.getKey());

                        return true;
                    }

                    return false;
                });
            });

            Bootstrap.vertx().eventBus().<JsonObject>localConsumer(EventBusConstants.EVENT_VISUALIZATION_TRACE_HISTORY_RESPONSE_PROCESSOR, message ->
            {
                if (!message.body().isEmpty())
                {
                    var event = message.body();

                    queryTracker.computeIfAbsent(event.getLong(QUERY_ID), value -> DateTimeUtil.currentSeconds() + 300);

                    if (event.containsKey("error") && event.getString("error").equalsIgnoreCase(""))
                    {
                        scatteredChartCleanup(event.getLong(QUERY_ID));
                    }
                    else
                    {
                        composeQueryResponse(event.getInteger(QUERY_PROGRESS), event.getJsonObject(RESULT), event.getString(VISUALIZATION_CATEGORY, VisualizationCategory.GRID.getName()), event.getLong(QUERY_ID), event.getLong(VisualizationConstants.SUB_QUERY_ID), event.getJsonObject(QUERY_CONTEXT), LOGGER, event.getJsonObject(QUERY_CONTEXT).containsKey(DUMMY_FIELDS) ? event.getJsonObject(QUERY_CONTEXT).getBoolean(DUMMY_FIELDS) : false);
                    }
                }
            });
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }

        promise.complete();
    }

    /**
     * This method composes a query response based on the provided result, visualization context, and other parameters.
     * It processes trace history data and prepares the composed result for visualization.
     * The response is then published to the event bus.
     *
     * @param queryProgress         The current progress of the query, used to track progress during execution.
     * @param result                The raw result of the query to be processed.
     * @param visualizationCategory The category of the visualization being requested (e.g., Grid, Top-N, Histogram).
     * @param queryId              The unique identifier for the query.
     * @param subQueryId           The identifier for the sub-query within the main query.
     * @param context              The context containing visualization-specific configurations.
     * @param logger               The logger used to log messages during processing.
     * @param qualifyUniqueColumns A flag to qualify unique columns in the result.
     */
    public void composeQueryResponse(int queryProgress, JsonObject result, String visualizationCategory, long queryId, long subQueryId, JsonObject context, Logger logger, boolean qualifyUniqueColumns)
    {
        var composedResult = new JsonObject();

        try
        {
            if (CommonUtil.traceEnabled())
            {
                logger.trace(String.format("Result received in Trace History Response Processor : %s", result.encode()));
            }

            Scatter scatter = null;

            TraceStats traceStat = null;

            APIStats apiStat = null;

            var visualizationTimeline = context.getJsonObject(VISUALIZATION_TIMELINE);

            var timeline = VisualizationConstants.VisualizationTimeline.valueOfName(visualizationTimeline.getString(VisualizationConstants.RELATIVE_TIMELINE));

            if (context.getString(VisualizationConstants.VISUALIZATION_NAME, EMPTY_VALUE).equalsIgnoreCase(SCATTERED_CHART))
            {
                scatter = scatterStats.computeIfAbsent(queryId, value -> new Scatter());

                if (scatter.getDataPoints() == null)
                {
                    scatter.setDataPoints(createGrid(timeline, visualizationTimeline));
                }
            }
            else if(context.containsKey(VISUALIZATION_NAME) && context.getString(VISUALIZATION_NAME).equalsIgnoreCase(API_STATS))
            {
                apiStat = apiStats.computeIfAbsent(queryId, value -> new APIStats());
            }
            else
            {
                traceStat = traceStats.computeIfAbsent(queryId, value -> new TraceStats());
            }

            var dataSource = context.getJsonArray(VisualizationConstants.VISUALIZATION_DATA_SOURCES).getJsonObject(0);

            if (!context.containsKey(VisualizationConstants.JOIN_TYPE) || (context.containsKey(VisualizationConstants.JOIN_TYPE) && context.getString(VisualizationConstants.JOIN_TYPE).equalsIgnoreCase(VisualizationJoinType.JOIN_TYPE_CUSTOM.getName())))
            {
                var rows = result.getJsonObject(CommonUtil.getString(subQueryId)).getJsonArray(RESULT);

                if (rows != null)
                {
                    if (dataSource.getString(VisualizationConstants.TYPE).equalsIgnoreCase(VisualizationDataSource.TRACE_HISTORY.getName()))
                    {
                        try
                        {
                            var spans = new JsonArray();

                            for (var i = 0; i < rows.size(); i++)
                            {
                                if (scatter != null && context.containsKey(VISUALIZATION_NAME) && context.getString(VISUALIZATION_NAME).equalsIgnoreCase(SCATTERED_CHART))
                                {
                                    composeScatteredResponse(scatter, rows.getJsonObject(i), timeline, visualizationTimeline);
                                }
                                else if(context.containsKey(VISUALIZATION_NAME) && context.getString(VISUALIZATION_NAME).equalsIgnoreCase(API_STATS))
                                {
                                    composeApiStatsResponse(rows.getJsonObject(i), composedResult, apiStat, logger);
                                }
                                else
                                {
                                    composeTraceResponse(context, rows.getJsonObject(i), composedResult, spans, traceStat, logger);
                                }
                            }

                            if (scatter != null && scatter.getFlag() && (context.containsKey(VISUALIZATION_NAME) && context.getString(VISUALIZATION_NAME).equalsIgnoreCase(SCATTERED_CHART)))
                            {
                                scatter.setDivideFactor(getFactor(timeline, visualizationTimeline));
                            }

                            if (scatter != null && context.containsKey(VISUALIZATION_NAME) && context.getString(VISUALIZATION_NAME).equalsIgnoreCase(SCATTERED_CHART))
                            {
                                var scatteredChart = scatter.getDataPoints();

                                var chartResult = new JsonObject();

                                var firstTimestamp = visualizationTimeline.getLong("from.datetime") / 1000;

                                for (var index = 0; index < scatteredChart.get(0).size(); index++, firstTimestamp += scatter.getDivideFactor())
                                {
                                    chartResult.put(CommonUtil.getString(firstTimestamp), new JsonObject()
                                            .put("1001", scatteredChart.get(0).get(index))
                                            .put("1000", scatteredChart.get(1).get(index))
                                            .put("800", scatteredChart.get(2).get(index))
                                            .put("500", scatteredChart.get(3).get(index))
                                            .put("300", scatteredChart.get(4).get(index))
                                            .put("100", scatteredChart.get(5).get(index)));
                                }

                                composedResult.put("data", new JsonArray().add(chartResult));

                                scatter.setQueryProgress(queryProgress);

                                if (queryProgress == 100)
                                {
                                    scatteredChartCleanup(queryId);
                                }
                            }

                            if (context.containsKey(VisualizationConstants.VISUALIZATION_NAME) && context.getString(VisualizationConstants.VISUALIZATION_NAME).equalsIgnoreCase(SPAN_DETAIL))
                            {
                                // Adding all spans for the span drill down (flame-chart)
                                composedResult.put("service.spans", new JsonArray().add(spans.encode()));

                                composedResult.put("service.span.count", new JsonArray().add(composedResult.getInteger("service.span.count")));
                            }

                            if (!context.containsKey(VisualizationConstants.VISUALIZATION_NAME) && dataSource.getString(VisualizationConstants.CATEGORY).equalsIgnoreCase(VisualizationDataSource.TRACE_SPAN.getName()))
                            {
                                composeAttributes(context, traceStat);

                                composeTrace(composedResult, traceStat);
                            }

                            if (context.containsKey(VISUALIZATION_NAME) && context.getString(VISUALIZATION_NAME).equalsIgnoreCase(API_STATS))
                            {
                                composeApiStats(composedResult, apiStat);
                            }
                        }
                        catch (Exception exception)
                        {
                            LOGGER.error(exception);
                        }
                        finally
                        {
                            cleanup(queryId);
                        }
                    }
                }
            }

            if (!composedResult.isEmpty())
            {
                if ((context.getString(VisualizationConstants.VISUALIZATION_CATEGORY).equalsIgnoreCase(VisualizationConstants.VisualizationCategory.TOP_N.getName()) || context.getString(VisualizationConstants.VISUALIZATION_CATEGORY).equalsIgnoreCase(VisualizationConstants.VisualizationCategory.HISTOGRAM.getName()) || context.getString(VisualizationConstants.VISUALIZATION_CATEGORY).equalsIgnoreCase(VisualizationCategory.STREAM.getName())) && !context.getString(VisualizationConstants.VISUALIZATION_TYPE).equalsIgnoreCase(VisualizationConstants.VisualizationCategory.GRID.getName()))
                {
                    if (dataSource.getString(VisualizationConstants.TYPE).equalsIgnoreCase(VisualizationConstants.VisualizationDataSource.TRACE_HISTORY.getName())
                            && (dataSource.getString(VisualizationConstants.CATEGORY).equalsIgnoreCase(VisualizationDataSource.TRACE_SPAN.getName()) || dataSource.getString(VisualizationConstants.CATEGORY).equalsIgnoreCase(VisualizationDataSource.TRACE.getName())))
                    {
                        Bootstrap.vertx().eventBus().publish(EventBusConstants.EVENT_DATASTORE_QUERY_RESPONSE, CodecUtil.compress(VisualizationConstants.packChartResult(composedResult.put(QUERY_PROGRESS, queryProgress), VisualizationCategoryOrdinal.VISUALIZATION_GRID.ordinal(), queryId, subQueryId).getBytes()));
                    }
                    else
                    {
                        Bootstrap.vertx().eventBus().publish(EventBusConstants.EVENT_DATASTORE_QUERY_RESPONSE, CodecUtil.compress(VisualizationConstants.packChartResult(composedResult.put(QUERY_PROGRESS, queryProgress), VisualizationConstants.VisualizationCategoryOrdinal.VISUALIZATION_TOPN_CHART.ordinal(), queryId, subQueryId).getBytes()));
                    }
                }
                else
                {
                    Bootstrap.vertx().eventBus().publish(EventBusConstants.EVENT_DATASTORE_QUERY_RESPONSE, CodecUtil.compress(VisualizationConstants.packGridResult(composedResult.put(QUERY_PROGRESS, queryProgress), VisualizationConstants.VisualizationCategoryOrdinal.VISUALIZATION_GRID.ordinal(), queryId, subQueryId).getBytes()));
                }
            }
            else
            {
                //send back empty result

                VisualizationConstants.send(visualizationCategory, VisualizationConstants.VisualizationCategory.GRID.getName(), null, String.format(ErrorMessageConstants.VISUALIZATION_QUERY_FAILED, "Preview Widget", ErrorMessageConstants.INVALID_NO_DATA_FOUND), queryId, subQueryId, logger, EVENT_DATASTORE_QUERY_RESPONSE);
            }
        }
        catch (Exception exception)
        {
            logger.error(exception);
        }
    }

    /**
     * Composes API statistics into the final result object by populating arrays with metrics for each endpoint.
     * This method aggregates the collected API statistics (hits, success/failure counts, error rates) and
     * organizes them into parallel arrays in the composed result for visualization purposes.
     *
     * @param composedResult The JsonObject containing the final result with arrays for each metric
     * @param apiStat The APIStats object containing aggregated statistics for all API endpoints
     */
    private void composeApiStats(JsonObject composedResult, APIStats apiStat)
    {
        try
        {
            var item = composedResult.getMap();

            // Get or create the arrays
            var endPoint = (JsonArray) item.computeIfAbsent("service.span.name^value", value -> new JsonArray());
            var hits = (JsonArray) item.computeIfAbsent("service.span.hits^value", value -> new JsonArray());
            var successHits = (JsonArray) item.computeIfAbsent("service.span.success^value", value -> new JsonArray());
            var failedHits = (JsonArray) item.computeIfAbsent("service.span.failure^value", value -> new JsonArray());
            var error4xx = (JsonArray) item.computeIfAbsent("service.span.4xx^value", value -> new JsonArray());
            var error5xx = (JsonArray) item.computeIfAbsent("service.span.5xx^value", value -> new JsonArray());
            var failureRate = (JsonArray) item.computeIfAbsent("service.span.fail.rate^value", value -> new JsonArray());
            var successRate = (JsonArray) item.computeIfAbsent("service.span.success.rate^value", value -> new JsonArray());

            for (var entry : apiStat.getStats().entrySet())
            {
                var stats = entry.getValue();

                endPoint.add(entry.getKey());
                hits.add(stats.getLong("hits", 0L));
                successHits.add(stats.getLong("success.hits", 0L));
                failedHits.add(stats.getLong("failed.hits", 0L));
                error4xx.add(stats.getLong("error.4xx", 0L));
                error5xx.add(stats.getLong("error.5xx", 0L));
                failureRate.add(CommonUtil.getFloat((stats.getLong("failed.hits")/stats.getFloat("hits")) * 100));
                successRate.add(CommonUtil.getFloat((stats.getLong("success.hits")/stats.getFloat("hits")) * 100));            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

    /**
     * Processes a single row from the trace query response and updates API statistics.
     * This method extracts the status code and span name from each row and updates the
     * APIStats object to track hits, success/failure counts, and error rates per endpoint.
     *
     * @param row The JsonObject representing a single row from the query result
     * @param composedResult The JsonObject containing the final composed result (currently unused in this method)
     * @param apiStat The APIStats object to update with statistics from this row
     * @param logger The logger instance for error logging
     */
    private void composeApiStatsResponse(JsonObject row, JsonObject composedResult, APIStats apiStat, Logger logger)
    {
        try
        {
            // Get status code from the row
            var statusCode = row.getString(SERVICE_SPAN_STATUS_CODE + "^value");

            // Check if status code is valid (not empty and not "-")
            if (!statusCode.equals(DASH_SEPARATOR) && !statusCode.isEmpty())
            {
                // Get span name
                var spanName = row.getString(SERVICE_SPAN_NAME + "^value", DASH_SEPARATOR);

                apiStat.updateApiStats(spanName, statusCode);
            }
        }
        catch (Exception exception)
        {
            logger.error(exception);
        }
    }

    /**
     * This method processes a single trace row from the query result and adds relevant information to the composed result.
     * It handles different visualization types and categories for trace data, such as Span Detail and Trace History.
     * Depending on the visualization type, it may add root span details, event details, or span-related attributes to the response.
     *
     * @param context        The context containing visualization-specific configurations.
     * @param row           A single row of trace data to be processed.
     * @param composedResult The JsonObject that will hold the composed result, adding relevant trace information.
     * @param spans         A JsonArray to hold spans for the visualization if needed (

    {
        // Get status code from the row
        var statusCode = row.getString(SERVICE_SPAN_STATUS_CODE + "^value");

        // Check if status code is valid (not empty and not "-")
        if (!statusCode.equals(DASH_SEPARATOR) && !statusCode.isEmpty())
        {
            // Get span name
            var spanName = row.getString(SERVICE_SPAN_NAME + "^value", DASH_SEPARATOR);

            apiStat.updateApiStats(spanName, statusCode);
        }
    }
    catch (Exception exception)
    {
        logger.error(exception);
    }
}

/**
 * This method processes a single trace row from the query result and adds relevant information to the composed result.
 * It handles different visualization types and categories for trace data, such as Span Detail and Trace History.
 * Depending on the visualization type, it may add root span details, event details, or span-related attributes to the response.
 *
 * @param context        The context containing visualization-specific configurations.
 * @param row           A single row of trace data to be processed.
 * @param composedResult The JsonObject that will hold the composed result, adding relevant trace information.
 * @param spans         A JsonArray to hold spans for the visualization if needed (e.g., for Span Detail drill down).
 * @param logger        The logger used to log messages and any errors encountered during processing.
 */
public void composeTraceResponse(JsonObject context, JsonObject row, JsonObject composedResult, JsonArray spans, TraceStats traceStat, Logger logger)
{
    var datasource = context.getJsonArray(VisualizationConstants.VISUALIZATION_DATA_SOURCES).getJsonObject(0);

    var type = datasource.getString(VisualizationConstants.TYPE);

    var category = datasource.getString(VisualizationConstants.CATEGORY);

    var name = context.getString(VisualizationConstants.VISUALIZATION_NAME, EMPTY_VALUE);

    if (name.equalsIgnoreCase(SPAN_DETAIL))
    {
        // Composing result for the span drill down

        var span = extractAttributes(row, traceStat, logger);

        spans.add(span);

        if (span.getString(TraceConstants.SERVICE_SPAN_PARENT_ID).equalsIgnoreCase(EMPTY_VALUE))
        {
            var item = composedResult.getMap();

            // Setting Root Span Details
            ((JsonArray) item.computeIfAbsent(TraceConstants.SERVICE_TRACE_ID, value -> new JsonArray())).add(span.getString(TraceConstants.SERVICE_SPAN_TRACE_ID).intern());

            ((JsonArray) item.computeIfAbsent(TraceConstants.SERVICE_NAME, value -> new JsonArray())).add(span.getString(TraceConstants.SERVICE_SPAN_SERVICE_NAME));

            ((JsonArray) item.computeIfAbsent(TraceConstants.SERVICE_ROOT_SPAN_NAME, value -> new JsonArray())).add(span.getString(SERVICE_SPAN_NAME));

            ((JsonArray) item.computeIfAbsent(TraceConstants.SERVICE_TRACE_DURATION_US, value -> new JsonArray())).add(span.getLong(TraceConstants.SERVICE_SPAN_DURATION_US));

            ((JsonArray) item.computeIfAbsent(TraceConstants.SERVICE_TRACE_STATUS_CODE, value -> new JsonArray())).add(span.getString(SERVICE_SPAN_STATUS_CODE));

            ((JsonArray) item.computeIfAbsent(TraceConstants.SERVICE_TRACE_START_TIME_US, value -> new JsonArray())).add(span.getLong(TraceConstants.SERVICE_SPAN_START_TIME_US));

            ((JsonArray) item.computeIfAbsent("service.trace.method.name", value -> new JsonArray())).add(span.getString("service.span.method.name"));

            ((JsonArray) item.computeIfAbsent("service.trace.method.value", value -> new JsonArray())).add(span.getString("service.span.method.value"));
        }

        composedResult.put("service.span.count", composedResult.getInteger("service.span.count", 0) + 1);

        span.remove("Timestamp");

        span.remove(TraceConstants.SERVICE_SPAN_ATTRIBUTE_EVENT);

        span.remove(SERVICE_SPAN_STATUS_CODE);

        span.remove(TraceConstants.SERVICE_SPAN_EVENT);
    }
    else if (type.equalsIgnoreCase(VisualizationDataSource.TRACE_HISTORY.getName())
            && category.equalsIgnoreCase(VisualizationDataSource.TRACE_SPAN.getName()))
    {
        var span = extractAttributes(row, traceStat, logger);

        var traceId = span.getString(TraceConstants.SERVICE_SPAN_TRACE_ID).intern();

        var item = traceStat.getTrace().computeIfAbsent(traceId, val -> new JsonObject());

        if (span.getString(TraceConstants.SERVICE_SPAN_PARENT_ID).equalsIgnoreCase(EMPTY_VALUE))
        {
            // Adding Root Span Details
            item.put(TraceConstants.SERVICE_NAME, span.getString(TraceConstants.SERVICE_SPAN_SERVICE_NAME));

            item.put(TraceConstants.SERVICE_TRACE_START_TIME_US, span.getLong(TraceConstants.SERVICE_SPAN_START_TIME_US));

            item.put(TraceConstants.SERVICE_TRACE_RESOURCE_NAME, span.getString(SERVICE_SPAN_NAME));

            item.put(TraceConstants.SERVICE_TRACE_STATUS, span.getString(SERVICE_SPAN_STATUS_CODE));

            item.put(TraceConstants.SERVICE_TRACE_DURATION_US, span.getLong(TraceConstants.SERVICE_SPAN_DURATION_US));

            item.put(EVENT_SOURCE, span.getString(EVENT_SOURCE));

            item.put("event.id", span.getString("event.id"));

            item.put(EVENT_SOURCE, span.getString(EVENT_SOURCE));

            item.put(TraceConstants.SERVICE_TRACE_TOTAL_SPANS, span.getInteger(TraceConstants.SERVICE_SPAN_TOTAL_COUNT));

            traceStat.getTraceIds().add(traceId);
        }

        item.put(TraceConstants.SERVICE_TRACE_SPANS, item.getInteger(TraceConstants.SERVICE_TRACE_SPANS, 0) + 1);
    }
    else if (type.equalsIgnoreCase(VisualizationDataSource.TRACE_HISTORY.getName())
            && category.equalsIgnoreCase(VisualizationDataSource.TRACE.getName()))
    {
        compose(extractAttributes(row, traceStat, logger), composedResult);
    }
}

public void composeScatteredResponse(Scatter scatter, JsonObject row, VisualizationTimeline timeline, JsonObject visualizationTimeline)
{
    try
    {
        var duration = row.getLong("service.trace.duration.us^value", 0L) == 0 ? 0.0 : row.getLong("service.trace.duration.us^value", 0L) / 1000.0; // it needs to be converted to milliseconds

        var timestamp = row.getLong("service.trace.start.time.us^value") / 1000000;

        populateScatteredChart(scatter, duration, getBucketNumber(timeline, timestamp, visualizationTimeline.getLong("from.datetime") / 1000, visualizationTimeline, scatter.getBuckets()));
    }
    catch (Exception exception)
    {
        LOGGER.error(exception);
    }
}

/**
 * This method composes trace data by aggregating relevant information from individual traces
 * stored in the global `trace` map and populating it into the provided `composedResult` JsonObject.
 * It collects details like trace spans, event IDs, trace start time, duration, status, and other attributes
 * for all trace IDs and adds them to the composed result in arrays.
 *
 * @param composedResult The JsonObject that will be populated with composed trace data.
 */
public void composeTrace(JsonObject composedResult, TraceStats traceStat)
{
    traceStat.getTraceIds().forEach(id ->
    {
        if (traceStat.getTrace().containsKey(id))
        {
            var item = traceStat.getTrace().get(id);

            var result = composedResult.getMap();

            ((JsonArray) result.computeIfAbsent(TraceConstants.SERVICE_TRACE_SPANS, value -> new JsonArray())).add(item.getInteger(TraceConstants.SERVICE_TRACE_SPANS));

            ((JsonArray) result.computeIfAbsent("event.id", value -> new JsonArray())).add(item.getString("event.id"));

            ((JsonArray) result.computeIfAbsent(TraceConstants.SERVICE_TRACE_START_TIME_US, value -> new JsonArray())).add(item.getLong(TraceConstants.SERVICE_TRACE_START_TIME_US));

            ((JsonArray) result.computeIfAbsent(TraceConstants.SERVICE_TRACE_DURATION_US, value -> new JsonArray())).add(item.getLong(TraceConstants.SERVICE_TRACE_DURATION_US));

            ((JsonArray) result.computeIfAbsent(TraceConstants.SERVICE_TRACE_SERVICE_NAME, value -> new JsonArray())).add(item.getString(TraceConstants.SERVICE_NAME));

            ((JsonArray) result.computeIfAbsent(TraceConstants.SERVICE_TRACE_RESOURCE_NAME, value -> new JsonArray())).add(item.getString(TraceConstants.SERVICE_TRACE_RESOURCE_NAME));

            ((JsonArray) result.computeIfAbsent(TraceConstants.SERVICE_TRACE_STATUS, value -> new JsonArray())).add(item.getString(TraceConstants.SERVICE_TRACE_STATUS));

            ((JsonArray) result.computeIfAbsent(TraceConstants.SERVICE_TRACE_TOTAL_SPANS, value -> new JsonArray())).add(item.getInteger(TraceConstants.SERVICE_TRACE_TOTAL_SPANS));

            ((JsonArray) result.computeIfAbsent(TraceConstants.SERVICE_TRACE_ID, value -> new JsonArray())).add(id);

            ((JsonArray) result.computeIfAbsent(EVENT_SOURCE, value -> new JsonArray())).add(item.getString(EVENT_SOURCE));
        }
    });
}

/**
 * This method composes attributes for trace data, processes them, and sends the result
 * as a response via the event bus. It works with a global `attributes` map and `attributeCount` map
 * to gather trace-related data, aggregate it, and package it into a JsonObject for further processing.
 *
 * @param context The context JsonObject that contains information related to the query,
 *                such as the query ID and sub-query ID.
 */
public void composeAttributes(JsonObject context, TraceStats traceStat)
{
    var result = new JsonObject();

    traceStat.getAttributes().keySet().forEach(key ->
    {
        var val = new JsonObject();

        traceStat.getAttributes().get(key).forEach(attribute ->
        {
            var ids = traceStat.getAttributeCount().get(key + COLUMN_SEPARATOR + attribute);

            ids.retainAll(traceStat.getTraceIds());

            val.put(attribute + COLUMN_SEPARATOR + ids.size(), ids);
        });

        ((JsonArray) result.getMap().computeIfAbsent(key, value -> new JsonArray())).add(val.encode());
    });

    result.put(QUERY_PROGRESS, 50);

        var buffer = VisualizationConstants.packGridResult(result, VisualizationCategoryOrdinal.VISUALIZATION_TRACE_HISTORY.ordinal(), context.getLong(VisualizationConstants.QUERY_ID), context.getLong(SUB_QUERY_ID));

    Bootstrap.vertx().eventBus().publish(EventBusConstants.EVENT_DATASTORE_QUERY_RESPONSE, CodecUtil.compress(buffer.getBytes()));
}

/**
 * This method extracts relevant attributes from a given trace row, processes events if applicable,
 * and returns a JsonObject containing the extracted and processed attributes. The extracted attributes
 * are used for tracing and further processing. It also associates the extracted attributes with the trace ID.
 *
 * @param row The JsonObject containing trace data to extract attributes from.
 * @param logger The logger used for logging events or errors during extraction.
 * @return A JsonObject containing the extracted attributes.
 */
public JsonObject extractAttributes(JsonObject row, TraceStats traceStat, Logger logger)
{
    var result = new JsonObject();

    row.forEach(entry ->
    {
        result.put(entry.getKey().replace(CARET_SEPARATOR + VALUE, EMPTY_VALUE), entry.getValue());

        if (entry.getKey().equalsIgnoreCase(TraceConstants.SERVICE_SPAN_ATTRIBUTE_EVENT + CARET_SEPARATOR + VALUE))
        {
            var event = new JsonObject();

            extractEvent(row.getBuffer(TraceConstants.SERVICE_SPAN_ATTRIBUTE_EVENT + CARET_SEPARATOR + VALUE), event, null, null, logger);

            event.remove(LogEngineConstants.EVENT_PATTERN_ID);

            var traceId = row.getString(TraceConstants.SERVICE_SPAN_TRACE_ID + CARET_SEPARATOR + VALUE);

            result.put(entry.getKey().replace(CARET_SEPARATOR + VALUE , EMPTY_VALUE), event);

            for (var key : event.getMap().keySet())
            {
                addAttribute(key, CommonUtil.getString(event.getValue(key)), traceId, traceStat);
            }

            if (row.getString(TraceConstants.SERVICE_SPAN_PARENT_ID + CARET_SEPARATOR + VALUE).equalsIgnoreCase(EMPTY_VALUE))
            {
                addAttribute("span.name", row.getString(SERVICE_SPAN_NAME + CARET_SEPARATOR + VALUE), traceId, traceStat);

                addAttribute(EVENT_SOURCE, row.getString(EVENT_SOURCE + CARET_SEPARATOR + VALUE), traceId, traceStat);

                result.put("service.span.method.name", event.getString("http.request.method", "-"));

                result.put("service.span.method.value", event.getString("url.path", "-"));

                result.put(SERVICE_SPAN_STATUS_CODE, event.getString("http.response.status_code", DASH_SEPARATOR));
            }

            result.put("service.span.entity", event.getString("service.span.entity", DASH_SEPARATOR));
        }
    });

    return result;
}

/**
 * This method adds an attribute (key-value pair) to the global attribute store.
 * It updates two data structures: one for storing attribute values (associated with keys)
 * and another for counting the number of occurrences of the attribute value
 * across different trace IDs. This is crucial for efficiently tracking attributes
 * and their associations with traces.
 *
 * @param key The attribute key (e.g., attribute name or span name).
 * @param value The value associated with the attribute key (e.g., span value or attribute value).
 * @param traceId The trace ID associated with the attribute value, used to count occurrences across traces.
 */
private void addAttribute(String key, String value, String traceId, TraceStats traceStat)
{
    traceStat.getAttributes().computeIfAbsent(key, val -> new HashSet<>()).add(value);

    traceStat.getAttributeCount().computeIfAbsent(key + COLUMN_SEPARATOR + value, val -> new HashSet<>()).add(traceId);
}

/**
 * This method is responsible for cleaning up the internal data structures by clearing
 * all stored data. It ensures that the global maps and sets used to track attributes,
 * trace counts, and trace IDs are reset, effectively preparing the system for the next query
 * or operation. This is useful for preventing data leaks between queries or different visualizations.
 */
private void cleanup(long queryId)
{
    var traceStat = traceStats.get(queryId);

    if (traceStat != null)
    {
        LOGGER.info(String.format("Resetting TraceStat for query id %s", queryId));

        traceStat.getAttributes().clear();

        traceStat.getAttributeCount().clear();

        traceStat.getTraceIds().clear();

        traceStat.getTrace().clear();
    }
}

private void scatteredChartCleanup(long queryId)
{
    LOGGER.info(String.format("Resetting scattered chart for query id %s", queryId));

    scatterStats.remove(queryId);

    queryTracker.remove(queryId);

    apiStats.remove(queryId);
}

public int getBucket(long timestamp, long minTimestamp, double factor, int bucketCount)
{
    try
    {
        if (bucketCount == 0)
        {
            return 0; // no buckets configured
        }

        // Number of whole 'factor' intervals from minTimestamp to timestamp
        var intervals = ((timestamp - minTimestamp)) / factor;

        // If timestamp is before minTimestamp, place it in bucket 0
        if (intervals < 0)
        {
            return 0;
        }

        return (int) (intervals % bucketCount);
    }
    catch (Exception exception)
    {
        LOGGER.error(exception);
    }

    return 0;
}

private List<List<Integer>> createGrid(VisualizationTimeline timeline, JsonObject visualizationTimeline)
{
    var grid = new ArrayList<List<Integer>>();

    try
    {
        if (timeline.getName().equalsIgnoreCase("custom"))
        {
            var difference = getTimeDifferenceByCustomTimeline(visualizationTimeline);

            if (difference <= 5 * 60) // 5 minutes
            {
                createGrid((int) Math.round(difference / 10.0), grid);
            }
            else if (difference <= 15 * 60) // 15 minutes
            {
                createGrid((int) Math.round(difference / 30.0), grid);
            }
            else if (difference <= 30 * 60) // 30 minutes
            {
                createGrid((int) Math.round(difference / 60.0), grid);
            }
            else if (difference <= 60 * 60) // 1 hour
            {
                createGrid((int) Math.round(difference / 120.0), grid);
            }
            else if (difference <= 6 * 60 * 60) // 6 hours
            {
                createGrid((int) Math.round(difference / 600.0), grid);
            }
            else if (difference <= 12 * 60 * 60) // 12 hours
            {
                createGrid((int) Math.round(difference / 1200.0), grid);
            }
            else if (difference <= 24 * 60 * 60) // 24 hours
            {
                createGrid((int) Math.round(difference / 2400.0), grid);
            }
            else if (difference <= 48 * 60 * 60) // 48 hours
            {
                createGrid((int) Math.round(difference / 4800.0), grid);
            }
            else if (difference <= 7 * 24 * 60 * 60) // 7 days
            {
                createGrid((int) Math.round(difference / 21600.0), grid);
            }
            else
            {
                createGrid((int) Math.round(difference / 86400.0), grid);
            }
        }
        else
        {
            switch (timeline)
            {
                case LAST_15_MINUTES, LAST_5_MINUTES, LAST_30_MINUTES, LAST_1_HOUR, THIS_MONTH, LAST_MONTH -> createGrid(30, grid);

                case LAST_6_HOURS, LAST_12_HOURS, LAST_24_HOURS, LAST_48_HOURS, LAST_2_DAYS -> createGrid(36, grid);

                case TODAY, YESTERDAY, LAST_DAY -> createGrid(36, grid);

                case THIS_WEEK, LAST_WEEK -> createGrid(28, grid);

                default -> createGrid(0, grid);
            }
        }
    }
    catch (Exception exception)
    {
        LOGGER.error(exception);
    }

    return grid;
}

private void createGrid(int value, ArrayList<List<Integer>> grid)
{
    for (var x  = 0; x < 6; x++)
    {
        var box = new ArrayList<Integer>(value);

        grid.add(box);

        for (var y = 0; y < value; y++) box.add(0);
    }
}

