    private int getBucketNumber(VisualizationTimeline timeline, long timestamp, long minTimestamp, JsonObject visualizationTimeline, int buckets)
    {
        return switch (timeline)
        {
            case CUSTOM -> getBucketByCustomTimeline(visualizationTimeline, timestamp, minTimestamp, buckets);

            case LAST_5_MINUTES -> getBucket(timestamp, minTimestamp, 10.0, buckets);

            case LAST_15_MINUTES -> getBucket(timestamp, minTimestamp, 30.0, buckets);

            case LAST_30_MINUTES -> getBucket(timestamp, minTimestamp, 60.0, buckets);

            case LAST_1_HOUR -> getBucket(timestamp, minTimestamp, 120.0, buckets);

            case LAST_6_HOURS -> getBucket(timestamp, minTimestamp, 600.0, buckets);

            case LAST_12_HOURS -> getBucket(timestamp, minTimestamp, 600.0 * 2.0, buckets);

            case LAST_24_HOURS, YESTERDAY -> getBucket(timestamp, minTimestamp, 600.0 * 4.0, buckets);

            case LAST_48_HOURS, LAST_2_DAYS -> getBucket(timestamp, minTimestamp, 600.0 * 8.0, buckets);

            case TODAY, LAST_DAY -> getBucket(timestamp, minTimestamp, 2400.0, buckets); // 40 minutes

            case THIS_WEEK, LAST_WEEK -> getBucket(timestamp, minTimestamp, 21600.0, buckets); // 6 hours

            case THIS_MONTH, LAST_MONTH -> getBucket(timestamp, minTimestamp, 86400.0, buckets); // 1 day

            default -> getBucket(timestamp, minTimestamp, 0.0, buckets);
        };
    }

    private void populateScatteredChart(Scatter scatter, double duration, int bucketNumber)
    {
        var scatteredChart = scatter.getDataPoints();

        if (duration > 1000)
        {
            scatteredChart.getFirst().set(bucketNumber, scatteredChart.getFirst().get(bucketNumber) + 1);
        }
        else if (duration > 800)
        {
            scatteredChart.get(1).set(bucketNumber, scatteredChart.get(1).get(bucketNumber) + 1);
        }
        else if (duration > 500)
        {
            scatteredChart.get(2).set(bucketNumber, scatteredChart.get(2).get(bucketNumber)+1);
        }
        else if (duration > 300)
        {
            scatteredChart.get(3).set(bucketNumber, scatteredChart.get(3).get(bucketNumber) + 1);
        }
        else if (duration > 100)
        {
            scatteredChart.get(4).set(bucketNumber, scatteredChart.get(4).get(bucketNumber) + 1);
        }
        else
        {
            scatteredChart.get(5).set(bucketNumber, scatteredChart.get(5).get(bucketNumber) + 1);
        }
    }

    private int getFactor(VisualizationTimeline timeline, JsonObject visualizationTimeline)
    {
        return switch (timeline)
        {
            case CUSTOM -> getFactorByCustomTimeline(visualizationTimeline);
            case LAST_5_MINUTES -> 10;
            case LAST_15_MINUTES -> 30;
            case LAST_30_MINUTES -> 60;
            case LAST_1_HOUR -> 120;
            case LAST_6_HOURS -> 10 * 60;
            case LAST_12_HOURS -> 20 * 60;
            case LAST_24_HOURS, TODAY, LAST_DAY, YESTERDAY -> 40 * 60;
            case LAST_48_HOURS, LAST_2_DAYS -> 80 * 60;
            case THIS_WEEK, LAST_WEEK -> 6 * 60 * 60;
            case THIS_MONTH, LAST_MONTH -> 60 * 60 * 24;

            default -> 3600 * 6;
        };
    }

    public long toEpochSeconds(String date, String time)
    {
        // Combine date and time
        var localDateTime = LocalDateTime.of(LocalDate.parse(date.replace("/", "-")), LocalTime.parse(time));

        // Convert to epoch seconds (assuming system default timezone)
        return localDateTime.atZone(ZoneId.systemDefault()).toEpochSecond();
    }

    private int getBucketByCustomTimeline(JsonObject visualizationTimeline, long endTimestamp, long lastTimeStampSeconds, int bucketCount)
    {
        var difference = getTimeDifferenceByCustomTimeline(visualizationTimeline);

        if (difference <= 5 * 60) // 5 minutes
        {
            return getBucket(endTimestamp, lastTimeStampSeconds, 10.0, bucketCount);
        }
        else if (difference <= 15 * 60) // 15 minutes
        {
            return getBucket(endTimestamp, lastTimeStampSeconds, 30.0, bucketCount);
        }
        else if (difference <= 30 * 60) // 30 minutes
        {
            return getBucket(endTimestamp, lastTimeStampSeconds, 60.0, bucketCount);
        }
        else if (difference <= 60 * 60) // 1 hour
        {
            return getBucket(endTimestamp, lastTimeStampSeconds, 120.0, bucketCount);
        }
        else if (difference <= 6 * 60 * 60) // 6 hours
        {
            return getBucket(endTimestamp, lastTimeStampSeconds, 600.0, bucketCount);
        }
        else if (difference <= 12 * 60 * 60) // 12 hours
        {
            return getBucket(endTimestamp, lastTimeStampSeconds, 1200.0, bucketCount);
        }
        else if (difference <= 24 * 60 * 60) // 24 hours
        {
            return getBucket(endTimestamp, lastTimeStampSeconds, 2400.0, bucketCount);
        }
        else if (difference <= 48 * 60 * 60) // 48 hours
        {
            return getBucket(endTimestamp, lastTimeStampSeconds, 4800.0, bucketCount);
        }
        else if (difference <= 7 * 24 * 60 * 60) // 7 days
        {
            return getBucket(endTimestamp, lastTimeStampSeconds, 21600.0, bucketCount);
        }
        else
        {
            return getBucket(endTimestamp, lastTimeStampSeconds, 86400.0, bucketCount);
        }
    }

    private int getFactorByCustomTimeline(JsonObject visualizationTimeline)
    {
        var difference = getTimeDifferenceByCustomTimeline(visualizationTimeline);

        if (difference <= 5 * 60) // 5 minutes
        {
            return 10;
        }
        else if (difference <= 15 * 60) // 15 minutes
        {
            return 30;
        }
        else if (difference <= 30 * 60) // 30 minutes
        {
            return 60;
        }
        else if (difference <= 60 * 60) // 1 hour
        {
            return 120;
        }
        else if (difference <= 6 * 60 * 60) // 6 hours
        {
            return 600;
        }
        else if (difference <= 12 * 60 * 60) // 12 hours
        {
            return 1200;
        }
        else if (difference <= 24 * 60 * 60) // 24 hours
        {
            return 2400;
        }
        else if (difference <= 48 * 60 * 60) // 48 hours
        {
            return 4800;
        }
        else if (difference <= 7 * 24 * 60 * 60) // 7 days
        {
            return 21600;
        }
        else
        {
            return 86400;
        }
    }

    private long getTimeDifferenceByCustomTimeline(JsonObject visualizationTimeline)
    {
        var startEpoch = toEpochSeconds(visualizationTimeline.getString("from.date"), visualizationTimeline.getString("from.time"));

        var endEpoch = toEpochSeconds(visualizationTimeline.getString("to.date"), visualizationTimeline.getString("to.time"));

        return endEpoch - startEpoch;
    }

