        {
            stats = new HashMap<>();
        }

        public Map<String, JsonObject> getStats()
        {
            return stats;
        }

        public void updateApiStats(String name, String statusCode)
        {
            var stat = stats.computeIfAbsent(name, k -> new JsonObject().put("hits", 0L).put("success.hits", 0L).put("failed.hits", 0L).put("error.4xx", 0L).put("error.5xx", 0L));

            stat.put("hits", stat.getLong("hits") + 1);

            var isSuccess = statusCode.startsWith("2");

            stat.put("success.hits", stat.getLong("success.hits") + (isSuccess ? 1 : 0));

            stat.put("failed.hits", stat.getLong("failed.hits") + (!isSuccess ? 1 : 0));

            stat.put("error.4xx", stat.getLong("error.4xx") + (statusCode.startsWith("4") ? 1 : 0));

            stat.put("error.5xx", stat.getLong("error.5xx") + (statusCode.startsWith("5") ? 1 : 0));
        }

        public void clear()
        {
            stats.clear();
        }
    }
