/**
 * Processes RUM (Real User Monitoring) history query responses.
 * Handles session aggregation, drill-down responses, time series data, and histogram generation.
 */
public class VisualizationRUMHistoryResponseProcessor extends AbstractVerticle
{
    private static final Logger LOGGER = new Logger(VisualizationRUMHistoryResponseProcessor.class, GlobalConstants.MOTADATA_VISUALIZATION, "Visualization RUM history Response Processor");

    private static final JsonArray INTERVALS = new JsonArray().add(5).add(15).add(30).add(60).add(90).add(120).add(180).add(240).add(300).add(600).add(1200).add(1800).add(3600).add(3600 * 6).add(3600 * 12).add(3600 * 18).add(3600 * 24);

    private final Map<Long, Long> queryTracker = new HashMap<>();

    private final Map<Long, RumSession> rumSessions = new HashMap<>();

    private final Map<Long, TreeMap<Long, Set<String>>> queryTicks = new HashMap<>();

    private final Map<Long, Integer> queryIntervals = new HashMap<>();

    private final Map<Long, Set<String>> uniqueIds = new HashMap<>();

    /**
     * Starts the RUM history response processor verticle.
     * Sets up periodic cleanup of timed-out queries and event bus consumers for response processing.
     *
     * @param promise the promise to complete when startup is finished
     */
    @Override
    public void start(Promise<Void> promise)
    {
        try
        {
            vertx.setPeriodic(30 * 1000L, id ->
            {
                var currentTime = DateTimeUtil.currentSeconds();

                queryTracker.entrySet().removeIf(entry ->
                {
                    if (currentTime >= entry.getValue())
                    {
                        LOGGER.info(String.format("Query %s is removed due to timeout", entry.getKey()));

                        cleanUp(entry.getKey());

                        return true;
                    }

                    return false;
                });
            });

            Bootstrap.vertx().eventBus().<JsonObject>localConsumer(EventBusConstants.EVENT_VISUALIZATION_RUM_HISTORY_RESPONSE_PROCESSOR, message ->
            {
                if (!message.body().isEmpty())
                {
                    var event = message.body();

                    queryTracker.computeIfAbsent(event.getLong(QUERY_ID), value -> DateTimeUtil.currentSeconds() + 300);

                    if (event.containsKey("error") && event.getString("error").equalsIgnoreCase(""))
                    {
                        LOGGER.info(String.format("Received error response for query %s", event.getLong(QUERY_ID)));

                        cleanUp(event.getLong(QUERY_ID));
                    }
                    else
                    {
                        composeQueryResponse(event.getInteger(QUERY_PROGRESS), event.getJsonObject(RESULT), event.getString(VISUALIZATION_CATEGORY, VisualizationCategory.GRID.getName()), event.getLong(QUERY_ID), event.getLong(VisualizationConstants.SUB_QUERY_ID), event.getJsonObject(QUERY_CONTEXT), LOGGER, event.getJsonObject(QUERY_CONTEXT).containsKey(DUMMY_FIELDS) ? event.getJsonObject(QUERY_CONTEXT).getBoolean(DUMMY_FIELDS) : false);
                    }
                }
            });
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }

        promise.complete();
    }

    /**
     * This method composes a query response based on the provided result, visualization context, and other parameters.
     * It processes trace history data and prepares the composed result for visualization.
     * The response is then published to the event bus.
     *
     * @param queryProgress         The current progress of the query, used to track progress during execution.
     * @param result                The raw result of the query to be processed.
     * @param visualizationCategory The category of the visualization being requested (e.g., Grid, Top-N, Histogram).
     * @param queryId              The unique identifier for the query.
     * @param subQueryId           The identifier for the sub-query within the main query.
     * @param context              The context containing visualization-specific configurations.
     * @param logger               The logger used to log messages during processing.
     * @param qualifyUniqueColumns A flag to qualify unique columns in the result.
     */
    public void composeQueryResponse(int queryProgress, JsonObject result, String visualizationCategory, long queryId, long subQueryId, JsonObject context, Logger logger, boolean qualifyUniqueColumns)
    {
        var composedResult = new JsonObject();

        try
        {
            if (CommonUtil.traceEnabled())
            {
                logger.trace(String.format("Result received in Trace History Response Processor : %s", result.encode()));
            }

            var dataSource = context.getJsonArray(VisualizationConstants.VISUALIZATION_DATA_SOURCES).getJsonObject(0);

            var category = dataSource.getString(CATEGORY, EMPTY_VALUE);

            var eventType = EventTypeFactory.getType(category);

            if (!context.containsKey(VisualizationConstants.JOIN_TYPE) || (context.containsKey(VisualizationConstants.JOIN_TYPE) && context.getString(VisualizationConstants.JOIN_TYPE).equalsIgnoreCase(VisualizationJoinType.JOIN_TYPE_CUSTOM.getName())))
            {
                var rows = result.getJsonObject(CommonUtil.getString(subQueryId)).getJsonArray(RESULT);

                if (rows != null)
                {
                    if (dataSource.getString(VisualizationConstants.TYPE).equalsIgnoreCase(VisualizationDataSource.RUM_HISTORY.getName()))
                    {
                        var rumSession = rumSessions.computeIfAbsent(queryId, value -> new RumSession());

                        for (var index = 0; index < rows.size(); index++)
                        {
                            if (category.equalsIgnoreCase(VisualizationDataSource.RUM_SESSION.getName()))
                            {
                                composeSessionResponse(rows.getJsonObject(index), rumSession, eventType);
                            }
                            else if (category.equalsIgnoreCase(VisualizationDataSource.RUM_VIEW.getName()))
                            {
                                if (dataSource.getString("sub.category", "").equalsIgnoreCase("rum.view.drill.down"))
                                {
                                    composeDrillDownResponse(rows.getJsonObject(index), composedResult);
                                }
                                else
                                {
                                    composeResponse(rows.getJsonObject(index), rumSession, eventType);
                                }
                            }
                            else if (category.equalsIgnoreCase(VisualizationDataSource.RUM_VIEW_RESOURCE.getName()))
                            {
                                if (dataSource.getString("sub.category", "").equalsIgnoreCase("rum.view.resource.drill.down"))
                                {
                                    composeDrillDownResponse(rows.getJsonObject(index), composedResult);
                                }
                                else
                                {
                                    composeResponse(rows.getJsonObject(index), rumSession, eventType);
                                }
                            }
                            else if (category.equalsIgnoreCase(VisualizationDataSource.RUM_VIEW_ACTION.getName()))
                            {
                                if (dataSource.getString("sub.category", "").equalsIgnoreCase("rum.view.action.drill.down"))
                                {
                                    composeDrillDownResponse(rows.getJsonObject(index), composedResult);
                                }
                                else
                                {
                                    composeResponse(rows.getJsonObject(index), rumSession, eventType);
                                }
                            }
                            else if (category.equalsIgnoreCase(VisualizationDataSource.RUM_VIEW_ERROR.getName()))
                            {
                                if (dataSource.getString("sub.category", "").equalsIgnoreCase("rum.view.error.drill.down"))
                                {
                                    composeDrillDownResponse(rows.getJsonObject(index), composedResult);
                                }
                                else
                                {
                                    composeResponse(rows.getJsonObject(index), rumSession, eventType);
                                }
                            }
                            else if (category.equalsIgnoreCase(VisualizationDataSource.RUM_VIEW_LONG_TASK.getName()))
                            {
                                if (dataSource.getString("sub.category", "").equalsIgnoreCase("rum.view.long.task.drill.down"))
                                {
                                    composeDrillDownResponse(rows.getJsonObject(index), composedResult);
                                }
                                else
                                {
                                    composeResponse(rows.getJsonObject(index), rumSession, eventType);
                                }
                            }
                            else if (category.equalsIgnoreCase("rum.session.time.spent"))
                            {
                                composeSessionTimestampResponse(rows.getJsonObject(index), rumSession);
                            }
                            else if (category.equalsIgnoreCase("rum.session.drill.down"))
                            {
                                composeDrillDownResponse(rows.getJsonObject(index), composedResult);
                            }
                            else if (category.equalsIgnoreCase("rum.search.event"))
                            {
                                composeSessionDrillDownResponse(rows.getJsonObject(index), composedResult, RUMConstant.convertTime(context.getLong("rum.view.session.start.time", 0L), TimeUnit.MILLISECONDS, TimeUnit.SECONDS));
                            }
                        }

                        if (eventType != null && !dataSource.containsKey("sub.category"))
                        {
                            composeTimeSeriesResponse(rows, context, eventType);
                        }

                        var sessionDetails = rumSession.getSessionDetails();

                        for (var session : rumSession.getSessionDetails().keySet())
                        {
                            var sessionDetail = sessionDetails.get(session);

                            var columns = context.getJsonArray("visualization.extra.columns", new JsonArray());

                            if (!columns.isEmpty())
                            {
                                for (var index = 0; index < columns.size(); index++)
                                {
                                    var column = columns.getString(index);

                                    ((JsonArray) composedResult.getMap().computeIfAbsent(column, value -> new JsonArray())).add(sessionDetail.containsKey(column) ? sessionDetail.getValue(column) : EMPTY_VALUE);
                                }
                            }
                            else
                            {
                                for (var column : sessionDetail.getMap().keySet())
                                {
                                    ((JsonArray) composedResult.getMap().computeIfAbsent(column, value -> new JsonArray())).add(sessionDetail.getValue(column));
                                }
                            }
                        }
                    }
                }
            }

            if (!composedResult.isEmpty())
            {
                if (eventType != null) composedResult.remove(eventType.getAttribute());

                if ((context.getString(VisualizationConstants.VISUALIZATION_CATEGORY).equalsIgnoreCase(VisualizationConstants.VisualizationCategory.TOP_N.getName()) || context.getString(VisualizationConstants.VISUALIZATION_CATEGORY).equalsIgnoreCase(VisualizationConstants.VisualizationCategory.HISTOGRAM.getName()) || context.getString(VisualizationConstants.VISUALIZATION_CATEGORY).equalsIgnoreCase(VisualizationCategory.STREAM.getName())) && !context.getString(VisualizationConstants.VISUALIZATION_TYPE).equalsIgnoreCase(VisualizationConstants.VisualizationCategory.GRID.getName()))
                {
                    if (dataSource.containsKey("sub.category"))
                    {
                        Bootstrap.vertx().eventBus().publish(EventBusConstants.EVENT_DATASTORE_QUERY_RESPONSE, CodecUtil.compress(VisualizationConstants.packGridResult(composedResult.put(QUERY_PROGRESS, queryProgress), VisualizationConstants.VisualizationCategoryOrdinal.VISUALIZATION_GRID.ordinal(), queryId, subQueryId).getBytes()));
                    }
                    else
                    {
                        composeResult(queryTicks.computeIfAbsent(queryId, value -> new TreeMap<>()), context, queryIntervals.get(queryId), 50, dataSource.getString(CATEGORY), eventType);

                        composeAttributeResult(rumSessions.get(queryId), context, 50);

                        Bootstrap.vertx().eventBus().publish(EventBusConstants.EVENT_DATASTORE_QUERY_RESPONSE, CodecUtil.compress(VisualizationConstants.packGridResult(composedResult.put(QUERY_PROGRESS, queryProgress), VisualizationConstants.VisualizationCategoryOrdinal.VISUALIZATION_GRID.ordinal(), queryId, subQueryId).getBytes()));

                        if (queryProgress == 100)
                        {
                            cleanUp(queryId);
                        }
                    }
                }
                else
                {
                    Bootstrap.vertx().eventBus().publish(EventBusConstants.EVENT_DATASTORE_QUERY_RESPONSE, CodecUtil.compress(VisualizationConstants.packGridResult(composedResult.put(QUERY_PROGRESS, queryProgress), VisualizationConstants.VisualizationCategoryOrdinal.VISUALIZATION_GRID.ordinal(), queryId, subQueryId).getBytes()));
                }
            }
            else
            {
                //send back empty result

                VisualizationConstants.send(visualizationCategory, VisualizationConstants.VisualizationCategory.GRID.getName(), null, String.format(ErrorMessageConstants.VISUALIZATION_QUERY_FAILED, "Preview Widget", ErrorMessageConstants.INVALID_NO_DATA_FOUND), queryId, subQueryId, logger, EVENT_DATASTORE_QUERY_RESPONSE);
            }
        }
        catch (Exception exception)
        {
            logger.error(exception);
        }
    }

    /**
     * Composes session-level response data by aggregating RUM events.
     * Updates session statistics and event counts based on the event type.
     *
     * @param row the row data from the query result
     * @param rumSession the RUM session object to update
     * @param rumType the RUM event type
     */
    private void composeSessionResponse(JsonObject row, RumSession rumSession, EventType rumType)
    {
        try
        {
            var sessionId = row.getString(rumType.getId() + CARET_SEPARATOR + GlobalConstants.VALUE);

            var view = row.getString(RUMConstant.RUM_VIEW_NAME + CARET_SEPARATOR + GlobalConstants.VALUE, EMPTY_VALUE);

            var sessionType = row.getString(RUMConstant.RUM_VIEW_SESSION_TYPE + CARET_SEPARATOR + GlobalConstants.VALUE, EMPTY_VALUE);

            var createdTimestamp = row.getLong(RUMConstant.RUM_VIEW_CREATED_TIME_MS + CARET_SEPARATOR + VALUE, 0L);

            var sessionTimestamp = RUMConstant.convertTime(row.getLong(TIMESTAMP, 0L), TimeUnit.MILLISECONDS, TimeUnit.MICROSECONDS);

            var smallestTimestampBySessions = rumSession.getSmallestTimestampBySessions();

            var largestTimestampBySessions = rumSession.getLargestTimestampBySessions();

            var smallestTimestamp = smallestTimestampBySessions.computeIfAbsent(sessionId, value -> sessionTimestamp);

            var largestTimestamp = largestTimestampBySessions.computeIfAbsent(sessionId, value -> sessionTimestamp);

            var timeSpent = sessionTimestamp - RUMConstant.convertTime(createdTimestamp, TimeUnit.MILLISECONDS, TimeUnit.MICROSECONDS);

            var sessionDetail = rumSession.getSessionDetails().computeIfAbsent(sessionId, value -> new JsonObject()
                    .put(RUMConstant.RUM_VIEW_SESSION_ID, sessionId)
                    .put(TIMESTAMP, createdTimestamp)
                    .put(RUMConstant.RUM_VIEW_INITIAL_VIEW, view)
                    .put(RUMConstant.RUM_VIEW_NAME, view)
                    .put(RUMConstant.RUM_VIEW_TIME_SPENT_US, timeSpent)
                    .put(RUMConstant.RUM_VIEW_SESSION_TYPE, sessionType));

            extractEvent(row.getBuffer(rumType.getAttribute() + CARET_SEPARATOR + GlobalConstants.VALUE), sessionId, rumSession);

            if (sessionDetail.getLong(RUMConstant.RUM_VIEW_TIME_SPENT_US, 0L) < timeSpent)
            {
                sessionDetail.put(RUMConstant.RUM_VIEW_TIME_SPENT_US, timeSpent);
            }

            if (sessionTimestamp < smallestTimestamp)
            {
                // set initial view name if session has the smallest timestamp
                smallestTimestampBySessions.put(sessionId, sessionTimestamp);

                sessionDetail.put(RUMConstant.RUM_VIEW_INITIAL_VIEW, view)
                        .put(RUMConstant.RUM_VIEW_SESSION_TYPE, sessionType);
            }

            if (sessionTimestamp > largestTimestamp)
            {
                // set view name if session has the largest timestamp
                largestTimestampBySessions.put(sessionId, sessionTimestamp);

                sessionDetail.put(RUMConstant.RUM_VIEW_NAME, view);
            }

            var errors = sessionDetail.getInteger(RUMConstant.RUM_VIEW_ERRORS, 0) + row.getInteger(RUMConstant.RUM_VIEW_ERRORS + CARET_SEPARATOR + GlobalConstants.VALUE, 0);

            var actions = sessionDetail.getInteger(RUMConstant.RUM_VIEW_ACTIONS, 0) + row.getInteger(RUMConstant.RUM_VIEW_ACTIONS + CARET_SEPARATOR + GlobalConstants.VALUE, 0);

            var frustrations = sessionDetail.getInteger(RUMConstant.RUM_VIEW_FRUSTRATIONS, 0) + row.getInteger(RUMConstant.RUM_VIEW_FRUSTRATIONS + CARET_SEPARATOR + GlobalConstants.VALUE, 0);

            var loadingTime = sessionDetail.getLong("rum.view.loading.time.us.sum", 0L) +  row.getLong(RUMConstant.RUM_VIEW_LOADING_TIME_US + CARET_SEPARATOR + GlobalConstants.VALUE, 0L);

            var firstContentfulPaint = sessionDetail.getLong("rum.view.first.contentful.paint.us.sum", 0L) +  row.getLong(RUMConstant.RUM_VIEW_FIRST_CONTENTFUL_PAINT_US + CARET_SEPARATOR + GlobalConstants.VALUE, 0L);

            var largestContentfulPaint = sessionDetail.getLong("rum.view.largest.contentful.paint.us.sum", 0L) +  row.getLong(RUMConstant.RUM_VIEW_LARGEST_CONTENTFUL_PAINT_US + CARET_SEPARATOR + GlobalConstants.VALUE, 0L);

            var interactionToNextPaint = sessionDetail.getLong("rum.view.interaction.to.next.paint.us.sum", 0L) +  row.getLong(RUMConstant.RUM_VIEW_INTERACTION_TO_NEXT_PAINT_US + CARET_SEPARATOR + GlobalConstants.VALUE, 0L);

            var cumulativeLayoutShift = sessionDetail.getFloat("rum.view.cumulative.layout.shift.sum", 0f) +  row.getFloat(RUMConstant.RUM_VIEW_CUMULATIVE_LAYOUT_SHIFT + CARET_SEPARATOR + GlobalConstants.VALUE, 0f);

            sessionDetail.put("records", sessionDetail.getInteger("records", 0) + 1);

            rumSession.addView(sessionId, row.getString(RUMConstant.RUM_VIEW_ID + CARET_SEPARATOR + GlobalConstants.VALUE, EMPTY_VALUE));

            sessionDetail.put(RUMConstant.RUM_VIEW_ERRORS, errors)
                    .put(RUMConstant.RUM_VIEW_ACTIONS, actions)
                    .put(RUMConstant.RUM_VIEW_FRUSTRATIONS, frustrations)
                    .put(RUMConstant.RUM_VIEWS, rumSession.getViews(sessionId).size())
                    .put("rum.view.loading.time.us.sum", loadingTime)
                    .put(RUMConstant.RUM_VIEW_LOADING_TIME_US, loadingTime / sessionDetail.getDouble("records", 1d))
                    .put("rum.view.first.contentful.paint.us.sum", firstContentfulPaint)
                    .put(RUMConstant.RUM_VIEW_FIRST_CONTENTFUL_PAINT_US, firstContentfulPaint / sessionDetail.getDouble("records", 1d))
                    .put("rum.view.largest.contentful.paint.us.sum", largestContentfulPaint)
                    .put(RUMConstant.RUM_VIEW_LARGEST_CONTENTFUL_PAINT_US, largestContent

ULATIVE_LAYOUT_SHIFT + CARET_SEPARATOR + GlobalConstants.VALUE, 0f);

            sessionDetail.put("records", sessionDetail.getInteger("records", 0) + 1);

            rumSession.addView(sessionId, row.getString(RUMConstant.RUM_VIEW_ID + CARET_SEPARATOR + GlobalConstants.VALUE, EMPTY_VALUE));

            sessionDetail.put(RUMConstant.RUM_VIEW_ERRORS, errors)
                    .put(RUMConstant.RUM_VIEW_ACTIONS, actions)
                    .put(RUMConstant.RUM_VIEW_FRUSTRATIONS, frustrations)
                    .put(RUMConstant.RUM_VIEWS, rumSession.getViews(sessionId).size())
                    .put("rum.view.loading.time.us.sum", loadingTime)
                    .put(RUMConstant.RUM_VIEW_LOADING_TIME_US, loadingTime / sessionDetail.getDouble("records", 1d))
                    .put("rum.view.first.contentful.paint.us.sum", firstContentfulPaint)
                    .put(RUMConstant.RUM_VIEW_FIRST_CONTENTFUL_PAINT_US, firstContentfulPaint / sessionDetail.getDouble("records", 1d))
                    .put("rum.view.largest.contentful.paint.us.sum", largestContentfulPaint)
                    .put(RUMConstant.RUM_VIEW_LARGEST_CONTENTFUL_PAINT_US, largestContentfulPaint / sessionDetail.getDouble("records", 1d))
                    .put("rum.view.interaction.to.next.paint.us.sum", interactionToNextPaint)
                    .put(RUMConstant.RUM_VIEW_INTERACTION_TO_NEXT_PAINT_US, interactionToNextPaint / sessionDetail.getDouble("records", 1d))
                    .put("rum.view.cumulative.layout.shift.sum", cumulativeLayoutShift)
                    .put(RUMConstant.RUM_VIEW_CUMULATIVE_LAYOUT_SHIFT, cumulativeLayoutShift / sessionDetail.getDouble("records", 1d));

            for (var column : row.getMap().entrySet())
            {
                var key = column.getKey().replace(CARET_SEPARATOR + GlobalConstants.VALUE, EMPTY_VALUE);

                if (!sessionDetail.containsKey(key))
                {
                    sessionDetail.put(key, column.getValue());
                }
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

    private void composeSessionDrillDownResponse(JsonObject row, JsonObject composedResult, long sessionStartTime)
    {
        try
        {
            var relativeTime = RUMConstant.convertTime(CommonUtil.getLong(row.getLong(TIMESTAMP)), TimeUnit.MILLISECONDS, TimeUnit.SECONDS) - sessionStartTime;

            if (relativeTime < 0) relativeTime = 0;

            for (var column : row.getMap().keySet())
            {
                ((JsonArray) composedResult.getMap().computeIfAbsent(column, value -> new JsonArray())).add(row.getValue(column));
            }

            ((JsonArray) composedResult.getMap().computeIfAbsent("rum.search.event.relative.time.us^value", value -> new JsonArray())).add(RUMConstant.convertTime(relativeTime, TimeUnit.SECONDS, TimeUnit.MICROSECONDS));
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

    /**
     * Composes generic response data for RUM events.
     * Extracts event attributes and populates session details.
     *
     * @param row the row data from the query result
     * @param rumSession the RUM session object to update
     * @param rumType the RUM event type
     */
    private void composeResponse(JsonObject row, RumSession rumSession, EventType rumType)
    {
        try
        {
            var viewId = row.getString(rumType.getId() + CARET_SEPARATOR + GlobalConstants.VALUE);

            var sessionDetails = rumSession.getSessionDetails();

            var sessionDetail = sessionDetails.computeIfAbsent(viewId, value -> new JsonObject());

            var attributes = extractEvent(row.getBuffer( rumType.getAttribute() + CARET_SEPARATOR + GlobalConstants.VALUE), viewId, rumSession);

            for (var column : row.getMap().entrySet())
            {
                var key = column.getKey().replace(CARET_SEPARATOR + GlobalConstants.VALUE, EMPTY_VALUE);

                if (!sessionDetail.containsKey(key))
                {
                    sessionDetail.put(key, column.getValue());
                }
            }

            populateSessionDetails(attributes, sessionDetail);
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

    private void populateSessionDetails(JsonObject data, JsonObject sessionDetail)
    {
        for (var key : data.getMap().keySet())
        {
            if (!sessionDetail.containsKey(key)) sessionDetail.put(key, data.getValue(key));
        }
    }

    /**
     * Composes drill-down response by extracting and formatting row data.
     * Adds all row columns to the composed result.
     *
     * @param row the row data from the query result
     * @param composedResult the result object to populate
     */
    private void composeDrillDownResponse(JsonObject row, JsonObject composedResult)
    {
        try
        {
            for (var column : row.getMap().keySet())
            {
                ((JsonArray) composedResult.getMap().computeIfAbsent(column, value -> new JsonArray())).add(row.getValue(column));
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

    /**
     * Composes session timestamp response by tracking smallest and largest timestamps.
     * Calculates total time spent in the session.
     *
     * @param row the row data from the query result
     * @param rumSession the RUM session object to update
     */
    private void composeSessionTimestampResponse(JsonObject row, RumSession rumSession)
    {
        try
        {
            var sessionDetail = rumSession.getSessionDetails().computeIfAbsent("1", value -> new JsonObject());

            var createdTimestamp = row.getLong(RUMConstant.RUM_VIEW_CREATED_TIME_MS + CARET_SEPARATOR + VALUE, 0L);

            var sessionTimestamp = row.getLong(TIMESTAMP, 0L);

            var timeSpent = sessionTimestamp - createdTimestamp;

            if (sessionDetail.getLong(RUMConstant.RUM_VIEW_TIME_SPENT_MS, 0L) < timeSpent)
            {
                sessionDetail.put(RUMConstant.RUM_VIEW_TIME_SPENT_MS, timeSpent);
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

    /**
     * Extracts RUM event data from a binary buffer.
     * Decodes ordinal-encoded event attributes into a JsonObject.
     *
     * @param buffer the binary buffer containing encoded event data
     * @param logger the logger for error reporting
     * @return JsonObject containing decoded event attributes
     */
    public JsonObject extractEvent(Buffer buffer, Logger logger)
    {
        var event = new JsonObject();

        var position = 0;

        try
        {
            for (var j = 0; j < buffer.length(); j = position)
            {
                try
                {
                    var ordinal = buffer.getIntLE(position);

                    if (EventOrdinalCacheStore.getStore().getValue(ordinal) != null)
                    {
                        position += 4;
                    }

                    else
                    {
                        position += 2;

                        ordinal = buffer.getIntLE(position);

                        position += 4;
                    }

                    // substring() uses less resources compare to split().
                    var item = EventOrdinalCacheStore.getStore().getValue(ordinal);

                    var key = item.substring(item.indexOf(SEPARATOR)+SEPARATOR.length());

                    var length = buffer.getShortLE(position);

                    position += 2;

                    var value = buffer.getString(position, position + length);

                    var category = DatastoreConstants.getDataCategory(false, key, value);

                    if (category == DatastoreConstants.DataCategory.STRING.getName())
                    {
                        // string
                        event.put(key, value);
                    }
                    else if (category == DatastoreConstants.DataCategory.NUMERIC.getName())
                    {
                        // numeric
                        event.put(key, CommonUtil.getLong(value));
                    }
                    else
                    {
                        // float
                        event.put(key, CommonUtil.getDouble(value));
                    }

                    position += length;
                }

                catch (Exception exception)
                {
                    logger.error(exception);

                    break;
                }
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }

        return event;
    }

    /**
     * Composes time series result data from tick data.
     * Publishes histogram chart results to the event bus.
     *
     * @param ticks the time series tick data with unique IDs
     * @param context the query context
     * @param intervalIndex the interval index for histogram bucketing
     * @param progress the query progress percentage
     * @param category the visualization category
     * @param rumType the RUM event type
     */
    private void composeResult(TreeMap<Long, Set<String>> ticks, JsonObject context, int intervalIndex, int progress, String category, EventType rumType)
    {
        try
        {
            if (!ticks.isEmpty())
            {
                var tickCount = new JsonObject();

                tickCount.put(TIME_STAMP, new JsonArray()).put(rumType.getCounter(), new JsonArray());

                for (var entry : ticks.entrySet())
                {
                    tickCount.getJsonArray(TIME_STAMP).add(entry.getKey());

                    tickCount.getJsonArray(rumType.getCounter()).add(entry.getValue());
                }

                tickCount.put(QUERY_PROGRESS, progress);

                vertx.eventBus().publish(EventBusConstants.EVENT_DATASTORE_QUERY_RESPONSE, CodecUtil.compress(VisualizationConstants.packChartResult(tickCount, VisualizationCategoryOrdinal.VISUALIZATION_HISTOGRAM.ordinal(), context.getLong(VisualizationConstants.QUERY_ID), context.getLong(SUB_QUERY_ID)).getBytes()));
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
        finally
        {
            if (progress >= 100)
            {
                queryTicks.remove(context.getLong(QUERY_ID));

                queryIntervals.remove(context.getLong(QUERY_ID));

                uniqueIds.remove(context.getLong(QUERY_ID));

                if (CommonUtil.traceEnabled())
                {

                    LOGGER.trace("removing query context for event history query " + context.getLong(QUERY_ID));
                }
            }

            else
            {
                queryIntervals.put(context.getLong(QUERY_ID), intervalIndex);
            }
        }
    }

    /**
     * Composes attribute result data from RUM session attributes.
     * Publishes aggregated attribute counts to the event bus.
     *
     * @param rumSession the RUM session containing attribute data
     * @param context the query context
     * @param progress the query progress percentage
     */
    private void composeAttributeResult(RumSession rumSession, JsonObject context, int progress)
    {
        var result = new JsonObject();

        var attributes = rumSession.getAttributes();

        var attributeCount = rumSession.getAttributeCount();

        attributes.keySet().forEach(key ->
        {
            try
            {
                var val = new JsonObject();

                attributes.get(key).forEach(attribute ->
                {
                    var ids = attributeCount.get(key + COLUMN_SEPARATOR + attribute);

                    val.put(attribute + COLUMN_SEPARATOR + ids.size(), ids);
                });

                ((JsonArray) result.getMap().computeIfAbsent(key, value -> new JsonArray())).add(val.encode());
            }
            catch (Exception exception)
            {
                LOGGER.error(exception);
            }
        });

        Bootstrap.vertx().eventBus().publish(EventBusConstants.EVENT_DATASTORE_QUERY_RESPONSE, CodecUtil.compress(VisualizationConstants.packGridResult(result.put(QUERY_PROGRESS, progress), VisualizationConstants.VisualizationCategoryOrdinal.VISUALIZATION_TRACE_HISTORY.ordinal(), context.getLong(QUERY_ID), context.getLong(SUB_QUERY_ID)).getBytes()));
    }

    /**
     * Composes histogram response by aggregating ticks into time intervals.
     * Rounds timestamps to the specified interval and merges unique IDs.
     *
     * @param ticks the original tick data
     * @param index the interval index for bucketing
     * @return aggregated tick data with rounded timestamps
     */
    private TreeMap<Long, Set<String>> composeHistogramResponse(TreeMap<Long, Set<String>> ticks, int index)
    {
        var result = new TreeMap<Long, Set<String>>();

        try
        {
            var iterator = ticks.entrySet().iterator();

            while (iterator.hasNext())
            {
                var entry = iterator.next();

                var millis = DateTimeUtil.roundOffSeconds(entry.getKey(), INTERVALS.getInteger(index));

                var resultTick = result.getOrDefault(millis, new HashSet<>());

                resultTick.addAll(entry.getValue());

                result.put(millis, resultTick);

                iterator.remove();
            }
        }

        catch (Exception exception)
        {
            LOGGER.error(exception);
        }

        return result;
    }

    /**
     * Processes RUM event attributes and adds them to the session.
     * Iterates through attributes and adds each key-value pair to the session.
     *
     * @param id the session or view ID
     * @param attributes the attributes to process
     * @param session the RUM session to update
     */
    private void processAttributes(String id, JsonObject attributes, RumSession session)
    {
        for (var key : attributes.getMap().keySet())
        {
            if (attributes.getValue(key) != null && !attributes.getValue(key).toString().isEmpty())
            {
                addAttribute(key, CommonUtil.getString(attributes.getValue(key)), id, session);
            }
        }
    }

    /**
     * Adds a single attribute to the RUM session.
     * Updates both the attribute set and attribute count for the session.
     *
     * @param key the attribute key
     * @param value the attribute value
     * @param sessionId the session ID
     * @param rumSession the RUM session to update
     */
    private void addAttribute(String key, String value, String sessionId, RumSession rumSession)
    {
        rumSession.addAttribute(key, value);

        rumSession.addAttributeCount(key, value, sessionId);
    }

    /**
     * Cleans up query data and RUM session data for the given query ID.
     * Removes all tracking data and session information.
     *
     * @param queryId the query ID to clean up
     */
    private void cleanUp(long queryId)
    {
        try
        {
            var rumSession = rumSessions.get(queryId);

            if (rumSession != null)
            {
                LOGGER.info(String.format("Removing rum session for query id %s", queryId));

                rumSession.cleanUp();
            }

            queryIntervals.remove(queryId);

            queryTicks.remove(queryId);
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

    /**
     * Composes time series response from query result rows.
     * Processes rows and aggregates unique IDs into time-based ticks.
     *
     * @param rows the query result rows
     * @param context the query context
     * @param rumType the RUM event type
     */
    public void composeTimeSeriesResponse(JsonArray rows, JsonObject context, EventType rumType)
    {
        try
        {
            if (rows != null)
            {
                var queryId = context.getLong(QUERY_ID);

                var queryData = initializeQueryData(queryId);

                var valid = validRowsForTimeSeries(rows, queryData, rumType);

                if (valid)
                {
                    queryTicks.get(queryId).putAll(queryData.ticks);
                }
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

    /**
     * Extracts event data from buffer and processes attributes.
     * Decodes binary event data and adds attributes to the RUM session.
     *
     * @param buffer the binary buffer containing event data
     * @param id the session or view ID
     * @param rumSession the RUM session to update
     */
    private JsonObject extractEvent(Buffer buffer, String id, RumSession rumSession)
    {
        var event = new JsonObject();

        try
        {
            if (buffer != null)
            {
                event = extractEvent(buffer, LOGGER);

                processAttributes(id, event, rumSession);
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }

        return event;
    }

    /**
     * Initializes query data structures for time series processing.
     * Sets up ticks, intervals, and unique ID tracking for the query.
     *
     * @param queryId the query ID
     * @return initialized QueryData object
     */
    private QueryData initializeQueryData(Long queryId)
    {
        queryIntervals.putIfAbsent(queryId, 0);

        uniqueIds.putIfAbsent(queryId, new HashSet<>());

        var ticks = queryTicks.computeIfAbsent(queryId, value -> new TreeMap<>());

        var intervalIndex = queryIntervals.get(queryId);

        return new QueryData(ticks, intervalIndex, queryId);
    }

    /**
     * Validates and processes all rows for time series data.
     * Checks each row and adds valid data to the query ticks.
     *
     * @param rows the query result rows
     * @param queryData the query data context
     * @param rumType the RUM event type
     * @return true if at least one valid row was processed
     */
    private boolean validRowsForTimeSeries(JsonArray rows, QueryData queryData, EventType rumType)
    {
        var valid = false;

        for (var i = 0; i < rows.size(); i++)
        {
            var row = rows.getJsonObject(i);

            if (validRow(row, queryData, rumType))
            {
                valid = true;
            }
        }

        return valid;
    }

    /**
     * Validates a single row and adds it to time series ticks if valid.
     * Checks for required fields and adds unique IDs to the appropriate time bucket.
     *
     * @param row the row to validate
     * @param queryData the query data context
     * @param rumType the RUM event type
     * @return true if the row is valid and processed
     */
    private boolean validRow(JsonObject row, QueryData queryData, EventType rumType)
    {
        var id = row.getString(rumType.getId() + CARET_SEPARATOR + GlobalConstants.VALUE);

        if (!row.containsKey(TIMESTAMP) || id == null)
        {
            return false;
        }

        try
        {
            var millis = DateTimeUtil.roundOffSeconds(row.getLong(TIMESTAMP), INTERVALS.getInteger(queryData.intervalIndex));

            var tick = queryData.ticks.getOrDefault(millis, new HashSet<>());

            if (uniqueIds.containsKey(queryData.queryId) && !uniqueIds.get(queryData.queryId).contains(id))
            {
                addUniqueIdToTick(queryData.queryId, id, tick, millis, queryData);
            }

            return true;
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);

            return false;
        }
    }

    /**
     * Adds a unique ID to the time series tick data.
     * Tracks the ID globally and adds it to the specific time bucket.
     *
     * @param queryId the query ID
     * @param id the unique ID to add
     * @param tick the tick set to add the ID to
     * @param millis the timestamp for the tick
     * @param queryData the query data context
     */
    private void addUniqueIdToTick(Long queryId, String id, Set<String> tick, Long millis, QueryData queryData)
    {
        uniqueIds.get(queryId).add(id);

        tick.add(id);

        queryData.ticks.put(millis, tick);

        handleValidTickData(queryData);
    }

