    /**
     * Handles tick data when it exceeds the maximum bar chart limit.
     * Increases the interval index and re-aggregates ticks into larger time buckets.
     *
     * @param queryData the query data context
     */
    private void handleValidTickData(QueryData queryData)
    {
        if (queryData.ticks.size() > MAX_BAR_CHART_LIMIT)
        {
            queryData.intervalIndex += 1;

            queryData.ticks = composeHistogramResponse(queryData.ticks, queryData.intervalIndex);

            queryIntervals.put(queryData.queryId, queryData.intervalIndex);
        }
    }

