    public static class RumSession
    {
        private final Map<String, Long> smallestTimestampBySessions; // session -> timestamp...

        private final Map<String, Long> largestTimestampBySessions; // session -> timestamp...

        private final Map<String, JsonObject> sessionDetails;

        private final Map<String, Set<String>> views; // session -> view.id

        private final Map<String, Set<String>> attributes; // view.name -> ["monitors", "groups", "dashboard"]

        private final Map<String, Set<String>> attributeCount; // view.name§monitors -> ["session.id.1", "session.id.2",...,"session.id.n"]

        public RumSession()
        {
            smallestTimestampBySessions = new HashMap<>();

            largestTimestampBySessions = new HashMap<>();

            sessionDetails = new HashMap<>();

            views = new HashMap<>();

            attributes = new HashMap<>();

            attributeCount = new HashMap<>();
        }

        public Map<String, Long> getSmallestTimestampBySessions()
        {
