        {
            return sessionDetails;
        }

        public Map<String, Long> getLargestTimestampBySessions()
        {
            return largestTimestampBySessions;
        }

        public void addView(String sessionId, String id)
        {
            if (!sessionId.isEmpty())
            {
                views.computeIfAbsent(sessionId, key -> new HashSet<>()).add(id);
            }
        }

        public Set<String> getViews(String id)
        {
            return views.getOrDefault(id, new HashSet<>());
        }

        public void addAttribute(String name, String value)
        {
            if (!name.isEmpty())
            {
                attributes.computeIfAbsent(name, key -> new HashSet<>()).add(value);
            }
        }

        public Map<String, Set<String>> getAttributes()
        {
            return attributes;
        }

        public void addAttributeCount(String name, String value, String sessionId)
        {
            if (name != null && !name.isEmpty())
            {
                attributeCount.computeIfAbsent(name + COLUMN_SEPARATOR + value, key -> new HashSet<>()).add(sessionId);
            }
        }

        public Map<String, Set<String>> getAttributeCount()
        {
            return attributeCount;
        }

        public void cleanUp()
        {
            smallestTimestampBySessions.clear();

            largestTimestampBySessions.clear();

            sessionDetails.clear();

            views.clear();

            attributes.clear();

            attributeCount.clear();
        }

        public void cleanData()
        {
            smallestTimestampBySessions.clear();

            largestTimestampBySessions.clear();

            sessionDetails.clear();

            views.clear();
        }
    }

