        public static EventType getType(String type)
        {
            if (type.equalsIgnoreCase(VisualizationConstants.VisualizationDataSource.RUM_VIEW.getName()))
            {
                return new View();
            }
            else if (type.equalsIgnoreCase(VisualizationConstants.VisualizationDataSource.RUM_SESSION.getName()))
            {
                return new Session();
            }
            else if (type.equalsIgnoreCase(VisualizationConstants.VisualizationDataSource.RUM_VIEW_RESOURCE.getName()))
            {
                return new Resource();
            }
            else if (type.equalsIgnoreCase(VisualizationConstants.VisualizationDataSource.RUM_VIEW_ACTION.getName()))
            {
                return new Action();
            }
            else if (type.equalsIgnoreCase(VisualizationConstants.VisualizationDataSource.RUM_VIEW_ERROR.getName()))
            {
                return new Error();
            }
            else if (type.equalsIgnoreCase(VisualizationConstants.VisualizationDataSource.RUM_VIEW_LONG_TASK.getName()))
            {
                return new LongTask();
            }

            return null;
        }
