                else if (visualizationDataSource.getString(CATEGORY).equalsIgnoreCase(VisualizationDataSource.RUM_METRIC.getName()))
                {
                    metricCategory = false;

                    netRouteCategory = false;

                    traceCategory = false;

                    rumCategory = true;

                    Map<String, Object> qualifiedEntities;

                    qualifiedEntities = qualifyEntities(false, visualizationDataPoint, user.getLong(ID), qualifiedObjects, filteredGroupEntities, filteredTagEntities, LOGGER, false, DatastoreConstants.PluginId.RUM_POLICY_DURATION_METRIC.getName());

                    if (qualifiedEntities != null && !qualifiedEntities.isEmpty())
                    {
                        setEntities(visualizationDataPoint, qualifiedEntities, entities, plugins, visualizationDataPoints);
                    }
                }

                else if (visualizationDataSource.getString(CATEGORY).equalsIgnoreCase(VisualizationConstants.VisualizationDataSource.NETWORK_CONFIG.getName()))
                {
                    metricCategory = false;

                    netRouteCategory = false;

                    traceCategory = false;

                    Map<String, Object> qualifiedEntities;

                    qualifiedEntities = qualifyEntities(false, visualizationDataPoint, user.getLong(ID), qualifiedObjects, filteredGroupEntities, filteredTagEntities, LOGGER, false, DatastoreConstants.PluginId.POLICY_NETWORK_CONFIG.getName());

                    if (qualifiedEntities != null && !qualifiedEntities.isEmpty())
                    {
                        setEntities(visualizationDataPoint, qualifiedEntities, entities, plugins, visualizationDataPoints);
                    }
                }
                else
                {
                    var qualifiedEntities = qualifyEntities(false, visualizationDataPoint, user.getLong(ID), qualifiedObjects, filteredGroupEntities, filteredTagEntities, LOGGER, false, DatastoreConstants.PluginId.METRIC_POLICY_DURATION_METRIC.getName());

                    if (qualifiedEntities != null && !qualifiedEntities.isEmpty())
                    {
                        setEntities(visualizationDataPoint, qualifiedEntities, entities, plugins, visualizationDataPoints);
                    }
                }
            }
        }

        applyFilter(VisualizationDataSource.PERFORMANCE_METRIC.getName(), event, true, visualizationDataSource, severities, policies, entities.keySet());

