/**
 * Manages RUM (Real User Monitoring) history visualization queries.
 * Handles query queuing, execution, progress tracking, and result processing.
 */
public class VisualizationRUMHistoryManager extends AbstractVerticle
{
    private static final Logger LOGGER = new Logger(VisualizationRUMHistoryManager.class, GlobalConstants.MOTADATA_VISUALIZATION, "Visualization RUM History Manager");

    private final Map<Long, Map<Long, String>> queryStatuses = new HashMap<>();//queryId along with subqueryIds and status

    private final Map<Long, JsonObject> subQueries = new HashMap<>(); //subquery context

    private final JsonObject eventColumns = new JsonObject();

