package com.mindarray.util;

import com.mindarray.Bootstrap;
import com.mindarray.GlobalConstants;
import io.vertx.core.Future;
import io.vertx.core.Promise;
import io.vertx.core.buffer.Buffer;

import java.nio.charset.StandardCharsets;
import java.nio.file.Paths;

import static com.mindarray.GlobalConstants.*;

/**
 * Utility class for managing file-based shutdown mechanisms on Windows systems.
 * <p>
 * This class provides a cross-process shutdown coordination mechanism specifically designed
 * for Windows environments where multiple Motadata processes need to be gracefully terminated.
 * It implements a file-based signaling system that allows external processes, services, or
 * system administrators to trigger controlled application shutdown.
 * <p>
 * <b>Key Features:</b>
 * <ul>
 *   <li>File-based shutdown watcher that monitors for shutdown signals</li>
 *   <li>Periodic monitoring with configurable intervals (default: 1 second)</li>
 *   <li>Asynchronous file operations using Vert.x file system API</li>
 *   <li>Graceful shutdown coordination across multiple processes</li>
 *   <li>Windows-specific implementation with OS validation</li>
 * </ul>
 * <p>
 * <b>Workflow:</b>
 * <ol>
 *   <li>Initialize shutdown watcher using {@link #initShutdownWatcher()}</li>
 *   <li>Watcher periodically checks for shutdown file existence and content</li>
 *   <li>External processes write shutdown signal using {@link #writeShutdownSignal()}</li>
 *   <li>When "shutdown" keyword is detected, application terminates gracefully</li>
 * </ol>
 * <p>
 * <b>File Structure:</b>
 * <pre>
 * {CURRENT_DIR}/shutdown/shutdown.ctx
 * </pre>
 * <p>
 * <b>Usage Example:</b>
 * <pre>
 * // Initialize shutdown watcher (typically in Bootstrap)
 * ShutdownUtil.initShutdownWatcher(vertx);
 *
 * // Trigger shutdown from another process
 * ShutdownUtil.writeShutdownSignal(vertx)
 *     .onSuccess(v -> logger.info("Shutdown signal sent"))
 *     .onFailure(throwable -> logger.error("Failed to send shutdown signal", throwable));
 * </pre>
 * <p>
 * <b>Thread Safety:</b>
 * This class uses static methods and maintains internal state through static variables.
 * The {@code running} flag is used to coordinate shutdown across multiple timer instances.
 * <p>
 * <b>Platform Compatibility:</b>
 * Currently supports Windows systems only. Non-Windows platforms will log a debug message
 * and skip initialization.
 *
 */
public class ShutdownUtil
{
    private static final Logger LOGGER = new Logger(ShutdownUtil.class, GlobalConstants.MOTADATA_UTIL, "Shutdown Util");

    private static boolean running = Boolean.TRUE;

    private static final String DIRECTORY = GlobalConstants.CURRENT_DIR + GlobalConstants.PATH_SEPARATOR + GlobalConstants.SHUTDOWN;

    private static final String PATH = DIRECTORY + GlobalConstants.PATH_SEPARATOR + GlobalConstants.SHUTDOWN_CTX;

    /**
     * Initializes a shutdown watcher for Windows systems that monitors a shutdown file.
     * <p>
     * This method sets up a file-based shutdown mechanism specifically for Windows platforms.
     * It creates a periodic timer that checks for the existence and content of a shutdown file
     * every second. When the shutdown file contains the "shutdown" keyword, it triggers
     * application termination.
     * <p>
     * The watcher performs the following operations:
     * 1. Validates that the system is running on Windows (returns early if not)
     * 2. Cleans up any existing shutdown file from previous runs
     * 3. Creates the shutdown directory if it doesn't exist
     * 4. Sets up a periodic timer (1-second interval) to monitor the shutdown file
     * 5. Cancels the timer and stops monitoring when the running flag is set to false
     * <p>
     * This mechanism allows external processes or services to trigger graceful shutdown
     * by writing the "shutdown" keyword to the monitored file.
     *
     */
    public static void initShutdownWatcher()
    {
        if (!OS_WINDOWS)
        {
            LOGGER.debug("Shutdown watcher is only supported on Windows");
        }
        else
        {
            try
            {
                if(Bootstrap.vertx().fileSystem().existsBlocking(DIRECTORY) && Bootstrap.vertx().fileSystem().existsBlocking(PATH))
                {
                    Bootstrap.vertx().fileSystem().deleteBlocking(PATH); //delete shutdown file if already exist
                }
            }
            catch (Exception exception)
            {
                LOGGER.error(exception);
            }

            try
            {
                Bootstrap.vertx().fileSystem().mkdirs(DIRECTORY).onComplete(result -> {

                    LOGGER.info(String.format("Watching directory %s", Paths.get(DIRECTORY).toAbsolutePath()));

                    Bootstrap.vertx().setPeriodic(1000, timerId -> {

                        if (!running)
                        {
                            Bootstrap.vertx().cancelTimer(timerId);

                            return;
                        }

                        checkShutdownFile();
                    });
                });
            }
            catch (Exception exception)
            {
                LOGGER.error(exception);
            }
        }
    }


    /**
     * Checks the shutdown file for the presence of shutdown signal and triggers application exit.
     * <p>
     * This private method is called periodically by the shutdown watcher to examine the
     * shutdown file. It performs asynchronous file operations to:
     * 1. Check if the shutdown file exists
     * 2. Read the file content if it exists
     * 3. Compare the content with the expected "shutdown" keyword
     * 4. Trigger immediate application termination (System.exit(0)) if keyword matches
     * 5. Log appropriate messages for different scenarios (file found, keyword match/mismatch)
     * <p>
     * The method uses Vert.x's asynchronous file system API with Future composition
     * to handle file operations without blocking the event loop.
     *
     */
    private static void checkShutdownFile()
    {
        try
        {
            Bootstrap.vertx().fileSystem().exists(PATH).compose(exists -> exists ? Bootstrap.vertx().fileSystem().readFile(PATH) :  Future.succeededFuture()).onSuccess(result -> {

                if (result != null)
                {
                    var content = result.toString(StandardCharsets.UTF_8);

                    if (MDB_SHUTDOWN.equals(content))
                    {
                        LOGGER.info(String.format("Shutdown keyword found.Shutting down type: %s",Bootstrap.bootstrapType()));

                        running = false;

                        System.exit(0);
                    }
                    else
                    {
                        LOGGER.info(String.format("File exists but shutdown keyword not found. Content: %s", content));
                    }
                }
            });
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

    /**
     * Writes a shutdown signal to the shutdown file to trigger application termination.
     * <p>
     * This method creates a shutdown signal by writing the "shutdown" keyword to the
     * designated shutdown file. It's designed to be called by other components
     * (particularly on Windows systems) to initiate graceful shutdown of the application.
     * <p>
     * The method performs the following operations:
     * 1. Executes file operations in a blocking context to avoid blocking the event loop
     * 2. Creates the shutdown directory if it doesn't exist
     * 3. Creates the shutdown file if it doesn't exist
     * 4. Writes the "shutdown" keyword to the file using UTF-8 encoding
     * 5. Returns a Future that completes when the write operation is successful
     * <p>
     * This method is typically called from the Bootstrap.stop() method when running
     * on Windows systems with MANAGER bootstrap type to signal other processes
     * or services to shut down gracefully.
     *
     * @return A Future<Void> that completes successfully when the shutdown signal is written,
     *         or fails with an exception if the write operation encounters an error
     */
    public static Future<Void> writeShutdownSignal()
    {
        var promise = Promise.<Void>promise();

        Bootstrap.vertx().executeBlocking(() -> {

            try
            {
                // Create directory if not exists
                if (!Bootstrap.vertx().fileSystem().existsBlocking(DIRECTORY))
                {
                    Bootstrap.vertx().fileSystem().mkdirsBlocking(DIRECTORY);

                    LOGGER.info(String.format("Directory created: %s",DIRECTORY));
                }

                if(!Bootstrap.vertx().fileSystem().existsBlocking(PATH))
                {
                    Bootstrap.vertx().fileSystem().createFileBlocking(PATH);

                    LOGGER.info(String.format("File created: %s",PATH));
                }

                Bootstrap.vertx().fileSystem().writeFileBlocking(PATH, Buffer.buffer(MDB_SHUTDOWN, StandardCharsets.UTF_8.name()));

                LOGGER.info("shutdown writing completed");

                promise.complete();
            }
            catch (Exception exception)
            {
                LOGGER.error(exception);

                promise.fail(exception);
            }

            return null;
        });

        return promise.future();
    }
}

