     *
     * @param millis The duration in milliseconds
     * @return A formatted string representing the duration
     */
    public static String millisToDuration(long millis)
    {
        // Calculate duration components
        var months = TimeUnit.MILLISECONDS.toDays(millis) / 30;
        var weeks = (TimeUnit.MILLISECONDS.toDays(millis) % 30) / 7;
        var days = (TimeUnit.MILLISECONDS.toDays(millis) % 30) % 7;
        var hours = TimeUnit.MILLISECONDS.toHours(millis) % 24;
        var minutes = TimeUnit.MILLISECONDS.toMinutes(millis) % 60;

        var result = new StringBuilder();

        // Add each non-zero component to the result
        if (months > 0) result.append(months).append(" month").append(months > 1 ? "s " : " ");
        if (weeks > 0) result.append(weeks).append(" week").append(weeks > 1 ? "s " : " ");
        if (days > 0) result.append(days).append(" day").append(days > 1 ? "s " : " ");
        if (hours > 0) result.append(hours).append(" hour").append(hours > 1 ? "s " : " ");

        // Only include minutes if there are no larger units (months, weeks, days)
        if (months <= 0 && weeks <= 0 && days <= 0 && minutes > 0)
            result.append(minutes).append(" minute").append(minutes > 1 ? "s " : " ");

        return result.toString();
    }

    /**
     * Converts a duration in milliseconds to a human-readable string.
     * <p>
     * This method breaks down the duration into months, weeks, days, hours, minutes and seconds,
     * and formats it as a string (e.g., "2 months 1 week 3 days 5 hours 3 Minutes 10 Seconds").
     * <p>
     * The method uses the following conversion rules:
     * - 30 days = 1 month
     * - 7 days = 1 week
     * - Minutes and Seconds are only included if the duration is less than a day
     *
     * @param millis The duration in milliseconds
     * @return A formatted string representing the duration
     */
    public static String millisToDurationWithSeconds(long millis)
    {
        var seconds = TimeUnit.MILLISECONDS.toSeconds(millis) % 60;

        var result = new StringBuilder(millisToDuration(millis));

        if (seconds > 0)
            result.append(seconds).append(" second").append(seconds > 1 ? "s " : " ");

        return result.toString();
    }

    /**
     * Calculates the delay in milliseconds until the next aligned time boundary for a given interval.
     * <p>
     * This method ensures that timers run at proper time boundaries regardless of when they are started.
     * For example:
     * - If interval is 2 minutes, it aligns to XX:00, XX:02, XX:04, etc.
     * - If interval is 15 minutes, it aligns to XX:00, XX:15, XX:30, XX:45
     * <p>
     * The method calculates the next boundary by:
     * 1. Getting the current time in milliseconds
     * 2. Calculating how many intervals have passed since the start of the hour
     * 3. Adding one more interval to get the next boundary
     * 4. Returning the delay until that boundary
     *
     * @param intervalMinutes The timer interval in minutes (e.g., 2, 5, 15, 30)
     * @return The delay in milliseconds until the next aligned time boundary
     */
    public static long calculateNextAlignedTimerDelay(int intervalMinutes)
    {
        var currentTimeMillis = currentMilliSeconds();

        var intervalMillis = intervalMinutes * 60_000L;

        // Calculate how many intervals have already passed since epoch
        var intervalsPassed = currentTimeMillis / intervalMillis;

        // Next boundary = start of next interval
        var nextBoundaryMillis = (intervalsPassed + 1) * intervalMillis;

        // Calculate delay until next boundary
        var delayMillis = nextBoundaryMillis - currentTimeMillis;

        // Safety check (should never be negative)
        return Math.max(delayMillis, 0);
    }

    /**
     * Helper method to check if current time is within the specified time range.
     * Handles cases where end time is before start time (spans midnight).
     *
     * @param currentTime The current time
     * @param startTime The start time of the period
     * @param endTime The end time of the period
     * @return true if current time is within the range, false otherwise
     */
    public static boolean isTimeWithinRange(LocalTime currentTime, LocalTime startTime, LocalTime endTime)
    {
        if (startTime.equals(endTime))
        {
            return false; // Invalid range
        }

        if (startTime.isBefore(endTime))
        {
            // Normal case: start time is before end time (same day)
            return !currentTime.isBefore(startTime) && !currentTime.isAfter(endTime);
        }
        else
        {
            // Special case: end time is before start time (spans midnight)
            return !currentTime.isBefore(startTime) || !currentTime.isAfter(endTime);
        }
    }


    public enum Unit
    {
        SECOND("Second"),
        MINUTE("Minute"),
        HOUR("Hour"),
        DAY("Day"),
        WEEK("Week"),
        MONTH("Month"),
        QUARTER("Quarter"),
        YEAR("Year");

        private final String name;

        Unit(String name)
        {
            this.name = name;
        }

        public String getName()
        {
            return name;
        }

        private static final Map<String, Unit> VALUES = Collections.unmodifiableMap(Arrays.stream(values())
                .collect(Collectors.toMap(Unit::getName, e -> e)));

        public static Unit valueOfName(String name)
        {
            return VALUES.get(name);
        }
    }

    public static long toSeconds(long time, String unit)
    {
        return switch (Unit.valueOfName(unit))
        {
            case SECOND -> time;
            case MINUTE -> time * 60;
            case HOUR -> time * 60 * 60;
            case DAY -> time * 24 * 60 * 60;
            case WEEK -> time * 7 * 24 * 60 * 60;
            case MONTH -> time * 30 * 24 * 60 * 60;
            case QUARTER -> time * 90 * 24 * 60 * 60;
            case YEAR -> time * 365 * 24 * 60 * 60;
        };
    }
