    /**
     * Handles IP range evaluation for filtering conditions
     * @param value The range value in format "start-end" (e.g., "192.168.1.1-10")
     * @param targetIp The IP address to check against the range
     * @return true if the target IP is within the specified range, false otherwise
     */
    private boolean evaluateIPRange(Object value, Object targetIp)
    {
        try
        {
            var start = value.toString().split("-")[0].trim();

            var end = start.substring(0, start.lastIndexOf('.')) + "." + value.toString().split("-")[1].trim();

            if (APIUtil.validateRange(start, end))
            {
                return CommonUtil.calculateIPRange(InetAddress.getByName(start), InetAddress.getByName(end))
                        .stream()
                        .anyMatch(address -> address.equals(targetIp));
            }
        }
        catch (Exception e)
        {
            LOGGER.error(e);
        }
        return false;
    }

    @Override
    public void start(Promise<Void> promise)
    {
        var objectItems = ObjectConfigStore.getStore().getItems();

        for (var i = 0; i < objectItems.size(); i++)
        {
            var item = objectItems.getJsonObject(i);

            itemByObjects.put(item.getLong(ID), item);
        }

        var metrics = MetricConfigStore.getStore().getItems();

        for (var i = 0; i < metrics.size(); i++)
        {
            var metric = metrics.getJsonObject(i);

            itemByMetrics.put(metric.getLong(ID), metric);
        }

        /*
         * This event is triggered by the user and is responsible for processing a specified Rule.
         *
         * - When triggered, the event evaluates the Rule's conditions against available objects.
         * - It identifies the objects that meet the Rule's criteria.
         * - Once qualified objects are determined, the event assigns the appropriate tags to them.
         *
         * This ensures that objects are categorized correctly based on the Rule's logic.
         */
        vertx.eventBus().<JsonObject>localConsumer(EventBusConstants.EVENT_TAG_RULE_RUN, message ->
        {

            try
            {
                var event = message.body();

                //Bulk Feature
                if (event.containsKey(APIConstants.REQUEST_PARAM_IDS))
                {
                    var futures = new ArrayList<Future<JsonObject>>();

                    var objectMap = new JsonObject();

                    var metricMap = new JsonObject();

                    var changedObjectIds = new HashSet<>();

                    var changedMetricIds = new HashSet<>();

                    for (var i = 0; i < event.getJsonArray(APIConstants.REQUEST_PARAM_IDS).size(); i++)
                    {
                        var ruleId = event.getJsonArray(APIConstants.REQUEST_PARAM_IDS).getLong(i);

                        var rule = TagRuleConfigStore.getStore().getItem(ruleId);

                        if (rule!=null)
                        {
                            if (rule.containsKey(TagRule.TAG_RULE_CONDITIONS))
                            {
                                var conditions = rule.getJsonArray(TagRule.TAG_RULE_CONDITIONS);

                                if (APIConstants.Entity.OBJECT.getName().toLowerCase().equalsIgnoreCase(rule.getString(TagRule.TAG_RULE_TYPE)))
                                {
                                    LOGGER.debug("Qualify conditions: " + rule.getString(TagRule.TAG_RULE_NAME));

                                    //will return qualified monitors for the rule
                                    var items = qualify(conditions, YES.equalsIgnoreCase(rule.getString(TagRule.TAG_RULE_INCLUSIVE_CONDITION)));

                                    if (!items.isEmpty())
                                    {
                                        LOGGER.debug("qualified " + items.size() + " monitors for Rule: " + rule.getString(TagRule.TAG_RULE_NAME));

                                        // queue assignment for the qualified monitors
                                        futures.add(updateBulkTags(items, rule.getJsonArray(TagRule.TAG_RULE_TAGS), rule.getJsonObject(TagRule.TAG_RULE_DYNAMIC_TAGS), TagRule.TAG_RULE_OPERATION_ASSIGN.equalsIgnoreCase(rule.getString(TagRule.TAG_RULE_OPERATION)), objectMap, changedObjectIds));
                                    }
                                    else
                                    {
                                        LOGGER.debug("no monitor qualified for rule: " + rule.getString(TagRule.TAG_RULE_NAME));
                                    }
                                }
                                else
                                {
                                    //will return qualified instances for the rule
                                    var items = qualify(conditions, rule.getString(TagRule.TAG_RULE_TYPE), YES.equalsIgnoreCase(rule.getString(TagRule.TAG_RULE_INCLUSIVE_CONDITION)), false);

                                    if (!items.isEmpty())
                                    {
                                        LOGGER.debug("qualified instances for rule: " + rule.getString(TagRule.TAG_RULE_NAME));

                                        // queue assignment for the qualified instances
                                        futures.add(updateBulkTags(items, rule.getJsonArray(TagRule.TAG_RULE_TAGS), rule.getJsonObject(TagRule.TAG_RULE_DYNAMIC_TAGS), TagRule.TAG_RULE_OPERATION_ASSIGN.equalsIgnoreCase(rule.getString(TagRule.TAG_RULE_OPERATION)), metricMap, changedMetricIds));
                                    }
                                    else
                                    {
                                        LOGGER.debug("no instance qualified for rule: " + rule.getString(TagRule.TAG_RULE_NAME));
                                    }
                                }
                            }

                            //Update Last Triggered Time
                            Bootstrap.configDBService().update(DBConstants.TBL_TAG_RULE, new JsonObject().put(DBConstants.FIELD_NAME, ID).put(VALUE, rule.getLong(ID)),
                                    TagRuleConfigStore.getStore().getItem(rule.getLong(ID)).put(TagRule.TAG_RULE_TRIGGERED_TIME, System.currentTimeMillis()), DEFAULT_USER, SYSTEM_REMOTE_ADDRESS, future ->
                                    {
                                        if (future.succeeded())
                                        {
                                            TagRuleConfigStore.getStore().updateItem(rule.getLong(ID));
                                        }
                                    });
                        }
                    }

                    if (futures.isEmpty())
                    {
                        LOGGER.info("no qualifying items across all rules. replying success.");

                        message.reply(new JsonObject().put(STATUS, STATUS_SUCCEED));
                    }
                    else
                    {
                        LOGGER.info("executing bulk tag updates for " + futures.size() + " operation(s)...");

                        Future.join(futures).onComplete(ar ->
                        {
                            if (ar.succeeded())
                            {
                                var postOps = new ArrayList<Future<Void>>();

                                if (!objectMap.isEmpty())
                                {
                                    var objPromise = Promise.<Void>promise();

                                    Bootstrap.configDBService().updateAllMultipleValues(TBL_OBJECT,
                                            new JsonObject().put(DBConstants.FIELD_NAME, ID).put(VALUE, new JsonArray(new ArrayList<>(changedObjectIds))),
                                            objectMap,
                                            SYSTEM_USER, SYSTEM_REMOTE_ADDRESS, handler->
                                            {
                                                if (handler.succeeded())
                                                {
                                                    ObjectConfigStore.getStore().updateAll(handler.result());

                                                    objPromise.complete();
                                                }
                                                else
                                                {
                                                    LOGGER.error(handler.cause());

                                                    objPromise.fail(handler.cause());
                                                }
                                            });

                                    postOps.add(objPromise.future());
                                }

                                if (!metricMap.isEmpty())
                                {
                                    var metricPromise = Promise.<Void>promise();

                                    var changedMetric = new JsonArray(new ArrayList<>(changedMetricIds));

                                    Bootstrap.configDBService().updateAllMultipleValues(DBConstants.TBL_METRIC,
                                            new JsonObject().put(DBConstants.FIELD_NAME, ID).put(VALUE, changedMetric),
                                            metricMap,
                                            SYSTEM_USER, SYSTEM_REMOTE_ADDRESS, handler->
                                            {
                                                if (handler.succeeded())
                                                {
                                                    MetricConfigStore.getStore().updateAll(handler.result(), changedMetric);

                                                    metricPromise.complete();
                                                }
                                                else
                                                {
                                                    LOGGER.error(handler.cause());

                                                    metricPromise.fail(handler.cause());
                                                }
                                            });

                                    postOps.add(metricPromise.future());
                                }

                                if (postOps.isEmpty())
                                {
                                    LOGGER.info("no db updates required for objects or metrics. replying success.");

                                    message.reply(new JsonObject().put(STATUS, STATUS_SUCCEED));
                                }
                                else
                                {
                                    Future.join(postOps).onComplete(done ->
                                    {
                                        if (done.succeeded())
                                        {
                                            LOGGER.info("bulk tag updates completed successfully.");

                                            message.reply(new JsonObject().put(STATUS, STATUS_SUCCEED));
                                        }
                                        else
                                        {
                                            LOGGER.error(done.cause());

                                            message.fail(HttpStatus.SC_INTERNAL_SERVER_ERROR, done.cause().getMessage());
                                        }

                                        postOps.clear();
                                    });
                                }

                                objectMap.clear();

                                metricMap.clear();

                                changedObjectIds.clear();

                                changedMetricIds.clear();

                                futures.clear();
                            }
                            else
                            {
                                LOGGER.error(ar.cause());

                                message.fail(HttpStatus.SC_INTERNAL_SERVER_ERROR, ar.cause().getMessage());

                                futures.clear();
                            }
                        });
                    }
                }
                else
                {
                    if (event.containsKey(TagRule.TAG_RULE_CONDITIONS))
                    {
                        var conditions = event.getJsonArray(TagRule.TAG_RULE_CONDITIONS);

                        if (APIConstants.Entity.OBJECT.getName().toLowerCase().equalsIgnoreCase(event.getString(TagRule.TAG_RULE_TYPE)))
                        {
                            LOGGER.debug("qualify conditions for objects: " + event.getString(TagRule.TAG_RULE_NAME));

                            //will return qualified monitors for the rule
                            var items = qualify(conditions, YES.equalsIgnoreCase(event.getString(TagRule.TAG_RULE_INCLUSIVE_CONDITION)));

                            if (event.getBoolean(TagRule.TAG_RULE_TEST))
                            {
                                if (!items.isEmpty())
                                {
                                    message.reply(new JsonObject().put(RESULT, items).put(STATUS, STATUS_SUCCEED));
                                }
                                else
                                {
                                    message.fail(HttpStatus.SC_NOT_FOUND, ErrorMessageConstants.INVALID_NO_DATA_FOUND);
                                }
                            }
                            else
                            {
                                if (!items.isEmpty())
                                {
                                    //will assign tags to the qualified monitors
                                    updateTags(items, event.getJsonArray(TagRule.TAG_RULE_TAGS), event.getJsonObject(TagRule.TAG_RULE_DYNAMIC_TAGS), TagRule.TAG_RULE_OPERATION_ASSIGN.equalsIgnoreCase(event.getString(TagRule.TAG_RULE_OPERATION))).onComplete(result ->
                                    {

                                        if (result.succeeded())
                                        {
                                            LOGGER.debug("tag updates completed successfully.");

                                            message.reply(new JsonObject().put(STATUS, STATUS_SUCCEED));
                                        }
                                        else
                                        {
                                            LOGGER.error(result.cause());

                                            message.fail(HttpStatus.SC_INTERNAL_SERVER_ERROR, result.cause().getMessage());
                                        }
                                    });
                                }
                                else
                                {
                                    message.reply(new JsonObject().put(STATUS, STATUS_SUCCEED));

                                    LOGGER.debug("no monitor qualified for rule: " + event.getString(TagRule.TAG_RULE_NAME));
                                }
                            }
                        }
                        else
                        {
                            LOGGER.debug("qualify conditions for instance: " + event.getString(TagRule.TAG_RULE_NAME));

                            //will return qualified instances for the rule
                            var items = qualify(conditions, event.getString(TagRule.TAG_RULE_TYPE), YES.equalsIgnoreCase(event.getString(TagRule.TAG_RULE_INCLUSIVE_CONDITION)), event.getBoolean(TagRule.TAG_RULE_TEST));

                            if (event.getBoolean(TagRule.TAG_RULE_TEST))
                            {
                                var objects = new JsonArray();

                                var count = 0;

                                //In Preview, we will only send 1000 instances to UI
                                for (var item : items.entrySet())
                                {
                                    var entries = item.getValue();

                                    if (count >= 1000)
                                    {
                                        break;
                                    }

                                    objects.addAll(entries);

                                    count += entries.size();
                                }

                                if (!objects.isEmpty())
                                {
                                    message.reply(new JsonObject().put(RESULT, objects).put(STATUS, STATUS_SUCCEED));
                                }
                                else
                                {
                                    message.fail(HttpStatus.SC_NOT_FOUND, ErrorMessageConstants.INVALID_NO_DATA_FOUND);
                                }
                            }
                            else
                            {
                                if (!items.isEmpty())
                                {
                                    //will assign tags to the qualified instances
                                    updateTags(items, event.getJsonArray(TagRule.TAG_RULE_TAGS), event.getJsonObject(TagRule.TAG_RULE_DYNAMIC_TAGS), TagRule.TAG_RULE_OPERATION_ASSIGN.equalsIgnoreCase(event.getString(TagRule.TAG_RULE_OPERATION))).onComplete(result ->
                                    {

                                        if (result.succeeded())
                                        {
                                            LOGGER.debug("tag updates completed successfully.");

                                            message.reply(new JsonObject().put(RESULT, items).put(STATUS, STATUS_SUCCEED));
                                        }
                                        else
                                        {
                                            LOGGER.error(result.cause());

                                            message.fail(HttpStatus.SC_INTERNAL_SERVER_ERROR, result.cause().getMessage());
                                        }
                                    });
                                }
                                else
                                {
                                    message.reply(new JsonObject().put(STATUS, STATUS_SUCCEED));

                                    LOGGER.debug("no instance qualified for rule: " + event.getString(TagRule.TAG_RULE_NAME));
                                }
                            }
                        }
                    }

                    //At every Run we will update the Last Run Time of the Rule
                    if (!event.getBoolean(TagRule.TAG_RULE_TEST))
                    {
                        Bootstrap.configDBService().update(DBConstants.TBL_TAG_RULE, new JsonObject().put(DBConstants.FIELD_NAME, ID).put(VALUE, event.getLong(ID)),
                                TagRuleConfigStore.getStore().getItem(event.getLong(ID)).put(TagRule.TAG_RULE_TRIGGERED_TIME, System.currentTimeMillis()), DEFAULT_USER, SYSTEM_REMOTE_ADDRESS, future ->
                                {
                                    if (future.succeeded())
                                    {
                                        TagRuleConfigStore.getStore().updateItem(event.getLong(ID));
                                    }
                                });
                    }
                }

            }
            catch (Exception exception)
            {
                LOGGER.error(exception);
            }
        });

        vertx.eventBus().<JsonObject>localConsumer(EventBusConstants.EVENT_CHANGE_NOTIFICATION, message ->
        {
            var event = message.body();

            switch (EventBusConstants.ChangeNotificationType.valueOf(event.getString(EventBusConstants.CHANGE_NOTIFICATION_TYPE)))
            {
                case ADD_OBJECT ->
                {
                    //At every new Object Provision, we will store the Object ID and will process it later
                    objects.add(event.getLong(ID));

                    itemByObjects.put(event.getLong(ID), ObjectConfigStore.getStore().getItem(event.getLong(ID)));
