                case DELETE_OBJECT -> itemByObjects.remove(event.getLong(ID));

                case UPDATE_OBJECT ->  itemByObjects.put(event.getLong(ID), ObjectConfigStore.getStore().getItem(event.getLong(ID)));

                case ADD_METRIC -> itemByMetrics.put(event.getLong(ID), MetricConfigStore.getStore().getItem(event.getLong(ID)));

                case DELETE_METRIC -> itemByMetrics.remove(event.getLong(ID));

                case UPDATE_METRIC -> itemByMetrics.put(event.getLong(ID), MetricConfigStore.getStore().getItem(event.getLong(ID)));
            }

        }).exceptionHandler(LOGGER::error);

