   private void qualifyRule(Long id, JsonObject item, boolean status, JsonArray conditions, JsonArray ids, boolean inclusive)
   {
       try
       {
           for (var i = 0; i < conditions.size(); i++)
           {
               var condition = conditions.getJsonObject(i);

               if (item.getValue(condition.getString(VisualizationConstants.DATA_POINT)) != null)
               {
                   var value = PolicyEngineConstants.Operator.IN.getName().equalsIgnoreCase(condition.getString(OPERATOR)) ? new JsonArray(condition.getString(VALUE)) : condition.getValue(VALUE);

                   if (condition.getString(FILTER).equalsIgnoreCase(DatastoreConstants.ConditionGroup.AND.getName()))
                   {
                       if(PolicyEngineConstants.Operator.RANGE.getName().equalsIgnoreCase(condition.getString(OPERATOR)))
                       {
                           status = status && evaluateIPRange(value, item.getValue(condition.getString(VisualizationConstants.DATA_POINT)));
                       }
                       else
                       {
                           status = status && PolicyEngineConstants.evaluateCondition(inclusive, condition.getString(OPERATOR), value, item.getValue(condition.getString(VisualizationConstants.DATA_POINT)));
                       }
                   }
                   else if (condition.getString(FILTER).equalsIgnoreCase(DatastoreConstants.ConditionGroup.OR.getName()))
                   {
                       if(PolicyEngineConstants.Operator.RANGE.getName().equalsIgnoreCase(condition.getString(OPERATOR)))
                       {
                           status = status || evaluateIPRange(value, item.getValue(condition.getString(VisualizationConstants.DATA_POINT)));
                       }
                       else
                       {
                           status = status || PolicyEngineConstants.evaluateCondition(inclusive, condition.getString(OPERATOR), value, item.getValue(condition.getString(VisualizationConstants.DATA_POINT)));
                       }
                   }
                   else
                   {
                       if(PolicyEngineConstants.Operator.RANGE.getName().equalsIgnoreCase(condition.getString(OPERATOR)))
                       {
                           status = evaluateIPRange(value, item.getValue(condition.getString(VisualizationConstants.DATA_POINT)));
                       }
                       else
                       {
                           status = PolicyEngineConstants.evaluateCondition(inclusive, condition.getString(OPERATOR), value, item.getValue(condition.getString(VisualizationConstants.DATA_POINT)));
                       }
                   }
               }
               else
               {
                   if (DatastoreConstants.ConditionGroup.AND.getName().equalsIgnoreCase(condition.getString(FILTER)))
                   {
                       status = false;
                   }
               }
           }

           if (status)
           {
               ids.add(id);
           }
       }
       catch (Exception exception)
       {
           LOGGER.error(exception);
       }

   }

   /*
    *  This method will apply Tags based on rules to the given qualified Objects
    *  params: ids (List of Qualified Object IDs),
    *          objectTags (Static Tags - example-> department:dev etc. ),
    *          dynamicTags (Dynamic Tags - example-> vm:{vm.ip} etc.),
    *          assign (true or false based on Rule)
    *
    * */
   private Future<JsonObject> updateTags(JsonArray ids, JsonArray objectTags, JsonObject dynamicTags, boolean assign)
   {
       var future = Promise.<JsonObject>promise();

       LOGGER.debug("object tag started the prep for update");

       try
       {
           // Fast no-op: nothing to add/remove
           if (objectTags.isEmpty() && dynamicTags.isEmpty())
           {
               future.complete(new JsonObject().put(GlobalConstants.STATUS, STATUS_SUCCEED));

               return future.future();
           }

           // Stage only changed records and perform one batched DB update
           var changedIds = new JsonArray();

           var changedObjects = new JsonArray();

           var bulkRecord = new JsonObject(); // { "<id>": { OBJECT_TAGS: [...] }, ... }

           for (var id : ids)
           {
               var object = itemByObjects.get(CommonUtil.getLong(id));

               if (object == null || object.isEmpty())
               {
                   continue;
               }

               // Work on a detached copy to avoid mutating objectStore by reference
               var base = object.getJsonArray(AIOpsObject.OBJECT_TAGS);

               var tags = (base != null) ? new JsonArray().addAll(base) : new JsonArray();

               var changed = false;

               // Static tags merge
               if (assign)
               {
                   for (var i = 0; i < objectTags.size(); i++)
                   {
                       var tag = objectTags.getInteger(i);

                       if (!tags.contains(tag))
                       {
                           tags.add(tag);

                           changed = true;
                       }
                   }
               }
               else
               {
                   for (var i = 0; i < objectTags.size(); i++)
                   {
                       if (tags.remove(objectTags.getInteger(i)))
                       {
                           changed = true;
                       }
                   }
               }

               // Dynamic tags merge
               if (!dynamicTags.isEmpty())
               {
                   var newTags = processDynamicTags(object, dynamicTags);

                   if (assign)
                   {
                       for (var i = 0; i < newTags.size(); i++)
                       {
                           var tag = newTags.getInteger(i);

                           if (!tags.contains(tag))
                           {
                               tags.add(tag);

                               changed = true;
                           }
                       }
                   }
                   else if (!newTags.isEmpty())
                   {
                       for (var i = 0; i < newTags.size(); i++)
                       {
                           if (tags.remove(newTags.getInteger(i)))
                           {
                               changed = true;
                           }
                       }
                   }
                   else if (base == null)
                   {
                       // Preserve existing behavior: when removing and no base tags present, keep array empty
                       tags.clear();
                   }
               }

               // Change already tracked during merge operations
               if (changed)
               {
                   changedIds.add(CommonUtil.getLong(id));

                   var staged = new JsonObject()
                           .put(AIOpsObject.OBJECT_ID, object.getInteger(AIOpsObject.OBJECT_ID))
                           .put(AIOpsObject.OBJECT_TAGS, tags);

                   changedObjects.add(staged);

                   // Persist minimal payload; keep current order from 'tags'
                   bulkRecord.put(CommonUtil.getString(id), staged);
               }
           }

           if (changedIds.isEmpty())
           {
               LOGGER.debug("no object tag changes detected; skipping db update");

               future.complete(new JsonObject().put(GlobalConstants.STATUS, STATUS_SUCCEED));

               return future.future();
           }

           for (var i = 0; i < changedObjects.size(); i++)
           {
               TagCacheStore.getStore().init(changedObjects.getJsonObject(i));
           }

           LOGGER.debug("updated the object tags for insertion");

           Bootstrap.configDBService().updateAllMultipleValues(
                   DBConstants.TBL_OBJECT,
                   new JsonObject().put(DBConstants.FIELD_NAME, ID).put(VALUE, changedIds),
                   bulkRecord,
                   DEFAULT_USER,
                   SYSTEM_REMOTE_ADDRESS,
                   result ->
                   {
                       if (result.succeeded())
                       {
                           LOGGER.debug("db update succeeded for tbl_object, calling config store update item");

                           ObjectConfigStore.getStore().updateAll(result.result());

                           future.complete(new JsonObject().put(GlobalConstants.STATUS, STATUS_SUCCEED));
                       }
                       else
                       {
                           LOGGER.error(result.cause());

                           future.fail(result.cause());
                       }
                   });
       }
       catch (Exception exception)
       {
           LOGGER.error(exception);
           future.fail(exception);
       }

       return future.future();
   }

   /*
