                       if (objectName != null && qualifiedObjectNames.contains(objectName))
                       {
                           var record = new JsonObject();

                           record.getMap().putAll(sourceObject.getMap());

                           if (sourceObject.getJsonArray(INSTANCE_TAGS) != null)
                           {
                               record.put(INSTANCE_TAGS, new JsonArray().addAll(sourceObject.getJsonArray(INSTANCE_TAGS)));
                           }

                           updatedObjects.add(record);
                       }
                       else
                       {
                           // safe to reuse reference for unqualified entries (we won't mutate them)
                           updatedObjects.add(sourceObject);
                       }
                   }
               }

               setTags(instanceTags, dynamicTags, metricEntry.getValue(), updatedObjects, assign);

               TagCacheStore.getStore().updateInstanceTags(metric.getLong(ID), updatedObjects,
                       NMSConstants.INSTANCE_TYPES.getOrDefault(metric.getString(Metric.METRIC_PLUGIN), EMPTY_VALUE));

               ObjectConfigStore.getStore().updateInstanceTags(metric.getLong(ID), updatedObjects);

               // Persist minimal payload to avoid mutating the in

Objects != null && !sourceObjects.isEmpty())
                {
                    for (var i = 0; i < sourceObjects.size(); i++)
                    {
                        var sourceObject = sourceObjects.getJsonObject(i);

                        var objectName = sourceObject.getString(AIOpsObject.OBJECT_NAME);

                        if (objectName != null && qualifiedObjectNames.contains(objectName))
                        {
                            var record = new JsonObject();

                            record.getMap().putAll(sourceObject.getMap());

                            if (sourceObject.getJsonArray(INSTANCE_TAGS) != null)
                            {
                                record.put(INSTANCE_TAGS, new JsonArray().addAll(sourceObject.getJsonArray(INSTANCE_TAGS)));
                            }

                            updatedObjects.add(record);
                        }
                        else
