                            updatedObjects.add(sourceObject);
                        }
                    }
                }

                setTags(instanceTags, dynamicTags, metricEntry.getValue(), updatedObjects, assign);

                TagCacheStore.getStore().updateInstanceTags(metric.getLong(ID), updatedObjects,
                        NMSConstants.INSTANCE_TYPES.getOrDefault(metric.getString(Metric.METRIC_PLUGIN), EMPTY_VALUE));

                ObjectConfigStore.getStore().updateInstanceTags(metric.getLong(ID), updatedObjects);

                // Persist minimal payload to avoid mutating the in-memory metricStore by reference
