                        {
                            if (result.succeeded())
                            {
                                promise.complete();
                            }
                            else
                            {
                                promise.fail(result.cause().getMessage());
                            }
                        });
            }

            LOGGER.debug("instance tag started the prep for insertion");

            Future.join(futures).onComplete(result ->
            {
