            future.fail(exception);
        }

        return future.future();
    }

    /*
     *  Extend Method of processInstanceTags
     * */
    private void setTags(JsonArray instanceTags, JsonObject dynamicTags, JsonArray qualifiedObjects, JsonArray objects, boolean assign)
    {
        try
        {
            var qualified = new HashSet<String>();

            for (var index = 0; index < qualifiedObjects.size(); index++)
            {
                qualified.add(qualifiedObjects.getJsonObject(index).getString(AIOpsObject.OBJECT_NAME));
            }

            for (var index = 0; index < objects.size(); index++)
            {
                var object = objects.getJsonObject(index);

                // will apply tag only to the objects which are qualified
                if (object.getString(AIOpsObject.OBJECT_NAME) != null && qualified.contains(object.getString(AIOpsObject.OBJECT_NAME)))
                {
                    for (var tagIndex = 0; tagIndex < instanceTags.size(); tagIndex++)
                    {
                        var tag = instanceTags.getInteger(tagIndex);

                        var objectInstanceTags = (JsonArray) object.getMap().computeIfAbsent(INSTANCE_TAGS, val -> new JsonArray());

                        if (!objectInstanceTags.contains(tag) && assign)
                        {
                            objectInstanceTags.add(tag);
                        }
                        else if (objectInstanceTags.contains(tag) && !assign)
                        {
                            objectInstanceTags.remove(tag);
                        }
                    }

                    if (!dynamicTags.isEmpty())
                    {
                        var newTags = processDynamicTags(object, dynamicTags);

                        var tags = object.getJsonArray(INSTANCE_TAGS, new JsonArray());

                        if (assign)
                        {
                            for (var j = 0; j < newTags.size(); j++)
                            {
                                if (!tags.contains(newTags.getInteger(j)))
                                {
                                    tags.add(newTags.getInteger(j));
                                }
                            }

                            object.put(INSTANCE_TAGS, tags);
                        }
                        else
                        {
                            for (var j = 0; j < newTags.size(); j++)
                            {
                                tags.remove(newTags.getInteger(j));
                            }
                        }
                    }
                }
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

    /*
     *  This method will process the Dynamic Tags and will return the list of tags
     *  params: object (Object), tags (Dynamic Tags)
     *  example: object: {object.name: vm1, object.id: 1000000001, object.ip:172.16.0.0}
     *           tags: {tag1: object.name, tag2: object.ip}
     *
     *           return: [tag1:vm1, tag2:172.16.0.0] but in hashcode format [1000000001, 1000000002]
     * */
    private JsonArray processDynamicTags(JsonObject object, JsonObject tags)
    {
        var dynamicTags = new JsonArray();

        var newTags = new JsonArray();

        try
        {
            for (var key : tags.fieldNames())
            {
                var value = tags.getString(key);

                if (value != null && !value.isEmpty() && object.containsKey(value))
                {
                    dynamicTags.add(key + COLON_SEPARATOR + object.getString(value));
                }
            }

            if (!dynamicTags.isEmpty())
            {
                newTags = TagConfigStore.getStore().addItems(dynamicTags, Tag.TagType.OBJECT.getName(), DBConstants.ENTITY_TYPE_USER);
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }

        return newTags;
    }


    private JsonArray getMetricsByPlugin(String plugin)
    {
        var result = new JsonArray();

        try
        {
            var metrics = MetricConfigStore.getStore().getItems();

            for (var index = 0; index < metrics.size(); index++)
            {
                var item = metrics.getJsonObject(index);

                if (item.getString(Metric.METRIC_PLUGIN) != null && item.getString(Metric.METRIC_PLUGIN).equalsIgnoreCase(plugin))
                {
                    result.add(item);
                }
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
        return result;
    }

    /*
     * This method will return the Instances based on the Instance Type
     * params: instanceType(example: interface, vm, etc.)
     * */
    private JsonArray getInstances(String instanceType)
    {
        var items = new JsonArray();

        try
        {
            var plugins = PLUGIN_BY_INSTANCES.getOrDefault(instanceType, new JsonArray());

            if (!plugins.isEmpty())
            {
                for (var plugin : plugins)
                {
                    items.addAll(getMetricsByPlugin(CommonUtil.getString(plugin)));
                }
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }

        return items;
    }

    /*
     *  This method will process New Provisioned Objects and tags will be assigned to them if they qualify the conditions
     *
     *  params: objects (List of Object IDs)
     *  Only "Objects" Based Rules AND Rules with "Assign" operation are going to be processed
     * */
    private void assign(JsonArray objects)
    {
        try
        {
            var staticTags = new HashMap<Long, JsonArray>();

            var dynamicTags = new HashMap<Long, JsonObject>();

            if (!objects.isEmpty())
            {
                var items = TagRuleConfigStore.getStore().getItems();

                for (var index = 0; index < items.size(); index++)
                {
                    var rule = items.getJsonObject(index);

                    if (rule.containsKey(TagRule.TAG_RULE_CONDITIONS) &&
                            APIConstants.Entity.OBJECT.getName().toLowerCase().equalsIgnoreCase(rule.getString(TagRule.TAG_RULE_TYPE)) &&
                            TagRule.TAG_RULE_OPERATION_ASSIGN.equalsIgnoreCase(rule.getString(TagRule.TAG_RULE_OPERATION)))
                    {

                        for (var item : qualify(rule.getJsonArray(TagRule.TAG_RULE_CONDITIONS), YES.equalsIgnoreCase(rule.getString(TagRule.TAG_RULE_INCLUSIVE_CONDITION)), objects))
                        {
                            staticTags.computeIfAbsent(CommonUtil.getLong(item), value -> new JsonArray()).addAll(rule.getJsonArray(TagRule.TAG_RULE_TAGS));

                            dynamicTags.computeIfAbsent(CommonUtil.getLong(item), value -> new JsonObject()).mergeIn(rule.getJsonObject(TagRule.TAG_RULE_DYNAMIC_TAGS));
                        }
                    }
                }

                for (var index = 0; index < objects.size(); index++)
                {
                    updateTags(new JsonArray().add(objects.getLong(index)), staticTags.getOrDefault(objects.getLong(index), new JsonArray()), dynamicTags.getOrDefault(objects.getLong(index), new JsonObject()), true).onComplete(result ->
                    {
                        if (result.succeeded())
                        {
                            LOGGER.debug("Monitor Tags are assigned..");
                        }
                    });
                }
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

    private JsonArray enrich(JsonArray tags, JsonArray newTags)
    {
        try
        {
            for (var index = 0; index < newTags.size(); index++)
            {
                if (!tags.contains(newTags.getLong(index)))
                {
                    tags.add(newTags.getLong(index));
                }
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }

        return tags;
    }

    /**
     * Updates tags in bulk for a list of object IDs.
     *
     * This method applies static and dynamic tags to the specified objects based on the rule operation (assign or remove).
     * It compares the previous tags with the updated tags and only updates objects whose tags have changed.
     * The update is performed in the database and the in-memory store.
     *
     * @param ids        JsonArray of object IDs to update.
     * @param objectTags JsonArray of static tag IDs to assign or remove.
     * @param dynamicTags JsonObject of dynamic tags to process and assign or remove.
     * @param assign     If true, tags are assigned; if false, tags are removed.
     * @return Future\<JsonObject\> indicating the status of the bulk update operation.
     */
    private Future<JsonObject> updateBulkTags(JsonArray ids, JsonArray objectTags, JsonObject dynamicTags, boolean assign, JsonObject objectMap, HashSet changedIds)
    {
        var future = Promise.<JsonObject>promise();

        LOGGER.debug("bulk object tags started the prep for update");

        try
        {
            if (ids == null || ids.isEmpty() || (objectTags.isEmpty() && dynamicTags.isEmpty()))
            {
                future.complete(new JsonObject().put(GlobalConstants.STATUS, STATUS_SUCCEED));

                return future.future();
            }

            var changedObjects = new JsonArray();

            for (var id : ids)
            {
                // Always read the source object from the store (do not keep references in objectMap)
                var object = itemByObjects.get(CommonUtil.getLong(id));

                if (object != null && !object.isEmpty())
                {
                    // Determine baseline tags: prefer already staged tags, else take from store
                    var stagedExisting = objectMap.getJsonObject(CommonUtil.getString(id));

                    var baseTags = (stagedExisting != null && stagedExisting.containsKey(AIOpsObject.OBJECT_TAGS))
                            ? stagedExisting.getJsonArray(AIOpsObject.OBJECT_TAGS)
                            : object.getJsonArray(AIOpsObject.OBJECT_TAGS, new JsonArray());

                    var tagSet = new HashSet<Integer>();

                    for (var i = 0; i < baseTags.size(); i++)
                    {
                        tagSet.add(baseTags.getInteger(i));
                    }

                    var changed = false;

                    // Apply static tag updates
                    if (assign)
                    {
                        for (var i = 0; i < objectTags.size(); i++)
                        {
                            if (tagSet.add(objectTags.getInteger(i)))
                            {
                                changed = true;
                            }
                        }
                    }
                    else
                    {
                        for (var i = 0; i < objectTags.size(); i++)
                        {
                            if (tagSet.remove(objectTags.getInteger(i)))
                            {
                                changed = true;
                            }
                        }
                    }

                    // Apply dynamic tag updates (computed from the source object only)
                    if (!dynamicTags.isEmpty())
                    {
                        var newTags = processDynamicTags(object, dynamicTags);

                        if (assign)
                        {
                            for (var i = 0; i < newTags.size(); i++)
                            {
                                if (tagSet.add(newTags.getInteger(i)))
                                {
                                    changed = true;
                                }
                            }
                        }
                        else
                        {
                            for (var i = 0; i < newTags.size(); i++)
                            {
                                if (tagSet.remove(newTags.getInteger(i)))
                                {
                                    changed = true;
                                }
                            }
                        }
                    }

                    //3: Skip cache update if tags unchanged
                    if (changed)
                    {
                        // Convert HashSet back to JsonArray
                        var tags = new JsonArray(new ArrayList<>(tagSet));

                        // Stage only minimal update per id: { object.id, object.tags }
                        var staged = new JsonObject()
                                .put(AIOpsObject.OBJECT_ID, object.getInteger(AIOpsObject.OBJECT_ID))
                                .put(AIOpsObject.OBJECT_TAGS, tags);

                        objectMap.put(CommonUtil.getString(id), staged);

                        // Collect for batch cache update
                        changedObjects.add(staged);

                        changedIds.add(id);
                    }
                }
            }

            if (changedIds.isEmpty() && changedObjects.isEmpty())
            {
                LOGGER.debug("No object tag changes detected.");

                future.complete(new JsonObject().put(GlobalConstants.STATUS, STATUS_SUCCEED));

                return future.future();
            }

            for (var i = 0; i < changedObjects.size(); i++)
            {
                TagCacheStore.getStore().init(changedObjects.getJsonObject(i));
            }

            LOGGER.debug("Object Tags has been updated");

            future.complete(new JsonObject().put(GlobalConstants.STATUS, STATUS_SUCCEED));
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);

            future.fail(exception);
        }


        return future.future();
    }

    /**
     * Updates tags in bulk for a set of qualified instances.
     *
     * This method applies static and dynamic tags to the specified instances based on the rule operation (assign or remove).
     * It updates the tags for each instance, reflects changes in the database and in-memory stores, and returns a Future indicating the status.
     *
     * @param instances    Map of MetricConfigStore IDs to qualified instance objects.
     * @param instanceTags JsonArray of static tag IDs to assign or remove.
     * @param dynamicTags  JsonObject of dynamic tags to process and assign or remove.
     * @param assign       If true, tags are assigned; if false, tags are removed.
     * @return Future<JsonObject> indicating the status of the bulk update operation.
     */
    private Future<JsonObject> updateBulkTags(Map<Long, JsonArray> instances, JsonArray instanceTags, JsonObject dynamicTags, boolean assign, JsonObject instanceMap, HashSet changedIds)
    {
        var future = Promise.<JsonObject>promise();

        LOGGER.debug("bulk instance tag started the prep for update");

        try
        {
            for (var entry : instances.entrySet())
            {
                if(itemByMetrics.containsKey(entry.getKey()))
                {
                    var updatedObjects = new JsonArray(); // Build a detached objects array: clone only qualified elements and detach INSTANCE_TAGS

                    var qualifiedValues = entry.getValue();  //Cache array reference to avoid repeated getJsonObject() calls

                    var key = CommonUtil.getString(entry.getKey());

                    var item = itemByMetrics.get(entry.getKey());

                    // Determine the source objects: prefer previously staged objects from instanceMap, else current store
                    var metrics = item.getJsonObject(Metric.METRIC_CONTEXT).getJsonArray(OBJECTS);

                    if (instanceMap.containsKey(key))
                    {
                        var metricContext = instanceMap.getJsonObject(key).getJsonObject(Metric.METRIC_CONTEXT);

                        if (metricContext != null)
                        {
                            metrics = metricContext.getJsonArray(OBJECTS);
                        }
                    }

                    var qualifiedObjectNames = new HashSet<String>();

                    for (var idx = 0; idx < qualifiedValues.size(); idx++)
                    {
                        var objectName = qualifiedValues.getJsonObject(idx).getString(AIOpsObject.OBJECT_NAME);

                        if (objectName != null)
                        {
                            qualifiedObjectNames.add(objectName);
                        }
                    }

                    if (metrics != null && !metrics.isEmpty())
                    {
                        for (var i = 0; i < metrics.size(); i++)
                        {
                            var object = metrics.getJsonObject(i);

                            var objectName = object.getString(AIOpsObject.OBJECT_NAME);

                            if (objectName != null && qualifiedObjectNames.contains(objectName))
                            {
                                var record = new JsonObject();

                                record.getMap().putAll(object.getMap());

                                if (object.getJsonArray(INSTANCE_TAGS) != null)
                                {
                                    record.put(INSTANCE_TAGS, new JsonArray().addAll(object.getJsonArray(INSTANCE_TAGS)));
                                }

                                updatedObjects.add(record);
                            }
                            else
                            {
                                // safe to reuse reference for unqualified entries (we won't mutate them)
                                updatedObjects.add(object);
                            }
                        }
                    }

                    setTags(instanceTags, dynamicTags, qualifiedValues, updatedObjects, assign);

                    changedIds.add(entry.getKey());

                    TagCacheStore.getStore().updateInstanceTags(entry.getKey(), updatedObjects,
                            NMSConstants.INSTANCE_TYPES.getOrDefault(item.getString(Metric.METRIC_PLUGIN), EMPTY_VALUE));

                    ObjectConfigStore.getStore().updateInstanceTags(entry.getKey(), updatedObjects);

                    // Stage minimal record for bulk DB update to avoid mutating metricStore by reference
                    instanceMap.put(key, new JsonObject().put(Metric.METRIC_CONTEXT, item.getJsonObject(Metric.METRIC_CONTEXT).put(OBJECTS, updatedObjects)));
                }
            }

            future.complete(new JsonObject().put(GlobalConstants.STATUS, STATUS_SUCCEED));

            LOGGER.debug("tags are updated in instances..");
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);

            future.fail(exception);
        }

        return future.future();
    }
}

