    /**
     * Retrieves the queue size for the trace datastore engine.
     * <p>
     * This method determines the maximum number of trace events that can be queued
     * for processing by the trace datastore engine at any given time. The queue size
     * affects memory usage and throughput of trace data processing.
     * </p>
     * <p>
     * The value is determined based on the configuration key "trace.datastore.engine.queue.size".
     * If this key is present in the configuration, the method applies the following constraints:
     * <ul>
     *   <li>Minimum value: 2,000 events</li>
     *   <li>Maximum value: 50,000 events</li>
     * </ul>
     * If the configuration key is not present, a default value of 5,000 events is returned.
     * </p>
     * <p>
     * A larger queue size allows for handling higher volumes of trace data but requires
     * more memory. In high-throughput environments, consider increasing this value while
     * monitoring memory usage.
     **/
    public static int getTraceDatastoreEngineQueueSize()
    {
        if (configs.containsKey("trace.datastore.engine.queue.size"))
        {
            return Math.max(2000, Math.min(configs.getInteger("trace.datastore.engine.queue.size"), 50000));
        }
        else
        {
            return switch (getDeploymentType())
            {
                //S
                case 0 -> 5000;

                //M
                case 1 -> 8000;

                //L
                case 2 -> 10000;

                //XL
                case 3 -> 20000;

                default -> 5000;
            };
        }
    }

