public class LogCollector extends AbstractAPI
{
    public static final String LOG_COLLECTOR_NAME = "log.collector.name";
    public static final String LOG_COLLECTOR_ID = "log.collector.id";
    public static final String LOG_COLLECTOR_LOG_PARSERS = "log.collector.log.parsers";
    public static final String LOG_COLLECTOR_RUNBOOK = "log.collector.runbook";
    public static final String LOG_COLLECTOR_INTERVAL = "log.collector.interval";
    public static final String LOG_COLLECTOR_STATUS = "log.collector.status";
    public static final String LOG_COLLECTOR_UNHEALTHY_MESSAGE = "log.collector.unhealthy.message";
    public static final String LOG_COLLECTOR_STATE = "log.collector.state";
    public static final String LOG_COLLECTOR_STATE_HEALTHY = "healthy";
    public static final String LOG_COLLECTOR_STATE_UNHEALTHY = "unhealthy";


    private static final Logger LOGGER = new Logger(LogCollector.class, MOTADATA_API, "Log Collector API");

    public LogCollector()
    {
        super("log-collectors", LogCollectorConfigStore.getStore(), new Logger(LogCollector.class, MOTADATA_API, "Log Collector API"));
    }

    @Override
    public void init(Router router)
    {
        try
        {
            super.init(router);
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

    @Override
    protected void getAll(RoutingContext routingContext)
    {
        try
        {
            var items = LogCollectorConfigStore.getStore().getItems();

            for (var index = 0; index < items.size(); index++)
            {
                var item = items.getJsonObject(index);

                var status = LogCollectorConfigStore.getStore().getStatus(item.getLong(ID));

                if (LOG_COLLECTOR_STATE_HEALTHY.equalsIgnoreCase(status) || UNKNOWN.equalsIgnoreCase(status))
                {
                    item.put(LOG_COLLECTOR_STATUS, status);
                }
                else
                {
                    item.put(LOG_COLLECTOR_STATUS, LOG_COLLECTOR_STATE_UNHEALTHY);

                    item.put(LOG_COLLECTOR_UNHEALTHY_MESSAGE, status);
                }
            }

            this.send(routingContext, new JsonObject().put(RESPONSE_CODE, HttpStatus.SC_OK)
                    .put(GlobalConstants.STATUS, GlobalConstants.STATUS_SUCCEED)
                    .put(GlobalConstants.RESULT, items));

        }
        catch (Exception exception)
        {
            LOGGER.error(exception);

            this.send(routingContext, new JsonObject().put(GlobalConstants.STATUS, GlobalConstants.STATUS_FAIL)
                    .put(RESPONSE_CODE, SC_INTERNAL_SERVER_ERROR)
                    .put(GlobalConstants.ERROR, CommonUtil.formatStackTrace(exception.getStackTrace()))
                    .put(GlobalConstants.ERROR_CODE, ErrorCodes.ERROR_CODE_INTERNAL_ERROR)
                    .put(GlobalConstants.MESSAGE, String.format(INTERNAL_SERVER_EXCEPTION, DEFAULT_ERROR_MESSAGE)));
        }
    }


    //After create we will assign log parsers to all the runbook entities
    @Override
    protected Future<Void> afterCreate(JsonObject event, RoutingContext routingContext)
    {
        try
        {
            this.send(routingContext, event);

            var item = LogCollectorConfigStore.getStore().getItem(event.getLong(ID));

            var runbook = RunbookPluginConfigStore.getStore().getItem(item.getLong(LOG_COLLECTOR_RUNBOOK));

            var parsers = item.getJsonArray(LOG_COLLECTOR_LOG_PARSERS);

            var entities = new JsonArray();

            if (runbook.getString(RunbookPlugin.RUNBOOK_PLUGIN_ENTITY_TYPE).equalsIgnoreCase(APIConstants.Entity.OBJECT.getName()))
            {
                var objects = ObjectConfigStore.getStore().getItems(runbook.getJsonArray(RunbookPlugin.RUNBOOK_PLUGIN_ENTITIES));

                if (objects != null && !objects.isEmpty())
                {
                    for (var index = 0; index < objects.size(); index++)
                    {
                        entities.add(objects.getJsonObject(index).getString(OBJECT_IP));
                    }
                }
            }
            else if (runbook.getString(RunbookPlugin.RUNBOOK_PLUGIN_ENTITY_TYPE).equalsIgnoreCase(APIConstants.Entity.GROUP.getName()))
            {
                var items = ObjectConfigStore.getStore().getItems(ObjectConfigStore.getStore().getItemsByGroups(runbook.getJsonArray(RunbookPlugin.RUNBOOK_PLUGIN_ENTITIES)));

                if (items != null)
                {
                    var types = Runbook.getObjectTypesByRunbookPluginType(Runbook.RunbookPluginType.valueOf(runbook.getString(RUNBOOK_PLUGIN_TYPE)));

                    for (var index = 0; index < items.size(); index++)
                    {
                        // for custom script types is null and for powershell, ssh, jdbc and snmp scripts will qualify only same objects types
                        if (types == null || types.contains(items.getJsonObject(index).getString(AIOpsObject.OBJECT_TYPE)))
                        {
                            entities.add(items.getJsonObject(index).getString(OBJECT_IP));
                        }
                    }
                }
            }
            else if (runbook.getString(RunbookPlugin.RUNBOOK_PLUGIN_ENTITY_TYPE).equalsIgnoreCase(EVENT_SOURCE))
            {
                for (var entity : runbook.getJsonArray(RunbookPlugin.RUNBOOK_PLUGIN_ENTITIES))
                {
                    if (entity != null && !CommonUtil.getString(entity).isEmpty())
                    {
                        entities.add(CommonUtil.getString(entity));
                    }
                }
            }

            if (parsers != null && !parsers.isEmpty())
            {
                LOGGER.info(String.format("Entities qualified: %s, log parsers: %s ", entities, parsers));

                for (var index = 0; index < entities.size(); index++)
                {

                    Bootstrap.vertx().eventBus().send(EVENT_CHANGE_LOCAL_NOTIFICATION,
                            item.put(CHANGE_NOTIFICATION_TYPE, ChangeNotificationType.ASSIGN_LOG_PARSER)
                                    .put(OBJECT_IP, entities.getString(index))
                                    .put(ASSIGNED_LOG_PARSERS, parsers));
                }
            }


            Bootstrap.vertx().eventBus().publish(EventBusConstants.EVENT_CHANGE_NOTIFICATION, item.put(EventBusConstants.CHANGE_NOTIFICATION_TYPE, ChangeNotificationType.ADD_LOG_COLLECTOR.name()));

        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }

        return Future.succeededFuture();
    }

    @Override
    protected Future<JsonObject> afterUpdate(JsonObject entity, RoutingContext routingContext)
    {
        Bootstrap.vertx().eventBus().publish(EventBusConstants.EVENT_CHANGE_NOTIFICATION, routingContext.body().asJsonObject().put(EventBusConstants.CHANGE_NOTIFICATION_TYPE, ChangeNotificationType.UPDATE_LOG_COLLECTOR.name()));

        return super.afterUpdate(entity, routingContext);
    }

    @Override
    protected Future<Void> afterDelete(JsonObject entity, RoutingContext routingContext)
    {
        this.send(routingContext, entity);

        Bootstrap.vertx().eventBus().publish(EventBusConstants.EVENT_CHANGE_NOTIFICATION, entity.put(EventBusConstants.CHANGE_NOTIFICATION_TYPE, ChangeNotificationType.DELETE_LOG_COLLECTOR.name()));

        return Future.succeededFuture();
    }
}

