    /**
     * Retrieves event sources filtered by group type and enriches them with monitor host names.
     *
     * This method performs the following operations:
     * 1. Fetches event sources from EventSourceConfigStore based on the provided group.type parameter
     * 2. For each event source, attempts to resolve the corresponding monitor object from ObjectConfigStore
     * 3. If a monitor is found, enriches the event source with the monitor's display name (event.host)
     * 4. Returns the enriched event sources or original sources if no objects are provisioned
     *
     * The enrichment process helps the UI display meaningful monitor names instead of IP addresses,
     * while maintaining the original event.source for internal query building operations.
     *
     */
    private void getSources(RoutingContext routingContext)
    {
        try
        {
            var items = EventSourceConfigStore.getStore().getItemsByMultiValueField(EVENT_TYPE, routingContext.request().getParam("group.type"));

            if(CommonUtil.isNotNullOrEmpty(items) && CommonUtil.isNotNullOrEmpty(ObjectConfigStore.getStore().getItems()))
            {
                for (var index = 0; index < items.size(); index++)
                {
                    var item = items.getJsonObject(index);

                    var id = ObjectConfigStore.getStore().getItemByIP(item.getString(EVENT_SOURCE));

                    if(id != null)
                    {
                        item.put(EVENT_HOST, ObjectConfigStore.getStore().getItem(id).getString(AIOpsObject.OBJECT_NAME));
                    }
                }

                send(routingContext, new JsonObject().put(RESPONSE_CODE, HttpStatus.SC_OK).put(GlobalConstants.STATUS, STATUS_SUCCEED).put(GlobalConstants.RESULT, items));
            }
            else
            {
                send(routingContext, new JsonObject().put(RESPONSE_CODE, HttpStatus.SC_OK).put(GlobalConstants.STATUS, STATUS_SUCCEED).put(GlobalConstants.RESULT, items));
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);

            //will always send sources...
            send(routingContext, new JsonObject().put(RESPONSE_CODE, HttpStatus.SC_OK).put(GlobalConstants.STATUS, STATUS_SUCCEED).put(GlobalConstants.RESULT, EventSourceConfigStore.getStore().getItemsByMultiValueField(EVENT_TYPE, routingContext.request().getParam("group.type"))));
        }
    }

