            else if (groupType.equalsIgnoreCase(VisualizationConstants.VisualizationDataSource.TRACE_METRIC.getName()))
            {
                var futures = new ArrayList<Future<JsonObject>>();

                var metricFuture = Promise.<JsonObject>promise();

                var eventFuture = Promise.<JsonObject>promise();

                futures.add(metricFuture.future());

                futures.add(eventFuture.future());

                Bootstrap.vertx().eventBus().<JsonObject>request(EventBusConstants.EVENT_METRIC_COLUMN_MAPPER_QUERY, "", reply ->
                {
                    if (reply.succeeded())
                    {
                        var event = reply.result().body();

