public class SLOCycle extends AbstractAPI
{
    private static final Logger LOGGER = new Logger(SLOCycle.class, GlobalConstants.MOTADATA_API, "SLO Cycle API");

    public SLOCycle()
    {
        super("slo-cycles", SLOCycleConfigStore.getStore(), LOGGER);
    }

    public static final String SLO_CYCLE_NAME = "slo.cycle.name";
    public static final String SLO_CYCLE_START_TIME = "slo.cycle.start.time"; // Epoch seconds of the starting of the day (ex. for 8-8-2025 it will be 1751932800)
    public static final String SLO_CYCLE_END_TIME = "slo.cycle.end.time"; // Epoch seconds of the ending of the cycle
    public static final String SLO_CYCLE_ID = "slo.cycle.id"; // FK to SLOCycleConfigStore
    public static final String SLO_CYCLE_TOTAL_DURATION = "slo.cycle.total.duration";
    public static final String SLO_CYCLE_ACCEPTABLE_VIOLATION_TIME = "slo.cycle.acceptable.violation.time";
    public static final String SLO_CYCLE_NOTIFICATION_STATUS = "slo.cycle.notification.status";
    public static final String SLO_CYCLE_PENALTY_AMOUNT = "slo.cycle.penalty.amount";
    public static final String SLO_CYCLE_CONTRACT_AMOUNT = "slo.cycle.contract.amount";

    @Override
    public void init(Router router)
    {
        try
        {
            super.init(router, Set.of(REQUEST_CREATE, REQUEST_DELETE));

            router.put("/" + endpoint + "/:id/calculate-penalty").handler(this::calculatePenalty);
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

    private void calculatePenalty(RoutingContext routingContext)
    {
        try
        {
            var id = CommonUtil.getLong(routingContext.request().getParam(GlobalConstants.ID));

            if (id != GlobalConstants.DUMMY_ID)
            {
                var requestBody = routingContext.body().asJsonObject();

                var achievedPercentage = requestBody.getFloat(SLOConstants.ACHIEVED_PERCENT);

                var penaltyProfileId = requestBody.getLong(PenaltyProfile.PENALTY_PROFILE_ID);

                if (achievedPercentage != null && penaltyProfileId != null)
                {
                    var penaltyProfile = PenaltyProfileConfigStore.getStore().getItem(penaltyProfileId);

                    if (penaltyProfile != null && !penaltyProfile.isEmpty())
                    {
                        var currency = penaltyProfile.getString(PenaltyProfile.PENALTY_PROFILE_CURRENCY, EMPTY_VALUE);

                        var penaltyAmount = SLOConstants.
                                getCurrencyFormattedValue(SLOConstants.getPenaltyAmount(achievedPercentage,
                                        penaltyProfile.getDouble(PenaltyProfile.PENALTY_PROFILE_CONTRACT_AMOUNT, 0.0),
                                        penaltyProfile.getJsonArray(PenaltyProfile.PENALTY_PROFILE_SLABS)), currency);

                        Bootstrap.configDBService().update(DBConstants.TBL_SLO_CYCLE,
                                new JsonObject().put(DBConstants.FIELD_NAME, ID).put(VALUE, id),
                                new JsonObject()
                                        .put(PenaltyProfile.PENALTY_PROFILE_ID, penaltyProfileId)
                                        .put(SLOCycle.SLO_CYCLE_PENALTY_AMOUNT, penaltyAmount)
                                        .put(SLOCycle.SLO_CYCLE_CONTRACT_AMOUNT,
                                                SLOConstants.getCurrencyFormattedValue(penaltyProfile.getDouble(PenaltyProfile.PENALTY_PROFILE_CONTRACT_AMOUNT, 0.0), currency))
                                , DEFAULT_USER, SYSTEM_REMOTE_ADDRESS, result ->
                                {
                                    if (result.succeeded())
                                    {
                                        SLOCycleConfigStore.getStore().updateItem(id).onComplete(asyncResult ->
                                        {
                                            if (asyncResult.succeeded())
                                            {
                                                LOGGER.info(String.format("Penalty amount updated for SLO cycle %s is %s", id, penaltyAmount));

                                                this.send(routingContext, new JsonObject().put(RESPONSE_CODE, HttpStatus.SC_OK).put(GlobalConstants.STATUS, GlobalConstants.STATUS_SUCCEED));
                                            }
                                            else
                                            {
                                                LOGGER.error(asyncResult.cause());

                                                this.send(routingContext, new JsonObject().put(RESPONSE_CODE, HttpStatus.SC_INTERNAL_SERVER_ERROR).put(GlobalConstants.STATUS, GlobalConstants.STATUS_FAIL)
                                                        .put(GlobalConstants.MESSAGE, String.format(ErrorMessageConstants.ENTITY_UPDATE_FAILED, APIConstants.Entity.SLO_CYCLE.getName(), ErrorMessageConstants.DEFAULT_ERROR_MESSAGE)));
                                            }
                                        });
                                    }
                                    else
                                    {
                                        LOGGER.error(result.cause());

                                        this.send(routingContext, new JsonObject().put(RESPONSE_CODE, HttpStatus.SC_INTERNAL_SERVER_ERROR).put(GlobalConstants.STATUS, GlobalConstants.STATUS_FAIL)
                                                .put(GlobalConstants.MESSAGE, String.format(ErrorMessageConstants.ENTITY_UPDATE_FAILED, APIConstants.Entity.SLO_CYCLE.getName(), ErrorMessageConstants.DEFAULT_ERROR_MESSAGE)));
                                    }
                                });
                    }
                }
                else
                {
                    this.send(routingContext, new JsonObject().put(RESPONSE_CODE, HttpStatus.SC_BAD_REQUEST).put(GlobalConstants.STATUS, GlobalConstants.STATUS_FAIL)
                            .put(GlobalConstants.MESSAGE, String.format(ErrorMessageConstants.API_FIELD_REQUIRED, SLOConstants.ACHIEVED_PERCENT + " and " + PenaltyProfile.PENALTY_PROFILE_ID)));
                }
            }
        }
        catch (Exception exception)
        {
            APIUtil.sendResponse(exception, routingContext);
        }
    }
}

