public class TagRule extends AbstractAPI
{
    public static final String TAG_RULE_NAME = "tag.rule.name";
    public static final String TAG_RULE_TYPE = "tag.rule.type";
    public static final String TAG_RULE_OPERATION = "tag.rule.operation";
    public static final String TAG_RULE_TAGS = "tag.rule.tags";
    public static final String TAG_RULE_DYNAMIC_TAGS = "tag.rule.dynamic.tags";
    public static final String TAG_RULE_CONDITIONS = "tag.rule.conditions";
    public static final String TAG_RULE_TRIGGERED_TIME = "tag.rule.triggered.time";
    public static final String TAG_RULE_INCLUSIVE_CONDITION = "tag.rule.inclusive.condition";
    public static final String TAG_RULE_TEST = "tag.rule.test";
    public static final String TAG_RULE_OPERATION_ASSIGN = "Assign";
    public static final String TAG_RULE_BULK = "tag.rule.bulk";
    private static final Logger LOGGER = new Logger(TagRule.class, MOTADATA_API, "Tag Rule API");
    private static final Pattern PATTERN = Pattern.compile("(.*):\\{(\\S+)}");

    public TagRule()
    {
        super("tag-rules", TagRuleConfigStore.getStore(), LOGGER);
    }

    @Override
    public void init(Router router)
    {
        try
        {
            super.init(router);

            router.get("/" + endpoint + "/:id/references").handler(this::getReferences);

            router.post("/" + endpoint + "/bulk").handler(this::validateBulkCreate).handler(this::bulkCreate);
        }

        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }


    /*
     *  Rule can be created with 2 type of tags,
     *  Static tags and Dynamic tags.
     *   - Static tags are tags which are directly added to the rule.
     *   - Dynamic tags are tags which are added to the rule with a pattern, Dynamic tags are resolved at runtime.(example: host:{object.host})
     *
     *  Before Create we will separate this tags and store them in different fields.
     * */
    @Override
    protected Future<JsonObject> beforeCreate(RoutingContext routingContext)
    {
        var promise = Promise.<JsonObject>promise();

        try
        {
            promise.complete(setTags(routingContext));
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);

            promise.fail(exception);
        }

        return promise.future();
    }

    /*
     *  Rule can be created with 2 type of tags,
     *  Static tags and Dynamic tags.
     *   - Static tags are tags which are directly added to the rule.
     *   - Dynamic tags are tags which are added to the rule with a pattern, Dynamic tags are resolved at runtime.(example: host:{object.host})
     *
     *  Before Create we will separate this tags and store them in different fields.
     * */
    @Override
    protected Future<JsonObject> beforeUpdate(RoutingContext routingContext)
    {
        var promise = Promise.<JsonObject>promise();

        try
        {
            promise.complete(setTags(routingContext));
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);

            promise.fail(exception);
        }

        return promise.future();
    }

    /**
     * Extracts and separates static and dynamic tags from the request body.
     *
     * <p>This method expects the request body (from {@code routingContext.body().asJsonObject()})
     * to contain a JsonArray under the key {@link #TAG_RULE_TAGS}. Each element in that array
     * may be:
     * <ul>
     *   <li>a static tag (stored as-is), or</li>
     *   <li>a dynamic tag following the {@code PATTERN} (example: {@code host:{object.host}}).</li>
     * </ul>
     *
     * Behavior:
     * <ol>
     *   <li>Iterate over the incoming tags.</li>
     *   <li>If a tag matches {@code PATTERN}, extract the left-hand side as the dynamic tag key
     *       and the inner token as the dynamic tag value and add to {@code TAG_RULE_DYNAMIC_TAGS}.</li>
     *   <li>Otherwise collect the tag as a static tag and resolve it using
     *       {@link TagConfigStore#getStore()#addItems(JsonArray, String, String)} which returns
     *       the stored representation (hash/ids) for static tags.</li>
     *   <li>Update the original request body in-place with resolved static tags and dynamic tags.</li>
     * </ol>
     *
     * The returned JsonObject is the same object as the request body (modified in-place) and is
     * annotated as non-null.
     *
     * @param routingContext Vert.x routing context containing the request body
     * @return modified request body JsonObject with {@code TAG_RULE_TAGS} and {@code TAG_RULE_DYNAMIC_TAGS} populated
     */
    @NotNull
    private static JsonObject setTags(RoutingContext routingContext)
    {
        var dynamicTags = new JsonObject();

        var staticTags = new JsonArray();

        var requestBody = routingContext.body().asJsonObject();

        var tags = requestBody.getJsonArray(TAG_RULE_TAGS);

        if (!tags.isEmpty())
        {
            for (var index = 0; index < tags.size(); index++)
            {
                var tag = tags.getString(index);

                var matcher = PATTERN.matcher(tag);

                if (matcher.find() && matcher.groupCount() == 2)
                {
                    if (matcher.group(1) != null && !matcher.group(1).isEmpty() && matcher.group(2) != null && !matcher.group(2).isEmpty())
                    {
                        dynamicTags.put(matcher.group(1), matcher.group(2));
                    }
                }
                else
                {
                    staticTags.add(tag);
                }
            }
        }

        requestBody.put(TAG_RULE_TAGS, TagConfigStore.getStore().addItems(staticTags, Tag.TagType.OBJECT.getName(), DBConstants.ENTITY_TYPE_USER));

        requestBody.put(TAG_RULE_DYNAMIC_TAGS, dynamicTags);

        return requestBody;
    }


    /*
     *  Will return the count of entities tagged by the rule.
     * */
    @Override
    protected Future<JsonObject> getEntityCountPreHook(JsonObject response)
    {
        var future = Promise.<JsonObject>promise();

        try
        {
            var items = TagRuleConfigStore.getStore().getItems();

            var futures = new ArrayList<Future<String>>();

            for (var index = 0; index < items.size(); index++)
            {
                var item = items.getJsonObject(index);

                var promise = Promise.<String>promise();

                futures.add(promise.future());

                Bootstrap.vertx().eventBus().<JsonObject>request(EVENT_TAG_RULE_RUN, item.put(TagRule.TAG_RULE_TEST, true), reply ->
                {
                    try
                    {
                        if (reply.succeeded())
                        {
                            var result = reply.result().body();

                            if (result.containsKey(STATUS) && result.getString(STATUS).equalsIgnoreCase(STATUS_SUCCEED))
                            {
                                promise.complete(item.getLong(ID) + HASH_SEPARATOR + result.getJsonArray(RESULT).size());
                            }
                            else
                            {
                                promise.complete(item.getLong(ID) + HASH_SEPARATOR + 0);
                            }
                        }
                        else
                        {
                            promise.complete(item.getLong(ID) + HASH_SEPARATOR + 0);
                        }
                    }
                    catch (Exception exception)
                    {
                        LOGGER.error(exception);

                        promise.complete(item.getLong(ID) + HASH_SEPARATOR + 0);
                    }
                });
            }

            Future.all(futures).onComplete(asyncResult ->
            {
                if (asyncResult.succeeded())
                {
                    var result = new JsonObject();

                    for (var item : asyncResult.result().list())
                    {
                        var tokens = CommonUtil.getString(item).split(HASH_SEPARATOR);

                        result.put(tokens[0], CommonUtil.getInteger(tokens[1]));
                    }

                    future.complete(result);
                }
                else
                {
                    LOGGER.error(asyncResult.cause());
                }
            });
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }

        return future.future();
    }

    @Override
    protected Future<Void> afterGetAll(JsonArray items, RoutingContext routingContext)
    {
        try
        {
            for (var index = 0; index < items.size(); index++)
            {
                resolveTags(items.getJsonObject(index));
            }

            this.send(routingContext, new JsonObject().put(RESPONSE_CODE, HttpStatus.SC_OK).put(GlobalConstants.STATUS, STATUS_SUCCEED).put(GlobalConstants.RESULT, items));
        }
        catch (Exception exception)
        {
            APIUtil.sendResponse(exception, routingContext);
        }

        return Future.succeededFuture();
    }

    @Override
    protected Future<Void> afterGet(JsonObject item, RoutingContext routingContext)
    {
        try
        {
            resolveTags(item);

            Bootstrap.vertx().eventBus().<JsonObject>request(EVENT_TAG_RULE_RUN, item.put(TagRule.TAG_RULE_TEST, true), reply ->
            {
                try
                {
                    if (reply.succeeded())
                    {
                        var result = reply.result().body();

                        if (result.containsKey(STATUS) && result.getString(STATUS).equalsIgnoreCase(STATUS_SUCCEED))
                        {
                            this.send(routingContext, new JsonObject().put(RESPONSE_CODE, HttpStatus.SC_OK).put(STATUS, STATUS_SUCCEED).put(GlobalConstants.RESULT, item.put(ENTITY_PROPERTY_COUNT, result.getJsonArray(RESULT).size())));
                        }
                        else
                        {
                            this.send(routingContext, new JsonObject().put(RESPONSE_CODE, HttpStatus.SC_OK).put(STATUS, STATUS_SUCCEED).put(GlobalConstants.RESULT, item.put(ENTITY_PROPERTY_COUNT, 0)));
                        }
                    }
                    else
                    {
                        this.send(routingContext, new JsonObject().put(RESPONSE_CODE, HttpStatus.SC_OK).put(STATUS, STATUS_SUCCEED).put(GlobalConstants.RESULT, item.put(ENTITY_PROPERTY_COUNT, 0)));
                    }
                }
                catch (Exception exception)
                {
                    LOGGER.error(exception);

                    this.send(routingContext, new JsonObject().put(RESPONSE_CODE, HttpStatus.SC_OK).put(STATUS, STATUS_SUCCEED).put(GlobalConstants.RESULT, item.put(ENTITY_PROPERTY_COUNT, 0)));
                }
            });
        }

        catch (Exception exception)
        {
            APIUtil.sendResponse(exception, routingContext);
        }

        return Future.succeededFuture();
    }

    //resolve tags from hashcode to actual tags
    private void resolveTags(JsonObject item)
    {
        //resolve static tags
        var items = TagConfigStore.getStore().getItems(item.getJsonArray(TAG_RULE_TAGS));

        //resolve dynamic tags
        if (item.containsKey(TAG_RULE_DYNAMIC_TAGS) && !item.getJsonObject(TAG_RULE_DYNAMIC_TAGS).isEmpty())
        {
            for (var key : item.getJsonObject(TAG_RULE_DYNAMIC_TAGS).getMap().entrySet())
            {
                items.add(key.getKey() + ":{" + key.getValue() + "}");
            }
        }

        item.put(TAG_RULE_TAGS, items);
    }


    /**
     * Validate bulk create payload and normalize request body.
     *
     * <p>Expected input:
     * <pre>
     * {
     *   "tag.rule.bulk": [ { ... }, { ... } ]
     * }
     * </pre>
     *
     * Behavior:
     * <ul>
     *   <li>Checks that {@code TAG_RULE_BULK} exists and is a non-empty {@link JsonArray}.</li>
     *   <li>Loads the entity schema for the current endpoint to determine the display/title for the
     *       {@code TAG_RULE_NAME} property (used in unique checks).</li>
     *   <li>Validates each array element is a non-empty {@link JsonObject} and enqueues unique-name checks
     *       via {@link APIUtil#testUniqueRule} when {@code TAG_RULE_NAME} is present.</li>
     *   <li>Normalizes the request body to a {@link JsonObject} containing a single key {@code "params"}
     *       which holds the original array (i.e. {@code { "params": [ ... ] }}), by overwriting the
     *       routing context body using {@link io.vertx.core.buffer.Buffer}.</li>
     *   <li>If no unique checks are required, the handler chain proceeds immediately by calling
     *       {@code routingContext.next()}. Otherwise it waits for all uniqueness checks to complete
     *       and sends any error response returned by those checks or proceeds on success.</li>
     * </ul>
     *
     *
     * @param routingContext Vert.x routing context containing the request body and user information.
     */
    private void validateBulkCreate(RoutingContext routingContext)
    {
        try
        {
            var context = routingContext.body().asJsonObject();

            var schema = CommonUtil.getEntitySchema(endpoint);

            if(schema != null && !schema.isEmpty() && context.containsKey(TAG_RULE_BULK) && !context.getJsonArray(TAG_RULE_BULK).isEmpty())
            {
                var rules = context.getJsonArray(TAG_RULE_BULK);

                var title = TAG_RULE_NAME; // fallback

                var futures = new ArrayList<Future<JsonObject>>();

                var properties = schema.getJsonArray(APIConstants.ENTITY_PROPERTY);

                if (properties != null)
                {
                    for (var index = 0; index < properties.size(); index++)
                    {
                        var param = properties.getJsonObject(index);

                        if (TAG_RULE_NAME.equals(param.getString(APIConstants.ENTITY_PROPERTY_NAME)))
                        {
                            title = param.getString(APIConstants.ENTITY_PROPERTY_TITLE, TAG_RULE_NAME);

                            break;
                        }
                    }
                }

                // Single-pass: validate shape and enqueue UNIQUE checks
                for (var i = 0; i < rules.size(); i++)
                {
                    var item = rules.getJsonObject(i);

                    if (item.containsKey(TAG_RULE_NAME))
                    {
                        futures.add(APIUtil.testUniqueRule(routingContext, REQUEST_CREATE, TAG_RULE_NAME, title, item, this.configStore));
                    }
                }

                // Normalize request body to JsonObject with "params"
                routingContext.setBody(Buffer.buffer(new JsonObject().put(REQUEST_PARAMS, rules).encode()));

                if (futures.isEmpty())
                {
                    routingContext.next();
                }
                else
                {
                    Future.all(futures).onComplete(async ->
                    {
                        if (async.succeeded())
                        {
                            for (var obj : async.result().list())
                            {
                                var res = (JsonObject) obj;

                                if (res != null && !res.isEmpty())
                                {
                                    this.send(routingContext, res);

                                    return;
                                }
                            }
                            routingContext.next();
                        }
                        else
                        {
                            this.send(routingContext, new JsonObject()
                                    .put(RESPONSE_CODE, HttpStatus.SC_INTERNAL_SERVER_ERROR)
                                    .put(STATUS, STATUS_FAIL)
                                    .put(MESSAGE, String.format(ErrorMessageConstants.INTERNAL_SERVER_EXCEPTION, ErrorMessageConstants.DEFAULT_ERROR_MESSAGE)));
                        }
                    });
                }
            }
            else
            {
                this.send(routingContext, new JsonObject()
                        .put(RESPONSE_CODE, HttpStatus.SC_BAD_REQUEST)
                        .put(STATUS, STATUS_FAIL)
                        .put(MESSAGE, ErrorMessageConstants.API_INVALID_INPUT_PARAMETERS));
                return;
            }
        }
        catch (Exception exception)
        {
            APIUtil.sendResponse(exception, routingContext);
        }
    }

    /**
     * Handle bulk create for TagRule.
     *
     * <p>Accepts either:
     * <ul>
     *   <li>a raw JSON array of items, or</li>
     *   <li>a JSON object with key {@code "params"} containing the array.</li>
     * </ul>
     *
     * <p>For each item this method:
     * <ol>
     *   <li>Separates static and dynamic tags (static tags are resolved via {@link TagConfigStore}).</li>
     *   <li>Stores dynamic tags in {@code TAG_RULE_DYNAMIC_TAGS} and resolved static tag ids in {@code TAG_RULE_TAGS}.</li>
     *   <li>Marks the record as a user entity by setting {@code DBConstants.FIELD_TYPE} to {@code DBConstants.ENTITY_TYPE_USER}.</li>
     * </ol>
     *
     * <p>All prepared records are persisted with the configuration DB service. On success the configuration
     * store is updated and a success response containing created ids is returned. On failure an error
     * response is sent.
     *
     * @param routingContext Vert.x routing context containing the request body, user and response objects
     */
    private void bulkCreate(RoutingContext routingContext)
    {
        try
        {
            var schema = CommonUtil.getEntitySchema(endpoint);

            if (schema != null)
            {
                var params = routingContext.body().asJsonObject().getJsonArray(REQUEST_PARAMS);

                var records = new JsonArray();

                for (var i = 0; i < params.size(); i++)
                {
                    var item = params.getJsonObject(i);

                    // Separate static and dynamic tags similar to beforeCreate
                    var dynamicTags = new JsonObject();

                    var staticTags = new JsonArray();

                    var tags = item.getJsonArray(TAG_RULE_TAGS, new JsonArray());

                    for (var tagIndex = 0; tagIndex < tags.size(); tagIndex++)
                    {
                        var tag = CommonUtil.getString(tags.getValue(tagIndex));

                        var matcher = PATTERN.matcher(tag);

                        if (matcher.find() && matcher.groupCount() == 2)
                        {
                            if (matcher.group(1) != null && !matcher.group(1).isEmpty() && matcher.group(2) != null && !matcher.group(2).isEmpty())
                            {
                                dynamicTags.put(matcher.group(1), matcher.group(2));
                            }
                        }
                        else
                        {
                            staticTags.add(tag);
                        }
                    }

                    item.put(TAG_RULE_TAGS, TagConfigStore.getStore().addItems(staticTags, Tag.TagType.OBJECT.getName(), DBConstants.ENTITY_TYPE_USER));

                    item.put(TAG_RULE_DYNAMIC_TAGS, dynamicTags).put(DBConstants.FIELD_TYPE, DBConstants.ENTITY_TYPE_USER);

                    records.add(item);
                }

                Bootstrap.configDBService().saveAll(schema.getString(APIConstants.ENTITY_TABLE), records, routingContext.user().principal().getString(User.USER_NAME), routingContext.request().remoteAddress().host(), result ->
                {
                    if (result.succeeded())
                    {
                        var ids = result.result();

                        this.configStore.updateItems(ids).onComplete(async ->
                                this.send(routingContext, new JsonObject()
                                        .put(RESPONSE_CODE, HttpStatus.SC_OK)
                                        .put(STATUS, STATUS_SUCCEED)
                                        .put(REQUEST_PARAM_IDS, ids)
                                        .put(MESSAGE, String.format(InfoMessageConstants.ENTITY_CREATED, schema.getString(APIConstants.ENTITY_NAME)))));
                    }
                    else
                    {
                        this.send(routingContext, new JsonObject()
                                .put(RESPONSE_CODE, HttpStatus.SC_INTERNAL_SERVER_ERROR)
                                .put(STATUS, STATUS_FAIL)
                                .put(MESSAGE, String.format(ErrorMessageConstants.ENTITY_CREATE_FAILED, schema.getString(APIConstants.ENTITY_NAME), result.cause().getMessage()))
                                .put(ERROR_CODE, ErrorCodes.ERROR_CODE_INTERNAL_ERROR)
                                .put(ERROR, CommonUtil.formatStackTrace(result.cause().getStackTrace())));
                    }
                });
            }
            else
            {
                this.send(routingContext, new JsonObject()
                        .put(RESPONSE_CODE, HttpStatus.SC_BAD_REQUEST)
                        .put(STATUS, STATUS_FAIL)
                        .put(MESSAGE, String.format(ErrorMessageConstants.SCHEMA_FILE_NOT_FOUND, endpoint)));
                return;
            }
        }
        catch (Exception exception)
        {
            APIUtil.sendResponse(exception, routingContext);
        }
    }
}

