    /**
     * Deletes the agent and its associated configurations, cache, and status from the system.
     * <p>
     * This method performs a full cleanup of an agent identified by its ID:
     * <ul>
     *     <li>Deletes the agent record from the configuration database.</li>
     *     <li>Removes related entries from in-memory caches:
     *         <ul>
     *             <li>{@link TraceCacheStore}</li>
     *             <li>{@link AgentCacheStore}</li>
     *             <li>{@link ObjectConfigStore}</li>
     *             <li>{@link TraceServiceConfigStore}</li>
     *         </ul>
     *     </li>
     *     <li>Publishes an agent deletion event to notify the metadata manager.</li>
     *     <li>If applicable, updates the license cache based on metric or trace configurations.</li>
     *     <li>Unprovisions the associated object and marks it as unavailable.</li>
     *     <li>Sends an HTTP error response and fails the promise if deletion fails.</li>
     * </ul>
     *
     * @param id             the ID of the agent to delete.
     * @param routingContext the context of the current HTTP request, used for user and session information.
     * @param agent          a {@link JsonObject} containing the agent's configuration data.
     * @return a {@link Future} that completes when the delete operation has finished.
     */
    private Future<Void> delete(long id, RoutingContext routingContext, JsonObject agent)
    {
        var promise = Promise.<Void>promise();

        Bootstrap.configDBService().delete(TBL_AGENT,
                new JsonObject().put(DBConstants.FIELD_NAME, GlobalConstants.ID).put(VALUE, CommonUtil.getLong(id)), routingContext.user().principal().getString(User.USER_NAME), routingContext.request().remoteAddress().host(),
                asyncResult ->
                {
                    try
                    {
                        if (asyncResult.succeeded() && !asyncResult.result().isEmpty())
                        {
                            this.configStore.deleteItem(CommonUtil.getLong(id));

                            // Removing all the APM service related cache when we delete agent
                            TraceCacheStore.getStore().remove(CommonUtil.getLong(id));

                            AgentCacheStore.getStore().deleteItem(CommonUtil.getLong(id));

                            var item = ObjectConfigStore.getStore().getItemByAgentId(CommonUtil.getLong(id));

                            TraceServiceConfigStore.getStore().remove(item.getString(OBJECT_IP));

                            AgentConstants.publishEvent(new JsonObject().put(EventBusConstants.EVENT_TOPIC, EventBusConstants.MOTADATA_MANAGER_TOPIC).put(EVENT_TYPE, EventBusConstants.EVENT_AGENT_DELETE).put(ID, CommonUtil.getLong(id))
                                    .put(SESSION_ID, routingContext.user().principal().getString(SESSION_ID)).put(AGENT_DISABLE, YES)
                                    .put(USER_NAME, routingContext.user().principal().getString(USER_NAME))
                                    .put(Agent.AGENT_UUID, agent.getString(AGENT_UUID)), LOGGER);

                            var configs = new JsonObject(agent.getString(AGENT_CONFIGS));

                            if (YES.equalsIgnoreCase(configs.getJsonObject(AGENT).getString(METRIC_AGENT_STATUS)))
                            {
                                LicenseCacheStore.getStore().update(NMSConstants.AGENTS, false);
                            }

                            if (item != null)
                            {

                                //unprovision object
                                Bootstrap.vertx().eventBus().send(EVENT_OBJECT_UNPROVISION, item);

                                //mark availability as down after agent deleted
                                ObjectStatusCacheStore.getStore().updateItem(item.getLong(ID), STATUS_DOWN, DateTimeUtil.currentSeconds());

                                TraceCacheStore.getStore().removeSource(item.getString(OBJECT_IP));
                            }

                            if (configs.containsKey(Agent.AGENT_TRACE))
                            {
                                LicenseCacheStore.getStore().update(NMSConstants.TRACE_SERVICES, configs.getJsonObject(Agent.AGENT_TRACE).size(),  false);
                            }

                            promise.complete();
                        }
                        else
                        {
                            this.send(routingContext, new JsonObject().put(RESPONSE_CODE, HttpStatus.SC_INTERNAL_SERVER_ERROR)
                                    .put(GlobalConstants.STATUS, STATUS_FAIL)
                                    .put(GlobalConstants.MESSAGE, String.format(ErrorMessageConstants.ENTITY_DELETE_FAILED, Entity.AGENT.getName(), asyncResult.failed() ? asyncResult.cause().getMessage() : UNKNOWN))
                                    .put(ERROR_CODE, ErrorCodes.ERROR_CODE_INTERNAL_ERROR)
                                    .put(GlobalConstants.ERROR, asyncResult.failed() ? CommonUtil.formatStackTrace(asyncResult.cause().getStackTrace()) : UNKNOWN));

                            promise.fail(asyncResult.failed() ? asyncResult.cause().getMessage() : UNKNOWN);
                        }
                    }
                    catch (Exception exception)
                    {
                        LOGGER.error(exception);

                        promise.fail(exception);
                    }
                });

        return promise.future();
    }
