public class Query extends AbstractAPI
{
    private static final Logger LOGGER = new Logger(Query.class, GlobalConstants.MOTADATA_API, "Query API");

    public Query()
    {
        super("query", null, LOGGER);
    }

    @Override
    public void init(Router router)
    {
        try
        {
            router.get("/visualization/:id").handler(this::executeVisualizationQuery);

            router.post("/visualization").handler(this::executeVisualizationQueryByContext);

            router.post("/metric/histogram").handler(this::executeHistogramQuery);

            router.post("/metric/aggregations").handler(this::executeAggregationQuery);

            router.get("/objects").handler(this::getObjects);

            router.get("/objects/unhealthy-monitors").handler(this::getUnhealthyMonitors);

            router.get("/objects/:id/status").handler(this::getObjectStatus);

            router.get("/objects/:id/poll-info").handler(this::getPollInfo);

            router.get("/objects/:id/instances").handler(this::getInstances);

            router.get("/objects/instances").handler(this::getInstanceKeys);

            router.get("/objects/:id/group").handler(this::getObjectsByGroup);

            router.get("/objects/tag").handler(this::getObjectsByTag);

            router.get("/objects/status").handler(this::getObjectsByStatus);

            router.get("/objects/severity").handler(this::getObjectsBySeverity);
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

    private void getObjects(RoutingContext routingContext)
    {
        try
        {
            var user = UserConfigStore.getStore().getItem(routingContext.user().principal().getLong(ID));

            if (routingContext.request().params().contains(FILTER))
            {
                var requestParameters = JsonObject.mapFrom(Json.decodeValue(routingContext.request().getParam(FILTER)));

                if (requestParameters != null)
                {
                    if(requestParameters.containsKey(KEY) && requestParameters.containsKey(VALUE) && Tag.TAG.equalsIgnoreCase(requestParameters.getString(KEY)))
                    {
                        var items = ObjectConfigStore.getStore().getItems(ObjectConfigStore.getStore().getItemsByUserProfile(routingContext.user().principal().getLong(ID)));

                        var filteredObjects = new JsonArray();

                        for (var index = 0; index < items.size(); index++) {

                            var item = items.getJsonObject(index);

                            if (item.getJsonArray(AIOpsObject.OBJECT_TAGS) != null && TagConfigStore.getStore().getItems(item.getJsonArray(AIOpsObject.OBJECT_TAGS)).stream().anyMatch(requestParameters.getJsonArray(VALUE)::contains))
                            {
                                filteredObjects.add(item);
                            }

                        }

                        this.send(routingContext, new JsonObject().put(RESPONSE_CODE, HttpStatus.SC_OK).put(GlobalConstants.STATUS, GlobalConstants.STATUS_SUCCEED)
                                .put(GlobalConstants.RESULT, filteredObjects));
                    }
                    else if (requestParameters.containsKey(KEY) && requestParameters.containsKey(VALUE))
                    {

                        this.send(routingContext, new JsonObject().put(RESPONSE_CODE, HttpStatus.SC_OK).put(GlobalConstants.STATUS, GlobalConstants.STATUS_SUCCEED)
                                .put(GlobalConstants.RESULT, ObjectConfigStore.getStore().getItems(ObjectConfigStore.getStore().getItemsByUserProfile(routingContext.user().principal().getLong(ID), requestParameters.getString(KEY), requestParameters.getJsonArray(VALUE)))));
                    }
                    else
                    {
                        this.send(routingContext, new JsonObject().put(RESPONSE_CODE, HttpStatus.SC_BAD_REQUEST)
                                .put(GlobalConstants.STATUS, GlobalConstants.STATUS_FAIL)
                                .put(ERROR_CODE, ErrorCodes.ERROR_CODE_BAD_REQUEST)
                                .put(GlobalConstants.MESSAGE, ErrorMessageConstants.API_INVALID_INPUT_PARAMETERS));
                    }
                }
                else
                {
                    this.send(routingContext, new JsonObject().put(RESPONSE_CODE, HttpStatus.SC_BAD_REQUEST)
                            .put(GlobalConstants.STATUS, GlobalConstants.STATUS_FAIL)
                            .put(ERROR_CODE, ErrorCodes.ERROR_CODE_BAD_REQUEST)
                            .put(GlobalConstants.MESSAGE, ErrorMessageConstants.API_INVALID_INPUT_PARAMETERS));
                }
            }
            else
            {
                this.send(routingContext, new JsonObject().put(RESPONSE_CODE, HttpStatus.SC_OK).put(GlobalConstants.STATUS, GlobalConstants.STATUS_SUCCEED)
                        .put(GlobalConstants.RESULT, ObjectConfigStore.getStore().getItems(ObjectConfigStore.getStore().getItemsByUserProfile(user.getLong(ID)))));
            }
        }
        catch (Exception exception)
        {
            APIUtil.sendResponse(exception, routingContext);
        }
    }

    private void getUnhealthyMonitors(RoutingContext routingContext)
    {
        try
        {
            NMSConstants.getFaultyObjects(true).onComplete(result ->
            {
                if (result.succeeded())
                {

                    this.send(routingContext, new JsonObject().put(RESPONSE_CODE, HttpStatus.SC_OK).put(GlobalConstants.STATUS, GlobalConstants.STATUS_SUCCEED)
                            .put(GlobalConstants.RESULT, result.result()));

                }
                else
                {
                    this.send(routingContext, new JsonObject().put(RESPONSE_CODE, HttpStatus.SC_INTERNAL_SERVER_ERROR).put(GlobalConstants.STATUS, STATUS_FAIL).put(ERRORS, result.cause().getMessage()));
                }

            });
        }
        catch (Exception exception)
        {
            APIUtil.sendResponse(exception, routingContext);
        }
    }

    private void getObjectsByGroup(RoutingContext routingContext)
    {
        try
        {
            var items = ObjectConfigStore.getStore().getItemsByGroup(CommonUtil.getLong(routingContext.request().getParam(ID)));

            var objects = new JsonArray();

            for (var index = 0; index < items.size(); index++)
            {
                var id = CommonUtil.getLong(items.getValue(index));

                objects.add(new JsonObject().put(ID, id).put(AIOpsObject.OBJECT_NAME, ObjectConfigStore.getStore().getObjectName(id)));
            }

            this.send(routingContext, new JsonObject().put(STATUS, STATUS_SUCCEED).put(RESPONSE_CODE, HttpStatus.SC_OK).put(RESULT, objects));
        }
        catch (Exception exception)
        {
            APIUtil.sendResponse(exception, routingContext);
        }
    }

    private void getObjectsByTag(RoutingContext routingContext)
    {
        try
        {
            if (routingContext.request().params().contains(FILTER))
            {
                var requestParameters = JsonObject.mapFrom(Json.decodeValue(routingContext.request().getParam(FILTER)));

                if (requestParameters != null && requestParameters.containsKey(KEY) && requestParameters.containsKey(VALUE)
                    && Tag.TAG.equalsIgnoreCase(requestParameters.getString(KEY)))
                {
                    var items = ObjectConfigStore.getStore().getIdsByTags(requestParameters.getJsonArray(VALUE));

                    var objects = new JsonArray();

                    for (var index = 0; index < items.size(); index++)
                    {
                        var id = CommonUtil.getLong(items.getValue(index));

                        objects.add(new JsonObject().put(ID, id).put(AIOpsObject.OBJECT_NAME, ObjectConfigStore.getStore().getObjectName(id)));
                    }

                    this.send(routingContext, new JsonObject().put(STATUS, STATUS_SUCCEED).put(RESPONSE_CODE, HttpStatus.SC_OK).put(RESULT, objects));
                }
                else
                {
                    this.send(routingContext, new JsonObject().put(STATUS, STATUS_FAIL).put(RESPONSE_CODE, HttpStatus.SC_BAD_REQUEST)
                            .put(ERROR_CODE, ErrorCodes.ERROR_CODE_BAD_REQUEST)
                            .put(MESSAGE, String.format(ErrorMessageConstants.API_FIELD_REQUIRED, "filter with key='tag' and value array")));
                }
            }
            else
            {
                this.send(routingContext, new JsonObject().put(STATUS, STATUS_FAIL).put(RESPONSE_CODE, HttpStatus.SC_BAD_REQUEST)
                        .put(ERROR_CODE, ErrorCodes.ERROR_CODE_BAD_REQUEST)
                        .put(MESSAGE, String.format(ErrorMessageConstants.API_FIELD_REQUIRED, FILTER)));
            }
        }
        catch (Exception exception)
        {
            APIUtil.sendResponse(exception, routingContext);
        }
    }

    private void getObjectsBySeverity(RoutingContext routingContext)
    {
        if (!routingContext.queryParams().isEmpty() && routingContext.queryParams().contains(SEVERITY))
