                }
            });
        }
        catch (Exception exception)
        {
            APIUtil.sendResponse(exception, routingContext);
        }
    }


    @Override
    protected Future<JsonObject> getReferencesPreHook(RoutingContext routingContext, JsonObject response)
    {
        try
        {
            if (response != null && !response.isEmpty())
            {
                var entities = response.getJsonArray(Entity.OBJECT.getName(), new JsonArray());

                var ids = new JsonArray(entities.stream().map(obj -> ((JsonObject)obj).getLong(ID)).toList());

                var qualifiedIds = ObjectConfigStore.getStore().getItemsByUserProfile(routingContext.user().principal().getLong(ID), ids);

                var objects = new JsonArray();

                for (var index = 0; index < qualifiedIds.size(); index++)
                {
                    var object = ObjectConfigStore.getStore().getItem(qualifiedIds.getLong(index));

                    NMSConstants.enrich(object);

                    CommonUtil.removeSensitiveFields(object,true);

                    objects.add(object);
                }

                response.put(Entity.OBJECT.getName(), objects);
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }

        return Future.succeededFuture(response);
    }

    @Override
    protected Future<JsonObject> getEntityCountPreHook(JsonObject response)
    {
        try
        {
            var userId = response.getLong(USER_ID);

            var ids = TemplateConfigStore.getStore().getIds();

            for (var index = 0; index < ids.size(); index++)
            {
                var templateId = ids.getLong(index);

                var objectIds = ObjectConfigStore.getStore().flatItems(VisualizationConstants.TEMPLATE_ID, templateId, ID);

                response.put(CommonUtil.getString(templateId), ObjectConfigStore.getStore().getItemsByUserProfile(userId, objectIds).size());
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }

        return Future.succeededFuture(response);
    }


    private Future<Void> updateObject(JsonObject object)
    {
        var promise = Promise.<Void>promise();

        var objectId = object.getLong(ID);

        Bootstrap.configDBService.update(DBConstants.TBL_OBJECT,
                new JsonObject().put(FIELD_NAME, ID).put(VALUE, objectId),
                object,
                DEFAULT_USER, MOTADATA_SYSTEM, result ->
                {
                    if (result.succeeded())
                    {
                        // Refresh the object in the store
                        ObjectConfigStore.getStore().updateItem(objectId).onComplete(asyncResult ->
                        {
                            if (asyncResult.succeeded())
                            {
                                LOGGER.debug(String.format("successfully updated object %d with template ID %d",
                                        objectId, object.getLong(VisualizationConstants.TEMPLATE_ID)));
                                promise.complete();
                            }
                            else
                            {
                                LOGGER.warn(String.format("failed to refresh object %d in store: %s",
                                        objectId, asyncResult.cause().getMessage()));
                                promise.fail(asyncResult.cause());
                            }
                        });
                    }
                    else
                    {
                        LOGGER.warn(String.format("failed to update object %d in database: %s",
                                objectId, result.cause().getMessage()));
                        promise.fail(result.cause());
                    }
                });

        return promise.future();
    }
