    /**
     * Handles the retrieval of reference entities for a metric policy.
     * <p>
     * This method fetches reference entities based on the policy ID from the request,
     * applies additional processing via {@code getReferencesPreHook}, and sends the result
     * back to the client. The response includes severity and tag information for each object.
     * <p>
     * In case of errors during retrieval or processing, an appropriate error response is sent.
     *
     * @param routingContext the Vert.x routing context containing request and response information
     */
    @Override
    protected void getReferences(RoutingContext routingContext)
    {
        try
        {
            this.configStore.getReferenceEntities(CommonUtil.getLong(routingContext.request().getParam(ID))).onComplete(result ->
            {
                if (result.succeeded())
                {
                    this.getReferencesPreHook(routingContext, result.result()).onComplete(asyncResult ->
                    {
                        if (asyncResult.succeeded())
                        {
                            var items = new JsonObject().put(Entity.OBJECT.getName(), new JsonArray());

                            var objects = asyncResult.result().getJsonArray(Entity.OBJECT.getName());

                            for (var i = 0; i < objects.size(); i++)
                            {
                                items.getJsonArray(Entity.OBJECT.getName()).add(NMSConstants.enrich(objects.getJsonObject(i)));
                            }

                            if (asyncResult.result().containsKey(Entity.TRACE_SERVICE.getName()))
                            {
                                items.put(Entity.TRACE_SERVICE.getName(), asyncResult.result().getJsonArray(Entity.TRACE_SERVICE.getName()));
                            }

                            this.send(routingContext, new JsonObject().put(RESPONSE_CODE, HttpStatus.SC_OK).put(GlobalConstants.STATUS, STATUS_SUCCEED).put(GlobalConstants.RESULT, items));
                        }
                        else
                        {
                            this.send(routingContext, new JsonObject().put(RESPONSE_CODE, HttpStatus.SC_INTERNAL_SERVER_ERROR).put(GlobalConstants.STATUS, GlobalConstants.STATUS_FAIL)
                                    .put(MESSAGE, String.format(INTERNAL_SERVER_EXCEPTION, asyncResult.cause().getMessage()))
                                    .put(ERROR_CODE, ErrorCodes.ERROR_CODE_INTERNAL_ERROR)
                                    .put(ERROR, CommonUtil.formatStackTrace(asyncResult.cause().getStackTrace())));
                        }
                    });
                }
                else
                {
                    this.send(routingContext, new JsonObject().put(RESPONSE_CODE, HttpStatus.SC_INTERNAL_SERVER_ERROR).put(GlobalConstants.STATUS, GlobalConstants.STATUS_FAIL)
                            .put(MESSAGE, String.format(INTERNAL_SERVER_EXCEPTION, result.cause().getMessage()))
                            .put(ERROR_CODE, ErrorCodes.ERROR_CODE_INTERNAL_ERROR)
                            .put(ERROR, CommonUtil.formatStackTrace(result.cause().getStackTrace())));
                }
            });
        }
        catch (Exception exception)
        {
            APIUtil.sendResponse(exception, routingContext);
        }
    }

    private void updateState(RoutingContext routingContext)
    {
        var state = routingContext.body().asJsonObject().getString(POLICY_STATE);

        var policyId = CommonUtil.getLong(routingContext.request().getParam(ID));

        try
        {
            Bootstrap.configDBService().update(DBConstants.TBL_METRIC_POLICY, new JsonObject().put(DBConstants.FIELD_NAME, GlobalConstants.ID).put(VALUE, policyId),
                    new JsonObject().put(POLICY_STATE, state), routingContext.user().principal().getString(USER_NAME)
                    , routingContext.request().remoteAddress().host(), result ->
                    {
                        if (result.succeeded())
                        {
                            MetricPolicyConfigStore.getStore().updateItem(policyId).onComplete(asyncResult ->
                            {
                                if (asyncResult.succeeded())
                                {
                                    Bootstrap.vertx().eventBus().publish(EventBusConstants.EVENT_CHANGE_NOTIFICATION, new JsonObject().put(ID, policyId).put(EventBusConstants.CHANGE_NOTIFICATION_TYPE, EventBusConstants.ChangeNotificationType.UPDATE_POLICY.name()));
                                }
                            });

                          /*  //disable policy notification order to clear its cache will ne confirm the same whether its required or not
                            if (state.equalsIgnoreCase(NO))
                            {
                                Bootstrap.vertx().eventBus().publish(EventBusConstants.EVENT_CHANGE_NOTIFICATION,new JsonObject().put(ID,policyId).put(EventBusConstants.CHANGE_NOTIFICATION_TYPE,EventBusConstants.ChangeNotificationType.DISABLE_POLICY.name()));
                            }*/

                            this.send(routingContext, new JsonObject().put(MESSAGE, MetricPolicyConfigStore.getStore().getItem(policyId).getString(POLICY_NAME) + (state.equalsIgnoreCase(YES) ? " Enabled" : " Disabled") + " successfully...").put(RESPONSE_CODE, HttpStatus.SC_OK)
                                    .put(GlobalConstants.STATUS, STATUS_SUCCEED).put(ID, policyId));
                        }

                        else
                        {

                            this.send(routingContext, new JsonObject().put(MESSAGE, "Failed to " + (state.equalsIgnoreCase(YES) ? "Enable" : "Disable") + " policy " + MetricPolicyConfigStore.getStore().getItem(policyId).getString(POLICY_NAME)).put(RESPONSE_CODE, HttpStatus.SC_OK)
                                    .put(MESSAGE, String.format(INTERNAL_SERVER_EXCEPTION, result.cause().getMessage()))
                                    .put(GlobalConstants.ERROR, CommonUtil.formatStackTrace(result.cause().getStackTrace()))
                                    .put(ERROR_CODE, ErrorCodes.ERROR_CODE_INTERNAL_ERROR)
                                    .put(GlobalConstants.STATUS, STATUS_FAIL).put(ID, policyId));
                        }
                    });
        }

        catch (Exception exception)
        {
            LOGGER.error(exception);

            this.send(routingContext, new JsonObject().put(RESPONSE_CODE, HttpStatus.SC_INTERNAL_SERVER_ERROR).put(GlobalConstants.STATUS, GlobalConstants.STATUS_FAIL)
                    .put(ERROR, CommonUtil.formatStackTrace(exception.getStackTrace()))
                    .put(ERROR_CODE, ErrorCodes.ERROR_CODE_INTERNAL_ERROR)
                    .put(MESSAGE, String.format(INTERNAL_SERVER_EXCEPTION, DEFAULT_ERROR_MESSAGE)));
        }
    }

    @Override
    protected void getAll(RoutingContext routingContext)
    {
        try
        {
            var params = routingContext.request().params().contains(FILTER) ? JsonObject.mapFrom(Json.decodeValue(routingContext.request().getParam(FILTER))) : new JsonObject();

            this.beforeGetAll(routingContext).compose(handler ->

                    Future.<JsonArray>future(promise ->

                            this.getEntityCountPreHook(new JsonObject().put(USER_ID, routingContext.user().principal().getLong(ID))).onComplete(result ->
                            {
                                if (result.succeeded())
                                {
                                    var items = new JsonArray();

                                    if (!params.isEmpty())
                                    {
                                        items = this.configStore.getItemsByValues(params.getString(KEY), params.getJsonArray(VALUE));
                                    }
                                    else
                                    {
                                        items = this.configStore.getItems();
                                    }

                                    var entities = new JsonArray();

                                    for (var index = 0; index < items.size(); index++)
                                    {
                                        var item = CommonUtil.removeSensitiveFields(items.getJsonObject(index), true);

                                        if (result.result() != null && result.result().containsKey(CommonUtil.getString(item.getLong(ID))))
                                        {
                                            item.put(ENTITY_PROPERTY_COUNT, result.result().getInteger(CommonUtil.getString(item.getLong(ID))));
                                        }

                                        entities.add(item);
                                    }

                                    promise.complete(entities);
                                }
                                else
                                {
                                    this.send(routingContext, new JsonObject().put(RESPONSE_CODE, HttpStatus.SC_INTERNAL_SERVER_ERROR).put(GlobalConstants.STATUS, GlobalConstants.STATUS_FAIL)
                                            .put(MESSAGE, String.format(INTERNAL_SERVER_EXCEPTION, result.cause().getMessage()))
                                            .put(ERROR_CODE, ErrorCodes.ERROR_CODE_INTERNAL_ERROR)
                                            .put(GlobalConstants.ERROR, CommonUtil.formatStackTrace(result.cause().getStackTrace())));

                                    promise.fail(result.cause());
                                }
                            })).compose(entities -> this.afterGetAll(entities, routingContext)));
        }

        catch (Exception exception)
        {
            APIUtil.sendResponse(exception, routingContext);
        }
    }

    @Override
    protected Future<Void> afterGetAll(JsonArray items, RoutingContext routingContext)
    {
        try
        {
            var entities = new JsonArray();

            for (var i = 0; i < items.size(); i++)
            {
                var item = items.getJsonObject(i);

                if (item.containsKey(POLICY_TAGS) && item.getJsonArray(POLICY_TAGS) != null && !item.getJsonArray(POLICY_TAGS).isEmpty())
                {
                    item.put(POLICY_TAGS, TagConfigStore.getStore().getItems(item.getJsonArray(POLICY_TAGS)));
                }

                entities.add(item);
            }

            this.send(routingContext, new JsonObject().put(RESPONSE_CODE, HttpStatus.SC_OK).put(GlobalConstants.STATUS, STATUS_SUCCEED).put(GlobalConstants.RESULT, entities));
        }
        catch (Exception exception)
        {
            APIUtil.sendResponse(exception, routingContext);
        }

        return Future.succeededFuture();
    }

    @Override
    protected Future<Void> afterGet(JsonObject item, RoutingContext routingContext)
    {
        try
        {
            if (item.containsKey(POLICY_TAGS) && item.getJsonArray(POLICY_TAGS) != null && !item.getJsonArray(POLICY_TAGS).isEmpty())
            {
                item.put(POLICY_TAGS, TagConfigStore.getStore().getItems(item.getJsonArray(POLICY_TAGS)));
            }

            this.send(routingContext, new JsonObject().put(RESPONSE_CODE, HttpStatus.SC_OK).put(STATUS, STATUS_SUCCEED).put(GlobalConstants.RESULT, item));
        }
        catch (Exception exception)
        {
            APIUtil.sendResponse(exception, routingContext);
        }

        return Future.succeededFuture();
    }
}

