public class ConfigTemplate extends AbstractAPI
{
    public static final String CONFIG_TEMPLATE_NAME = "config.template.name";
    public static final String CONFIG_TEMPLATE_CATALOG_IDS = "config.template.catalog.ids";
    public static final String CONFIG_TEMPLATE_OS_TYPE = "config.template.os.type";
    public static final String CONFIG_TEMPLATE_VENDOR = "config.template.vendor";
    public static final String CONFIG_TEMPLATE_DESCRIPTION = "config.template.description";
    private static final Logger LOGGER = new Logger(ConfigTemplate.class, MOTADATA_API, "Config Template API");

    public ConfigTemplate()
    {
        super("config-templates", ConfigTemplateConfigStore.getStore(), LOGGER);
    }

    @Override
    public void init(Router router)
    {
        try
        {
            super.init(router);

            router.get("/" + endpoint + "/:id/references").handler(this::getReferences);
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

    @Override
    protected Future<JsonObject> getReferencesPreHook(RoutingContext routingContext, JsonObject response)
    {
        try
        {
            if (response != null && !response.isEmpty() && response.containsKey(APIConstants.Entity.CONFIGURATION.getName()))
            {
                var entities = response.getJsonArray(APIConstants.Entity.CONFIGURATION.getName());

                var qualifiedIds = new HashSet<>(ObjectConfigStore.getStore().getObjectIdsByUserProfile(routingContext.user().principal().getLong(ID)).stream().map(CommonUtil::getInteger).toList());

                var qualifiedEntities = new JsonArray();

                for (var index = 0; index < entities.size(); index++)
                {
                    var item = entities.getJsonObject(index);

                    if (qualifiedIds.remove(item.getInteger(Configuration.CONFIG_OBJECT)))
                    {
                        var object = ObjectConfigStore.getStore().getItemByValue(AIOpsObject.OBJECT_ID, item.getInteger(Configuration.CONFIG_OBJECT));

                        NMSConstants.enrich(object);

                        ConfigConstants.removeGarbageFields(object);

                        item.mergeIn(object);

                        qualifiedEntities.add(item);
                    }
                }

                response.put(APIConstants.Entity.CONFIGURATION.getName(), qualifiedEntities);
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }

        return Future.succeededFuture(response);
    }

    @Override
    protected Future<JsonObject> getEntityCountPreHook(JsonObject response)
    {
        var promise = Promise.<JsonObject>promise();

        try
        {
            var futures = new ArrayList<Future<Void>>();

            var userId = CommonUtil.getLong(response.remove(USER_ID));

            for (var template : response)
            {
                futures.add(getQualifiedEntities(Long.parseLong(template.getKey()), userId, response));
            }

            Future.join(futures).onComplete(result -> promise.complete(response));
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);

            promise.fail(exception);
        }

        return promise.future();
    }

    private Future<Void> getQualifiedEntities(long id, long userId, JsonObject response)
    {
        var promise = Promise.<Void>promise();

        this.configStore.getReferenceEntities(id).onComplete(result ->
        {
            try
            {
                if (result.succeeded())
                {
                    if (result.result().containsKey(APIConstants.Entity.CONFIGURATION.getName()))
                    {
                        var objects = result.result().getJsonArray(APIConstants.Entity.CONFIGURATION.getName());

                        var entities = new JsonArray();

                        for (var index = 0; index < objects.size(); index++)
                        {
                            entities.add(objects.getJsonObject(index).getInteger(Configuration.CONFIG_OBJECT));
                        }

                        response.put(id + "", ObjectConfigStore.getStore().getItemsByUserProfile(userId, ObjectConfigStore.getStore().getItemsByObjectIds(entities.getList())).size());
                    }

                    promise.complete();
                }
                else
                {
                    promise.fail(result.cause());
                }
            }
            catch (Exception exception)
            {
                LOGGER.error(exception);

                promise.fail(exception);
            }

        });

        return promise.future();
    }
}

