public class SystemFile extends AbstractAPI
{
    public static final String SYSTEM_FILE_OS = "system.file.os";

    public static final String SYSTEM_FILE_TYPE = "system.file.type";

    public static final String SYSTEM_FILE_TYPE_FILE = "File";

    public static final String SYSTEM_FILE_TYPE_DIR = "Directory";

    public static final String SYSTEM_FILE = "system.file";

    private static final Logger LOGGER = new Logger(SystemFile.class, MOTADATA_API, "System File API");

    public SystemFile()
    {
        super("system-files", SystemFileConfigStore.getStore(), LOGGER);
    }

    @Override
    protected Future<JsonObject> beforeCreate(RoutingContext routingContext)
    {
        return distinct(routingContext, APIConstants.REQUEST_CREATE);
    }

    @Override
    protected Future<JsonObject> beforeUpdate(RoutingContext routingContext)
    {
        return distinct(routingContext, APIConstants.REQUEST_UPDATE);
    }

    private Future<JsonObject> distinct(RoutingContext routingContext, String requestType)
    {
        var promise = Promise.<JsonObject>promise();

        var requestBody = routingContext.body().asJsonObject();

        var items = this.configStore.getItems();

        var valid = true;

        for (var index = 0; index < items.size(); index++)
        {
            var item = items.getJsonObject(index);

            if (valid && item.getString(SYSTEM_FILE).equalsIgnoreCase(requestBody.getString(SYSTEM_FILE))
                    && item.getString(SYSTEM_FILE_TYPE).equalsIgnoreCase(requestBody.getString(SYSTEM_FILE_TYPE))
                    && item.getString(SYSTEM_FILE_OS).equalsIgnoreCase(requestBody.getString(SYSTEM_FILE_OS)))
            {
                valid = requestType.equalsIgnoreCase(APIConstants.REQUEST_UPDATE)
                        && item.getLong(GlobalConstants.ID).equals(CommonUtil.getLong(routingContext.request().getParam(ID)));
            }
        }

        if (valid)
        {
            promise.complete(requestBody);
        }
        else
        {
            this.send(routingContext, new JsonObject().put(RESPONSE_CODE, HttpStatus.SC_BAD_REQUEST)
                    .put(GlobalConstants.STATUS, GlobalConstants.STATUS_FAIL).put(ERROR_CODE, ErrorCodes.ERROR_CODE_BAD_REQUEST)
                    .put(GlobalConstants.MESSAGE, String.format(ErrorMessageConstants.API_FIELD_UNIQUE_RULE, NMSConstants.RediscoverJob.FILE_DIRECTORY.getName())));

            promise.fail(String.format(ErrorMessageConstants.API_FIELD_UNIQUE_RULE, NMSConstants.RediscoverJob.FILE_DIRECTORY.getName()));
        }

        return promise.future();
    }
}

