     */
    protected void search(RoutingContext routingContext)
    {
        try
        {

            this.beforeSearch(routingContext).compose(handler ->
                    process(routingContext,  true)).compose(result ->
                    afterSearch(result, routingContext)
            );

        }
        catch (Exception e)
        {
            APIUtil.sendResponse(e, routingContext);
        }
    }

    /**
     * Core search processing: fetches data, applies filters/search, enriches, sorts, and paginates.
     * Returns structured result with items and pagination metadata.
     */
    protected Future<JsonObject> process(RoutingContext routingContext,  boolean applyPagination)
    {
        var promise = Promise.<JsonObject>promise();

        var requestBody = routingContext.body().asJsonObject();

        try
        {
            // Extract parameters
            var sortColumn = requestBody.getString(APIConstants.SORT_COLUMN, ID);

            var sortOrder = requestBody.getString(APIConstants.SORT_ORDER, DESC);

            var pageNumber = requestBody.getInteger(APIConstants.PAGE_NUMBER, 0);

            var pageSize = requestBody.getInteger(APIConstants.PAGE_SIZE, 20);

            // Step 1: Fetch data using hook method
            var data = fetch(routingContext, requestBody);

            var rows = enrichItems(data);

            // Step 2: Apply filters and search
            var filteredItems = filterAndSort(rows, requestBody);

            // Step 3: Enrich items using hook method

            var asyncPromise = Promise.<JsonArray>promise();

            enrichWithCounts(routingContext,filteredItems,asyncPromise).onComplete(asyncResult ->
            {
                if (asyncResult.succeeded())
                {
                    try
                    {
                        // Step 4: Sort the enriched results
                         filteredItems.getList().sort(APIConstants.sort(sortColumn, sortOrder));

                        // Step 5: Apply pagination if requested
                        var items = applyPagination ? applyPagination(filteredItems, pageNumber, pageSize) : filteredItems;

                        // Step 6: Build result
                        var result = applyPagination ? composeResult(items,filteredItems.size(), pageNumber, pageSize, sortColumn, sortOrder) : new JsonObject().put(ITEMS, items).put(TOTAL, filteredItems.size());

                        promise.complete(result);

                    }
                    catch (Exception e)
                    {
                        promise.fail(e);
                    }
                }
                else
                {
                    promise.fail(asyncResult.cause());
                }
            });

        }
        catch (Exception e)
        {
            promise.fail(e);
        }

        return promise.future();
    }

