    /**
     * Applies filtering, searching, and sorting to the dataset using parallel streams.
     * Removes sensitive fields for security before returning results.
     */
    protected JsonArray filterAndSort(JsonArray items,JsonObject requestBody)
    {
        var iterator = items.iterator();

        while (iterator.hasNext())
        {
            var item = (JsonObject) iterator.next();

            if (!matchFilters(item, requestBody) ||
                    !matchSearch(item, requestBody.getString(SEARCH_FILTER,"").trim().toLowerCase(), requestBody.getJsonArray(SEARCH_COLUMNS,new JsonArray())))
            {
                iterator.remove();
            }

            CommonUtil.removeSensitiveFields(item, true);
        }

        return items;
    }

    /**
     * Tests if an item matches all filter criteria using AND logic.
     * Returns false if any required field is missing or doesn't match.
     */
    protected boolean matchFilters(JsonObject item, JsonObject request)
    {

        if (CommonUtil.isNotNullOrEmpty(request.getJsonObject(GlobalConstants.FILTERS)))
        {
            for (var key : request.getJsonObject(FILTERS).fieldNames())
            {
                var value = item.getString(key);

                // If value is missing → no match
                if (value == null)
                {
                    return false;
                }

                var filterValues = request.getJsonObject(FILTERS).getJsonArray(key);

                var matched = false;

                for (var i = 0; i < filterValues.size(); i++)
                {
                    var filterValue = filterValues.getString(i);

                    if (value.equalsIgnoreCase(filterValue))
                    {
                        matched = true;

                        break;
                    }
                }

                if (!matched)
                {
                    return false;
                }
            }
        }

        return true;
    }
