/**
 * REST API handler for RUM (Real User Monitoring) policy management.
 * Provides CRUD operations and state management for RUM policies.
 */
public class RUMPolicy extends AbstractAPI
{
    private static final Logger LOGGER = new Logger(RUMPolicy.class, MOTADATA_API, "RUM Policy API");

    /**
     * Constructs the RUM Policy API handler.
     * Initializes with endpoint name and policy configuration store.
     */
    public RUMPolicy()
    {
        super("rum-policies", RUMPolicyConfigStore.getStore(), LOGGER);
    }

    /**
     * Initializes API routes for RUM policy operations.
     * Sets up endpoints for references retrieval and state updates.
     */
    @Override
    public void init(Router router)
    {
        try
        {
            super.init(router);

            router.get("/" + endpoint + "/:id/references").handler(this::getReferences);

            router.put("/" + endpoint + "/:id/state").handler(this::updateState); //update  policy state API
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

    /**
     * Pre-hook to enrich policy references with RUM service profiles.
     * Resolves entity references based on service IDs or tags.
     */
    @Override
    protected Future<JsonObject> getReferencesPreHook(RoutingContext routingContext, JsonObject response)
    {
        var promise = Promise.<JsonObject>promise();

        try
        {
            var item = RUMPolicyConfigStore.getStore().getItem(CommonUtil.getLong(routingContext.request().getParam(ID))).getJsonObject(POLICY_CONTEXT);

            var items = new JsonArray();

            if (item.getString(ENTITY_TYPE).equalsIgnoreCase(APIConstants.Entity.RUM_SERVICE.getName()))
            {
                items = RUMServiceProfileConfigStore.getStore().getItems(new JsonArray(item.getJsonArray(ENTITIES).stream().map(CommonUtil::getLong).toList()));
            }
            else if (item.getString(ENTITY_TYPE).equalsIgnoreCase(Tag.TAG))
            {
                try
                {
                    var entities = TagConfigStore.getStore().getIdsByItems(item.getJsonArray(ENTITIES)).stream().map(CommonUtil::getInteger).toList();

                    var counts = new HashSet<Long>();

                    var profiles = RUMServiceProfileConfigStore.getStore().getItemsByMultiValueFieldAny(RUMServiceProfile.RUM_PROFILE_TAGS, new JsonArray(entities));

                    for (var index = 0; index < profiles.size(); index++)
                    {
                        var profile = profiles.getJsonObject(index);

                        if (counts.add(profile.getLong(ID)))
                        {
                            items.add(profile);
                        }
                    }
                }
                catch (Exception exception)
                {
                    LOGGER.error(exception);
                }
            }

            promise.complete(response.put(APIConstants.Entity.RUM_SERVICE.getName(), items));
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }

        return promise.future();
    }

    /**
     * Pre-hook to calculate entity counts for each RUM policy.
     * Counts RUM services associated with policies by direct assignment or tags.
     */
    @Override
    protected Future<JsonObject> getEntityCountPreHook(JsonObject response)
    {
        var promise = Promise.<JsonObject>promise();

        try
        {
            try
            {
                var ids = RUMPolicyConfigStore.getStore().getIds();

                for (var index = 0; index < ids.size(); index++)
                {
                    try
                    {
                        var item = RUMPolicyConfigStore.getStore().getItem(ids.getLong(index)).getJsonObject(POLICY_CONTEXT);

                        if (item.containsKey(METRIC))
                        {
                            if (item.getString(ENTITY_TYPE).equalsIgnoreCase(Entity.RUM_SERVICE.getName()))
                            {
                                response.put(CommonUtil.getString(ids.getLong(index)), item.getJsonArray(ENTITIES).size());
                            }
                            else if (item.getString(ENTITY_TYPE).equalsIgnoreCase(Tag.TAG))
                            {
                                var entities = TagConfigStore.getStore().getIdsByItems(item.getJsonArray(ENTITIES)).stream().map(CommonUtil::getInteger).toList();

                                var counts = new HashSet<Long>();

                                var objects = RUMServiceProfileConfigStore.getStore().getItemsByMultiValueFieldAny(RUMServiceProfile.RUM_PROFILE_TAGS, new JsonArray(entities));

                                for (var i = 0; i < objects.size(); i++)
                                {
                                    counts.add(objects.getJsonObject(i).getLong(ID));
                                }

                                response.put(CommonUtil.getString(ids.getLong(index)), counts.size());
                            }

                        }
                    }
                    catch (Exception exception)
                    {
                        LOGGER.error(exception);
                    }
                }

                promise.complete(response);
            }
            catch (Exception exception)
            {
                LOGGER.error(exception);

                promise.fail(exception);
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }

        return promise.future();
    }

    /**
     * Pre-create validation hook for RUM policies.
     * Validates policy name uniqueness and processes tags before creation.
     */
    @Override
    protected Future<JsonObject> beforeCreate(RoutingContext routingContext)
    {
        var promise = Promise.<JsonObject>promise();

        var items = RUMPolicyConfigStore.getStore().getItems();

        var requestBody = routingContext.body().asJsonObject();

        var valid = true;

        // Need to check manually as we are not deleting policy just archiving so if that policy is archived so user can create policy with same archived one..
        for (var index = 0; index < items.size(); index++)
        {
            var item = items.getJsonObject(index);

            if ((!item.containsKey(POLICY_ARCHIVED) || item.getString(POLICY_ARCHIVED).equalsIgnoreCase(NO)) && item.getString(POLICY_NAME).equalsIgnoreCase(requestBody.getString(POLICY_NAME)))
            {
                valid = false;

                send(routingContext, new JsonObject().put(STATUS, STATUS_FAIL).put(ERROR_CODE, ErrorCodes.ERROR_CODE_BAD_REQUEST)
                        .put(RESPONSE_CODE, SC_BAD_REQUEST).put(MESSAGE, String.format(ErrorMessageConstants.API_FIELD_UNIQUE_RULE, POLICY_NAME)));

                promise.fail(String.format(ErrorMessageConstants.API_FIELD_UNIQUE_RULE, POLICY_NAME));

                break;
            }
        }

        if (valid)
        {
            if (requestBody.getJsonArray(POLICY_TAGS) != null && !requestBody.getJsonArray(POLICY_TAGS).isEmpty())
            {
                requestBody.put(POLICY_TAGS, TagConfigStore.getStore().addItems(requestBody.getJsonArray(POLICY_TAGS), Tag.TagType.POLICY.getName(), DBConstants.ENTITY_TYPE_USER));
            }

            promise.complete(requestBody.put(POLICY_ARCHIVED, NO).put(POLICY_CREATION_TIME, DateTimeUtil.currentSeconds()).put(POLICY_STATE, YES));
        }

        return promise.future();
    }

