    }

    @Override
    public JsonArray getItems(JsonArray ids)
    {
        var items = new JsonArray();

        if (ids != null && !ids.isEmpty())
        {
            items.addAll(new JsonArray(ids.stream().filter(this.items::containsKey).map(id -> this.items.get(id).copy()).collect(Collectors.toList())));

        }

        return items;
    }

    /**
     * Compares the groups attached to the entity with the user's groups,
     * and returns array of groups that are common to both the entity and the user.
     */
    public JsonArray getQualifiedGroups(JsonArray groups, JsonArray userGroups)
    {
        var items = new JsonArray();

        try
        {
            for (var group : userGroups)
            {
                if (groups.contains(group))
                {
                    items.add(group);
                }
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }

        return items;
    }

    /**
     * Retrieves the group IDs accessible to a user based on their profile or direct group assignments.
     *
     * <p>This method determines which groups a user has access to by following this priority order:</p>
     * <ol>
     *   <li><strong>Default User</strong>: If the user ID is DEFAULT_ID, returns all group IDs in the system</li>
     *   <li><strong>User Profile with GROUP scope</strong>: If the user has a profile with GROUP scope type,
     *       returns the groups defined in the profile context</li>
     *   <li><strong>User Profile with other scope types</strong>: If the user has a profile with non-GROUP scope
     *       (e.g., TAG), returns an empty array as groups are not applicable</li>
     *   <li><strong>Direct Group Assignment</strong>: If the user has no profile or an invalid profile,
     *       returns the groups directly assigned to the user</li>
     * </ol>
     *
     * <p>This method is fundamental to the access control system, as it determines which groups
     * (and consequently which objects within those groups) a user can access. It's used extensively
     * throughout the system for filtering data based on user permissions.</p>
     *
     * <p><strong>Usage Examples:</strong></p>
     * <ul>
     *   <li>Filtering objects visible to a user in object listings</li>
     *   <li>Determining which groups can be selected in group-based policies</li>
     *   <li>Building hierarchical group trees for user interfaces</li>
     *   <li>Validating user access to specific resources</li>
     * </ul>
     *
     * @param userId the ID of the user whose accessible groups are to be retrieved
     * @return a JsonArray containing the IDs of groups accessible to the user.
     *         Returns all group IDs for default user, profile-defined groups for users with GROUP-scoped profiles,
     *         empty array for users with non-GROUP profiles, or directly assigned groups as fallback
     */
    public JsonArray getItemsByUserProfile(long userId)
    {
        if (userId == DEFAULT_ID) return GroupConfigStore.getStore().flatItems(ID);

        var user = UserConfigStore.getStore().getItem(userId);

        var profileId = user.getLong(User.USER_PROFILE);

        if (profileId != null && !profileId.equals(DUMMY_ID))
        {
            var profile = UserProfileConfigStore.getStore().getItem(profileId);

            if (profile != null)
            {
                var context = profile.getJsonObject(UserProfile.USER_PROFILE_CONTEXT);

                return switch (UserProfile.UserProfileScopeType.valueOfName(context.getString(UserProfile.USER_PROFILE_SCOPE_TYPE, EMPTY_VALUE)))
                {
                    case UserProfile.UserProfileScopeType.GROUP -> context.getJsonArray(GlobalConstants.ENTITIES);

                    case null, default -> new JsonArray();
                };
            }
        }

        return user.getJsonArray(USER_GROUPS);
    }
}

