package com.mindarray.store;

import com.mindarray.Bootstrap;
import com.mindarray.GlobalConstants;
import com.mindarray.db.DBConstants;
import com.mindarray.trace.TraceConstants;
import com.mindarray.util.CommonUtil;
import com.mindarray.util.Logger;
import io.vertx.core.Future;
import io.vertx.core.Promise;
import io.vertx.core.json.JsonArray;
import io.vertx.core.json.JsonObject;

import java.util.*;

import static com.mindarray.GlobalConstants.*;
import static com.mindarray.eventbus.EventBusConstants.EVENT_SOURCE;

public class TraceServiceConfigStore extends AbstractConfigStore
{
    private static final Logger LOGGER = new Logger(TraceServiceConfigStore.class, GlobalConstants.MOTADATA_STORE, "Trace Service Config Store");

    private static final TraceServiceConfigStore STORE = new TraceServiceConfigStore();

    private final Map<String, Long> itemByService = new HashMap<>();

    private TraceServiceConfigStore()
    {
        super(DBConstants.TBL_TRACE_SERVICE, LOGGER, false);
    }

    public static TraceServiceConfigStore getStore()
    {
        return STORE;
    }

    /**
     * Initializes the configuration store by loading all trace service configurations from the database.
     *
     * This method retrieves all trace service configurations from the database and populates the internal
     * cache (`items`) with the retrieved data. It also maintains a mapping of service names to their
     * corresponding IDs in the `itemIdByService` map. If the initialization is successful, the promise
     * is completed; otherwise, it is failed with the appropriate error.
     *
     * Context:
     * - This method is typically called during the startup phase of the application or when the
     *   configuration store needs to be initialized.
     * - It ensures that the store is populated with the latest trace service configurations, allowing
     *   the system to operate seamlessly with the most up-to-date data.
     *
     * @return A {@link Future} that completes when the store initialization is finished.
     *         The future indicates the successful setup of the configuration store or a failure
     *         if an error occurs during initialization.
     */
    @Override
    public Future<Void> initStore()
    {
        var promise = Promise.<Void>promise();

        try
        {
            Bootstrap.configDBService().getAll(DBConstants.TBL_TRACE_SERVICE, result ->
            {
                if (result.succeeded())
                {
                    items.clear();

                    itemByService.clear();

                    if (result.result() != null && !result.result().isEmpty())
                    {
                        for (var index = 0; index < result.result().size(); index++)
                        {
                            var item = result.result().getJsonObject(index);

                            items.put(item.getLong(GlobalConstants.ID), item);

                            if (CommonUtil.debugEnabled())
                            {
                                LOGGER.debug(String.format("item added %s into the store", CommonUtil.removeSensitiveFields(item, false).encodePrettily()));
                            }

                            itemByService.put(item.getString(TraceConstants.SERVICE_NAME), item.getLong(GlobalConstants.ID));
                        }
                    }

                    promise.complete();

                    LOGGER.info(String.format("store %s initialized...", this.getClass().getSimpleName()));
                }
                else
                {
                    LOGGER.fatal(String.format("failed to init store %s , reason : %s...", this.getClass().getSimpleName(), result.cause()));

                    promise.fail(result.cause());
                }
            });
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);

            promise.fail(exception.getMessage());
        }

        return promise.future();
    }

    /**
     * Adds a new trace service configuration to the store and updates the service-to-ID mapping.
     *
     * This method adds a new configuration item to the internal cache (`items`) using the provided ID.
     * After successfully adding the item, it updates the `itemIdByService` map to associate the service
     * name with its corresponding ID. This ensures that the store maintains an up-to-date mapping of
     * service names to their IDs for efficient lookups.
     *
     * Context:
     * - This method is typically used when a new trace service configuration is created or added to
     *   the system. It ensures that the configuration is stored in the cache and that the service-to-ID
     *   mapping is updated for quick access.
     *
     * @param id The unique identifier of the trace service configuration to be added. This ID is used
     *           to locate the configuration in the database and store it in the cache.
     * @return A {@link Future} that completes when the item is successfully added to the store.
     *         The future indicates the success or failure of the operation.
     */
    @Override
    public Future<Void> addItem(long id)
    {
        return super.addItem(id).onComplete(result ->
        {
            if (result.succeeded())
            {
                var service = items.get(id).getString(TraceConstants.SERVICE_NAME);

                itemByService.put(service, id);
            }
        });
    }

    /**
     * Archives all trace service configurations associated with the specified event source.
     *
     * This method identifies all trace service configurations in the store that are linked to the
     * given event source and marks them as archived in the database. It updates the `archive` field
     * for the matching configurations and removes them from the in-memory cache. This ensures that
     * the configurations are no longer active but remain in the database for historical reference.
     *
     * Context:
     * - This method is typically used when an event source is removed or becomes inactive, and all
     *   associated trace service configurations need to be archived.
     * - It ensures that the store reflects the current state of active configurations while retaining
     *   archived configurations for future reference.
     *
     * @param eventSource The name of the event source whose associated trace service configurations
     *                    need to be archived. This is used to identify the relevant configurations
     *                    in the store.
     */
    public void remove(String eventSource)
    {
        var ids = new JsonArray();

        for (var id : items.keySet())
        {
            if (items.get(id).getString(EVENT_SOURCE).equalsIgnoreCase(eventSource))
            {
                ids.add(id);
            }
        }

        if (!ids.isEmpty())
        {
            Bootstrap.configDBService().updateAll(DBConstants.TBL_TRACE_SERVICE,
                    new JsonObject().put(DBConstants.FIELD_NAME, GlobalConstants.ID).put(VALUE, ids),
                    new JsonObject().put("archive", GlobalConstants.YES),
                    DEFAULT_USER,
                    SYSTEM_REMOTE_ADDRESS,
                    result -> updateItems(ids));
        }
    }

    /**
     * Updates the mapping of a trace service name to its corresponding ID in the store.
     *
     * This method ensures that the internal mapping (`itemIdByService`) is updated with the latest
     * association between a trace service name and its unique identifier. It retrieves the service
     * name from the configuration item associated with the given ID and updates the mapping to
     * reflect the current state of the store.
     *
     * Context:
     * - This method is typically used when a trace service configuration is modified, and the
     *   mapping between the service name and its ID needs to be updated to reflect the changes.
     * - It ensures that the store maintains an accurate and up-to-date mapping for efficient lookups.
     *
     * @param id The unique identifier of the trace service configuration that has been updated.
     *           This ID is used to locate the configuration in the store and update the mapping.
     */
    public void update(long id)
    {
        itemByService.put(items.get(id).getString(TraceConstants.SERVICE_NAME), id);
    }

    /**
     * Retrieves the unique identifier (ID) of a trace service based on its name.
     *
     * This method looks up the internal mapping of service names to their corresponding IDs
     * and returns the ID associated with the specified service name. If the service name
     * does not exist in the mapping, the method returns `-1L` as a default value.
     *
     * Context:
     * - This method is typically used when there is a need to retrieve the ID of a trace service
     *   for operations such as updating, deleting, or querying the service configuration.
     * - It ensures efficient lookups by leveraging the pre-populated mapping of service names
     *   to IDs in the cache.
     *
     * @param service The name of the trace service whose ID is to be retrieved. This name is used
     *                as the key to look up the corresponding ID in the mapping.
     * @return The unique identifier (ID) of the specified trace service as a {@code long}.
     *         If the service name does not exist in the mapping, the method returns `-1L`.
     */
    public long getIdByService(String service)
    {
        return itemByService.getOrDefault(service, -1L);
    }

    /**
     * Checks if a trace service exists in the store based on its name.
     *
     * This method verifies whether a trace service with the specified name is present in the
     * internal mapping of service names to their corresponding IDs. It provides a quick way
     * to determine the existence of a service without needing to query the database or iterate
     * through the entire cache.
     *
     * Context:
     * - This method is typically used when validating the existence of a trace service before
     *   performing operations such as adding, updating, or deleting configurations.
     * - It ensures that operations are only performed on valid and existing services, reducing
     *   the risk of errors or inconsistencies.
     *
     * @param service The name of the trace service to check for existence. This name is used as
     *                the key to look up the service in the internal mapping.
     * @return {@code true} if the service exists in the store, {@code false} otherwise.
     */
    public boolean serviceExists(String service)
    {
        return itemByService.containsKey(service);
    }

    /**
     * Retrieves trace service items by their IDs with optional archive status filtering.
     *
     * This method fetches trace service configurations based on the provided array of IDs
     * and filters them according to the archive status. When {@code includeArchived} is false,
     * only active (non-archived) services are returned. When true, all services matching the
     * provided IDs are returned regardless of their archive status.
     *
     * Context:
     * - This method is used by policy classes (MetricPolicy, EventPolicy) to retrieve trace
     *   services for policy reference operations.
     * - Filtering by archive status ensures that policies only reference active services
     *   unless explicitly requested otherwise.
     *
     * @param ids The array of trace service IDs to retrieve. Must not be null.
     * @param includeArchived If true, includes archived services in the result.
     *                        If false, only returns active (non-archived) services.
     * @return A {@link JsonArray} containing the filtered trace service configurations.
     *         Returns an empty array if no matching services are found or if ids is null/empty.
     */
    public JsonArray getItems(JsonArray ids, boolean includeArchived)
    {
        var result = new JsonArray();

        if (ids != null && !ids.isEmpty())
        {
            var items = getItems(ids);

            if (items != null)
            {
                if (includeArchived)
                {
                    return items;
                }

                for (var i = 0; i < items.size(); i++)
                {
                    var item = items.getJsonObject(i);

                    if (item != null && NO.equalsIgnoreCase(item.getString("archive", NO)))
                    {
                        result.add(item);
                    }
                }
            }
        }

        return result;
    }
}

