package com.mindarray.store;

import com.mindarray.Bootstrap;
import com.mindarray.GlobalConstants;
import com.mindarray.datastore.DatastoreConstants;
import com.mindarray.eventbus.EventBusConstants;
import com.mindarray.log.LogEngineConstants;
import com.mindarray.rum.RUMConstant;
import com.mindarray.util.DateTimeUtil;
import com.mindarray.util.Logger;
import com.mindarray.visualization.VisualizationConstants;
import io.vertx.core.Future;
import io.vertx.core.Promise;
import io.vertx.core.json.JsonArray;
import io.vertx.core.json.JsonObject;

import java.io.File;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.atomic.AtomicLong;

import static com.mindarray.GlobalConstants.ENTITIES;
import static com.mindarray.GlobalConstants.PLUGIN_ID;
import static com.mindarray.eventbus.EventBusConstants.*;

/**
 * Cache store for Real User Monitoring (RUM) event processing and metrics.
 * Manages event counters, HTTP requests, client tokens, and RUM data sources.
 */
public class RUMCacheStore extends AbstractCacheStore
{
    private static final Logger LOGGER = new Logger(RUMCacheStore.class,  GlobalConstants.MOTADATA_STORE, "RUM Cache Store");

    private static final RUMCacheStore STORE = new RUMCacheStore();

    // Event processing counters
    private final AtomicLong events = new AtomicLong(0);

    private final AtomicLong faultyEvents = new AtomicLong(0);

    private final AtomicLong httpRequests = new AtomicLong(0);

    private static final Set<String> CLIENT_TOKENS = new HashSet<>();

    private JsonObject rumAttributes = new JsonObject();

    private final Set<String> sources = new HashSet<>();

    private final Map<String, Long> lastReceivedByApplication = new ConcurrentHashMap<>(); // application.id -> timestamp (milli)

    private final AtomicInteger maxEvents = new AtomicInteger(RUMConstant.RUM_MAX_EVENTS);

    private RUMCacheStore()
    {}

    /**
     * Returns the singleton instance of the RUM cache store.
     *
     * @return the singleton store instance
     */
    public static RUMCacheStore getStore()
    {
        return STORE;
    }

    /**
     * Initializes the RUM cache store by loading event sources and RUM attributes.
     * Loads RUM event sources from configuration and reads RUM attributes from file.
     *
     * @return Future that completes when initialization is successful or fails on error
     */
    @Override
    public Future<Void> initStore()
    {
        var promise = Promise.<Void>promise();

        try
        {
            var items = EventSourceConfigStore.getStore().flatItemsByValue(EventBusConstants.EVENT_TYPE, VisualizationConstants.VisualizationDataSource.RUM_VIEW.getName(), EVENT_SOURCE);

            if (items != null && !items.isEmpty())
            {
                for (var index = 0; index < items.size(); index++)
                {
                    var source = items.getJsonObject(index);

                    // Add new source if not already registered
                    if (!sources.contains(source.getString(EVENT_SOURCE)))
                    {
                        sources.add(items.getJsonObject(index).getString(EVENT_SOURCE));
                    }
                }
            }

            var file = new File(GlobalConstants.CURRENT_DIR + GlobalConstants.PATH_SEPARATOR + GlobalConstants.DB_DIR + GlobalConstants.PATH_SEPARATOR + "rum-attributes.json");

            if (file.exists())
            {
                rumAttributes = new JsonObject(Bootstrap.vertx().fileSystem().readFileBlocking(file.getPath()));

                LOGGER.info("RUM attributes loaded.");

                promise.complete();
            }
            else
            {
                promise.fail("RUM Attributes json file not found.");
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);

            promise.fail(exception);
        }

        return promise.future();
    }

    /**
     * Increments the total event counter by the specified amount.
     *
     * @param events the number of events to add
     */
    public void updateEvents(int events)
    {
        this.events.addAndGet(events);
    }

    /**
     * Increments the faulty event counter by the specified amount.
     *
     * @param events the number of faulty events to add
     */
    public void updateFaultyEvents(int events)
    {
        faultyEvents.addAndGet(events);
    }

    /**
     * Returns the faulty events counter.
     *
     * @return atomic counter for faulty events
     */
    public AtomicLong getFaultyEvents()
    {
        return faultyEvents;
    }

    /**
     * Returns the HTTP requests counter.
     *
     * @return atomic counter for HTTP requests
     */
    public AtomicLong getHttpRequests()
    {
        return httpRequests;
    }

    /**
     * Returns the total events counter.
     *
     * @return atomic counter for total events
     */
    public AtomicLong getEvents()
    {
        return events;
    }

    /**
     * Increments the HTTP requests counter by the specified amount.
     *
     * @param events the number of HTTP requests to add
     */
    public void updateHttpRequests(int events)
    {
        this.httpRequests.addAndGet(events);
    }

    /**
     * Checks if a service with the given ID already exists.
     * Attempts to add the service ID to the client tokens set.
     *
     * @param serviceId the service ID to check
     * @return true if service already exists, false if newly added
     */
    public boolean isServiceExists(String serviceId)
    {
        return !CLIENT_TOKENS.add(serviceId);
    }

    /**
     * Retrieves RUM attributes for the specified event type.
     *
     * @param type the RUM event type
     * @return JSON array of attributes for the event type
     */
    public JsonArray getRUMAttributes(RUMConstant.EventType type)
    {
        return rumAttributes.getJsonArray(type.getEventType());
    }

    /**
     * Adds a new RUM event source and publishes change notifications.
     * Registers the event source and notifies the system about new data sources.
     *
     * @param eventSource the event source name
     * @param dataSources list of visualization data sources
     * @param pluginIds list of plugin IDs corresponding to data sources
     */
    public void addEventSource(String eventSource, List<VisualizationConstants.VisualizationDataSource> dataSources, List<DatastoreConstants.PluginId> pluginIds)
    {
        if (!sources.contains(eventSource))
        {
            sources.add(eventSource);

            for (var index = 0; index < dataSources.size(); index++)
            {
                if (dataSources.get(index) != null && pluginIds.size() > index && pluginIds.get(index) != null)
                {
                    Bootstrap.vertx().eventBus().send(EVENT_CHANGE_LOCAL_NOTIFICATION,
                            new JsonObject().put(EVENT_SOURCE, eventSource)
                                    .put(EVENT, dataSources.get(index).getName())
                                    .put(CHANGE_NOTIFICATION_TYPE, ChangeNotificationType.ADD_EVENT_SOURCE)
                                    .put(ENTITIES, new JsonArray().add(eventSource))
                                    .put(PLUGIN_ID, pluginIds.get(index).getName())
                                    .put(LogEngineConstants.EVENT_CATEGORY, dataSources.get(index).getName()));
                }
            }
        }
    }

    /**
     * Resets the event counter to the maximum allowed events.
     */
    public void reset()
    {
        maxEvents.set(RUMConstant.RUM_MAX_EVENTS);
    }

    /**
     * Subtracts the specified number of events from the counter.
     * Ensures that the counter does not go below zero.
     *
     * @param event the number of events to subtract
     */
    public void subtract(int event)
    {
        while (true)
        {
            var value = maxEvents.get();

            // Atomically sets to new value only if the current value hasn't changed
            if (maxEvents.compareAndSet(value, value - event))
            {
                return;
            }
        }
    }

    /**
     * @return Current count of events processed
     */
    public int getMaxEvents()
    {
        return maxEvents.get();
    }

    /**
     * Gets the set of RUM data sources.
     *
     * <p>Returns the collection of registered RUM data sources that are
     * currently active in the system.</p>
     *
     * @return A Set of strings representing the RUM data sources
     */
    public Set<String> getSources()
    {
        return sources;
    }

    /**
     * Updates the last received timestamp for the given RUM application.
     * <p>
     * Stores the current system time (in milliseconds) against the
     * provided application ID whenever a RUM event is received.
     *
     * @param applicationId Unique identifier of the RUM application
     */
    public void updateLastReceived(String applicationId)
    {
        lastReceivedByApplication.put(applicationId, DateTimeUtil.currentMilliSeconds());
    }

    /**
     * Retrieves the last received event timestamp for the given RUM application.
     * <p>
     * Returns the timestamp (in milliseconds) when the last RUM event
     * was received for the specified application.
     *
     * @param applicationId Unique identifier of the RUM application
     * @return Timestamp in milliseconds of the last received event,
     *         or {@code null} if no events have been received
     */
    public Long getLastReceivedTimestamp(String applicationId)
    {
        return lastReceivedByApplication.get(applicationId);
    }
}

