public class StorageProfileConfigStore extends AbstractConfigStore
{
    private static final Logger LOGGER = new Logger(StorageProfileConfigStore.class, GlobalConstants.MOTADATA_STORE, "Storage Profile Config Store");

    private static final StorageProfileConfigStore STORE = new StorageProfileConfigStore();

    private StorageProfileConfigStore()
    {
        super(DBConstants.TBL_STORAGE_PROFILE, LOGGER, false, List.of(
                Map.of(
                        REFERENCE_ENTITY, Entity.CONFIGURATION,
                        REFERENCE_ENTITY_PROPERTY, Configuration.CONFIG_STORAGE_PROFILE,
                        REFERENCE_ENTITY_STORE, ConfigStore.CONFIGURATION,
                        REFERENCE_ENTITY_PROPERTY_TYPE, ReferenceEntityPropertyType.VALUE
                ),
                Map.of(
                        REFERENCE_ENTITY, Entity.BACKUP_PROFILE,
                        REFERENCE_ENTITY_PROPERTY, BackupProfile.BACKUP_STORAGE_PROFILE,
                        REFERENCE_ENTITY_STORE, ConfigStore.BACKUP_PROFILE,
                        REFERENCE_ENTITY_PROPERTY_TYPE, ReferenceEntityPropertyType.VALUE
                )
        ));
    }

    public static StorageProfileConfigStore getStore()
    {
        return STORE;
    }

    @Override
    public Future<Void> initStore()
    {
        var promise = Promise.<Void>promise();

        try
        {
            Bootstrap.configDBService().getAll(DBConstants.TBL_STORAGE_PROFILE, result ->
            {
                if (result.succeeded())
                {
                    items.clear();

                    if (result.result() != null && !result.result().isEmpty())
                    {
                        for (var index = 0; index < result.result().size(); index++)
                        {
                            var item = result.result().getJsonObject(index);

                            // default system's two storage profile for backup. which won't be edited from UI.

                            if (item.getLong(GlobalConstants.ID).equals(10000000000001L))
                            {
                                item.put(StorageProfile.STORAGE_PROFILE_CONTEXT, new JsonObject()
                                        .put(GlobalConstants.STORAGE_PATH, CURRENT_DIR + PATH_SEPARATOR + "CONFIG-DB-BACKUP-LOCAL"));
                            }
                            else if (item.getLong(GlobalConstants.ID).equals(10000000000002L))
                            {
                                item.put(StorageProfile.STORAGE_PROFILE_CONTEXT, new JsonObject()
                                        .put(GlobalConstants.STORAGE_PATH, CURRENT_DIR + PATH_SEPARATOR + "REPORT-DB-BACKUP-LOCAL"));
                            }

                            items.put(item.getLong(GlobalConstants.ID), item);

                            if (CommonUtil.debugEnabled())
                            {
                                LOGGER.debug(String.format("item added %s into the store", CommonUtil.removeSensitiveFields(item, false).encodePrettily()));
                            }
                        }
                    }

                    promise.complete();

                    LOGGER.info(String.format("store %s initialized...", this.getClass().getSimpleName()));
                }
                else
                {
                    LOGGER.fatal(String.format("failed to init store %s , reason : %s...", this.getClass().getSimpleName(), result.cause()));

                    promise.fail(result.cause());
                }
            });
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);

            promise.fail(exception.getMessage());
        }

        return promise.future();
    }
}

