                .filter(item -> item.containsKey(flatField) && item.getString(flatField).equalsIgnoreCase(flatValue) &&
                        value.trim().contains(item.getString(field)))
                .map(JsonObject::copy)
                .collect(Collectors.toList()));

    }
}

