package com.mindarray.store;

import com.mindarray.Bootstrap;
import com.mindarray.GlobalConstants;
import com.mindarray.trace.TraceConstants;
import com.mindarray.util.DateTimeUtil;
import com.mindarray.util.Logger;
import io.vertx.core.Future;
import io.vertx.core.Promise;
import io.vertx.core.impl.ConcurrentHashSet;
import io.vertx.core.json.JsonArray;
import io.vertx.core.json.JsonObject;

import java.io.File;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicInteger;

import static com.mindarray.GlobalConstants.*;

/**
 * TraceCacheStore is a singleton class responsible for caching trace-related data
 * such as spans, trace context, service types, and metadata required for trace analysis.
 * This cache is primarily used for quick lookup and temporary storage of trace context
 * during runtime, and also helps filter out garbage attributes as configured from a JSON file.
 */
public class TraceCacheStore extends AbstractCacheStore
{
    private static final Logger LOGGER = new Logger(TraceCacheStore.class, MOTADATA_STORE, "Trace Cache Store");

    private static final TraceCacheStore STORE = new TraceCacheStore();

    // Maps trace ID to a map of span ID and its parent span ID
    private final Map<String, Map<String, String>> spansByTrace = new ConcurrentHashMap<>(); // key -> trace.id, value -> span.id, parent.span.id

    // Maps span ID to service dependency key
    private final Map<String, String> spansByService = new ConcurrentHashMap<>(); // key -> span.id, value -> dependency.key

    // Stores timestamp (in seconds) for each trace ID
    private final Map<String, Long> ticksByTrace = new ConcurrentHashMap<>(); // key -> trace.id, value -> timestamp

    // Maps service name to service type (e.g., WEB, DB, etc.)
    private final Map<String, Short> typeByService = new ConcurrentHashMap<>(); // key -> service, value -> service type (ex. Web, DB)

    // Set of unique event sources
    private final Set<String> sources = new ConcurrentHashSet<>();

    // Counter for tracking the number of events (spans) processed
    private static final AtomicInteger events = new AtomicInteger(TraceConstants.TRACE_MAX_EVENTS);

    private Set<String> garbageAttributes = new HashSet<>(); // Initializing at the startup only...

    private TraceCacheStore()
    {}

    /**
     * Initializes the trace cache store by loading garbage attributes from file.
     *
     * <p>This method reads the trace-garbage-attributes.json file from the database directory
     * and populates the garbageAttributes set with values that should be filtered out during
     * trace processing.</p>
     */
    @Override
    public Future<Void> initStore()
    {
        var futures = new ArrayList<Future<Void>>();

        var promise = Promise.<Void>promise();

        try
        {
            var future = Promise.<Void>promise();

            futures.add(future.future());

            var file = new File(GlobalConstants.CURRENT_DIR + GlobalConstants.PATH_SEPARATOR + GlobalConstants.DB_DIR + GlobalConstants.PATH_SEPARATOR + "trace-garbage-attributes.json");

            if (file.exists())
            {
                garbageAttributes = new HashSet<>(new JsonArray(Bootstrap.vertx().fileSystem().readFileBlocking(file.getPath())).getList());

                LOGGER.info("Garbage attributes loaded.");

                future.complete();
            }
            else
            {
                future.fail("Trace Garbage Attributes not found.");
            }

        }
        catch (Exception exception)
        {
            LOGGER.error(exception);

            promise.fail(exception);
        }

        Future.all(futures).onComplete(asyncResult ->
        {
            if (asyncResult.succeeded())
            {
                LOGGER.info("init completed...");

                promise.complete();
            }
            else
            {
                LOGGER.error(asyncResult.cause());

                promise.fail(asyncResult.cause());
            }
        });

        return promise.future();
    }

    public static TraceCacheStore getStore()
    {
        return STORE;
    }

    /**
     * Gets the set of trace data sources.
     *
     * <p>Returns the collection of registered trace data sources that are
     * currently active in the system.</p>
     *
     * @return A Set of strings representing the trace data sources
     */
    public Set<String> getSources()
    {
        return sources;
    }

    /**
     * Adds a new trace data source to the registry.
     *
     * <p>Registers a new source of trace data in the system.</p>
     *
     * @param source The identifier of the trace data source to add
     */
    public void addSource(String source)
    {
        sources.add(source);
    }

    /**
     * Removes a trace data source from the registry.
     *
     * <p>Unregisters a source of trace data from the system.</p>
     *
     +     * @param source The identifier of the trace data source to remove
     +     */
    public void removeSource(String source)
    {
        sources.remove(source);
    }

    /**
     * @return Map of trace IDs and their span-parent relationships
     */
    public Map<String, Map<String, String>> getSpansByTrace()
    {
        return spansByTrace;
    }

    /**
     * Retrieves the service name associated with a given span ID.
     *
     * @param spanId the span ID
     * @return the associated service name or null if not found
     */
    public String getService(String spanId)
    {
        return spansByService.get(spanId);
    }

    /**
     * Updates or inserts the span and its parent for a given trace ID.
     *
     * @param traceId      the trace identifier
     * @param spanId       the span identifier
     * @param parentSpanId the parent span identifier
     */
    public void updateTraceContext(String traceId, String spanId, String parentSpanId)
    {
        spansByTrace.computeIfAbsent(traceId, value -> new ConcurrentHashMap<>()).put(spanId, parentSpanId);
    }

    /**
     * Removes and returns the span context map for the specified trace ID.
     *
     * @param traceId the trace identifier
     * @return map of span ID to parent span ID
     */
    public Map<String, String> removeTraceContext(String traceId)
    {
        return spansByTrace.remove(traceId);
    }


    /**
     * Updates the expiry time of a trace by recording the current timestamp.
     *
     * @param traceId the trace identifier
     */
    public void updateTraceExpiryTime(String traceId)
    {
        ticksByTrace.put(traceId, DateTimeUtil.currentSeconds());
    }

    /**
     * @return Map of trace IDs and their associated timestamp (expiry time)
     */
    public Map<String, Long> getTicksByTrace()
    {
        return ticksByTrace;
    }

    /**
     * Removes the expiry timestamp entry for the given trace ID.
     *
     * @param traceId the trace identifier
     */
    public void removeTicksByTrace(String traceId)
    {
        ticksByTrace.remove(traceId);
    }

    /**
     * Updates the mapping between span ID and service/dependency key.
     *
     * @param spanId the span identifier
     * @param value  the associated service or dependency key
     */
    public void updateSpansByService(String spanId, String value)
    {
        spansByService.put(spanId, value);
    }

    /**
     * Removes the mapping for a span ID from the service map.
     *
     * @param spanId the span identifier
     */
    public void removeSpansByService(String spanId)
    {
        spansByService.remove(spanId);
    }

    /**
     * Removes all service type mappings related to the specified agent ID.
     * Used during agent de-registration or cleanup.
     *
     * @param agentId the agent identifier
     */
    public void remove(long agentId)
    {
        for (var key : AgentCacheStore.getStore().getItem(agentId).fieldNames())
        {
            if (key.startsWith(TraceConstants.TRACE_PREFIX))
            {
                typeByService.remove(key.replaceFirst(TraceConstants.TRACE_PREFIX, EMPTY_VALUE));
            }
        }
    }

    /**
     * Updates the service type for the given service name.
     *
     * @param service the service name
     * @param type    the service type code
     */
    public void updateServiceType(String service, short type)
    {
        typeByService.put(service, type);
    }

    /**
     * Retrieves the service type for a given service name.
     * Defaults to CUSTOM type if not present.
     *
     * @param service the service name
     * @return the associated service type
     */
    public short getServiceType(String service)
    {
        return typeByService.getOrDefault(service, TraceConstants.ServiceType.CUSTOM.getServiceType());
    }

    /**
     * @return Set of attribute keys considered garbage (to be ignored in traces)
     */
    public Set<String> getGarbageAttributes()
    {
        return garbageAttributes;
    }

    /**
     * Resets the event counter to the maximum allowed events.
     */
    public void reset()
    {
        events.set(TraceConstants.TRACE_MAX_EVENTS);
    }

    /**
     * Subtracts the specified number of events from the counter.
     * Ensures that the counter does not go below zero.
     *
     * @param event the number of events to subtract
     */
    public void subtract(int event)
    {
        while (true)
        {
            var value = events.get();

            // Atomically sets to new value only if the current value hasn't changed
            if (events.compareAndSet(value, value-event))
            {
                return;
            }
        }
    }

    /**
     * @return Current count of events (spans) processed
     */
    public int getEvents()
    {
        return events.get();
    }
}

