    /*
     *  method returns total count of instances(vm, access.point, interfaces, process) in monitor
     * */
    public int getInstances(long objectId)
    {
        var count = 0;

        try
        {
            if (instancesByObject.containsKey(objectId))
            {
                var instances = instancesByObject.get(objectId);

                if (instances.containsKey(NMSConstants.ACCESS_POINTS))
                {
                    count = instances.getJsonArray(NMSConstants.ACCESS_POINTS).size();

                    return count;

                }
                else if (instances.containsKey(NMSConstants.INTERFACES))
                {
                    count = instances.getJsonArray(NMSConstants.INTERFACES).size();

                    return count;
                }
                else if (instances.containsKey(NMSConstants.VMS))
                {
                    count = instances.getJsonArray(NMSConstants.VMS).size();

                    return count;
                }
                else if (instances.containsKey(NMSConstants.PROCESSES))
                {
                    count = instances.getJsonArray(NMSConstants.PROCESSES).size();

                    return count;
                }

            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }

        return count;
    }

    public void deleteMetrics(long objectId)
    {
        this.items.values().stream().filter(item -> item.getLong(Metric.METRIC_OBJECT).equals(objectId)).forEach(item -> MetricCacheStore.getStore().deleteMetric(item.getLong(ID)));
    }
}

