package com.mindarray.store;

import com.mindarray.Bootstrap;
import com.mindarray.GlobalConstants;
import com.mindarray.db.DBConstants;
import com.mindarray.eventbus.EventBusConstants;
import com.mindarray.log.LogPatternDetector;
import com.mindarray.util.Logger;
import io.vertx.core.Future;
import io.vertx.core.Promise;
import io.vertx.core.json.JsonObject;

public class LogParserConfigStore extends AbstractConfigStore
{

    private static final Logger LOGGER = new Logger(LogParserConfigStore.class, GlobalConstants.MOTADATA_STORE, "Log Parser Config Store");

    private static final LogParserConfigStore STORE = new LogParserConfigStore();

    private LogParserConfigStore()
    {
        super(DBConstants.TBL_LOG_PARSER, LOGGER, true);
    }

    public static LogParserConfigStore getStore()
    {
        return STORE;
    }

    @Override
    public Future<Void> initStore()
    {

        var promise = Promise.<Void>promise();

        super.initStore().onComplete(result ->
        {
            if (result.succeeded())
            {
                try
                {
                    LogPatternDetector.loadDefaultFormats();

                    promise.complete();
                }

                catch (Exception exception)
                {
                    promise.fail(exception);

                    LOGGER.warn("failed to init log parser config store...");

                    LOGGER.error(exception);
                }
            }

            else
            {
                promise.fail(result.cause());
            }
        });

        return promise.future();
    }

    @Override
    public void addItem(long id, JsonObject item)
    {
        if (item != null)
        {
            this.items.put(id, item);

            Bootstrap.vertx().eventBus().publish(EventBusConstants.EVENT_CHANGE_NOTIFICATION, new JsonObject()
                    .put(EventBusConstants.CHANGE_NOTIFICATION_TYPE, EventBusConstants.ChangeNotificationType.ADD_LOG_PARSER.name()).put(GlobalConstants.ID, id));
        }
    }

    @Override
    public void deleteItem(long id)
    {
        super.deleteItem(id);

        Bootstrap.vertx().eventBus().publish(EventBusConstants.EVENT_CHANGE_NOTIFICATION, new JsonObject()
                .put(EventBusConstants.CHANGE_NOTIFICATION_TYPE, EventBusConstants.ChangeNotificationType.DELETE_LOG_PARSER.name()).put(GlobalConstants.ID, id));
    }

    /**
     * @return generated plugin id incrementally
     */
    public int generatePluginId()
    {
        if (this.getItems().isEmpty())  // it will be required as in case of Hybrid-L as we do not provide any log parsers by default.
        {
            return 600500;
        }

        /*
         * to ensure that the plugin id is unique and incremented and it should not be clashed with existing plugin id of default parsers,
         * we will start a new series of plugin ID for custom parsers.
         * */
        return Math.max(600500, this.getItems().stream()
                .mapToInt(item -> JsonObject.mapFrom(item).getInteger(GlobalConstants.PLUGIN_ID))
                .max()
                .orElse(600500) + 1);
    }
}

