    /**
     * Initializes the ObjectConfigStore by loading all enabled, disabled, and maintenance objects from the database.
     * This method also initializes related stores and sets up internal mappings for efficient lookups.
     *
     * @return a Future that completes when the store initialization is finished
     */
    @Override
    public Future<Void> initStore()
    {

        var promise = Promise.<Void>promise();

        try
        {
            TagConfigStore.getStore().initStore().onComplete(asyncResult ->
            {
                LOGGER.info(String.format("store %s initialized...", this.getClass().getSimpleName()));

                Bootstrap.configDBService().get(DBConstants.TBL_OBJECT,
                        new JsonObject().put(DBConstants.FIELD_NAME, AIOpsObject.OBJECT_STATE).put(VALUE, new JsonArray().add(NMSConstants.State.ENABLE.name()).add(NMSConstants.State.DISABLE.name()).add(NMSConstants.State.MAINTENANCE.name())),
                        result ->
                        {
                            if (result.succeeded())
                            {
                                items.clear();

                                itemsByAgent.clear();

                                itemsByIP.clear();

                                itemsByObjectName.clear();

                                itemsByTarget.clear();

                                itemsByObjectId.clear();

                                itemsById.clear();

                                itemsByCategory.clear();

                                itemsByType.clear();

                                itemsByTag.clear();

                                itemsByInstanceTag.clear();

                                ObjectManagerCacheStore.getStore().initStore().onComplete(response ->
                                {
                                    if (result.result() != null && !result.result().isEmpty())
                                    {
                                        for (var index = 0; index < result.result().size(); index++)
                                        {
                                            var item = result.result().getJsonObject(index);

                                            items.put(item.getLong(GlobalConstants.ID), item);

                                            if (CommonUtil.debugEnabled())
                                            {
                                                LOGGER.debug(String.format("item added %s into the store", CommonUtil.removeSensitiveFields(item, false).encodePrettily()));
                                            }

                                            if (!item.getString(AIOpsObject.OBJECT_STATE).equalsIgnoreCase(NMSConstants.State.ENABLE.name()))
                                            {
                                                var status = switch (NMSConstants.State.valueOf(item.getString(AIOpsObject.OBJECT_STATE)))
                                                {
                                                    case DISABLE -> STATUS_DISABLE;

                                                    case MAINTENANCE -> STATUS_MAINTENANCE;

                                                    case SUSPEND -> STATUS_SUSPEND;

                                                    default -> STATUS_UNKNOWN;
                                                };

                                                LOGGER.info(String.format("updating state for object : %s with status : %s ", item.getString(AIOpsObject.OBJECT_STATE), status));

                                                ObjectStatusCacheStore.getStore().updateItem(item.getLong(ID), status, DateTimeUtil.currentSeconds());
                                            }

                                            init(item, false);
                                        }
                                    }

                                    MetricConfigStore.getStore().initStore().onComplete(asyncResponse ->
                                    {
                                        // Initialize instance tags from metrics
                                        var metricItems = MetricConfigStore.getStore().getItems();

                                        for (var index = 0; index < metricItems.size(); index++)
                                        {
                                            var item = metricItems.getJsonObject(index);

                                            var context = item.getJsonObject(Metric.METRIC_CONTEXT);

                                            if (context != null && context.containsKey(NMSConstants.OBJECTS))
                                            {
                                                var objects = context.getJsonArray(NMSConstants.OBJECTS);

                                                var instanceType = NMSConstants.INSTANCE_TYPES.getOrDefault(item.getString(Metric.METRIC_PLUGIN), "");

                                                if (objects != null && !objects.isEmpty() && !instanceType.isEmpty())
                                                {
                                                    updateInstanceTags(item.getLong(ID), objects);
                                                }
                                            }
                                        }

                                        LOGGER.info(String.format("store %s initialized...", this.getClass().getSimpleName()));

                                        ObjectCacheStore.getStore().initStore();

                                        SchedulerConfigStore.getStore().initStore().onComplete(future ->
                                        {
                                            LOGGER.info(String.format("store %s initialized...", this.getClass().getSimpleName()));

                                            promise.complete();
                                        });
                                    });

                                    //adding default object id(9999999) for plugins which are stored as Metric...
                                    itemsByPlugin.computeIfAbsent(DatastoreConstants.PluginId.LICENSE_STAT.getName(), value -> new JsonArray()).add(NMSConstants.DUMMY_OBJECT_ID);

                                    itemsByPlugin.computeIfAbsent(DatastoreConstants.PluginId.FLOW_STAT.getName(), value -> new JsonArray()).add(NMSConstants.DUMMY_OBJECT_ID);

                                    itemsById.put(CommonUtil.getLong(NMSConstants.DUMMY_OBJECT_ID),NMSConstants.DUMMY_OBJECT_ID);

                                    populateItemsByProfile(UserProfileConfigStore.getStore().getItems());

                                    populateItemsByUser(UserConfigStore.getStore().getItems());
                                });
                            }
                            else
                            {
                                LOGGER.fatal(String.format("failed to init store %s , reason : %s...", this.getClass().getSimpleName(), result.cause()));

                                promise.fail(result.cause());
                            }
                        });
            });
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);

            promise.fail(exception.getMessage());
        }

        return promise.future();
    }

    /**
     * Retrieves the object ID for a given internal ID.
     *
     * @param id the internal ID of the object
     * @return the object ID if found, otherwise NOT_AVAILABLE
     */
    public int getObjectId(long id)
    {
        return items.containsKey(id) ? CommonUtil.getInteger(items.get(id).getValue(AIOpsObject.OBJECT_ID)) : NOT_AVAILABLE;
    }

    /**
     * Generates the next available object ID by finding the maximum existing object ID and incrementing it.
     *
     * @return the next available object ID
     */
    public int getNextObjectId()
    {
        return items.values().stream().mapToInt(item -> item.getInteger(AIOpsObject.OBJECT_ID)).max().orElse(0) + 1;
    }

    /**
     * Retrieves the object name for a given internal ID.
     * If the object is not found in the active store, it searches in the archived store.
     *
     * @param id the internal ID of the object
     * @return the object name if found, otherwise an empty string
     */
    public String getObjectName(long id)
    {
        var objectName = items.containsKey(id) ? items.get(id).getString(AIOpsObject.OBJECT_NAME) : GlobalConstants.EMPTY_VALUE;

        if (CommonUtil.isNullOrEmpty(objectName))
        {
            objectName = ArchivedObjectConfigStore.getStore().getObjectName(id);
        }

        return objectName;
    }

    /**
     * Retrieves object names for a collection of internal IDs.
     * For each ID, if the object is not found in the active store, it searches in the archived store.
     *
     * @param ids the array of internal IDs
     * @return a JsonArray containing the object names that were found
     */
    public JsonArray getObjectNames(JsonArray ids)
    {
        var objects = new JsonArray();

        for (var index = 0; index < ids.size(); index++)
        {
            var id = ids.getLong(index);

            var objectName = items.containsKey(id) ? items.get(id).getString(AIOpsObject.OBJECT_NAME) : GlobalConstants.EMPTY_VALUE;

            if (CommonUtil.isNullOrEmpty(objectName))
            {
                objectName = ArchivedObjectConfigStore.getStore().getObjectName(id);
            }

            if (!objectName.isEmpty())
            {
                objects.add(objectName);
            }
        }

        return objects;
    }

    /**
     * Retrieves the object name for a given agent ID.
