   /**
    * Filters objects based on tag-based access control rules defined in a user profile context.
    * Evaluates tag conditions using AND/OR logic and inclusive/exclusive rules.
    *
    * @param context the user profile context containing tag rules
    * @param ids the array of object IDs to evaluate
    * @param qualifiedObjects the output array to populate with qualified objects
    * @param idRequired if true, adds internal IDs; if false, adds object IDs
    */
   public void getItemsByTag(JsonObject context, JsonArray ids, JsonArray qualifiedObjects, boolean idRequired)
   {
       var tagContext = context.getJsonObject(UserProfile.TAG_CONTEXT);

       var conditions = tagContext.getJsonArray(TagRule.TAG_RULE_CONDITIONS);

       var inclusive = tagContext.getString(TagRule.TAG_RULE_INCLUSIVE_CONDITION).equalsIgnoreCase(YES);

       for (var index = 0; index < ids.size(); index++)
       {
           var item = ObjectConfigStore.getStore().getItem(ids.getLong(index), false);

           var status = false;

           for (var i = 0; i < conditions.size(); i++)
           {
               var condition = conditions.getJsonObject(i);

               var objectTags = item.getJsonArray(AIOpsObject.OBJECT_TAGS, new JsonArray());

               var tag = CommonUtil.getInteger(TagConfigStore.getStore().getTag(condition.getString(VisualizationConstants.DATA_POINT)));

               var tagExists = objectTags.contains(tag);

               // Apply inclusive/exclusive logic
               var conditionResult = inclusive == tagExists;

               // Apply AND/OR logic
               var filterType = condition.getString(FILTER);

               if (DatastoreConstants.ConditionGroup.AND.getName().equalsIgnoreCase(filterType))
               {
                   status = status && conditionResult;
               }
               else if (DatastoreConstants.ConditionGroup.OR.getName().equalsIgnoreCase(filterType))
               {
                   status = status || conditionResult;
               }
               else
               {
                   status = conditionResult;
               }
           }

           if (status)
           {
               qualifiedObjects.add(idRequired ? item.getLong(ID) : item.getInteger(AIOpsObject.OBJECT_ID));
           }
       }
   }

