    /**
     * Upserts a batch of items into the in-memory store and notifies listeners of each update.
     *
     * Each element in the provided {@code items} array is expected to be a {@link io.vertx.core.json.JsonObject}
     * containing the internal identifier field referenced by {@link GlobalConstants#ID}. For every record:
     * - The record is stored in the store's {@code items} map keyed by the internal ID.
     * - A notification is emitted using {@code notify(REQUEST_UPDATE, id, record)} to inform registered listeners
     *   of the update.
     *
     * Any exception encountered while processing the batch is caught and logged via the store logger; the method
     * does not propagate exceptions to callers.
     *
     * @param items a {@link io.vertx.core.json.JsonArray} of {@link io.vertx.core.json.JsonObject} records to upsert
     */
    public void updateAll(JsonArray items)
    {
        try
        {
            for (var index = 0; index < items.size(); index++)
            {
                var record = items.getJsonObject(index);

                CommonUtil.decryptSensitiveFields(record, cipherUtil);

                this.items.put(record.getLong(ID), record);

                notify(REQUEST_UPDATE, record.getLong(GlobalConstants.ID), record);

                Bootstrap.vertx().eventBus().send(EventBusConstants.EVENT_PUBLICATION, new JsonObject().put(EventBusConstants.EVENT_TYPE, EventBusConstants.EVENT_CHANGE_NOTIFICATION)
                        .put(EventBusConstants.CHANGE_NOTIFICATION_TYPE, EventBusConstants.ChangeNotificationType.UPDATE_OBJECT.name())
                        .put(EventBusConstants.EVENT_TOPIC, EventBusConstants.REMOTE_EVENT_PROCESSOR_TOPIC)
                        .put(ID, record.getLong(GlobalConstants.ID)));

                Bootstrap.vertx().eventBus().publish(EventBusConstants.EVENT_CHANGE_NOTIFICATION,
                        new JsonObject().put(EventBusConstants.CHANGE_NOTIFICATION_TYPE, EventBusConstants.ChangeNotificationType.UPDATE_OBJECT.name())
                                .put(ID, record.getLong(GlobalConstants.ID)));
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }


    /**
     * Adds a new item to the store and initializes its mappings.
     * Also handles duplicate entries in the archived store and notifies listeners.
     *
     * @param id the internal ID of the item to add
     * @return a Future that completes when the item is successfully added
     */
    @Override
    public Future<Void> addItem(long id)
    {
        return super.addItem(id).onComplete(result ->
        {

            if (result.succeeded())
            {
                try
                {
                    var item = items.get(id).copy();

                    init(item, false);

                    notify(item, REQUEST_CREATE);

                    //if there is any old entry found for same object.id in Archived config store,then we will drop that and insert new object
                    if (ArchivedObjectConfigStore.getStore().getIdByObjectId(ObjectConfigStore.getStore().getObjectIdById(id)) != DUMMY_ID && ArchivedObjectConfigStore.getStore().getIdByObjectId(ObjectConfigStore.getStore().getObjectIdById(id)) != id)
                    {
                        LOGGER.info("Duplicate entry found for object.id " + ObjectConfigStore.getStore().getObjectIdById(id) + " in object table,deleting old entry...");

                        Bootstrap.configDBService().delete(DBConstants.TBL_OBJECT,
                                new JsonObject().put(DBConstants.FIELD_NAME, ID).put(VALUE, ArchivedObjectConfigStore.getStore().getIdByObjectId(ObjectConfigStore.getStore().getObjectIdById(id))),
                                DEFAULT_USER, SYSTEM_REMOTE_ADDRESS,

     * @return a Future that completes when the item is successfully added
     */
    @Override
    public Future<Void> addItem(long id)
    {
        return super.addItem(id).onComplete(result ->
        {

            if (result.succeeded())
            {
                try
                {
                    var item = items.get(id).copy();

                    init(item, false);

                    notify(item, REQUEST_CREATE);

                    //if there is any old entry found for same object.id in Archived config store,then we will drop that and insert new object
                    if (ArchivedObjectConfigStore.getStore().getIdByObjectId(ObjectConfigStore.getStore().getObjectIdById(id)) != DUMMY_ID && ArchivedObjectConfigStore.getStore().getIdByObjectId(ObjectConfigStore.getStore().getObjectIdById(id)) != id)
                    {
                        LOGGER.info("Duplicate entry found for object.id " + ObjectConfigStore.getStore().getObjectIdById(id) + " in object table,deleting old entry...");

                        Bootstrap.configDBService().delete(DBConstants.TBL_OBJECT,
                                new JsonObject().put(DBConstants.FIELD_NAME, ID).put(VALUE, ArchivedObjectConfigStore.getStore().getIdByObjectId(ObjectConfigStore.getStore().getObjectIdById(id))),
                                DEFAULT_USER, SYSTEM_REMOTE_ADDRESS,
                                asyncResult ->
                                {

                                    if (asyncResult.succeeded())
                                    {
                                        LOGGER.info("Duplicate entry deleted from object table... " + ArchivedObjectConfigStore.getStore().getIdByObjectId(ObjectConfigStore.getStore().getObjectIdById(id)));

                                        ArchivedObjectConfigStore.getStore().deleteItem(ArchivedObjectConfigStore.getStore().getIdByObjectId(ObjectConfigStore.getStore().getObjectIdById(id)));

                                        ArchivedObjectConfigStore.getStore().addItem(id);
                                    }
                                    else
                                    {
                                        LOGGER.warn("Duplicate entry is not deleted from object table...");
                                    }

                                });
                    }
                    else
                    {
                        ArchivedObjectConfigStore.getStore().addItem(id);
                    }
                }
                catch (Exception exception)
                {
                    LOGGER.error(exception);
                }
            }
        });
    }

    /**
     * Deletes an item from the store and cleans up all associated mappings.
     * Also updates the archived store and notifies listeners.
     *
     * @param id the internal ID of the item to delete
     */
    @Override
    public void deleteItem(long id)
    {
        var item = items.get(id);

        super.deleteItem(id);

        ArchivedObjectConfigStore.getStore().updateItem(id);

        // Remove existing tag mappings to re-assign
        removeItemsByTag(itemsById.get(id), false);

        // Still call TagCacheStore for backward compatibility during migration
        TagCacheStore.getStore().deleteTagsByMonitor(itemsById.get(id));

        ObjectCacheStore.getStore().delete(id);

        itemsById.remove(id);

        itemsByObjectId.values().remove(id);

        if (item.getString(AIOpsObject.OBJECT_CATEGORY).equalsIgnoreCase(NMSConstants.Category.SERVER.getName()) && item.getLong(AIOpsObject.OBJECT_AGENT) != null)
        {
            itemsByAgent.remove(item.getLong(AIOpsObject.OBJECT_AGENT));
        }

        if (item.getString(AIOpsObject.OBJECT_NAME) != null)
        {
            itemsByObjectName.remove(item.getString(AIOpsObject.OBJECT_NAME));
        }

        if (!item.getString(AIOpsObject.OBJECT_CATEGORY).equalsIgnoreCase(NMSConstants.Category.SERVICE_CHECK.getName()))
        {
            if (item.getString(AIOpsObject.OBJECT_IP) != null)
            {
                itemsByIP.remove(item.getString(AIOpsObject.OBJECT_IP));
            }

            if (item.getString(AIOpsObject.OBJECT_TARGET) != null)
            {
                itemsByTarget.remove(item.getString(AIOpsObject.OBJECT_TARGET));
            }
        }

        for (var items : itemsByPlugin.values())
        {
            items.remove(id);
        }

        var objectGroups = item.getJsonArray(AIOpsObject.OBJECT_GROUPS);

        if (objectGroups != null && !objectGroups.isEmpty())
        {
            for (var index = 0; index < objectGroups.size(); index++)
            {
                if (itemsByGroup.get(objectGroups.getLong(index)) != null)
                {
                    itemsByGroup.get(objectGroups.getLong(index)).remove(CommonUtil.getString(id));
                }
            }
        }

        itemsByCategory.get(item.getString(AIOpsObject.OBJECT_CATEGORY)).remove(item.getInteger(OBJECT_ID));

        itemsByType.get(item.getString(AIOpsObject.OBJECT_TYPE)).remove(item.getLong(OBJECT_ID));

        itemsByProfile.values().forEach(items -> items.remove(id));

        itemsByUser.values().forEach(items -> items.remove(id));

        notify(item, REQUEST_DELETE);
    }

    /**
     * Updates an item in the store and refreshes its mappings.
     * Also updates the archived store and notifies listeners.
     *
     * @param id the internal ID of the item to update
     * @return a Future that completes when the item is successfully updated
