    /**
     * Retrieves objects by type and complex field matching criteria.
     * Filters objects by type, key-value pair, and nested object field value.
     *
     * @param type the object type to filter by
     * @param key the field name to match
     * @param value the value to match against the field
     * @param flatField the nested object field name
     * @param flatValue the key within the nested object
     * @param field the expected value within the nested object
     * @return a JsonArray containing copies of matching objects
     */
    public JsonArray flatItemsByMapValueField(NMSConstants.Type type, String key, String value, String flatField, String flatValue, Integer field)
    {
        return new JsonArray(items.values().stream()
                .filter(item -> item.getString(AIOpsObject.OBJECT_TYPE).equalsIgnoreCase(type.getName()) &&
                        item.getString(key).equalsIgnoreCase(value) && item.getJsonObject(flatField) != null && item.getJsonObject(flatField).containsKey(flatValue)
                        && item.getJsonObject(flatField).getValue(flatValue).equals(field))
                .map(JsonObject::copy)
                .collect(Collectors.toList()));
    }

