   /**
    * assign a monitor to a tag at the object level or instance level.
    *
    * @param tagId The ID of the tag
    * @param objectId The ID of the monitor
    * @param instance Whether this is an instance-level tag (true) or object-level tag (false)
    */
   public void assign(long tagId, String objectId, boolean instance)
   {
       if (instance)
       {
           itemsByInstanceTag.computeIfAbsent(tagId, k -> Collections.newSetFromMap(new ConcurrentHashMap<>())).add(objectId);
       }
       else
       {
           itemsByTag.computeIfAbsent(tagId, k -> Collections.newSetFromMap(new ConcurrentHashMap<>())).add(objectId);
       }
   }

