    * Removes a monitor from all tags at the object level or instance level.
    *
    * @param objectId The ID of the object/monitor to remove
    * @param instance Whether to remove from instance-level tags (true) or object-level tags (false)
    */
   public void removeItemsByTag(long objectId, boolean instance)
   {
       if (instance)
       {
           removeTags(CommonUtil.getString(objectId), itemsByInstanceTag);
       }
       else
       {
           removeTags(CommonUtil.getString(objectId), itemsByTag);
       }
   }

   /**
    * Removes a monitor from a tag mapping and cleans up empty tag entries.
    *
    * @param objectId The ID of the object/monitor to remove
    * @param entitiesByTag The map to remove the monitor from
    */
   private void removeTags(String objectId, Map<Long, Set<String>> entitiesByTag)
   {
       entitiesByTag.forEach((tagId, entities) ->
       {
           entities.remove(objectId);

           // Remove tag entry if no monitors are assigned to it
           if (entities.isEmpty())
           {
               entitiesByTag.remove(tagId);
           }
       });
   }

