       {
           for (var tagIndex = 0; tagIndex < item.getJsonArray(AIOpsObject.OBJECT_TAGS).size(); tagIndex++)
           {
               assign(item.getJsonArray(AIOpsObject.OBJECT_TAGS).getLong(tagIndex), item.getString(OBJECT_ID), false);
           }
