       ObjectCacheStore.getStore().updateItemsByTags(item.getJsonArray(AIOpsObject.OBJECT_TAGS));

       WidgetConfigStore.getStore().updateItemsByTags(item.getJsonArray(AIOpsObject.OBJECT_TAGS));
   }

