   /**
    * Updates instance tags for a metric item. This method is used to track tags assigned to specific instances
    * within an object (e.g., interfaces, VMs).
    *
    * @param id The ID of the metric item
    * @param objects The array of objects containing instance tags
    */
   public void updateInstanceTags(long id, JsonArray objects)
   {
       try
       {
           var objectId = getObjectId(MetricConfigStore.getStore().getMetricObjectId(id));

           // First remove existing instance tags for this object
           removeItemsByTag(objectId, true);

           // Process new instance tags
           for (var index = 0; index < objects.size(); index++)
           {
               var object = objects.getJsonObject(index);

               if (object.containsKey(GlobalConstants.INSTANCE_TAGS))
               {
                   var instanceTags = object.getJsonArray(GlobalConstants.INSTANCE_TAGS);

                   for (var tagIndex = 0; tagIndex < instanceTags.size(); tagIndex++)
                   {
                       var tagId = instanceTags.getLong(tagIndex);

                       assign(tagId, CommonUtil.getString(objectId), true);
                   }
               }
           }
       }
       catch (Exception exception)
       {
           LOGGER.warn("Unable to update instance tags for metric item: " + id);

           LOGGER.error(exception);
       }
   }

   /**
    * Updates the itemsByProfile and itemsByUser maps for a specific object ID based on group membership.
    * This method evaluates whether the given object qualifies for access by various user profiles and users
    * based on the groups the object belongs to.
    *
    * <p>The method performs two main operations:</p>
    * <ul>
    *   <li><b>Profile-based access:</b> For GROUP-scoped profiles, checks if the object belongs to any of the
    *       profile's groups and updates the itemsByProfile map accordingly</li>
    *   <li><b>User-based access:</b> For users, checks if the object belongs to any of the user's groups
    *       and updates the itemsByUser map accordingly. The default user (ID = 1) has access to all objects</li>
    * </ul>
    *
    * <p>Access qualification logic:</p>
    * <ul>
    *   <li>For profiles: Object qualifies if any of its groups match any of the profile's groups (ENTITIES)</li>
    *   <li>For users: Object qualifies if any of its groups match any of the user's groups (USER_GROUPS)</li>
    *   <li>Default user: Always has access to all objects regardless of group membership</li>
    * </ul>
    *
    * <p>This method should be called when:</p>
    * <ul>
    *   <li>An object's groups are modified (added/removed)</li>
    *   <li>A new object is added to the system with group assignments</li>
    *   <li>Object group membership changes that affect user/profile access</li>
    * </ul>
    *
    * @param objectId the internal ID of the object to evaluate for profile and user access
    */
   public void updateItemsByUser(long objectId)
   {
       try
       {
           var profiles = UserProfileConfigStore.getStore().getItems();

           var users = UserConfigStore.getStore().getItems();

           var object = ObjectConfigStore.getStore().getItem(objectId, false);

           var groups = object.getJsonArray(AIOpsObject.OBJECT_GROUPS);

           if (profiles != null && !profiles.isEmpty())
           {
               for (var index = 0; index < profiles.size(); index++)
               {
                   var profile = profiles.getJsonObject(index);

                   var profileId = profile.getLong(ID);

                   var context = profile.getJsonObject(UserProfile.USER_PROFILE_CONTEXT);

                   if (UserProfile.UserProfileScopeType.GROUP.getName().equalsIgnoreCase(context.getString(UserProfile.USER_PROFILE_SCOPE_TYPE)))
                   {
                       var profileGroups = context.getJsonArray(ENTITIES);

                       // Get or create the set for this profile
                       var objects = itemsByProfile.computeIfAbsent(profileId, k -> new ConcurrentHashSet<>());

                       // Update the set based on qualification result
                       if (profileGroups.stream().anyMatch(groups::contains))
                       {
                           objects.add(objectId);
                       }
                       else
                       {
                           objects.remove(objectId);
                       }
                   }
               }
           }

           for (var index = 0; index < users.size(); index++)
           {
               try
               {
                   var user = users.getJsonObject(index);

                   var userId = user.getLong(ID);

                   var objects = itemsByUser.computeIfAbsent(userId, k -> new ConcurrentHashSet<>());

                   if (userId.equals(DEFAULT_ID) || user.getJsonArray(User.USER_GROUPS).stream().anyMatch(groups::contains))
                   {
                       objects.add(objectId);
                   }
                   else
                   {
                       objects.remove(objectId);
                   }
               } catch (Exception e)
               {
                   LOGGER.error(e);
               }

           }
       }
       catch (Exception exception)
       {
           LOGGER.error(exception);
       }
   }

