    /**
     * Populates the itemsByProfile map with profile IDs as keys and sets of object IDs as values.
     * This method processes all provided user profiles and maps each profile to the objects that
     * are accessible based on the profile's group configuration.
     *
     * <p>The itemsByProfile map structure:</p>
     * <ul>
     *   <li>Key: Profile ID (Long)</li>
     *   <li>Value: Set of object internal IDs (Set&lt;Long&gt;) that belong to the profile's groups</li>
     * </ul>
     *
     * <p>Processing logic:</p>
     * <ul>
     *   <li>For each profile, retrieves the groups defined in the profile context (ENTITIES field)</li>
     *   <li>Uses {@link #getItemsByGroups(JsonArray)} to find all objects belonging to those groups</li>
     *   <li>If objects are found, creates/updates the profile's entry in the map</li>
     *   <li>If no objects are found and the profile exists in the map, clears the profile's set</li>
     * </ul>
     *
     * <p>This method is typically called during:</p>
     * <ul>
     *   <li>System initialization to build the initial profile-to-object mappings</li>
     *   <li>Profile updates when profile group configurations change</li>
     *   <li>Bulk refresh operations to rebuild the entire map</li>
     * </ul>
     *
     * <p><b>Note:</b> This method processes all profiles at once. For single object updates</p>
     *
     * @param profiles a JsonArray containing user profile objects to process
     */
    public void populateItemsByProfile(JsonArray profiles)
    {
        try
        {
            if (profiles != null && !profiles.isEmpty())
            {
                // Get all object IDs to evaluate
                var ids = ObjectConfigStore.getStore().getIds();

                if (ids != null && !ids.isEmpty())
                {
                    for (var index = 0; index < profiles.size(); index++)
                    {
                        var profile = profiles.getJsonObject(index);

                        var id = profile.getLong(ID);

                        var context = profile.getJsonObject(UserProfile.USER_PROFILE_CONTEXT);

                        var items = getItemsByGroups(context.getJsonArray(ENTITIES));

                        if(items.isEmpty() && itemsByProfile.containsKey(id))
                        {
                            itemsByProfile.get(id).clear();
                        }
                        else
                        {
                            var objects = new ConcurrentHashSet<Long>();

                            for (var objIndex = 0; objIndex < items.size(); objIndex++)
                            {
                                objects.add(items.getLong(objIndex));
                            }

                            itemsByProfile.put(id, objects);
                        }
                    }
                }
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

    /**
     * Populates the itemsByUser map with user IDs as keys and sets of object IDs as values.
     * This method processes all provided users and maps each user to the objects that are
     * accessible based on the user's group membership.
     *
     * <p>The itemsByUser map structure:</p>
     * <ul>
     *   <li>Key: User ID (Long)</li>
     *   <li>Value: Set of object internal IDs (Set&lt;Long&gt;) that belong to the user's groups</li>
     * </ul>
     *
     * <p>Processing logic:</p>
     * <ul>
     *   <li>For the default user (ID = 1): Grants access to all objects in the system</li>
     *   <li>For regular users: Retrieves the groups defined in the user's USER_GROUPS field</li>
     *   <li>Uses {@link #getItemsByGroups(JsonArray)} to find all objects belonging to those groups</li>
     *   <li>If objects are found, creates/updates the user's entry in the map</li>
     *   <li>If no objects are found and the user exists in the map, clears the user's set</li>
     * </ul>
     *
     * <p>Special handling:</p>
     * <ul>
     *   <li><b>Default User:</b> The default user (ID = 1) has unrestricted access to all objects,
     *       regardless of group membership</li>
     *   <li><b>Empty Groups:</b> Users with no groups assigned will have an empty set or cleared entry</li>
     * </ul>
     *
     * <p>This method is typically called during:</p>
     * <ul>
     *   <li>System initialization to build the initial user-to-object mappings</li>
     *   <li>User updates when user group assignments change</li>
     *   <li>Bulk refresh operations to rebuild the entire map</li>
     * </ul>
     *
     * <p><b>Note:</b> This method processes all users at once. For single object updates</p>
     *
     * @param users a JsonArray containing user objects to process
     */
    public void populateItemsByUser(JsonArray users)
    {
        try
        {
            if(users != null && !users.isEmpty())
            {
                for(var index = 0; index < users.size(); index++)
                {
                    var user = users.getJsonObject(index);

                    var userId = user.getLong(ID);

                    var items = new JsonArray();

                    items = userId.equals(DEFAULT_ID) ? ObjectConfigStore.getStore().getIds() : getItemsByGroups(user.getJsonArray(User.USER_GROUPS));

                    if(items.isEmpty() && itemsByUser.containsKey(userId))
                    {
                        itemsByUser.get(userId).clear();
                    }
                    else
                    {
                        var objects = new ConcurrentHashSet<Long>();

                        for (var objIndex = 0; objIndex < items.size(); objIndex++)
                        {
                            objects.add(items.getLong(objIndex));
                        }

                        itemsByUser.put(userId, objects);
                    }
                }
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

    /**
     * Remove the profile from the map
     * <p>
     * Used when a profile is deleted
     *
     * @param id The internal ID of the object to remove
     */
    public void removeProfile(long id)
    {
        itemsByProfile.remove(id);
    }

    /**
     * Remove the user from the map
     * <p>
     * Used when a user is deleted
     *
     * @param id The internal ID of the object to remove
     */
    public void removeUser(long id)
    {
        itemsByUser.remove(id);
    }

    /**
     * Updates the IP-to-object ID mapping by replacing the oldIp IP with the new IP.
     * <p>
     * This is typically used when an object has a dynamic IP that changes, and the internal mapping
     * (used for quick lookup) needs to reflect the updated address.
     *
     * @param oldIp       The oldIp IP address currently associated with the object.
     * @param updatedIp The new IP address to associate with the object.
     */
    public void updateIP(String oldIp, String updatedIp)
    {
        if (itemsByIP.containsKey(oldIp) && !oldIp.equalsIgnoreCase(updatedIp))
        {
            itemsByIP.put(updatedIp, itemsByIP.remove(oldIp));
        }
    }
}

