import static com.mindarray.GlobalConstants.NO;

public class SLOProfileConfigStore extends AbstractConfigStore
{
    private static final Logger LOGGER = new Logger(SLOProfileConfigStore.class, GlobalConstants.MOTADATA_STORE, "SLO Profile Config Store");

    private static final SLOProfileConfigStore STORE = new SLOProfileConfigStore();

    private final Map<Long, JsonObject> activeSLOProfiles = new ConcurrentHashMap<>();

    private final AtomicLong COUNTER = new AtomicLong(0);

    private SLOProfileConfigStore()
    {
        super(DBConstants.TBL_SLO_PROFILE, LOGGER, false);
    }

    public static SLOProfileConfigStore getStore()
    {
        return STORE;
    }

    @Override
    public Future<Void> initStore()
    {
        var promise = Promise.<Void>promise();

        try
        {
            Bootstrap.configDBService().getAll(DBConstants.TBL_SLO_PROFILE, result ->
            {
                if (result.succeeded())
                {
                    var maximum = 0;

                    items.clear();

                    if (result.result() != null && !result.result().isEmpty())
                    {
                        for (var index = 0; index < result.result().size(); index++)
                        {
                            var item = result.result().getJsonObject(index);

                            if (item.getInteger(GlobalConstants.ID) > maximum)
                            {
                                maximum = item.getInteger(GlobalConstants.ID);
                            }

                            if (!item.containsKey(SLOProfile.SLO_PROFILE_ARCHIVED) || item.getString(SLOProfile.SLO_PROFILE_ARCHIVED).equalsIgnoreCase(NO))
                            {
                                items.put(item.getLong(GlobalConstants.ID), item);

                                if (item.containsKey(SLOCycle.SLO_CYCLE_ID))
                                {
                                    activeSLOProfiles.put(item.getLong(GlobalConstants.ID), item);
                                }
                            }

                            if (CommonUtil.debugEnabled())
                            {
                                LOGGER.debug(String.format("item added %s into the store", CommonUtil.removeSensitiveFields(item, false).encodePrettily()));
                            }
                        }
                    }

                    COUNTER.set(maximum);

                    promise.complete();

                    LOGGER.info(String.format("store %s initialized...", this.getClass().getSimpleName()));
                }
                else
                {
                    promise.fail(result.cause());

                    LOGGER.fatal(String.format("failed to init store %s , reason : %s...", this.getClass().getSimpleName(), result.cause()));
                }
            });
        }
        catch (Exception exception)
        {
            promise.fail(exception);

            LOGGER.error(exception);
        }

        return promise.future();
    }

    public long newId()
    {
        return COUNTER.incrementAndGet();
    }

    public JsonArray getActiveSLOProfiles()
    {
        return new JsonArray(new ArrayList<>(this.activeSLOProfiles.values()));
    }

    public JsonArray getActiveSLOProfileIds()
    {
        return new JsonArray(new ArrayList<>(activeSLOProfiles.keySet()));
    }

    @Override
    public Future<Void> updateItem(long id)
    {
        return super.updateItem(id).onComplete(result ->
        {
            var item = items.get(id);

            if (item.containsKey(SLOCycle.SLO_CYCLE_ID))
            {
                activeSLOProfiles.put(item.getLong(GlobalConstants.ID), item);
            }
        });
    }

    @Override
    public void deleteItem(long id)
    {
        super.deleteItem(id);

        activeSLOProfiles.remove(id);
    }
}

