package com.mindarray.store;

import com.mindarray.Bootstrap;
import com.mindarray.GlobalConstants;
import com.mindarray.slo.SLOConstants;
import com.mindarray.util.CodecUtil;
import com.mindarray.util.CommonUtil;
import com.mindarray.util.Logger;
import io.vertx.core.Future;
import io.vertx.core.Promise;
import io.vertx.core.buffer.Buffer;
import io.vertx.core.json.JsonObject;

import java.io.File;
import java.util.HashMap;
import java.util.Map;
import java.util.TreeMap;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicBoolean;

import static com.mindarray.GlobalConstants.*;
import static com.mindarray.GlobalConstants.PATH_SEPARATOR;

public class SLOCalculatorCacheStore extends AbstractCacheStore
{
    private static final SLOCalculatorCacheStore STORE = new SLOCalculatorCacheStore();

    private static final Logger LOGGER = new Logger(SLOCalculatorCacheStore.class, GlobalConstants.MOTADATA_STORE, "SLO Calculator Cache Store");

    private static final Map<Long, Map<String, JsonObject>> sloDetails = new ConcurrentHashMap<>();

    private static final Map<Long, TreeMap<Long, Integer>> sloEvents = new ConcurrentHashMap<>();

    private final AtomicBoolean updated = new AtomicBoolean();

    private final AtomicBoolean dirty = new AtomicBoolean();

    private SLOCalculatorCacheStore()
    {
    }

    public static SLOCalculatorCacheStore getStore()
    {
        return STORE;
    }

    @Override
    public Future<Void> initStore()
    {
        var promise = Promise.<Void>promise();

        try
        {
            var file = new File(CURRENT_DIR + PATH_SEPARATOR + CONFIG_DIR + PATH_SEPARATOR + SLOConstants.SLO_CACHE_FILE);

            if (file.exists())
            {
                var buffer = Bootstrap.vertx().fileSystem().readFileBlocking(file.getPath());

                if (buffer != null && buffer.getBytes().length > 0)
                {
                    var context = new JsonObject(Buffer.buffer(CodecUtil.toBytes(buffer.getBytes()))).getMap();

                    if (context.containsKey("items"))
                    {
                        for (var entry : ((Map<String, Object>) context.get("items")).entrySet())
                        {
                            var key = entry.getKey();

                            var value = (Map<String, Object>) entry.getValue();

                            var map = new HashMap<String, JsonObject>();

                            for (var e: value.entrySet())
                            {
                                map.put(e.getKey(), JsonObject.mapFrom(e.getValue()));
                            }

                            sloDetails.put(CommonUtil.getLong(key), map);
                        }
                    }

                    if (context.containsKey("events"))
                    {
                        for (var entry : ((Map<String, Object>) context.get("events")).entrySet())
                        {
                            var key = entry.getKey();

                            var value = (Map<String, Object>) entry.getValue();

                            var map = new TreeMap<Long, Integer>();

                            for (var e: value.entrySet())
                            {
                                map.put(CommonUtil.getLong(e.getKey()), CommonUtil.getInteger(e.getValue()));
                            }

                            sloEvents.put(CommonUtil.getLong(key), map);
                        }
                    }

                    LOGGER.info(String.format("%s loaded...", SLOConstants.SLO_CACHE_FILE));
                }
            }
            else
            {
                LOGGER.info(String.format("%s created...", SLOConstants.SLO_CACHE_FILE));

                Bootstrap.vertx().fileSystem().createFileBlocking(file.getPath());
            }

            promise.complete();
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);

            promise.fail(exception.getMessage());
        }

        return promise.future();
    }

    public void init(long sloId)
    {
        sloDetails.put(sloId, new HashMap<>());

        sloEvents.put(sloId, new TreeMap<>());
    }

    public Map<String, JsonObject> clear(long sloId)
    {
        Map<String, JsonObject> details = null;

        try
        {
            sloEvents.remove(sloId);

            details = sloDetails.remove(sloId);

            setUpdate(true);
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }

        return details;
    }

    public Map<String, JsonObject> getSLODetails(long sloId)
    {
        return sloDetails.get(sloId);
    }

    public TreeMap<Long, Integer> getSLOEvents(long sloId)
    {
        return sloEvents.get(sloId);
    }

    public boolean updated()
    {
        return updated.get();
    }

    public boolean dirty()
    {
        return dirty.get();
    }

    public void setDirty(boolean value)
    {
        dirty.set(value);
    }

    public void setUpdate(boolean value)
    {
        updated.set(value);
    }

    public void dump(String path)
    {
        if (!sloDetails.isEmpty() || !sloEvents.isEmpty())
        {
            Bootstrap.vertx().<Void>executeBlocking(promise ->
            {
                try
                {
                    Bootstrap.vertx().fileSystem().writeFileBlocking(path,
                            Buffer.buffer(CodecUtil.compress(new JsonObject().put("items", new HashMap<>(sloDetails)).put("events", new HashMap<>(sloEvents)).encode().getBytes())));

                    dirty.set(true);
                }
                catch (Exception exception)
                {
                    LOGGER.error(exception);
                }

                promise.complete();
            });
        }
    }
}

