import java.util.List;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

public class FlowASMapperConfigStore extends AbstractConfigStore
{
    private static final Logger LOGGER = new Logger(FlowASMapperConfigStore.class, GlobalConstants.MOTADATA_STORE, "Flow AS Mapper Config Store");

    private static final FlowASMapperConfigStore STORE = new FlowASMapperConfigStore();

    private final Map<String, List<String>> mappings = new ConcurrentHashMap<>();  //{"127.0.0.1" : Stanford#78988#Stanford University}

    private FlowASMapperConfigStore()
    {
        super(DBConstants.TBL_FLOW_AS_MAPPER, LOGGER, true);
    }

    public static FlowASMapperConfigStore getStore()
    {
        return STORE;
    }

    @Override
    public Future<Void> initStore()
    {
        var promise = Promise.<Void>promise();

        try
        {
            Bootstrap.configDBService().getAll(DBConstants.TBL_FLOW_AS_MAPPER, result ->
            {
                if (result.succeeded())
                {
                    items.clear();

                    mappings.clear();

                    if (result.result() != null && !result.result().isEmpty())
                    {
                        for (var index = 0; index < result.result().size(); index++)
                        {
                            var item = result.result().getJsonObject(index);

                            items.put(item.getLong(GlobalConstants.ID), item);

                            update(item.getLong(GlobalConstants.ID), true);
                        }
                    }

                    promise.complete();

                    LOGGER.info(String.format("store %s initialized...", this.getClass().getSimpleName()));
                }
                else
                {
                    promise.fail(result.cause());

                    LOGGER.fatal(String.format("failed to init store %s , reason : %s...", this.getClass().getSimpleName(), result.cause()));
                }

            });
        }
        catch (Exception exception)
        {
            promise.fail(exception);

            LOGGER.error(exception);
        }

        return promise.future();
    }

    @Override
    public Future<Void> addItem(long id)
    {
        return super.addItem(id).onComplete(result ->
        {
            if (result.succeeded())
            {
                update(id, true);
            }
        });
    }

    @Override
    public void addItem(long id, JsonObject item)
    {
        if (item != null)
        {
            this.items.put(id, item);

            update(id, true);
        }
    }

    @Override
    public Future<Void> updateItem(long id)
    {
        update(id, false);        // delete item first from Cache as we don't know what user has deleted from range

        return super.updateItem(id).onComplete(result ->
        {
            if (result.succeeded())
            {
                update(id, true);
            }
        });
    }

    @Override
    public void deleteItem(long id)
    {
        update(id, false);

        super.deleteItem(id);

    }

    @Override
    public void deleteItems(JsonArray ids)
    {
        if (ids != null && !ids.isEmpty())
        {
            for (var index = 0; index < ids.size(); index++)
            {
                this.deleteItem(ids.getLong(index));
            }
        }
    }

    /**
     * update cache
     * if IP update directly
     * if Range - Calculate Range and update
     *
     * @param id
     */
    private void update(long id, boolean add)
    {
        try
        {
            var item = items.get(id);

            if (item != null)
            {
                var ipAddresses = item.getJsonArray(FlowASMapper.FLOW_AS_MAPPER_GROUP);

                for (var index = 0; index < ipAddresses.size(); index++)
                {
                    var ipGroup = ipAddresses.getString(index);//Could be in single ip / Range of Ips

                    if (ipGroup.contains("-"))
                    {
                        var tokens = ipGroup.split("-");

                        var start = tokens[0].trim();

                        if (tokens[1].trim().matches("\\d+"))//in case user provides range like 172.16.10.1-55
                        {
                            update(start, start.substring(0, start.lastIndexOf('.')) + "." + tokens[1].trim(), item, add);
                        }
                        else
                        {
                            //in case user provides range like 172.16.10.1-172.16.15.1 or xx.xx.10.1-xx.1.2.5
                            update(start, ipGroup.split("-")[1].trim(), item, add);
                        }
                    }
                    else if (ipGroup.contains("xx"))
                    {
                        update(ipGroup, ipGroup, item, add);
                    }
                    else
                    {
                        if (add)
                        {
                            mappings.put(ipGroup, new ArrayList<>(Arrays.asList(
                                    item.getString(FlowASMapper.FLOW_AS_MAPPER_NAME),          // index 0
                                    item.getString(FlowASMapper.FLOW_AS_MAPPER_NUMBER),        // index 1
                                    item.getString(FlowASMapper.FLOW_AS_MAPPER_ORGANIZATION)   // index 2
                            )));
                        }
                        else
                        {
                            mappings.remove(ipGroup);
                        }
                    }
                }
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

    private void update(String start, String end, JsonObject item, boolean add)
    {
        try
        {
            if (start.contains("xx"))
            {
                start = start.replaceAll("xx", "0");
            }
            if (end.contains("xx"))
            {
                end = end.replaceAll("xx", "255");
            }

            if (APIUtil.validateRange(start, end))
            {
                if (add)
                {
                    var asName = item.getString(FlowASMapper.FLOW_AS_MAPPER_NAME);

                    var asNumber = item.getString(FlowASMapper.FLOW_AS_MAPPER_NUMBER);

                    var asOrganization = item.getString(FlowASMapper.FLOW_AS_MAPPER_ORGANIZATION);

                    CommonUtil.calculateIPRange(InetAddress.getByName(start), InetAddress.getByName(end))
                            .forEach(ip -> mappings.put(ip, new ArrayList<>(List.of(
                                    asName,         // index 0
                                    asNumber,       // index 1
                                    asOrganization  // index 2
                            ))));
                }
                else
                {
                    CommonUtil.calculateIPRange(InetAddress.getByName(start), InetAddress.getByName(end)).forEach(mappings::remove);
                }
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

    /*
        Set As Name and Organization in flow as per As Mapping.
     */
    public void setAS(String ip, JsonObject flow, String flowType)
    {

        var mapping = mappings.get(ip);

        if (mapping != null)
        {
            flow.put(flowType + ".as", mapping.get(0));  //name

            flow.put(flowType + ".asn", mapping.get(1)); //number

            flow.put(flowType + ".aso", mapping.get(2)); //Organization
        }
    }

}

