/**
 * Cache store for RUM policy states, severities, and triggered policy information.
 * Manages policy keys, severity tracking, and application/instance severity aggregation.
 */
public class RUMPolicyCacheStore extends AbstractCacheStore
{

    private static final RUMPolicyCacheStore STORE = new RUMPolicyCacheStore();
    private static final Logger LOGGER = new Logger(RUMPolicyCacheStore.class, GlobalConstants.MOTADATA_STORE, "RUM Policy Cache Store");

    private final Map<String, Integer> policyKeys = new ConcurrentHashMap<>();//containing policy keys with its hashcodes
    private final Map<Integer, String> policyKeyHashCodes = new ConcurrentHashMap<>();// containing policy keys against hashcode opposite of previous one to get key value
    private final Map<Long, String> policyKeysByService = new ConcurrentHashMap<>(); //unique policy keys or policy keys against application id or entityid
    private final Map<Integer, Long> policyIds = new ConcurrentHashMap<>();//policy key hashcode with its policy triggered policyId
    private final Map<Integer, GlobalConstants.Severity> severities = new ConcurrentHashMap<>(); //policy key hashcode with its policy triggered severity
    private final Map<Integer, String> values = new ConcurrentHashMap<>();//policy key hashcode with its policy triggered value
    private final Map<Integer, String> policyThresholds = new ConcurrentHashMap<>();//policy key hashcode with its policy triggered threshold value

    private final Map<String, String> instances = new ConcurrentHashMap<>();
    private final Map<Long, String> applications = new ConcurrentHashMap<>();
    private final Map<Integer, Integer> plugins = new ConcurrentHashMap<>();//policy key hashcode with its policy triggered pluginId


    private final Map<Long, Integer> warningSeverities = new ConcurrentHashMap<>();
    private final Map<Long, Integer> criticalSeverities = new ConcurrentHashMap<>();
    private final Map<Long, Integer> clearSeverities = new ConcurrentHashMap<>();
    private final Map<Long, Integer> downSeverities = new ConcurrentHashMap<>();
    private final Map<Long, Integer> majorSeverities = new ConcurrentHashMap<>();
    private final Map<Long, Integer> unreachableSeverities = new ConcurrentHashMap<>();

    private final AtomicBoolean updated = new AtomicBoolean();
    private final AtomicBoolean dirty = new AtomicBoolean();

    private RUMPolicyCacheStore()
    {
    }

    /**
     * Returns the singleton instance of the RUM policy cache store.
     *
     * @return the singleton store instance
     */
    public static RUMPolicyCacheStore getStore()
    {
        return STORE;
    }


    /**
     * Initializes the RUM policy cache store by loading persisted severity data.
     *
     * @return Future that completes when initialization is successful
     */
    @Override
    public Future<Void> initStore()
    {
        var promise = Promise.<Void>promise();

        loadSeverities();

        promise.complete();

        LOGGER.info(String.format("store %s initialized...", this.getClass().getSimpleName()));

        return promise.future();
    }


    /**
     * Loads persisted RUM policy severity data from file.
     * Restores application and instance severity mappings from disk.
     */
    private void loadSeverities()
    {
        try
        {
            try
            {
                var file = new File(CURRENT_DIR + PATH_SEPARATOR + CONFIG_DIR + PATH_SEPARATOR + PolicyEngineConstants.RUM_POLICY_SEVERITIES);

                if (file.exists())
                {
                    var buffer = Bootstrap.vertx().fileSystem().readFileBlocking(file.getPath());

                    if (buffer != null && buffer.getBytes().length > 0)
                    {
                        var context = new JsonObject(Buffer.buffer(CodecUtil.toBytes(buffer.getBytes()))).getMap();

                        ((Map<String, Object>) (context.get("applications"))).forEach((key, value) -> applications.put(CommonUtil.getLong(key), CommonUtil.getString(value)));

                        ((Map<String, Object>) (context.get(INSTANCES))).forEach((key, value) -> instances.put(key, CommonUtil.getString(value)));

                        LOGGER.info("loaded RUM policy severities");
                    }
                }
                else
                {
                    Bootstrap.vertx().fileSystem().createFileBlocking(file.getPath());
                }
            }
            catch (Exception exception)
            {
                LOGGER.error(exception);
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

    /**
     * Updates or adds a policy item in the cache with the given hash code and context.
     * Manages policy key mappings, severity tracking, and triggers severity updates.
     *
     * @param hashCode the hash code of the policy key
     * @param context the policy context containing policy details
     */
    public void updateItem(int hashCode, JsonObject context)
    {
        try
        {
            if (policyKeys.getOrDefault(context.getString(PolicyEngineConstants.POLICY_KEY), null) == null)
            {
                policyKeys.put(context.getString(PolicyEngineConstants.POLICY_KEY), hashCode);

                plugins.put(hashCode, context.getInteger(GlobalConstants.PLUGIN_ID));

                policyKeyHashCodes.put(hashCode, context.getString(PolicyEngineConstants.POLICY_KEY));
            }

            var keys = policyKeysByService.getOrDefault(context.getLong(ENTITY_ID), null);

            var items = new HashSet<String>();

            items.add(CommonUtil.getString(hashCode));

            if (keys != null && !keys.isEmpty())
            {
                items.addAll(Arrays.asList(keys.split(GlobalConstants.COMMA_SEPARATOR)));

                policyKeysByService.put(context.getLong(ENTITY_ID), StringUtils.join(items, GlobalConstants.COMMA_SEPARATOR));
            }

            else
            {
                policyKeysByService.put(context.getLong(ENTITY_ID), CommonUtil.getString(hashCode));
            }

            var severity = severities.getOrDefault(hashCode, Severity.UNKNOWN);

            policyIds.put(hashCode, context.getLong(ID));

            severities.put(hashCode, Severity.valueOf(context.getString(GlobalConstants.SEVERITY)));

            values.put(hashCode, CommonUtil.getString(context.getValue(VALUE)));

            policyThresholds.put(hashCode, CommonUtil.getString(context.getValue(MetricPolicy.POLICY_THRESHOLD, EMPTY_VALUE)));

            if (!severity.equals(Severity.valueOf(context.getString(GlobalConstants.SEVERITY))))
            {
                update(context, items);
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

    /**
     * Updates severity aggregations for applications and instances based on policy changes.
     * Calculates overall severity from all policies and publishes severity change notifications.
     *
     * @param context the policy context
     * @param items the set of policy hash codes for the entity
     */
    private void update(JsonObject context, Set<String> items)
    {
        try
        {

            var severities = new TreeSet<Severity>();

            TreeSet<Severity> instances = null;

            var entityId = context.getLong(ENTITY_ID);

            var policyKey = context.getString(PolicyEngineConstants.POLICY_KEY);

            var instance = EMPTY_VALUE;

            if (policyKey != null && policyKey.split(SEPARATOR_WITH_ESCAPE).length > 3)
            {
                var tokens = policyKey.split(SEPARATOR_WITH_ESCAPE);

                instance = tokens[0] + SEPARATOR + tokens[3];

                instances = new TreeSet<>();
            }

            var clearSeverities = 0;

            var criticalSeverities = 0;

            var downSeverities = 0;

            var majorSeverities = 0;

            var unreachableSeverities = 0;

            var warningSeverities = 0;

            for (var item : items)
            {
                if (!item.isEmpty())
                {
                    var policyHashCode = CommonUtil.getInteger(item);

                    var severity = this.severities.get(policyHashCode);

                    policyKey = policyKeyHashCodes.get(policyHashCode);

                    if (policyKey != null)
                    {
                        var tokens = policyKey.split(SEPARATOR_WITH_ESCAPE);

                        if (tokens.length > 3)                              // for instance
                        {
                            if (severity.equals(Severity.DOWN))             // if instance down , then add critical which will affect the object severity
                            {
                                severities.add(Severity.CRITICAL);
                            }
                            else
                            {
                                severities.add(severity);
                            }

                            if ((tokens[0] + SEPARATOR + tokens[3]).equalsIgnoreCase(instance))
                            {
                                instances.add(severity);
                            }
                        }
                        else
                        {
                            severities.add(severity);
                        }


                        if (severity.equals(Severity.CLEAR))
                        {
                            clearSeverities++;
                        }
                        else if (severity.equals(Severity.DOWN))
                        {
                            downSeverities++;
                        }
                        else if (severity.equals(Severity.UNREACHABLE))
                        {
                            unreachableSeverities++;
                        }
                        else if (severity.equals(Severity.WARNING))
                        {
                            warningSeverities++;
                        }
                        else if (severity.equals(Severity.MAJOR))
                        {
                            majorSeverities++;
                        }
                        else if (severity.equals(Severity.CRITICAL))
                        {
                            criticalSeverities++;
                        }
                    }
                }
            }

            this.clearSeverities.put(entityId, clearSeverities);

            this.criticalSeverities.put(entityId, criticalSeverities);

            this.majorSeverities.put(entityId, majorSeverities);

            this.warningSeverities.put(entityId, warningSeverities);

            this.unreachableSeverities.put(entityId, unreachableSeverities);

            this.downSeverities.put(entityId, downSeverities);

            if (!applications.getOrDefault(entityId, Severity.UNKNOWN.name()).equalsIgnoreCase(severities.last().name()))
            {
                //publish to UI
                applications.put(entityId, severities.last().name());

                updated.set(true);

                Bootstrap.vertx().eventBus().send(EventBusConstants.EVENT_SEVERITY_CHANGE, new JsonObject().put(ENTITY_ID, entityId).put(PolicyEngineConstants.POLICY_KEY, entityId).put(SEVERITY, applications.get(entityId)).put(PolicyEngineConstants.SEVERITY_TYPE, "object.severity"));
            }

            if (!instance.isEmpty() && !this.instances.getOrDefault(instance, GlobalConstants.Severity.UNKNOWN.name()).equalsIgnoreCase(instances.last().name()))
            {
                this.instances.put(instance, instances.last().name());

                updated.set(true);

                Bootstrap.vertx().eventBus().send(EventBusConstants.EVENT_SEVERITY_CHANGE, new JsonObject().put(ENTITY_ID, entityId)
                        .put(PolicyEngineConstants.POLICY_KEY, instance)
                        .put(INSTANCE, instance.split(SEPARATOR_WITH_ESCAPE)[1].trim())
                        .put(SEVERITY, this.instances.get(instance)).put(PolicyEngineConstants.SEVERITY_TYPE, "instance.severity"));
            }

            Bootstrap.vertx().eventBus().send(EventBusConstants.EVENT_POLICY_NOTIFICATION, context.put(PolicyEngineConstants.POLICY_ID, context.getLong(ID)));
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }


    /**
     * Retrieves policy items for the given entity IDs.
     * Returns a map of policy keys to their corresponding policy details.
     *
     * @param entities JSON array of entity IDs
     * @return map of policy keys to policy details
     */
    public Map<String, JsonObject> getItems(JsonArray entities)
    {
        var items = new HashMap<String, JsonObject>();

        try
        {
            for (var index = 0; index < entities.size(); index++)
            {
                if (policyKeysByService.containsKey(entities.getLong(index)))
                {
                    for (var key : policyKeysByService.get(entities.getLong(index)).split(COMMA_SEPARATOR))
                    {
                        try
                        {
                            if (CommonUtil.isNotNullOrEmpty(key))
                            {
                                var hashCode = CommonUtil.getInteger(key);

                                if (policyKeyHashCodes.containsKey(hashCode))
                                {
                                    items.put(policyKeyHashCodes.get(hashCode), getItem(hashCode));
                                }
                            }
                        }
                        catch (Exception exception)
                        {
                            LOGGER.warn(String.format("exception occurred for key %s for monitor %s", policyKeysByService.get(entities.getLong(index)), ObjectConfigStore.getStore().getObjectName(entities.getLong(index))));

                            LOGGER.error(exception);
                        }
                    }
                }
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }

        return items;
    }


    /**
     * Retrieves a single policy item by its hash code.
     * Constructs policy details including metric, instance, severity, and threshold.
     *
     * @param hashCode the policy key hash code
     * @return policy details as JsonObject, or null if not found
     */
    public JsonObject getItem(int hashCode)
    {
        JsonObject item = null;

        try
        {
            if (policyKeyHashCodes.containsKey(hashCode))
            {
                var policyKey = policyKeyHashCodes.get(hashCode);

                item = new JsonObject().put(METRIC, policyKey.split(SEPARATOR_WITH_ESCAPE)[2].trim()).put(INSTANCE, policyKey.split(SEPARATOR_WITH_ESCAPE).length > 3 ? policyKey.split(SEPARATOR_WITH_ESCAPE)[3].trim() : null).put(ID, policyIds.get(hashCode)).put(ENTITY_ID, CommonUtil.getLong(policyKey.split(SEPARATOR_WITH_ESCAPE)[0]))
                        .put(VALUE, values.get(hashCode)).put(SEVERITY, severities.get(hashCode))
                        .put(Metric.METRIC_TYPE, EMPTY_VALUE)
                        .put(MetricPolicy.POLICY_THRESHOLD, policyThresholds.getOrDefault(hashCode, EMPTY_VALUE))
                        .put(PLUGIN_ID, plugins.get(hashCode));

            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }

        return item;
    }


    /**
     * Returns all application and instance severities.
     *
     * @return JsonObject containing object and instance severity mappings
     */
    public JsonObject getSeverities()
    {
        return new JsonObject().put("object.severity", JsonObject.mapFrom(applications)).put("instance.severity", JsonObject.mapFrom(instances));
    }


    /**
     * Deletes all policy data for the given application/entity ID.
     * Removes all associated policies, severities, and instance mappings.
     *
     * @param id the entity ID to delete
     */
    public void deleteItem(long id)
    {
        applications.remove(id);

        instances.keySet().removeIf(key -> CommonUtil.getLong(key.split(SEPARATOR_WITH_ESCAPE)[0]) == id);

        var keys = policyKeysByService.remove(id);

        if (keys != null)
        {
            Arrays.stream(keys.split(COMMA_SEPARATOR)).forEach(key -> cleanup(CommonUtil.getInteger(key)));
        }

        clearSeverities.remove(id);

        criticalSeverities.remove(id);

        majorSeverities.remove(id);

        warningSeverities.remove(id);

        unreachableSeverities.remove(id);

        downSeverities.remove(id);
    }

    /**
     * Deletes a specific instance policy and updates severity counts.
     * Decrements the severity counter for the entity and cleans up policy data.
     *
     * @param id the entity ID
     * @param instance the instance name
     * @param policyKey the policy key
     */
    public void deleteItem(long id, String instance, String policyKey)
    {
        var hashCode = policyKey.hashCode();

        switch (severities.get(hashCode))
        {
            case CRITICAL -> criticalSeverities.put(id, criticalSeverities.get(id) - 1);

            case CLEAR -> clearSeverities.put(id, clearSeverities.get(id) - 1);

            case WARNING -> warningSeverities.put(id, warningSeverities.get(id) - 1);

            case UNREACHABLE -> unreachableSeverities.put(id, unreachableSeverities.get(id) - 1);

            case DOWN -> downSeverities.put(id, downSeverities.get(id) - 1);

            case MAJOR -> majorSeverities.put(id, majorSeverities.get(id) - 1);
        }

        cleanup(hashCode);

        instances.remove(id + SEPARATOR + instance);
    }

    /**
     * Cleans up all policies associated with the given policy ID.
     * Removes policy mappings and recalculates entity severities.
     *
     * @param id the policy ID to clean up
     */
    public void cleanup(long id)
    {
        try
        {
            var hashCodes = new HashSet<Integer>();

            var entities = new HashMap<Long, Set<String>>();

            var iterator = this.policyIds.entrySet().iterator();

            while (iterator.hasNext())
            {
                var entry = iterator.next();

                if (entry.getValue().equals(id) && policyKeyHashCodes.containsKey(entry.getKey()))
                {
                    hashCodes.add(entry.getKey());

                    var entity = CommonUtil.getLong(policyKeyHashCodes.get(entry.getKey()).split(SEPARATOR_WITH_ESCAPE)[0]);

                    entities.computeIfAbsent(entity, value -> new HashSet<>()).add(CommonUtil.getString(entry.getKey()));

                    iterator.remove();
                }
            }

            if (!hashCodes.isEmpty())
            {
                hashCodes.forEach(this::cleanup);

                for (var entry : entities.entrySet())
                {
                    var items = new HashSet<>(Arrays.asList(policyKeysByService.get(entry.getKey()).split(COMMA_SEPARATOR)));

                    items.removeAll(entry.getValue());

                    if (!items.isEmpty())
                    {
                        policyKeysByService.put(entry.getKey(), StringUtils.join(items, COMMA_SEPARATOR));
                    }

                    notify(entry.getKey(), items);

                }
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

    /**
     * Recalculates and publishes severity for an entity based on remaining policies.
     * Updates application severity and sends severity change notification.
     *
     * @param id the entity ID
     * @param items the set of remaining policy hash codes
     */
    private void notify(long id, Set<String> items)
    {
        try
        {
            if (!items.isEmpty())
            {
                var severities = new TreeSet<Severity>();


                for (var item : items)
                {
                    if (CommonUtil.isNotNullOrEmpty(item))
                    {
                        if (this.severities.containsKey(CommonUtil.getInteger(item)))
                        {
                            severities.add(this.severities.get(CommonUtil.getInteger(item)));
                        }

                    }
                }

                if (!severities.isEmpty() && !applications.getOrDefault(id, Severity.UNKNOWN.name()).equalsIgnoreCase(severities.last().name()))
                {
                    applications.put(id, severities.last().name());

                    updated.set(true);
                }
                else if (severities.isEmpty())
                {
                    applications.put(id, Severity.UNKNOWN.name());

                    updated.set(true);
                }

            }
            else
            {
                applications.put(id, Severity.UNKNOWN.name());

                updated.set(true);
            }

            Bootstrap.vertx().eventBus().send(EventBusConstants.EVENT_SEVERITY_CHANGE, new JsonObject().put(ENTITY_ID, id).put(PolicyEngineConstants.POLICY_KEY, id).put(SEVERITY, applications.get(id)).put(PolicyEngineConstants.SEVERITY_TYPE, "object.severity"));
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

    /**
     * Removes all cached data for a specific policy hash code.
     * Cleans up severities, plugins, IDs, values, and key mappings.
     *
     * @param hashCode the policy key hash code to clean up
     */
    private void cleanup(int hashCode)
    {
        severities.remove(hashCode);

        plugins.remove(hashCode);

        policyIds.remove(hashCode);

        values.remove(hashCode);

        policyKeys.entrySet().removeIf(entry -> entry.getValue() == hashCode);

        policyKeyHashCodes.remove(hashCode);

        policyThresholds.remove(hashCode);
    }

    /**
     * Retrieves the current severity for the given entity.
     *
     * @param entity the entity ID
     * @return the severity string, or null if not found
     */
    public String getSeverity(long entity)
    {
        return applications.getOrDefault(entity, null);
    }


    /**
     * Retrieves the current severity for the given instance.
     *
     * @param entity the instance identifier
     * @return the severity string, or null if not found
     */
    public String getInstanceSeverity(String entity)
    {
        return instances.getOrDefault(entity, null);
    }

    /**
     * Notifies listeners about severity changes for the given ID.
     * This method collects all policy keys associated with the object and triggers the notification logic.
     *
     * @param id the object/entity ID for which to notify severity changes
     */
    public void notify(long id)
    {
        notify(id, new HashSet<>(Arrays.asList(policyKeysByService.get(id).split(COMMA_SEPARATOR))));
    }

    /**
     * Checks if the cache has been marked as dirty (needs persistence).
     *
     * @return true if dirty, false otherwise
     */
    public boolean dirty()
    {
        return dirty.get();
    }

    /**
     * Sets the dirty flag indicating whether the cache needs persistence.
     *
     * @param value true to mark as dirty, false otherwise
     */
    public void setDirty(boolean value)
    {
        dirty.set(value);
    }


    /**
     * Persists severity data to disk if updates have occurred.
     * Writes application and instance severity mappings to the specified file path.
     *
     * @param path the file path where severity data should be persisted
     */
    public void dump(String path)
    {
        if ((!applications.isEmpty() || !instances.isEmpty()) && updated.get())
        {
            Bootstrap.vertx().<Void>executeBlocking(promise ->
            {
                try
                {
                    Bootstrap.vertx().fileSystem().writeFileBlocking(path,
                            Buffer.buffer(CodecUtil.compress(new JsonObject().put("applications", new HashMap<>(applications)).put("instances", new HashMap<>(instances)).encode().getBytes())));
                }
                catch (Exception exception)
                {
                    LOGGER.error(exception);
                }

                promise.complete();
            });

            updated.set(false);

            dirty.set(true);
        }
    }
}

