        {
            items.entrySet().removeIf(entry -> entry.getKey().split(HASH_SEPARATOR)[0].equalsIgnoreCase(CommonUtil.getString(id)));
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }
