    // ------------------------ Correction Utility Methods ------------------------ //

    /**
     * Get the correction timestamps for the given SLO cycle and correction profiles
     *
     * @param sloCycle The SLO cycle
     * @param corrections The correction profiles
     * @return The list of correction timestamps
     */
    public static List<long[]> getCorrectionTimestamps(JsonObject sloCycle, JsonArray corrections)
    {
        var timestamps = new ArrayList<long[]>();

        try
        {
            if (sloCycle != null && !sloCycle.isEmpty())
            {
                if (corrections != null && !corrections.isEmpty())
                {
                    for (var i = 0; i < corrections.size(); i++)
                    {
                        var correction = corrections.getJsonObject(i);

                        if (correction.containsKey(CorrectionProfile.CORRECTION_PROFILE_CONTEXT))
                        {
                            var context = correction.getJsonObject(CorrectionProfile.CORRECTION_PROFILE_CONTEXT);

                            var cycleStartTime = sloCycle.getLong(SLOCycle.SLO_CYCLE_START_TIME);

                            var cycleEndTime = sloCycle.getLong(SLOCycle.SLO_CYCLE_END_TIME);

                            switch (RecurringType.valueOfName(correction.getString(CorrectionProfile.CORRECTION_PROFILE_RECURRING_TYPE)))
                            {
                                case ONCE ->
                                {
                                    if (context.containsKey(CorrectionProfile.CORRECTION_TIMES))
                                    {
                                        var correctionTimes = context.getJsonArray(CorrectionProfile.CORRECTION_TIMES);

                                        // 1. Clip correction windows
                                        for (var index = 0; index < correctionTimes.size(); index++)
                                        {
                                            var correctionTime = correctionTimes.getJsonArray(index);

                                            var correctionStartTime = correctionTime.getLong(0);

                                            var correctionEndTime = correctionTime.getLong(1);

                                            if (correctionEndTime < correctionStartTime || correctionStartTime > cycleEndTime)
                                            {
                                                continue;
                                            }

                                            var start = Math.max(cycleStartTime, correctionStartTime);

                                            var end = Math.min(cycleEndTime, correctionEndTime);

                                            if (start < end)
                                            {
                                                timestamps.add(new long[]{start, end});
                                            }
                                        }
                                    }
                                    else
                                    {
                                        LOGGER.warn("correction times are missing in correction profile context");
                                    }
                                }
                                case MONITORING_HOURS ->
                                {
                                    var item = BusinessHourConfigStore.getStore().getItem(context.getLong(CorrectionProfile.BUSINESS_HOUR_PROFILE));

                                    if (item != null && item.containsKey(BusinessHour.BUSINESS_HOUR_CONTEXT))
                                    {
                                        var businessHours = item.getJsonObject(BusinessHour.BUSINESS_HOUR_CONTEXT);

                                        var start = Instant.ofEpochSecond(cycleStartTime).atZone(ZoneId.systemDefault()).toLocalDate();

                                        var end = Instant.ofEpochSecond(cycleEndTime).atZone(ZoneId.systemDefault()).toLocalDate();

                                        for (var date = start; date.isBefore(end); date = date.plusDays(1))
                                        {
                                            var hours = businessHours.getJsonArray(date.getDayOfWeek().getDisplayName(TextStyle.FULL, Locale.ENGLISH));

                                            // means no business hours for this day
                                            if (hours == null || hours.isEmpty())
                                            {
                                                timestamps.add(new long[]{date.atStartOfDay().atZone(ZoneId.systemDefault()).toEpochSecond()
                                                        , date.plusDays(1).atStartOfDay().atZone(ZoneId.systemDefault()).toEpochSecond()});
                                            }
                                            else
                                            {
                                                for (var hour = 0 ; hour < 23; hour++)
                                                {
                                                    if (!hours.contains(hour))
                                                    {
                                                        timestamps.add(new long[]{date.atTime(hour, 0).atZone(ZoneId.systemDefault()).toEpochSecond()
                                                                , date.atTime(hour + 1, 0).atZone(ZoneId.systemDefault()).toEpochSecond()});
                                                    }
                                                }

                                                if (!hours.contains(23))
                                                {
                                                    timestamps.add(new long[]{date.atTime(23, 0).atZone(ZoneId.systemDefault()).toEpochSecond()
                                                            , date.plusDays(1).atStartOfDay().atZone(ZoneId.systemDefault()).toEpochSecond()});
                                                }
                                            }
                                        }
                                    }
                                    else
                                    {
                                        LOGGER.warn("business hour is not configured");
                                    }
                                }
                                case REPEATING ->
                                {
                                    var repeatEnds = context.getString(CorrectionProfile.REPEAT_ENDS);

                                    var startTime = context.getLong(CorrectionProfile.REPEAT_START_TIME);

                                    var duration = DateTimeUtil.toSeconds(context.getLong(CorrectionProfile.DURATION), context.getString(CorrectionProfile.DURATION_UNIT, DateTimeUtil.Unit.SECOND.getName()));

                                    var repeatInterval = DateTimeUtil.toSeconds(context.getLong(CorrectionProfile.REPEAT_INTERVAL), context.getString(CorrectionProfile.REPEAT_INTERVAL_UNIT, DateTimeUtil.Unit.DAY.getName()));

                                    var repeatEndTime = context.getLong(CorrectionProfile.REPEAT_END_TIME, Instant.MAX.getEpochSecond()); // in case of repeat ends never or on will not get this

                                    var count = 0;

                                    while (true)
                                    {
                                        // repeat ends on date
                                        if (repeatEnds.equalsIgnoreCase("on") && startTime >= repeatEndTime) break;

                                        // repeat ends after no of times
                                        if (repeatEnds.equalsIgnoreCase("n") && count >= context.getLong(CorrectionProfile.REPEAT_END_COUNT)) break;

                                        if (startTime > cycleEndTime) break;// stop if outside cycle

                                        var endTime = startTime + duration;

                                        if (endTime > cycleStartTime)
                                        {
                                            var start = Math.max(cycleStartTime, startTime);

                                            var end = Math.min(Math.min(cycleEndTime, endTime), repeatEndTime);

                                            if (start < end)
                                            {
                                                timestamps.add(new long[]{start, end});
                                            }
                                        }

                                        startTime += repeatInterval;

                                        count++;
                                    }
                                }
                            }
                        }
                    }

                    return mergeOverlappingIntervals(timestamps);
                }
                else
                {
                    LOGGER.warn("Either correction profile is null or empty or correction context is missing");
                }
            }
            else
            {
                LOGGER.warn("slo cycle is null or empty");
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }

        return timestamps;
    }

    /**
     * Merges overlapping intervals in a list of timestamps.
     *
     * @param timestamps The list of timestamps to merge
     * @return The list of merged timestamps
     */
    private static List<long[]> mergeOverlappingIntervals(List<long[]> timestamps)
    {
        // 2. Sort by start time
        timestamps.sort(Comparator.comparingLong(timestamp -> timestamp[0]));

        // 3. Merge overlapping intervals
        var merged = new ArrayList<long[]>();

        long[] current = null;

        for (var timestamp : timestamps)
        {
            if (current == null)
            {
                current = timestamp;
            }
            else if (timestamp[0] <= current[1])
            {
                // Overlap → extend
                current[1] = Math.max(current[1], timestamp[1]);
            }
            else
            {
                merged.add(current);

                current = timestamp;
            }
        }

        if (current != null)
        {
            merged.add(current);
        }

        return merged;
    }

    public static List<JsonArray> populateBatch(JsonArray entities, SLOConstants.SLOFrequency frequency)
    {
        var count = MotadataConfigUtil.getCorrectionBatchSize(frequency);

        var batches = new ArrayList<JsonArray>();

        for (var index = 0; index < entities.size(); index += count)
        {
            var batch = new JsonArray();

            var end = Math.min(index + count, entities.size());

            for (var i = index; i < end; i++)
            {
                batch.add(entities.getLong(i));
            }

            batches.add(batch);
        }

        return batches;
    }

