    private static final Logger LOGGER = new Logger(SLOProcessor.class, GlobalConstants.MOTADATA_SLO, "SLO Processor");

    private EventEngine eventEngine;

    private final Map<Long, Long> sloCycles = new HashMap<>();

    private final AtomicInteger count = new AtomicInteger(1);

    private final SLOCalculatorCacheStore sloCalculatorCacheStore = SLOCalculatorCacheStore.getStore();

    private final StringBuilder builder = new StringBuilder(0);

    private Set<String> mappers;

    private String eventType;

    // ------------------------ Verticle related methods ------------------------ //

    /**
     * Starts the SLO Processor verticle and initializes event handlers.
     * Sets up periodic timer for SLO calculations and registers event bus consumers.
     *
     * @param promise the promise to complete when startup is finished
     * @throws Exception if startup fails
     */
    @Override
    public void start(Promise<Void> promise) throws Exception
    {
        try
        {
            eventType = config().getString(EVENT_TYPE);

            mappers = new HashSet<>();

            vertx.setPeriodic(DateTimeUtil.calculateNextAlignedTimerDelay(MotadataConfigUtil.getSLOCalculationTimerMinutes()), TimeUnit.MINUTES.toMillis(MotadataConfigUtil.getSLOCalculationTimerMinutes()), timer -> calculate());

            vertx.eventBus().<JsonObject>localConsumer(EVENT_CHANGE_NOTIFICATION, message ->
            {
                try
                {
                    if (message.body().getString(CHANGE_NOTIFICATION_TYPE, EMPTY_VALUE).equalsIgnoreCase(ChangeNotificationType.DELETE_SLO_PROFILE.name()))
                    {
                        var sloId = message.body().getLong(ID, -1L);

                        if (sloId != -1L && sloCycles.containsKey(sloId))
                        {
                            LOGGER.info(eventType + " removing slo profile id " + sloId + " from slo cycles");

                            sloCycles.remove(sloId);

                            sloCalculatorCacheStore.clear(sloId);
                        }
                    }
                }
                catch (Exception exception)
                {
                    LOGGER.error(exception);
                }
            });

            LOGGER.info("SLO Processor with event type " + eventType + " started successfully!!!");

            eventEngine = new EventEngine().setEventType(eventType)
                    .setPersistEventOffset(true).setLogger(LOGGER).setEventHandler(this::process).start(vertx, promise);
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

    /**
     * Stops the SLO Processor verticle and cleans up resources.
     *
     * @param promise the promise to complete when shutdown is finished
     * @throws Exception if shutdown fails
     */
    @Override
    public void stop(Promise<Void> promise) throws Exception
    {
        LOGGER.info(eventType + "SLO Processor undeployed...");

        eventEngine.stop(vertx, promise);
    }

    // ------------------------ Main method ------------------------ //

    /**
     * Processes incoming SLO events and routes them to appropriate handlers.
     *
     * @param event the SLO event to process
     */
    private void process(JsonObject event)
    {
        try
        {
            var eventType = SLOEventType.valueOfName(event.getString(EVENT_TYPE, GlobalConstants.EMPTY_VALUE));

            if (eventType != null)
            {
                switch (eventType)
                {
                    case SLO_INIT ->
                        init(event);

                    case SLO_CYCLE_START ->
                        startCycle(event);

                    case SLO_CYCLE_END ->
                        endCycle(event);

                    case SLO_OBJECT_DISABLE ->
                        handleObjectDisable(event);

                    case SLO_INSTANCE_DISABLE ->
                        handleInstanceDisable(event);

                    case SLO_PROCESS ->
                        processSLO(event);
                }
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

    // ------------------------ SLO processing related methods ------------------------ //

    /**
     * This method is used to process the inspected result.
     * <p>
     *     We update the SLO based on the current status and timestamp.
     * </p>
     * @param inspectedResult the inspected result received from the {@link com.mindarray.policy.MetricPolicyInspector} and {@link com.mindarray.store.ObjectStatusCacheStore (via SLOManager)}
     */
    private void processSLO(JsonObject inspectedResult)
    {
        try
        {
            var sloId = inspectedResult.getLong(SLOProfile.SLO_PROFILE_ID);

            // avoid processing if slo id is not present in slo cycles
            if (sloId == null || !sloCycles.containsKey(sloId))
            {
                return;
            }

            var severity = inspectedResult.getString(SEVERITY);

            var object = inspectedResult.getLong(AIOpsConstants.ENTITY_ID, -1L);

            var instance = inspectedResult.getString(INSTANCE) == null ? EMPTY_VALUE : inspectedResult.getString(INSTANCE);

            var timestamp = inspectedResult.getLong(EventBusConstants.EVENT_TIMESTAMP);

            var key = object + (!instance.isEmpty() ? INSTANCE_SEPARATOR + instance : EMPTY_VALUE);

            var detail = sloCalculatorCacheStore.getSLODetails(sloId).get(key);

            // ignore the values if it's not added at the time of cycle start
            if (detail != null && !severity.equalsIgnoreCase(STATUS_UNKNOWN))
            {
                if (severity.equalsIgnoreCase(Severity.CRITICAL.name()) || severity.equalsIgnoreCase(STATUS_DOWN) || severity.equalsIgnoreCase(STATUS_UNREACHABLE))
                {
                    updateSLO(detail, SLOFlapStatus.DEGRADED, timestamp, object, instance, sloId, sloCycles.get(sloId));
                }
                else
                {
                    updateSLO(detail, SLOFlapStatus.HEALTHY, timestamp, object, instance, sloId, sloCycles.get(sloId));
                }
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

    // ------------------------ SLO Cycle related methods ------------------------ //

    /**
     * Initializes an SLO profile with a new cycle.
     *
     * @param event the initialization event containing SLO profile and cycle information
     */
    private void init(JsonObject event)
    {
        try
        {
            var sloId = event.getLong(SLOProfile.SLO_PROFILE_ID);

            var cycleId = event.getLong(SLOCycle.SLO_CYCLE_ID);

            var type = event.getString(SLOProfile.SLO_PROFILE_TYPE);

            LOGGER.info(String.format("slo profile %s initialized with cycle %s with type %s and event %s", sloId, cycleId, type, eventType));

            sloCycles.put(sloId, cycleId);

            if (CommonUtil.debugEnabled())
            {
                LOGGER.debug(String.format("event type : %s, slo cycles : %s", eventType, sloCycles));
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

    /**
     * Starts a new SLO cycle and initializes entities for monitoring.
     *
     * @param event the cycle start event containing SLO profile and cycle information
     */
    private void startCycle(JsonObject event)
    {
        try
        {
            var sloId = event.getLong(SLOProfile.SLO_PROFILE_ID);

            var cycleId = event.getLong(SLOCycle.SLO_CYCLE_ID);

            LOGGER.info(String.format("starting cycle %s for slo profile %s with event %s", cycleId, sloId, eventType));

            var sloProfile = SLOProfileConfigStore.getStore().getItem(sloId);

            var sloCycle = SLOCycleConfigStore.getStore().getItem(cycleId);

            if (sloCycle != null && sloProfile != null && !sloProfile.isEmpty() && !sloCycle.isEmpty())
            {
                var startTime = sloCycle.getLong(SLOCycle.SLO_CYCLE_START_TIME);

                var endTime = sloCycle.getLong(SLOCycle.SLO_CYCLE_END_TIME);

                var duration = endTime - startTime;

                var entities = sloCycle.getJsonArray(GlobalConstants.ENTITIES);

                // get past data from the previous cycle
                var sloDetails = sloCalculatorCacheStore.clear(sloId);

                sloCalculatorCacheStore.init(sloId);

                qualifyAndAssignEntities(sloProfile, entities, startTime, duration, sloDetails);
            }
            else
            {
                LOGGER.warn("slo profile or slo cycle not found for slo profile id " + sloId + " and cycle id " + cycleId);
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

    /**
     * Ends an SLO cycle and performs final calculations and notifications.
     *
     * @param event the cycle end event containing SLO profile and cycle information
     */
    private void endCycle(JsonObject event)
    {
        try
        {
            var sloId = event.getLong(SLOProfile.SLO_PROFILE_ID);

            var cycleId = event.getLong(SLOCycle.SLO_CYCLE_ID);

            var sloProfile = SLOProfileConfigStore.getStore().getItem(sloId);

            var sloCycle = SLOCycleConfigStore.getStore().getItem(cycleId);

            if (sloCycle != null && sloProfile != null && !sloProfile.isEmpty() && !sloCycle.isEmpty())
            {
                var sloInstances = sloCalculatorCacheStore.getSLODetails(sloId);

                var timestamp = sloCycle.getLong(SLOCycle.SLO_CYCLE_END_TIME);

                var duration = sloCycle.getLong(SLOCycle.SLO_CYCLE_TOTAL_DURATION);

                LOGGER.info(String.format("ending cycle %s for slo profile %s", cycleId, sloId));

                int downCount = calculateInstanceSLO(sloInstances, sloId, sloCycle, sloProfile, timestamp, duration);

                calculateGlobalSLO(sloId, sloCycle, sloProfile, timestamp, duration, downCount);
            }
            else
            {
                LOGGER.warn("slo profile or slo cycle not found for slo profile id " + sloId + " and cycle id " + cycleId);
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

    /**
     * Qualifies and assigns entities to an SLO profile for monitoring.
     *
     * @param sloProfile the SLO profile configuration
     * @param objects the array of object IDs to monitor
     * @param startTime the cycle start time
     * @param duration the cycle duration
     * @param sloDetails previous SLO details from cache
     */
    private void qualifyAndAssignEntities(JsonObject sloProfile, JsonArray objects, long startTime, long duration, Map<String, JsonObject> sloDetails)
    {
        try
        {
            LOGGER.info(String.format("qualifying and assigning entities for slo profile %s", sloProfile.getString(SLOProfile.SLO_PROFILE_NAME)));

            var sloId = sloProfile.getLong(GlobalConstants.ID);

            var cycleId = sloCycles.get(sloId);

            var sloContext = sloProfile.getJsonObject(SLOProfile.SLO_PROFILE_CONTEXT);

            var availabilitySLO = sloProfile.getString(SLOProfile.SLO_PROFILE_TYPE).equalsIgnoreCase(SLOType.AVAILABILITY.getName());

            var sloInstance = sloContext.getString(SLOProfile.SLO_INSTANCE, GlobalConstants.EMPTY_VALUE);

            SLOFlapStatus globalSLOStatus = SLOFlapStatus.HEALTHY;

            var detail = sloCalculatorCacheStore.getSLODetails(sloId);

            for (var index = 0; index < objects.size(); index++)
            {
                var object = objects.getLong(index);

                if (sloInstance.equalsIgnoreCase(NMSConstants.InstanceType.MONITOR.getName()))
                {
                    var status = getInitialSLOStatus(availabilitySLO, object, EMPTY_VALUE, sloDetails);

                    if (status == SLOFlapStatus.DEGRADED && globalSLOStatus == SLOFlapStatus.HEALTHY)
                    {
                        globalSLOStatus = SLOFlapStatus.DEGRADED;
                    }

                    var data = new JsonObject()
                            .put(DURATION_LEFT, duration);

                    detail.put(object.toString(), data);

                    // add initial status as up or down
                    updateSLO(data, status, startTime, object, EMPTY_VALUE, sloId, cycleId);
                }
                else
                {
                    var instances = MetricConfigStore.getStore().getInstanceObjectsByPluginNames(object, sloContext.getJsonArray(VisualizationConstants.PLUGINS));

                    for (var instanceObject : instances)
                    {
                        if (filter(instanceObject, sloContext.getJsonObject(FILTERS).getJsonObject(DATA_FILTER, null)))
                        {
                            var instance = sloInstance.equalsIgnoreCase(NMSConstants.InstanceType.INTERFACE.getName()) ? instanceObject.getString(NMSConstants.INTERFACE) : instanceObject.getString(AIOpsObject.OBJECT_NAME);

                            var status = getInitialSLOStatus(availabilitySLO, object, instance, sloDetails);

                            if (status == SLOFlapStatus.DEGRADED && globalSLOStatus == SLOFlapStatus.HEALTHY)
                            {
                                globalSLOStatus = SLOFlapStatus.DEGRADED;
                            }

                            var data = new JsonObject()
                                    .put(DURATION_LEFT, duration);

                            detail.put(object + INSTANCE_SEPARATOR + instance, data);

                            // add initial status as up or down
                            updateSLO(data, status, startTime, object, instance, sloId, cycleId);
                        }
                    }
                }
            }

            // add global slo
            var data = new JsonObject()
                    .put(DURATION_LEFT, duration);

            sloCalculatorCacheStore.getSLODetails(sloId).put(EMPTY_VALUE, data);

            updateSLO(data, globalSLOStatus, startTime, NOT_AVAILABLE, EMPTY_VALUE, sloId, cycleId);
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

    /**
     * Filters entities based on configured filter conditions.
     *
     * @param entry the entity to filter
     * @param filter the filter configuration
     * @return true if entity passes the filter, false otherwise
     */
    private boolean filter(JsonObject entry, JsonObject filter)
    {
        var result = false;

        try
        {
            if (filter != null && !filter.isEmpty())
            {
                var conditionGroup = filter.getJsonArray(CONDITION_GROUPS).getJsonObject(0);

                var operator = conditionGroup.getString(OPERATOR);

                var conditions = conditionGroup.getJsonArray(CONDITIONS);

                for (var j = 0; j < conditions.size(); j++)
                {
                    var condition = conditions.getJsonObject(j);

                    var operand =  condition.getString(OPERAND, EMPTY_VALUE);

                    if (entry.containsKey(operand))
                    {
                        result = PolicyEngineConstants.evaluateCondition(conditionGroup.getString(FILTER).equalsIgnoreCase("include"), condition.getString(OPERATOR), condition.getValue(VALUE), entry.getValue(operand));

                        if ((result && operator.equalsIgnoreCase(DatastoreConstants.ConditionGroup.OR.getName())) || (!result && operator.equalsIgnoreCase(DatastoreConstants.ConditionGroup.AND.getName())))
                        {
                            break;
                        }
                    }
                }
            }
            else
            {
                return true;
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }

        return result;
    }

