@param object the object ID
    * @param instance the instance name (empty for device-level SLOs)
    * @param sloDetails previous SLO details from cache
    * @return the initial SLO flap status
    */
   private SLOFlapStatus getInitialSLOStatus(boolean availabilitySLO, long object, String instance, Map<String, JsonObject> sloDetails)
   {
       var sloFlapStatus = SLOFlapStatus.HEALTHY;

       try
       {
           // Prepare sloKey based on instance availability
           var sloKey = !instance.isEmpty()
                   ? object + INSTANCE_SEPARATOR + instance
                   : object + EMPTY_VALUE;

           // --- 1. Check OBJECT status first ---
           var objectStatus = ObjectStatusCacheStore.getStore().getItem(object);

           if (objectStatus != null &&
                   (objectStatus.equalsIgnoreCase(STATUS_DISABLE) || objectStatus.equalsIgnoreCase(STATUS_MAINTENANCE)))
           {
               return SLOFlapStatus.NOT_CALCULATED;
           }

           // --- 2. Then check INSTANCE status (if present) ---
           var status = !instance.isEmpty()
                   ? ObjectStatusCacheStore.getStore().getItem(object, instance)
                   : objectStatus;

           if (status != null &&
                   (status.equalsIgnoreCase(STATUS_DISABLE) || status.equalsIgnoreCase(STATUS_MAINTENANCE)))
           {
               return SLOFlapStatus.NOT_CALCULATED;
           }

           // --- 3. If availability SLO, use UP/DOWN logic ---
           if (availabilitySLO && status != null)
           {
               return status.equalsIgnoreCase(STATUS_UP)
                       ? SLOFlapStatus.HEALTHY
                       : SLOFlapStatus.DEGRADED;
           }

           // --- 4. Fallback to sloDetails if available ---
           if (sloDetails != null && sloDetails.containsKey(sloKey))
           {
               sloFlapStatus = SLOFlapStatus.values()[sloDetails.get(sloKey).
                       getInteger(LAST_SLO_STATUS, 0)];
           }
       }
       catch (Exception exception)
       {
           LOGGER.error(exception);
       }

       return sloFlapStatus;
   }

   // ------------------------ SLO calculation related methods ------------------------ //

   /**
    * Performs periodic SLO calculations for all active cycles.
    * Called by timer to calculate and store SLO metrics at regular intervals.
    */
   private void calculate()
   {
       // get the current timestamp
       var timestamp = DateTimeUtil.currentSeconds();

       for (var entry : sloCycles.entrySet())
       {
           try
           {
               var sloId = entry.getKey();

               var sloInstances = sloCalculatorCacheStore.getSLODetails(sloId);

               // get the cycle id
               var cycleId = entry.getValue();

               // get the slo profile
               var sloProfile = SLOProfileConfigStore.getStore().getItem(sloId);

               // get the slo cycle
               var sloCycle = SLOCycleConfigStore.getStore().getItem(cycleId);

               // get the slo context
               var sloContext = sloProfile.getJsonObject(SLOProfile.SLO_PROFILE_CONTEXT);

               // get the duration i.e. current timestamp - cycle start time
               var duration = timestamp - sloCycle.getLong(SLOCycle.SLO_CYCLE_START_TIME);

               // skip the cycled end time calculation triggered by timer
               if (timestamp / 60 >= sloCycle.getLong(SLOCycle.SLO_CYCLE_END_TIME) / 60)
               {
                   LOGGER.info("skipping manual slo calculation as cycle end time is reached for slo id " + sloId);

                   continue;
               }

               // for daily slo dump data every 15 minute, for weekly 30 min, for monthly and quarterly 1 hour
               if ((SLOFrequency.DAILY.getName().equalsIgnoreCase(sloContext.getString(SLOProfile.SLO_FREQUENCY))) ||
                       (SLOFrequency.WEEKLY.getName().equalsIgnoreCase(sloContext.getString(SLOProfile.SLO_FREQUENCY)) && count.get() % 2 == 0) ||
                       (SLOFrequency.MONTHLY.getName().equalsIgnoreCase(sloContext.getString(SLOProfile.SLO_FREQUENCY)) && count.get() % 4 == 0) ||
                       (SLOFrequency.QUARTERLY.getName().equalsIgnoreCase(sloContext.getString(SLOProfile.SLO_FREQUENCY)) && count.get() % 4 == 0))
               {
                   var downCount = calculateInstanceSLO(sloInstances, sloId, sloCycle, sloProfile, timestamp, duration);

                   calculateGlobalSLO(sloId, sloCycle, sloProfile, timestamp, duration, downCount);
               }
           }
           catch (Exception exception)
           {
               LOGGER.error(exception);
           }
       }

       // reset the count once we reach 4
       if (count.getAndIncrement() >= 4)
       {
           count.set(1);
       }
   }

   /**
    * Calculates SLO metrics for individual instances and writes them to datastore.
    *
    * @param sloInstances map of instance SLO data
    * @param sloId the SLO profile ID
    * @param sloCycle the SLO cycle configuration
    * @param sloProfile the SLO profile configuration
    * @param timestamp the calculation timestamp
    * @param duration the elapsed duration since cycle start
    * @return the count of instances currently in degraded state
    */
   private int calculateInstanceSLO(Map<String, JsonObject> sloInstances, long sloId, JsonObject sloCycle, JsonObject sloProfile, long timestamp, long duration)
   {
       var sloContext = sloProfile.getJsonObject(SLOProfile.SLO_PROFILE_CONTEXT);

       var availability = sloProfile.getString(SLOProfile.SLO_PROFILE_TYPE, EMPTY_VALUE).equalsIgnoreCase(SLOType.AVAILABILITY.getName());

       // keep the count of down events
       var downCount = new AtomicInteger(0);

       var cycleId = sloCycle.getLong(ID);

       if (sloInstances != null && !sloInstances.isEmpty())
       {
           for (var entry : sloInstances.entrySet())
           {
               try
               {
                   var key = entry.getKey();

                   var value = entry.getValue();

                   // empty value will be for global slo
                   if (!key.equalsIgnoreCase(EMPTY_VALUE))
                   {
                       var tokens = key.split(INSTANCE_SEPARATOR);

                       var objectId = CommonUtil.getLong(tokens[0]);

                       var instance = tokens.length > 1 ? tokens[1] : EMPTY_VALUE;

                       // update the last status
                       updateSLO(value, getLastSLOStatus(value), timestamp, objectId, instance, sloId, cycleId, true);

                       // if last status is breached than we need to update the downtime
                       if (getLastSLOStatus(value) == SLOFlapStatus.DEGRADED)
                       {
                           // close the flap at current timestamp
                           sloCalculatorCacheStore.getSLOEvents(sloId).merge(timestamp, -1, Integer::sum);

                           downCount.incrementAndGet();
                       }

                       write(mappers, builder, ArchivedObjectConfigStore.getStore().getObjectIdById(objectId),
                               instance,
                               DatastoreConstants.DatastoreType.SLO_METRIC,
                               DatastoreConstants.PluginId.SLO_INSTANCE,
                               sloId + GROUP_SEPARATOR + cycleId,
                               VisualizationConstants.VisualizationDataSource.SLO_INSTANCE.getName(),
                               timestamp,
                               buildSLOCalculationEvent(value, sloCycle, sloContext.getFloat(SLOProfile.SLO_TARGET), sloContext.getFloat(SLOProfile.SLO_WARNING), instance, duration, availability));
                   }
               }
               catch (Exception exception)
               {
                   LOGGER.error(exception);
               }
           }
       }

       return downCount.intValue();
   }

   /**
    * Calculates global SLO metrics and handles notifications.
    *
    * @param sloId the SLO profile ID
    * @param sloCycle the SLO cycle configuration
    * @param sloProfile the SLO profile configuration
    * @param timestamp the calculation timestamp
    * @param duration the elapsed duration since cycle start
    * @param downCount the number of instances currently in degraded state
    */
   private void calculateGlobalSLO(long sloId, JsonObject sloCycle, JsonObject sloProfile, long timestamp, long duration, int downCount)
   {
       var cycleId = sloCycle.getLong(ID);

       var sloContext = sloProfile.getJsonObject(SLOProfile.SLO_PROFILE_CONTEXT);

       var availability = sloProfile.getString(SLOProfile.SLO_PROFILE_TYPE, EMPTY_VALUE).equalsIgnoreCase(SLOType.AVAILABILITY.getName());

       // generate and dump data for global slo
       var result = merge(sloCalculatorCacheStore.getSLOEvents(sloId), timestamp);

       sloCalculatorCacheStore.getSLOEvents(sloId).clear();

       if (downCount > 0)
       {
           sloCalculatorCacheStore.getSLOEvents(sloId).put(timestamp, downCount);
       }


       var value = sloCalculatorCacheStore.getSLODetails(sloId).get(EMPTY_VALUE);

       // means any down flap is happen in this time interval
       if (!result.isEmpty())
       {
           for (var index = 0; index < result.size(); index++)
           {
               var event = result.getJsonObject(index);

               updateSLO(value, SLOFlapStatus.values()[event.getInteger(SLO_STATUS_FLAP)], event.getLong(TIME_STAMP), NOT_AVAILABLE, EMPTY_VALUE, sloId, cycleId);
           }

           // update the last flap
           updateSLO(value, getLastSLOStatus(value), timestamp, NOT_AVAILABLE, EMPTY_VALUE, sloId, cycleId, true);
       }
       // no down flap is there in this time frame
       else
       {
           updateSLO(value, SLOFlapStatus.HEALTHY, timestamp, NOT_AVAILABLE, EMPTY_VALUE, sloId, cycleId, true);
       }

       var event = buildGlobalSLOCalculationEvent(value, sloCycle, sloContext.getFloat(SLOProfile.SLO_TARGET), sloContext.getFloat(SLOProfile.SLO_WARNING), cycleId + EMPTY_VALUE, duration, availability);

       write(mappers, builder, sloId,
               cycleId + EMPTY_VALUE,
               DatastoreConstants.DatastoreType.SLO_METRIC,
               DatastoreConstants.PluginId.SLO,
               EMPTY_VALUE,
               VisualizationConstants.VisualizationDataSource.SLO.getName(),
               timestamp,
               event);

       var cycleEnd = sloCycle.getLong(SLOCycle.SLO_CYCLE_END_TIME) == timestamp;

       // if in the config store we're having status 0(Ok) and the current status is 1(Warning) or 2(Breached) OR cycle is ending than we need to send notification
       if (sloCycle.getInteger(SLOCycle.SLO_CYCLE_NOTIFICATION_STATUS) < event.getInteger(SLO_STATUS) || cycleEnd)
       {
           notify(sloCycle, sloProfile, event, cycleEnd, timestamp);
       }
   }

