   // ------------------------ Deletion event handling methods ------------------------ //

   /**
    * Handles object deletion events by removing the object from SLO calculations.
    *
    * @param event the object deletion event
    */
   private void handleObjectDisable(JsonObject event)
   {
       try
       {
           var sloId = event.getLong(SLOProfile.SLO_PROFILE_ID);

           var objectId = event.getLong(AIOpsConstants.ENTITY_ID);

           var timestamp = event.getLong(EventBusConstants.EVENT_TIMESTAMP);

           // avoid processing if slo id is not present in slo cycles
           if (sloId == null || !sloCycles.containsKey(sloId))
           {
               return;
           }

           var cycleId = sloCycles.get(sloId);

           var sloDetails = sloCalculatorCacheStore.getSLODetails(sloId);

           // Get the SLO profile to determine the instance type
           var sloProfile = SLOProfileConfigStore.getStore().getItem(sloId);

           if (sloProfile == null || sloProfile.isEmpty())
           {
               LOGGER.warn(String.format("SLO profile %s not found for object deletion", sloId));

               return;
           }

           var sloContext = sloProfile.getJsonObject(SLOProfile.SLO_PROFILE_CONTEXT);

           var sloInstance = sloContext != null ? sloContext.getString(SLOProfile.SLO_INSTANCE, EMPTY_VALUE) : EMPTY_VALUE;

           // Build list of keys to process
           var keys = new ArrayList<String>();

           if (sloInstance.equalsIgnoreCase(NMSConstants.InstanceType.MONITOR.getName()))
           {
               // For monitor type, only add the object key
               keys.add(objectId.toString());

               if (CommonUtil.debugEnabled())
               {
                   LOGGER.debug(String.format("SLO_INSTANCE is monitor, processing single object key: %s", objectId));
               }
           }
           else
           {
               // For non-monitor types, find all instances of this object
               for (var entry : sloDetails.entrySet())
               {
                   var key = entry.getKey();

                   // Skip empty key (global SLO) and find keys starting with objectId + INSTANCE_SEPARATOR
                   if (key.startsWith(objectId + INSTANCE_SEPARATOR))
                   {
                       keys.add(key);
                   }
               }

               if (CommonUtil.debugEnabled())
               {
                   LOGGER.debug(String.format("SLO_INSTANCE is %s, found %d instance keys for object %s", 
                       sloInstance, keys.size(), objectId));
               }
           }

           // Process all keys in the list
           for (var key : keys)
           {
               var detail = sloDetails.get(key);

               if (detail != null)
               {
                   // Extract instance name from key if it contains separator
                   var instance = EMPTY_VALUE;

                   if (key.contains(INSTANCE_SEPARATOR))
                   {
                       var tokens = key.split(INSTANCE_SEPARATOR);

                       instance = tokens.length > 1 ? tokens[1] : EMPTY_VALUE;
                   }

                   // Update the SLO status to HEALTHY so it doesn't contribute to breach
                   updateSLO(detail, SLOFlapStatus.NOT_CALCULATED, timestamp, objectId, instance, sloId, cycleId);

                   if (instance.isEmpty())
                   {
                       LOGGER.info(String.format("Object %s removed from SLO profile %s", objectId, sloId));
                   }
                   else
                   {
                       LOGGER.info(String.format("Instance %s of object %s removed from SLO profile %s", 
                           instance, objectId, sloId));
                   }
               }
           }

           if (keys.isEmpty())
           {
               LOGGER.warn(String.format("No keys found to process for object %s in SLO profile %s", objectId, sloId));
           }
           else
           {
               LOGGER.info(String.format("Processed %d keys for object %s deletion in SLO profile %s", 
                   keys.size(), objectId, sloId));
           }
       }
       catch (Exception exception)
       {
           LOGGER.error(exception);
       }
   }

   /**
    * Handles instance deletion events by removing specific instances from SLO calculations.
    *
    * @param event the instance deletion event
    */
   private void handleInstanceDisable(JsonObject event)
   {
       try
       {
           var sloId = event.getLong(SLOProfile.SLO_PROFILE_ID);

           var objectId = event.getLong(AIOpsConstants.ENTITY_ID);

           var instances = event.getJsonArray(NMSConstants.METRIC_INSTANCES);

           var timestamp = event.getLong(EventBusConstants.EVENT_TIMESTAMP);

           // avoid processing if slo id is not present in slo cycles
           if (sloId == null || !sloCycles.containsKey(sloId))
           {
               return;
           }

           var cycleId = sloCycles.get(sloId);

           if (instances != null && !instances.isEmpty())
           {
               for (var i = 0; i < instances.size(); i++)
               {
                   var instance = instances.getString(i);

                   var key = objectId + INSTANCE_SEPARATOR + instance;

                   var detail = sloCalculatorCacheStore.getSLODetails(sloId).get(key);

                   // If the instance exists in SLO details, update it to HEALTHY status before removal
                   if (detail != null)
                   {
                       // Update the SLO status to HEALTHY so it doesn't contribute to breach
                       updateSLO(detail, SLOFlapStatus.NOT_CALCULATED, timestamp, objectId, instance, sloId, cycleId);

                       LOGGER.info(String.format("Instance %s of object %s removed from SLO profile %s", instance, objectId, sloId));
                   }
               }
           }
       }
       catch (Exception exception)
       {
           LOGGER.error(exception);
       }
   }

