               if (!smsRecipients.isEmpty())
               {
                   Notification

 * @param timestamp the notification timestamp
     */
    private void notify(JsonObject sloCycle, JsonObject sloProfile, JsonObject event, boolean cycleEnd, long timestamp)
    {
        try
        {
            if (sloProfile.containsKey(SLOProfile.SLO_PROFILE_NOTIFICATION_RECIPIENTS) && !sloProfile.getJsonArray(SLOProfile.SLO_PROFILE_NOTIFICATION_RECIPIENTS).isEmpty())
            {
                var notificationRecipients = sloProfile.getJsonArray(SLOProfile.SLO_PROFILE_NOTIFICATION_RECIPIENTS);

                var emailRecipients = new HashSet<String>();

                var smsRecipients = new HashSet<String>();

                var handleRecipients = new HashMap<String, Set<String>>();

                PolicyEngineConstants.setRecipients(emailRecipients, smsRecipients, handleRecipients, notificationRecipients,DEFAULT_ID);

                var sloStatus = SLOStatus.values()[event.getInteger(SLO_STATUS)];

                var notificationContext = buildMailNotificationContext(sloStatus, sloCycle, sloProfile, event, cycleEnd, timestamp);

                if (!emailRecipients.isEmpty())
                {
                    Notification.sendEmail(notificationContext.put(Notification.EMAIL_NOTIFICATION_RECIPIENTS, new JsonArray(new ArrayList<>(emailRecipients))));
                }

                if (!smsRecipients.isEmpty())
                {
                    Notification.sendSMS(buildMessage(sloCycle, sloProfile, event, cycleEnd, timestamp), new JsonArray(new ArrayList<>(smsRecipients)));
                }

                if (!handleRecipients.isEmpty())
                {
                    handleRecipients.forEach((channelType, targets) ->
                    {
                        Notification.send(new JsonObject()
                                .put(NOTIFICATION_TYPE, channelType)
                                .put(CHANNELS, new JsonArray(new ArrayList<>(targets)))
                                .put(Notification.CHANNEL_NOTIFICATION_CONTENT, new StringSubstitutor(notificationContext.getJsonObject(Notification.EMAIL_NOTIFICATION_CONTENT)
                                                .put(SEVERITY_COLOR, getNotificationColor(String.valueOf(sloStatus).toUpperCase(), channelType)).getMap())
                                        .replace(getNotificationTemplate(channelType, sloStatus, cycleEnd))));
                    });
                }
            }

            // update the last sent notification status
            sloCycle.put(SLOCycle.SLO_CYCLE_NOTIFICATION_STATUS, event.getInteger(SLO_STATUS));

            Bootstrap.configDBService().update(DBConstants.TBL_SLO_CYCLE,
                    new JsonObject().put(DBConstants.FIELD_NAME, ID).put(VALUE, sloCycle.getLong(ID)),
                    sloCycle, DEFAULT_USER, SYSTEM_REMOTE_ADDRESS, result ->
                    {
                        if (result.succeeded())
                        {
                            SLOCycleConfigStore.getStore().updateItem(sloCycle.getLong(ID));
                        }
                        else
                        {
                            LOGGER.error(result.cause());
                        }
                    });
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

    private String getNotificationColor(String sloStatus,String channelType)
    {
        if (channelType.equalsIgnoreCase(Notification.NotificationType.SLACK.getName()))
        {
            return SlackNotification.SlackColorCode.valueOf(sloStatus).getColorCode();
        }

        return EMPTY_VALUE;
    }

    /**
     * Builds email notification context for SLO alerts.
     *
     * @param sloStatus the current SLO status
     * @param sloCycle the SLO cycle configuration
     * @param sloProfile the SLO profile configuration
     * @param event the SLO calculation event
     * @param cycleEnd true if this is a cycle end notification
     * @param timestamp the notification timestamp
     * @return the email notification context
     */
    private JsonObject buildMailNotificationContext(SLOStatus sloStatus,JsonObject sloCycle, JsonObject sloProfile, JsonObject event, boolean cycleEnd, long timestamp)
    {
        var context = new JsonObject();

        var notificationContent = new JsonObject();

        try
        {
            context.put(NOTIFICATION_TYPE, Notification.NotificationType.EMAIL.getName())
                    .put(Notification.EMAIL_NOTIFICATION_ATTACHMENT_DISPOSITION_TYPE, "inline").put(Notification.EMAIL_NOTIFICATION_ATTACHMENT_TYPE, "image/png")
                    .put(Notification.EMAIL_NOTIFICATION_ATTACHMENTS, new JsonArray().addAll(Notification.EMAIL_NOTIFICATION_INLINE_ATTACHMENT_ICONS));

            notificationContent.put(SLOProfile.SLO_PROFILE_NAME, sloProfile.getString(SLOProfile.SLO_PROFILE_NAME))
                    .put(SLOProfile.SLO_PROFILE_BUSINESS_SERVICE_NAME, sloProfile.getString(SLOProfile.SLO_PROFILE_BUSINESS_SERVICE_NAME))
                    .put(SLO_STATUS, sloStatus.getName())
                    .put(SLOProfile.SLO_FREQUENCY, sloProfile.getJsonObject(SLOProfile.SLO_PROFILE_CONTEXT).getString(SLOProfile.SLO_FREQUENCY))
                    .put(SLOProfile.SLO_TARGET, sloProfile.getJsonObject(SLOProfile.SLO_PROFILE_CONTEXT).getFloat(SLOProfile.SLO_TARGET))
                    .put(SLO_ACHIEVED_PERCENT, event.getFloat(SLO_ACHIEVED_PERCENT))
                    .put(SLO_VIOLATED_PERCENT, event.getFloat(SLO_VIOLATED_PERCENT))
                    .put(SLOProfile.SLO_PROFILE_TYPE, sloProfile.getString(SLOProfile.SLO_PROFILE_TYPE))
                    .put(SLOProfile.SLO_PROFILE_START_TIME, DateTimeUtil.timestamp(sloCycle.getLong(SLOCycle.SLO_CYCLE_START_TIME) * 1000L))
                    .put(TIME_STAMP, DateTimeUtil.timestamp(timestamp * 1000L));

            if (cycleEnd)
            {
                context.getJsonArray(Notification.EMAIL_NOTIFICATION_ATTACHMENTS).add("information.png");

                context.put(Notification.EMAIL_NOTIFICATION_SUBJECT, "SLO Cycle End")
                        .put(Notification.TEMPLATE_NAME, Notification.EMAIL_NOTIFICATION_SLO_CYCLE_END_HTML_TEMPLATE);

                notificationContent.put(MESSAGE, String.format(SLO_CYCLE_END_NOTIFICATION_MESSAGE, sloProfile.getString(SLOProfile.SLO_PROFILE_NAME), DateTimeUtil.timestamp(sloCycle.getLong(SLOCycle.SLO_CYCLE_START_TIME) * 1000L), DateTimeUtil.timestamp(sloCycle.getLong(SLOCycle.SLO_CYCLE_END_TIME) * 1000L), event.getFloat(SLO_ACHIEVED_PERCENT) + "%"))
                        .put(SLO_URL, String.format(SLO_HISTORY_URL, sloProfile.getLong(ID), sloCycle.getLong(ID)));
            }
            else if (sloStatus == SLOStatus.BREACHED)
            {
                context.getJsonArray(Notification.EMAIL_NOTIFICATION_ATTACHMENTS).add("critical.png");

                context.put(Notification.EMAIL_NOTIFICATION_SUBJECT, "SLO Breached")
                        .put(Notification.TEMPLATE_NAME, Notification.EMAIL_NOTIFICATION_SLO_BREACHED_HTML_TEMPLATE);

                notificationContent.put(MESSAGE, String.format(SLO_BREACHED_NOTIFICATION_MESSAGE, sloProfile.getString(SLOProfile.SLO_PROFILE_NAME), DateTimeUtil.timestamp(timestamp * 1000L), sloProfile.getJsonObject(SLOProfile.SLO_PROFILE_CONTEXT).getFloat(SLOProfile.SLO_TARGET) + "%"))
                        .put(SLO_URL, String.format(SLO_OVERVIEW_URL, sloProfile.getLong(ID)));
            }
            else if (sloStatus == SLOStatus.WARNING)
            {
                context.getJsonArray(Notification.EMAIL_NOTIFICATION_ATTACHMENTS).add("warning.png");

                context.put(Notification.EMAIL_NOTIFICATION_SUBJECT, "SLO Warning")
                        .put(Notification.TEMPLATE_NAME, Notification.EMAIL_NOTIFICATION_SLO_WARNING_HTML_TEMPLATE);

                notificationContent.put(MESSAGE, String.format(SLO_WARNING_NOTIFICATION_MESSAGE, sloProfile.getString(SLOProfile.SLO_PROFILE_NAME), DateTimeUtil.timestamp(timestamp * 1000L)))
                        .put(SLO_URL, String.format(SLO_OVERVIEW_URL, sloProfile.getLong(ID)));
            }

            context.put(Notification.EMAIL_NOTIFICATION_CONTENT, notificationContent);
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }

        return context;
    }

    /**
     * Builds SMS notification message for SLO alerts.
     *
     * @param sloCycle the SLO cycle configuration
     * @param sloProfile the SLO profile configuration
     * @param event the SLO calculation event
     * @param cycleEnd true if this is a cycle end notification
     * @param timestamp the notification timestamp
     * @return the SMS message text
     */
    private String buildMessage(JsonObject sloCycle, JsonObject sloProfile, JsonObject event, boolean cycleEnd, long timestamp)
    {
        var message = EMPTY_VALUE;

        try
        {
            var sloStatus = SLOStatus.values()[event.getInteger(SLO_STATUS)];

            if (cycleEnd)
            {
                message = String.format(SLO_CYCLE_END_NOTIFICATION_MESSAGE, sloProfile.getString(SLOProfile.SLO_PROFILE_NAME), DateTimeUtil.timestamp(sloCycle.getLong(SLOCycle.SLO_CYCLE_START_TIME) * 1000L), DateTimeUtil.timestamp(sloCycle.getLong(SLOCycle.SLO_CYCLE_END_TIME) * 1000L), event.getFloat(SLO_ACHIEVED_PERCENT) + "%");
            }
            else if (sloStatus == SLOStatus.BREACHED)
            {
                message = String.format(SLO_BREACHED_NOTIFICATION_MESSAGE, sloProfile.getString(SLOProfile.SLO_PROFILE_NAME), DateTimeUtil.timestamp(timestamp * 1000L), sloProfile.getJsonObject(SLOProfile.SLO_PROFILE_CONTEXT).getFloat(SLOProfile.SLO_TARGET) + "%");
            }
            else if (sloStatus == SLOStatus.WARNING)
            {
                message = String.format(SLO_WARNING_NOTIFICATION_MESSAGE, sloProfile.getString(SLOProfile.SLO_PROFILE_NAME), DateTimeUtil.timestamp(timestamp * 1000L));
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }

        return message;
    }

    /**
     * Gets the appropriate Teams & SLACK notification template based on SLO status.
     *
     * @param sloStatus the current SLO status
     * @param cycleEnd true if this is a cycle end notification
     * @return the Teams notification template
     */
    private String getNotificationTemplate(String channelType, SLOConstants.SLOStatus sloStatus, boolean cycleEnd)
    {
        var template = EMPTY_VALUE;

        if(channelType.equalsIgnoreCase(Notification.NotificationType.MICROSOFT_TEAMS.getName()))
        {
            if (cycleEnd)
            {
                template = Notification.TEAMS_NOTIFICATION_SLO_CYCLE_END_JSON_TEMPLATE;
            }
            else if (sloStatus == SLOConstants.SLOStatus.BREACHED)
            {
                template = Notification.TEAMS_NOTIFICATION_SLO_BREACHED_JSON_TEMPLATE;
            }
            else if (sloStatus == SLOConstants.SLOStatus.WARNING)
            {
                template = Notification.TEAMS_NOTIFICATION_SLO_WARNING_JSON_TEMPLATE;
            }
        }
        else
        {
            if (cycleEnd)
            {
                template = Notification.SLACK_NOTIFICATION_SLO_CYCLE_END_JSON_TEMPLATE;
            }
            else if (sloStatus == SLOConstants.SLOStatus.BREACHED)
            {
                template = Notification.SLACK_NOTIFICATION_SLO_BREACHED_JSON_TEMPLATE;
            }
            else if (sloStatus == SLOConstants.SLOStatus.WARNING)
            {
                template = Notification.SLACK_NOTIFICATION_SLO_WARNING_JSON_TEMPLATE;
            }
        }

        return template;
    }
