                                        var metricPlugin = MetricPlugin.valueOfName(event.getString(Metric.METRIC_PLUGIN));

                                        switch (metricPlugin)
                                        {
                                            case CISCO_UCS_CHASSIS ->
                                                    add("cisco.ucs.chassis", event.getJsonObject(RESULT), AIOpsConstants.DependencyLevel.NINE, connections);

