/**
 * FlowStatCalculator is responsible for collecting, aggregating, and reporting flow statistics
 * from network flow data processing.
 * <p>
 * Key responsibilities:
 * - Collecting flow statistics from pmacct (NetFlow/sFlow accounting daemon)
 * - Aggregating flow data from multiple FlowProcessor instances
 * - Calculating per-second flow rates and volume metrics
 * - Writing flow statistics to the datastore for visualization and analysis
 * - Handling remote flow statistics from collector instances
 * - Managing column mappers for datastore schema
 * <p>
 * The calculator operates in two modes:
 * 1. APP mode: Receives aggregated stats from collectors and writes to datastore
 * 2. COLLECTOR mode: Fetches raw pmacct data and sends to APP instance
 * <p>
 */
public class FlowStatCalculator extends AbstractVerticle
{
    /** Logger for this class */
    private static final Logger LOGGER = new Logger(FlowStatCalculator.class, GlobalConstants.MOTADATA_FLOW, "Flow Stat Calculator");

    /** Timer interval (in seconds) for flushing flow statistics Default: 2 min*/
    private static final int FLOW_STAT_FLUSH_TIMER_SECONDS = MotadataConfigUtil.getFlowStatFlushTimerSeconds();

    /** Map storing per-source flow statistics [count, volume_bytes] */
    private final Map<String, long[]> stats = new HashMap<>();

    /** StringBuilder for building column mapper strings efficiently */
    private final StringBuilder builder = new StringBuilder(0);

    /** Set of column mappers to track datastore schema changes */
    private Set<String> mappers;

    /** Total aggregated flow events count */
    private long events = 0L;

    /** Total aggregated flow volume in bytes */
    private long eventVolumeBytes = 0L;

    /** Reusable JsonObject for event data to reduce object allocation */
    private final JsonObject event = new JsonObject();

    /** Path to NetFlow pmacct daemon pipe */
    private static final String NFACCTD_PIPE_PATH = GlobalConstants.CURRENT_DIR + GlobalConstants.PATH_SEPARATOR + "NetFlow.pipe";

    /** Path to sFlow pmacct daemon pipe */
    private static final String SFACCTD_PIPE_PATH = GlobalConstants.CURRENT_DIR + GlobalConstants.PATH_SEPARATOR + "sFlow.pipe";

    /** Total flows processed from pmacct output (used for EPS calculation) */
    private final AtomicLong totalFlowsProcessed = new AtomicLong(0);

    /**
     * Initializes the FlowStatCalculator verticle.
     * <p>
     * This method:
     * 1. Sets up event bus consumers for flow statistics from processors and remote collectors
     * 2. Starts periodic timer for fetching pmacct data and writing statistics
     * 3. Configures different behavior based on bootstrap type (APP vs COLLECTOR)
     * <p>
     * In APP mode: Receives aggregated stats from collectors and writes to datastore
     * In COLLECTOR mode: Fetches raw pmacct data and sends to APP instance
     *
     * @param promise Promise to be completed when initialization is done
     * @throws Exception If an error occurs during initialization
     */
    @Override
    public void start(Promise<Void> promise) throws Exception
    {
        // Initialize column mappers set for datastore schema tracking
        mappers = new HashSet<>();

        LOGGER.info("Starting pmacct License Monitor");

        // Set up periodic timer to fetch pmacct data and process statistics
        vertx.setPeriodic(FLOW_STAT_FLUSH_TIMER_SECONDS * 1000L, h -> fetch());

        // Configure APP mode behavior - receives stats from remote collectors
        if(Bootstrap.bootstrapType().name().equalsIgnoreCase(BootstrapType.APP.name()))
        {
            // Consumer for remote flow statistics from collector instances
            vertx.eventBus().<JsonObject>localConsumer(EVENT_FLOW_REMOTE_STAT, message -> {

                var item = message.body();

                if(item != null && item.containsKey(TOTAL_FLOWS))
                {
                    // Track total flows for EPS calculation
                    totalFlowsProcessed.addAndGet(item.getLong(TOTAL_FLOWS));

                    if(CommonUtil.traceEnabled())
                    {
                        LOGGER.trace("Event Received from Collector, Merging Data... " +  totalFlowsProcessed);
                    }
                }
            });
        }

        // Consumer for local flow processor statistics
        vertx.eventBus().<JsonObject>localConsumer(EVENT_FLOW_PROCESSOR_STAT, message -> {

            var item = message.body();

            if(item != null)
            {
                // Merge statistics from local flow processors
                merge(item.getJsonObject(RESULT));

                // Aggregate flow counts and volume bytes
                if(item.getLong(AGGREGATED_FLOWS) != null && item.getLong(AGGREGATED_VOLUME_BYTES) != null)
                {
                    events+= item.getLong(AGGREGATED_FLOWS);

                    eventVolumeBytes += item.getLong(AGGREGATED_VOLUME_BYTES);

                    if(CommonUtil.traceEnabled())
                    {
                        LOGGER.trace("Flow Processor Stats Collected...");
                    }
                }
            }
        });

        promise.complete();
    }

    /**
     * Merges incoming stats map into the local stats map.
     * For each source, the count and volume values are added to existing totals.
     * Uses compute() method for thread-safe atomic updates.
     *
     * @param stats JsonObject containing per-source statistics to merge
     */
    private void merge(JsonObject stats)
    {
        if (stats != null)
        {
            for (var source : stats.getMap().keySet())
            {
                var currentValues = stats.getJsonArray(source);

                // Merge using compute for less branching and better clarity
                this.stats.compute(source, (k, values) ->
                {

                    if (values == null)
                    {
                        // Clone to prevent retaining references to input map's array
                        return new long[]{currentValues.getLong(0), currentValues.getLong(1)};
                    }
                    else
                    {
                        values[0] += currentValues.getLong(0); // count

                        values[1] += currentValues.getLong(1); // sum

                        return values;
                    }
                });
            }
        }
    }

    /**
     * Main fetch method that orchestrates pmacct data collection and statistics processing.
     * <p>
     * This method:
     * 1. Spawns processes to read from both NetFlow and sFlow pmacct pipes
     * 2. Processes the collected data based on bootstrap type:
     *    - COLLECTOR: Sends EPS stats to APP instance
     *    - APP: Writes flow statistics to datastore
     * <p>
     * Uses Future composition to handle both pmacct processes sequentially.
     */
    private void fetch()
    {
        // Process both NetFlow and sFlow pipes sequentially
        spawnProcess(NFACCTD_PIPE_PATH)
                .compose(future -> spawnProcess(SFACCTD_PIPE_PATH))
                .onComplete(handler -> {

            if(Bootstrap.bootstrapType() == GlobalConstants.BootstrapType.EVENT_COLLECTOR || Bootstrap.bootstrapType() == GlobalConstants.BootstrapType.FLOW_COLLECTOR || Bootstrap.bootstrapType() == BootstrapType.EDGE_COLLECTOR)
            {
                // Collector mode: Send EPS statistics to APP instance
                if(totalFlowsProcessed.get() > 0)
                {
                    if(CommonUtil.traceEnabled())
                    {
                        LOGGER.trace("Sending EPS stat to APP : " + totalFlowsProcessed);
                    }

                    vertx.eventBus().send(EVENT_REMOTE, new JsonObject()
                            .put(EVENT_TYPE, EVENT_FLOW_REMOTE_STAT)
                            .put(REMOTE_EVENT_PROCESSOR_UUID, Bootstrap.getRegistrationId())
                            .put(TOTAL_FLOWS, totalFlowsProcessed.getAndSet(0)));
                }
            }
            else
            {
                // APP mode: Write aggregated statistics to datastore
                writeFlowStats();
            }
        });
    }

    /**
     * Spawns a pmacct process to read flow statistics from the specified pipe.
     * <p>
     * This method:
     * 1. Executes pmacct command with specific parameters for statistics extraction
     * 2. Parses the output to extract flow counts
     * 3. Handles process errors and logging
     * 4. Uses executeBlocking to avoid blocking the event loop
     *
     * @param path Path to the pmacct pipe (NetFlow or sFlow)
     * @return Future that completes when the process finishes
     */
    private Future<Void> spawnProcess(String path)
    {
        var promise = Promise.<Void>promise();

        // Use executeBlocking to avoid blocking the event loop during process execution
        vertx.executeBlocking(blockingPromise -> {
            try
            {
                // Execute pmacct command: -s (statistics), -e (erase), -p (pipe path)
                var process = new ProcessBuilder("/usr/local/pmacct/bin/pmacct", "-s", "-e", "-p", path)
                        .redirectErrorStream(false)
                        .start();

                // Handle both stdout and stderr streams
                try (BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
                     BufferedReader errorReader = new BufferedReader(new InputStreamReader(process.getErrorStream())))
                {

                    // Parse pmacct output to extract flow statistics
                    parseOutput(reader);

                    int exitCode = process.waitFor();

                    // Handle process errors if exit code is non-zero
                    if (exitCode != 0)
                    {
                        onProcessError(errorReader, exitCode);
                    }

                    blockingPromise.complete();
                }
            }
            catch (Exception e)
            {
                blockingPromise.fail(e);
            }
        }, promise);

        return promise.future();
    }

    /**
     * Handles pmacct process errors by reading error stream and logging.
     *
     * @param errorReader BufferedReader for the process error stream
     * @param exitCode Process exit code
     * @throws IOException If error reading the error stream
     */
    private void onProcessError(BufferedReader errorReader, int exitCode) throws IOException
    {
        var errorOutput = new StringBuilder();

        String line;

        while ((line = errorReader.readLine()) != null)
        {
            errorOutput.append(line).append("\n");
        }

        LOGGER.error(new RuntimeException("pmacct command failed with exit code " + exitCode + ": " + errorOutput));
    }

    /**
     * Parses pmacct command output to extract flow count information.
     * <p>
     * Expected pmacct output format (whitespace-separated):
     * [field1] [field2] [flows_count] [field4] ...
     * <p>
     * This method extracts the flow count from the third column and accumulates
     * the total flows processed for EPS (Events Per Second) calculation.
     *
     * @param reader BufferedReader containing pmacct output
     * @throws IOException If error reading the output stream
     */
    private void parseOutput(BufferedReader reader) throws IOException
    {
        String line;

        while ((line = reader.readLine()) != null)
        {
            line = line.trim();

            if (line.isEmpty() || line.startsWith("#") || line.contains("ERROR") || line.contains("PEER_SRC_IP")) continue;

            var parts = line.split("\\s+");

            if (parts.length >= 4)
            {
                try
                {
                    var flows = Long.parseLong(parts[2]);

                    totalFlowsProcessed.addAndGet(flows);

                    if(CommonUtil.traceEnabled())
                    {
                        LOGGER.trace("Adding Flows: " + totalFlowsProcessed);
                    }
                }
                catch (NumberFormatException exception)
                {
                    if(CommonUtil.traceEnabled())
                    {
                        LOGGER.trace("Failed to parse pmacct line: " + line);
                    }
                }
            }
        }
    }

    /**
     * Writes aggregated flow statistics to the datastore.
     * <p>
     * This method performs two types of writes:
     * 1. Overall flow statistics (total flows, volume, per-second rates)
     * 2. Per-source flow statistics (individual source breakdowns)
     * <p>
     * After writing, all counters and maps are reset for the next collection cycle.
     * Similar to LogStatCalculator's calculate() method but for flow data.
     */
    private void writeFlowStats()
    {
        // Capture current total flows for rate calculation
        long totalFlows = totalFlowsProcessed.getAndSet(0L);

        // Write overall flow statistics if we have data
        if(events > 0 && eventVolumeBytes > 0)
        {
            event.clear();

            // Send overall flow statistics with calculated per-second rates
            send(event
                    .put(FLOW_VOLUME_BYTES, eventVolumeBytes)
                    .put(FLOWS_TOTAL, events)
                    .put(FLOWS_PER_SEC, Math.round(CommonUtil.getDouble(totalFlows) / FLOW_STAT_FLUSH_TIMER_SECONDS))
                    .put(FLOW_VOLUME_BYTES_PER_SEC, Math.round(CommonUtil.getDouble(eventVolumeBytes) / FLOW_STAT_FLUSH_TIMER_SECONDS))
                    .put(EVENT_TIMESTAMP, DateTimeUtil.currentSeconds()), DatastoreConstants.PluginId.FLOW_STAT.getName() + DASH_SEPARATOR + "flow.stat.calculator");

            if(MotadataConfigUtil.devMode())
            {
                vertx.eventBus().send("test.flow.stat.metric", event);
            }
        }

        // Write per-source flow statistics if available
        if(!stats.isEmpty())
        {
            stats.forEach((source, flows) -> {

                event.clear();

                // Write individual source statistics to datastore
                DatastoreConstants.write(event
                        .put(EVENT_SOURCE, source)
                        .put(SOURCE_FLOW_VOLUME_BYTES, flows[1])
                        .put(SOURCE_FLOWS, flows[0])
                        .put(PLUGIN_ID, DatastoreConstants.PluginId.FLOW_VOLUME_STAT.getName())
                        .put(EVENT_TIMESTAMP, DateTimeUtil.currentSeconds())
                        .put(DatastoreConstants.DATASTORE_TYPE, DatastoreConstants.DatastoreType.FLOW.ordinal()), "flow.volume.stat", mappers, builder);

                if(MotadataConfigUtil.devMode())
                {
                    vertx.eventBus().send("test.flow.stat.event", event);
                }
            });

            // Reset all counters and maps for next collection cycle
            stats.clear();

            events = 0;

            eventVolumeBytes = 0;
        }
    }

    private void send(JsonObject event, String plugin)
    {
        var buffer = Buffer.buffer("UTF-8");

        buffer.setLongLE(0, CommonUtil.getLong(event.remove(EVENT_TIMESTAMP)));

        if (CommonUtil.debugEnabled())
        {
            LOGGER.debug(String.format("event send to db with plugin : %s ", plugin));
        }

        var bytes = plugin.getBytes(StandardCharsets.UTF_8);

        buffer.appendIntLE(bytes.length);

        buffer.appendBytes(bytes);

        buffer.appendByte(DatastoreConstants.DatastoreFormat.VERTICAL.getName().byteValue());

        buffer.appendByte(CommonUtil.getByteValue(DatastoreConstants.DatastoreType.PERFORMANCE_METRIC.ordinal()));

        //adding static object id: 9999999 for retrieving data for visualization
        buffer.appendIntLE(CommonUtil.getInteger(NMSConstants.DUMMY_OBJECT_ID));

        buffer.appendIntLE(EMPTY_VALUE.length()).appendString(EMPTY_VALUE);

        event.getMap().forEach((key, value) ->
        {
            if (value != null)
            {
                updateBuffer(key, CommonUtil.getString(value), buffer);
            }
        });

        vertx.eventBus().send(EventBusConstants.EVENT_DATASTORE_WRITE + "." + DatastoreConstants.DatastoreCategory.METRIC.getName(), buffer.getBytes());
    }

    private void updateBuffer(String column, String value, Buffer buffer)
    {
        try
        {
            builder.setLength(0);

            var category = DatastoreConstants.getDataCategory(true, column, value);

            buffer.appendByte(category);

            var bytes = column.getBytes(StandardCharsets.UTF_8);

            buffer.appendIntLE(bytes.length).appendBytes(bytes);

            if (category == DatastoreConstants.DataCategory.FLOAT.getName())
            {
                ByteUtil.writeDouble(buffer, CommonUtil.getDouble(value));
            }
            else if (category == DatastoreConstants.DataCategory.NUMERIC.getName())
            {
                buffer.appendLongLE(Math.round(CommonUtil.getDouble(value)));
            }
            else
            {
                bytes = value.getBytes(StandardCharsets.UTF_8);

                buffer.appendIntLE(bytes.length).appendBytes(bytes);
            }

            builder.append(category).append(COLUMN_SEPARATOR).append(DatastoreConstants.PluginId.FLOW_STAT.getName()).append(COLUMN_SEPARATOR).append(column).append(COLUMN_SEPARATOR).append(NO);

            if (!mappers.contains(builder.toString()))
            {
                mappers.add(builder.toString());

                vertx.eventBus().publish(EventBusConstants.EVENT_COLUMN_MAPPER_UPDATE,
                        new JsonObject()
                                .put(CHANGE_NOTIFICATION_TYPE, EventBusConstants.ChangeNotificationType.UPDATE_METRIC_COLUMN.name())
                                .put(DatastoreConstants.MAPPER, builder.toString()));
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }
}

