the requested status filters. When a match is found,
    * it updates the result using {@link #updateAvailabilityStatusByEntity}.
    *
    * @param context  The context containing query parameters:
    *                 <ul>
    *                   <li>{@code tag} - JsonObject mapping tag names to entity arrays</li>
    *                   <li>{@code plugins} - JsonArray of plugin identifiers (format: "pluginId-type")</li>
    *                   <li>{@code status} - JsonArray of status values to include</li>
    *                   <li>{@code group.by} - Grouping type for application lookup</li>
    *                 </ul>
    * @param result   The result object to populate with matched data
    * @param resultBy The result grouping type (tag name or empty string to skip tag column)
    */
   private void setTagResult(JsonObject context, JsonObject result, String resultBy)
   {
       var instancePlugins = context.getJsonArray(VisualizationConstants.PLUGINS);

       for (var entry : context.getJsonObject(VisualizationConstants.VisualizationGrouping.TAG.getName()).getMap().entrySet()) //Entities From the Qualified Entity...
       {
           var tag = entry.getKey();

           for (var entity : (JsonArray) entry.getValue()) //Entities From the Qualified Entity...
           {
               JsonObject apps = null;

               var tokens = CommonUtil.getString(entity).split(GROUP_SEPARATOR);

               var items = ObjectStatusCacheStore.getStore().getInstanceItems(ObjectConfigStore.getStore().getIdByObjectId(CommonUtil.getInteger(tokens[0])), false);

               for (var instancePlugin : instancePlugins)
               {
                   var values = CommonUtil.getString(instancePlugin).split(DASH_SEPARATOR);

                   var type = getInstanceMetricByType(context, values[1]);

                   if (items != null && items.containsKey(type + INSTANCE_SEPARATOR + tokens[1] + INSTANCE_SEPARATOR + values[0]))
                   {
                       if (context.getString(VisualizationConstants.GROUP_BY).equalsIgnoreCase(VisualizationConstants.GROUP_APP))
                       {
                           apps = MetricConfigStore.getStore().getAppsByObjectId(ObjectConfigStore.getStore().getIdByObjectId(CommonUtil.getInteger(tokens[0])));
                       }

                       var status = CommonUtil.getString(items.get(type + INSTANCE_SEPARATOR + tokens[1] + INSTANCE_SEPARATOR + values[0]));

                       if (apps != null && apps.containsKey(tokens[1]) && context.getJsonArray(STATUS).contains(status.toLowerCase()))
                       {
                           updateAvailabilityStatusByEntity(result, Status.valueOf(status.toUpperCase()), resultBy, tag, CommonUtil.getInteger(tokens[0]), apps.getString(tokens[1]));
                       }
                       else if (!context.getString(VisualizationConstants.GROUP_BY).equalsIgnoreCase(VisualizationConstants.GROUP_APP) && context.getJsonArray(STATUS).contains(status.toLowerCase()))
                       {
                           //as key contains instance type so splitting and checking it matches same selected instance with selected status if matches put that in map...
                           updateAvailabilityStatusByEntity(result, Status.valueOf(status.toUpperCase()), resultBy, tag, CommonUtil.getInteger(tokens[0]), tokens[1]);
                       }
                   }
               }
           }
       }
   }

   /**
    * Maps instance type to metric type based on the grouping context.
    * <p>
    * This method performs forward mapping from instance types (used in cache keys) to
    * metric types (used in plugin configurations). The mapping is context-dependent
    * based on the {@code group.by} setting.
    * <p>
    * Mapping rules:
    * <ul>
    *   <li>VM grouping + {@code esxi.vm} → {@code vmware.esxi.vm}</li>
    *   <li>Interface grouping + {@code interface} → {@code network.interface}</li>
    *   <li>System network interface grouping → {@code linux.network.interface}</li>
    * </ul>
    *
    * @param context The context containing the {@code group.by} parameter
    * @param tokens  The tokens parsed from the instance key (tokens[0] is the instance type)
    * @param type    The initial instance type to potentially transform
    * @return The mapped metric type, or the original type if no mapping applies
    */
   private String getInstanceTypeByMetric(JsonObject context, String[] tokens, String type)
   {
       if (context.getString(VisualizationConstants.GROUP_BY).equalsIgnoreCase(VisualizationConstants.GROUP_VM) && tokens[0].equalsIgnoreCase(NMSConstants.ESXI_VM))
       {
           type = "vmware.esxi.vm";
       }
       else if (context.getString(VisualizationConstants.GROUP_BY).equalsIgnoreCase(NMSConstants.INTERFACE) && tokens[0].equalsIgnoreCase(NMSConstants.INTERFACE))
       {
           type = "network.interface";
       }
       else if (context.getString(VisualizationConstants.GROUP_BY).equalsIgnoreCase(NMSConstants.SYSTEM_NETWORK_INTERFACE) && tokens[0].equalsIgnoreCase(NMSConstants.SYSTEM_NETWORK_INTERFACE))
       {
           type = "linux.network.interface";
       }

       return type;
   }

   /**
    * Maps metric type back to instance type based on the grouping context.
    * <p>
    * This method performs reverse mapping from metric types (used in plugin configurations)
    * to instance types (used in cache keys). The mapping is context-dependent based on
    * the {@code group.by} setting.
    * <p>
    * Mapping rules:
    * <ul>
    *   <li>VM grouping: {@code vmware.esxi.vm} → {@code esxi.vm}</li>
    *   <li>Interface grouping: {@code network.interface} → {@code interface}</li>
    *   <li>App/Process grouping:
    *     <ul>
    *       <li>{@code linux.process} or {@code windows.process} → {@code system.process}</li>
    *       <li>{@code windows.service} → {@code system.service}</li>
    *     </ul>
    *   </li>
    * </ul>
    *
    * @param context The context containing the {@code group.by} parameter
    * @param type    The metric type to potentially transform
    * @return The mapped instance type, or the original type if no mapping applies
    */
   private String getInstanceMetricByType(JsonObject context, String type)
   {
       if (context.getString(VisualizationConstants.GROUP_BY).equalsIgnoreCase(VisualizationConstants.GROUP_VM))
       {
           if (type.equalsIgnoreCase("vmware.esxi.vm"))
           {
               type = NMSConstants.ESXI_VM;
           }
       }

       else if (context.getString(VisualizationConstants.GROUP_BY).equalsIgnoreCase(NMSConstants.INTERFACE))
       {
           if (type.equalsIgnoreCase("network.interface"))
           {
               type = NMSConstants.INTERFACE;
           }
       }

       else if (context.getString(VisualizationConstants.GROUP_BY).equalsIgnoreCase(VisualizationConstants.GROUP_APP) || context.getString(VisualizationConstants.GROUP_BY).equalsIgnoreCase(VisualizationConstants.GROUP_PROCESS))
       {
           if (type.equalsIgnoreCase("linux.process") || type.equalsIgnoreCase("windows.process"))
           {
               type = NMSConstants.SYSTEM_PROCESS;
           }
           else if (type.equalsIgnoreCase("windows.service"))
           {
               type = NMSConstants.SYSTEM_SERVICE;
           }
       }
       return type;
   }

   /**
    * Adds a single availability status entry to the result for heatmap visualization.
    * <p>
    * This method populates the columnar result arrays with object ID, status, instance name,
    * instance IP, timestamp, and duration. It converts the internal object ID to the external
    * object ID using {@link ObjectConfigStore}.
    * <p>
    * Instance IP is only added when the instance type is configured in
    * {@link NMSConstants#INSTANCE_IP_METRICS}, otherwise an empty value is used.
    *
    * @param result       The result object containing columnar arrays to populate
    * @param status       The status enum value (UP, DOWN, WARNING, etc.)
    * @param object       The internal object ID (will be converted to external object ID)
    * @param timestamp    The status timestamp in seconds (0 to skip timestamp/duration columns)
    * @param duration     The status duration in seconds
    * @param instance     The instance name (empty string to skip instance columns)
    * @param instanceType The instance type for IP lookup (e.g., "interface", "system.network.interface")
    */
   private void updateAvailabilityStatus(JsonObject result, GlobalConstants.Status status, long object, long timestamp, int duration, String instance, String instanceType)
   {
       result.getJsonArray(APIConstants.Entity.OBJECT.getName().toLowerCase()).add(ObjectConfigStore.getStore().getObjectIdById(object));

       result.getJsonArray(STATUS).add(status);

       if (instance != null && !instance.isEmpty())
       {
           result.getJsonArray(INSTANCE).add(instance);

           if (NMSConstants.INSTANCE_IP_METRICS.containsKey(instanceType))
           {
               result.getJsonArray(INSTANCE_IP).add(ObjectCacheStore.getStore().getInstanceIP(object, instance));
           }
           else
           {
               result.getJsonArray(INSTANCE_IP).add(EMPTY_VALUE);
           }
       }

       if (timestamp > 0)
       {
           result.getJsonArray(TIME_STAMP).add(timestamp * 1000);

           result.getJsonArray(DURATION).add(duration);
       }
   }

   /**
    * Adds an availability status entry with entity grouping to the result.
    * <p>
    * This method is used when results are grouped by an entity type (tag or group).
    * It adds the object ID, status, entity value, and optionally the instance name
    * to the corresponding columnar arrays in the result.
    * <p>
    * The entity type column is only added when {@code entityType} is not an empty value.
    *
    * @param result     The result object containing columnar arrays to populate
    * @param status     The status enum value (UP, DOWN, WARNING, etc.)
    * @param entityType The entity type for grouping (e.g., "tag", "group", or empty to skip)
    * @param entity     The entity value (e.g., tag name, group name)
    * @param object     The external object ID
    * @param instance   The instance name (null or empty to skip instance column)
    */
   private void updateAvailabilityStatusByEntity(JsonObject result, GlobalConstants.Status status, String entityType, String entity, int object, String instance)
   {
       result.getJsonArray(APIConstants.Entity.OBJECT.getName().toLowerCase()).add(object);

       /*
       entityType can be {example = Tag} and if Empty Value do not include that in Map.
        */
       if (!entityType.equalsIgnoreCase(EMPTY_VALUE))
       {
           result.getJsonArray(entityType).add(entity);
       }

       result.getJsonArray(STATUS).add(status);

       if (instance != null && !instance.isEmpty())
       {
           result.getJsonArray(INSTANCE).add(instance);
       }
   }

   /**
    * Adds an object status entry with full metadata to the result for active status queries.
    * <p>
    * This method populates the result with comprehensive object information including:
    * <ul>
    *   <li>Object ID (converted from internal to external ID)</li>
    *   <li>Status value</li>
    *   <li>Instance name (with dynamic column naming based on context)</li>
    *   <li>Timestamp and duration (when provided)</li>
    *   <li>Group names (resolved from group IDs, comma-separated)</li>
    *   <li>Instance IP (for report containers with IP-enabled instance types)</li>
    *   <li>Reason for status (for report containers)</li>
    *   <li>Object creation time (for report containers)</li>
    * </ul>
    * <p>
    * The instance column name is determined by the {@code group.by} context value or
    * falls back to the first value in {@code instance.type} array.
    *
    * @param result    The result object containing columnar arrays to populate
    * @param status    The status enum value (UP, DOWN, WARNING, etc.)
    * @param object    The internal object ID (will be converted to external object ID)
    * @param timestamp The status timestamp in seconds (0 to skip timestamp/duration columns)
    * @param duration  The status duration in seconds
    * @param instance  The instance name (empty string for object-level queries)
    * @param context   The query context for determining column names and report options
    * @param builder   StringBuilder for concatenating group names (null to skip group column)
    */
   private void updateObjectStatus(JsonObject result, GlobalConstants.Status status, long object, long timestamp, int duration, String instance, JsonObject context, StringBuilder builder)
   {
       result.getJsonArray(APIConstants.Entity.OBJECT.getName().toLowerCase()).add(ObjectConfigStore.getStore().getObjectIdById(object));

       result.getJsonArray(STATUS).add(status);

       if (instance != null && !instance.isEmpty())
       {
           result.getJsonArray(context.getString(VisualizationConstants.GROUP_BY) != null && !context.getString(VisualizationConstants.GROUP_BY).isEmpty() ? context.getString(VisualizationConstants.GROUP_BY) : context.getJsonArray(INSTANCE_TYPE).getString(0)).add(instance);
       }

       if (timestamp > 0)
       {
           result.getJsonArray(TIME_STAMP).add(timestamp * 1000);

           result.getJsonArray(DURATION).add(duration);
       }

       if (builder != null)
       {
           var item = ObjectConfigStore.getStore().getItem(object, false);

           if (item.containsKey(AIOpsObject.OBJECT_GROUPS))
           {
               var groups = item.getJsonArray(AIOpsObject.OBJECT_GROUPS);

               if (!groups.isEmpty())
               {
                   for (var group : groups)
                   {
                       if (!builder.isEmpty())
                       {
                           builder.append(COMMA_SEPARATOR); // Append comma separator if not the first string
                       }

                       // In Report, we require to have group name instead of group ID
                       builder.append(GroupConfigStore.getStore().getItem(CommonUtil.getLong(group), false).getString(Group.FIELD_GROUP_NAME));
                   }
               }
               else
               {
                   builder.append(EMPTY_VALUE);
               }

               result.getJsonArray(AIOpsObject.OBJECT_GROUPS).add(builder.toString());

               builder.setLength(0);
           }
       }

       // add the "instance.ip" column in case of a report.
       if (result.containsKey(INSTANCE_IP))
       {
           result.getJsonArray(INSTANCE_IP).add(ObjectCacheStore.getStore().getInstanceIP(object, instance));
       }

       // add the "reason" column in case of a report.
       if (result.containsKey(REASON))
       {
           result.getJsonArray(REASON).add(ObjectStatusCacheStore.getStore().getItemByReason(object,EMPTY_VALUE));
       }

       // add the "object.creation.time" column in case of a report.
       if (result.containsKey(AIOpsObject.OBJECT_CREATION_TIME))
       {
           result.getJsonArray(AIOpsObject.OBJECT_CREATION_TIME).add(ObjectConfigStore.getStore().getItem(object).getValue(AIOpsObject.OBJECT_CREATION_TIME_SECONDS, 0));
       }

   }

   /**
    * Retrieves active status information with durations for objects and instances.
    * <p>
    * This method queries the event bus for status duration data and combines it with
    * status information from the {@link ObjectStatusCacheStore}. It supports both
    * object-level and instance-level queries, as well as report-specific columns.
    * <p>
    * For report containers ({@code container.type} = "report"), additional columns are added:
    * <ul>
    *   <li>{@code object.groups} - Comma-separated group names</li>
    *   <li>{@code reason} - Status change reason</li>
    *   <li>{@code instance.ip} - Instance IP (for instance-level with IP metrics)</li>
    *   <li>{@code object.creation.time} - Object creation timestamp (for object-level)</li>
    * </ul>
    * <p>
    * The method sends a request to {@link EventBusConstants#EVENT_OBJECT_STATUS_DURATION_QUERY}
    * to retrieve duration information, then iterates through objects/instances to build the result.
    *
    * @param context The context containing query parameters:
    *                <ul>
    *                  <li>{@code instance.type} - JsonArray of instance types</li>
    *                  <li>{@code status} - JsonArray of status values to filter</li>
    *                  <li>{@code group.by} - Grouping type for column naming</li>
    *                  <li>{@code container.type} - "report" for report-specific columns</li>
    *                </ul>
    * @param objects The array of entity IDs to query
    * @return A {@link Future} that will be completed with a {@link JsonObject} containing:
    *         <ul>
    *           <li>{@code object} - JsonArray of object IDs</li>
    *           <li>{@code status} - JsonArray of status values</li>
    *           <li>{@code timestamp} - JsonArray of timestamps (milliseconds)</li>
    *           <li>{@code duration} - JsonArray of durations (seconds)</li>
    *           <li>Additional columns based on instance type and container type</li>
    *         </ul>
    *         The future fails with {@code INVALID_NO_DATA_FOUND} if no matching data is found.
    */
   private Future<JsonObject> getObjectActiveStatuses(JsonObject context, JsonArray objects)
   {
       var result = new JsonObject();

       var promise = Promise.<JsonObject>promise();

       try
       {
           Bootstrap.vertx().eventBus().<JsonObject>request(EventBusConstants.EVENT_OBJECT_STATUS_DURATION_QUERY, context, reply ->
           {
               try
               {
                   if (reply.result() != null && !reply.result().body().isEmpty())
                   {
                       var containerTypeReport = context.containsKey(VisualizationConstants.CONTAINER_TYPE) && context.getString(VisualizationConstants.CONTAINER_TYPE) != null && context.getString(VisualizationConstants.CONTAINER_TYPE).equalsIgnoreCase(VisualizationConstants.CONTAINER_TYPE_REPORT);

                       // Extract instance type value from context for reuse
                       var instanceType = context.containsKey(INSTANCE_TYPE) ? context.getJsonArray(INSTANCE_TYPE).getString(0) : null;

                       var durations = reply.result().body();

                       StringBuilder builder = null;

                       if (containerTypeReport)
                       {
                           builder = new StringBuilder();

                           result.put(AIOpsObject.OBJECT_GROUPS, new JsonArray());

                           result.put(REASON, new JsonArray());

                           // if the context contains an instance type, and it is not empty and the instance type is present in the configured IP metrics list then add instance ip column in the result else add DISCOVERED TIME column.
                           if (instanceType != null && !instanceType.isEmpty() && NMSConstants.INSTANCE_IP_METRICS.containsKey(instanceType))
                           {
                               /*
                                *  If the object is an instance:
                                *  - We need to add INSTANCE_IP as a column in the result
                                *  - We do NOT include OBJECT_CREATION_TIME since it's not applicable to instances
                                */
                               result.put(INSTANCE_IP, new JsonArray());
                           }
                           else if (EMPTY_VALUE.equalsIgnoreCase(instanceType))
                           {
                               /*
                                *  If the object is a monitor (not an instance):
                                *  - We include OBJECT_CREATION_TIME as it's relevant

 instanceType = context.containsKey(INSTANCE_TYPE) ? context.getJsonArray(INSTANCE_TYPE).getString(0) : null;

                        var durations = reply.result().body();

                        StringBuilder builder = null;

                        if (containerTypeReport)
                        {
                            builder = new StringBuilder();

                            result.put(AIOpsObject.OBJECT_GROUPS, new JsonArray());

                            result.put(REASON, new JsonArray());

                            // if the context contains an instance type, and it is not empty and the instance type is present in the configured IP metrics list then add instance ip column in the result else add DISCOVERED TIME column.
                            if (instanceType != null && !instanceType.isEmpty() && NMSConstants.INSTANCE_IP_METRICS.containsKey(instanceType))
                            {
                                /*
                                 *  If the object is an instance:
                                 *  - We need to add INSTANCE_IP as a column in the result
                                 *  - We do NOT include OBJECT_CREATION_TIME since it's not applicable to instances
                                 */
                                result.put(INSTANCE_IP, new JsonArray());
                            }
                            else if (EMPTY_VALUE.equalsIgnoreCase(instanceType))
                            {
                                /*
                                 *  If the object is a monitor (not an instance):
                                 *  - We include OBJECT_CREATION_TIME as it's relevant to monitor creation
                                 *  - We do NOT include INSTANCE_IP as monitors don't have instance IP
                                 */
                                result.put(AIOpsObject.OBJECT_CREATION_TIME, new JsonArray());
                            }

                            context.remove(VisualizationConstants.CONTAINER_TYPE);
                        }

                        if (context.containsKey(INSTANCE_TYPE) && context.getJsonArray(INSTANCE_TYPE).getString(0).equalsIgnoreCase(EMPTY_VALUE))
                        {
                            result.put(APIConstants.Entity.OBJECT.getName().toLowerCase(), new JsonArray()).put(STATUS, new JsonArray()).put(TIME_STAMP, new JsonArray()).put(DURATION, new JsonArray());

                            for (var object : objects) //Entities From the Qualified Entity...
                            {
                                var item = ObjectStatusCacheStore.getStore().getItem(CommonUtil.getLong(object));

                                if (item != null && !context.getString(VisualizationConstants.GROUP_BY).equalsIgnoreCase(VisualizationConstants.GROUP_APP) && context.getJsonArray(STATUS).contains(item.toLowerCase()))
                                {
                                    updateObjectStatus(result, Status.valueOf(item.toUpperCase()), CommonUtil.getLong(object), ObjectStatusCacheStore.getStore().getTimestamp(CommonUtil.getLong(object)), durations.getJsonObject(CommonUtil.getString(object)).getInteger(EMPTY_VALUE, 0), EMPTY_VALUE, context, builder);
                                }
                            }

                        }

                        else
                        {
                            result.put(APIConstants.Entity.OBJECT.getName().toLowerCase(), new JsonArray()).put(STATUS, new JsonArray()).put(context.getString(VisualizationConstants.GROUP_BY) != null && !context.getString(VisualizationConstants.GROUP_BY).isEmpty() ? context.getString(VisualizationConstants.GROUP_BY) : context.getJsonArray(INSTANCE_TYPE).getString(0), new JsonArray()).put(TIME_STAMP, new JsonArray()).put(DURATION, new JsonArray());

                            for (var object : objects) //Entities From the Qualified Entity...
                            {
                                JsonObject apps = null;

                                var items = ObjectStatusCacheStore.getStore().getInstanceItems(CommonUtil.getLong(object), false);

                                if (items != null)
                                {
                                    if (context.getString(VisualizationConstants.GROUP_BY).equalsIgnoreCase(VisualizationConstants.GROUP_APP))
                                    {
                                        apps = MetricConfigStore.getStore().getAppsByObjectId(CommonUtil.getLong(object));
                                    }

                                    for (var entry : items.entrySet())
                                    {
                                        var status = CommonUtil.getString(entry.getValue());

                                        var timestamp = ObjectStatusCacheStore.getStore().getTimestamp(CommonUtil.getLong(object), entry.getKey());

                                        if (apps != null && apps.containsKey(entry.getKey().split(INSTANCE_SEPARATOR)[1]) && context.getJsonArray(STATUS).contains(status.toLowerCase()))
                                        {
                                            updateObjectStatus(result, Status.valueOf(status.toUpperCase()), CommonUtil.getLong(object), timestamp, durations.getJsonObject(CommonUtil.getString(object)).getInteger(entry.getKey(), 0), apps.getString(entry.getKey().split(INSTANCE_SEPARATOR)[1]), context, builder);
                                        }
                                        else if (!context.getString(VisualizationConstants.GROUP_BY).equalsIgnoreCase(VisualizationConstants.GROUP_APP) && context.getJsonArray(VisualizationConstants.INSTANCE_TYPE).contains(entry.getKey().split(INSTANCE_SEPARATOR)[0]) && context.getJsonArray(STATUS).contains(status.toLowerCase()))
                                        {
                                            updateObjectStatus(result, Status.valueOf(status.toUpperCase()), CommonUtil.getLong(object), timestamp, durations.getJsonObject(CommonUtil.getString(object)).getInteger(entry.getKey(), 0), entry.getKey().split(INSTANCE_SEPARATOR)[1], context, builder);
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
                catch (Exception exception)
                {
                    LOGGER.error(exception);
                }

                if (result.isEmpty() || !result.containsKey(STATUS) || result.getJsonArray(STATUS).isEmpty())
                {
                    promise.fail(ErrorMessageConstants.INVALID_NO_DATA_FOUND);
                }
                else
                {
                    promise.complete(result);
                }
            });
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }

        return promise.future();
    }

    /**
     * {@inheritDoc}
     * <p>
     * This implementation executes a blocking operation to retrieve availability status counts
     * grouped by tag or group entities. It iterates through each group/tag, counts the status
     * occurrences for entities within that group/tag, and returns the aggregated results.
     * <p>
     * The result contains status count arrays aligned with entity arrays, allowing for
     * visualization of status distribution across different groups or tags.
     */
    @Override
    public AvailabilityCacheService getGroupByAvailabilityStatus(JsonObject context, Handler<AsyncResult<JsonObject>> handler)
    {
        vertx.<JsonObject>executeBlocking(future ->
                {
                    var result = buildGroupByStatusResult(context);

                    if (!result.isEmpty())
                    {
                        handler.handle(Future.succeededFuture(result));
                    }
                    else
                    {
                        handler.handle(Future.failedFuture(ErrorMessageConstants.INVALID_DATA_SOURCE));
                    }

                    future.complete(result);
                }, false,
                result ->
                {
                    if (result.succeeded())
                    {
                        handler.handle(Future.succeededFuture(result.result()));
                    }
                    else
                    {
                        LOGGER.error(result.cause());

                        handler.handle(Future.failedFuture(result.cause()));
                    }
                });
        return this;
    }

    /**
     * Builds the grouped status count result for availability by group/tag queries.
     * <p>
     * This method iterates through group or tag entities and counts status occurrences
     * for each entity. It supports both object-level and instance-level counting.
     * <p>
     * For instance-level queries (when {@code instance.type} is specified):
     * <ul>
     *   <li>If tag grouping is configured, uses tag entities with plugin IDs</li>
     *   <li>Otherwise, iterates through instance items and counts matching statuses</li>
     * </ul>
     * For object-level queries:
     * <ul>
     *   <li>Directly counts object statuses from the {@link ObjectStatusCacheStore}</li>
     * </ul>
     * <p>
     * Each group/tag produces a partial result that is merged into the final result
     * using the {@link #enrich} method.
     *
     * @param context The context containing query parameters:
     *                <ul>
     *                  <li>{@code group} or {@code tag} - JsonObject mapping entity names to object arrays</li>
     *                  <li>{@code instance.type} - Instance type for instance-level queries (optional)</li>
     *                  <li>{@code status} - JsonArray of status values to count</li>
     *                  <li>{@code plugin.ids} - JsonArray of plugin IDs for tag queries (optional)</li>
     *                </ul>
     * @return A {@link JsonObject} with columnar arrays:
     *         <ul>
     *           <li>Status columns (e.g., {@code up}, {@code down}) - JsonArray of counts per entity</li>
     *           <li>{@code group} or {@code tag} - JsonArray of entity names</li>
     *           <li>{@code group.id} - JsonArray of group IDs (only for group entities)</li>
     *         </ul>
     */
    private JsonObject buildGroupByStatusResult(JsonObject context)
    {
        var result = new JsonObject();

        var entityType = context.containsKey(VisualizationConstants.VisualizationGrouping.GROUP.getName()) ? VisualizationConstants.VisualizationGrouping.GROUP.getName() : VisualizationConstants.VisualizationGrouping.TAG.getName();

        var entities = context.containsKey(VisualizationConstants.VisualizationGrouping.GROUP.getName()) ? context.getJsonObject(VisualizationConstants.VisualizationGrouping.GROUP.getName()) : context.getJsonObject(VisualizationConstants.VisualizationGrouping.TAG.getName());

        var qualifiedEntities = context.getJsonArray(ENTITIES);

        if (context.containsKey(VisualizationConstants.INSTANCE_TYPE) && !context.getString(VisualizationConstants.INSTANCE_TYPE).isEmpty())
        {
            JsonObject filteredTags = null;

            HashSet<Integer> monitors = null;

            HashMap<Integer, HashSet<String>> instances = null;

            if(context.containsKey(VisualizationConstants.VisualizationGrouping.GROUP.getName()) && context.containsKey(VisualizationConstants.VisualizationGrouping.TAG.getName()))
            {
                filteredTags = (JsonObject) context.remove(VisualizationConstants.VisualizationGrouping.TAG.getName());

                monitors = new HashSet<>();

                instances = new HashMap<>();
            }

            if(filteredTags != null)
            {
                for (var tag:filteredTags.getMap().entrySet())
                {
                    for (var entity : (JsonArray) tag.getValue())
                    {
                        var tokens = CommonUtil.getString(entity).split(GROUP_SEPARATOR);

                        monitors.add(CommonUtil.getInteger(tokens[0]));

                        instances.computeIfAbsent(CommonUtil.getInteger(tokens[0]),val -> new HashSet<>()).add(tokens[1]);
                    }
                }
            }

            for (var entrySet:entities.getMap().entrySet())
            {
                var value = (JsonArray) entrySet.getValue();

                var partialResult = new JsonObject();

                for (var index = 0; index < value.size(); index++)
                {
                    if (context.containsKey(VisualizationConstants.VisualizationGrouping.TAG.getName()) && !context.getJsonObject(VisualizationConstants.VisualizationGrouping.TAG.getName()).isEmpty())
                    {
                        var val = value.getString(index);

                        var entityId = ObjectConfigStore.getStore().getIdByObjectId(CommonUtil.getInteger(val.split(GROUP_SEPARATOR)[0]));

                        if (qualifiedEntities.contains(entityId))
                        {
                            var instanceItems = ObjectStatusCacheStore.getStore().getInstanceItems(entityId, false);

                            if (instanceItems != null && !instanceItems.isEmpty())
                            {
                                if (context.containsKey(VisualizationConstants.VisualizationGrouping.TAG.getName()) && !context.getJsonObject(VisualizationConstants.VisualizationGrouping.TAG.getName()).isEmpty())
                                {
                                    for (var pluginId : context.getJsonArray("plugin.ids"))
                                    {
                                        if (instanceItems.containsKey(context.getString(INSTANCE_TYPE) + INSTANCE_SEPARATOR + CommonUtil.getString(val).split(GROUP_SEPARATOR)[1] + INSTANCE_SEPARATOR + pluginId))
                                        {
                                            var status = instanceItems.get(context.getString(INSTANCE_TYPE) + INSTANCE_SEPARATOR + CommonUtil.getString(val).split(GROUP_SEPARATOR)[1] + INSTANCE_SEPARATOR + pluginId).toLowerCase();

                                            if (context.containsKey(STATUS) && context.getJsonArray(STATUS).contains(status))
                                            {
                                                if (partialResult.containsKey(status))
                                                {
                                                    partialResult.put(status, partialResult.getInteger(status) + 1);
                                                }
                                                else
                                                {
                                                    partialResult.put(status, 1);
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                    else
                    {
                        if (monitors != null && !monitors.isEmpty())
                        {
                            if (monitors.contains(value.getInteger(index)))
                            {
                                var instanceSet = instances.get(value.getInteger(index));

                                var entityId = ObjectConfigStore.getStore().getIdByObjectId(value.getInteger(index));

                                if (qualifiedEntities.contains(entityId))
                                {
                                    var instanceItems = ObjectStatusCacheStore.getStore().getInstanceItems(ObjectConfigStore.getStore().getIdByObjectId(value.getInteger(index)), false);

                                    for (var pluginId : context.getJsonArray("plugin.ids"))
                                    {
                                        for (var instance:instanceSet)
                                        {
                                            if (instanceItems.containsKey(context.getString(INSTANCE_TYPE) + INSTANCE_SEPARATOR + instance+ INSTANCE_SEPARATOR + pluginId))
                                            {
                                                var status = instanceItems.get(context.getString(INSTANCE_TYPE) + INSTANCE_SEPARATOR + instance + INSTANCE_SEPARATOR + pluginId).toLowerCase();

                                                if (context.containsKey(STATUS) && context.getJsonArray(STATUS).contains(status))
                                                {
                                                    if (partialResult.containsKey(status))
                                                    {
                                                        partialResult.put(status, partialResult.getInteger(status) + 1);
                                                    }
                                                    else
                                                    {
                                                        partialResult.put(status, 1);
                                                    }
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                        else
                        {
                            var entityId = ObjectConfigStore.getStore().getIdByObjectId(value.getInteger(index));

                            if (qualifiedEntities.contains(entityId))
                            {
                                var instanceItems = ObjectStatusCacheStore.getStore().getInstanceItems(ObjectConfigStore.getStore().getIdByObjectId(value.getInteger(index)), false);

                                if (instanceItems != null && !instanceItems.isEmpty())
                                {
                                    for (var entry : instanceItems.entrySet())
                                    {
                                        var status = CommonUtil.getString(entry.getValue()).toLowerCase();

                                        if (CommonUtil.debugEnabled())
                                        {
                                            LOGGER.debug(String.format("instance : %s , status : %s", entry.getKey(), entry.getValue()));
                                        }

                                        //as key contains instance type so splitting and checking it matches same selected instance with selected status if matches incrementing count
                                        if (entry.getKey().split(INSTANCE_SEPARATOR)[0].equalsIgnoreCase(context.getString(VisualizationConstants.INSTANCE_TYPE)) && context.getJsonArray(STATUS).contains(status))
                                        {
                                            if (partialResult.containsKey(status))
                                            {
                                                partialResult.put(status, partialResult.getInteger(status) + 1);
                                            }
                                            else
                                            {
                                                partialResult.put(status, 1);
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }

                if (!partialResult.isEmpty())
                {
                    enrich(context,partialResult,result,entityType,entrySet.getKey());
                }
            }
        }
        else
        {
            for (var entrySet:entities.getMap().entrySet())
            {
                var value = (JsonArray) entrySet.getValue();

                var partialResult = new JsonObject();

                for (var index = 0; index < value.size(); index++)
                {
                    var entityId = ObjectConfigStore.getStore().getIdByObjectId(value.getInteger(index));

                    if (qualifiedEntities.contains(entityId))
                    {
                        var status = ObjectStatusCacheStore.getStore().getItem(entityId);

                        if (status != null)
                        {
                            status = status.toLowerCase();

                            if (context.getJsonArray(STATUS).contains(status))
                            {
                                if (partialResult.containsKey(status))
                                {
                                    partialResult.put(status, partialResult.getInteger(status) + 1);
                                }
                                else
                                {
                                    partialResult.put(status, 1);
                                }
                            }
                        }
                    }
                }

                if (!partialResult.isEmpty())
                {
                    enrich(context,partialResult,result,entityType,entrySet.getKey());
                }
            }
        }

        return result;
    }

    /**
     * Merges partial group/tag results into the final aggregated result.
     * <p>
     * This method performs the following operations:
     * <ol>
     *   <li>Ensures all requested statuses are present in the partial result (with 0 count if missing)</li>
     *   <li>Appends status counts from partial result to the corresponding arrays in the final result</li>
     *   <li>Adds the entity name (and ID for groups) to the entity type column</li>
     * </ol>
     * <p>
     * For group entities, the entity value is expected to be in the format "groupName::groupId",
     * which is split to populate both the group name and group ID columns. The group ID is
     * included to support drill-down functionality in the UI without requiring additional API calls.
     *
     * @param context      The query context containing the status array for ensuring all statuses are present
     * @param partialResult The status counts for a single group/tag entity
     * @param result       The final result object to merge partial results into
     * @param entityType   The entity type ("group" or "tag") for column naming
     * @param entityValue  The entity identifier (group name::id for groups, tag name for tags)
     */
    private void enrich(JsonObject context, JsonObject partialResult,JsonObject result,String entityType,String entityValue)
    {
        context.getJsonArray(STATUS).stream().filter(status -> !partialResult.containsKey(CommonUtil.getString(status))).forEach(status -> partialResult.put(CommonUtil.getString(status), 0));

        partialResult.getMap().forEach((key, value) ->
        {
            if (result.containsKey(key))
            {
                result.getJsonArray(key).add(value);
            }
            else
            {
                result.put(key, new JsonArray().add(value));
            }
        });

        if (entityType.equalsIgnoreCase(VisualizationConstants.VisualizationGrouping.GROUP.getName()))
        {
            var entityValues = entityValue.split(GROUP_SEPARATOR);

            if (result.containsKey(entityType))
            {
                result.getJsonArray(entityType).add(entityValues[0]);
            }
            else
            {
                result.put(entityType, new JsonArray().add(entityValues[0]));
            }

            //need to send group id to UI as in order for drilldown UI will need group id in filter if not provided than UI will have to fire API of group and will have to 
            // iterate and resolve each row so taken approach of sending it from backend and only for group it is required
            if (result.containsKey(entityType+".id"))
            {
                result.getJsonArray(entityType+".id").add(entityValues[1]);
            }
            else
            {
                result.put(entityType+".id", new JsonArray().add(entityValues[1]));
            }
        }
        else
        {
            if (result.containsKey(entityType))
            {
                result.getJsonArray(entityType).add(entityValue);
            }
            else
            {
                result.put(entityType, new JsonArray().add(entityValue));
            }
        }
    }
