/**
 * TCP log listener verticle. Deployed in two instances:
 * - Instance 1: Plain TCP on port 5140 (default)
 * - Instance 2: TLS on port 5141 (default)
 * Each instance runs on its own worker thread with isolated state (thread-safe).
 */
public class TCPLogListener extends AbstractVerticle
{

    private final Logger logger ;
    private final int port;
    private final boolean processorEnabled;
    private final NetServerOptions serverOptions;
    private boolean streaming = false;

    /**
     * Constructs a TCPLogListener with optional TLS support.
     * Initializes either a plain TCP listener (port 5140) or a TLS-enabled listener (port 5141).
     * Each instance maintains its own logger, port configuration, and server options.
     * The processor enabled flag is read from configuration and applies to all instances.
     * Both configurations enable address/port reuse and TCP keep-alive for stability.
     * TLS instances load certificate and key from server-cert.pem and server-key.pem files.
     * Supports TLSv1.2 and TLSv1.3 protocols for secure connections.
     * @param tlsEnabled true for TLS listener (port 5141), false for plain TCP (port 5140)
     */
    public TCPLogListener(boolean tlsEnabled)
    {
        if(tlsEnabled)
        {
            this.logger = new Logger(TCPLogListener.class, GlobalConstants.MOTADATA_LOG, "TLS TCP Log Listener");
            this.port = MotadataConfigUtil.getTLSTCPPort();
            this.serverOptions = new NetServerOptions()
                    .setReuseAddress(true)
                    .setReusePort(true)
                    .setTcpKeepAlive(true)
                    .setEnabledSecureTransportProtocols(Set.of("TLSv1.2", "TLSv1.3"))
                    .setSsl(true)
                    .setPemKeyCertOptions(new PemKeyCertOptions()
                            .setCertPath(GlobalConstants.CURRENT_DIR + GlobalConstants.PATH_SEPARATOR + "server-cert.pem")
                            .setKeyPath(GlobalConstants.CURRENT_DIR + GlobalConstants.PATH_SEPARATOR + "server-key.pem"));
        }
        else
        {
            this.logger = new Logger(TCPLogListener.class, GlobalConstants.MOTADATA_LOG, "TCP Log Listener");
            this.port = MotadataConfigUtil.getTCPPort();
            this.serverOptions = new NetServerOptions()
                    .setReuseAddress(true)
                    .setReusePort(true)
                    .setTcpKeepAlive(true);
        }

        processorEnabled = MotadataConfigUtil.logProcessorEnabled();
    }

    /**
     * Starts the TCP log listener server and registers event handlers.
     * Creates a TCP server with configured options and sets up connection handlers for incoming logs.
     * Each incoming log message is parsed using newline delimiters and enriched with metadata.
     * Logs are routed to EVENT_LOG_PROCESS or EVENT_LOG based on processor configuration.
     * Supports real-time log streaming when enabled via EVENT_CHANGE_NOTIFICATION messages.
     * Validates logs against license quota (except in EVENT_COLLECTOR mode).
     * Registers a local consumer for START_LOG_TAIL and STOP_LOG_TAIL notifications.
     * Each instance runs on its own worker thread with isolated state (thread-safe).
     * @param promise Completed when server starts successfully, failed if binding fails
     */
    @Override
    public void start(Promise<Void> promise) throws Exception
    {
        vertx.createNetServer(serverOptions).connectHandler(socket ->
        {
            // Log connection information in debug mode
            if (CommonUtil.debugEnabled())
            {
                logger.debug("[TCP] connection from :" + socket.remoteAddress().host() + "->" + socket.remoteAddress().port());
            }

            // Create a record parser that splits incoming data on newline characters
            var parser = RecordParser.newDelimited("\r\n", socket);

            // Also handle plain newlines (without carriage return)
            parser.delimitedMode("\n");

            // Handle connection end event
            parser.endHandler(result ->
            {
                // Close the socket when the connection ends
                socket.close();

                // Log connection closure in debug mode
                if (CommonUtil.debugEnabled())
                {
                    logger.debug("[TCP] connection closed : " + socket.remoteAddress().host() + "->" + socket.remoteAddress().port());
                }

                // Handle exceptions during parsing or processing
            }).exceptionHandler(exception ->
            {
                // Log the exception
                logger.error(exception);

                // Close the socket on error
                socket.close();

                // Handle incoming data packets
            }).handler(packet ->
            {
                // Check if we're in EVENT_COLLECTOR mode or if we have quota available
                if (Bootstrap.bootstrapType() == GlobalConstants.BootstrapType.EVENT_COLLECTOR || Bootstrap.bootstrapType() == GlobalConstants.BootstrapType.EDGE_COLLECTOR || LicenseUtil.updateUsedLogQuota(packet.getBytes().length))
                {
                    // Create a log event object with metadata
                    var event = new JsonObject()
                            .put(EventBusConstants.EVENT_VOLUME_BYTES, packet.getBytes().length)
                            .put(EventBusConstants.EVENT, packet.toString().trim())
                            .put(EventBusConstants.EVENT_SOURCE, socket.remoteAddress().host())
                            .put(LogEngineConstants.RECEIVED_TIMESTAMP, DateTimeUtil.currentSeconds())
                            .put(EVENT_TYPE, EVENT_LOG);

                    // Route the event based on processor configuration
                    if (processorEnabled)
                    {
                        // Send to log processor if enabled
                        vertx.eventBus().send(EVENT_LOG_PROCESS, event);
                    }
                    else
                    {
                        // Send directly to log event handler
                        vertx.eventBus().send(EVENT_LOG, event);
                    }

                    // If streaming is enabled, broadcast the event for real-time monitoring
                    if (streaming)
                    {
                        vertx.eventBus().send(EventBusConstants.EVENT_STREAMING_BROADCAST,
                                new JsonObject()
                                        .put(StreamingEngine.STREAMING_TYPE, StreamingEngine.StreamingType.LOG_TAIL.getName())
                                        .put(EVENT_CONTEXT, event));
                    }

                    // Log detailed trace information if enabled
                    if (CommonUtil.traceEnabled())
                    {
                        logger.trace(String.format("log received from TCP source: %s %s",
                                socket.remoteAddress().host(), CommonUtil.getString(packet)));
                    }
                }
                // If quota is exceeded or in wrong mode, the log is silently dropped
            });

            // Start listening on the configured TCP port
        }).listen( this.port, "0.0.0.0", result ->
        {
            if (result.succeeded())
            {
                logger.info(String.format("LOG listener connected port %s", this.port));

                // Complete the promise to signal successful startup
                promise.complete();
            }
            else
            {
                logger.info(String.format("LOG listener failed to connected : %s ", result.cause()));

                // Fail the promise with the cause
                promise.fail(result.cause());
            }
        });

        // Set up a consumer for change notifications to control streaming behavior
        vertx.eventBus().<JsonObject>localConsumer(EventBusConstants.EVENT_CHANGE_NOTIFICATION, message ->
        {
            // Extract the notification type from the message
            switch (ChangeNotificationType.valueOf(message.body().getString(CHANGE_NOTIFICATION_TYPE)))
            {
                // Enable streaming when a START_LOG_TAIL notification is received
                case START_LOG_TAIL -> streaming = true;

                // Disable streaming when a STOP_LOG_TAIL notification is received
                case STOP_LOG_TAIL -> streaming = false;

                // Ignore other notification types
                default ->
                {
                    // do nothing for other notification types
                }
            }

            // Log any exceptions that occur during message processing
        }).exceptionHandler(logger::error);
    }
}

