package com.mindarray.eventbus;

import com.mindarray.Bootstrap;
import com.mindarray.GlobalConstants;
import com.mindarray.util.Logger;
import io.vertx.core.Future;
import io.vertx.core.Promise;
import io.vertx.core.buffer.Buffer;
import io.vertx.core.datagram.DatagramSocket;
import io.vertx.core.datagram.DatagramSocketOptions;
import io.vertx.core.json.JsonObject;

import java.util.HashMap;
import java.util.Map;
import java.util.TreeMap;
import java.util.function.Consumer;

import static com.mindarray.GlobalConstants.HOST;
import static com.mindarray.GlobalConstants.PORT;

public class UDPServer implements TransportServer
{
    private final JsonObject config;

    private final String eventType;

    private  DatagramSocket server;

    private static final Logger LOGGER = new Logger(UDPServer.class, GlobalConstants.MOTADATA_EVENT_BUS, "UDP Server");

    private final int port;

    private final String host;

    private final Consumer<byte[]> consumer;

    private static final Map<Integer, TreeMap<Short, byte[]>> CHUNKS = new HashMap<>(); // Maps messageId -> list of received chunks

    private static final Map<Integer, Long> CHUNK_TRACKER = new HashMap<>(); // Track message timestamps

    private static final long CHUNK_TIMEOUT_MS = 10000; // 10 seconds timeout

    UDPServer(JsonObject config)
    {
        this.config = config;

        this.eventType = config.getString(EventBusConstants.EVENT_TYPE);

        port = config.getInteger(PORT);

        host = config.getString(HOST);

        consumer = bytes -> Bootstrap.vertx().eventBus().send(eventType, bytes);
    }

    @Override
    public Future<Void> bind()
    {
        var promise = Promise.<Void>promise();

        server = Bootstrap.vertx().createDatagramSocket(new DatagramSocketOptions().setReusePort(true).setReuseAddress(true));

        server.listen(port, host, handler ->
        {
            if (handler.succeeded())
            {
                LOGGER.info(String.format("Server is successfully bind with port %s", port));

                cleanUp();

                promise.complete();
            }
            else
            {
                promise.fail(handler.cause());
            }
        });

        return promise.future();
    }

    private void cleanUp()
    {
        // Check every 10 seconds
        Bootstrap.vertx().setPeriodic(10000, timerId ->
        {
            LOGGER.debug("cleanup timer started ...");

            if (!CHUNKS.isEmpty())
            {
                var iterator = CHUNK_TRACKER.entrySet().iterator();

                while (iterator.hasNext())
                {
                    var entry = iterator.next();

                    if (System.currentTimeMillis() - entry.getValue() > CHUNK_TIMEOUT_MS)
                    {
                        var messageId = entry.getKey();

                        CHUNKS.remove(messageId);

                        iterator.remove();

                        LOGGER.info(String.format("Cleaned up incomplete message %d due to timeout", messageId));
                    }
                }
            }
        });
    }

    @Override
    public void send(String topic, byte[] data)
    {
        server.send(Buffer.buffer(data), port, host);
    }

    @Override
    public Future<Void> receive()
    {
        server.handler(packet -> parseChunk(packet.data(), consumer));

        return Future.succeededFuture();
    }

    @Override
    public Future<Void> close()
    {
        return server.close();
    }

    /**
     * Parses and reassembles chunked UDP messages.
     *
     * Message format:
     * - Bytes 0-3: Message ID (int) - unique identifier for the complete message
     * - Bytes 4-5: Chunk index (short) - position of this chunk in the sequence
     * - Bytes 6-7: Total chunks (short) - total number of chunks for this message
     * - Bytes 8+: Chunk data - actual payload data for this chunk
     *
     * @param buffer The UDP packet buffer containing chunk header and data
     * @param consumer Callback to process the complete reassembled message
     */
    public static void parseChunk(Buffer buffer, Consumer<byte[]> consumer)
    {
        var messageId = buffer.getInt(0);

        var chunkIndex = buffer.getShort(4);

        var totalChunks = buffer.getShort(6);

        var chunkData = buffer.getBytes(8, buffer.length());

        CHUNKS.computeIfAbsent(messageId, val -> new TreeMap<>()).put(chunkIndex, chunkData);

        CHUNK_TRACKER.putIfAbsent(messageId, System.currentTimeMillis());

        // Check if all chunks are received
        if (CHUNKS.get(messageId).size() == totalChunks)
        {
            var message = Buffer.buffer();

            CHUNKS.get(messageId).values().forEach(message::appendBytes);          // Process full message

            if (message.length() > 0)
            {
                consumer.accept(message.getBytes());
            }

            // Clean up
            CHUNKS.remove(messageId);

            CHUNK_TRACKER.remove(messageId);
        }
    }
}

