                                                    .put(MANAGER_UUID,Bootstrap.getRegistrationId()).put(INSTALLATION_MODE,MotadataConfigUtil.getInstallationMode())
                                                    .put(TIME_STAMP, DateTimeUtil.currentSeconds())
                                                    .put(TIME,DateTimeUtil.getScheduledTimestamp(DateTimeUtil.currentMilliSeconds()))
                                                    .put(MESSAGE,"failed to update remote event processor entry in config db. Possible reason " + result.cause())).encodePrettily())));

                            LOGGER.warn(String.format("failed to update remote event processor %s...", event.encodePrettily()));
                        }
                    });
                }
            }
            else
            {
                vertx.eventBus().send(EVENT_AUDIT_WRITE,new JsonObject().put(AUDIT_MODULE,SYSTEM_HEATH).put(AUDIT_OPERATION,VIEW)
                        .put(AUDIT_MESSAGE,String.format(String.format(ENTITY_UPDATED, SYSTEM_HEATH) + GlobalConstants.NEW_LINE +
                                new JsonObject().put("new.prop.value",new JsonObject().mergeIn(event).put(CONFIG,config)
                                        .put(MANAGER_UUID,Bootstrap.getRegistrationId()).put(INSTALLATION_MODE,MotadataConfigUtil.getInstallationMode())
                                        .put(TIME_STAMP, DateTimeUtil.currentSeconds())
