package com.mindarray.eventbus;

import com.mindarray.Bootstrap;
import com.mindarray.GlobalConstants;
import com.mindarray.util.CommonUtil;
import com.mindarray.util.Logger;
import com.mindarray.util.MotadataConfigUtil;
import io.vertx.core.Future;
import io.vertx.core.Promise;
import io.vertx.core.buffer.Buffer;
import io.vertx.core.http.HttpClientOptions;
import io.vertx.core.http.WebSocket;
import io.vertx.core.http.WebSocketConnectOptions;
import io.vertx.core.json.JsonObject;
import io.vertx.core.net.PemTrustOptions;

import java.net.ConnectException;
import java.util.Set;
import java.util.function.Consumer;

import static com.mindarray.GlobalConstants.*;
import static com.mindarray.eventbus.EventBusConstants.EVENT_TOPIC;

/**
 * HttpClient is a Vert.x-based WebSocket transport client implementation
 * that connects to a remote HTTP server's WebSocket endpoint, sends/receives data, and
 * integrates with the Vert.x EventBus for message dispatch.
 *
 * <p>This implementation follows the WebSocket-based approach where the client
 * connects to the server's WebSocket endpoint instead of opening a local HTTP server.
 * This eliminates the need for clients to manage server infrastructure.</p>
 *
 * <p>Key features:</p>
 * <ul>
 *   <li>WebSocket-based communication for bidirectional messaging</li>
 *   <li>Automatic registration with server using event topics</li>
 *   <li>Message framing compatible with other transport implementations</li>
 *   <li>Integration with Vert.x EventBus for message routing</li>
 *   <li>No SSL support (as requested)</li>
 * </ul>
 */
public class HTTPClient implements TransportClient
{

    // HTTP client configuration (host, port, event type, etc.)
    private final JsonObject config;

    // Event type associated with messages for this client
    private final String eventType;

    // The active WebSocket connection to the server
    private WebSocket webSocket;

    // Consumer to handle incoming byte[] messages
    private Consumer<byte[]> consumer;

    // Logger for HTTP client-specific logging
    private static final Logger LOGGER = new Logger(HTTPClient.class, GlobalConstants.MOTADATA_EVENT_BUS, "HTTP Client");

    // Remote event topic (parsed from bootstrap type)
    private final String remoteEventTopic = EventBusConstants.getRemoteEventTopic(Bootstrap.bootstrapType()).split(DOT_SEPARATOR_ESCAPE, 2)[1];

    // WebSocket endpoint path for transport communication
    private static final String WEBSOCKET_ENDPOINT = "/transport/websocket";

    /**
     * Creates a new HttpClient instance with the given configuration.
     *
     * @param config JSON configuration containing host, port, and event type.
     */
    public HTTPClient(JsonObject config)
    {
        this.config = config;

        this.eventType = config.getString(EventBusConstants.EVENT_TYPE);

        consumer = bytes -> Bootstrap.vertx().eventBus().send(eventType, bytes);
    }

    /**
     * Establishes a WebSocket connection to the configured HTTP server.
     * Uses Vert.x WebClient with optimized options.
     *
     * @return Future indicating connection success/failure (never fails for APP manager).
     */
    @Override
    public Future<Void> connect()
    {
        var promise = Promise.<Void>promise();

        var clientOptions = new HttpClientOptions()
                .setMaxWebSocketMessageSize(MotadataConfigUtil.getHTTPBufferSizeBytes())
                .setSsl(MotadataConfigUtil.httpsEnabled());

        var webSocketConnectOptions = new WebSocketConnectOptions()
                .setHost(config.getString(HOST))
                .setPort(config.getInteger(PORT))
                .setIdleTimeout(MotadataConfigUtil.getHTTPIdleTimeoutSeconds() * 1000L)
                .setURI(WEBSOCKET_ENDPOINT)
                .setConnectTimeout(MotadataConfigUtil.getHTTPConnectionTimeoutSeconds())
                .setSsl(MotadataConfigUtil.httpSslEnabled());

        if (MotadataConfigUtil.httpSslEnabled())
        {
            clientOptions.setTrustAll(false).setVerifyHost(false).setUseAlpn(true)
                    .setEnabledSecureTransportProtocols(Set.of("TLSv1.2", "TLSv1.3"))
                    .setTrustOptions(new PemTrustOptions().addCertPath(GlobalConstants.CURRENT_DIR + GlobalConstants.PATH_SEPARATOR + "server-cert.pem"));
        }

        Bootstrap.vertx().createHttpClient(clientOptions).webSocket(webSocketConnectOptions)
                .onComplete(handler ->
                {
                    try
                    {
                        if (handler.succeeded())
                        {
                            webSocket = handler.result();

                            webSocket.writeTextMessage(new JsonObject().put(EVENT_TOPIC, EventBusConstants.getRemoteEventTopic(Bootstrap.bootstrapType())).encode());

                            LOGGER.info(String.format("%s HTTP client is successfully connected with WebSocket to %s:%s", Bootstrap.bootstrapType(), config.getString(HOST), config.getInteger(PORT)));

                            promise.complete();
                        }
                        else
                        {
                            LOGGER.warn(String.format("%s error while connecting to address %s:%s  reason : %s ", Bootstrap.bootstrapType(),config.getString(HOST),config.getInteger(PORT),handler.cause()));

                            // For APP manager: do not fail the promise, if connection fails.otherwise app won't start
                            if (Bootstrap.bootstrapType() == BootstrapType.MANAGER
                                    && MotadataConfigUtil.getSystemBootstrapType().equalsIgnoreCase(BootstrapType.APP.name())
                                    && handler.cause() instanceof ConnectException)
                            {
                                promise.complete();
                            }
                            else
                            {
                                promise.fail(handler.cause());
                            }
                        }

                    } catch (Exception exception)
                    {
                        LOGGER.warn(String.format("%s error while connecting to address %s:%s  reason : %s ", Bootstrap.bootstrapType(),config.getString(HOST),config.getInteger(PORT),exception.getMessage()));

                        LOGGER.error(exception);

                        promise.fail(exception);
                    }
                });

        return promise.future();
    }

    /**
     * Sends a message (byte[]) over the WebSocket connection.
     * Sends as binary WebSocket frame for efficient transport.
     *
     * @param bytes The byte array to send.
     */
    @Override
    public void send(byte[] bytes)
    {
        try
        {
            if (webSocket != null)
            {
                webSocket.writeBinaryMessage(Buffer.buffer(bytes));

                if (CommonUtil.traceEnabled())
                {
                    LOGGER.trace(String.format("%s sending data to address: %s:%s ", Bootstrap.bootstrapType(), config.getString(HOST),config.getInteger(PORT)));
                }
            }
        }
        catch (Exception exception)
        {
            LOGGER.warn(String.format("error occurred while sending in %s to address : %s:%s ",Bootstrap.bootstrapType(),config.getString(HOST),config.getInteger(PORT)));

            LOGGER.error(exception);
        }
    }

    /**
     * Sets up WebSocket message handlers for incoming messages.
     * Handles both text (registration) and binary (data) messages.
     *
     * @return A succeeded Future since setup is synchronous.
     */
    @Override
    public Future<Void> receive()
    {
        if (webSocket != null)
        {
            webSocket.binaryMessageHandler(buffer ->
            {
                try
                {
                    if (buffer != null && buffer.length() > 0)
                    {
                        consumer.accept(Buffer.buffer()
                                .appendShortLE(CommonUtil.getShort(remoteEventTopic.getBytes().length))
                                .appendBytes(remoteEventTopic.getBytes())
                                .appendBytes(buffer.getBytes())
                                .getBytes());

                        if (CommonUtil.traceEnabled())
                        {
                            LOGGER.trace(String.format("%s received bytes of length: %s via WebSocket at port: %s ", Bootstrap.bootstrapType(), buffer.length(), config.getInteger(PORT)));
                        }
                    }
                }
                catch (Exception exception)
                {
                    LOGGER.warn(String.format("error occurred in %s while processing message for address : %s:%s", Bootstrap.bootstrapType(),config.getString(HOST),config.getInteger(PORT)));

                    LOGGER.error(exception);
                }
            });

            webSocket.closeHandler(close -> LOGGER.info(String.format("%s WebSocket connection closed in port %s ", Bootstrap.bootstrapType(),config.getInteger(PORT))));

            webSocket.exceptionHandler(exception ->
            {
                LOGGER.warn(String.format("%s WebSocket exception in port : %s ", Bootstrap.bootstrapType(),config.getInteger(PORT)));

                LOGGER.error(exception);
            });
        }

        return Future.succeededFuture();
    }

    /**
     * Registers a custom handler for incoming byte[] messages.
     *
     * @param handler A Consumer that will process incoming messages.
     */
    @Override
    public void registerMessageHandler(Consumer<byte[]> handler)
    {
        this.consumer = handler;
    }

    /**
     * Closes the WebSocket connection if open.
     *
     * @return Future that completes when the WebSocket is closed.
     */
    @Override
    public Future<Void> close()
    {
        try
        {
            LOGGER.info(String.format("%s port: %s event.type: %s is closed ...", Bootstrap.bootstrapType(), config.getInteger(PORT), eventType));

            if (webSocket != null)
            {
                return webSocket.close();
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }

        return Future.succeededFuture();
    }
}

