package com.mindarray.eventbus;

import com.mindarray.Bootstrap;
import com.mindarray.GlobalConstants;
import com.mindarray.datastore.DatastoreConstants;
import com.mindarray.util.*;
import io.vertx.core.Future;
import io.vertx.core.Promise;
import io.vertx.core.buffer.Buffer;
import io.vertx.core.json.JsonObject;
import io.vertx.core.net.NetServer;
import io.vertx.core.net.NetServerOptions;
import io.vertx.core.net.NetSocket;
import io.vertx.core.net.PemKeyCertOptions;
import io.vertx.core.parsetools.RecordParser;

import java.util.*;

import static com.mindarray.GlobalConstants.*;
import static com.mindarray.eventbus.EventBusConstants.*;

/**
 * TCPServer is a Vert.x-based server implementation for handling TCP connections.
 * It supports client registration by event topic, message sending with round-robin load balancing,
 * receiving messages, and sending periodic keep-alive signals to connected clients.
 */
public class TCPServer implements TransportServer
{
    // TCP server configuration (host, port, event type, etc.)
    private final JsonObject config;

    // Event type associated with this TCP server
    private final String eventType;

    // Vert.x NetServer instance
    private NetServer server;

    // Logger instance for TCP server
    private static final Logger LOGGER = new Logger(TCPServer.class, GlobalConstants.MOTADATA_EVENT_BUS, "TCP Server");

    // Map of event topic → list of connected sockets
    private final Map<String, List<NetSocket>> connections = new HashMap<>();

    // Round-robin index for each topic
    private final Map<String, Integer> indexes = new HashMap<>();

    // Timer ID for keep-alive scheduling
    private long timer;

    /**
     * Constructs a TCPServer instance with the given configuration.
     *
     * @param config JSON configuration containing server details like port and event type.
     */
    public TCPServer(JsonObject config)
    {
        this.config = config;

        this.eventType = config.getString(EVENT_TYPE);
    }

    /**
     * Binds the TCP server to the configured port and starts listening for client connections.
     *
     * @return a Future that completes when the server successfully binds.
     */
    @Override
    public Future<Void> bind()
    {
        var promise = Promise.<Void>promise();

        var serverOptions = new NetServerOptions()
                .setReuseAddress(true)
                .setReusePort(true)
                .setTcpFastOpen(true)
                .setTcpKeepAlive(true)
                .setTcpNoDelay(true)
                .setSendBufferSize(MotadataConfigUtil.getTCPBufferSizeBytes())
                .setReceiveBufferSize(MotadataConfigUtil.getTCPBufferSizeBytes());

        if (MotadataConfigUtil.tcpSslEnabled())
        {
            serverOptions.setSsl(true)
                    .setEnabledSecureTransportProtocols(Set.of("TLSv1.2", "TLSv1.3"))
                    .setKeyCertOptions(new PemKeyCertOptions().setCertPath(GlobalConstants.CURRENT_DIR + GlobalConstants.PATH_SEPARATOR + "server-cert.pem")
                            .setKeyPath(GlobalConstants.CURRENT_DIR + GlobalConstants.PATH_SEPARATOR + "server-key.pem"));
        }

        server = Bootstrap.vertx().createNetServer(serverOptions);

        recv();

        server.listen(config.getInteger(PORT))
                .onComplete(handler ->
                {
                    if (handler.succeeded())
                    {
                        LOGGER.info(String.format("server is successfully opened with port %s", config.getInteger(PORT)));

                        promise.complete();
                    }
                    else
                    {
                        LOGGER.error(handler.cause());

                        promise.fail(handler.cause());
                    }
                });

        return promise.future();
    }

    /**
     * Sends data to a specific client group identified by UUID.
     * If multiple sockets exist for the same UUID, round-robin delivery is used.
     *
     * @param topic the identifier for the client/topic group.
     * @param data the data to send as byte array.
     */
    @Override
    public void send(String topic, byte[] data)
    {
        try
        {
            var sockets = connections.get(topic);

            if (sockets != null)
            {
                var size = sockets.size();

                // Round-robin selection for multiple sockets from the same client/topic. generally in EVENT_PROCESSOR's Log parser
                var index = indexes.getOrDefault(topic, 0);

                sockets.get(index % size).write(Buffer.buffer(data).appendString(VALUE_SEPARATOR_WITH_ESCAPE));

                indexes.put(topic, (index + 1) % size);

                if (CommonUtil.traceEnabled())
                {
                    LOGGER.trace(String.format("sending data to : %s to port : %s ",topic,config.getInteger(PORT)));
                }
            }
        }
        catch (Exception exception)
        {
            LOGGER.warn(String.format("error occurred while sending in %s for topic : %s ",Bootstrap.bootstrapType(),topic));

            LOGGER.error(exception);
        }
    }

    /**
     * Configures server to accept new client connections and sets up message receiving handlers.
     * Also initializes periodic keep-alive messaging.
     *
     * @return a succeeded Future once configuration is applied.
     */
    public Future<Void> recv()
    {
        connections.clear();

        server.connectHandler(socket ->
        {
            var remote = socket.remoteAddress();

            LOGGER.info(String.format("client is connected to server with address %s:%s at port : %s", remote.host(),remote.port(),config.getInteger(PORT)));

            socket.handler(buffer ->
            {
                if (buffer != null && buffer.length() > 0)
                {
                    var event = buffer.toJsonObject();

                    connections.computeIfAbsent(event.getString(EVENT_TOPIC, EMPTY_VALUE), key -> new ArrayList<>()).add(socket);

                    LOGGER.info(String.format("client registered with topic %s at port : %s ", event.getString(EVENT_TOPIC),config.getInteger(PORT)));

                    RecordParser.newDelimited(VALUE_SEPARATOR_WITH_ESCAPE,socket).handler(message ->
                    {
                        if (message != null && message.length() > 0)
                        {
                            Bootstrap.vertx().eventBus().send(eventType,message.getBytes());

                            if (CommonUtil.traceEnabled())
                            {
                                LOGGER.trace(String.format("%s receiving data at port : %s ", Bootstrap.bootstrapType(),config.getInteger(PORT)));
                            }
                        }
                    });
                }
            });

            socket.closeHandler(close ->
            {
                LOGGER.debug(String.format("client is closed with address %s at port : %s ", remote.host() + ":" + remote.port(),config.getInteger(PORT)));

                connections.forEach((topic, sockets) ->
                {
                    LOGGER.debug(String.format("client is closed with topic : %s ", topic));

                    sockets.remove(socket);
                });

                connections.entrySet().removeIf(entry ->
                {
                    if (entry.getValue().isEmpty())
                    {
                        indexes.remove(entry.getKey());
                    }

                    return entry.getValue().isEmpty();
                });
            });

        }).exceptionHandler(throwable -> LOGGER.error(throwable.getCause()));

        keepAliveConnection();

        return Future.succeededFuture();
    }

    /**
     * Sends periodic keep-alive messages to all connected clients.
     * Manager clients receive a heartbeat event, others receive an encrypted keep-alive payload.
     */
    private void keepAliveConnection()
    {
        Bootstrap.vertx().cancelTimer(timer);

        var buffer = Buffer.buffer().appendBytes(new CipherUtil().encrypt(CodecUtil.compress(new JsonObject().put(EVENT_TYPE, DatastoreConstants.OperationType.CONNECTION_KEEP_ALIVE.name()).encode())));

        var event = Buffer.buffer(new JsonObject().put(EVENT_TYPE,EVENT_MOTADATA_MANAGER_HEARTBEAT).encode());

        timer = Bootstrap.vertx().setPeriodic(MotadataConfigUtil.getKeepAliveTimerSeconds() * 1000L, timerId ->
        {
            for (var entry : connections.entrySet())
            {
                for (var socket : entry.getValue())
                {
                    if (entry.getKey().contains(MOTADATA_MANAGER_TOPIC))
                    {
                        socket.write(event.appendString(VALUE_SEPARATOR_WITH_ESCAPE));
                    }
                    else
                    {
                        socket.write(buffer.appendString(VALUE_SEPARATOR_WITH_ESCAPE));
                    }

                    if (CommonUtil.traceEnabled())
                    {
                        LOGGER.trace(String.format("sending keep alive from : %s to %s ", config.getInteger(PORT),entry.getKey()));
                    }
                }
            }
        });
    }

    /**
     * Empty implementation to satisfy interface; TCPServer handles receiving in recv().
     */
    @Override
    public Future<Void> receive()
    {
        return Future.succeededFuture();
    }

    /**
     * Stops the TCP server, closes all connections, and cancels keep-alive timer.
     *
     * @return a Future that completes when the server is closed.
     */
    @Override
    public Future<Void> close()
    {
        try
        {
            Bootstrap.vertx().cancelTimer(timer);

            LOGGER.info(String.format("%s server is closed ... event type : %s port : %s ", Bootstrap.bootstrapType(),eventType,config.getInteger(PORT)));

            if (server != null)
            {
                return server.close();
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }

        return Future.succeededFuture();
    }
}

