package com.mindarray.eventbus;

import com.mindarray.Bootstrap;
import com.mindarray.GlobalConstants;
import com.mindarray.util.Logger;
import io.vertx.core.Future;
import io.vertx.core.buffer.Buffer;
import io.vertx.core.datagram.DatagramSocket;
import io.vertx.core.datagram.DatagramSocketOptions;
import io.vertx.core.json.JsonObject;

import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.function.Consumer;

import static com.mindarray.GlobalConstants.HOST;
import static com.mindarray.GlobalConstants.PORT;

public class UDPClient implements TransportClient
{
    private final JsonObject config;

    private final String eventType;

    private DatagramSocket client;

    private static final Logger LOGGER = new Logger(UDPClient.class, GlobalConstants.MOTADATA_EVENT_BUS, "UDP Client");

    private static final AtomicInteger COUNTER = new AtomicInteger(0);

    private Consumer<byte[]> consumer;

    private static final int CHUNK_SIZE = 1400; // Should be <= MTU - header

    private final int port;

    private final String host;

    UDPClient(JsonObject config)
    {
        this.config = config;

        this.eventType = config.getString(EventBusConstants.EVENT_TYPE);

        port = config.getInteger(PORT);

        host = config.getString(HOST);

        consumer = bytes -> Bootstrap.vertx().eventBus().send(eventType, bytes);
    }

    @Override
    public Future<Void> connect()
    {
        client = Bootstrap.vertx().createDatagramSocket(new DatagramSocketOptions().setReusePort(true).setReuseAddress(true));


        return Future.succeededFuture();
    }

    @Override
    public void send(byte[] data)
    {
        var chunks = createChunks(data);

        for (var chunk : chunks)
        {
            client.send(chunk, port, host, response ->
            {
                if (response.failed())
                {
                    LOGGER.info("Failed to send chunk");
                }
            });
        }
    }

    @Override
    public Future<Void> receive()
    {
        return Future.succeededFuture();
    }

    /**
     * @param consumer
     */
    @Override
    public void registerMessageHandler(Consumer<byte[]> consumer)
    {
        this.consumer = consumer;
    }

    @Override
    public Future<Void> close()
    {
        return client.close();
    }

    /**
     * Splits large data into smaller UDP-friendly chunks with reassembly headers.
     *
     * Each chunk contains an 8-byte header followed by payload data:
     * - Bytes 0-3: Message ID (int) - unique identifier for reassembly
     * - Bytes 4-5: Chunk index (short) - position of this chunk (0-based)
     * - Bytes 6-7: Total chunks (short) - total number of chunks in message
     * - Bytes 8+: Chunk payload - actual data fragment
     *
     * @param data The original data to be chunked
     * @return List of Buffer objects, each containing a chunk with header
     */
    public static List<Buffer> createChunks(byte[] data)
    {
        var totalChunks = (int) Math.ceil((double) data.length / CHUNK_SIZE);

        var messageId = COUNTER.getAndIncrement(); // You can use a custom ID if needed

        var chunks = new ArrayList<Buffer>(totalChunks);

        for (var i = 0; i < totalChunks; i++)
        {
            var start = i * CHUNK_SIZE;

            var end = Math.min(start + CHUNK_SIZE, data.length);

            var chunk = new byte[end - start];

            System.arraycopy(data, start, chunk, 0, chunk.length);

            var buffer = Buffer.buffer(8 + end - start);               // header + payloadSize

            buffer.appendInt(messageId);     // 4 bytes

            buffer.appendShort((short) i);   // 2 bytes: chunk index

            buffer.appendShort((short) totalChunks); // 2 bytes: total chunks

            buffer.appendBytes(chunk);       // payload

            chunks.add(buffer);
        }

        return chunks;
    }
}

