package com.mindarray.eventbus;

import com.mindarray.Bootstrap;
import com.mindarray.GlobalConstants;
import com.mindarray.datastore.DatastoreConstants;
import com.mindarray.util.*;
import io.vertx.core.Future;
import io.vertx.core.Promise;
import io.vertx.core.buffer.Buffer;
import io.vertx.core.http.HttpServer;
import io.vertx.core.http.HttpServerOptions;
import io.vertx.core.http.ServerWebSocket;
import io.vertx.core.json.JsonObject;
import io.vertx.core.net.PemKeyCertOptions;

import java.util.*;

import static com.mindarray.GlobalConstants.EMPTY_VALUE;
import static com.mindarray.GlobalConstants.PORT;
import static com.mindarray.eventbus.EventBusConstants.*;

/**
 * HttpServer is a Vert.x-based HTTP server implementation with direct WebSocket transport support.
 * It uses the webSocketHandler approach where any HTTP request can be upgraded to WebSocket,
 * eliminating the need for clients to open local HTTP servers.
 *
 * <p>This implementation follows the direct WebSocket approach where:</p>
 * <ul>
 *   <li>Server accepts WebSocket upgrades on any HTTP request</li>
 *   <li>Clients connect using WebSocket protocol directly</li>
 *   <li>Bidirectional communication over WebSocket connections</li>
 *   <li>Client registration by event topic</li>
 *   <li>Message sending with round-robin load balancing</li>
 *   <li>Periodic keep-alive signals to connected clients</li>
 * </ul>
 *
 * <p>Key features:</p>
 * <ul>
 *   <li>Direct WebSocket handler for simple setup</li>
 *   <li>Topic-based client registration and message routing</li>
 *   <li>Round-robin load balancing for multiple clients on same topic</li>
 *   <li>Automatic keep-alive mechanism</li>
 *   <li>No SSL support (as requested)</li>
 *   <li>Integration with Vert.x EventBus</li>
 * </ul>
 */
public class HTTPServer implements TransportServer
{
    // HTTP server configuration (host, port, event type, etc.)
    private final JsonObject config;

    // Event type associated with this HTTP server
    private final String eventType;

    // Vert.x HttpServer instance
    private HttpServer server;

    // Logger instance for HTTP server
    private static final Logger LOGGER = new Logger(HttpServer.class, GlobalConstants.MOTADATA_EVENT_BUS, "HTTP Server");

    // Map of event topic → list of connected WebSocket connections
    private final Map<String, List<ServerWebSocket>> connections = new HashMap<>();

    // Round-robin index for each topic
    private final Map<String, Integer> indexes = new HashMap<>();

    // Timer ID for keep-alive scheduling
    private long timer;

    /**
     * Constructs an HttpServer instance with the given configuration.
     *
     * @param config JSON configuration containing server details like port and event type.
     */
    public HTTPServer(JsonObject config)
    {
        this.config = config;

        this.eventType = config.getString(EVENT_TYPE);
    }

    /**
     * Binds the HTTP server to the configured port and starts listening for WebSocket connections.
     * Uses direct webSocketHandler approach for simplicity.
     *
     * @return a Future that completes when the server successfully binds.
     */
    @Override
    public Future<Void> bind()
    {
        var promise = Promise.<Void>promise();

        var options = new HttpServerOptions()
                .setReuseAddress(true)
                .setReusePort(true)
                .setTcpKeepAlive(true)
                .setTcpNoDelay(true)
                .setSendBufferSize(MotadataConfigUtil.getHTTPBufferSizeBytes())
                .setReceiveBufferSize(MotadataConfigUtil.getHTTPBufferSizeBytes())
                .setCompressionSupported(true)
                .setMaxWebSocketMessageSize(MotadataConfigUtil.getHTTPBufferSizeBytes())
                .setAcceptBacklog(MotadataConfigUtil.getWebSocketBacklogQueueSize())
                .setIdleTimeout(MotadataConfigUtil.getHTTPIdleTimeoutSeconds())
                .setSsl(MotadataConfigUtil.httpSslEnabled());

        if (MotadataConfigUtil.httpSslEnabled())
        {
            options.setSsl(true).setUseAlpn(true).setEnabledSecureTransportProtocols(Set.of("TLSv1.2", "TLSv1.3"))
                .setKeyCertOptions(new PemKeyCertOptions().setCertPath(GlobalConstants.CURRENT_DIR + GlobalConstants.PATH_SEPARATOR + "server-cert.pem")
                        .setKeyPath(GlobalConstants.CURRENT_DIR + GlobalConstants.PATH_SEPARATOR + "server-key.pem"));
        }

        server = Bootstrap.vertx().createHttpServer(options);

        recv();

        server.listen(config.getInteger(PORT))
                .onComplete(handler ->
                {
                    if (handler.succeeded())
                    {
                        LOGGER.info(String.format("%s HTTP server with WebSocket opened on port %s",Bootstrap.bootstrapType(), config.getInteger(PORT)));

                        promise.complete();
                    }
                    else
                    {
                        LOGGER.warn(String.format("%s failed to listen on port %s",Bootstrap.bootstrapType(),config.getInteger(PORT)));

                        LOGGER.error(handler.cause());

                        promise.fail(handler.cause());
                    }
                });

        return promise.future();
    }

    /**
     * Configures the HTTP server to handle WebSocket connections and sets up message processing handlers.
     * This method establishes the core WebSocket communication infrastructure for the server.
     *
     * <p>This method performs the following operations:</p>
     * <ul>
     *   <li>Sets up WebSocket connection handler for incoming client connections</li>
     *   <li>Configures binary message handler for processing data messages</li>
     *   <li>Configures text message handler for client registration</li>
     *   <li>Sets up connection cleanup handlers for graceful disconnection</li>
     *   <li>Initializes periodic keep-alive mechanism</li>
     * </ul>
     *
     * <p><b>WebSocket Handlers:</b></p>
     * <ul>
     *   <li><b>Connection Handler:</b> Logs new client connections and sets up per-connection handlers</li>
     *   <li><b>Binary Message Handler:</b> Processes incoming data messages and forwards them to the event bus</li>
     *   <li><b>Text Message Handler:</b> Handles client registration messages containing event topics</li>
     *   <li><b>Close Handler:</b> Manages connection cleanup and removes clients from topic mappings</li>
     *   <li><b>Exception Handler:</b> Logs WebSocket-related exceptions for debugging</li>
     * </ul>
     *
     * <p><b>Message Processing:</b></p>
     * <ul>
     *   <li>Binary messages are forwarded directly to the Vert.x event bus under the configured event type</li>
     *   <li>Text messages are parsed as JSON to extract event topic for client registration</li>
     *   <li>All message processing includes proper error handling and logging</li>
     * </ul>
     *
     * <p><b>Connection Management:</b></p>
     * <ul>
     *   <li>Maintains a mapping of event topics to connected WebSocket clients</li>
     *   <li>Automatically removes disconnected clients from topic mappings</li>
     *   <li>Cleans up round-robin indexes when topic groups become empty</li>
     * </ul>
     *
     * <p>This method is called internally during server binding and should not be invoked directly.</p>
     *
     * @see #bind()
     * @see #keepAliveConnection()
     * @see #send(String, byte[])
     */
    private void recv()
    {
        server.webSocketHandler(webSocket ->
        {
            var remote = webSocket.remoteAddress();

            LOGGER.info(String.format("WebSocket client connected to HTTP server from address %s:%s at port: %s", remote.host(), remote.port(), config.getInteger(PORT)));

            webSocket.binaryMessageHandler(buffer ->
            {
                try
                {
                    if (buffer != null && buffer.length() > 0)
                    {
                        Bootstrap.vertx().eventBus().send(eventType, buffer.getBytes());

                        if (CommonUtil.traceEnabled())
                        {
                            LOGGER.trace(String.format("%s received binary data of length: %s at port: %s ", Bootstrap.bootstrapType(), buffer.length(), config.getInteger(PORT)));
                        }
                    }
                }
                catch (Exception exception)
                {
                    LOGGER.warn(String.format("%s error occurred while processing binary message in port %s", Bootstrap.bootstrapType(),config.getInteger(PORT)));

                    LOGGER.error(exception);
                }
            });

            webSocket.textMessageHandler(message ->
            {
                try
                {
                    var event = new JsonObject(message);

                    LOGGER.info(String.format("client registered with event %s at port %s", event.encode(), config.getInteger(PORT)));

                    connections.computeIfAbsent(event.getString(EVENT_TOPIC, EMPTY_VALUE), key -> new ArrayList<>()).add(webSocket);
                }
                catch (Exception exception)
                {
                    LOGGER.warn(String.format("%s error occurred while processing text message in port %s", Bootstrap.bootstrapType(),config.getInteger(PORT)));

                    LOGGER.error(exception);
                }
            });

            webSocket.closeHandler(close ->
            {
                LOGGER.debug(String.format("WebSocket client closed connection from address %s at port: %s ", remote.host() + ":" + remote.port(), config.getInteger(PORT)));

                connections.forEach((topic, webSockets) ->
                {
                    LOGGER.debug(String.format("WebSocket client closed with topic: %s ", topic));

                    webSockets.remove(webSocket);
                });

                connections.entrySet().removeIf(entry ->
                {
                    if (entry.getValue().isEmpty())
                    {
                        indexes.remove(entry.getKey());
                    }

                    return entry.getValue().isEmpty();
                });
            });

            webSocket.exceptionHandler(exception ->
            {
                LOGGER.warn(String.format("%s WebSocket exception from %s:%s",Bootstrap.bootstrapType(),remote.host(), remote.port()));

                LOGGER.error(exception);
            });
        });

        keepAliveConnection();
    }

    /**
     * Sends periodic keep-alive messages to all connected clients.
     * Manager clients receive a heartbeat event, others receive an encrypted keep-alive payload.
     */
    private void keepAliveConnection()
    {
        Bootstrap.vertx().cancelTimer(timer);

        var buffer = Buffer.buffer().appendBytes(new CipherUtil().encrypt(CodecUtil.compress(new JsonObject().put(EVENT_TYPE, DatastoreConstants.OperationType.CONNECTION_KEEP_ALIVE.name()).encode())));

        var event = Buffer.buffer(new JsonObject().put(EVENT_TYPE,EVENT_MOTADATA_MANAGER_HEARTBEAT).encode());

        timer = Bootstrap.vertx().setPeriodic(MotadataConfigUtil.getKeepAliveTimerSeconds() * 1000L, timerId ->
        {
            for (var entry : connections.entrySet())
            {
                for (var socket : entry.getValue())
                {
                    if (entry.getKey().contains(MOTADATA_MANAGER_TOPIC))
                    {
                        socket.writeBinaryMessage(event);
                    }
                    else
                    {
                        socket.writeBinaryMessage(buffer);
                    }

                    if (CommonUtil.traceEnabled())
                    {
                        LOGGER.trace(String.format("%s sending keep alive from port %s to %s ", Bootstrap.bootstrapType(),config.getInteger(PORT),entry.getKey()));
                    }
                }
            }
        });
    }


    /**
     * Sends data to a specific client group identified by UUID.
     * If multiple WebSocket connections exist for the same UUID, round-robin delivery is used.
     *
     * @param topic the identifier for the client/topic group.
     * @param data the data to send as byte array.
     */
    @Override
    public void send(String topic, byte[] data)
    {
        try
        {
            var webSockets = connections.get(topic);

            if (webSockets != null)
            {
                var size = webSockets.size();

                var index = indexes.getOrDefault(topic, 0);

                webSockets.get(index % size).writeBinaryMessage(Buffer.buffer(data));

                indexes.put(topic, (index + 1) % size);

                if (CommonUtil.traceEnabled())
                {
                    LOGGER.trace(String.format("%s sending data to: %s from port: %s ",Bootstrap.bootstrapType(), topic, config.getInteger(PORT)));
                }
            }
        }
        catch (Exception exception)
        {
            LOGGER.warn(String.format("error occurred while sending in %s for topic : %s ",Bootstrap.bootstrapType(),topic));

            LOGGER.error(exception);
        }
    }

    /**
     * Starts asynchronous message reception from connected clients.
     *
     * <p>This method initiates the message receiving process, which typically runs
     * in a separate thread or event loop. Received messages are processed according
     * to the server implementation, which may include:</p>
     * <ul>
     *   <li>Forwarding messages to the Vert.x event bus</li>
     *   <li>Invoking registered message handlers</li>
     *   <li>Storing messages for later processing</li>
     *   <li>Filtering or transforming messages</li>
     * </ul>
     *
     * <p><b>Asynchronous Operation:</b></p>
     * <ul>
     *   <li>This method returns immediately after starting the receive operation</li>
     *   <li>Message reception continues until the server is closed</li>
     *   <li>Received messages are processed asynchronously</li>
     * </ul>
     *
     * <p><b>Error Handling:</b></p>
     * <ul>
     *   <li>Reception errors should be logged but should not stop the receive loop</li>
     *   <li>Critical errors may be reported through the returned Future</li>
     *   <li>Connection failures should trigger appropriate recovery mechanisms</li>
     * </ul>
     *
     * <p>Example usage:</p>
     * <pre>{@code
     * server.bind().onSuccess(v -> {
     *     // Start receiving messages
     *     server.receive().onSuccess(v2 -> {
     *         logger.info("Message reception started");
     *     }).onFailure(error -> {
     *         logger.error("Failed to start message reception", error);
     *     });
     * });
     * }</pre>
     *
     * @return a Future that completes successfully when message reception is started,
     * or fails with an exception if reception cannot be started
     * @throws IllegalStateException if the server is not bound or reception is already active
     * @see #bind()
     * @see #send(String, byte[])
     * @see #close()
     */
    @Override
    public Future<Void> receive()
    {
        return Future.succeededFuture();
    }

    /**
     * Closes the server and releases all associated resources.
     *
     * <p>This method performs a clean shutdown of the server, which typically includes:</p>
     * <ul>
     *   <li>Stopping message reception</li>
     *   <li>Closing network connections</li>
     *   <li>Releasing socket and other system resources</li>
     *   <li>Terminating background threads</li>
     * </ul>
     *
     * <p><b>Synchronous Operation:</b></p>
     * <ul>
     *   <li>This method is synchronous and blocks until the server is fully closed</li>
     *   <li>All pending operations should be completed or aborted</li>
     *   <li>Resources should be released even if errors occur during shutdown</li>
     * </ul>
     *
     * <p><b>Thread Safety:</b></p>
     * <ul>
     *   <li>This method can be called from any thread</li>
     *   <li>Multiple concurrent calls should be handled safely (idempotent operation)</li>
     *   <li>After closing, the server cannot be reused; a new instance must be created</li>
     * </ul>
     *
     * <p>Example usage:</p>
     * <pre>{@code
     * // Shutdown hook or application termination
     * Runtime.getRuntime().addShutdownHook(new Thread(() -> {
     *     logger.info("Shutting down server");
     *     server.close();
     * }));
     *
     * // Explicit shutdown
     * void shutdown() {
     *     server.close();
     *     logger.info("Server closed");
     * }
     * }</pre>
     *
     * @throws IllegalStateException if the server is already closed
     * @see #bind()
     * @see #receive()
     */
    @Override
    public Future<Void> close()
    {
        try
        {
            Bootstrap.vertx().cancelTimer(timer);

            LOGGER.info(String.format("%s server is closed ... event type : %s port : %s ", Bootstrap.bootstrapType(),eventType,config.getInteger(PORT)));

            if (server != null)
            {
                return server.close();
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }

        return Future.succeededFuture();
    }
}

