package com.mindarray.eventbus;

import com.mindarray.Bootstrap;
import com.mindarray.GlobalConstants;
import com.mindarray.util.CommonUtil;
import com.mindarray.util.Logger;
import com.mindarray.util.MotadataConfigUtil;
import io.vertx.core.Future;
import io.vertx.core.Promise;
import io.vertx.core.json.JsonObject;
import org.zeromq.SocketType;
import org.zeromq.ZMQ;

import java.time.Duration;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.locks.LockSupport;

import static com.mindarray.GlobalConstants.*;
import static com.mindarray.eventbus.EventBusConstants.SOCKET_MODE;


/**
 * ZeroMQ (ZMQ) server implementation for the Motadata transport layer.
 *
 * <p>This class provides a ZeroMQ-based transport server that supports multiple socket modes
 * for different messaging patterns. It implements the {@link TransportServer} interface to
 * provide a standardized transport abstraction layer for server-side operations.</p>
 *
 * <p>The server supports different ZeroMQ socket patterns:</p>
 * <ul>
 *   <li><b>PUB (Sender)</b>: Publishes messages to multiple SUB receivers</li>
 *   <li><b>PULL</b>: Receives messages from multiple PUSH clients in a round-robin fashion</li>
 *   <li><b>PUSH</b>: Sends messages to PULL sockets in a load-balanced manner</li>
 * </ul>
 *
 * <p>Key features:</p>
 * <ul>
 *   <li>Configurable High Water Mark (HWM) for message queuing and flow control</li>
 *   <li>TCP keep-alive support for connection reliability</li>
 *   <li>Automatic handling of slow receivers (XPUB_NODROP)</li>
 *   <li>Thread-safe message handling with atomic operations</li>
 *   <li>Integration with Vert.x event bus for message routing</li>
 *   <li>Support for both binding and connecting modes</li>
 * </ul>
 *
 * <p>Configuration example:</p>
 * <pre>{@code
 * JsonObject config = new JsonObject()
 *     .put("SOCKET_MODE", "PUB")
 *     .put("HOST", "localhost")
 *     .put("PORT", 5555)
 *     .put("EVENT_TYPE", "remote.events");
 *
 * ZMQServer server = new ZMQServer(config);
 * server.bind().onSuccess(v -> {
 *     // Server is ready to accept connections
 *     server.send("topic", "Hello World".getBytes());
 * });
 * }</pre>
 *
 * <p><b>Thread Safety:</b> This class is thread-safe for concurrent access to its public methods.
 * However, the underlying ZMQ socket operations are performed in dedicated threads.</p>
 *
 * @author Motadata Engineering Team
 * @version 1.0
 * @since 1.0
 * @see TransportServer
 * @see ZMQClient
 */
public class ZMQServer implements TransportServer
{
    /**
     * Configuration object containing server parameters such as host, port, socket mode, and event type.
     * This configuration is used to establish the ZMQ server binding and determine behavior.
     */
    private final JsonObject config;

    /**
     * The underlying ZeroMQ socket instance used for server operations.
     * This socket is configured based on the socket mode specified in the configuration.
     */
    private ZMQ.Socket server;

    /**
     * The event type identifier used for routing messages to the appropriate event bus consumers.
     * Extracted from the configuration during initialization.
     */
    private final String eventType;

    /**
     * Atomic boolean flag indicating whether the server should continue processing events.
     * Used to control the message receiving loop in a thread-safe manner.
     */
    private final AtomicBoolean hasMoreEvent = new AtomicBoolean(true);

    private Thread receiver;

    /**
     * Logger instance for this ZMQ server, configured with appropriate context and component name.
     */
    private static final Logger LOGGER = new Logger(ZMQServer.class, GlobalConstants.MOTADATA_EVENT_BUS, "ZMQ Server", GlobalConstants.BootstrapType.AGENT.equals(Bootstrap.bootstrapType()));

    /**
     * Constructs a new ZMQServer with the specified configuration.
     *
     * <p>The configuration object must contain the following required parameters:</p>
     * <ul>
     *   <li><b>SOCKET_MODE</b>: The ZMQ socket mode (PUB, PULL, or PUSH)</li>
     *   <li><b>HOST</b>: The host address to bind to (for binding modes)</li>
     *   <li><b>PORT</b>: The port number to bind to or connect to</li>
     *   <li><b>EVENT_TYPE</b>: The event type for message routing</li>
     * </ul>
     *
     * <p>The constructor initializes the server configuration but does not establish
     * the actual ZMQ socket connection. Call {@link #bind()} to start the server.</p>
     *
     * @param config the configuration object containing server parameters and settings.
     *               Must not be null and should contain all required parameters.
     * @throws NullPointerException if config is null
     * @throws IllegalArgumentException if required configuration parameters are missing
     */
    public ZMQServer(JsonObject config)
    {
        this.config = config;

        this.eventType = config.getString(EventBusConstants.EVENT_TYPE);
    }

    /**
     * Binds the ZeroMQ server socket based on the configured socket mode.
     *
     * <p>This method creates and configures the appropriate ZMQ socket type based on the
     * SOCKET_MODE specified in the configuration. The supported socket modes are:</p>
     * <ul>
     *   <li><b>PUB</b>: Creates a event sender socket that binds to a port and publishes messages to receivers</li>
     *   <li><b>PULL</b>: Creates a pull socket that binds to a port and receives messages from push clients</li>
     *   <li><b>PUSH</b>: Creates a push socket that connects to a pull socket for load-balanced message sending</li>
     * </ul>
     *
     * <p>The binding process includes:</p>
     * <ul>
     *   <li>Socket creation with appropriate type</li>
     *   <li>High Water Mark (HWM) configuration for message queuing and flow control</li>
     *   <li>TCP keep-alive and timeout settings for connection reliability</li>
     *   <li>Socket binding to the specified port (for PUB and PULL modes)</li>
     *   <li>Socket connection to remote endpoint (for PUSH mode)</li>
     *   <li>Special handling for slow receivers (PUB mode)</li>
     * </ul>
     *
     * <p>For PUB sockets, the server binds to all interfaces (*) on the specified port
     * and includes a brief pause to eliminate the slow receiver problem. For PULL sockets,
     * the server binds and starts a receiving thread. For PUSH sockets, the server connects
     * to a remote PULL socket.</p>
     *
     * <p><b>Configuration Requirements:</b></p>
     * <ul>
     *   <li>PORT: Required for all socket modes</li>
     *   <li>HOST: Required for PUSH mode (connection target)</li>
     *   <li>SOCKET_MODE: Must be one of PUB, PULL, or PUSH</li>
     * </ul>
     *
     * @return a Future that completes successfully when the server is bound and ready,
     *         or fails with an exception if the binding cannot be established
     * @throws IllegalArgumentException if the socket mode is not supported
     * @see #send(String, byte[])
     * @see #receive()
     * @see #close()
     */
    @Override
    public Future<Void> bind()
    {
        LOGGER.info(String.format("%s Binding ZMQ Server with mode : %s",Bootstrap.bootstrapType(),config.getString(SOCKET_MODE)));

        return switch (EventBusConstants.SocketMode.valueOf(config.getString(SOCKET_MODE)))
        {
            case PUB ->
            {
                var promise = Promise.<Void>promise();

                try
                {
                    server = EventBusConstants.getZMQSocket(SocketType.PUB, config);

                    server.setLinger(0);

                    server.setReceiveTimeOut(MotadataConfigUtil.getRemoteSocketReceiveTimeout());

                    server.setXpubNoDrop(true);

                    server.setSndHWM(MotadataConfigUtil.getEventBacklogSize());

                    server.setHWM(MotadataConfigUtil.getEventBacklogSize());

                    server.setSendTimeOut(0);

                    server.bind("tcp://*:" + config.getInteger(PORT));

                    LockSupport.parkNanos(Duration.ofMillis(100).toNanos()); // Eliminate slow subscriber problem

                    LOGGER.info(String.format("%s server is successfully opened port %s",Bootstrap.bootstrapType(), config.getInteger(PORT)));

                    promise.complete();
                }
                catch (Exception exception)
                {
                    promise.fail(exception);

                    LOGGER.warn(String.format("%s failed to bind with port %s",Bootstrap.bootstrapType(), config.getInteger(PORT)));

                    LOGGER.error(exception);
                }

                yield promise.future();
            }

            case PULL ->
            {
                var promise = Promise.<Void>promise();

                try
                {
                    server = EventBusConstants.getZMQSocket(SocketType.PULL, config);

                    server.setLinger(0);

                    server.setReceiveTimeOut(MotadataConfigUtil.getRemoteSocketReceiveTimeout());

                    server.setHWM(MotadataConfigUtil.getEventBacklogSize());

                    server.setRcvHWM(MotadataConfigUtil.getEventBacklogSize());

                    server.bind("tcp://" + config.getString(HOST) + ":" + config.getInteger(PORT));

                    LOGGER.info(String.format("%s server is successfully opened port with %s:%d",Bootstrap.bootstrapType(), config.getString(HOST), config.getInteger(PORT)));

                    promise.complete();
                }
                catch (Exception exception)
                {
                    promise.fail(exception);

                    LOGGER.warn(String.format("%s failed to bind with %s:%d",Bootstrap.bootstrapType(),config.getString(HOST), config.getInteger(PORT)));

                    LOGGER.error(exception);
                }

                yield promise.future();
            }

            case PUSH ->
            {
                var promise = Promise.<Void>promise();

                try
                {
                    server = EventBusConstants.getZMQSocket(SocketType.PUSH, config);

                    server.setLinger(0);

                    server.setReceiveTimeOut(MotadataConfigUtil.getRemoteSocketReceiveTimeout());

                    server.setSndHWM(MotadataConfigUtil.getEventBacklogSize());

                    server.setHWM(MotadataConfigUtil.getEventBacklogSize());

                    server.setSendTimeOut(0);

                    server.setTCPKeepAlive(1);

                    server.bind("tcp://*:" + config.getInteger(PORT));

                    LOGGER.info(String.format("%s server is successfully opened port with %s:%d",Bootstrap.bootstrapType(), config.getString(HOST), config.getInteger(PORT)));

                    promise.complete();
                }
                catch (Exception exception)
                {
                    promise.fail(exception);

                    LOGGER.warn(String.format("%s failed to bind with %s:%d",Bootstrap.bootstrapType(), config.getString(HOST), config.getInteger(PORT)));

                    LOGGER.error(exception);
                }

                yield promise.future();
            }

            default -> Future.failedFuture("Unsupported ZMQ server mode");
        };
    }

    /**
     * Sends a message with the specified topic through the ZeroMQ socket.
     *
     * <p>This method sends a multi-part message consisting of a topic and message data.
     * The behavior depends on the socket mode:</p>
     * <ul>
     *   <li><b>PUB</b>: Publishes the message to all connected receivers that have subscribed to the topic</li>
     *   <li><b>PUSH</b>: Sends the message to connected PULL sockets in a load-balanced manner</li>
     *   <li><b>PULL</b>: Not typically used for sending (pull sockets usually only receive)</li>
     * </ul>
     *
     * <p>The message is sent as a two-part ZMQ message:</p>
     * <ol>
     *   <li><b>Topic part</b>: The topic string converted to bytes, sent with SNDMORE flag</li>
     *   <li><b>Message part</b>: The actual message data as bytes</li>
     * </ol>
     *
     * <p>For PUB sockets, only receivers that have subscribed to the exact topic
     * (or a matching prefix) will receive the message. The topic-based filtering
     * happens at the receiver side for efficiency.</p>
     *
     * <p><b>Performance Considerations:</b></p>
     * <ul>
     *   <li>The method is synchronous and will block until the message is queued</li>
     *   <li>If the High Water Mark (HWM) is reached, behavior depends on socket configuration</li>
     *   <li>For PUB sockets, slow receivers are handled by the XPUB_NODROP setting</li>
     * </ul>
     *
     * <p><b>Note:</b> This method should only be called after a successful bind has been
     * established via {@link #bind()}. Calling this method before binding may result
     * in undefined behavior or exceptions.</p>
     *
     * @param topic the topic string for message routing and filtering. Must not be null or empty.
     * @param bytes the message data to send as a byte array. Must not be null.
     * @throws IllegalStateException if the server is not bound
     * @throws org.zeromq.ZMQException if there's an error sending the message
     * @throws NullPointerException if topic or bytes is null
     * @see #bind()
     */
    @Override
    public void send(String topic, byte[] bytes)
    {
        try
        {
            server.send(topic.getBytes(), ZMQ.SNDMORE);

            server.send(bytes);

            if (CommonUtil.traceEnabled())
            {
                LOGGER.trace(String.format("%s sending data to : %s from port : %s ",Bootstrap.bootstrapType(),topic,config.getInteger(PORT)));
            }
        }
        catch (Exception exception)
        {
            LOGGER.warn(String.format("error occurred while sending in %s for topic : %s ",Bootstrap.bootstrapType(),topic));

            LOGGER.error(exception);
        }
    }

    /**
     * Starts receiving messages from the ZeroMQ socket in a separate thread.
     *
     * <p>This method creates a new thread that continuously listens for incoming messages
     * on the ZMQ socket. The receiving behavior depends on the socket mode:</p>
     * <ul>
     *   <li><b>PULL</b>: Receives messages from push clients in a round-robin fashion</li>
     *   <li><b>PUB</b>: Not typically used for receiving (senders usually only send)</li>
     *   <li><b>PUSH</b>: Not typically used for receiving (push sockets usually only send)</li>
     * </ul>
     *
     * <p>The receiving process:</p>
     * <ol>
     *   <li>Creates a dedicated thread named "ZMQ Server [host:port]" for message reception</li>
     *   <li>Continuously polls the socket for new messages using blocking recv()</li>
     *   <li>Validates received messages (non-null and non-empty)</li>
     *   <li>Forwards valid messages to the Vert.x event bus using the configured event type</li>
     *   <li>Continues until {@link #close()} is called</li>
     * </ol>
     *
     * <p>The method automatically handles message routing by sending received messages
     * to the Vert.x event bus with the event type specified in the configuration.
     * This allows other components to consume the messages through event bus subscriptions.</p>
     *
     * <p><b>Thread Safety:</b> This method is thread-safe and can be called multiple times,
     * but only one receiving thread will be active per server instance.</p>
     *
     * <p><b>Error Handling:</b> If an error occurs during message reception, it is logged
     * and the receiving loop continues. The thread will only stop when the server is closed.</p>
     *
     * <p><b>Performance:</b> The receiving thread uses blocking I/O, which is efficient
     * for the ZMQ transport but means the thread will be blocked when no messages are available.</p>
     *
     * @return a Future that completes immediately after starting the receiving thread.
     *         The Future completion does not indicate message reception status.
     * @throws IllegalStateException if the server is not bound
     * @see #bind()
     * @see #close()
     */
    @Override
    public Future<Void> receive()
    {
        receiver = new Thread(() ->
        {
            byte[] message;

            while (hasMoreEvent.get())
            {
                try
                {
                    message = server.recv();

                    if (message != null && message.length > 0)
                    {
                        Bootstrap.vertx().eventBus().send(eventType,message);
                    }
                }
                catch (Exception exception)
                {
                    LOGGER.warn(String.format("error while sending event to : %s , thread : %s  ",eventType,Thread.currentThread().getName() ));

                    LOGGER.error(exception);
                }
            }

            LOGGER.info("receiver thread stopped successfully with more events : " + hasMoreEvent.get());

        },"ZMQ Server " + config.getString(HOST) + ":" + config.getInteger(PORT));

        receiver.start();

        return Future.succeededFuture();
    }

    /**
     * Closes the ZeroMQ server and releases all associated resources.
     *
     * <p>This method performs a graceful shutdown of the ZMQ server by:</p>
     * <ol>
     *   <li>Logging the server closure with host and port information</li>
     *   <li>Setting the hasMoreEvent flag to false to stop the receiving loop</li>
     *   <li>Closing the underlying ZMQ socket</li>
     *   <li>Releasing any system resources associated with the server</li>
     * </ol>
     *
     * <p>After calling this method:</p>
     * <ul>
     *   <li>The receiving thread will terminate gracefully</li>
     *   <li>No more messages can be sent or received</li>
     *   <li>The server socket will be unbound from its port</li>
     *   <li>The server cannot be reused and a new instance must be created for restart</li>
     * </ul>
     *
     * <p><b>Thread Safety:</b> This method is thread-safe and can be called from any thread.
     * Multiple calls to close() are safe and will have no additional effect.</p>
     *
     * <p><b>Graceful Shutdown:</b> The method ensures that any ongoing receive operations
     * complete before the socket is closed, preventing data loss or corruption.</p>
     *
     * <p><b>Best Practice:</b> Always call this method when the server is no longer needed
     * to prevent resource leaks and ensure proper cleanup. This is especially important
     * in long-running applications.</p>
     *
     * @see #bind()
     * @see #receive()
     */
    @Override
    public Future<Void> close()
    {
        try
        {
            hasMoreEvent.set(false);

            LOGGER.info("closing server");

            if (receiver != null)
            {
                // Wait for the receiving thread to finish processing
                receiver.join(MotadataConfigUtil.getRemoteSocketTimeout());
            }

            server.close();

            LOGGER.info(String.format("server closed : %s " ,config.getString(HOST,EMPTY_VALUE) + ":" + config.getInteger(PORT)));

        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }

        return Future.succeededFuture();
    }
}

