                                        writeTriggeredActionEvent(targets, context, entityId, policy.getLong(ID), reply.result().body().put(RUNBOOK_WORKLOG_TYPE, PolicyTriggerActionType.NOTIFICATION.getName()), LOGGER, mappers, builder);
