public class RUMPolicyTriggerDurationCalculator extends AbstractVerticle
{
    private static final Logger LOGGER = new Logger(RUMPolicyTriggerDurationCalculator.class, GlobalConstants.MOTADATA_POLICY, "RUM Policy Trigger Duration Calculator");
    private static final int POLICY_FLAP_FLUSH_TIMER_SECONDS = MotadataConfigUtil.getPolicyFlapFlushTimerSeconds();
    private final JsonObject servicePolicyStatuses = new JsonObject();
    private final JsonObject policyTriggerTicks = new JsonObject();
    private final AtomicBoolean policyTriggerTickDirty = new AtomicBoolean();
    private final AtomicBoolean policyStatusDirty = new AtomicBoolean();
    private boolean updated = false;

    /**
     * Starts the RUMPolicyTriggerDurationCalculator verticle.
     * This method:
     * 1. Loads persisted policy trigger ticks and flap durations from backup files
     * 2. Sets up event bus handlers for duration calculation, queries, and acknowledgments
     * 3. Initializes periodic timers for flushing data to disk
     * 4. Registers with the high availability system for cache synchronization
     *
     * @param promise A promise that will be completed when startup is finished or failed if an error occurs
     */
    @Override
    public void start(Promise<Void> promise) throws Exception
    {
        try
        {
            var flushTimerSeconds = new AtomicInteger(POLICY_FLAP_FLUSH_TIMER_SECONDS);

            var file = new File(GlobalConstants.CURRENT_DIR + GlobalConstants.PATH_SEPARATOR + GlobalConstants.CONFIG_DIR + GlobalConstants.PATH_SEPARATOR + PolicyEngineConstants.RUM_POLICY_TRIGGER_TICKS);

            if (file.exists())
            {
                var buffer = vertx.fileSystem().readFileBlocking(file.getPath());

                if (buffer != null && buffer.getBytes().length > 0)
                {
                    policyTriggerTicks.mergeIn(new JsonObject(Buffer.buffer(CodecUtil.toBytes(buffer.getBytes()))));

                    LOGGER.info(String.format("%s loaded from the backup file...", PolicyEngineConstants.RUM_POLICY_TRIGGER_TICKS));
                }
            }
            else
            {
                vertx.fileSystem().createFileBlocking(file.getPath());
            }

            file = new File(GlobalConstants.CURRENT_DIR + GlobalConstants.PATH_SEPARATOR + GlobalConstants.CONFIG_DIR + GlobalConstants.PATH_SEPARATOR + PolicyEngineConstants.RUM_POLICY_FLAP_DURATIONS);

            if (file.exists())
            {
                var buffer = vertx.fileSystem().readFileBlocking(file.getPath());

                if (buffer != null && buffer.getBytes().length > 0)
                {
                    new JsonObject(Buffer.buffer(CodecUtil.toBytes(buffer.getBytes()))).getMap().forEach((key, value) -> servicePolicyStatuses.put(key, JsonObject.mapFrom(value)));

                    LOGGER.info(String.format("%s loaded from the backup file...", PolicyEngineConstants.RUM_POLICY_FLAP_DURATIONS));
                }
            }
            else
            {
                vertx.fileSystem().createFileBlocking(file.getPath());
            }

            vertx.eventBus().<JsonObject>localConsumer(EventBusConstants.EVENT_RUM_POLICY_SEVERITY_DURATION_CALCULATE, message ->
            {
                try
                {
                    if (!message.body().isEmpty())
                    {

                        var event = message.body();

                        var key = event.getLong(ENTITY_ID) + SEPARATOR + event.getLong(ID) + SEPARATOR + (event.getValue(INSTANCE, null) != null && !CommonUtil.getString(event.getValue(INSTANCE)).isEmpty() ? event.getString(GlobalConstants.METRIC) + SEPARATOR + event.getValue(INSTANCE) : event.getString(GlobalConstants.METRIC));

                        if (servicePolicyStatuses.containsKey(key))
                        {
                            var duration = servicePolicyStatuses.getJsonObject(key).getInteger(DURATION, 0);

                            if (!servicePolicyStatuses.getJsonObject(key).getString(SEVERITY).equalsIgnoreCase(event.getString(SEVERITY)))   // flap change
                            {
                                /*
                                 * There are two case
                                 * 1. previous.flap.timestamp = event.timestamp (auto_clear) -> we get duration 10, we add duration in event.timestamp
                                 * 2. previous.flap.timestamp > event.timestamp (polling delay) -> we get duration < difference, we add difference + 1 to maintain sequence of flap
                                 * */

                                var previousFlapTimeStamp = servicePolicyStatuses.getJsonObject(key).getLong(PREVIOUS_FLAP_TIMESTAMP);

                                var currentTimeStamp = event.getLong(EVENT_TIMESTAMP);

                                var flapDiffSeconds = event.getLong(EVENT_TIMESTAMP) - previousFlapTimeStamp;

                                if (flapDiffSeconds <= 0)
                                {
                                    currentTimeStamp = event.getLong(EVENT_TIMESTAMP) + (duration <= Math.abs(flapDiffSeconds) ? 1 + Math.abs(flapDiffSeconds) : duration);

                                    flapDiffSeconds = currentTimeStamp - previousFlapTimeStamp;
                                }

                                send(servicePolicyStatuses.getJsonObject(key).put(DURATION, flapDiffSeconds));   // if flap then send data to DB..

                                // if flap then notify to refresh respective widgets

                                Bootstrap.vertx().eventBus().send(EventBusConstants.EVENT_VISUALIZATION_REALTIME_WIDGET_REFRESH, new JsonObject().put(EVENT_CONTEXT, new JsonObject().put(VisualizationConstants.PLUGIN, DatastoreConstants.PluginId.RUM_POLICY_DURATION_METRIC.getName() + DASH_SEPARATOR + VisualizationConstants.VisualizationDataSource.POLICY_FLAP.getName().toLowerCase()).put(NMSConstants.OBJECT, new JsonArray().add(CommonUtil.getString(event.getLong(ENTITY_ID))))));

                                if (CommonUtil.traceEnabled()) //
                                {
                                    LOGGER.trace(String.format("Current severity for policy.key %s of %s is %s with %s is %d for duration %d with flapDiff %d and new Severity %s with timestamp is %d which triggered for value : %s", key, event.getString(INSTANCE), servicePolicyStatuses.getJsonObject(key).getString(SEVERITY), PREVIOUS_FLAP_TIMESTAMP, previousFlapTimeStamp, duration, flapDiffSeconds, event.getString(SEVERITY), event.getLong(EVENT_TIMESTAMP), event.getString(VALUE)));
                                }

                                servicePolicyStatuses.getJsonObject(key).mergeIn(event).put(PolicyEngineConstants.POLICY_NOTE, EMPTY_VALUE).put(PREVIOUS_FLAP_TIMESTAMP, event.getLong(EVENT_TIMESTAMP)).put(PREVIOUS_FLAP_VALUE, event.getValue(VALUE)).remove(PolicyEngineConstants.POLICY_ACKNOWLEDGE);

                                if ((event.getLong(EVENT_TIMESTAMP) - previousFlapTimeStamp) <= 0) // MOTADATA-558 in case of auto-clear and polling scheduler clashes
                                {
                                    if (CommonUtil.traceEnabled())
                                    {
                                        LOGGER.trace(String.format("!!Altered timestamp!! ip : %s, %s : %d, event.timestamp : %d, duration : %d,updated %s : %d", event.getString(AIOpsObject.OBJECT_IP), PREVIOUS_FLAP_TIMESTAMP, previousFlapTimeStamp, event.getLong(EVENT_TIMESTAMP), duration, PREVIOUS_FLAP_TIMESTAMP, currentTimeStamp));
                                    }

                                    servicePolicyStatuses.getJsonObject(key).put(PREVIOUS_FLAP_TIMESTAMP, currentTimeStamp);
                                }

                                RUMPolicyFlapDurationCacheStore.getStore().update(key, servicePolicyStatuses.getJsonObject(key));
                            }
                            else
                            {
                                event.remove(PolicyEngineConstants.POLICY_RUNBOOK_ID); // as runbook id will not change if severity not changed

                                servicePolicyStatuses.getJsonObject(key).mergeIn(event);

                                RUMPolicyFlapDurationCacheStore.getStore().update(key, servicePolicyStatuses.getJsonObject(key));
                            }
                        }
                        else
                        {
                            servicePolicyStatuses.put(key, event.put(DURATION, 0).put(PolicyEngineConstants.POLICY_NOTE, EMPTY_VALUE).put(PREVIOUS_FLAP_TIMESTAMP, event.getLong(EVENT_TIMESTAMP)).put(PREVIOUS_FLAP_VALUE, event.getValue(VALUE)));

                            RUMPolicyFlapDurationCacheStore.getStore().update(key, servicePolicyStatuses.getJsonObject(key));

                            Bootstrap.vertx().eventBus().send(EventBusConstants.EVENT_VISUALIZATION_REALTIME_WIDGET_REFRESH, new JsonObject().put(EVENT_CONTEXT, new JsonObject().put(VisualizationConstants.PLUGIN, DatastoreConstants.PluginId.RUM_POLICY_DURATION_METRIC.getName() + DASH_SEPARATOR + VisualizationConstants.VisualizationDataSource.POLICY_FLAP.getName().toLowerCase()).put(NMSConstants.OBJECT, new JsonArray().add(CommonUtil.getString(event.getLong(ENTITY_ID))))));
                        }

                        if (!policyTriggerTicks.containsKey(key))
                        {
                            updated = true;

                            policyTriggerTicks.put(key, System.currentTimeMillis());
                        }

                        event.put(PolicyEngineConstants.POLICY_FIRST_TRIGGER_TICK, policyTriggerTicks.getLong(key));

                        if (MotadataConfigUtil.devMode())
                        {
                            vertx.eventBus().publish(EVENT_RUM_POLICY + "." + "test",new JsonObject().mergeIn(event).put(POLICY_KEY,key));
                        }
                    }


                }
                catch (Exception exception)
                {
                    LOGGER.error(exception);
                }
            });

            vertx.eventBus().<JsonObject>localConsumer(EventBusConstants.EVENT_RUM_POLICY_TRIGGER_DURATION_QUERY, message ->
            {
                var request = message.body();

                if (!request.isEmpty() && request.containsKey(PolicyEngineConstants.POLICY_KEY))    // if policy key is present then return only that policy data
                {
                    message.reply(servicePolicyStatuses.getJsonObject(request.getString(PolicyEngineConstants.POLICY_KEY), new JsonObject()));
                }
                else
                {
                    message.reply(new JsonObject().mergeIn(servicePolicyStatuses));
                }

            });

            vertx.eventBus().<JsonObject>localConsumer(EventBusConstants.EVENT_RUM_POLICY_TRIGGER_TICK_QUERY, message -> message.reply(new JsonObject().mergeIn(policyTriggerTicks)));

            vertx.eventBus().<JsonObject>localConsumer(EventBusConstants.EVENT_RUM_POLICY_ACKNOWLEDGE, message ->
            {
                var event = message.body();

                var policy = RUMPolicyConfigStore.getStore().getItem(event.getLong(PolicyEngineConstants.POLICY_ID));

                var key = event.getLong(RUMConstant.RUM_ID) + SEPARATOR + event.getLong(PolicyEngineConstants.POLICY_ID) + SEPARATOR + (event.getValue(INSTANCE, null) != null && !CommonUtil.getString(event.getValue(INSTANCE)).isEmpty() ? policy.getJsonObject(PolicyEngineConstants.POLICY_CONTEXT).getString(METRIC) + SEPARATOR + event.getValue(INSTANCE) : policy.getJsonObject(PolicyEngineConstants.POLICY_CONTEXT).getString(METRIC));

                var context = new JsonObject().mergeIn(event).put(PolicyEngineConstants.POLICY_ACKNOWLEDGE_TIME, DateTimeUtil.currentMilliSeconds());

                context.remove(RUMConstant.RUM_ID);

                context.remove(PolicyEngineConstants.POLICY_ID);

                context.remove(INSTANCE);

                if (context.getString(ACKNOWLEDGED).equalsIgnoreCase(YES))
                {
                    servicePolicyStatuses.getJsonObject(key).put(PolicyEngineConstants.POLICY_ACKNOWLEDGE, context.encode());

                    RUMPolicyFlapDurationCacheStore.getStore().update(key, servicePolicyStatuses.getJsonObject(key));
                }
                else
                {
                    servicePolicyStatuses.getJsonObject(key).remove(PolicyEngineConstants.POLICY_ACKNOWLEDGE);

                    RUMPolicyFlapDurationCacheStore.getStore().update(key, servicePolicyStatuses.getJsonObject(key));

                }
            });

            vertx.eventBus().<JsonObject>localConsumer(EventBusConstants.EVENT_RUM_POLICY_COMMENT_UPDATE, message ->
            {
                var event = message.body();

                var policy = RUMPolicyConfigStore.getStore().getItem(event.getLong(PolicyEngineConstants.POLICY_ID));

                var key = event.getLong(RUMConstant.RUM_ID) + SEPARATOR + event.getLong(PolicyEngineConstants.POLICY_ID) + SEPARATOR + (event.getValue(INSTANCE, null) != null && !CommonUtil.getString(event.getValue(INSTANCE)).isEmpty() ? policy.getJsonObject(PolicyEngineConstants.POLICY_CONTEXT).getString(METRIC) + SEPARATOR + event.getValue(INSTANCE) : policy.getJsonObject(PolicyEngineConstants.POLICY_CONTEXT).getString(METRIC));

                servicePolicyStatuses.getJsonObject(key).put(PolicyEngineConstants.POLICY_NOTE, event.getString(PolicyEngineConstants.POLICY_NOTE));

                RUMPolicyFlapDurationCacheStore.getStore().update(key, servicePolicyStatuses.getJsonObject(key));
            });

            vertx.eventBus().<JsonObject>localConsumer(EventBusConstants.EVENT_CHANGE_NOTIFICATION, message ->
            {
                var event = message.body();

                if (EventBusConstants.ChangeNotificationType.valueOf(event.getString(CHANGE_NOTIFICATION_TYPE)) == EventBusConstants.ChangeNotificationType.DELETE_OBJECT && (!event.containsKey(METRIC_INSTANCES) || event.getValue(METRIC_INSTANCES) == null))
                {
                    var keys = new HashSet<String>();

                    servicePolicyStatuses.getMap().keySet().forEach(key ->
                    {
                        if (CommonUtil.getLong(key.split(SEPARATOR_WITH_ESCAPE)[0].trim()) == event.getLong(ID))
                        {
                            keys.add(key);

                            RUMPolicyFlapDurationCacheStore.getStore().remove(key);
                        }
                    });

                    keys.forEach(servicePolicyStatuses::remove);
                }
                else if (EventBusConstants.ChangeNotificationType.valueOf(event.getString(EventBusConstants.CHANGE_NOTIFICATION_TYPE)) == EventBusConstants.ChangeNotificationType.UPDATE_CACHE)
                {
                    if (policyTriggerTickDirty.get())
                    {
                        policyTriggerTickDirty.set(false);

                        HAConstants.notifyObserver(new JsonObject().put(HAConstants.CACHE_NAME, PolicyEngineConstants.RUM_POLICY_TRIGGER_TICKS).put(STATUS, STATUS_SUCCEED).put(RESULT, vertx.fileSystem().readFileBlocking(GlobalConstants.CURRENT_DIR + GlobalConstants.PATH_SEPARATOR + GlobalConstants.CONFIG_DIR + GlobalConstants.PATH_SEPARATOR + PolicyEngineConstants.RUM_POLICY_TRIGGER_TICKS)));
                    }

                    if (policyStatusDirty.get())
                    {
                        policyStatusDirty.set(false);

                        HAConstants.notifyObserver(new JsonObject().put(HAConstants.CACHE_NAME, PolicyEngineConstants.RUM_POLICY_FLAP_DURATIONS).put(STATUS, STATUS_SUCCEED).put(RESULT, vertx.fileSystem().readFileBlocking(GlobalConstants.CURRENT_DIR + GlobalConstants.PATH_SEPARATOR + GlobalConstants.CONFIG_DIR + GlobalConstants.PATH_SEPARATOR + PolicyEngineConstants.RUM_POLICY_FLAP_DURATIONS)));
                    }

                    if (RUMPolicyCacheStore.getStore().dirty())
                    {
                        HAConstants.notifyObserver(new JsonObject().put(HAConstants.CACHE_NAME, PolicyEngineConstants.RUM_POLICY_SEVERITIES).put(STATUS, STATUS_SUCCEED).put(RESULT, vertx.fileSystem().readFileBlocking(GlobalConstants.CURRENT_DIR + GlobalConstants.PATH_SEPARATOR + GlobalConstants.CONFIG_DIR + GlobalConstants.PATH_SEPARATOR + PolicyEngineConstants.RUM_POLICY_SEVERITIES)));

                        RUMPolicyCacheStore.getStore().setDirty(false);
                    }
                }
            }).exceptionHandler(LOGGER::error);

            vertx.setPeriodic(10 * 1000L, timer -> write());

            vertx.setPeriodic(30 * 1000L, timer ->
            {
                if (updated)
                {
                    policyTriggerTickDirty.set(true);

                    updated = false;

                    vertx.fileSystem().writeFileBlocking(GlobalConstants.CURRENT_DIR + GlobalConstants.PATH_SEPARATOR + GlobalConstants.CONFIG_DIR + GlobalConstants.PATH_SEPARATOR + PolicyEngineConstants.RUM_POLICY_TRIGGER_TICKS,
                            Buffer.buffer(CodecUtil.compress(policyTriggerTicks.encode().getBytes())));
                }

                flushTimerSeconds.set(flushTimerSeconds.get() - 30);

                if (flushTimerSeconds.get() <= 0 && !servicePolicyStatuses.isEmpty())
                {
                    policyStatusDirty.set(true);

                    vertx.fileSystem().writeFileBlocking(GlobalConstants.CURRENT_DIR + GlobalConstants.PATH_SEPARATOR + GlobalConstants.CONFIG_DIR + GlobalConstants.PATH_SEPARATOR + PolicyEngineConstants.RUM_POLICY_FLAP_DURATIONS,
                            Buffer.buffer(CodecUtil.compress(new JsonObject().mergeIn(servicePolicyStatuses).encode().getBytes())));

                    flushTimerSeconds.set(POLICY_FLAP_FLUSH_TIMER_SECONDS);
                }
            });

            RUMPolicyFlapDurationCacheStore.getStore().initStore();
        }

        catch (Exception exception)
        {
            LOGGER.error(exception);
        }

        promise.complete();
    }

    /**
     * Updates policy durations by incrementing the duration counters.
     * This method is called periodically to:
     * 1. Increment the duration for all active policy states
     * 2. Clean up entries for objects that no longer exist
     * <p>
     * The duration is incremented by 10 seconds each time this method is called.
     */
    private void write()
    {
        var deletedEntries = new HashSet<String>();

        for (var entry : servicePolicyStatuses.getMap().entrySet())
        {
            try
            {
                var value = (JsonObject) entry.getValue();

                var applicationId = value.getLong(APIConstants.ENTITY_ID);

                var object = RUMServiceProfileConfigStore.getStore().getItem(applicationId, false);

                if (object != null)
                {
                    value.put(DURATION, value.getInteger(DURATION, 0) + 10);

                    RUMPolicyFlapDurationCacheStore.getStore().updateFlapDuration(entry.getKey(),value.getInteger(DURATION));
                }
                else
                {
                    // just for safer purpose will be keeping check if object null and its keys not removed so will be removing keys forcefully
                    deletedEntries.add(entry.getKey());

                    RUMPolicyFlapDurationCacheStore.getStore().remove(entry.getKey());
                }
            }
            catch (Exception exception)
            {
                LOGGER.error(exception);
            }
        }

        if (!deletedEntries.isEmpty())
        {
            deletedEntries.forEach(servicePolicyStatuses::remove);
        }
    }


    /**
     * Sends policy flap information to the datastore.
     * This method:
     * 1. Creates a buffer with policy flap data including timestamps, durations, and state information
     * 2. Formats the data for storage in the event datastore
     * 3. Resets the duration counter after recording the flap
     *
     * @param value The policy flap information to be sent to the datastore
     */
    private void send(JsonObject value)
    {
        try
        {
            var buffer = Buffer.buffer();

            LOGGER.info(String.format("RUM POlICY Trigger Duration Calculator received   %s" ,value));

            if (CommonUtil.isNullOrEmpty(value.getString(GlobalConstants.SEVERITY)) || value.getValue(VALUE) == null )
            {
                LOGGER.warn(String.format("RUM POlICY Trigger Duration Calculator received event for key: %s" ,value));
            }

            appendBytes(buffer, value.getLong(PREVIOUS_FLAP_TIMESTAMP), DatastoreConstants.PluginId.RUM_POLICY_DURATION_METRIC.getName());

            updateEventFieldBatch(AIOpsObject.OBJECT_ID, CommonUtil.getString(value.getLong(APIConstants.ENTITY_ID)), buffer);

            updateEventFieldBatch(INSTANCE, value.containsKey(INSTANCE) && !value.getString(INSTANCE).isEmpty() ? CommonUtil.getString(value.getValue(INSTANCE)) : EMPTY_VALUE, buffer);

            updateEventFieldBatch(PolicyEngineConstants.POLICY_ID, CommonUtil.getString(value.getLong(ID)), buffer);

            updateEventFieldBatch(PolicyEngineConstants.POLICY_RUNBOOK_ID, CommonUtil.getString(value.getLong(PolicyEngineConstants.POLICY_RUNBOOK_ID, 0L)), buffer);

            updateEventFieldBatch(DURATION, CommonUtil.getString(value.getInteger(DURATION)), buffer);

            updateEventFieldBatch(SEVERITY, value.getString(SEVERITY), buffer);

            updateEventFieldBatch(MetricPolicy.POLICY_THRESHOLD, CommonUtil.getString(value.getValue(MetricPolicy.POLICY_THRESHOLD, EMPTY_VALUE)), buffer);

            updateEventFieldBatch(VALUE, CommonUtil.getString(value.getValue(PREVIOUS_FLAP_VALUE, value.getValue(VALUE))), buffer);

            updateEventFieldBatch(METRIC, CommonUtil.getString(value.getValue(METRIC)), buffer);

            updateEventFieldBatch(PolicyEngineConstants.POLICY_TYPE, CommonUtil.getString(value.getValue(PolicyEngineConstants.POLICY_TYPE)), buffer);

            vertx.eventBus().send(EventBusConstants.EVENT_DATASTORE_WRITE + "." + DatastoreConstants.DatastoreCategory.EVENT.getName(), buffer.getBytes());

            value.put(DURATION, 0);

        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }


    /**
     * Initializes a buffer with common event metadata.
     * This method sets up the buffer with timestamp, plugin information,
     * and datastore format details that are required for all events.
     *
     * @param bytes     The buffer to initialize
     * @param timestamp The event timestamp in epoch seconds
     * @param pluginId  The ID of the plugin generating the event
     */
    private void appendBytes(Buffer bytes, long timestamp, int pluginId)
    {
        bytes.setLongLE(0, timestamp);

        var plugin = pluginId + DASH_SEPARATOR + VisualizationConstants.VisualizationDataSource.POLICY_FLAP.getName().toLowerCase();

        bytes.appendIntLE(plugin.length());

        bytes.appendString(plugin);

        bytes.appendByte(DatastoreConstants.DatastoreFormat.HORIZONTAL.getName().byteValue());

        bytes.appendByte(CommonUtil.getByteValue(DatastoreConstants.DatastoreType.METRIC_POLICY_FLAP_HISTORY.ordinal()));

        bytes.appendShortLE(CommonUtil.getShort(EMPTY_VALUE.length()));

        bytes.appendString(EMPTY_VALUE);
    }


    /**
     * Updates a field in the event buffer for batch processing.
     * This method formats and appends a field-value pair to the buffer
     * according to the datastore's expected format, handling different
     * data types appropriately.
     *
     * @param column The name of the field to update
     * @param value  The string value to set for the field
     * @param buffer The buffer to append the field-value pair to
     */
    private void updateEventFieldBatch(String column, String value, Buffer buffer)
    {
        try
        {
            var category = DatastoreConstants.DataCategory.STRING.getName();

            if (column.equalsIgnoreCase(PolicyEngineConstants.POLICY_ID) || column.equalsIgnoreCase(DURATION) || column.equalsIgnoreCase(AIOpsObject.OBJECT_ID))
            {
                category = DatastoreConstants.DataCategory.NUMERIC.getName();
            }

            buffer.appendByte(category);

            buffer.appendIntLE(column.length());

            buffer.appendString(column);

            if (category == DatastoreConstants.DataCategory.NUMERIC.getName())//if it has decimal number than convert it into integer
            {
                buffer.appendLongLE(Math.round(CommonUtil.getDouble(value)));
            }
            else
            {
                var bytes = value.getBytes(StandardCharsets.UTF_8);

                buffer.appendIntLE(bytes.length);

                buffer.appendBytes(bytes);
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }


    /**
     * Stops the RUMPolicyTriggerDurationCalculator verticle.
     * This method ensures that all policy state information is persisted to disk
     * before the verticle is undeployed, preserving the data for recovery.
     *
     * @param promise A promise that will be completed when shutdown is finished
     */
    @Override
    public void stop(Promise<Void> promise) throws Exception
    {
        LOGGER.info("Undeploying verticle RUMPolicyTriggerDurationCalculator...");

        try
        {
            if (!servicePolicyStatuses.isEmpty())
            {
                vertx.fileSystem().writeFileBlocking(GlobalConstants.CURRENT_DIR + GlobalConstants.PATH_SEPARATOR + GlobalConstants.CONFIG_DIR + GlobalConstants.PATH_SEPARATOR + PolicyEngineConstants.RUM_POLICY_FLAP_DURATIONS,
                        Buffer.buffer(CodecUtil.compress(new JsonObject().mergeIn(servicePolicyStatuses).encode().getBytes())));
            }

            if (!policyTriggerTicks.isEmpty())
            {

                vertx.fileSystem().writeFileBlocking(GlobalConstants.CURRENT_DIR + GlobalConstants.PATH_SEPARATOR + GlobalConstants.CONFIG_DIR + GlobalConstants.PATH_SEPARATOR + PolicyEngineConstants.RUM_POLICY_TRIGGER_TICKS,
                        Buffer.buffer(CodecUtil.compress(policyTriggerTicks.encode().getBytes())));
            }

            RUMPolicyCacheStore.getStore().dump(CURRENT_DIR + PATH_SEPARATOR + CONFIG_DIR + PATH_SEPARATOR + PolicyEngineConstants.RUM_POLICY_SEVERITIES);
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }

        promise.complete();
    }
}

