                                columns.add(tokens[1] + LAST_COLUMN_SUFFIX);

                                result.getMap().computeIfAbsent(tokens[1] + LAST_COLUMN_SUFFIX, v -> new JsonArray());

                                // if not enough data to forecast then put null in stats
                                if (response.containsKey(ERROR) && response.getString(ERROR).contains("group: " + tokens[0] + " ") && response.containsKey(RESULT)) // check for the insufficient data error with object id to avoid mismatches(strictly match "group: X" only, prevents false hit)
                                {
                                    stats.computeIfAbsent(tokens[0], data -> new JsonObject()).put(tokens[1] + AFTER_COLUMN_INFIX + timeline, null);

                                }
                                else if (columns.contains(tokens[1] + AFTER_COLUMN_INFIX + timeline))
                                {
                                    stats.computeIfAbsent(tokens[0], data -> new JsonObject()).put(tokens[1] + AFTER_COLUMN_INFIX + timeline, entry.getValue());
                                }
                            }
                        }
                    });

                }
            }
            // if percent based forecast
            else
            {
                var predictionIndex = 0;

                var conditions = reportContext.getJsonArray(REPORT_FORECAST_THRESHOLD_CONDITIONS);

                for (var index = 0; index < context.getJsonArray(EVENT_CONTEXT).size(); index++)
                {
                    var eventContext = context.getJsonArray(EVENT_CONTEXT).getJsonObject(index);

                    // skip last poll response as its already filled
                    if (eventContext.getBoolean(NMSConstants.LAST_POLL_VALUE, false))
                    {
                        continue;
                    }

                    var response = VisualizationConstants.unpack(Buffer.buffer((eventContext).getBinary(GlobalConstants.RESULT)), LOGGER, false, eventContext.containsKey(QUERY_CONTEXT) ? eventContext.getJsonObject(QUERY_CONTEXT) : null, false, true);

                    var rows = response.getJsonArray(RESULT, new JsonArray());

                    // it is the point from where prediction data starts in rows
                    predictionIndex = response.getInteger(PREDICTION_INDEX, 0);

                    LOGGER.debug("forecast failed for " + response.getString(ERROR));

                    if (!rows.isEmpty())
                    {
                        // we will check last 2 points and last value to determine already reached state
                        for (var i = predictionIndex - 2; i < rows.size(); i++)
                        {
                            var row = rows.getJsonObject(i);

                            if (row != null)
                            {
                                row.getMap().forEach((key, value) ->
                                {
                                    if (!key.equalsIgnoreCase(TIME_STAMP) && (CommonUtil.getLong(value) != Long.MIN_VALUE && CommonUtil.getFloat(value) != -Float.MAX_VALUE) && !key.contains("upperbound") && !key.contains("lowerbound"))
                                    {
                                        var tokens = key.split(CARET_SEPARATOR_WITH_ESCAPE);

                                        if (tokens.length == 3)
                                        {
                                            // if no monitor has last poll data then this column will be initialized here
                                            columns.add(tokens[1] + LAST_COLUMN_SUFFIX);

                                            result.getMap().computeIfAbsent(tokens[1] + LAST_COLUMN_SUFFIX, v -> new JsonArray());

                                            var prediction = stats.computeIfAbsent(tokens[0], data -> new JsonObject());

                                            for (var j = 0; j < conditions.size(); j++)
                                            {
                                                var condition = conditions.getJsonObject(j);

                                                // if not enough data to forecast then put null in stats
                                                if (response.containsKey(ERROR) && response.getString(ERROR).contains("group: " + tokens[0] + " ") && response.containsKey(RESULT)) // check for the insufficient data error with object id to avoid mismatches(strictly match "group: X" only, prevents false hit)
                                                {
                                                    prediction.put(tokens[1] + DOT_SEPARATOR + condition.getInteger(THRESHOLD), null);
                                                }
                                                else
                                                {
                                                    var column = tokens[1] + DOT_SEPARATOR + condition.getInteger(THRESHOLD);

                                                    // if last value satisfies condition then put already reached
                                                    if (prediction.containsKey(tokens[1] + LAST_COLUMN_SUFFIX))
                                                    {
                                                        if (evaluate(condition.getInteger(THRESHOLD), condition.getString(CONDITION), prediction.getString(tokens[1] + LAST_COLUMN_SUFFIX)))
                                                        {
                                                            prediction.put(column, "Already Reached");
                                                        }
                                                    }

                                                    // if Not already reached state then calculate this
                                                    if (!prediction.containsKey(column) || "Stable Growth".equalsIgnoreCase(prediction.getString(column)))
                                                    {
                                                        // if past data and condition satisfies then put already reached
                                                        // if future data and condition satisfies then put time diff from now to row timestamp
                                                        if (evaluate(condition.getInteger(THRESHOLD), condition.getString(CONDITION), value))
                                                        {
                                                            prediction.put(column, (row.getLong(TIMESTAMP) <= System.currentTimeMillis()) ? "Already Reached" : DateTimeUtil.millisToDuration(row.getLong(TIMESTAMP) - System.currentTimeMillis()));
                                                        }
                                                        // not seen any condition breach yet
                                                        else if (!prediction.containsKey(column))
                                                        {
                                                            prediction.put(column, "Stable Growth");
                                                        }
                                                    }
                                                }
                                            }
                                        }
                                        else
                                        {
                                            LOGGER.warn("invalid key " + key);
                                        }
                                    }
                                });
                            }
                        }
                    }
                }
            }

            buildResult(context, result, stats, columns);

            // we will send first event context as it will have all query details for frontend to handle preview logics
            EventBusConstants.publish(context.getString(SESSION_ID), EventBusConstants.UI_ACTION_VISUALIZATION_RENDER, context.put(EventBusConstants.EVENT_COMPRESSION_TYPE, COMPRESSION_TYPE_ZERO)
                    .put(VisualizationConstants.CONTAINER_TYPE,"report").put(RESULT, VisualizationConstants.packGridResult(result, VisualizationConstants.VisualizationCategoryOrdinal.VISUALIZATION_GRID.ordinal(), context.getLong(QUERY_ID), -1).getBytes()));

        }

        catch (Exception exception)
        {
            LOGGER.error(exception);

            EventBusConstants.publish(context.getString(SESSION_ID), EventBusConstants.UI_ACTION_VISUALIZATION_RENDER, context.put(EventBusConstants.EVENT_COMPRESSION_TYPE, COMPRESSION_TYPE_ZERO).put(RESULT, packError(String.format("Report : %s, Got exception while generating report %s", report.getString(Report.REPORT_NAME), exception.getMessage()), context.getLong(QUERY_ID), -1)));
        }
    }

    /**
     * Method used to forecast Capacity Planning
     *
     * @param context Context
     * @param report  Report
     */
    private void composeCapacityPlanningForecastResponse(JsonObject context, JsonObject report)
    {
        try
        {
            var result = new JsonObject();

            var reportContext = report.getJsonObject(Report.REPORT_CONTEXT);

            var stats = new HashMap<String, JsonObject>();

            var columns = new HashSet<String>();

            var thresholdType = reportContext.getString(REPORT_THRESHOLD_TYPE, EMPTY_VALUE);

            reportContext.getJsonArray(REPORT_FORECAST_COLUMN).forEach(entry ->
            {
                var column = CommonUtil.getString(entry);

                columns.add(column);

                columns.add(column + THRESHOLD_COLUMN_SUFFIX);

                columns.add(column + DELTA_COLUMN_SUFFIX);
            });

            // fill last poll data into stats
            for (var recordIndex = 0; recordIndex < context.getJsonArray(EVENT_CONTEXT).size(); recordIndex++)
            {
                var innerContext = context.getJsonArray(EVENT_CONTEXT).getJsonObject(recordIndex);

                if (innerContext.getBoolean(NMSConstants.LAST_POLL_VALUE, false))
                {
                    var response = unpack(Buffer.buffer((innerContext).getBinary(RESULT)), LOGGER, false, innerContext.getJsonObject(QUERY_CONTEXT, null), false, true);

                    var rows = response.getJsonArray(RESULT);

                    if (rows != null && !rows.isEmpty())
                    {
                        for (int index = 0; index < rows.size(); index++)
                        {
                            var row = rows.getJsonObject(index);

                            for (var entry : row.getMap().entrySet())
                            {
                                // in case of instance we will keep key as 1###instance
                                if (entry.getKey().endsWith("^last") && !entry.getKey().equalsIgnoreCase(VisualizationGrouping.MONITOR.getName()) && reportContext.containsKey(INSTANCE))
                                {
                                    var column = entry.getKey().replace(CARET_SEPARATOR, DOT_SEPARATOR);

                                    stats.computeIfAbsent(row.getString(VisualizationGrouping.MONITOR.getName()) + GROUP_SEPARATOR + row.getString(column.split(INSTANCE_SEPARATOR)[0]), k -> new JsonObject()).put(column, entry.getValue());

                                    columns.add(column);
                                }
                                else if (entry.getKey().endsWith("^last") && !reportContext.containsKey(INSTANCE))
                                {
                                    // fill all monitor json object
                                    // we will replace the key as it's required dot separator not caret
                                    var column = entry.getKey().replace(CARET_SEPARATOR, DOT_SEPARATOR);

                                    // Must be separate: in instance mode getLong would run on non-numeric values and throw exception
                                    if (CommonUtil.getLong(entry.getValue()) != Long.MIN_VALUE && CommonUtil.getFloat(entry.getValue()) != -Float.MAX_VALUE)
                                    {
                                        stats.computeIfAbsent(row.getString(VisualizationGrouping.MONITOR.getName()), k -> new JsonObject()).put(column, entry.getValue());
                                    }

                                    columns.add(column);
                                }
                            }
                        }
                    }
                }
                // for dynamic threshold fill threshold values
                else if (thresholdType.equalsIgnoreCase(THRESHOLD_TYPE_DYNAMIC) && innerContext.containsKey(CAPACITY_PLANNING_FORECAST_PARENT_QUERY_ID)) // means this is dynamic threshold forecast
                {
                    var response = unpack(Buffer.buffer((innerContext).getBinary(RESULT)), LOGGER, false, innerContext.containsKey(QUERY_CONTEXT) ? innerContext.getJsonObject(QUERY_CONTEXT) : null, false, true);

                    var rows = response.getJsonArray(RESULT);

                    var column = columns.stream().filter(c -> c.endsWith(THRESHOLD_COLUMN_SUFFIX)).findFirst().orElse(null);

                    if (rows != null && !rows.isEmpty())
                    {
                        for (int index = 0; index < rows.size(); index++)
                        {
                            var row = rows.getJsonObject(index);

                            row.forEach(entry ->
                            {
                                if (!entry.getKey().equalsIgnoreCase(VisualizationGrouping.MONITOR.getName()) && reportContext.containsKey(INSTANCE) && entry.getKey().contains(CARET_SEPARATOR))
                                {
                                    stats.computeIfAbsent(row.getString(VisualizationGrouping.MONITOR.getName()) + GROUP_SEPARATOR + row.getString(column.split(INSTANCE_SEPARATOR)[0]), k -> new JsonObject()).put(column, entry.getValue());
                                }
                                else if (!reportContext.containsKey(INSTANCE))
                                {
                                    // Must be separate: in instance mode getLong would run on non-numeric values and throw exception
                                    if (!entry.getKey().equalsIgnoreCase(VisualizationGrouping.MONITOR.getName()) && (CommonUtil.getLong(entry.getValue()) != Long.MIN_VALUE && CommonUtil.getFloat(entry.getValue()) != -Float.MAX_VALUE))
                                    {
                                        stats.computeIfAbsent(row.getString(VisualizationGrouping.MONITOR.getName()), k -> new JsonObject()).put(column, entry.getValue());// we have added threshold zero already if value is correct will put either it will be zero as usual
                                    }
                                }
                            });
                        }
                    }
                }
            }

            // initialize monitor column in result
            result.put(VisualizationGrouping.MONITOR.getName(), new JsonArray());

            if (reportContext.containsKey(INSTANCE)) // in case of instance report, need to create column for instance name
            {
                result.put(INSTANCE, new JsonArray());
            }

            // initialize all columns in result
            columns.forEach(column -> result.getMap().computeIfAbsent(column, data -> new JsonArray()));

            for (var index = 0; index < context.getJsonArray(EVENT_CONTEXT).size(); index++)
            {
                var innerContext = context.getJsonArray(EVENT_CONTEXT).getJsonObject(index);

                // as we don't need other data we will skip that event context after mapping filled
                if (innerContext.getBoolean(NMSConstants.LAST_POLL_VALUE, false) || (thresholdType.equalsIgnoreCase(THRESHOLD_TYPE_DYNAMIC) && innerContext.containsKey(CAPACITY_PLANNING_FORECAST_PARENT_QUERY_ID)))
                {
                    continue;
                }

                var response = VisualizationConstants.unpack(Buffer.buffer((innerContext).getBinary(GlobalConstants.RESULT)), LOGGER, false, innerContext.getJsonObject(QUERY_CONTEXT, null), false, true);

                LOGGER.debug("forecast failed for " + response.getString(ERROR));

                var timeline = innerContext.getJsonObject(VISUALIZATION_TIMELINE).getString(RELATIVE_TIMELINE).replace("-", EMPTY_VALUE);

                var rows = response.getJsonArray(RESULT);

                if (rows != null && !rows.isEmpty())
                {
                    // Fill stats using the last prediction
                    var row = rows.getJsonObject((rows.size() - 1));

                    if (row != null && !row.isEmpty())
                    {
                        row.getMap().forEach((key, value) ->
                        {
                            if (!key.equalsIgnoreCase(TIME_STAMP) && (CommonUtil.getLong(value) != Long.MIN_VALUE && CommonUtil.getFloat(value) != -Float.MAX_VALUE) && !key.contains("upperbound") && !key.contains("lowerbound"))
                            {
                                var tokens = key.split(CARET_SEPARATOR_WITH_ESCAPE);

                                if (tokens.length == 3)
                                {
                                    // if no monitor has last poll data then this column will be initialized here
                                    columns.add(tokens[1] + LAST_COLUMN_SUFFIX);

                                    result.getMap().computeIfAbsent(tokens[1] + LAST_COLUMN_SUFFIX, v -> new JsonArray());

                                    // if no forecast data then put forecast and delta column as null
                                    if ((response.containsKey(ERROR) && response.getString(ERROR).contains("group: " + tokens[0] + " ") && response.containsKey(RESULT)))
                                    {
                                        stats.computeIfAbsent(tokens[0], v -> new JsonObject()).put(tokens[1] + AFTER_COLUMN_INFIX + timeline, null);

                                        stats.get(tokens[0]).put(tokens[1] + AFTER_COLUMN_INFIX + timeline + DELTA_COLUMN_SUFFIX, null);

                                        // if no forecast data but static capacity planning forecast then put threshold from reportcontext
                                        if (!thresholdType.equalsIgnoreCase(THRESHOLD_TYPE_DYNAMIC))
                                        {
                                            stats.get(tokens[0]).put(tokens[1] + AFTER_COLUMN_INFIX + timeline + THRESHOLD_COLUMN_SUFFIX, reportContext.getLong(REPORT_THRESHOLD_VALUE));
                                        }
                                    }
                                    else
                                    {
                                        stats.computeIfAbsent(tokens[0], k -> new JsonObject()).put(tokens[1] + AFTER_COLUMN_INFIX + timeline, value);

                                        var prediction = stats.get(tokens[0]);

                                        var threshold = stats.get(tokens[0]).getString(tokens[1] + AFTER_COLUMN_INFIX + timeline + THRESHOLD_COLUMN_SUFFIX);

                                        // in case of dynamic we will have threshold value in stats
                                        if (threshold != null && !threshold.isEmpty())
                                        {
                                            prediction.put(tokens[1] + AFTER_COLUMN_INFIX + timeline + DELTA_COLUMN_SUFFIX, Math.max(Long.parseLong(value.toString()) - Long.parseLong(threshold), 0));
                                        }
                                        // if static then calculate delta using static threshold
                                        else if (!thresholdType.equalsIgnoreCase(THRESHOLD_TYPE_DYNAMIC))
                                        {
                                            prediction.put(tokens[1] + AFTER_COLUMN_INFIX + timeline + THRESHOLD_COLUMN_SUFFIX, reportContext.getLong(REPORT_THRESHOLD_VALUE));

                                            prediction.put(tokens[1] + AFTER_COLUMN_INFIX + timeline + DELTA_COLUMN_SUFFIX, Math.max(Long.parseLong(value.toString()) - reportContext.getLong(REPORT_THRESHOLD_VALUE, 0L), 0));
                                        }
                                    }
                                }
                            }
                        });
                    }
                }

            }

            buildResult(context, result, stats, columns);

            EventBusConstants.publish(context.getString(SESSION_ID), EventBusConstants.UI_ACTION_VISUALIZATION_RENDER, context.put(EventBusConstants.EVENT_COMPRESSION_TYPE, COMPRESSION_TYPE_ZERO)
                    .put(RESULT, VisualizationConstants.packGridResult(result, VisualizationConstants.VisualizationCategoryOrdinal.VISUALIZATION_GRID.ordinal(), context.getLong(QUERY_ID), -1).getBytes()));

        }
        catch (Exception exception)
        {
            LOGGER.error(exception);

            EventBusConstants.publish(context.getString(SESSION_ID), EventBusConstants.UI_ACTION_VISUALIZATION_RENDER, context.put(EventBusConstants.EVENT_COMPRESSION_TYPE, COMPRESSION_TYPE_ZERO).put(RESULT, packError(String.format("Report : %s, Got exception while generating report %s", report.getString(Report.REPORT_NAME), exception.getMessage()), context.getLong(QUERY_ID), -1)));
        }
    }

