    // prepare result from stats map
    // if any column value is null or not exist then added insufficient data by default
    private void buildResult(JsonObject context, JsonObject result, HashMap<String, JsonObject> stats, HashSet<String> columns)
    {
        stats.forEach((monitor, data) ->
        {
            // in case of instance we will append monitor and instance separately(1###instance)
            if (result.containsKey(INSTANCE) && monitor.contains(GROUP_SEPARATOR))
            {
                var parts = monitor.split(GROUP_SEPARATOR);

                result.getJsonArray(VisualizationGrouping.MONITOR.getName()).add(parts[0]);

                result.getJsonArray(INSTANCE).add(parts[1]);
            }

            else
            {
                result.getJsonArray(VisualizationGrouping.MONITOR.getName()).add(monitor);
            }

            columns.forEach(column ->
            {
                var value = data.getValue(column);

                if(value != null && !value.toString().isEmpty())
                {
                    result.getJsonArray(column).add(value.toString());
                }
                else
                {
                    if (column.endsWith(LAST_COLUMN_SUFFIX) || column.endsWith(THRESHOLD_COLUMN_SUFFIX))
                    {
                        result.getJsonArray(column).add(NO_DATA);
                    }
                    else
                    {
                        result.getJsonArray(column).add(INSUFFICIENT_DATA);
                    }
                }
            });

        });

        stats.clear(); // clearing stats as it's not required anymore

        if (CommonUtil.traceEnabled())
        {
            LOGGER.trace(String.format("publishing result of report id %s received records %s result %s", context.getLong(ID), result.getJsonArray(VisualizationGrouping.MONITOR.getName()).size(), result));
        }
    }

    /**
     * @param context Context
     * @param report  Report
     */
    private void composeUnhealthyMonitorsResponse(JsonObject context, JsonObject report)
    {
        try
        {
            var result = new JsonObject();

            var template = report.getJsonObject(Report.REPORT_CONTEXT).getJsonObject(TEMPLATE);

            if (context.containsKey(EVENT_CONTEXT) && !context.getJsonArray(EVENT_CONTEXT).isEmpty())
            {
                var eventContext = context.getJsonArray(EVENT_CONTEXT);

                // need to covert row-wise result to column-wise result to packGridResult
                for (var i = 0; i < eventContext.size(); i++)
                {
                    eventContext.getJsonObject(i).forEach(entry -> ((JsonArray) result.getMap().computeIfAbsent(entry.getKey(), value -> new JsonArray())).add(entry.getValue()));
                }

            }

            EventBusConstants.publish(context.getString(SESSION_ID), EventBusConstants.UI_ACTION_VISUALIZATION_RENDER, template.put(EventBusConstants.EVENT_COMPRESSION_TYPE, COMPRESSION_TYPE_ZERO)
                    .put(RESULT, VisualizationConstants.packGridResult(result, VisualizationConstants.VisualizationCategoryOrdinal.VISUALIZATION_GRID.ordinal(), context.getLong(QUERY_ID), -1).getBytes()));

