/**
 * The DailyMiscJobs class is responsible for executing various daily maintenance tasks.
 * <p>
 * This class implements the Quartz Job interface and is annotated with @DisallowConcurrentExecution
 * to ensure that only one instance of this job runs at a time. It performs several maintenance
 * tasks that need to be executed daily:
 * <ul>
 *   <li>Resetting the event ID counter</li>
 *   <li>Running log retention to clean up old logs</li>
 *   <li>Cleaning up the flap cache based on retention policy</li>
 *   <li>Triggering configuration backup cleanup</li>
 * </ul>
 * <p>
 * The job is scheduled to run every day at midnight (12:00 AM).
 */
@DisallowConcurrentExecution
public class DailyMiscJobs implements Job
{
    /**
     * CRON expression for scheduling this job to run every day at midnight (12:00 AM)
     */
    static final String DAILY_MISC_JOBS_CRON_EXPRESSION = "0 0 0 * * ?"; // execute on every day 12:00 AM

    /**
     * Logger for this class
     */
    private static final Logger LOGGER = new Logger(DailyMiscJobs.class, GlobalConstants.MOTADATA_JOB, "System Job");

    private static final String BACKUP_PROFILE_URL = (MotadataConfigUtil.httpsEnabled() ? "https" : "http") + "://" + CommonUtil.getIPAddress() + COLON_SEPARATOR + MotadataConfigUtil.getHTTPServerPort(BootstrapType.APP.name()) + "/settings/system-settings/backup-profiles";


    /**
     * Executes the daily maintenance tasks.
     * <p>
     * This method is called by the Quartz scheduler when the job is triggered. It performs
     * the following tasks:
     * <ol>
     *   <li>Resets the event ID counter to prevent overflow</li>
     *   <li>Runs log retention to delete old log files based on retention policy</li>
     *   <li>Cleans up the flap cache based on retention policy</li>
     *   <li>Triggers configuration backup cleanup</li>
     * </ol>
     *
     * @param context the context in which the job is executed
     */
    @Override
    public void execute(JobExecutionContext context)
    {
        // Reset the event ID counter
        LOGGER.info("resetting event id counter....");
        CommonUtil.resetEventId();
        LOGGER.info("event id counter reset done successfully...");

        // Run log retention
        LOGGER.info(String.format("running log retention job for system boot sequence %s", Bootstrap.bootstrapType()));
        LogUtil.runLogRetention(Bootstrap.bootstrapType() == GlobalConstants.BootstrapType.AGENT ?
                AgentConfigUtil.getAgentLogRetentionDays() :
                MotadataConfigUtil.getLogRetentionDays());
        LOGGER.info("log retention job completed successfully...");

        // Clean up flap cache
        LOGGER.info("flap cache retention job started...");
        cleanupFlapCache(MotadataConfigUtil.getFlapCacheRetentionDays());
        LOGGER.info("flap cache retention job completed successfully...");


        // Trigger configuration backup cleanup
        Bootstrap.vertx().eventBus().send(EventBusConstants.EVENT_CONFIG_BACKUP_CLEANUP,
                DataRetentionPolicyConfigStore.getStore().getItem(GlobalConstants.DEFAULT_ID)
                        .getJsonObject(DataRetentionPolicy.DATA_RETENTION_POLICY_CONTEXT)
                        .getJsonObject("CONFIG"));

        checkBackupConfigurationNotifications();

        if (!MotadataConfigUtil.devMode())
        {
            // manage SLO profile cycles at every midnight
            Bootstrap.vertx().eventBus().send(EventBusConstants.EVENT_SLO_CYCLE_QUALIFY, new JsonObject());
        }
    }

    /**
     * Cleans up flap cache files based on the specified retention period.
     * <p>
     * This method deletes flap cache files that are older than the specified retention period.
     * It calculates the cutoff date based on the retention days and deletes any files created
     * before that date. The creation time of each file is extracted from its filename.
     * <p>
     * Implementation note: This method was added as part of MOTADATA-970 to define code for
     * retaining files within a specific timeline.
     *
     * @param retentionDays the number of days to retain flap cache files (files older than this will be deleted)
     */
    public void cleanupFlapCache(int retentionDays)
    {
        try
        {
            // Only proceed if retention days is valid
            if (retentionDays > GlobalConstants.NOT_AVAILABLE)
            {
                // Get the flap cache directory
                var flapCacheDir = new File(GlobalConstants.CURRENT_DIR + GlobalConstants.PATH_SEPARATOR +
                        "config-db-backups" + GlobalConstants.PATH_SEPARATOR + "flap-caches");

                // Check if the directory exists
                if (flapCacheDir.exists() && flapCacheDir.isDirectory())
                {
                    var files = flapCacheDir.listFiles();

                    if (files != null)
                    {
                        // Calculate the cutoff date (current date minus retention days)

                        var calendar = Calendar.getInstance();

                        calendar.set(Calendar.DATE, calendar.get(Calendar.DATE) - retentionDays);

                        // Set time to beginning of day (00:00:00.000)
                        calendar.set(Calendar.HOUR_OF_DAY, 0);
                        calendar.set(Calendar.MINUTE, 0);
                        calendar.set(Calendar.SECOND, 0);
                        calendar.set(Calendar.MILLISECOND, 0);

                        var cutoffTime = calendar.getTime().getTime();

                        // Process each file in the directory
                        for (var file : files)
                        {
                            try
                            {
                                // Extract creation time from filename (assumed to be the last part before .zip extension)
                                var creationTime = file.getName().split(GlobalConstants.DASH_SEPARATOR)
                                        [file.getName().split(GlobalConstants.DASH_SEPARATOR).length - 1]
                                        .replace(".zip", "");

                                // Delete files older than the cutoff date
                                if (Long.parseLong(creationTime) < cutoffTime)
                                {
                                    FileUtils.deleteQuietly(file);

                                    LOGGER.info(String.format("flap cache file %s deleted...", file));
                                }
                            }
                            catch (Exception exception)
                            {
                                FileUtils.deleteQuietly(file);

                                LOGGER.info(String.format("flap cache file %s deleted...", file));

                                LOGGER.warn(exception);
                            }

                        }
                    }
                }
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

    private void checkBackupConfigurationNotifications()
    {
        try
        {
            LOGGER.info("Starting backup configuration notification check...");

            var entities = BackupProfileConfigStore.getStore().getItems();

            var schedulers = SchedulerConfigStore.getStore().getItemsByValue(Scheduler.SCHEDULER_JOB_TYPE, JobScheduler.JobType.DATABASE_BACKUP.getName());

            for (var i = 0; i < entities.size(); i++)
            {
                var entity = entities.getJsonObject(i);

                var backupProfileType = entity.getString(BackupProfile.BACKUP_PROFILE_TYPE);

                for (var j = 0; j < schedulers.size(); j++)
                {
                    var scheduler = schedulers.getJsonObject(j);

                    if (scheduler.getJsonObject(Scheduler.SCHEDULER_CONTEXT).getJsonArray(NMSConstants.OBJECTS).getLong(0).equals(entity.getLong(ID)))
                    {
                        var storageProfileProtocol = StorageProfileConfigStore.getStore().getItem(entity.getLong(BACKUP_STORAGE_PROFILE)).getString(StorageProfile.STORAGE_PROFILE_PROTOCOL);

                        if (scheduler.getString(Scheduler.SCHEDULER_STATE).equalsIgnoreCase(GlobalConstants.NO))
                        {
                            // Scheduler is disabled
                            sendBackupNotification(backupProfileType,"Action Needed: " + backupProfileType + " backup not configured", String.format(BACKUP_NOT_CONFIGURED, backupProfileType));
                        }
                        else if (storageProfileProtocol != null && storageProfileProtocol.equalsIgnoreCase(StorageProfile.StorageProtocol.LOCAL.getName()))
                        {
                            // Scheduler enabled but uses local storage only
                            sendBackupNotification(backupProfileType, "Improve Resilience: " + backupProfileType + " backups on local storage only",String.format(BACKUP_LOCAL_ONLY, backupProfileType));
                        }

                        break;
                    }
                }
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

    private void sendBackupNotification(String backupProfileType, String subject, String message)
    {
        try
        {
            var user = UserConfigStore.getStore().getItem(DEFAULT_ID,false);

            if (user.getString(User.USER_EMAIL) != null && !user.getString(User.USER_EMAIL).isEmpty())
            {
                Notification.sendEmail(new JsonObject()
                        .put(Notification.EMAIL_NOTIFICATION_ATTACHMENT_DISPOSITION_TYPE, "inline")
                        .put(Notification.EMAIL_NOTIFICATION_ATTACHMENT_TYPE, "image/png")
                        .put(Notification.EMAIL_NOTIFICATION_ATTACHMENTS,
                                new JsonArray().add("information.png").addAll(Notification.EMAIL_NOTIFICATION_INLINE_ATTACHMENT_ICONS))
                        .put(Notification.EMAIL_NOTIFICATION_SUBJECT, subject)
                        .put(Notification.EMAIL_NOTIFICATION_RECIPIENTS, new JsonArray().add(user.getString(User.USER_EMAIL)))
                        .put(Notification.TEMPLATE_NAME, EMAIL_NOTIFICATION_BACKUP_CONFIG_ALERT_TEMPLATE)
                        .put(Notification.EMAIL_NOTIFICATION_CONTENT, new JsonObject()
                                .put(BACKUP_PROFILE_TYPE, backupProfileType)
                                .put(MESSAGE, message)
                                .put("configure.backup.url", BACKUP_PROFILE_URL)));

                LOGGER.info("Email has been sent to user");
            }

            if (user.containsKey(User.USER_MOBILE) && user.getString(User.USER_MOBILE) != null && !user.getString(User.USER_MOBILE).equalsIgnoreCase("0"))
            {
                Notification.sendSMS(message, new JsonArray().add(user.getString(User.USER_MOBILE)));
            }

            // Send UI sticky notification
            EventBusConstants.publish(UI_NOTIFICATION_BACKUP_CONFIG_ALERT, new JsonObject().put(BACKUP_PROFILE_TYPE, backupProfileType).put(SEVERITY, INFO).put(MESSAGE, message).put("configure.backup.url", BACKUP_PROFILE_URL));

            Bootstrap.vertx().eventBus().send(EVENT_AUDIT_WRITE, new JsonObject()
                    .put(AUDIT_MODULE, SYSTEM_HEATH)
                    .put(AUDIT_OPERATION, VIEW)
                    .put(AUDIT_MESSAGE, String.format(ENTITY_UPDATED, SYSTEM_HEATH) + GlobalConstants.NEW_LINE +
                            new JsonObject().put("new.prop.value", new JsonObject()
                                    .put(MANAGER_UUID,Bootstrap.getRegistrationId()).put(INSTALLATION_MODE,Bootstrap.getInstallationMode())
                                    .put(BACKUP_PROFILE_TYPE, backupProfileType)
                                    .put(MESSAGE, message)
                                    .put("configure.backup.url", BACKUP_PROFILE_URL)
                                    .put(TIME_STAMP, DateTimeUtil.currentSeconds())
                                    .put(TIME,DateTimeUtil.getScheduledTimestamp(DateTimeUtil.currentMilliSeconds())))));

        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }
}

