/**
 * The DatastoreRetentionJob class is responsible for managing data retention in the Motadata platform.
 * <p>
 * This class implements the Quartz Job interface and performs two main tasks:
 * <ul>
 *   <li>Triggering datastore retention by publishing an event to the event bus</li>
 *   <li>Cleaning up cache files based on a configurable retention policy</li>
 * </ul>
 * <p>
 * The job is scheduled to run every day at midnight (12:00 AM) to ensure that
 * old data is regularly purged from the system, preventing excessive disk usage
 * and maintaining system performance.
 */
public class DatastoreRetentionJob implements Job
{
    /**
     * CRON expression for scheduling this job to run every day at midnight (12:00 AM)
     */
    public static final String DATASTORE_RETENTION_JOB_CRON_EXPRESSION = "0 0 0 ? * * *"; // At 00:00:00am every day

    /**
     * Logger for this class
     */
    private static final Logger LOGGER = new Logger(DatastoreRetentionJob.class, GlobalConstants.MOTADATA_JOB, "Datastore Retention Job");

    /**
     * Executes the datastore retention job.
     * <p>
     * This method performs two main tasks:
     * <ol>
     *   <li>Triggers datastore event retention by publishing an event to the event bus</li>
     *   <li>Cleans up cache files based on the configured retention policy</li>
     * </ol>
     * <p>
     * The datastore retention is handled by other components that listen for the
     * EVENT_DATASTORE_RETENTION_TRIGGER event. The cache file cleanup is handled
     * directly by this class through the {@link #cleanup(long)} method.
     *
     * @param context the context in which the job is executed
     * @throws JobExecutionException if an error occurs during job execution
     */
    @Override
    public void execute(JobExecutionContext context) throws JobExecutionException
    {
        try
        {
            var currentTimeMillis = System.currentTimeMillis();

            // Trigger datastore event retention by publishing an event
            LOGGER.info("executing datastore retention job...");
            Bootstrap.vertx().eventBus().publish(EVENT_DATASTORE_RETENTION_TRIGGER, null);

            // Clean up cache files based on retention policy
            LOGGER.info("cache file clean up job started ....");
            cleanup(currentTimeMillis);
            LOGGER.info("cache file clean up job completed ....");

            LOGGER.info("slo cycle clean up job started ....");
            cleanupSLOCycles(currentTimeMillis);
            LOGGER.info("slo cycle clean up job completed ....");
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

    /**
     * Cleans up cache files based on the configured retention policy.
     * <p>
     * This method deletes cache files that are older than the retention period
     * configured in the system. It works by:
     * <ol>
     *   <li>Creating a set of dates to exclude from deletion (recent dates within the retention period)</li>
     *   <li>Checking each file in the cache directory</li>
     *   <li>Deleting files that don't match the excluded dates</li>
     * </ol>
     * <p>
     * The retention period is determined by {@link MotadataConfigUtil#getCacheFilesRetentionDays()}.
     */
    private void cleanup(long currentTimeMillis)
    {
        try
        {
            // Create a set of dates to exclude from deletion (files within retention period)
            var excludeDates = new HashSet<String>();

            // Get the date format used in cache file names
            var formatter = new SimpleDateFormat(DateTimeUtil.CORRELATED_METRIC_CACHE_FILE_TIMESTAMP_FORMAT);

            // Build a set of formatted dates to keep (one for each day in the retention period)
            while (excludeDates.size() != MotadataConfigUtil.getCacheFilesRetentionDays())
            {
                // Add the formatted date to the exclusion set
                excludeDates.add(formatter.format(new Date(currentTimeMillis)));

                // Move back one day (86400000 milliseconds = 24 hours)
                currentTimeMillis -= 86400000;
            }

            // Get the cache directory
            var cacheDir = new File(CURRENT_DIR + PATH_SEPARATOR + CACHE_DIR);

            var fileNames = new JsonArray();

            if (cacheDir.exists())
            {
                var files = cacheDir.listFiles();

                if (files != null)
                {
                    for (var file : files)
                    {
                        if (!file.getName().endsWith(CORRELATION_MAP))
                        {
                            // Split the filename by dash to extract the date components
                            var tokens = file.getName().split(DASH_SEPARATOR);

                            // Check if the file has enough tokens and its date is not in the exclusion set
                            if (tokens.length >= 3 && !excludeDates.contains(
                                    tokens[tokens.length - 3] + DASH_SEPARATOR +
                                            tokens[tokens.length - 2] + DASH_SEPARATOR +
                                            tokens[tokens.length - 1]))
                            {
                                // Log and delete files outside the retention period
                                LOGGER.info(String.format("cache file deleted : %s ", file.getName()));

                                fileNames.add(file.getName());

                                file.delete();
                            }
                        }
                    }
                }
            }

            Bootstrap.vertx().eventBus().send(EVENT_AUDIT_WRITE,new JsonObject().put(AUDIT_MODULE,SYSTEM_HEATH).put(AUDIT_OPERATION,VIEW)
                    .put(AUDIT_MESSAGE,String.format(String.format(ENTITY_UPDATED, SYSTEM_HEATH) + GlobalConstants.NEW_LINE +
                            new JsonObject().put("new.prop.value",new JsonObject()
                                    .put(MANAGER_UUID,Bootstrap.getRegistrationId())
                                    .put(INSTALLATION_MODE,MotadataConfigUtil.getInstallationMode())
                                    .put(FILE_NAME,fileNames)
                                    .put(ENTITY_PROPERTY_COUNT,fileNames.size())
                                    .put("retention.days",MotadataConfigUtil.getCacheFilesRetentionDays())
                                    .put(TIME_STAMP,DateTimeUtil.currentSeconds())
                                    .put(TIME,DateTimeUtil.getScheduledTimestamp(DateTimeUtil.currentMilliSeconds()))
                                    .put(MESSAGE,"Retention ran for cache files").encodePrettily()))));
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

    private void cleanupSLOCycles(long currentTimeMillis)
    {
        try
        {
            var context = DataRetentionPolicyConfigStore.getStore().getItem().getJsonObject(DataRetentionPolicy.DATA_RETENTION_POLICY_CONTEXT);

            if (context != null && !context.isEmpty())
            {
                var sloMetric = context.getJsonObject(DatastoreConstants.DatastoreType.SLO_METRIC.name());

                if (sloMetric != null && !sloMetric.isEmpty())
                {
                    var sloProfiles = SLOProfileConfigStore.getStore().getItems();

                    for (var index = 0; index < sloProfiles.size(); index++)
                    {
                        var sloProfile = sloProfiles.getJsonObject(index);

                        var profileContext = sloProfile.getJsonObject(SLOProfile.SLO_PROFILE_CONTEXT);

                        if (profileContext != null && !profileContext.isEmpty())
                        {
                            var frequency = profileContext.getString(SLOProfile.SLO_FREQUENCY);

                            var days = sloMetric.getJsonObject(frequency).getInteger("raw");

                            var ids = qualifyCycles(sloProfile.getLong(ID), days, currentTimeMillis);

                            var cycleId = sloProfile.getLong(SLOCycle.SLO_CYCLE_ID);

                            if (ids.contains(cycleId))
                            {
                                LOGGER.info("removing current cycle id " + cycleId + " from the qualified list of retention " + ids);

                                ids.remove(cycleId);
                            }

                            if (!ids.isEmpty())
                            {
                                Bootstrap.configDBService().deleteAll(DBConstants.TBL_SLO_CYCLE,
                                        new JsonObject().put(DBConstants.FIELD_NAME, ID).put(VALUE, ids),
                                        SYSTEM_USER, SYSTEM_REMOTE_ADDRESS,
                                        result->
                                        {
                                            if (result.succeeded())
                                            {
                                                SLOCycleConfigStore.getStore().deleteItems(ids);

                                                LOGGER.info("slo cycles deleted " + ids);
                                            }
                                            else
                                            {
                                                LOGGER.error(result.cause());

                                                LOGGER.warn("failed to delete slo cycles " + ids);
                                            }
                                        });
                            }
                        }
                    }
                }
                else
                {
                    LOGGER.warn("slo metric not found in data retention policy context");
                }
            }
            else
            {
                LOGGER.warn("data retention policy context not found");
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

    private JsonArray qualifyCycles(long sloId, int days, long currentTimeMillis)
    {
        var cycles = new JsonArray();

        try
        {
            var sloCycles = SLOCycleConfigStore.getStore().getItemsByValue(SLOProfile.SLO_PROFILE_ID, sloId);

            var startTime = (currentTimeMillis / 1000) - TimeUnit.DAYS.toSeconds(days);

            for (var index = 0; index < sloCycles.size(); index++)
            {
                var sloCycle = sloCycles.getJsonObject(index);

                if (sloCycle.getLong(SLOCycle.SLO_CYCLE_START_TIME) < startTime)
                {
                    LOGGER.info(String.format("slo cycle id %s having start time %s which is less then the retention time %s for the slo id %s", sloCycle.getLong(ID), sloCycle.getLong(SLOCycle.SLO_CYCLE_START_TIME), startTime, sloId));

                    cycles.add(sloCycle.getLong(ID));
                }
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }

        LOGGER.info("cycles qualified for slo id " + sloId + " : " + cycles);

        return cycles;
    }
}

