package com.mindarray.ha;

import com.mindarray.GlobalConstants;
import com.mindarray.eventbus.EventBusConstants;
import com.mindarray.util.CommonUtil;
import com.mindarray.util.Logger;
import com.mindarray.util.MotadataConfigUtil;
import com.mindarray.util.PortUtil;
import io.vertx.core.AbstractVerticle;
import io.vertx.core.Promise;
import io.vertx.core.json.JsonObject;

import java.util.concurrent.atomic.AtomicInteger;

import static com.mindarray.GlobalConstants.*;
import static com.mindarray.eventbus.EventBusConstants.*;

public class HAManager extends AbstractVerticle
{
    private static final Logger LOGGER = new Logger(HAManager.class, MOTADATA_HA, "HA Manager");

    @Override
    public void start(Promise<Void> promise) throws Exception
    {
        if (MotadataConfigUtil.getRemoteEventSecondaryReceiver() != null && !MotadataConfigUtil.getRemoteEventSecondaryReceiver().isEmpty())
        {
            LOGGER.info(String.format("switch over engine starting with installation mode : %s , ha mode : %s ", MotadataConfigUtil.getInstallationMode(), MotadataConfigUtil.getHAMode()));

            // when secondary becomes primary and if any one stopped service or restart then we need to check for primary is up or not.

            if (MotadataConfigUtil.getInstallationMode().equalsIgnoreCase(GlobalConstants.InstallationMode.PRIMARY.name()) && MotadataConfigUtil.getHAMode() != null && MotadataConfigUtil.getHAMode().equalsIgnoreCase(GlobalConstants.HAMode.PASSIVE.name()))
            {
                vertx.setTimer(180000, timer -> isPrimaryUp());
            }
            else
            {
                vertx.setTimer(180000, timer -> isPrimaryDown());
            }

            promise.complete();
        }
        else
        {
            promise.fail("Failed to deploy switch over engine , reason : fail over key is missing ");
        }

    }

    private void isPrimaryDown()
    {
        try
        {
            LOGGER.info(String.format("verifying primary is down or not .... with inspection time : %s and retries value : %s ", MotadataConfigUtil.getHAPrimaryNodeHealthInspectionTimerSeconds(), MotadataConfigUtil.getHAPrimaryNodePingRetries()));

            var retries = new AtomicInteger(0);

            var promise = Promise.<Void>promise();

            vertx.setPeriodic(MotadataConfigUtil.getHAPrimaryNodeHealthInspectionTimerSeconds(), timer ->
            {
                try
                {
                    if (!PortUtil.isConnected(CommonUtil.getRemoteEventSender(), MotadataConfigUtil.getEventSenderPort(MotadataConfigUtil.getEventRemoteProcessorSenderProtocol()), 2000))
                    {
                        retries.getAndIncrement();

                        LOGGER.info(String.format("Primary is found DOWN , address is : %s ", MotadataConfigUtil.getEventSenderPort(MotadataConfigUtil.getEventRemoteProcessorSenderProtocol()) + ":" + CommonUtil.getRemoteEventSender()));

                        if (retries.get() >= MotadataConfigUtil.getHAPrimaryNodePingRetries() && !promise.future().isComplete())
                        {
                            LOGGER.info(String.format("Primary is found DOWN  with retries value %s ", retries.get()));

                            vertx.cancelTimer(timer);

                            promise.complete();

                            switchOver();

                            isPrimaryUp();
                        }
                    }
                    else
                    {
                        retries.set(0);
                    }
                }
                catch (Exception exception)
                {
                    LOGGER.error(exception);
                }
            });
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

    private void isPrimaryUp()
    {
        try
        {
            LOGGER.info(String.format("verifying primary is up or not ..... with inspection time : %s and flap value : %s ", MotadataConfigUtil.getHAPrimaryNodeHealthInspectionTimerSeconds(), MotadataConfigUtil.getHAPrimaryNodePingRetries()));

            var retries = new AtomicInteger(0);

            var promise = Promise.<Void>promise();

            vertx.setPeriodic(MotadataConfigUtil.getHAPrimaryNodeHealthInspectionTimerSeconds(), timer ->
            {
                if (PortUtil.isConnected(MotadataConfigUtil.getRemoteEventSecondaryReceiver(), MotadataConfigUtil.getEventSenderPort(MotadataConfigUtil.getEventRemoteProcessorSenderProtocol()), 2000))
                {
                    retries.getAndIncrement();

                    LOGGER.info(String.format("primary is UP , address is : %s ", MotadataConfigUtil.getRemoteEventSecondaryReceiver() + ":" + MotadataConfigUtil.getEventSenderPort(MotadataConfigUtil.getEventRemoteProcessorSenderProtocol())));

                    if (retries.get() >= MotadataConfigUtil.getHAPrimaryNodePingRetries() && !promise.future().isComplete())
                    {
                        LOGGER.info(String.format("primary is UP with flap value %s ,  address is : %s  ", retries.get(), MotadataConfigUtil.getRemoteEventSecondaryReceiver() + ":" + MotadataConfigUtil.getEventSenderPort(MotadataConfigUtil.getEventRemoteProcessorSenderProtocol())));

                        promise.complete();

                        vertx.cancelTimer(timer);

                        switchOver();

                        isPrimaryDown();
                    }
                }
                else
                {
                    retries.set(0);
                }
            });
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

    private void switchOver()
    {
        try
        {
            LOGGER.info(String.format("switch over for %s and installation mode %s ", MotadataConfigUtil.getSystemBootstrapType(), MotadataConfigUtil.getInstallationMode()));

            switch (InstallationMode.valueOf(MotadataConfigUtil.getInstallationMode()))
            {
                case PRIMARY ->
                {
                    if (!MotadataConfigUtil.getVIPCommand().isEmpty() || MotadataConfigUtil.isHAOverWAN())
                    {
                        switchOver(InstallationMode.PRIMARY, InstallationMode.SECONDARY);
                    }
                    else
                    {
                        LOGGER.warn("can not perform switch over , reason : vip.command not found");
                    }
                }
                case SECONDARY ->
                {
                    if (!MotadataConfigUtil.getVIPCommand().isEmpty() || MotadataConfigUtil.isHAOverWAN())
                    {
                        switchOver(InstallationMode.SECONDARY, InstallationMode.PRIMARY);
                    }
                    else
                    {
                        LOGGER.warn("can not perform switch over , reason : vip.command not found");
                    }
                }

                case FAILOVER -> switchOver(InstallationMode.FAILOVER, InstallationMode.FAILOVER);

                default ->
                {
                    // do nothing
                }
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

    private void switchOver(GlobalConstants.InstallationMode previousMode, GlobalConstants.InstallationMode currentMode)
    {
        try
        {
            if (previousMode.equals(GlobalConstants.InstallationMode.PRIMARY) && currentMode.equals(GlobalConstants.InstallationMode.SECONDARY))
            {
                LOGGER.info("while SECONDARY switching from PRIMARY to SECONDARY , detaching vip from SECONDARY");

                HAConstants.switchOverIP(HAConstants.HASyncOperation.DETACH.getName());
            }

            vertx.eventBus().send(EVENT_REMOTE, new JsonObject()
                    .put(SYSTEM_BOOTSTRAP_TYPE, GlobalConstants.BootstrapType.APP)
                    .put(INSTALLATION_MODE, currentMode)
                    .put(EVENT_TYPE, EVENT_SWITCH_OVER)
                    .put(EventBusConstants.EVENT_CONFIG_CHANGE, new JsonObject()
                            .put(SYSTEM_BOOTSTRAP_TYPE, BootstrapType.APP.name())
                            .put(INSTALLATION_MODE, currentMode)
                            .put(EVENT_PUBLISHER_HOST, MotadataConfigUtil.getRemoteEventSecondaryReceiver())
                            .put(EVENT_SUBSCRIBER_HOST, MotadataConfigUtil.getRemoteEventSecondaryReceiver())
                            .put(EVENT_SUBSCRIBER_SECONDARY_HOST, MotadataConfigUtil.getRemoteEventSender())));

            vertx.eventBus().send(EVENT_REMOTE, new JsonObject()
                    .put(SYSTEM_BOOTSTRAP_TYPE, BootstrapType.APP)
                    .put(EVENT_TYPE, EVENT_REMOTE_PROCESSOR_RESTART));

            vertx.eventBus().send(EVENT_REMOTE, new JsonObject()
                    .put(SYSTEM_BOOTSTRAP_TYPE, BootstrapType.AGENT)
                    .put(EVENT_TYPE, EVENT_AGENT_RESTART));

            if (MotadataConfigUtil.getInstallationType() == 0)
            {
                vertx.eventBus().send(EVENT_REMOTE, new JsonObject()
                        .put(SYSTEM_BOOTSTRAP_TYPE, BootstrapType.DATASTORE)
                        .put(EVENT_TYPE, EVENT_REMOTE_PROCESSOR_RESTART));
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

    @Override
    public void stop(Promise<Void> promise) throws Exception
    {
        promise.complete();
    }
}

