public class ConfigUpgradeManager extends AbstractVerticle
{
    private static final Logger LOGGER = new Logger(ConfigUpgradeManager.class, GlobalConstants.MOTADATA_CONFIGURATION, "Config Upgrade Manager");

    private EventEngine eventEngine;

    @Override
    public void start(Promise<Void> promise) throws Exception
    {
        var replyTopic = config().getString(EventBusConstants.EVENT_TYPE) + EventBusConstants.EVENT_REPLY;

        eventEngine = new EventEngine()
                .setEventType(config().getString(EventBusConstants.EVENT_TYPE))
                .setBlockingEvent(true)
                .setEventQueueSize(1)
                .setPersistEventOffset(true)
                .setLogger(LOGGER)
                .setEventHandler(event -> upgrade(event).onComplete(result ->
                {

                    LOGGER.info("Upgrade Completed : " + event.getString(AIOpsObject.OBJECT_IP));

                    if (result.succeeded())
                    {
                        vertx.eventBus().send(replyTopic, event);
                    }
                    else
                    {
                        LOGGER.warn(result.cause());
                    }
                })).start(vertx, promise);
    }

    private Future<Void> upgrade(JsonObject event)
    {
        var promise = Promise.<Void>promise();

        Bootstrap.vertx().<JsonObject>executeBlocking(future ->
        {
            try
            {
                LOGGER.info(String.format("Config upgrade event received : %s", event.encode()));

                event.put(NMSConstants.STATE, ConfigConstants.ConfigOperationState.IN_PROGRESS.getName()).put(EventBusConstants.EVENT_TYPE, EventBusConstants.EVENT_PLUGIN_ENGINE);

                if (Bootstrap.bootstrapType().name().equalsIgnoreCase(BootstrapType.COLLECTOR.name()))
                {
                    Bootstrap.vertx().eventBus().send(EventBusConstants.EVENT_REMOTE, event);
                }
                else
                {
                    EventBusConstants.publish(EventBusConstants.EVENT_CONFIG_REQUEST_STATE_CHANGE, event); // Used in UI to show firmware upgrade progress

                    ConfigurationCacheStore.getStore().updateOperation(event.getLong(ID), ConfigConstants.ConfigOperation.UPGRADE, event.getString(NMSConstants.STATE));
                }

                if (NMSConstants.Category.NETWORK.getName().equals(event.getString(AIOpsObject.OBJECT_CATEGORY)))
                {
                    WorkerUtil.spawnWorker(
                            new HashMap<>(Map.of(event.getLong(EventBusConstants.EVENT_ID), event)),
                            event,
                            new ArrayList<>(List.of(event.getLong(EventBusConstants.EVENT_ID))),
                            event.getInteger(TIMEOUT),
                            false,
                            PluginEngineConstants.PluginEngine.GO,
                            System.currentTimeMillis(),
                            true
                    );
                }

                future.complete();
            }
            catch (Exception exception)
            {
                LOGGER.error(exception);

                if (exception.getMessage() != null && exception.getMessage().contains(ErrorMessageConstants.PROCESS_TIMED_OUT))
                {
                    event.put(STATUS, STATUS_FAIL)
                            .put(MESSAGE, String.format(ErrorMessageConstants.CONFIG_UPGRADE_FAILED, exception.getMessage()))
                            .put(ERROR_CODE, ErrorCodes.ERROR_CODE_PROCESS_TIMEOUT)
                            .put(ERROR, CommonUtil.formatStackTrace(exception.getStackTrace()));
                }

                else
                {
                    event.put(STATUS, STATUS_FAIL)
                            .put(MESSAGE, String.format(ErrorMessageConstants.CONFIG_UPGRADE_FAILED, exception.getMessage()))
                            .put(ERROR_CODE, ErrorCodes.ERROR_CODE_INTERNAL_ERROR)
                            .put(ERROR, CommonUtil.formatStackTrace(exception.getStackTrace()));
                }

                if (MotadataConfigUtil.devMode())
                {
                    Bootstrap.vertx().eventBus().send("config.response.processor.test", event);
                }

                Bootstrap.vertx().eventBus().send(Bootstrap.bootstrapType() == BootstrapType.COLLECTOR ? EventBusConstants.EVENT_REMOTE : EventBusConstants.EVENT_CONFIG_RESPONSE_PROCESSOR, event);

                future.fail(exception);
            }
        }).onComplete(result -> promise.complete());

        return promise.future();
    }

    @Override
    public void stop(Promise<Void> promise) throws Exception
    {
        eventEngine.stop(vertx, promise);
    }
}

