/**
 * ConfigOperationTracker is responsible for maintaining and managing configuration-related cache and operations.
 * <p>
 * This class serves as a central component for tracking and processing configuration operations such as backup,
 * restore, and other configuration management tasks. It maintains counters for operation statuses (total, succeeded, failed)
 * and handles notification delivery when operations complete.
 * <p>
 * The engine works as a Vert.x verticle that listens for configuration events on the event bus and processes them
 * accordingly. It supports both standalone operations and operations with post-processing steps.
 * <p>
 * Key responsibilities:
 * - Track progress of configuration operations
 * - Validate when operations are complete
 * - Send notifications about operation results
 * - Manage cleanup of completed operations
 */
public class ConfigOperationTracker extends AbstractVerticle
{
    /**
     * Constant representing the post-backup operation type
     */
    public static final String POST_BACKUP = "post.backup";
    /**
     * Logger instance for this class
     */
    private static final Logger LOGGER = new Logger(ConfigOperationTracker.class, MOTADATA_CONFIGURATION, "Config Operation Tracker");
    /**
     * Interval in seconds at which the configuration scheduler sends notification signals.
     */
    private static final int CONFIG_BACKUP_QUEUE_FLUSH_TIMER_SECONDS = MotadataConfigUtil.getConfigBackupQueueFlushTimerSeconds();
    /**
     * StringBuilder used for building group hierarchy strings for notifications
     */
    private final StringBuilder builder = new StringBuilder();
    /**
     * Map that tracks the status of configuration operations.
     * Structure:
     * - Key: Operation ID (Long)
     * - Value: Map of operation types to their status counters
     * - Inner Key: Operation type (String)
     * - Inner Value: JsonObject containing counters (total, succeeded, failed)
     */
    private final Map<Long, Map<String, JsonObject>> probes = new HashMap<>();
    /**
     * Set of qualified configuration item IDs pending for backup processing.
     * <p>
     * This set is populated by configuration change events and processed periodically
     * to trigger backup operations for the qualified items.
     */
    private final Set<Long> queuedItems = new HashSet<>();

    /**
     * Initializes the ConfigOperationTracker verticle.
     * <p>
     * Sets up an event bus consumer that listens for configuration notification events
     * and processes them through the {@link #dequeue(JsonObject)} method.
     *
     * @param promise Promise to be completed when initialization is done
     * @throws Exception If an error occurs during initialization
     */
    @Override
    public void start(Promise<Void> promise) throws Exception
    {
        vertx.eventBus().<JsonObject>localConsumer(EventBusConstants.EVENT_CONFIG_NOTIFICATION, message -> dequeue(message.body()));

        vertx.eventBus().<JsonObject>localConsumer(EventBusConstants.EVENT_CONFIG_CHANGE_REQUEST_ENQUEUE, message -> enqueue(message.body()));

        vertx.setPeriodic(CONFIG_BACKUP_QUEUE_FLUSH_TIMER_SECONDS * 1000L, timer -> dequeue());

        if (MotadataConfigUtil.devMode())
            vertx.eventBus().<JsonObject>localConsumer("test.config.backup.queue.timer", message -> dequeue());

        promise.complete();
    }

    /**
     * Main entry point for processing configuration events received from the event bus.
     * <p>
     * This method examines the incoming event and routes it to the appropriate processing
     * method based on the probe type. It handles both "TOTAL" type events (which set up
     * the expected operation counts) and status update events (which track progress).
     * <p>
     * After processing, it removes temporary probe-related fields from the event.
     *
     * @param event The configuration event to process, containing operation details and probe information
     */
    public void dequeue(JsonObject event)
    {
        try
        {
            if (event.containsKey(ConfigConstants.CONFIG_OPERATION_ID) && CommonUtil.isNotNullOrEmpty(event.getString(ConfigConstants.CONFIG_OPERATION)))
            {
                if (event.getString(ConfigConstants.PROBE_TYPE).equalsIgnoreCase(TOTAL_PROBES))
                {
                    complete(event);
                }
                else
                {
                    update(event);
                }

                // Clean up temporary fields after processing
                event.remove(ConfigConstants.PROBE_TYPE);

                event.remove(ConfigConstants.PROBE_COUNT);
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

    /**
     * Validates if a bulk operation is complete and triggers notifications if it is.
     * <p>
     * This method checks if the total count of operations equals the sum of succeeded and failed operations,
     * indicating that the operation is complete. When an operation is complete, it:
     * 1. Updates the event with success/failure counts
     * 2. Sets up execution mode information
     * 3. Handles special cases for post-operations
     * 4. Sends notifications to users
     * 5. Cleans up the tracking data
     *
     * @param id        The unique identifier for the operation
     * @param operation The type of operation being validated
     * @param event     The event object containing operation details
     * @return true if the operation is complete and notifications were sent, false otherwise
     */
    public boolean validate(long id, String operation, JsonObject event)
    {
        try
        {
            if (probes.containsKey(id))
            {
                var context = this.probes.get(id).get(operation);

                // Check if operation is complete (total = succeeded + failed)
                if (context != null && context.getInteger(TOTAL_PROBES) != DUMMY_NUMERIC_VALUE &&
                        context.getInteger(TOTAL_PROBES) == context.getInteger(STATUS_SUCCEEDED) + context.getInteger(STATUS_FAILED))
                {
                    // Handle special case for post-backup operations
                    if (operation.equalsIgnoreCase(POST_BACKUP))
                        event.put(ConfigConstants.CONFIG_OPERATION, ConfigConstants.ConfigOperation.BACKUP.getName());

                    // Update event with operation results
                    event.put(STATUS_SUCCEEDED, context.getInteger(STATUS_SUCCEEDED))
                            .put(STATUS_FAILED, context.getInteger(STATUS_FAILED))
                            .put("execution.mode", (event.containsKey(Scheduler.SCHEDULER_TIMELINE) &&
                                    !event.getString(Scheduler.SCHEDULER_TIMELINE).isEmpty() ?
                                    String.format("Schedule: %s", event.getString(Scheduler.SCHEDULER_TIMELINE)) :
                                    "Manual"));

                    // Handle special case for operations with dummy success value
                    if (context.getInteger(STATUS_SUCCEEDED).equals(DUMMY_NUMERIC_VALUE))
                    {
                        // Determine the post-operation type
                        var operationType = operation.equalsIgnoreCase(ConfigConstants.ConfigOperation.BACKUP.getName()) &&
                                CommonUtil.isNotNullOrEmpty(event.getString(ConfigConstants.CONFIG_POST_OPERATION)) ?
                                event.getString(ConfigConstants.CONFIG_POST_OPERATION) :
                                POST_BACKUP;

                        // Mark the post-operation as having a dummy total value
                        getCounts(id, operationType).put(TOTAL_PROBES, DUMMY_NUMERIC_VALUE);

                        if (operation.equalsIgnoreCase(ConfigConstants.ConfigOperation.BACKUP.getName()) &&
                                event.containsKey(ConfigConstants.CONFIG_POST_OPERATION) &&
                                CommonUtil.isNotNullOrEmpty(event.getString(ConfigConstants.CONFIG_POST_OPERATION)))
                        {
                            getCounts(id, POST_BACKUP).put(TOTAL_PROBES, DUMMY_NUMERIC_VALUE);
                        }
                    }

                    // In development mode, send notification via event bus
                    if (MotadataConfigUtil.devMode())
                    {
                        Bootstrap.vertx().eventBus().send("config.mail.notification", event);
                    }

                    LOGGER.debug(String.format("triggered mail/sms for operation : %s , event : %s",
                            operation, getCounts(event.getLong(ConfigConstants.CONFIG_OPERATION_ID, DUMMY_ID), operation)));

                    // Send notifications to users
                    notify(event);

                    // Clean up tracking data for this operation
                    remove(id, operation);

                    return true;
                }
            }

            return false;
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }

        return false;
    }

    /**
     * Updates the counter for a specific operation and count type.
     * <p>
     * This method increments (or in special cases, maintains) the counter for a specific operation type
     * and status (total, succeeded, or failed). It handles special cases for the TOTAL counter type
     * and validates if the operation is complete after updating the counter.
     * <p>
     * The method creates the necessary data structures if they don't exist yet, ensuring that
     * all counters are properly initialized before updating.
     *
     * @param operation The type of operation being tracked (e.g., "backup", "restore")
     * @param type      The counter type to update (TOTAL, STATUS_SUCCEEDED, or STATUS_FAILED)
     * @param event     The event containing operation details
     * @param count     The amount to increment the counter by (can be negative)
     */
    public void update(String operation, String type, JsonObject event, Integer count)
    {
        try
        {
            var id = event.getLong(ConfigConstants.CONFIG_OPERATION_ID, DUMMY_ID);

            if (!id.equals(DUMMY_ID))
            {
                // Initialize the counter structure if it doesn't exist
                probes.computeIfAbsent(id, value -> new HashMap<>())
                        .computeIfAbsent(operation, value -> new JsonObject()
                                .put(TOTAL_PROBES, 0)
                                .put(STATUS_SUCCEEDED, 0)
                                .put(STATUS_FAILED, 0));

                // Special handling for TOTAL counter type
                // Avoid updating the TOTAL count if it is already set (greater than 0).
                // A count of -1 is used specifically in CONFIG_MANAGEMENT when it's turned off,
                // so we should not reduce the TOTAL value in such cases.
                if (type.equalsIgnoreCase(TOTAL_PROBES) && probes.get(id).get(operation).getInteger(type) > 0 && count != -1)
                {
                    // Maintain the existing TOTAL value
                    probes.get(id).get(operation).put(type, probes.get(id).get(operation).getInteger(type));
                }
                else
                {
                    // Increment the counter by the specified amount
                    probes.get(id).get(operation).put(type, probes.get(id).get(operation).getInteger(type) + count);
                }

                LOGGER.debug(String.format("Updated %s probe count successfully for operation : %s with map : %s",
                        type, operation, getCounts(id, operation)));

                // Check if the operation is now complete
                validate(id, operation, event);
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

    /**
     * Retrieves the counter information for a specific operation.
     * <p>
     * This method returns a JsonObject containing the counters (total, succeeded, failed)
     * for the specified operation ID and operation type. If the counters don't exist yet,
     * it initializes them with default values (0 for each counter).
     *
     * @param id        The unique identifier for the operation
     * @param operation The type of operation to get counters for
     * @return A JsonObject containing the counter values, or an empty JsonObject if an error occurs
     */
    public JsonObject getCounts(long id, String operation)
    {
        try
        {
            // Initialize the counter structure if it doesn't exist and return it
            probes.computeIfAbsent(id, value -> new HashMap<>())
                    .computeIfAbsent(operation, value -> new JsonObject()
                            .put(TOTAL_PROBES, 0)
                            .put(STATUS_SUCCEEDED, 0)
                            .put(STATUS_FAILED, 0));

            return probes.get(id).get(operation);
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }

        // Return empty object in case of error
        return new JsonObject();
    }

    /**
     * Removes tracking data for a completed operation.
     * <p>
     * This method cleans up the tracking data for a specific operation after it has been
     * completed and processed. It removes the operation entry from the tracking map and,
     * if no more operations are being tracked for the given ID, removes the ID entry as well.
     * <p>
     * This cleanup helps prevent memory leaks by ensuring that completed operations don't
     * continue to consume memory.
     *
     * @param id        The unique identifier for the operation
     * @param operation The type of operation to remove tracking data for
     */
    public void remove(long id, String operation)
    {
        try
        {
            if (probes.get(id) != null)
            {
                // Remove the specific operation
                probes.get(id).remove(operation);

                // If the inner map is empty after removal, remove the id entry as well
                // to prevent memory leaks
                if (probes.get(id).isEmpty())
                {
                    probes.remove(id);
                }
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

    /**
     * Sends notifications to users about completed configuration operations.
     * <p>
     * This method handles the delivery of both email and SMS notifications to relevant users
     * when a configuration operation completes. It performs the following steps:
     * <p>
     * 1. Determines the recipients for notifications:
     * - Uses recipients specified in the event (if any)
     * - Adds the user who initiated the operation
     * <p>
     * 2. Formats the group information for display in the notification
     * <p>
     * 3. Sends email notifications with detailed information:
     * - Operation type and status
     * - Success/failure counts
     * - Timestamp information
     * - Group information
     * <p>
     * 4. Sends SMS notifications with a more concise message
     *
     * @param event The event containing operation details and recipient information
     */
    private void notify(JsonObject event)
    {
        // Need to consider the message when one of the file's backup fails
        try
        {
            // Determine email recipients - try discovery recipients first, then scheduler recipients
            var mailRecipients = event.getJsonArray(Discovery.DISCOVERY_EMAIL_RECIPIENTS) != null && !event.getJsonArray(Discovery.DISCOVERY_EMAIL_RECIPIENTS).isEmpty() ?
                    event.getJsonArray(Discovery.DISCOVERY_EMAIL_RECIPIENTS) : event.getJsonArray(Scheduler.SCHEDULER_EMAIL_RECIPIENTS) != null && !event.getJsonArray(Scheduler.SCHEDULER_EMAIL_RECIPIENTS).isEmpty() ? event.getJsonArray(Scheduler.SCHEDULER_EMAIL_RECIPIENTS) : null;

            // Determine SMS recipients - try discovery recipients first, then scheduler recipients
            var smsRecipients = event.getJsonArray(Discovery.DISCOVERY_SMS_RECIPIENTS) != null && !event.getJsonArray(Discovery.DISCOVERY_SMS_RECIPIENTS).isEmpty() ?
                    event.getJsonArray(Discovery.DISCOVERY_SMS_RECIPIENTS) : event.getJsonArray(Scheduler.SCHEDULER_SMS_RECIPIENTS) != null && !event.getJsonArray(Scheduler.SCHEDULER_SMS_RECIPIENTS).isEmpty() ? event.getJsonArray(Scheduler.SCHEDULER_SMS_RECIPIENTS) : null;

            // Add the user who initiated the operation to the recipients
            var item = UserConfigStore.getStore().getItemByValue(User.USER_NAME, event.getString(User.USER_NAME));

            if (item != null)
            {
                // Add user's email to recipients if available
                if (CommonUtil.isNotNullOrEmpty(item.getString(User.USER_EMAIL)))
                {
                    mailRecipients = mailRecipients == null ? new JsonArray(new ArrayList<>(1)).add(item.getString(User.USER_EMAIL)) : mailRecipients.add(item.getString(User.USER_EMAIL));
                }

                // Add user's mobile number to recipients if available
                if (CommonUtil.isNotNullOrEmpty(item.getString(User.USER_MOBILE)))
                {
                    smsRecipients = smsRecipients == null ? new JsonArray(new ArrayList<>(1)).add(item.getString(User.USER_MOBILE)) : smsRecipients.add(item.getString(User.USER_MOBILE));
                }
            }

            // Format group information for display in notifications
            var groups = new JsonArray();
            builder.setLength(0);

            // Process each group and build its hierarchy string
            if (event.containsKey(AIOpsObject.OBJECT_GROUPS))
            {
                event.getJsonArray(AIOpsObject.OBJECT_GROUPS).forEach(entry ->
                {
                    CommonUtil.normalizeGroupHierarchy(GroupConfigStore.getStore().getItem(CommonUtil.getLong(entry)), builder, null);

                    groups.add(builder.toString());

                    builder.setLength(0);
                });
            }

            // Send email notification if recipients exist
            if (mailRecipients != null && !mailRecipients.isEmpty())
            {
                // Create email notification with detailed information
                Notification.sendEmail(new JsonObject()
                        .put(Notification.EMAIL_NOTIFICATION_ATTACHMENT_DISPOSITION_TYPE, "inline").put(Notification.EMAIL_NOTIFICATION_ATTACHMENT_TYPE, "image/png")
                        .put(Notification.EMAIL_NOTIFICATION_ATTACHMENTS, new JsonArray().add("information.png").addAll(Notification.EMAIL_NOTIFICATION_INLINE_ATTACHMENT_ICONS))
                        .put(Notification.EMAIL_NOTIFICATION_SUBJECT, String.format(InfoMessageConstants.CONFIG_DISCOVERY_NOTIFICATION_SUBJECT, ConfigConstants.resolve(ConfigConstants.ConfigOperation.valueOfName(event.getString(ConfigConstants.CONFIG_OPERATION)))))
                        .put(Notification.TEMPLATE_NAME, Notification.EMAIL_NOTIFICATION_CONFIG_HTML_TEMPLATE)
                        .put(Notification.EMAIL_NOTIFICATION_RECIPIENTS, mailRecipients).put(Notification.EMAIL_NOTIFICATION_CONTENT, new JsonObject().mergeIn(event).put(ConfigConstants.CONFIG_OPERATION, ConfigConstants.resolve(ConfigConstants.ConfigOperation.valueOfName(event.getString(ConfigConstants.CONFIG_OPERATION)))).put(LogEngineConstants.RECEIVED_TIMESTAMP, DateTimeUtil.getTimeStampFromEpochTimestamp(event.getLong(EVENT_TIMESTAMP), true)).put(TIME_STAMP, DateTimeUtil.timestamp()).put(GlobalConstants.HOST, CommonUtil.getIPAddress()).put(AIOpsObject.OBJECT_GROUPS, StringUtils.join(groups, COMMA_SEPARATOR))));
            }

            // Send SMS notification if recipients exist
            if (smsRecipients != null && !smsRecipients.isEmpty())
            {
                // Create SMS notification with concise information
                Notification.sendSMS(new StringSubstitutor(new JsonObject().mergeIn(event).put(TIME_STAMP, DateTimeUtil.timestamp()).put(AIOpsObject.OBJECT_GROUPS, StringUtils.join(groups, COMMA_SEPARATOR)).getMap()).replace(InfoMessageConstants.CONFIG_DISCOVERY_NOTIFICATION_MESSAGE),
                        smsRecipients);
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

    /**
     * Processes and updates probe information for a "TOTAL" type event.
     * <p>
     * This method handles the initialization of counters for configuration operations.
     * It sets up the expected total count of operations that will be performed, which
     * is later used to determine when an operation is complete.
     * <p>
     * The method handles two main scenarios:
     * <p>
     * 1. Operations with post-processing:
     * - Updates counters for the backup operation
     * - Updates counters for the post-operation (e.g., restore)
     * - Updates counters for the post-backup operation
     * <p>
     * 2. Operations without post-processing:
     * - For backup operations, updates the post-backup counter
     * - For other operations, updates the counter for that specific operation
     *
     * @param event The event containing operation details and probe information
     */
    public void complete(JsonObject event)
    {
        try
        {
            // Check if this operation has a post-operation configured
            if (CommonUtil.isNotNullOrEmpty(event.getString(ConfigConstants.CONFIG_POST_OPERATION)))
            {
                // For operations with post-processing, update counters for all three stages

                // 1. Update counter for the backup operation
                update(ConfigConstants.ConfigOperation.BACKUP.getName(),
                        event.getString(PROBE_TYPE),
                        event,
                        event.getInteger(ConfigConstants.PROBE_COUNT));

                // 2. Update counter for the post-operation (e.g., restore)
                update(event.getString(ConfigConstants.CONFIG_POST_OPERATION),
                        event.getString(PROBE_TYPE),
                        event,
                        event.getInteger(ConfigConstants.PROBE_COUNT));

                // 3. Update counter for the post-backup operation
                update(POST_BACKUP,
                        event.getString(PROBE_TYPE),
                        event,
                        event.getInteger(ConfigConstants.PROBE_COUNT));
            }
            else
            {
                // For operations without post-processing
                if (event.getString(CONFIG_OPERATION).equalsIgnoreCase(ConfigOperation.BACKUP.getName()))
                {
                    // For backup operations, update the post-backup counter
                    update(POST_BACKUP,
                            event.getString(PROBE_TYPE),
                            event,
                            event.getInteger(ConfigConstants.PROBE_COUNT));
                }
                else
                {
                    // For other operations, update the counter for that specific operation
                    update(event.getString(CONFIG_OPERATION),
                            event.getString(PROBE_TYPE),
                            event,
                            event.getInteger(ConfigConstants.PROBE_COUNT));
                }
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }


    /**
     * Processes and updates probe information based on the event's operation type and status.
     * <p>
     * This method handles the updating of counters for configuration operations as they
     * progress. It tracks the success or failure of individual operations and updates
     * the appropriate counters.
     * <p>
     * The method handles different scenarios based on the operation type and status:
     * <p>
     * 1. For BACKUP operations with post-processing:
     * - If the operation FAILED:
     * - Updates failure counters for all three stages (backup, post-operation, post-backup)
     * - This ensures that a failure in one stage is properly reflected in all related stages
     * - If the operation SUCCEEDED:
     * - Updates only the backup operation counter
     * - Post-operations will be updated separately when they complete
     * <p>
     * 2. For BACKUP operations without post-processing:
     * - Updates the post-backup counter directly
     * <p>
     * 3. For non-BACKUP operations:
     * - Updates the counter for that specific operation type
     *
     * @param event The event containing operation details, probe type (SUCCESS/FAILED), and count
     */
    public void update(JsonObject event)
    {
        try
        {
            var configOperation = event.getString(ConfigConstants.CONFIG_OPERATION);

            // Handle BACKUP operations specially
            if (configOperation.equalsIgnoreCase(ConfigConstants.ConfigOperation.BACKUP.getName()))
            {
                // Check if this backup has a post-operation configured
                if (CommonUtil.isNotNullOrEmpty(event.getString(ConfigConstants.CONFIG_POST_OPERATION)))
                {
                    // Special handling for FAILED operations with post-processing
                    if (event.getString(PROBE_TYPE).equalsIgnoreCase(STATUS_FAILED))
                    {
                        // If a backup fails, mark all related operations as failed

                        // 1. Mark the backup operation as failed
                        update(ConfigConstants.ConfigOperation.BACKUP.getName(),
                                event.getString(PROBE_TYPE),
                                event,
                                event.getInteger(ConfigConstants.PROBE_COUNT));

                        // 2. Mark the post-operation as failed
                        update(event.getString(ConfigConstants.CONFIG_POST_OPERATION),
                                event.getString(PROBE_TYPE),
                                event,
                                event.getInteger(ConfigConstants.PROBE_COUNT));

                        // 3. Mark the post-backup operation as failed
                        update(POST_BACKUP,
                                event.getString(PROBE_TYPE),
                                event,
                                event.getInteger(ConfigConstants.PROBE_COUNT));
                    }
                    else
                    {
                        // For successful operations, only update the backup counter
                        // Post-operations will be updated separately when they complete
                        update(ConfigConstants.ConfigOperation.BACKUP.getName(),
                                event.getString(PROBE_TYPE),
                                event,
                                event.getInteger(ConfigConstants.PROBE_COUNT));
                    }
                }
                else
                {
                    // For backup operations without post-processing, update the post-backup counter
                    update(POST_BACKUP,
                            event.getString(PROBE_TYPE),
                            event,
                            event.getInteger(ConfigConstants.PROBE_COUNT));
                }
            }
            else
            {
                // For non-BACKUP operations, update the counter for that specific operation
                update(configOperation,
                        event.getString(ConfigConstants.PROBE_TYPE),
                        event,
                        event.getInteger(ConfigConstants.PROBE_COUNT));
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

    /**
     * Add a configuration change event for backup.
     * <p>
     * This method checks if the incoming event contains a valid event source.
     * If present, it retrieves the corresponding object name using the source IP,
     * then fetches the configuration item by object name and obtains its ID.
     * If the item exists, its ID is added to the set of qualified items for backup processing.
     * If the event source is missing, a warning is logged and the event is skipped.
     *
     * @param event The JsonObject representing the configuration change event.
     */
    private void enqueue(JsonObject event)
    {
        try
        {
            LOGGER.info(String.format("Received event for config change backup : %s", event));

            var item = ObjectConfigStore.getStore().getItemByIP(event.getString(EventBusConstants.EVENT_SOURCE));

            if (item != null)
            {
                var id = ConfigurationConfigStore.getStore().getIdByObjectId(ObjectConfigStore.getStore().getObjectId(item));

                if (id != NOT_AVAILABLE) queuedItems.add(id);

                if (MotadataConfigUtil.devMode())
                    Bootstrap.vertx().eventBus().send("test.config.backup.queue", new JsonObject().put("queuedItems", queuedItems.size()));
            }
            else
            {
                LOGGER.warn("Received event without a valid event source, skipping backup processing.");
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

    /**
     * Send qualified configuration items for backup.
     * This method checks if there are any qualified items pending for backup.
     * This method is typically triggered periodically by a scheduler.
     */
    private void dequeue()
    {
        try
        {
            if (queuedItems.isEmpty()) return; // If no qualified items, return early

            Bootstrap.vertx().eventBus().send(EventBusConstants.EVENT_CONFIG_BACKUP, new JsonObject().put(CONFIG_OPERATION, ConfigConstants.ConfigOperation.BACKUP.getName())
                    .put(NMSConstants.OBJECTS, new JsonArray((queuedItems.stream().toList())))
                    .put(ConfigConstants.CONFIG_OPERATION_ID, CommonUtil.newId())
                    .put(User.USER_NAME, DEFAULT_USER).put(REMOTE_ADDRESS, SYSTEM_REMOTE_ADDRESS));

            LOGGER.info(String.format("Sent %d qualified items for backup processing.", queuedItems.size()));
        }

        catch (Exception exception)
        {
            LOGGER.error(exception);
        }

        finally
        {
            queuedItems.clear();

            if (MotadataConfigUtil.devMode())
                Bootstrap.vertx().eventBus().send("test.config.backup.queue.timer.complete", new JsonObject().put("queuedItems", queuedItems.size()));
        }
    }
}

