    /**
     * Completes an operation and updates the system state accordingly.
     * <p>
     * This method handles the completion of operations for different bootstrap types:
     * <ul>
     *   <li>For agents, it updates the agent cache and enables the agent if it was disabled</li>
     *   <li>For collectors, event processors, and datastores, it updates their cache and publishes
     *       notification events</li>
     * </ul>
     * <p>
     * The method ensures that after an operation completes, the system components are
     * properly enabled to allow further operations.
     *
     * @param event         the JSON object containing the event data
     * @param bootstrapType the type of bootstrap component (AGENT, COLLECTOR, etc.)
     */
    private void complete(JsonObject event, String bootstrapType)
    {
        try
        {
            if (bootstrapType.equalsIgnoreCase(BootstrapType.AGENT.name()))
            {
                if (event.containsKey(ID)) //improvements - 3636 -> now allow user to perform another actions
                {
                    var id = AgentConfigStore.getStore().getAgentId(event.getString(AGENT_UUID));

                    var item = AgentCacheStore.getStore().getItem(id);

                    AgentCacheStore.getStore().updateDuration(id, NO);

                    if (item.containsKey(AGENT_DISABLE) && item.getString(AGENT_DISABLE).equalsIgnoreCase(YES))
                    {
                        AgentCacheStore.getStore().updateItem(id, item.put(AGENT_DISABLE, NO));

                        EventBusConstants.publish(UI_NOTIFICATION_AGENT, new JsonObject().put(EVENT_TYPE, EVENT_AGENT_ACTION).put(ID, id).put(AGENT_DISABLE, NO));
                    }
                }
            }
            else if (bootstrapType.equalsIgnoreCase(BootstrapType.COLLECTOR.name())
                    || bootstrapType.equalsIgnoreCase(BootstrapType.EDGE_COLLECTOR.name())
                    || bootstrapType.equalsIgnoreCase(BootstrapType.EVENT_PROCESSOR.name())
                    || bootstrapType.equalsIgnoreCase(BootstrapType.EVENT_COLLECTOR.name())
                    || bootstrapType.equalsIgnoreCase(BootstrapType.FLOW_COLLECTOR.name())
                    || bootstrapType.equalsIgnoreCase(BootstrapType.DATASTORE.name()))
            {
                if (event.containsKey(ID)) //now allow user to perform another actions
                {
                    RemoteEventProcessorCacheStore.getStore().updateDuration(event.getLong(ID), NO);

                    EventBusConstants.publish(UI_NOTIFICATION_REMOTE_PROCESSOR, new JsonObject().put(EVENT_TYPE, EVENT_REMOTE_EVENT_PROCESSOR_ACTION).put(ID, event.getLong(ID))
                            .put(RemoteEventProcessor.REMOTE_EVENT_PROCESSOR_UUID, event.getString(RemoteEventProcessor.REMOTE_EVENT_PROCESSOR_UUID))
                            .put(DISABLED, NO));
                }
            }

            EventBusConstants.complete(event);
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

    /**
     * Monitors and updates the status of remote event processors.
     * <p>
     * This method sets up a periodic task that runs every 10 seconds to:
     * <ul>
     *   <li>Check the availability of remote event processors</li>
     *   <li>Mark processors as down if no heartbeat is received for 30 seconds</li>
     *   <li>Re-enable processors that have been disabled for more than 90 seconds</li>
     *   <li>Update the UI with the current status of processors</li>
     *   <li>Detect and report datastore connectivity issues</li>
     * </ul>
     * <p>
     * The method implements an automatic recovery mechanism for processors that
     * might be temporarily unavailable, preventing them from being permanently disabled.
     */
    private void update()
    {
        /*
         * Execute timer on every 10 sec to check remote event processor availability
         * If last received heartbeat is greater than 30 sec delete that event processor from cache store that will mark it as a down
         */
        vertx.setPeriodic(10000L, timer ->
        {
            var items = RemoteEventProcessorConfigStore.getStore().getItems();

            for (var index = 0; index < items.size(); index++)
            {
                try
                {
                    var item = items.getJsonObject(index);

                    // Get the duration for which the remote event processor has been in its current state
                    var duration = RemoteEventProcessorCacheStore.getStore().getStateDuration(item.getLong(ID));

                    // Auto-recovery mechanism: If a remote event processor has been disabled for more than 90 seconds,
                    // automatically re-enable it to prevent permanent disablement due to temporary issues.
                    // This helps in recovering from transient network problems or brief service interruptions.
                    if (duration > 0 && (DateTimeUtil.currentSeconds() - duration) >= 90)
                    {
                        if (CommonUtil.debugEnabled())
                        {
                            LOGGER.debug(String.format("%s remote event processor action state enabled, reason : %s", item.getString(RemoteEventProcessor.REMOTE_EVENT_PROCESSOR_UUID), "flap timer limit exceeded..."));
                        }

                        RemoteEventProcessorCacheStore.getStore().updateDuration(item.getLong(ID), NO);

                        EventBusConstants.publish(UI_NOTIFICATION_REMOTE_PROCESSOR, new JsonObject().put(EVENT_TYPE, EVENT_REMOTE_EVENT_PROCESSOR_ACTION).put(ID, item.getLong(ID))
                                .put(RemoteEventProcessor.REMOTE_EVENT_PROCESSOR_UUID, item.getString(RemoteEventProcessor.REMOTE_EVENT_PROCESSOR_UUID))
                                .put(DISABLED, NO));
                    }

                    var cache = RemoteEventProcessorCacheStore.getStore().getItem(item.getLong(ID));

                    if (!cache.containsKey(EVENT_TIMESTAMP))
                    {
                        cache.put(EVENT_TIMESTAMP, DateTimeUtil.currentSeconds());
                    }

                    // Remote event processor availability check: Mark processors as down if no heartbeat received for 20+ seconds
                    if (DateTimeUtil.currentSeconds() - cache.getLong(EVENT_TIMESTAMP) >= MotadataConfigUtil.getRemoteEventProcessorNotificationTimerSeconds())
                    {
                        if (CommonUtil.traceEnabled())
                        {
                            LOGGER.trace(String.format("item is not reachable %s ", cache.encode()));
                        }

                        // send continuous event to UI. sticky notification . All remote entity.
                        EventBusConstants.publish(UI_NOTIFICATION_REMOTE_EVENT_PROCESSOR_HEALTH,new JsonObject().put(ID,item.getLong(ID)).put(MotadataAppManager.HEARTBEAT_STATE,cache.getString(MotadataAppManager.HEARTBEAT_STATE))
                                .put(MESSAGE,String.format(UNABLE_TO_CONNECT_MOTADATA_ENTITY,item.getString(REMOTE_EVENT_PROCESSOR_INSTALLATION_MODE),item.getString(REMOTE_EVENT_PROCESSOR_TYPE),item.getString(REMOTE_EVENT_PROCESSOR_HOST),item.getString(REMOTE_EVENT_PROCESSOR_IP))));


                        if (item.getString(REMOTE_EVENT_PROCESSOR_TYPE).equalsIgnoreCase(BootstrapType.DATASTORE.name()))
                        {
                            Bootstrap.vertx().eventBus().publish(EVENT_DATASTORE_PING, new JsonObject().put(STATUS, STATUS_DOWN).put(RemoteEventProcessor.REMOTE_EVENT_PROCESSOR_UUID, item.getString(RemoteEventProcessor.REMOTE_EVENT_PROCESSOR_UUID)));

                            LOGGER.warn(String.format("datastore : %s-%s is down : duration : %s ",item.getString(REMOTE_EVENT_PROCESSOR_IP), item.getString(REMOTE_EVENT_PROCESSOR_UUID), DateTimeUtil.currentSeconds() - cache.getLong(EVENT_TIMESTAMP)));
                        }

                        // Initialize heartbeat state if not already set
                        if (!cache.containsKey(MotadataAppManager.HEARTBEAT_STATE))
                        {
                            cache.put(MotadataAppManager.HEARTBEAT_STATE, NMSConstants.STATE_NOT_REACHABLE);

                            LOGGER.info(String.format("Remote entity is not reachable %s ", item.encode()));

                            vertx.eventBus().send(EVENT_AUDIT_WRITE,new JsonObject().put(AUDIT_MODULE,SYSTEM_HEATH).put(AUDIT_OPERATION,VIEW)
                                    .put(AUDIT_MESSAGE,String.format(String.format(ENTITY_UPDATED, SYSTEM_HEATH) + GlobalConstants.NEW_LINE +
                                            new JsonObject().put("new.prop.value",new JsonObject()
                                                    .put(REMOTE_EVENT_PROCESSOR_IP,item.getString(REMOTE_EVENT_PROCESSOR_IP))
                                                    .put(REMOTE_EVENT_PROCESSOR_TYPE,item.getString(REMOTE_EVENT_PROCESSOR_TYPE))
                                                    .put(REMOTE_EVENT_PROCESSOR_UUID,item.getString(REMOTE_EVENT_PROCESSOR_UUID))
                                                    .put(REMOTE_EVENT_PROCESSOR_INSTALLATION_MODE,item.getString(REMOTE_EVENT_PROCESSOR_INSTALLATION_MODE))
                                                    .mergeIn(cache).put(DURATION,DateTimeUtil.currentSeconds() - cache.getLong(EVENT_TIMESTAMP))
                                                    .put(MANAGER_UUID,Bootstrap.getRegistrationId()).put(INSTALLATION_MODE,Bootstrap.getInstallationMode())
                                                    .put(TIME_STAMP, DateTimeUtil.currentSeconds())
                                                    .put(TIME,DateTimeUtil.getScheduledTimestamp(DateTimeUtil.currentMilliSeconds()))
                                                    .put(MESSAGE,"Remote entity is Down.")).encodePrettily())));

                            notify(item,cache);
                        }

                        // State transition handling: If the processor was previously running, we need to:
                        // 1. Update its state to NOT_REACHABLE
                        // 2. Set the duration to when it became unreachable (current time minus timeout period)
                        // This helps in tracking how long the processor has been unreachable
                        if (cache.getString(MotadataAppManager.HEARTBEAT_STATE).equalsIgnoreCase(NMSConstants.STATE_RUNNING))
                        {
                            cache.put(MotadataAppManager.HEARTBEAT_STATE, NMSConstants.STATE_NOT_REACHABLE).put(DURATION, DateTimeUtil.currentSeconds() - MotadataConfigUtil.getRemoteEventProcessorNotificationTimerSeconds());

                            LOGGER.info(String.format("Remote entity is not reachable %s ", item.encode()));

                            vertx.eventBus().send(EVENT_AUDIT_WRITE,new JsonObject().put(AUDIT_MODULE,SYSTEM_HEATH).put(AUDIT_OPERATION,VIEW)
                                    .put(AUDIT_MESSAGE,String.format(String.format(ENTITY_UPDATED, SYSTEM_HEATH) + GlobalConstants.NEW_LINE +
                                            new JsonObject().put("new.prop.value",new JsonObject()
                                                    .put(REMOTE_EVENT_PROCESSOR_IP,item.getString(REMOTE_EVENT_PROCESSOR_IP))
                                                    .put(REMOTE_EVENT_PROCESSOR_TYPE,item.getString(REMOTE_EVENT_PROCESSOR_TYPE))
                                                    .put(REMOTE_EVENT_PROCESSOR_UUID,item.getString(REMOTE_EVENT_PROCESSOR_UUID))
                                                    .put(REMOTE_EVENT_PROCESSOR_INSTALLATION_MODE,item.getString(REMOTE_EVENT_PROCESSOR_INSTALLATION_MODE))
                                                    .mergeIn(cache).put(DURATION,DateTimeUtil.currentSeconds() - cache.getLong(EVENT_TIMESTAMP))
                                                    .put(MANAGER_UUID,Bootstrap.getRegistrationId()).put(INSTALLATION_MODE,Bootstrap.getInstallationMode())
                                                    .put(TIME_STAMP, DateTimeUtil.currentSeconds())
                                                    .put(TIME,DateTimeUtil.getScheduledTimestamp(DateTimeUtil.currentMilliSeconds()))
                                                    .put(MESSAGE,"Remote entity is Down.")).encodePrettily())));

                            notify(item,cache);
                        }

                        cache.put(STATUS, STATUS_DOWN);

                        RemoteEventProcessorCacheStore.getStore().updateItem(item.getLong(ID), cache);

                        dirty = true;

                        cache.put(REMOTE_EVENT_PROCESSOR_MAIL_NOTIFICATION_TIMER_SECONDS,cache.getInteger(REMOTE_EVENT_PROCESSOR_MAIL_NOTIFICATION_TIMER_SECONDS,0) + 10);

                        if (cache.getInteger(REMOTE_EVENT_PROCESSOR_MAIL_NOTIFICATION_TIMER_SECONDS,0) >= MotadataConfigUtil.getRemoteEventProcessorMailNotificationTimerSeconds())       // every 30 min send email if configured
                        {
                            // we'll check if blackout time is configured , and if that time increased surpassed then send e-mail
                            notify(item,cache);

                            cache.put(REMOTE_EVENT_PROCESSOR_MAIL_NOTIFICATION_TIMER_SECONDS,0);
                        }
                    }
                    else
                    {
                        if (cache.containsKey(REMOTE_EVENT_PROCESSOR_MAIL_NOTIFICATION_TIMER_SECONDS)
                                && cache.getString(MotadataAppManager.HEARTBEAT_STATE,EMPTY_VALUE).equalsIgnoreCase(NMSConstants.STATE_RUNNING))
                        {
                            LOGGER.info(String.format("%s %s %s is Up ",item.getString(REMOTE_EVENT_PROCESSOR_TYPE),item.getString(REMOTE_EVENT_PROCESSOR_IP),item.getString(REMOTE_EVENT_PROCESSOR_UUID)));

                            // publish to UI , when its up. for the first time then remove "last"
                            EventBusConstants.publish(UI_NOTIFICATION_REMOTE_EVENT_PROCESSOR_HEALTH,new JsonObject().put(ID,item.getLong(ID))
                                    .put(MotadataAppManager.HEARTBEAT_STATE,cache.getString(MotadataAppManager.HEARTBEAT_STATE)));

                            vertx.eventBus().send(EVENT_AUDIT_WRITE,new JsonObject().put(AUDIT_MODULE,SYSTEM_HEATH).put(AUDIT_OPERATION,VIEW)
                                    .put(AUDIT_MESSAGE,String.format(String.format(ENTITY_UPDATED, SYSTEM_HEATH) + GlobalConstants.NEW_LINE +
                                            new JsonObject().put("new.prop.value",new JsonObject()
                                                    .put(REMOTE_EVENT_PROCESSOR_IP,item.getString(REMOTE_EVENT_PROCESSOR_IP))
                                                    .put(REMOTE_EVENT_PROCESSOR_TYPE,item.getString(REMOTE_EVENT_PROCESSOR_TYPE))
                                                    .put(REMOTE_EVENT_PROCESSOR_UUID,item.getString(REMOTE_EVENT_PROCESSOR_UUID))
                                                    .put(REMOTE_EVENT_PROCESSOR_INSTALLATION_MODE,item.getString(REMOTE_EVENT_PROCESSOR_INSTALLATION_MODE))
                                                    .mergeIn(cache).put(DURATION,DateTimeUtil.currentSeconds() - cache.getLong(EVENT_TIMESTAMP))
                                                    .put(MANAGER_UUID,Bootstrap.getRegistrationId()).put(INSTALLATION_MODE,Bootstrap.getInstallationMode())
                                                    .put(TIME_STAMP, DateTimeUtil.currentSeconds())
                                                    .put(TIME,DateTimeUtil.getScheduledTimestamp(DateTimeUtil.currentMilliSeconds()))
                                                    .put(MESSAGE,"Remote entity is Up.")).encodePrettily())));

                            cache.remove(REMOTE_EVENT_PROCESSOR_MAIL_NOTIFICATION_TIMER_SECONDS);

                            cache.put(STATUS, STATUS_UP);

                            RemoteEventProcessorCacheStore.getStore().updateItem(item.getLong(ID), cache);

                            dirty = true;
                        }
                    }
                }
                catch (Exception exception)
                {
                    LOGGER.error(exception);
                }
            }
        });
    }

    private void notify(JsonObject item,JsonObject cache)
    {
        var user = UserConfigStore.getStore().getItem(DEFAULT_ID,false);

        if (user.getString(User.USER_EMAIL) != null && !user.getString(User.USER_EMAIL).isEmpty())
        {
            var emailBody = new JsonObject().mergeIn(item).put(EVENT_TIMESTAMP,DateTimeUtil.timestamp(DateTimeUtil.currentMilliSeconds())).put(SEVERITY,Severity.CRITICAL.name().toLowerCase())
                    .put(MESSAGE,String.format(UNABLE_TO_CONNECT_MOTADATA_ENTITY,item.getString(REMOTE_EVENT_PROCESSOR_INSTALLATION_MODE),item.getString(REMOTE_EVENT_PROCESSOR_TYPE),item.getString(REMOTE_EVENT_PROCESSOR_HOST),item.getString(REMOTE_EVENT_PROCESSOR_IP)));

            Bootstrap.vertx().eventBus().<JsonObject>request(EventBusConstants.EVENT_NOTIFICATION, new JsonObject()
                    .put(EventBusConstants.EVENT_REPLY, YES).put(NOTIFICATION_TYPE, Notification.NotificationType.EMAIL.getName())
                    .put(Notification.EMAIL_NOTIFICATION_ATTACHMENT_DISPOSITION_TYPE, "inline").put(Notification.EMAIL_NOTIFICATION_ATTACHMENT_TYPE, "image/png")
                    .put(Notification.EMAIL_NOTIFICATION_ATTACHMENTS, new JsonArray().add(Severity.CRITICAL.name().toLowerCase() + ".png").addAll(Notification.EMAIL_NOTIFICATION_INLINE_ATTACHMENT_ICONS))
                    .put(Notification.EMAIL_NOTIFICATION_SUBJECT, "Unable to Connect")
                    .put(Notification.EMAIL_NOTIFICATION_RECIPIENTS, new JsonArray().add(user.getString(User.USER_EMAIL)))
                    .put(TEMPLATE_NAME, EMAIL_NOTIFICATION_UNABLE_TO_CONNECT_HTML_TEMPLATE)
                    .put(Notification.EMAIL_NOTIFICATION_CONTENT, emailBody), reply ->
            {
                try
                {
                    if (reply.failed())
                    {
                        LOGGER.error(reply.cause());
                    }
                    else
                    {
                        LOGGER.info(String.format("Email has been successfully sent to user : %s  for remote entity : %s , :%s ",user.getString(USER_NAME),item.getString(REMOTE_EVENT_PROCESSOR_IP),item.getString(REMOTE_EVENT_PROCESSOR_TYPE)));
                    }

                    vertx.eventBus().send(EVENT_AUDIT_WRITE,new JsonObject().put(AUDIT_MODULE,SYSTEM_HEATH).put(AUDIT_OPERATION,VIEW)
                            .put(AUDIT_MESSAGE,String.format(String.format(ENTITY_UPDATED, SYSTEM_HEATH) + GlobalConstants.NEW_LINE +
                                    new JsonObject().put("new.prop.value",new JsonObject()
                                            .put(REMOTE_EVENT_PROCESSOR_IP,item.getString(REMOTE_EVENT_PROCESSOR_IP))
                                            .put(REMOTE_EVENT_PROCESSOR_TYPE,item.getString(REMOTE_EVENT_PROCESSOR_TYPE))
                                            .put(REMOTE_EVENT_PROCESSOR_UUID,item.getString(REMOTE_EVENT_PROCESSOR_UUID))
                                            .put(REMOTE_EVENT_PROCESSOR_INSTALLATION_MODE,item.getString(REMOTE_EVENT_PROCESSOR_INSTALLATION_MODE))
                                            .mergeIn(cache).put(DURATION,DateTimeUtil.currentSeconds() - cache.getLong(EVENT_TIMESTAMP))
                                            .put(USER_NAME,user.getString(USER_NAME)).put(User.USER_EMAIL,user.getString(User.USER_EMAIL))
                                            .put("mail.server.configured",MailServerConfigStore.getStore().isConfigured())
                                            .put(MANAGER_UUID,Bootstrap.getRegistrationId()).put(INSTALLATION_MODE,Bootstrap.getInstallationMode())
                                            .put(TIME_STAMP, DateTimeUtil.currentSeconds()).put(ERROR,reply.succeeded() ? EMPTY_VALUE : reply.cause().getMessage())
                                            .put(TIME,DateTimeUtil.getScheduledTimestamp(DateTimeUtil.currentMilliSeconds()))
                                            .put(MESSAGE,"Email has been sent to user " + user.getString(USER_NAME))).encodePrettily())));
                }
                catch (Exception exception)
                {
                    LOGGER.error(exception);
                }
            });
        }
        else
        {
            vertx.eventBus().send(EVENT_AUDIT_WRITE,new JsonObject().put(AUDIT_MODULE,SYSTEM_HEATH).put(AUDIT_OPERATION,VIEW)
                    .put(AUDIT_MESSAGE,String.format(String.format(ENTITY_UPDATED, SYSTEM_HEATH) + GlobalConstants.NEW_LINE +
                            new JsonObject().put("new.prop.value",new JsonObject()
                                    .put(REMOTE_EVENT_PROCESSOR_IP,item.getString(REMOTE_EVENT_PROCESSOR_IP))
                                    .put(REMOTE_EVENT_PROCESSOR_TYPE,item.getString(REMOTE_EVENT_PROCESSOR_TYPE))
                                    .put(REMOTE_EVENT_PROCESSOR_UUID,item.getString(REMOTE_EVENT_PROCESSOR_UUID))
                                    .put(REMOTE_EVENT_PROCESSOR_INSTALLATION_MODE,item.getString(REMOTE_EVENT_PROCESSOR_INSTALLATION_MODE))
                                    .mergeIn(cache).put(DURATION,DateTimeUtil.currentSeconds() - cache.getLong(EVENT_TIMESTAMP))
                                    .put(USER_NAME,user.getString(USER_NAME))
                                    .put(User.USER_EMAIL,user.getString(User.USER_EMAIL,EMPTY_VALUE))
                                    .put("mail.server.configured",MailServerConfigStore.getStore().isConfigured())
                                    .put(MANAGER_UUID,Bootstrap.getRegistrationId()).put(INSTALLATION_MODE,Bootstrap.getInstallationMode())
                                    .put(TIME_STAMP, DateTimeUtil.currentSeconds())
                                    .put(TIME,DateTimeUtil.getScheduledTimestamp(DateTimeUtil.currentMilliSeconds()))
                                    .put(MESSAGE,"No email has been found for user " + user.getString(USER_NAME))).encodePrettily())));
        }
    }

