import java.util.*;

import static com.mindarray.GlobalConstants.*;
import static com.mindarray.api.RUMServiceProfile.RUM_PROFILE_TYPE;
import static com.mindarray.datastore.DatastoreConstants.DATASTORE_CATEGORY;
import static com.mindarray.rum.RUMConstant.EVENTS;

/**
 * Calculates and aggregates RUM (Real User Monitoring) statistics.
 * <p>
 * This verticle receives statistics from RUM event processors, aggregates them over time,
 * calculates Apdex scores, and writes aggregated metrics to the datastore periodically.
 * It manages service-level metrics and geography-based Apdex statistics.
 */
public class RUMStatCalculator extends AbstractVerticle
{
    /**
     * Logger instance for RUM statistics calculation operations.
     */
    private static final Logger LOGGER = new Logger(RUMStatCalculator.class, MOTADATA_RUM, "RUM Stat Calculator");

    /**
     * Decimal formatter for rounding floating-point values to 4 decimal places.
     */
    private final DecimalFormat decimalFormat = new DecimalFormat("#.####");

    /**
     * Time interval in seconds to flush and write aggregated statistics to datastore.
     */
    private static final int RUM_STAT_FLUSH_TIMER_SECONDS = MotadataConfigUtil.getRUMStatFlushTimerSeconds();

    /**
     * Stores Apdex statistics aggregated by session, geography, and service.
     * Key format: "session-id``||``geo.country``||``geo.continent``||``service-name``||``event-source"
     * Value: Map of user interaction type (satisfied/tolerating/frustrating) to count
     */
    private final Map<String, Map<String, Integer>> apdexStats = new HashMap<>();

    /**
     * Reusable JsonObject for building event data to avoid object creation overhead.
     */
    private final JsonObject event = new JsonObject();

    /**
     * Reusable StringBuilder for efficient string concatenation during datastore writes.
     */
    private final StringBuilder builder = new StringBuilder(0);

    /**
     * Set of column mappers for datastore operations.
     */
    private Set<String> mappers;

    /**
     * Stores aggregated service statistics by service key.
     * Key format: "service-name``||``application-id``||``service-type"
     * Value: Array of 7 doubles [events, loading_time, lcp, errors, fcp, cls, inp]
     */
    private final Map<String, double[]> statsByService = new HashMap<>();

    /**
     * Tracks unique sessions per service for session count metrics.
     * Key: service name, Value: Set of unique session IDs
     */
    private final Map<String, Set<String>> sessionsByService = new HashMap<>();

    /**
     * Stores calculated Apdex rates by service name for inclusion in service stats.
     */
    private final Map<String, Double> apdexRatesByService = new HashMap<>();

    /**
     * Starts the RUM statistics calculator verticle.
     * <p>
     * Sets up event bus consumers for receiving statistics, configures periodic
     * calculation timers, and initializes test endpoints in development mode.
     *
     * @param promise Promise to complete when startup is successful or fail on error
     * @throws Exception if initialization fails
     */
    @Override
    public void start(Promise<Void> promise) throws Exception
    {
        try
        {
            mappers = new HashSet<>();

            vertx.eventBus().<JsonObject>localConsumer(EventBusConstants.EVENT_RUM_STAT, message -> merge(message.body()));

            vertx.setPeriodic(MotadataConfigUtil.getEnvironmentType().equalsIgnoreCase(ENV_TEST) ? 15 * 1000L : RUM_STAT_FLUSH_TIMER_SECONDS * 1000L, handler -> calculate());

            // Reset trace max events counter at every second
            vertx.setPeriodic(1000, id -> RUMCacheStore.getStore().reset());

            // Test consumer endpoints for exposing internal state during testing
            if (MotadataConfigUtil.devMode())
            {
                // Endpoint to get current accumulated stats by service (before calculation)
                vertx.eventBus().<JsonObject>localConsumer("test.rum.stats.accumulated", message ->
                {
                    var response = new JsonObject();

                    for (var entry : statsByService.entrySet())
                    {
                        var values = entry.getValue();

                        response.put(entry.getKey(), new JsonObject()
                                .put(EVENTS, (long) values[0])
                                .put(RUMConstant.LOADING_TIME_US, (long) values[1])
                                .put(RUMConstant.LARGEST_CONTENTFUL_PAINT_US, (long) values[2])
                                .put(RUMConstant.ERRORS, (int) values[3])
                                .put(RUMConstant.FIRST_CONTENTFUL_PAINT_US, (long) values[4])
                                .put(RUMConstant.CUMULATIVE_LAYOUT_SHIFT, (float) values[5])
                                .put(RUMConstant.INTERACTION_TO_NEXT_PAINT_US, (long) values[6]));
                    }

                    message.reply(response);

                }).exceptionHandler(LOGGER::error);

                // Endpoint to get current apdex stats (before calculation)
                vertx.eventBus().<JsonObject>localConsumer("test.rum.apdex.accumulated", message ->
                {
                    var response = new JsonObject();

                    for (var entry : apdexStats.entrySet())
                    {
                        var values = entry.getValue();

                        response.put(entry.getKey(), new JsonObject()
                                .put(RUMConstant.UserInteractionType.SATISFIED.getType(), values.getOrDefault(RUMConstant.UserInteractionType.SATISFIED.getType(), 0))
                                .put(RUMConstant.UserInteractionType.TOLERATING.getType(), values.getOrDefault(RUMConstant.UserInteractionType.TOLERATING.getType(), 0))
                                .put(RUMConstant.UserInteractionType.FRUSTRATING.getType(), values.getOrDefault(RUMConstant.UserInteractionType.FRUSTRATING.getType(), 0)));
                    }

                    message.reply(response);

                }).exceptionHandler(LOGGER::error);

                // Endpoint to get session counts by service
                vertx.eventBus().<JsonObject>localConsumer("test.rum.sessions.count", message ->
                {
                    var response = new JsonObject();

                    for (var entry : sessionsByService.entrySet())
                    {
                        response.put(entry.getKey(), entry.getValue().size());
                    }

                    message.reply(response);

                }).exceptionHandler(LOGGER::error);

                // Endpoint to trigger immediate calculation (for testing)
                vertx.eventBus().<JsonObject>localConsumer("test.rum.calculate.now", message ->
                {
                    calculate();

                    message.reply(new JsonObject().put("status", "calculated"));

                }).exceptionHandler(LOGGER::error);
            }

            Bootstrap.vertx().setPeriodic(60 * 1000, timerId -> logStats());

            promise.complete();
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);

            promise.fail(exception);
        }
    }

    /**
     * Merges incoming statistics from RUM event processors into aggregated maps.
     * <p>
     * Processes both Apdex statistics and service-level metrics, accumulating them
     * for later calculation and writing to the datastore.
     *
     * @param event JsonObject containing "apdex.stats" and "service.stats" data
     */
    private void merge(JsonObject event)
    {
        try
        {
            if (event != null)
            {
                // process apdex stats

                if (event.getJsonObject("apdex.stats") != null && !event.getJsonObject("apdex.stats").isEmpty())
                {
                    var stats = event.getJsonObject("apdex.stats").getMap(); // key -> "session-id``||``geo.country``||``geo.continent``||``service-name", value -> (key -> user interaction type, value -> count of user interaction type)

                    for (var entry : stats.entrySet())
                    {
                        var stat = (JsonObject) stats.get(entry.getKey()); // key -> user interaction type, value -> count of user interaction type

                        sessionsByService.computeIfAbsent(entry.getKey().split(SEPARATOR_WITH_ESCAPE)[3], value -> new HashSet<>()).add(entry.getKey().split(SEPARATOR_WITH_ESCAPE)[0]);

                        apdexStats.computeIfAbsent(entry.getKey(), value -> new HashMap<>());

                        var userInteractions = apdexStats.get(entry.getKey());

                        for (var key : stat.getMap().entrySet())
                        {
                            userInteractions.put(key.getKey(), userInteractions.getOrDefault(key.getKey(), 0) + (Integer) key.getValue());
                        }
                    }
                }

                // process service stats

                if (event.getJsonObject("service.stats") != null && !event.getJsonObject("service.stats").isEmpty())
                {
                    var serviceStats = event.getJsonObject("service.stats").getMap(); // key -> "service-name``||``application-id``||``service-type", value -> JsonObject containing service stats

                    for (var entry : serviceStats.entrySet())
                    {
                        var stat = (JsonObject) serviceStats.get(entry.getKey());

                        var values = statsByService.computeIfAbsent(entry.getKey(), value -> new double[7]);

                        values[0] += stat.getLong(EVENTS) !=null ? stat.getLong(EVENTS) : 0; // no of view events

                        values[1] += stat.getLong(RUMConstant.LOADING_TIME_US) != null ? stat.getLong(RUMConstant.LOADING_TIME_US) : 0;

                        values[2] += stat.getLong(RUMConstant.LARGEST_CONTENTFUL_PAINT_US) != null ? stat.getLong(RUMConstant.LARGEST_CONTENTFUL_PAINT_US) : 0;

                        values[3] += stat.getInteger(RUMConstant.ERRORS) != null ? stat.getInteger(RUMConstant.ERRORS) : 0;

                        values[4] += stat.getLong(RUMConstant.FIRST_CONTENTFUL_PAINT_US) != null ? stat.getLong(RUMConstant.FIRST_CONTENTFUL_PAINT_US) : 0;

                        values[5] += stat.getFloat(RUMConstant.CUMULATIVE_LAYOUT_SHIFT) != null ? stat.getFloat(RUMConstant.CUMULATIVE_LAYOUT_SHIFT) : 0;

                        values[6] += stat.getLong(RUMConstant.INTERACTION_TO_NEXT_PAINT_US) != null ? stat.getLong(RUMConstant.INTERACTION_TO_NEXT_PAINT_US) : 0;
                    }
                }
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

    /**
     * Calculates and writes aggregated statistics to the datastore.
     * <p>
     * Triggers writing of both Apdex and service statistics, then clears all
     * accumulated data for the next aggregation period.
     */
    private void calculate()
    {
        if (!statsByService.isEmpty() || !apdexStats.isEmpty())
        {
            // write apdex stat
            writeApdexStat();

            // write service stat
            writeServiceStat();
        }

        sessionsByService.clear();

        apdexStats.clear();

        statsByService.clear();

        apdexRatesByService.clear();
    }

    /**
     * Writes aggregated service-level statistics to the datastore.
     * <p>
     * Calculates average metrics per service including loading time, contentful paint metrics,
     * errors, layout shift, interaction timing, and session counts. Includes Apdex rate in the output.
     */
    private void writeServiceStat()
    {
        // key -> "service-name``||``application-id``||``service-type"
        for (var key : statsByService.keySet())
        {
            var values = statsByService.get(key);

            var tokens = key.split(SEPARATOR_WITH_ESCAPE);

            var applicationID = CommonUtil.getInteger(tokens[1]);

            try
            {
                // checking is there is any data
                if (values[0] > 0)
                {
                    LOGGER.info(String.format("total events : %s for service %s", values[0], tokens[0]));

                    event.put(getColumnForService(RUMConstant.LOADING_TIME_US, false), Math.round(CommonUtil.getDouble(values[1] / values[0]))) // rum.service~loading.time
                            .put(getColumnForService(RUMConstant.LARGEST_CONTENTFUL_PAINT_US, false), Math.round(CommonUtil.getDouble(values[2] / values[0]))) // rum.service~largest.contentful.paint
                            .put(getColumnForService(RUMConstant.APDEX_RATE, false), Double.valueOf(decimalFormat.format((apdexRatesByService.getOrDefault(tokens[0], 0.0))))) // rum.service~apdex.rate
                            .put(getColumnForService(RUMConstant.ERRORS, false), values[3]) // rum.service~errors
                            .put(getColumnForService(RUMConstant.FIRST_CONTENTFUL_PAINT_US, false), Math.round(CommonUtil.getDouble(values[4] / values[0]))) // rum.service~first.contentful.paint
                            .put(getColumnForService(RUMConstant.CUMULATIVE_LAYOUT_SHIFT, false), Double.valueOf(decimalFormat.format(values[5] / values[0]))) // rum.service~cumulative.layout.shift
                            .put(getColumnForService(RUMConstant.INTERACTION_TO_NEXT_PAINT_US, false), Math.round(CommonUtil.getDouble(values[6] / values[0]))) // rum.service~interaction.to.next.paint
                            .put(getColumnForService(RUMConstant.TYPE, false), RUMServiceProfileConfigStore.getStore().getItem(Long.parseLong(tokens[1])).getString(RUM_PROFILE_TYPE)) // rum.service~type
                            .put(getColumnForService(NMSConstants.INSTANCE_NAME, false), tokens[0]) // rum.service~instance.name
                            .put(getColumnForService(RUMConstant.RUM_SERVICE_INSTANCE_KEY, true), tokens[0]) // rum.service
                            .put(getColumnForService(RUMConstant.SESSIONS, false), sessionsByService.getOrDefault(tokens[0], new HashSet<>()).size()); // rum.service~sessions

                    RUMConstant.write(event, tokens[0], applicationID, DatastoreConstants.PluginId.RUM_METRIC.getName(), builder, mappers, LOGGER);

                    RUMConstant.send(new JsonObject().put(RESULT, new JsonObject().put(RUMConstant.RUM_SERVICE_INSTANCE_KEY , new JsonArray().add(event))),  DatastoreConstants.PluginId.RUM_METRIC.getName(),applicationID);

                    LOGGER.info(String.format("Rum service stat : %s", event.encodePrettily()));
                }
            }
            catch (Exception exception)
            {
                LOGGER.error(exception);
            }
            finally
            {
                if (MotadataConfigUtil.devMode())
                {
                    vertx.eventBus().send("test.rum.service.stat", event);
                }

                event.clear();
            }
        }
    }

    /**
     * Writes Apdex (Application Performance Index) statistics to the datastore.
     * <p>
     * Calculates Apdex rate using the formula: (satisfied + tolerating/2) / total
     * Groups statistics by session, geography, and service, and stores calculated rates
     * for inclusion in service statistics.
     */
    private void writeApdexStat()
    {
        // key -> "session-id``||``geo.country``||``geo.continent``||``service-name"``||``event.source"
        for (var key : apdexStats.keySet())
        {
            var values = apdexStats.get(key);

            var tokens = key.split(SEPARATOR_WITH_ESCAPE);

            try
            {
                var satisfied = values.getOrDefault(RUMConstant.UserInteractionType.SATISFIED.getType(), 0);

                var tolerating = values.getOrDefault(RUMConstant.UserInteractionType.TOLERATING.getType(), 0);

                var frustrating = values.getOrDefault(RUMConstant.UserInteractionType.FRUSTRATING.getType(), 0);

                LOGGER.info(String.format("Satisfied : %s, Tolerating : %s, Frustrating : %s", satisfied, tolerating, frustrating));

                if (satisfied + tolerating + frustrating > 0)
                {
                    var apdexRate = (satisfied + (Double.valueOf(tolerating) / 2)) / (satisfied + tolerating + frustrating);

                    apdexRatesByService.put(tokens[3], (double) apdexRate);

                    LOGGER.info("apdexRate : " + apdexRate);

                    event.put(RUMConstant.RUM_APDEX_SERVICE_NAME, tokens[3]) // rum.apdex.service.name
                            .put(RUMConstant.RUM_APDEX_COUNTRY, tokens[1]) // rum.apdex.country
                            .put(RUMConstant.RUM_APDEX_CONTINENT, tokens[2]) // rum.apdex.continent
                            .put(RUMConstant.RUM_APDEX_RATE, Double.valueOf(decimalFormat.format((apdexRate)))) // rum.apdex.rate
                            .put(EventBusConstants.EVENT_SOURCE, tokens[4])
                            .put(EventBusConstants.EVENT_TIMESTAMP, DateTimeUtil.currentSeconds())
                            .put(RUMConstant.RUM_APDEX_SESSION_ID, tokens[0]);

                    RUMCacheStore.getStore().addEventSource(tokens[4], List.of(VisualizationConstants.VisualizationDataSource.RUM_APDEX), List.of(DatastoreConstants.PluginId.RUM_APPDEX));

                    var builder = new StringBuilder(0);

                    DatastoreConstants.write(event.put(PLUGIN_ID, DatastoreConstants.PluginId.RUM_APPDEX.getName())
                            .put(DATASTORE_CATEGORY, DatastoreConstants.DatastoreCategory.TRACE.getName())
                            .put(DatastoreConstants.DATASTORE_TYPE, DatastoreConstants.DatastoreType.RUM_EVENT.ordinal()), VisualizationConstants.VisualizationDataSource.RUM_APDEX.getName(), mappers, builder);

                    LOGGER.info(String.format("Apdex stat : %s", event.encodePrettily()));
                }
            }
            catch (Exception exception)
            {
                LOGGER.error(exception);
            }
            finally
            {

                if (MotadataConfigUtil.devMode())
                {
                    vertx.eventBus().send("test.rum.apdex.stat", event);
                }

                event.clear();
            }
        }
    }

    /**
     * Generates the column name for service metrics.
     * <p>
     * Creates either an instance-level column (e.g., "rum.service~loading.time")
     * or the instance key itself based on the instance flag.
     *
     * @param column Column name to append
     * @param instance If true, returns only the instance key; if false, returns instance key with column
     * @return Formatted column name for datastore
     */
    public static String getColumnForService(String column, boolean instance)
    {
        return !instance ? RUMConstant.RUM_SERVICE_INSTANCE_KEY + GlobalConstants.INSTANCE_SEPARATOR + column : RUMConstant.RUM_SERVICE_INSTANCE_KEY;
    }

    /**
     * Logs periodic statistics about RUM event processing.
     * <p>
     * Reports total HTTP requests received, events processed, and faulty events encountered.
     * Resets counters after logging.
     */
    private void logStats()
    {
        LOGGER.info(String.format("Total HTTP Requests: %s, Total Events Processed: %s, Total Faulty Events: %s", RUMCacheStore.getStore().getHttpRequests().getAndSet(0), RUMCacheStore.getStore().getEvents().getAndSet(0), RUMCacheStore.getStore().getFaultyEvents().getAndSet(0)));
    }

    /**
     * Stops the RUM statistics calculator verticle.
     * <p>
     * Performs a final calculation to flush any remaining statistics before shutdown.
     *
     * @param promise Promise to complete when shutdown is successful
     */
    @Override
    public void stop(Promise<Void> promise)
    {
        calculate();

        LOGGER.info(String.format("RUMStatCalculator undeploy : %s ... ", Thread.currentThread().getName()));

        promise.complete();
    }
}

