/**
 * Processes Real User Monitoring (RUM) events from various sources.
 * <p>
 * This verticle handles incoming RUM events, parses them based on event type (VIEW, LONG_TASK, RESOURCE, ERROR, ACTION),
 * enriches them with geolocation data, calculates Apdex statistics, and writes them to the datastore.
 * It also manages policy engine integration for RUM analytics.
 */
public class RUMEventProcessor extends AbstractVerticle
{
    /**
     * Logger instance for RUM event processing operations.
     */
    private static final Logger LOGGER = new Logger(RUMEventProcessor.class, GlobalConstants.MOTADATA_RUM, "RUM Event Processor");

    /**
     * Event engine for processing RUM events from the event bus.
     */
    private EventEngine eventEngine;

    /**
     * Stores Apdex statistics aggregated by session, geography, and service.
     * Key format: "session-id``||``geo.country``||``geo.continent``||``service-name``||``event-source"
     * Value: Map of a user interaction type to count
     */
    private final Map<String, Map<String, Integer>> apdexStats = new HashMap<>();

    /**
     * Stores service-level statistics aggregated by service name, application ID, and service type.
     * Key format: "service-name``||``application-id``||``service-type"
     * Value: JsonObject containing aggregated service metrics
     */
    private final Map<String, JsonObject> serviceStats = new HashMap<>();

    /**
     * Reusable JsonObject for building event data to avoid object creation overhead.
     */
    private final JsonObject event = new JsonObject();

    /**
     * Reusable JsonObject for building search event data.
     */
    private final JsonObject searchEvent = new JsonObject();

    /**
     * Reusable JsonObject for storing geolocation information.
     */
    private final JsonObject geoLocationEvent = new JsonObject();

    /**
     * Set of column mappers for datastore operations.
     */
    private Set<String> mappers;

    /**
     * Reusable StringBuilder for efficient string concatenation during datastore writes.
     */
    private final StringBuilder builder = new StringBuilder();

    /**
     * Policy engine for processing RUM analytics policies.
     */
    private final PolicyEngine policyEngine;

    /**
     * Constructs a new RUMEventProcessor and initializes the policy engine.
     */
    public RUMEventProcessor()
    {
        this.policyEngine = new PolicyEngine(PolicyEngineConstants.PolicyType.RUM_ANALYTICS.getName());
    }

    /**
     * Starts the RUM event processor verticle.
     * <p>
     * Initializes event sources, sets up event bus consumers for policy management and event processing,
     * configures the event engine, and schedules periodic statistics broadcasting.
     *
     * @param promise Promise to complete when startup is successful or fail on error
     * @throws Exception if initialization fails
     */
    @Override
    public void start(Promise<Void> promise) throws Exception
    {
        try
        {
            mappers = new HashSet<>();

            var items = EventSourceConfigStore.getStore().flatItemsByValue(EventBusConstants.EVENT_TYPE, VisualizationConstants.VisualizationDataSource.RUM_VIEW.getName(), EVENT_SOURCE);

            if (items != null && !items.isEmpty())
            {
                for (var index = 0; index < items.size(); index++)
                {
                    var item = items.getJsonObject(index);

                    // Add new source if not already registered
                    if (!RUMCacheStore.getStore().getSources().contains(item.getString(EVENT_SOURCE)))
                    {
                        RUMCacheStore.getStore().addEventSource(item.getString(EVENT_SOURCE), RUMConstant.RUM_DATA_SOURCES, RUMConstant.RUM_PLUGIN_IDS);
                    }
                }
            }

            vertx.eventBus().<JsonObject>localConsumer(EVENT_CHANGE_NOTIFICATION, message ->
            {
                var event = message.body();

                switch (ChangeNotificationType.valueOf(event.getString(CHANGE_NOTIFICATION_TYPE)))
                {
                    case ADD_POLICY, UPDATE_POLICY ->
                    {
                        var policy = EventPolicyConfigStore.getStore().getItem(event.getLong(ID));

                        if(policy!= null && policyEngine.isApplicablePolicy(policy))
                        {
                            policyEngine.addPolicy(policy);
                        }
                    }

                    case DELETE_POLICY ->
                    {
                        policyEngine.removePolicy(event.getLong(ID));
                    }

                    case SUPPRESS_POLICY ->
                    {
                        if (message.body() != null)
                        {
                            policyEngine.suppressPolicy(event.getLong(POLICY_ID), true);
                        }
                    }

                    case UNSUPPRESS_POLICY ->
                    {
                        if (message.body() != null)
                        {
                            policyEngine.suppressPolicy(event.getLong(POLICY_ID), false);
                        }
                    }

                    case DISABLE_POLICY_ACTION_TRIGGER ->
                    {
                        var item = SchedulerConfigStore.getStore().getItem(event.getLong(ID));

                        if (item != null)
                        {
                            Bootstrap.configDBService().delete(DBConstants.TBL_SCHEDULER, new JsonObject().put(DBConstants.FIELD_NAME, ID).put(VALUE, event.getLong(ID)), DEFAULT_USER, SYSTEM_REMOTE_ADDRESS, future ->
                            {
                                if (future.succeeded())
                                {
                                    SchedulerConfigStore.getStore().deleteItem(event.getLong(ID));

                                    JobScheduler.removeJob(event.getLong(ID));
                                }
                            });
                        }
                    }
                    default ->
                    {
                        // do nothing
                    }
                }
            }).exceptionHandler(LOGGER::error);


            vertx.eventBus().<JsonObject>request(EventBusConstants.EVENT_EVENT_COLUMN_MAPPER_QUERY, EMPTY_VALUE, reply ->
            {
                try
                {
                    var item = reply.result();

                    if (item != null && item.body() != null)
                    {
                        // Initialize the policy engine with event columns and policies
                        policyEngine.initialize(item.body().getJsonObject(DatastoreConstants.EVENT_COLUMNS), EventPolicyConfigStore.getStore().getItems());
                    }
                }
                catch (Exception exception)
                {
                    LOGGER.error(exception);
                }
            });

            vertx.eventBus().<JsonObject>localConsumer(EventBusConstants.EVENT_COLUMN_MAPPER_UPDATE, message ->
            {
                try
                {
                    var event = message.body();

                    var tokens = event.getString(DatastoreConstants.MAPPER).split(GlobalConstants.COLUMN_SEPARATOR, -1);

                    if (event.getString(CHANGE_NOTIFICATION_TYPE).equalsIgnoreCase(EventBusConstants.ChangeNotificationType.UPDATE_EVENT_COLUMN.name()))
                    {
                        policyEngine.updateEventColumns(tokens);
                    }
                    else if(event.getString(CHANGE_NOTIFICATION_TYPE).equalsIgnoreCase(EventBusConstants.ChangeNotificationType.DELETE_EVENT_COLUMN.name()))
                    {
                        policyEngine.deleteEventColumns(event.getString(DatastoreConstants.MAPPER));
                    }
                }
                catch (Exception exception)
                {
                    LOGGER.error(exception);
                }
            }).exceptionHandler(LOGGER::error);

            vertx.eventBus().<JsonObject>localConsumer(EVENT_EVENT_POLICY_SUPPRESS, message ->
                    message.reply(message.body() != null && policyEngine.isPolicySuppressed(message.body().getLong(POLICY_ID))));

            // Registers a local consumer to handle policy stats fetch requests.
            // This is triggered by the EventPolicyInspector to collect current group statistics
            // for a given policy ID. The collected stats are processed and sent back via event bus.
            vertx.eventBus().<Long>localConsumer(EVENT_EVENT_POLICY_AGGREGATOR_QUERY + DOT_SEPARATOR + PolicyEngineConstants.PolicyType.RUM_ANALYTICS.getName(), message ->
            {
                try
                {
                    var id = message.body();

                    var item = new JsonObject().put(ID, id).put(RESULT, policyEngine.getPolicyStats(id)); //taking variable for logging purpose...

                    message.reply(item);

                    if(CommonUtil.debugEnabled())
                    {
                        LOGGER.debug(EventPolicyConfigStore.getStore().getItem(id).getString(POLICY_NAME) + " :  " + item);
                    }
                }
                catch (Exception exception)
                {
                    LOGGER.error(exception);
                }

            });

            eventEngine = new EventEngine()
                    .setLogger(LOGGER)
                    .setEventType(config().getString(EventBusConstants.EVENT_TYPE))
                    .setPersistEventOffset(true)
                    .setEventQueueSize(MotadataConfigUtil.getRUMProcessorQueueSize())
                    .setEventHandler(this::process)
                    .start(vertx, promise);

            // broadcasting stats to stat calculator
            vertx.setPeriodic(60 * 1000, timer ->
            {
                vertx.eventBus().send(EVENT_RUM_STAT, new JsonObject().put("apdex.stats", apdexStats)
                        .put("service.stats", serviceStats));

                apdexStats.clear();

                serviceStats.clear();
            });

            // adding shadow counters as these columns are floating
            vertx.eventBus().publish(EventBusConstants.EVENT_CHANGE_NOTIFICATION,
                    new JsonObject()
                            .put(CHANGE_NOTIFICATION_TYPE, ChangeNotificationType.ADD_SHADOW_COUNTERS.name())
                            .put(KEY, RUM_APDEX_RATE).put(VALUE, RUM_APDEX_RATE));

            vertx.eventBus().publish(EventBusConstants.EVENT_CHANGE_NOTIFICATION,
                    new JsonObject()
                            .put(CHANGE_NOTIFICATION_TYPE, ChangeNotificationType.ADD_SHADOW_COUNTERS.name())
                            .put(KEY, RUM_VIEW_CUMULATIVE_LAYOUT_SHIFT).put(VALUE, RUM_VIEW_CUMULATIVE_LAYOUT_SHIFT));
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);

            promise.fail(exception);
        }
    }

    /**
     * Processes incoming RUM event messages from the event bus.
     * <p>
     * Decodes IP addresses for geolocation, parses individual events based on type,
     * and handles event validation and error tracking.
     *
     * @param message JsonObject containing the RUM event batch and metadata
     */
    private void process(JsonObject message)
    {
        var applicationId = EMPTY_VALUE;

        try
        {
            if (message.containsKey(EventBusConstants.EVENT) && RUMCacheStore.getStore().getMaxEvents() > 0)
            {
                RUMCacheStore.getStore().addEventSource(message.getString(EVENT_SOURCE), RUMConstant.RUM_DATA_SOURCES, RUMConstant.RUM_PLUGIN_IDS);

                var batches = message.getString(EventBusConstants.EVENT);

                if (!batches.isEmpty() && !batches.equals("{}"))
                {
                    var events = batches.split("\\n");

                    if (events.length >= 1) decodeIP(message, "geo.location");

                    for (var item : events)
                    {
                        try
                        {
                            // Skip empty or whitespace-only items
                            if (item == null || item.trim().isEmpty())
                            {
                                RUMCacheStore.getStore().updateFaultyEvents(1);

                                continue;
                            }

                            event.clear().put(EVENT_SOURCE, message.getString(EVENT_SOURCE));

                            var rumEvent = new JsonObject(item).put(RUMConstant.RUM_VIEW_BROWSER, message.getString(BROWSER))
                                    .put(RUMConstant.RUM_VIEW_BROWSER_OS, message.getString(RUMConstant.BROWSER_OS))
                                    .put(RUMConstant.RUM_VIEW_CONTINENT, message.getString(RUMConstant.GEO_LOCATION_CONTINENT))
                                    .put(RUMConstant.RUM_VIEW_COUNTRY, message.getString(RUMConstant.GEO_LOCATION_COUNTRY))
                                    .put(RUMConstant.RUM_VIEW_CITY, message.getString(RUMConstant.GEO_LOCATION_CITY));

                            // subtracting 1 from event counter
                            RUMCacheStore.getStore().subtract(2); // 1 event for the main event and 1 for search event table

                            RUMCacheStore.getStore().updateEvents(2); // 1 event for the main event and 1 for search event table

                            applicationId = rumEvent.getJsonObject(RUMConstant.APPLICATION).getString(GlobalConstants.ID);

                            switch (RUMConstant.EventType.valueOfName(rumEvent.getString(RUMConstant.TYPE)))
                            {
                                case VIEW -> parseView(rumEvent);

                                case LONG_TASK -> parseLongTask(rumEvent);

                                case RESOURCE -> parseResource(rumEvent);

                                case ERROR -> parseError(rumEvent);

                                case ACTION -> parseAction(rumEvent);

                                case null, default -> LOGGER.warn(String.format("unknown event type: %s for RUM event", rumEvent.getString(RUMConstant.TYPE)));
                            }
                        }
                        catch (Exception exception)
                        {
                            LOGGER.warn("Failed to process RUM event from source: " + message.getString(EVENT_SOURCE) + ", event: " + item);

                            RUMCacheStore.getStore().updateFaultyEvents(1);

                            LOGGER.error(exception);
                        }
                    }
                }
            }
            else
            {
                LOGGER.info(String.format("RUM Event limit exceeded %s, dropping rum events", RUMConstant.RUM_MAX_EVENTS));
            }
        }
        catch (Exception exception)
        {
            LOGGER.warn("Failed to process RUM event from source: " + message.getString(EVENT_SOURCE));

            LOGGER.error(exception);
        }
        finally
        {
            RUMCacheStore.getStore().updateLastReceived(applicationId);

            event.clear();

            geoLocationEvent.clear();

            searchEvent.clear();
        }
    }

    /**
     * Parses a RUM VIEW event and extracts relevant metrics.
     * <p>
     * Processes view-level metrics including loading time, contentful paint metrics, layout shift,
     * and associated counts for errors, actions, resources, and long tasks.
     *
     * @param rumEvent JsonObject containing the raw VIEW event data
     */
    private void parseView(JsonObject rumEvent)
    {
        try
        {
            var item = RUMServiceProfileConfigStore.getStore().getItemByValue(RUMServiceProfile.RUM_PROFILE_NAME, rumEvent.getString(RUMConstant.SERVICE));

            var application = rumEvent.getJsonObject(RUMConstant.APPLICATION);

            var session = rumEvent.getJsonObject(RUMConstant.SESSION);

            var view = rumEvent.getJsonObject(RUMConstant.EventType.VIEW.getEventType());

            if (view.getString("is_view_completed", NO).equalsIgnoreCase(NO)) return;

            var timestamp = RUMConstant.convertTime(rumEvent.getLong(RUMConstant.DATE), TimeUnit.MILLISECONDS, TimeUnit.SECONDS);

            var attribute = new JsonObject();

            parseTags(rumEvent.getString("mdtags"), attribute, EventType.VIEW);

            event.put(RUMConstant.RUM_VIEW_APPLICATION_ID, application.getString(RUMConstant.ID))
                    .put(RUMConstant.RUM_VIEW_SESSION_ID, session.getString(RUMConstant.ID))
                    .put(RUMConstant.RUM_VIEW_SESSION_TYPE, session.getString(RUMConstant.TYPE))
                    .put(RUMConstant.RUM_VIEW_ID, view.getString(RUMConstant.ID))
                    .put(RUMConstant.RUM_VIEW_NAME, view.getString(NAME, RUMConstant.getDefaultViewName(view.getString(URL))))
                    .put(RUMConstant.RUM_VIEW_TIMESTAMP, RUMConstant.convertTime(rumEvent.getLong(DATE), TimeUnit.MILLISECONDS, TimeUnit.SECONDS))
                    .put(RUMConstant.RUM_VIEW_LOADING_TYPE, view.getString("loading_type")) // SUBTYPE
                    .put(RUMConstant.RUM_VIEW_LOADING_TIME_US, RUMConstant.convertTime(view.getLong("loading_time", 0L), TimeUnit.NANOSECONDS, TimeUnit.MICROSECONDS))
                    .put(RUMConstant.RUM_VIEW_TIME_SPENT_US, RUMConstant.convertTime(CommonUtil.getLong(view.getString("time_spent")), TimeUnit.NANOSECONDS, TimeUnit.MICROSECONDS))
                    .put(RUMConstant.RUM_VIEW_VERSION, item.getString(RUMServiceProfile.RUM_PROFILE_VERSION))
                    .put(RUMConstant.RUM_VIEW_SERVICE_NAME, rumEvent.getString(RUMConstant.SERVICE))
                    .put(RUMConstant.RUM_VIEW_ERRORS, view.getJsonObject(RUMConstant.EventType.ERROR.getEventType()).getInteger(RUMConstant.COUNT))
                    .put(RUMConstant.RUM_VIEW_ACTIONS, view.getJsonObject(RUMConstant.EventType.ACTION.getEventType()).getInteger(RUMConstant.COUNT))
                    .put(RUMConstant.RUM_VIEW_RESOURCES, view.getJsonObject(RUMConstant.EventType.RESOURCE.getEventType()).getInteger(RUMConstant.COUNT))
                    .put(RUMConstant.RUM_VIEW_LONG_TASKS, view.getJsonObject(RUMConstant.EventType.LONG_TASK.getEventType()).getInteger(RUMConstant.COUNT))
                    .put(RUMConstant.RUM_VIEW_FRUSTRATIONS, view.getJsonObject(RUMConstant.FRUSTRATION).getInteger(RUMConstant.COUNT))
                    .put(RUMConstant.RUM_VIEW_FIRST_CONTENTFUL_PAINT_US, RUMConstant.convertTime(view.getLong("first_contentful_paint", 0L), TimeUnit.NANOSECONDS, TimeUnit.MICROSECONDS))
                    .put(RUMConstant.RUM_VIEW_LARGEST_CONTENTFUL_PAINT_US, RUMConstant.convertTime(view.getLong("largest_contentful_paint", 0L), TimeUnit.NANOSECONDS, TimeUnit.MICROSECONDS))
                    .put(RUMConstant.RUM_VIEW_CUMULATIVE_LAYOUT_SHIFT, view.getFloat("cumulative_layout_shift", 0f))
                    .put(RUMConstant.RUM_VIEW_ENVIRONMENT, item.getString(RUMServiceProfile.RUM_PROFILE_ENVIRONMENT))
                    .put(RUMConstant.RUM_VIEW_BROWSER, rumEvent.getString(RUMConstant.RUM_VIEW_BROWSER))
                    .put(RUMConstant.RUM_VIEW_BROWSER_OS, rumEvent.getString(R

Constant.COUNT))
                    .put(RUMConstant.RUM_VIEW_LONG_TASKS, view.getJsonObject(RUMConstant.EventType.LONG_TASK.getEventType()).getInteger(RUMConstant.COUNT))
                    .put(RUMConstant.RUM_VIEW_FRUSTRATIONS, view.getJsonObject(RUMConstant.FRUSTRATION).getInteger(RUMConstant.COUNT))
                    .put(RUMConstant.RUM_VIEW_FIRST_CONTENTFUL_PAINT_US, RUMConstant.convertTime(view.getLong("first_contentful_paint", 0L), TimeUnit.NANOSECONDS, TimeUnit.MICROSECONDS))
                    .put(RUMConstant.RUM_VIEW_LARGEST_CONTENTFUL_PAINT_US, RUMConstant.convertTime(view.getLong("largest_contentful_paint", 0L), TimeUnit.NANOSECONDS, TimeUnit.MICROSECONDS))
                    .put(RUMConstant.RUM_VIEW_CUMULATIVE_LAYOUT_SHIFT, view.getFloat("cumulative_layout_shift", 0f))
                    .put(RUMConstant.RUM_VIEW_ENVIRONMENT, item.getString(RUMServiceProfile.RUM_PROFILE_ENVIRONMENT))
                    .put(RUMConstant.RUM_VIEW_BROWSER, rumEvent.getString(RUMConstant.RUM_VIEW_BROWSER))
                    .put(RUMConstant.RUM_VIEW_BROWSER_OS, rumEvent.getString(RUMConstant.RUM_VIEW_BROWSER_OS))
                    .put(RUMConstant.RUM_VIEW_CONTINENT, rumEvent.getString(RUMConstant.RUM_VIEW_CONTINENT, UNKNOWN))
                    .put(RUMConstant.RUM_VIEW_COUNTRY, rumEvent.getString(RUMConstant.RUM_VIEW_COUNTRY, UNKNOWN))
                    .put(RUMConstant.RUM_VIEW_CITY, rumEvent.getString(RUMConstant.RUM_VIEW_CITY, UNKNOWN))
                    .put(RUMConstant.RUM_VIEW_COUNTRY_CODE, event.getString(RUMConstant.RUM_VIEW_COUNTRY, UNKNOWN).equalsIgnoreCase(UNKNOWN) ? "-" :
                            GeoDBUtil.getCountryGeoLocation(event.getString(RUMConstant.RUM_VIEW_COUNTRY)) == null ? "-" : CommonUtil.getString(GeoDBUtil.getCountryGeoLocation(event.getString(RUMConstant.RUM_VIEW_COUNTRY)).getValue(FlowEngineConstants.COUNTRY_CODE, "-")))
                    .put(RUMConstant.RUM_VIEW_IS_ACTIVE, view.getBoolean("is_active", false).equals(true) ? YES : NO)
                    .put(RUMConstant.RUM_VIEW_EVENTS, rumEvent.encode())
                    .put(RUMConstant.RUM_VIEW_CREATED_TIME_MS, rumEvent.getJsonObject("session").getLong("created"))
                    .put(RUM_VIEW_RELATIVE_TIME_US, RUMConstant.convertTime(rumEvent.getJsonObject("context").getJsonObject("_timing").getLong("relativeTime"), TimeUnit.NANOSECONDS, TimeUnit.MICROSECONDS))
                    .put(RUMConstant.RUM_VIEW_INTERACTION_TO_NEXT_PAINT_US, RUMConstant.convertTime(view.getLong("interaction_to_next_paint", 0L), TimeUnit.NANOSECONDS, TimeUnit.MICROSECONDS))
                    .put(EventBusConstants.EVENT_TIMESTAMP, RUMConstant.convertTime(rumEvent.getLong(DATE), TimeUnit.MILLISECONDS, TimeUnit.SECONDS));

            view.mergeIn(event);

            populateAttribute(view, attribute, RUMConstant.EventType.VIEW);

            event.put(RUMConstant.RUM_VIEW_ATTRIBUTE_EVENT, RUMConstant.packEvent(attribute, DatastoreConstants.PluginId.RUM_VIEW.getName(), LOGGER));

            if (valid())
            {
                // updating apdex stats
                updateApdexStats();

                // updating service stats
                updateServiceStats();
            }

            if (MotadataConfigUtil.devMode())
            {
                // Send parsed event to test consumer
                vertx.eventBus().send("rum.view.test", event.copy());
            }
            // dumping view data into datastore
            DatastoreConstants.write(event.put(PLUGIN_ID, DatastoreConstants.PluginId.RUM_VIEW.getName())
                    .put(DATASTORE_CATEGORY, DatastoreConstants.DatastoreCategory.TRACE.getName())
                    .put(DatastoreConstants.DATASTORE_TYPE, DatastoreConstants.DatastoreType.RUM_EVENT.ordinal()), VisualizationConstants.VisualizationDataSource.RUM_VIEW.getName(), mappers, builder);

            policyEngine.processEvent(event.put(RUMConstant.RUM_ID, item.getLong(ID)).put(RUMConstant.SERVICE_NAME, event.getString(RUMConstant.RUM_VIEW_SERVICE_NAME)));

            processSearchEvent(EventType.VIEW, timestamp);

            if (CommonUtil.debugEnabled())
            {
                LOGGER.debug("RUM View Event : " + event.encodePrettily());
            }
        }
        catch (Exception exception)
        {
            LOGGER.warn("Failed to parse RUM view event");

            LOGGER.error(exception);
        }
    }

    /**
     * Parses a RUM LONG_TASK event and extracts performance metrics.
     * <p>
     * Processes long task metrics including duration, start time, render timing,
     * processing time, presentation time, and associated script information.
     *
     * @param rumEvent JsonObject containing the raw LONG_TASK event data
     */
    private void parseLongTask(JsonObject rumEvent)
    {
        try
        {
            var service = RUMServiceProfileConfigStore.getStore().getItemByValue(RUMServiceProfile.RUM_PROFILE_NAME, rumEvent.getString(RUMConstant.SERVICE));

            var application = rumEvent.getJsonObject(RUMConstant.APPLICATION);

            var session = rumEvent.getJsonObject(RUMConstant.SESSION);

            var view = rumEvent.getJsonObject(RUMConstant.EventType.VIEW.getEventType());

            var longTask = rumEvent.getJsonObject(RUMConstant.EventType.LONG_TASK.getEventType());

            var timestamp = RUMConstant.convertTime(rumEvent.getLong(RUMConstant.DATE), TimeUnit.MILLISECONDS, TimeUnit.SECONDS);

            var attribute = new JsonObject();

            parseTags(rumEvent.getString("mdtags"), attribute, EventType.LONG_TASK);

            event.put(RUM_VIEW_LONG_TASK_APPLICATION_ID, application.getString(RUMConstant.ID))
                    .put(RUM_VIEW_LONG_TASK_SESSION_ID, session.getString(RUMConstant.ID))
                    .put(RUM_VIEW_LONG_TASK_SESSION_TYPE, session.getString(RUMConstant.TYPE))
                    .put(RUM_VIEW_LONG_TASK_VIEW_ID, view.getString(RUMConstant.ID))
                    .put(RUM_LONG_TASK_VIEW_NAME, view.getString(NAME, RUMConstant.getDefaultViewName(view.getString(URL))))
                    .put(RUM_VIEW_LONG_TASK_TIMESTAMP, timestamp)
                    .put(RUM_VIEW_LONG_TASK_ID, longTask.getString(RUMConstant.ID))
                    .put(RUM_VIEW_LONG_TASK_DURATION_US, RUMConstant.convertTime(longTask.getLong(RUMConstant.DURATION), TimeUnit.NANOSECONDS, TimeUnit.MICROSECONDS))
                    .put(RUM_VIEW_LONG_TASK_START_TIME_US, RUMConstant.convertTime(longTask.getLong("start_time"), TimeUnit.NANOSECONDS, TimeUnit.MICROSECONDS))
                    .put(RUM_VIEW_LONG_TASK_RENDER_START_US, RUMConstant.convertTime(longTask.getLong("render_start"), TimeUnit.NANOSECONDS, TimeUnit.MICROSECONDS))
                    .put(RUM_VIEW_LONG_TASK_PROCESSING_TIME_US, event.getLong(RUM_VIEW_LONG_TASK_RENDER_START_US) - event.getLong(RUM_VIEW_LONG_TASK_START_TIME_US))
                    .put(RUM_VIEW_LONG_TASK_PRESENTATION_TIME_US, event.getLong(RUM_VIEW_LONG_TASK_DURATION_US) - event.getLong(RUM_VIEW_LONG_TASK_PROCESSING_TIME_US))
                    .put(RUM_VIEW_LONG_TASK_STYLE_LAYOUT_DURATION_US, event.getLong(RUM_VIEW_LONG_TASK_START_TIME_US) + event.getLong(RUM_VIEW_LONG_TASK_DURATION_US) - RUMConstant.convertTime(longTask.getLong("style_and_layout_start", 0L), TimeUnit.NANOSECONDS, TimeUnit.MICROSECONDS))
                    .put(RUM_VIEW_LONG_TASK_SCRIPTS, getValue(longTask.getJsonArray("scripts")))
                    .put(RUM_VIEW_LONG_TASK_ACTION_IDS, rumEvent.getJsonObject(RUMConstant.EventType.ACTION.getEventType()).getString(RUMConstant.ID))
                    .put(RUM_VIEW_LONG_TASK_SERVICE_NAME, rumEvent.getString(RUMConstant.SERVICE))
                    .put(RUM_VIEW_LONG_TASK_VERSION, service.getString(RUMServiceProfile.RUM_PROFILE_VERSION))
                    .put(RUMConstant.RUM_VIEW_LONG_TASK_ENVIRONMENT, service.getString(RUMServiceProfile.RUM_PROFILE_ENVIRONMENT))
                    .put(RUM_VIEW_LONG_TASK_BROWSER, rumEvent.getString(RUMConstant.RUM_VIEW_BROWSER))
                    .put(RUM_VIEW_LONG_TASK_BROWSER_OS, rumEvent.getString(RUMConstant.RUM_VIEW_BROWSER_OS))
                    .put(RUM_VIEW_LONG_TASK_CONTINENT, rumEvent.getString(RUMConstant.RUM_VIEW_CONTINENT, UNKNOWN))
                    .put(RUM_VIEW_LONG_TASK_COUNTRY, rumEvent.getString(RUMConstant.RUM_VIEW_COUNTRY, UNKNOWN))
                    .put(RUM_VIEW_LONG_TASK_BLOCKING_DURATION_US, longTask.getInteger("blocking_duration", 0))
                    .put(RUM_VIEW_LONG_TASK_CITY, rumEvent.getString(RUMConstant.RUM_VIEW_CITY, UNKNOWN))
                    .put(RUM_VIEW_LONG_TASK_EVENT, rumEvent.encode())
                    .put(EventBusConstants.EVENT_TIMESTAMP, timestamp)
                    .put(RUM_VIEW_LONG_TASK_CREATED_TIME_MS, rumEvent.getJsonObject("session").getLong("created"))
                    .put(RUM_VIEW_LONG_TASK_RELATIVE_TIME_US, RUMConstant.convertTime(rumEvent.getJsonObject("context").getJsonObject("_timing").getLong("relativeTime"), TimeUnit.NANOSECONDS, TimeUnit.MICROSECONDS))
                    .put(RUM_VIEW_LONG_TASK_NAME, "Long Task");

            if (event.getLong(RUM_VIEW_LONG_TASK_RENDER_START_US) == 0 || event.getLong(RUM_VIEW_LONG_TASK_PROCESSING_TIME_US) <= 0)
            {
                event.put(RUM_VIEW_LONG_TASK_PROCESSING_TIME_US, event.getLong(RUM_VIEW_LONG_TASK_START_TIME_US));
            }

            if (longTask.containsKey("scripts") && !longTask.getJsonArray("scripts").isEmpty())
            {
                // overriding default name with script name
                var scripts = longTask.getJsonArray("scripts");

                event.put(RUM_VIEW_LONG_TASK_NAME, scripts.getJsonObject(0).getString("invoker_type", EMPTY_VALUE) + COLON_SEPARATOR + scripts.getJsonObject(0).getString("invoker", EMPTY_VALUE));
            }

            longTask.mergeIn(event).mergeIn(view);

            for (var key : rumEvent.getJsonObject("connectivity", new JsonObject()).getMap().keySet())
            {
                longTask.put("connectivity."+key, rumEvent.getJsonObject("connectivity").getValue(key));
            }

            populateAttribute(longTask, attribute, EventType.LONG_TASK);

            event.put(RUMConstant.RUM_VIEW_LONG_TASK_ATTRIBUTE_EVENT, RUMConstant.packEvent(attribute, DatastoreConstants.PluginId.RUM_VIEW_LONG_TASK.getName(), LOGGER));

            if (MotadataConfigUtil.devMode())
            {
                // Send parsed event to test consumer
                vertx.eventBus().send("rum.longtask.test", event.copy());
            }

            DatastoreConstants.write(event.put(PLUGIN_ID, DatastoreConstants.PluginId.RUM_VIEW_LONG_TASK.getName())
                    .put(DATASTORE_CATEGORY, DatastoreConstants.DatastoreCategory.TRACE.getName())
                    .put(DatastoreConstants.DATASTORE_TYPE, DatastoreConstants.DatastoreType.RUM_EVENT.ordinal()), VisualizationConstants.VisualizationDataSource.RUM_VIEW_LONG_TASK.getName(), mappers, builder);

            policyEngine.processEvent(event.put(RUMConstant.RUM_ID, service.getLong(ID)).put(RUMConstant.SERVICE_NAME, event.getString(RUMConstant.RUM_VIEW_LONG_TASK_SERVICE_NAME)));

            processSearchEvent(EventType.LONG_TASK, timestamp);

            if (CommonUtil.debugEnabled())
            {
                LOGGER.debug("RUM Long Task Event : " + event.encodePrettily());
            }
        }
        catch (Exception exception)
        {
            LOGGER.warn("Failed to parse RUM long task event");

            LOGGER.error(exception);
        }
    }

    /**
     * Parses a RUM RESOURCE event and extracts resource loading metrics.
     * <p>
     * Processes resource metrics including type, duration, size, status code,
     * and timing breakdowns (download, first byte, connect, DNS).
     *
     * @param rumEvent JsonObject containing the raw RESOURCE event data
     */
    private void parseResource(JsonObject rumEvent)
    {
        try
        {
            var item = RUMServiceProfileConfigStore.getStore().getItemByValue(RUMServiceProfile.RUM_PROFILE_NAME, rumEvent.getString(RUMConstant.SERVICE));

            var application = rumEvent.getJsonObject(RUMConstant.APPLICATION);

            var session = rumEvent.getJsonObject(RUMConstant.SESSION);

            var view = rumEvent.getJsonObject(RUMConstant.EventType.VIEW.getEventType());

            var resource = rumEvent.getJsonObject(RUMConstant.EventType.RESOURCE.getEventType());

            resource.put(RUMConstant.URL, trim(resource.getString(RUMConstant.URL), RUM_RESOURCE_URL_MAX_SIZE));

            var timestamp = RUMConstant.convertTime(rumEvent.getLong(RUMConstant.DATE), TimeUnit.MILLISECONDS, TimeUnit.SECONDS);

            var attribute = new JsonObject();

            parseTags(rumEvent.getString("mdtags"), attribute, EventType.RESOURCE);

            event.put(RUM_VIEW_RESOURCE_APPLICATION_ID, application.getString(RUMConstant.ID))
                    .put(RUM_VIEW_RESOURCE_SESSION_ID, session.getString(RUMConstant.ID))
                    .put(RUM_VIEW_RESOURCE_SESSION_TYPE, session.getString(RUMConstant.TYPE))
                    .put(RUM_VIEW_RESOURCE_VIEW_ID, view.getString(RUMConstant.ID))
                    .put(RUM_VIEW_RESOURCE_VIEW_NAME, view.getString(NAME, RUMConstant.getDefaultViewName(view.getString(URL))))
                    .put(RUM_VIEW_RESOURCE_TIMESTAMP, timestamp)
                    .put(RUM_VIEW_RESOURCE_ID, resource.getString(RUMConstant.ID))
                    .put(RUM_VIEW_RESOURCE_TYPE, resource.getString(RUMConstant.TYPE))
                    .put(RUM_VIEW_RESOURCE_NAME, getResourceName(resource))
                    .put(RUM_VIEW_RESOURCE_URL, resource.getString(RUMConstant.URL))
                    .put(RUM_VIEW_RESOURCE_DURATION_US, RUMConstant.convertTime(resource.getLong(RUMConstant.DURATION), TimeUnit.NANOSECONDS, TimeUnit.MICROSECONDS))
                    .put(RUM_VIEW_RESOURCE_SIZE_BYTES, resource.getLong("size"))
                    .put(RUM_VIEW_RESOURCE_STATUS_CODE, resource.getLong("status_code"))
                    .put(RUM_VIEW_RESOURCE_ACTION_IDS, rumEvent.getJsonObject(RUMConstant.EventType.ACTION.getEventType()).getString(RUMConstant.ID))
                    .put(RUM_VIEW_RESOURCE_VERSION, item.getString(RUMServiceProfile.RUM_PROFILE_VERSION))
                    .put(RUM_VIEW_RESOURCE_SERVICE_NAME, rumEvent.getString(RUMConstant.SERVICE))
                    .put(RUMConstant.RUM_VIEW_RESOURCE_ENVIRONMENT, item.getString(RUMServiceProfile.RUM_PROFILE_ENVIRONMENT))
                    .put(RUMConstant.RUM_VIEW_RESOURCE_BROWSER, rumEvent.getString(RUMConstant.RUM_VIEW_BROWSER))
                    .put(RUMConstant.RUM_VIEW_RESOURCE_BROWSER_OS, rumEvent.getString(RUMConstant.RUM_VIEW_BROWSER_OS))
                    .put(RUMConstant.RUM_VIEW_RESOURCE_CONTINENT, rumEvent.getString(RUMConstant.RUM_VIEW_CONTINENT, UNKNOWN))
                    .put(RUMConstant.RUM_VIEW_RESOURCE_COUNTRY, rumEvent.getString(RUMConstant.RUM_VIEW_COUNTRY, UNKNOWN))
                    .put(RUMConstant.RUM_VIEW_RESOURCE_CITY, rumEvent.getString(RUMConstant.RUM_VIEW_CITY, UNKNOWN))
                    .put(EventBusConstants.EVENT_TIMESTAMP, timestamp)
                    .put(RUM_VIEW_RESOURCE_EVENT, rumEvent.encode())
                    .put(RUMConstant.RUM_VIEW_RESOURCE_CREATED_TIME_MS, rumEvent.getJsonObject("session").getLong("created"))
                    .put(RUM_VIEW_RESOURCE_RELATIVE_TIME_US, RUMConstant.convertTime(rumEvent.getJsonObject("context").getJsonObject("_timing").getLong("relativeTime"), TimeUnit.NANOSECONDS, TimeUnit.MICROSECONDS))
                    .put(RUM_VIEW_RESOURCES, new JsonArray()
                            .add(new JsonObject().put("download", resource.getJsonObject("download", new JsonObject())))
                            .add(new JsonObject().put("first.byte", resource.getJsonObject("first_byte", new JsonObject())))
                            .add(new JsonObject().put("connect", resource.getJsonObject("connect", new JsonObject())))
                            .add(new JsonObject().put("dns", resource.getJsonObject("dns", new JsonObject()))))
                    .put(RUM_VIEW_RESOURCE_DOWNLOAD_DURATION_US, RUMConstant.convertTime(resource.getJsonObject("download", new JsonObject()).getLong(RUMConstant.DURATION, 0L), TimeUnit.NANOSECONDS, TimeUnit.MICROSECONDS))
                    .put(RUM_VIEW_RESOURCE_FIRST_BYTE_DURATION_US, RUMConstant.convertTime(resource.getJsonObject("first_byte", new JsonObject()).getLong(RUMConstant.DURATION, 0L), TimeUnit.NANOSECONDS, TimeUnit.MICROSECONDS))
                    .put(RUM_VIEW_RESOURCE_REDIRECT_DURATION_US, RUMConstant.convertTime(resource.getJsonObject("redirect", new JsonObject()).getLong(RUMConstant.DURATION, 0L), TimeUnit.NANOSECONDS, TimeUnit.MICROSECONDS));

            resource.mergeIn(event).mergeIn(view);

            for (var key : rumEvent.getJsonObject("connectivity", new JsonObject()).getMap().keySet())
            {
                resource.put("connectivity."+key, rumEvent.getJsonObject("connectivity").getValue(key));
            }

            populateAttribute(resource, attribute, EventType.RESOURCE);

            attribute.put("resource.url", resource.getString(RUMConstant.URL));

            event.put(RUMConstant.RUM_VIEW_RESOURCE_ATTRIBUTE_EVENT, RUMConstant.packEvent(attribute, DatastoreConstants.PluginId.RUM_VIEW_RESOURCE.getName(), LOGGER));

            if (MotadataConfigUtil.devMode())
            {
                // Send parsed event to test consumer
                vertx.eventBus().send("rum.resource.test", event.copy());
            }

            DatastoreConstants.write(event.put(PLUGIN_ID, DatastoreConstants.PluginId.RUM_VIEW_RESOURCE.getName())
                    .put(DATASTORE_CATEGORY, DatastoreConstants.DatastoreCategory.TRACE.getName())
                    .put(DatastoreConstants.DATASTORE_TYPE, DatastoreConstants.DatastoreType.RUM_EVENT.ordinal()), VisualizationConstants.VisualizationDataSource.RUM_VIEW_RESOURCE.getName(), mappers, builder);

            policyEngine.processEvent(event.put(RUMConstant.RUM_ID, item.getLong(ID)).put(RUMConstant.SERVICE_NAME, event.getString(RUMConstant.RUM_VIEW_RESOURCE_SERVICE_NAME)));

            processSearchEvent(EventType.RESOURCE, timestamp);

            if (CommonUtil.debugEnabled())
            {
                LOGGER.debug("RUM Resource Event : " + event.encodePrettily());
            }
        }
        catch (Exception exception)
        {
            LOGGER.warn("Failed to parse RUM resource event");

            LOGGER.error(exception);
        }
    }

