   /**
    * Generates a human-readable name for a resource event.
    *
    * @param resource JsonObject containing resource data
    * @return Formatted resource name (e.g., "Load css file /styles/main.css")
    */
   private String getResourceName(JsonObject resource)
   {
       return "Load" + SPACE_SEPARATOR + resource.getString(RUMConstant.TYPE) + SPACE_SEPARATOR + "file" + SPACE_SEPARATOR + resource.getString(RUMConstant.URL);
   }

   /**
    * Generates a human-readable name for an action event.
    *
    * @param action JsonObject containing action data
    * @return Formatted action name (e.g., "click on button")
    */
   private Object getActionName(JsonObject action)
   {
       return action.getString(RUMConstant.TYPE, EMPTY_VALUE) + SPACE_SEPARATOR + "on" + SPACE_SEPARATOR + action.getJsonObject("target").getString("name");
   }

   /**
    * Generates a human-readable name for an error event.
    *
    * @param error JsonObject containing error data
    * @return Formatted error name including source, type, and message
    */
   private String getErrorName(JsonObject error)
   {
       return error.getString("source", EMPTY_VALUE) + SPACE_SEPARATOR + "error" + SPACE_SEPARATOR + error.getString("type", EMPTY_VALUE) + SPACE_SEPARATOR + error.getString("message", EMPTY_VALUE);
   }

   /**
    * Processes and writes a search event to the datastore for quick event lookup.
    * <p>
    * Creates a normalized search event record containing common fields across all event types
    * to enable efficient searching and filtering.
    *
    * @param eventType Type of RUM event (VIEW, LONG_TASK, RESOURCE, ERROR, ACTION)
    * @param timeStamp Event timestamp in seconds
    */
   public void processSearchEvent(RUMConstant.EventType eventType, long timeStamp)
   {
       try
       {
           searchEvent.clear();

           switch (eventType)
           {
               case VIEW -> searchEvent.put(RUM_SEARCH_EVENT_ID, event.getString(RUM_VIEW_ID))
