    /**
     * Decodes IP address to geolocation information and enriches the message.
     * <p>
     * Resolves IP to country, city, continent, and domain using GeoIP database
     * and DNS cache. Merges the geolocation data into the message.
     *
     * @param message JsonObject to enrich with geolocation data
     * @param type Geolocation type prefix (e.g., "geo.location")
     */
    private void decodeIP(JsonObject message, String type)
    {
        var ipAddress = message.getString(EVENT_SOURCE);

        try
        {
            // default values (no need to add in fieldDefaultValues)
            geoLocationEvent.put(type + ".country", GlobalConstants.UNKNOWN.toLowerCase(Locale.ROOT))
                    .put(type + ".city", GlobalConstants.UNKNOWN.toLowerCase(Locale.ROOT))
                    .put(type + ".continent", GlobalConstants.UNKNOWN.toLowerCase(Locale.ROOT))
                    .put(type + ".domain", GlobalConstants.UNKNOWN.toLowerCase(Locale.ROOT));

            var location = GeoDBUtil.resolveIP(ipAddress, type);

            if (location != null && !Objects.equals(location.getString("geo.location.country"), "unknown"))
            {
                geoLocationEvent.mergeIn(location);
            }
            else
            {
                LOGGER.debug("Not able to resolve IP " + ipAddress + "for type " + type);

                FlowGeolocationMapperConfigStore.getStore().setGeoLocation(ipAddress, geoLocationEvent, type); // flowType.domain
            }

            var domain = DNSCacheStore.getStore().get(ipAddress);

            if (domain != null)
            {
                // we have domain name from DNS Cache Store
                geoLocationEvent.put(type + ".domain", domain);
            }
            else
            {
                DNSCacheStore.getStore().add(ipAddress);
            }

            FlowDomainMapperConfigStore.getStore().setDomain(ipAddress, geoLocationEvent, type);

            geoLocationEvent.put(type + ".continent", GeoDBUtil.getCountryContinent(geoLocationEvent.getString(type + ".country")));

            if (CommonUtil.debugEnabled())
            {
                LOGGER.debug("Geo location for " + ipAddress + " is " + geoLocationEvent.encodePrettily());
            }

            message.mergeIn(geoLocationEvent);
        }
        catch (Exception exception)
        {
            LOGGER.warn("Failed to decode IP " + ipAddress + "for type " + type);

            LOGGER.error(exception);
        }
    }

    /**
     * Parses custom tags from a comma-separated string into a JsonObject.
     * <p>
     * Expects tags in format "key1:value1,key2:value2". Filters out reserved
     * tags like "service" and "env".
     *
     * @param tags Comma-separated tag string
     * @param attribute JsonObject to populate with parsed tags
     */
    private void parseTags(String tags, JsonObject attribute, EventType type)
    {
        JsonObject rumTags = null;

        try
        {
            if (tags != null && !tags.isEmpty())
            {
                rumTags = new JsonObject();

                for (var tag : tags.split(COMMA_SEPARATOR))
                {
                    var tokens = tag.split(COLON_SEPARATOR);

                    if (tokens.length == 2 && !(tokens[0].equalsIgnoreCase("service") || tokens[0].equalsIgnoreCase("env"))) rumTags.put(buildCounter(type, tokens[0]), tokens[1]);
                }
            }
        }
        catch (Exception exception)
        {
            LOGGER.warn("Failed to parse RUM tags : " + tags);

            LOGGER.error(exception);
        }

        if (rumTags != null)
        {
            rumTags.remove("service");

            rumTags.remove("env");

            attribute.mergeIn(rumTags);
        }
    }

    private String buildCounter(EventType type, String key)
    {
        return switch (type)
        {
            case VIEW -> "rum.view." + key;
            case ERROR -> "rum.view.error." + key;
            case RESOURCE -> "rum.view.resource." + key;
            case ACTION -> "rum.view.action." + key;
            case LONG_TASK -> "rum.view.long.task." + key;
            default -> "";
        };
    }

    /**
     * Updates Apdex (Application Performance Index) statistics for the current view event.
     * <p>
     * Calculates user interaction type based on loading time and aggregates statistics
     * by session, geography, and service. Only processes inactive views.
     */
    private void updateApdexStats()
    {
        try
        {
            if (event.getString(RUM_VIEW_IS_ACTIVE).equalsIgnoreCase(NO))
            {
                // "session-id``||``geo.country``||``geo.continent``||``service-name"||``event-source
                var key = event.getString(RUM_VIEW_SESSION_ID) + SEPARATOR +
                        geoLocationEvent.getString(RUMConstant.GEO_LOCATION_COUNTRY) + SEPARATOR +
                        geoLocationEvent.getString(RUMConstant.GEO_LOCATION_CONTINENT) + SEPARATOR +
                        event.getString(RUM_VIEW_SERVICE_NAME) + SEPARATOR +
                        event.getString(EVENT_SOURCE);

                var userInteraction = RUMConstant.evaluateUserInteractionType(event.getLong(RUM_VIEW_LOADING_TIME_US, 0L) / 1000_000_000.0).getType();

                var stats = apdexStats.computeIfAbsent(key, value -> new HashMap<>());

                stats.put(userInteraction, stats.getOrDefault(userInteraction, 0) + 1);

                LOGGER.debug("apdex stats updated ...");
            }
            else
            {
                LOGGER.debug("Skipping apdex stats update - loading_time is null for session: " +
                        event.getString(RUM_VIEW_SESSION_ID) + ", service: " + event.getString(RUM_VIEW_SERVICE_NAME));
            }
        }
        catch (Exception exception)
        {
            LOGGER.warn("Failed to update apdex stats for session: " + event.getString(RUM_VIEW_SESSION_ID, "null") + ", service: " + (event.getString(RUM_VIEW_SERVICE_NAME) != null ? event.getString(RUM_VIEW_SERVICE_NAME) : "null"));

            LOGGER.error(exception);
        }
    }

    /**
     * Updates aggregated service-level statistics for the current view event.
     * <p>
     * Accumulates metrics including loading time, contentful paint metrics, errors,
     * layout shift, and interaction timing by service, application, and service type.
     */
    private void updateServiceStats()
    {
        try
        {
            // "service-name``||``application-id``||``service-type"
            var key = String.format(RUMConstant.RUM_SERVICE_KEY,
                    event.getString(RUM_VIEW_SERVICE_NAME),
                    event.getString(RUM_VIEW_APPLICATION_ID),
                    RUMServiceProfileConfigStore.getStore().getItem(Long.parseLong(event.getString(RUM_VIEW_APPLICATION_ID))).getString(RUMServiceProfile.RUM_PROFILE_TYPE));

            var serviceStat = serviceStats.computeIfAbsent(key, value -> new JsonObject());

            serviceStat.put(RUMConstant.LOADING_TIME_US, serviceStat.getLong(RUMConstant.LOADING_TIME_US, 0L) + event.getLong(RUMConstant.RUM_VIEW_LOADING_TIME_US))
                    .put(RUMConstant.LARGEST_CONTENTFUL_PAINT_US, serviceStat.getLong(RUMConstant.LARGEST_CONTENTFUL_PAINT_US, 0L) + event.getLong(RUMConstant.RUM_VIEW_LARGEST_CONTENTFUL_PAINT_US))
                    .put(RUMConstant.ERRORS, serviceStat.getInteger(RUMConstant.ERRORS, 0) + event.getInteger(RUMConstant.RUM_VIEW_ERRORS))
                    .put(RUMConstant.FIRST_CONTENTFUL_PAINT_US, serviceStat.getLong(RUMConstant.FIRST_CONTENTFUL_PAINT_US, 0L) + event.getLong(RUMConstant.RUM_VIEW_FIRST_CONTENTFUL_PAINT_US))
                    .put(RUMConstant.CUMULATIVE_LAYOUT_SHIFT, serviceStat.getFloat(RUMConstant.CUMULATIVE_LAYOUT_SHIFT, 0f) + event.getFloat(RUMConstant.RUM_VIEW_CUMULATIVE_LAYOUT_SHIFT))
                    .put(RUMConstant.INTERACTION_TO_NEXT_PAINT_US, serviceStat.getLong(RUMConstant.INTERACTION_TO_NEXT_PAINT_US, 0L) + event.getLong(RUMConstant.RUM_VIEW_INTERACTION_TO_NEXT_PAINT_US))
                    .put(RUMConstant.EVENTS, serviceStat.getLong(EVENTS, 0L) + 1);

            LOGGER.debug("service stats updated ...");
        }
        catch (Exception exception)
        {
            LOGGER.warn("Failed to update service stats for event : " + event.encodePrettily());

            LOGGER.error(exception);
        }
    }

    /**
     * Validates that the current event has a valid application ID and associated profile.
     *
     * @return true if event is valid, false otherwise
     */
    private boolean valid()
    {
        try
        {
            var applicationId = event.getString(RUM_VIEW_APPLICATION_ID);

            if (applicationId == null)
            {
                LOGGER.warn("Application ID is null from Source : " + event.getString(EVENT_SOURCE) + " for event : " + event.encodePrettily());

                return false;
            }

            var item = RUMServiceProfileConfigStore.getStore().getItem(Long.parseLong(applicationId));

            if (item == null)
            {
                LOGGER.warn("Profile item not found for application ID from Source : " + event.getString(EVENT_SOURCE) + " applicationId: " + applicationId + " for event : " + event.encodePrettily());

                return false;
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);

            return false;
        }

        return true;
    }

    /**
     * Populates attribute JsonObject with configured RUM attributes for the given event type.
     * <p>
     * Extracts attribute values from the event based on the configured attribute list
     * for the event type, converting underscores to dots in attribute names.
     *
     * @param event Source event JsonObject
     * @param attribute Target attribute JsonObject to populate
     * @param type RUM event type to determine which attributes to extract
     */
    private void populateAttribute(JsonObject event, JsonObject attribute, RUMConstant.EventType type)
    {
        var attributes = RUMCacheStore.getStore().getRUMAttributes(type);

        for (var index = 0; index < attributes.size(); index++)
        {
            var column = attributes.getString(index);

            if (event.getValue(column) != null && !event.getValue(column).toString().isEmpty())
            {
                attribute.put(column.replace("_", DOT_SEPARATOR), event.getValue(column));
            }
            else
            {
                attribute.put(column.replace("_", DOT_SEPARATOR), EMPTY_VALUE);
            }
        }
    }

    /**
     * Method used to trim the String with provided limit
     * @param value Value to be trimmed
     * @param limit limit
     * @return trimmed value
     */
    private String trim(String value, int limit)
    {
        if (CommonUtil.isNotNullOrEmpty(value) && value.length() > limit)
        {
            value = value.substring(0, limit);
        }

        return value;
    }

    /**
     * Stops the RUM event processor verticle.
     * <p>
     * Gracefully shuts down the event engine and releases resources.
     *
     * @param promise Promise to complete when shutdown is successful
     * @throws Exception if shutdown fails
     */
    @Override
    public void stop(Promise<Void> promise) throws Exception
    {
        eventEngine.stop(vertx, promise);

        LOGGER.info(String.format("RUM Event Processor undeployed : %s ...", Thread.currentThread().getName()));
    }
}

