                "prompt_tokens": failure.get("prompt_tokens"),
                "output_tokens": failure.get("output_tokens"),
                "inference_time": failure.get("inference_time"),
            },
        }
        pairs.append(pair)

    print(f"  ✓ Extracted {len(pairs)} evaluation-derived pairs")
