- Business logic (Service, Manager, Engine classes)
- Configuration (Config, Router patterns)
- Authentication & Security (Auth, Security classes)
- Data models (DTO, Request, Response, Converter)
- Validation & Error handling (Validator, Exception)
- EventBus & messaging patterns
- Schema definitions

Target: 100-150M tokens (~100M optimal for balanced coverage)
Format: JSONL with {"input": "raw_code_text"}
"""

import json
import os
import re
import sys
from pathlib import Path
from typing import List, Dict, Set, Tuple
from dataclasses import dataclass, field
import hashlib

@dataclass
