class CodeHygiene:
    """Utility for cleaning and sanitizing code"""

    SECRET_PATTERNS = [
        r'password\s*=\s*["\']',
        r'token\s*=\s*["\']',
        r'api[_-]?key\s*=\s*["\']',
        r'secret\s*=\s*["\']',
        r'private[_-]?key\s*=\s*["\']',
        r'auth[_-]?token\s*=\s*["\']',
    ]

    COPYRIGHT_PATTERNS = [
        r'/\*\*?\s*\n\s*\*\s*Copyright.*?\*/',
        r'//\s*Copyright.*?\n',
        r'/\*\s*Licensed under.*?\*/',
    ]

    @staticmethod
    def has_secrets(text: str) -> bool:
        """Check if text contains potential secrets"""
        for pattern in CodeHygiene.SECRET_PATTERNS:
            if re.search(pattern, text, re.IGNORECASE):
                return True
        return False

    @staticmethod
    def strip_headers(text: str) -> str:
        """Remove copyright and license headers"""
        for pattern in CodeHygiene.COPYRIGHT_PATTERNS:
            text = re.sub(pattern, '', text, flags=re.DOTALL | re.IGNORECASE)
        return text.strip()

    @staticmethod
    def strip_comments_excessive(text: str) -> str:
        """Remove excessive commented-out code but keep documentation"""
        lines = text.split('\n')
        cleaned = []
        in_comment_block = False
        comment_block_lines = []

        for line in lines:
            stripped = line.strip()

            if '/*' in stripped and not stripped.startswith('/**'):
                in_comment_block = True

            if in_comment_block:
                comment_block_lines.append(line)
                if '*/' in stripped:
                    in_comment_block = False
                    if any('/**' in l for l in comment_block_lines):
                        cleaned.extend(comment_block_lines)
                    comment_block_lines = []
                continue

            if stripped.startswith('//') and not stripped.startswith('///'):
                if any(pattern in stripped for pattern in ['public ', 'private ', 'protected ', 'return ', 'if (', 'for (']):
                    continue

            cleaned.append(line)

        return '\n'.join(cleaned)

    @staticmethod
    def clean_code(text: str) -> Tuple[str, bool]:
        """Clean code for CPT dataset"""
        if CodeHygiene.has_secrets(text):
            return "", False

        text = CodeHygiene.strip_headers(text)
        text = CodeHygiene.strip_comments_excessive(text)
        text = re.sub(r'\n{3,}', '\n\n', text)

        return text.strip(), True


class JavaChunker:
    """Intelligent Java code chunker"""

    @staticmethod
    def estimate_tokens(text: str) -> int:
        """Rough token estimation: ~4 chars per token for code"""
        return len(text) // 4

    @staticmethod
    def find_class_boundaries(content: str) -> List[Tuple[int, int, str]]:
        """Find class/interface boundaries in Java file"""
        boundaries = []

        class_pattern = r'(public|private|protected)?\s*(abstract|final)?\s*(class|interface|enum)\s+(\w+)'

        for match in re.finditer(class_pattern, content):
            class_name = match.group(4)
            start_pos = match.start()

            brace_count = 0
            in_class = False
            end_pos = start_pos

            for i in range(start_pos, len(content)):
                if content[i] == '{':
                    brace_count += 1
                    in_class = True
                elif content[i] == '}':
                    brace_count -= 1
                    if in_class and brace_count == 0:
                        end_pos = i + 1
                        break

            if end_pos > start_pos:
                boundaries.append((start_pos, end_pos, class_name))

        return boundaries

    @staticmethod
    def chunk_by_class(content: str, max_size: int = 2048, min_size: int = 256) -> List[str]:
        """Chunk Java file by class/interface boundaries"""
        chunks = []
        boundaries = JavaChunker.find_class_boundaries(content)

        if not boundaries:
            return JavaChunker.chunk_by_size(content, max_size, min_size)

        for start, end, class_name in boundaries:
            chunk = content[start:end]
            tokens = JavaChunker.estimate_tokens(chunk)

            if tokens > max_size:
                method_chunks = JavaChunker.chunk_by_methods(chunk, max_size)
                chunks.extend(method_chunks)
            elif tokens >= min_size:
                chunks.append(chunk)

        return chunks

    @staticmethod
    def chunk_by_methods(content: str, max_size: int) -> List[str]:
        """Split large class by methods"""
        chunks = []

        method_pattern = r'(public|private|protected)\s+.*?\s+\w+\s*\([^)]*\)\s*\{'
        methods = list(re.finditer(method_pattern, content))

        if not methods:
            return JavaChunker.chunk_by_size(content, max_size, 256)

        class_header = content[:methods[0].start()] if methods else ""
        current_chunk = class_header

        for i, method_match in enumerate(methods):
            method_start = method_match.start()
            method_end = methods[i + 1].start() if i + 1 < len(methods) else len(content)
            method_text = content[method_start:method_end]

            if JavaChunker.estimate_tokens(current_chunk + method_text) > max_size:
                if current_chunk.strip():
                    chunks.append(current_chunk.strip())
                current_chunk = class_header + method_text
            else:
                current_chunk += method_text

        if current_chunk.strip():
            chunks.append(current_chunk.strip())

        return chunks

    @staticmethod
    def chunk_by_size(content: str, max_size: int, min_size: int) -> List[str]:
        """Fallback: chunk by size with line boundaries"""
        chunks = []
        lines = content.split('\n')
        current_chunk = []
        current_tokens = 0

        for line in lines:
            line_tokens = JavaChunker.estimate_tokens(line)

            if current_tokens + line_tokens > max_size and current_chunk:
                chunk_text = '\n'.join(current_chunk)
                if JavaChunker.estimate_tokens(chunk_text) >= min_size:
                    chunks.append(chunk_text)
                current_chunk = [line]
                current_tokens = line_tokens
            else:
                current_chunk.append(line)
                current_tokens += line_tokens

        if current_chunk:
            chunk_text = '\n'.join(current_chunk)
            if JavaChunker.estimate_tokens(chunk_text) >= min_size:
                chunks.append(chunk_text)

        return chunks


class CPTDatasetGeneratorV2:
    """CPT dataset generator v2 with comprehensive coverage"""

    def __init__(self, config: CPTConfig):
        self.config = config
        self.processed_hashes: Set[str] = set()
        self.total_tokens = 0
        self.stats = {
            'files_processed': 0,
            'files_skipped': 0,
            'chunks_generated': 0,
            'critical_chunks': 0,
            'high_priority_chunks': 0,
            'low_priority_chunks': 0,
            'secrets_found': 0,
        }
        self.category_counts = {}

    def hash_content(self, content: str) -> str:
        """Generate hash for deduplication"""
        return hashlib.md5(content.encode()).hexdigest()

    def is_duplicate(self, content: str) -> bool:
        """Check if content is duplicate"""
        content_hash = self.hash_content(content)
        if content_hash in self.processed_hashes:
            return True
        self.processed_hashes.add(content_hash)
        return False

    def categorize_file(self, filename: str) -> str:
        """Categorize file by name pattern"""
        if "Store" in filename:
            return "Store"
        elif "Config" in filename:
            return "Config"
        elif "Service" in filename:
            return "Service"
        elif "Manager" in filename:
            return "Manager"
        elif "Engine" in filename:
            return "Engine"
        elif "Repository" in filename:
            return "Repository"
        elif "Auth" in filename or "Security" in filename:
            return "Auth/Security"
        elif "Validator" in filename:
            return "Validator"
        elif "Exception" in filename:
            return "Exception"
        elif "Handler" in filename:
            return "Handler"
        elif "Verticle" in filename:
            return "Verticle"
        elif "Router" in filename or "APIRouter" in filename:
            return "Router"
        elif filename.startswith("Abstract"):
            return "Abstract"
        elif "EventBus" in filename:
            return "EventBus"
        elif "DTO" in filename or "Request" in filename or "Response" in filename:
            return "DTO/Model"
        elif "Converter" in filename or "Factory" in filename or "Provider" in filename:
            return "Utility"
        else:
            return "Other"

    def get_priority(self, filename: str, content: str) -> str:
        """Determine priority level based on content and filename"""
        content_lower = content.lower()
        filename_lower = filename.lower()

        # CRITICAL: Core infrastructure
        for pattern in self.config.critical_patterns:
            if pattern.lower() in filename_lower or pattern.lower() in content_lower:
                return "CRITICAL"

        # HIGH: Important but less core
        for pattern in self.config.high_priority_patterns:
            if pattern.lower() in filename_lower or pattern.lower() in content_lower:
                return "HIGH"

        # LOW: Supporting code
        for pattern in self.config.low_priority_patterns:
            if pattern.lower() in filename_lower or pattern.lower() in content_lower:
                return "LOW"

        return "MEDIUM"

    def extract_java_files_from_repo(self) -> List[Path]:
        """Extract Java files from Motadata repo"""
        java_files = []
        repo_path = Path(self.config.internal_repo_path)

        if not repo_path.exists():
            print(f"⚠️  Internal repo not found at {repo_path}")
            return []

        print(f"📂 Scanning {repo_path}...")

        for root, dirs, files in os.walk(repo_path):
            dirs[:] = [d for d in dirs if 'test' not in d.lower() and d not in ['.git', 'target', 'build', 'node_modules']]

            for file in files:
                if file.endswith('.java') and 'src/main' in root:
                    java_files.append(Path(root) / file)

        print(f"✅ Found {len(java_files)} Java files in internal repo")
        return java_files

    def extract_schema_files(self) -> List[Path]:
        """Extract schema JSON files"""
        schema_files = []
        repo_path = Path(self.config.internal_repo_path)

        if not repo_path.exists():
            return []

        for root, dirs, files in os.walk(repo_path):
            if 'schema' in root.lower():
                for file in files:
                    if file.endswith('.json'):
                        schema_files.append(Path(root) / file)

        print(f"✅ Found {len(schema_files)} schema files")
        return schema_files

    def extract_code_from_datasets(self) -> List[str]:
        """Extract raw code snippets from existing datasets"""
        code_snippets = []
        datasets_path = Path(self.config.existing_datasets_path)

        for jsonl_file in datasets_path.glob("v17*.jsonl"):
            try:
                with open(jsonl_file, 'r') as f:
                    for line in f:
                        try:
                            data = json.loads(line)

                            if 'chosen' in data:
                                chosen = data.get('chosen', '')
                                if isinstance(chosen, str):
                                    code_snippets.extend(self.extract_code_blocks(chosen))
                                elif isinstance(chosen, list):
                                    for msg in chosen:
                                        if isinstance(msg, dict) and msg.get('role') == 'assistant':
                                            content = msg.get('content', '')
                                            if content:
                                                code_snippets.extend(self.extract_code_blocks(content))

                            elif 'messages' in data:
                                for msg in data.get('messages', []):
                                    if isinstance(msg, dict) and msg.get('role') == 'assistant':
                                        content = msg.get('content', '')
                                        if content:
                                            code_snippets.extend(self.extract_code_blocks(content))

                            elif 'code' in data:
                                code = data.get('code', '')
                                if code and len(code.strip()) > 100:
                                    code_snippets.append(code.strip())
                        except json.JSONDecodeError:
                            continue
            except Exception as e:
                print(f"⚠️  Error reading {jsonl_file.name}: {e}")

        print(f"✅ Extracted {len(code_snippets)} code snippets from datasets")
        return code_snippets

    def extract_code_blocks(self, text: str) -> List[str]:
        """Extract code blocks from markdown-formatted text"""
        code_blocks = re.findall(r'```(?:java)?\n(.*?)```', text, re.DOTALL)
        text_no_thinking = re.sub(r'<thinking>.*?</thinking>', '', text, flags=re.DOTALL)

        if 'class ' in text_no_thinking or 'public ' in text_no_thinking:
            code_blocks.append(text_no_thinking.strip())

        return [block.strip() for block in code_blocks if len(block.strip()) > 100]

    def process_file(self, file_path: Path) -> List[Dict]:
        """Process a single file into CPT chunks"""
        try:
            with open(file_path, 'r', encoding='utf-8', errors='ignore') as f:
                content = f.read()

            cleaned_content, is_safe = CodeHygiene.clean_code(content)

            if not is_safe:
                self.stats['secrets_found'] += 1
                self.stats['files_skipped'] += 1
                print(f"⚠️  Skipped (secrets detected): {file_path.name}")
                return []

            if not cleaned_content or len(cleaned_content) < 100:
                self.stats['files_skipped'] += 1
                return []

            chunks = JavaChunker.chunk_by_class(
                cleaned_content,
                max_size=self.config.max_chunk_size,
                min_size=self.config.min_chunk_size
            )

            cpt_entries = []
            for chunk in chunks:
                if self.is_duplicate(chunk):
                    continue

                priority = self.get_priority(file_path.name, chunk)
                tokens = JavaChunker.estimate_tokens(chunk)
                category = self.categorize_file(file_path.name)

                entry = {
                    'input': chunk,
                    'metadata': {
                        'source': str(file_path),
                        'priority': priority,
                        'category': category,
                        'tokens': tokens
                    }
                }

                cpt_entries.append(entry)
                self.total_tokens += tokens

                # Update category counts
                self.category_counts[category] = self.category_counts.get(category, 0) + 1

                if priority == "CRITICAL":
                    self.stats['critical_chunks'] += 1
                elif priority == "HIGH":
                    self.stats['high_priority_chunks'] += 1
                elif priority == "LOW":
                    self.stats['low_priority_chunks'] += 1

            self.stats['files_processed'] += 1
            self.stats['chunks_generated'] += len(cpt_entries)

            return cpt_entries

        except Exception as e:
            print(f"⚠️  Error processing {file_path}: {e}")
            self.stats['files_skipped'] += 1
            return []

    def process_code_snippet(self, snippet: str, source: str = "dataset") -> List[Dict]:
        """Process raw code snippet"""
        cleaned_content, is_safe = CodeHygiene.clean_code(snippet)

        if not is_safe or not cleaned_content:
            return []

        if self.is_duplicate(cleaned_content):
            return []

        tokens = JavaChunker.estimate_tokens(cleaned_content)

        if tokens < self.config.min_chunk_size:
            return []

        priority = self.get_priority("snippet", cleaned_content)
        category = "Dataset"

        entry = {
            'input': cleaned_content,
            'metadata': {
                'source': source,
                'priority': priority,
                'category': category,
                'tokens': tokens
            }
        }

        self.total_tokens += tokens
        self.stats['chunks_generated'] += 1
        self.category_counts[category] = self.category_counts.get(category, 0) + 1

        if priority == "CRITICAL":
            self.stats['critical_chunks'] += 1
        elif priority == "HIGH":
            self.stats['high_priority_chunks'] += 1
        elif priority == "LOW":
            self.stats['low_priority_chunks'] += 1

        return [entry]

    def generate(self) -> str:
        """Generate complete CPT v2 dataset"""
        print("=" * 70)
        print("🚀 CPT Dataset Generation v2 - COMPREHENSIVE EXPANSION")
        print("=" * 70)

        all_entries = []

        # 1. Extract from internal repo
        print("\n📦 Phase 1: Internal Repository (All Java files)")
        java_files = self.extract_java_files_from_repo()

        for i, file_path in enumerate(java_files, 1):
            entries = self.process_file(file_path)
            all_entries.extend(entries)

            if i % 50 == 0:
                print(f"   Progress: {i}/{len(java_files)} files, {self.total_tokens:,} tokens accumulated")

            if self.total_tokens >= self.config.target_tokens:
                print(f"✅ Reached target token count: {self.total_tokens:,}")
                break

        # 2. Extract schema files
        if self.total_tokens < self.config.target_tokens:
            print("\n📦 Phase 2: Schema Files")
            schema_files = self.extract_schema_files()

            for file_path in schema_files:
                try:
                    with open(file_path, 'r') as f:
                        schema_content = f.read()

                    schema_entry = f"Schema Definition: {file_path.name}\n\n{schema_content}"
                    entries = self.process_code_snippet(schema_entry, source=str(file_path))
                    all_entries.extend(entries)
                except:
                    continue

        # 3. Extract from existing datasets
        if self.total_tokens < self.config.target_tokens:
            print("\n📦 Phase 3: Existing Dataset Code Snippets")
            code_snippets = self.extract_code_from_datasets()

            for snippet in code_snippets:
                entries = self.process_code_snippet(snippet, source="existing_datasets")
                all_entries.extend(entries)

                if self.total_tokens >= self.config.max_tokens:
                    break

        # Sort by priority: CRITICAL > HIGH > MEDIUM > LOW
        priority_order = {"CRITICAL": 0, "HIGH": 1, "MEDIUM": 2, "LOW": 3}
        all_entries.sort(key=lambda x: priority_order.get(x['metadata']['priority'], 4))

        # Write output
        output_file = Path(self.config.output_dir) / "cpt_dataset_v2.jsonl"
        output_file.parent.mkdir(parents=True, exist_ok=True)

        print(f"\n💾 Writing to {output_file}...")

        with open(output_file, 'w') as f:
            for entry in all_entries:
                f.write(json.dumps({"text": entry['input']}) + '\n')

        # Write metadata separately
        metadata_file = Path(self.config.output_dir) / "cpt_metadata_v2.json"
        metadata = {
            'total_entries': len(all_entries),
            'total_tokens': self.total_tokens,
            'stats': self.stats,
            'category_distribution': self.category_counts,
            'config': {
                'max_chunk_size': self.config.max_chunk_size,
                'min_chunk_size': self.config.min_chunk_size,
                'target_tokens': self.config.target_tokens,
            }
        }

        with open(metadata_file, 'w') as f:
            json.dump(metadata, f, indent=2)

        # Print summary
        print("\n" + "=" * 70)
        print("✅ CPT Dataset Generation v2 Complete!")
        print("=" * 70)
        print(f"📊 Statistics:")
        print(f"   • Total entries: {len(all_entries):,}")
        print(f"   • Total tokens: {self.total_tokens:,}")
        print(f"   • Files processed: {self.stats['files_processed']:,}")
        print(f"   • Files skipped: {self.stats['files_skipped']:,}")
        print(f"   • Chunks generated: {self.stats['chunks_generated']:,}")
        print(f"   • Critical chunks: {self.stats['critical_chunks']:,}")
        print(f"   • High priority chunks: {self.stats['high_priority_chunks']:,}")
        print(f"   • Low priority chunks: {self.stats['low_priority_chunks']:,}")
        print(f"   • Secrets found & removed: {self.stats['secrets_found']:,}")

        print(f"\n📂 Category Distribution:")
        for category, count in sorted(self.category_counts.items(), key=lambda x: x[1], reverse=True):
            pct = (count / len(all_entries) * 100) if all_entries else 0
            print(f"   • {category:20s}: {count:4d} chunks ({pct:5.1f}%)")

        print(f"\n📁 Output:")
        print(f"   • Dataset: {output_file}")
        print(f"   • Metadata: {metadata_file}")
        print("=" * 70)

        return str(output_file)


def main():
    """Main entry point"""
    config = CPTConfig()
    generator = CPTDatasetGeneratorV2(config)

    try:
        output_file = generator.generate()
        print(f"\n✅ Success! CPT v2 dataset ready at: {output_file}")
        print(f"\n📝 Next steps:")
        print(f"   1. Review dataset: head -n 5 {output_file}")
        print(f"   2. Compare v1 vs v2: python datasets/cpt/review_dataset.py")
        print(f"   3. Train CPT: python training/train_cpt.py")
        return 0
    except Exception as e:
        print(f"\n❌ Error: {e}")
        import traceback
        traceback.print_exc()
        return 1


if __name__ == "__main__":
    sys.exit(main())

